            catch { nocheOn = bkNoche; normTarget = bkTarget; normStrength = bkStrength; normalizeOn = bkOn; excAmount = bkExc; masterDb = bkUp; eqAmount = bkEq; bassAmount = bkBass; videoVol = bkVid; videoAuto = bkVidA; sbrOn = bkSbr; iaVivo = bkIa; eqAuto = bkEqA; bassAuto = bkBassA; iaMezcla = bkIaMez; iaGpu = bkIaGpu; perfilDisco = bkDsk; iaHarvestOn = bkIaDat; AplicaPerfilDisco(); }   // si algo truena, deja los valores como estaban
            finally { try { Cursor.Hide(); } catch { } maintMode = wasMaint; ForceFocus(); }
        }

        // Busca automaticamente una carpeta llamada "musica" junto a los datos o hasta 3 niveles arriba
        // (ej.: nueva\Release\Rocola.exe  +  nueva\musica). No requiere elegir carpeta.
        private string MusicFolder
        {
            get
            {
                try
                {
                    string dir = CarpetaDatos;
                    for (int i = 0; i < 4 && dir != null; i++)
                    {
                        string cand = Path.Combine(dir, "musica");
                        if (Directory.Exists(cand)) return cand;
                        DirectoryInfo p = Directory.GetParent(dir);
                        dir = (p != null) ? p.FullName : null;
                    }
                }
                catch { }
                return RutaDatos("musica");   // por defecto, junto a los datos
            }
        }

        protected override void OnResize(EventArgs e) { base.OnResize(e); LayoutControls(); Invalidate(); VuelveAPrecalentar(); }

        protected override void OnPaintBackground(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            int w = ClientSize.Width, h = ClientSize.Height;
            if (w < 2 || h < 2) { base.OnPaintBackground(e); return; }
#if ROCOLA_GPU
            if (gpuPanel != null && gpuPanel.Visible) return;   // el panel GPU (pantalla completa) ya cubre todo; no gastes CPU pintando el cielo detras
#endif
            formStars.SkyOffsetX = 0; formStars.SkyOffsetY = 0; formStars.SkyFullW = w; formStars.SkyFullH = h;
            formStars.SkyMid = EscalaBrillo(SkyColorMid(bgAccent), bgRespiro); formStars.Acento = bgAccent;
            formStars.Dim = bgDimResp;   // atenua TAMBIEN las franjas de arriba/abajo en sincronia con la rejilla (una sola pieza), respiracion incluida
            formStars.DrawCached(g, w, h, EscalaBrillo(SkyColor(bgAccent), bgRespiro), EscalaBrillo(SkyColor2(bgAccent), bgRespiro));   // cielo en degradado CONTINUO; etiquetas y mini-cubo transparentes encima
        }

        private static Color Shade(Color c, double towardBlack)
        {
            if (towardBlack < 0) towardBlack = 0; if (towardBlack > 1) towardBlack = 1;
            double k = 1.0 - towardBlack;
            return Color.FromArgb(c.A, (int)(c.R * k), (int)(c.G * k), (int)(c.B * k));
        }

        // Cielo del fondo: casi negro con un toque del color del genero (arranca oscuro como el modo
        // atraccion, pero cambia de tinte segun lo que suena).
        // EL COLOR DE LAS NEBULOSAS: el del genero llevado a medias con un violeta azulado. El del genero a
        // secas es demasiado terroso para una nebulosa; mezclado, se sigue notando de que color va la cancion
        // pero parece cielo. La misma cuenta que hace la version por CPU.
        private static Color ColorNebulosa(Color accent)
        {
            return Color.FromArgb(255, (accent.R + 140) / 2, (accent.G + 120) / 2, (accent.B + 255) / 2);
        }

        private static Color SkyColor(Color accent)
        {
            // ARRIBA del cielo: casi negro (apenas un dejo del genero). Se oscurece hacia el cenit.
            int r = 3 + accent.R / 22, g = 4 + accent.G / 22, b = 8 + accent.B / 18;
            if (r > 22) r = 22; if (g > 22) g = 22; if (b > 30) b = 30;
            return Color.FromArgb(255, r, g, b);
        }

        // Color INFERIOR del degradado del cielo: mas tenido al genero y un poco mas claro que el de arriba.
        private static Color SkyColor2(Color accent)
        {
            // ABAJO del cielo: resplandor de horizonte. Sin musica = azul default; con musica = el color del
            // genero normalizado a un brillo visible, con un leve piso azul para que siga sintiendose cielo.
            int mx = accent.R; if (accent.G > mx) mx = accent.G; if (accent.B > mx) mx = accent.B;
            int r, g, b;
            if (mx < 10) { r = 50; g = 88; b = 188; }
            else
            {
                r = accent.R * 165 / mx; g = accent.G * 165 / mx; b = accent.B * 165 / mx;
                r = (r * 3 + 50) / 4; g = (g * 3 + 88) / 4; b = (b * 3 + 188) / 4;
            }
            if (r > 205) r = 205; if (g > 205) g = 205; if (b > 220) b = 220;
            r = r * SkyDark / 100; g = g * SkyDark / 100; b = b * SkyDark / 100;   // ESTETICA: cielo un poco mas oscuro (el azul se veia muy brillante)
            return Color.FromArgb(255, r, g, b);
        }

        // Factor de OSCURIDAD del cielo (100 = como antes; menor = mas oscuro). Solo brillo, conserva el tinte.
        private const int SkyDark = 75;

        // EN MEDIO del cielo: el "azulado default". Casi independiente del genero (apenas un dejo) para que,
        // como pediste, despues del color del genero de abajo siga el azul antes de oscurecer al negro de arriba.
        private static Color SkyColorMid(Color accent)
        {
            int r = 22 + accent.R / 10, g = 50 + accent.G / 8, b = 120 + accent.B / 7;
            if (r > 60) r = 60; if (g > 105) g = 105; if (b > 205) b = 205;
            r = r * SkyDark / 100; g = g * SkyDark / 100; b = b * SkyDark / 100;   // ESTETICA: mitad del cielo mas oscura
            return Color.FromArgb(255, r, g, b);
        }

        // Sube o baja el brillo de un color sin tocar su tono. La usa la respiracion del cielo: es lo
        // unico que la pared hace por su cuenta, asi que va por un solo sitio.
        internal static Color EscalaBrillo(Color c, float f)
        {
            if (f < 0f) f = 0f;
            int r = (int)(c.R * f + 0.5f), g = (int)(c.G * f + 0.5f), b = (int)(c.B * f + 0.5f);
            if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
            return Color.FromArgb(c.A, r, g, b);
        }

        private static Color Lighten(Color c, double t)
        {
            if (t < 0) t = 0; if (t > 1) t = 1;
            return Color.FromArgb(c.A, (int)(c.R + (255 - c.R) * t), (int)(c.G + (255 - c.G) * t), (int)(c.B + (255 - c.B) * t));
        }

        private static Color LerpColor(Color a, Color b, double t)
        {
            if (t < 0) t = 0; if (t > 1) t = 1;
            return Color.FromArgb(Hacia(a.A, b.A, t), Hacia(a.R, b.R, t), Hacia(a.G, b.G, t), Hacia(a.B, b.B, t));
        }

        // UN PASO DE UN COLOR HACIA OTRO, QUE DE VERDAD LLEGA.
        //
        // Esto se usa para deslizar el color del fondo de una cancion a la siguiente: en cada cuadro se
        // acerca un 16% a su destino. Con la cuenta de antes -que tiraba los decimales- un canal que tenia
        // que SUBIR se quedaba clavado: subir el 16% de una diferencia de seis son 0.96, y al tirar los
        // decimales eso es cero. O sea que el color no llegaba NUNCA a su destino, se quedaba a seis.
        //
        // Y eso no era solo un color un pelin distinto. El programa se pregunta "sigue cambiando el color?"
        // comparando el actual con el destino, y la respuesta pasaba a ser QUE SI PARA SIEMPRE. Con esa
        // respuesta, la rocola repinta el fondo entero, la rejilla de discos y el interior del disco en CADA
        // cuadro en vez de en uno de cada tres. O sea que despues de la primera cancion se quedaba, de por
        // vida, haciendo el triple de trabajo del previsto, y cuanto mas grande la pantalla peor.
        //
        // Ahora el paso es de un punto como minimo y nunca se pasa de largo, asi que el deslizamiento acaba
        // -en unos veinticinco cuadros, un segundo- y el programa vuelve a su ritmo normal.
        private static int Hacia(int de, int a, double t)
        {
            int d = a - de;
            if (d == 0) return de;
            int abs = (d > 0) ? d : -d;
            int paso = (int)(abs * t + 0.5);
            if (paso < 1) paso = 1;
            if (paso > abs) paso = abs;
            return de + ((d > 0) ? paso : -paso);
        }

        private static GraphicsPath RoundedPath(Rectangle r, int radius)
        {
            GraphicsPath p = new GraphicsPath();
            int d = radius * 2;
            if (d > r.Height) d = r.Height;
            if (d > r.Width) d = r.Width;
            if (d < 2) d = 2;
            p.AddArc(r.X, r.Y, d, d, 180, 90);
            p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            p.CloseFigure();
            return p;
        }

        // ATAJO (rendimiento): casi todos los titulos son letras inglesas, numeros y signos corrientes.
        // Para esos, descomponer el texto en letra+tilde y preguntar por la categoria Unicode de cada
        // caracter es trabajo tirado: por debajo de 128 no hay NINGUN caracter que sea marca de acento, y
        // bajar a minusculas ahi es exactamente pasar la A-Z a la a-z. Asi que primero se mira si el texto
        // es de esos -una pasada, sin reservar memoria- y si lo es se baja a minusculas a mano; y si encima
        // ya venia en minusculas se devuelve el mismo texto, sin copiar nada.
        // El texto con acentos, enes o alfabetos raros sigue por el camino largo de siempre, igual que antes.
        // Armar el indice del buscador de una biblioteca de 120 mil canciones baja de 362 a 173 ms por esto.
        private static string Normalize(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            int n = s.Length, i = 0;
            bool hayMayus = false;
            for (; i < n; i++) { char c = s[i]; if (c >= (char)128) break; if (c >= 'A' && c <= 'Z') hayMayus = true; }
            if (i == n)
            {
                if (!hayMayus) return s;
                char[] b = new char[n];
                for (int k = 0; k < n; k++) { char c = s[k]; b[k] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c; }
                return new string(b);
            }
            string formd = s.ToLowerInvariant().Normalize(NormalizationForm.FormD);
            StringBuilder sb = new StringBuilder(formd.Length);
            for (int k = 0; k < formd.Length; k++)
                if (CharUnicodeInfo.GetUnicodeCategory(formd[k]) != UnicodeCategory.NonSpacingMark) sb.Append(formd[k]);
            return sb.ToString();
        }

        // DONDE CAE lo tecleado dentro de un texto, ignorando mayusculas y acentos, pero devolviendo la
        // posicion en el texto ORIGINAL. Normalizar el texto entero y buscar ahi NO vale: al quitar los acentos
        // las posiciones se corren y el resaltado caeria una letra mas alla de donde debe.
        private static bool BuscaTramo(string texto, string qNorm, out int ini, out int largo)
        {
            ini = 0; largo = 0;
            if (string.IsNullOrEmpty(texto) || string.IsNullOrEmpty(qNorm)) return false;
            string formd = texto.ToLowerInvariant().Normalize(NormalizationForm.FormD);
            StringBuilder sb = new StringBuilder(formd.Length);
            int[] mapa = new int[formd.Length];
            // El mapa dice, por cada letra ya limpia, de que letra del texto original salio. Se avanza sobre la
            // forma descompuesta y se cuenta cuantos caracteres ORIGINALES se llevan consumidos.
            // Al descomponer, cada letra del original se abre en UNA base y cero o mas tildes. Las tildes son
            // de la base anterior, asi que solo las bases gastan un caracter del original.
            int orig = -1, j = 0;
            for (int i = 0; i < formd.Length; i++)
            {
                if (CharUnicodeInfo.GetUnicodeCategory(formd[i]) == UnicodeCategory.NonSpacingMark) continue;
                orig++;
                mapa[j] = orig; sb.Append(formd[i]); j++;
            }
            string limpio = sb.ToString();
            int k = limpio.IndexOf(qNorm, StringComparison.Ordinal);
            if (k < 0 || k >= j) return false;
            ini = mapa[k];
            int fin = (k + qNorm.Length < j) ? mapa[k + qNorm.Length] : texto.Length;
            largo = fin - ini;
            if (largo <= 0 || ini + largo > texto.Length) return false;
            return true;
        }

        private static bool Has(string s, params string[] keys)
        {
            for (int i = 0; i < keys.Length; i++) if (s.Contains(keys[i])) return true;
            return false;
        }

        // EL COLOR DE LO QUE SUENA: excepciones por artista (BTS = morado) y, si no, el genero.
        //
        // Aqui estaba el fallo del fondo. Esto miraba SOLO la etiqueta de genero del archivo (su ID3), y
        // muchisimos MP3 no traen ninguna. Entonces devolvia el azul de "no se de que es esto" aunque la
        // rocola SI supiera el genero por otro lado: la pastilla decia "Tropical", sacado del disco, del
        // artista o del nombre de la carpeta, y el fondo se quedaba azul. Ahora se pregunta por la misma
        // cascada que responde en la lista, en el buscador y en la franja de abajo, asi que las cuatro dicen
        // lo mismo. Deja de ser estatico porque esa cascada necesita lo que la rocola ha ido aprendiendo.
        private Color ColorDeLoQueSuena(Track t, Album org)
        {
            if (t == null) return DefaultAccent;
            string a = (t.Artist != null) ? t.Artist.ToLowerInvariant() : "";
            // El morado de BTS es una PETICION del bar, no una deduccion: se queda como esta y no se le
            // gira el tono. Lo pidieron morado, sale morado, tenga la portada el color que tenga.
            if (a.Contains("bts") || a.Contains("bangtan")) return Color.FromArgb(149, 86, 220);
            string et = GeneroDeCancion(t, org);
            Color gen = (et.Length > 0) ? ColorDeEtiqueta(et) : DefaultAccent;
            // Y encima, EL TONO DE LA PORTADA. Dos cumbias seguidas pintaban exactamente la misma
            // pantalla naranja aunque una fuera un disco rojo y la otra uno verde.
            return TinteConPortada(gen, ColorDePortadaDe(org));
        }

        // ---------- EL COLOR QUE LE PONE LA PORTADA AL FONDO ----------
        //
        // LA PORTADA ELIGE EL TONO. LA ROCOLA MANDA EN TODO LO DEMAS.
        //
        // De la portada se toma SOLO de que color es -rojo, azul, verde-. Lo oscuro y lo vivo que sale a
        // la pantalla lo sigue decidiendo el genero, con el mismo brillo y la misma viveza que ya tenia.
        // Asi NINGUNA portada puede estropear la pantalla: ni una casi blanca lavandola, ni una negra
        // apagandola, ni una de neon quemandola. No hay topes de seguridad que ajustar ni recortes que
        // se puedan quedar cortos: sale de como esta hecho, porque el brillo y la viveza NO SE TOCAN.
        //
        // Y el resto de la pantalla no se entera de nada: el genero sigue mandando en la etiqueta de la
        // pastilla (que usa ColorDeEtiqueta directo), asi que la palabra "Tropical" conserva su color.
        internal static Color TinteConPortada(Color genero, Color portada)
        {
            if (portada.A == 0) return genero;                     // la portada no sabe de que color es
            int mx = Math.Max(genero.R, Math.Max(genero.G, genero.B));
            int mn = Math.Min(genero.R, Math.Min(genero.G, genero.B));
            if (mx - mn < 2) return genero;                        // un gris no tiene tono que girar
            return GiraTono(genero, TonoDe(portada) - TonoDe(genero), 1f);
        }

        // TONO de un color, en grados de la rueda (0 = rojo, 120 = verde, 240 = azul).
        private static float TonoDe(Color c)
        {
            float r = c.R / 255f, g = c.G / 255f, b = c.B / 255f;
            float mx = Math.Max(r, Math.Max(g, b)), mn = Math.Min(r, Math.Min(g, b));
            float d = mx - mn;
            if (d < 0.0001f) return 0f;
            float h;
            if (mx == r) h = 60f * (((g - b) / d) % 6f);
            else if (mx == g) h = 60f * ((b - r) / d + 2f);
            else h = 60f * ((r - g) / d + 4f);
            while (h < 0f) h += 360f; while (h >= 360f) h -= 360f;
            return h;
        }

        // Gira el TONO de un color (grados en la rueda de color) y le escala el brillo, dejando la VIVEZA
        // como estaba. Vive AQUI FUERA, y no dentro del trozo de tarjeta grafica donde estaba, porque
        // ahora tambien la usa el fondo que toma el tono de la portada, y eso pasa con tarjeta y sin ella.
        private static Color GiraTono(Color c, float grados, float brillo)
        {
            float r = c.R / 255f, g = c.G / 255f, b = c.B / 255f;
            float mx = Math.Max(r, Math.Max(g, b)), mn = Math.Min(r, Math.Min(g, b));
            float v = mx, d = mx - mn;
            float sat = (mx <= 0.0001f) ? 0f : d / mx;
            float hue = 0f;
            if (d > 0.0001f)
            {
                if (mx == r) hue = 60f * (((g - b) / d) % 6f);
                else if (mx == g) hue = 60f * ((b - r) / d + 2f);
                else hue = 60f * ((r - g) / d + 4f);
            }
            hue += grados; while (hue < 0f) hue += 360f; while (hue >= 360f) hue -= 360f;
            v *= brillo; if (v > 1f) v = 1f;
            float cc = v * sat, x = cc * (1f - Math.Abs((hue / 60f) % 2f - 1f)), m = v - cc;
            float rr, gg, bb;
            if (hue < 60f) { rr = cc; gg = x; bb = 0f; }
            else if (hue < 120f) { rr = x; gg = cc; bb = 0f; }
            else if (hue < 180f) { rr = 0f; gg = cc; bb = x; }
            else if (hue < 240f) { rr = 0f; gg = x; bb = cc; }
            else if (hue < 300f) { rr = x; gg = 0f; bb = cc; }
            else { rr = cc; gg = 0f; bb = x; }
            return Color.FromArgb((int)((rr + m) * 255f + 0.5f), (int)((gg + m) * 255f + 0.5f), (int)((bb + m) * 255f + 0.5f));
        }

        private const int MuestraLado = 32;          // como mucho, 32x32 puntos de la portada
        private const float TonoMinViveza = 0.22f;   // por debajo de esto es un gris, no un color
        private const float TonoMinBrillo = 0.14f;   // y por debajo de esto es negro
        private const float TonoMinAcuerdo = 0.35f;  // cuanto tienen que coincidir los colores para que uno mande

        // DE QUE COLOR ES UNA PORTADA. Devuelve un color del que solo importa el TONO; si la portada no
        // tiene ninguno -blanco y negro, o un revoltijo donde no manda nadie- devuelve A=0, "no se sabe",
        // y entonces manda el genero como hasta ahora.
        //
        // Se muestrea con paso fijo: como mucho 32x32 puntos, sea la portada de 300 pixeles de lado o de
        // 1400. Asi lo que cuesta NO depende del tamaño de la imagen, que es lo que haria que un disco con
        // una portada enorme trabara la rocola justo al empezar la cancion.
        //
        // Y se descarta lo que no es color: los puntos casi grises y los casi negros. Casi todas las
        // portadas traen marco oscuro y letras blancas, y contandolos el promedio se iria siempre al gris.
        //
        // El promedio de tonos se hace con seno y coseno, no sumando grados: el rojo esta en 0 y en 360 a
        // la vez, asi que sumando, dos rojos darian verde.
        private static Color ColorDePortada(Bitmap b)
        {
            if (b == null) return Color.FromArgb(0, 0, 0, 0);
            int w = b.Width, h = b.Height;
            if (w < 2 || h < 2) return Color.FromArgb(0, 0, 0, 0);
            int px = (w + MuestraLado - 1) / MuestraLado; if (px < 1) px = 1;
            int py = (h + MuestraLado - 1) / MuestraLado; if (py < 1) py = 1;
            double sx = 0, sy = 0, peso = 0;
            for (int y = py / 2; y < h; y += py)
                for (int x = px / 2; x < w; x += px)
                {
                    Color c;
                    try { c = b.GetPixel(x, y); } catch { return Color.FromArgb(0, 0, 0, 0); }
                    float r = c.R / 255f, g = c.G / 255f, bl = c.B / 255f;
                    float mx = Math.Max(r, Math.Max(g, bl)), mn = Math.Min(r, Math.Min(g, bl));
                    if (mx < TonoMinBrillo) continue;              // negro: no dice de que color es el disco
                    float d = mx - mn, sat = d / mx;
                    if (sat < TonoMinViveza) continue;             // gris: tampoco
                    float hue;
                    if (mx == r) hue = 60f * (((g - bl) / d) % 6f);
                    else if (mx == g) hue = 60f * ((bl - r) / d + 2f);
                    else hue = 60f * ((r - g) / d + 4f);
                    // Pesa lo VIVO y lo CLARO: un rojo encendido manda mas que un beige que apenas pasa el
                    // corte. Si no, el fondo de una portada casi apagada decidiria por encima de su dibujo.
                    double pes = sat * mx;
                    double rad = hue * Math.PI / 180.0;
                    sx += Math.Cos(rad) * pes; sy += Math.Sin(rad) * pes; peso += pes;
                }
            if (peso <= 0.0001) return Color.FromArgb(0, 0, 0, 0);
            // Y SI LOS COLORES NO SE PONEN DE ACUERDO tampoco se sabe. Una portada con de todo -media roja
            // y media verde- daria un promedio que apunta a cualquier lado y no se parece a ninguna de las
            // dos. Cuando eso pasa, mejor callarse y dejar mandar al genero.
            double acuerdo = Math.Sqrt(sx * sx + sy * sy) / peso;
            if (acuerdo < TonoMinAcuerdo) return Color.FromArgb(0, 0, 0, 0);
            double ang = Math.Atan2(sy, sx) * 180.0 / Math.PI; if (ang < 0) ang += 360.0;
            return GiraTono(Color.FromArgb(255, 0, 0), (float)ang, 1f);   // un color cualquiera con ESE tono
        }

        // El color de la portada de un disco, APUNTADO. Recorrer un mapa de bits cuesta, y esto se pregunta
        // cada vez que empieza una cancion; por disco solo hace falta hacerlo una vez.
        //
        // Si la portada aun no esta cargada NO se apunta nada: se vuelve a preguntar cuando llegue (lo hace
        // el aviso de portada cargada, que ya existia para el cubito de abajo).
        private readonly Dictionary<string, Color> colorPortada = new Dictionary<string, Color>(StringComparer.OrdinalIgnoreCase);
        private static bool fondoPortadaOn = true;   // "fondo_portada=" en config
        private static readonly Color SinColor = Color.FromArgb(0, 0, 0, 0);
        private Color ColorDePortadaDe(Album a)
        {
            if (!fondoPortadaOn || a == null) return SinColor;
            string k = a.CoverPath;
            if (string.IsNullOrEmpty(k)) return SinColor;
            Color c;
            if (colorPortada.TryGetValue(k, out c)) return c;
            Bitmap b = LoadCover(a) as Bitmap;
            if (b == null) return SinColor;
            c = ColorDePortada(b);
            colorPortada[k] = c;
            return c;
        }

        // Etiqueta canonica del genero para agrupar los discos TOP (mismas familias que GenreToColor).
        private static string GenreLabel(string genre)
        {
            if (string.IsNullOrEmpty(genre)) return "Otros";
            string g = genre.ToLowerInvariant();
            // KARAOKE manda sobre todo lo demas: una cumbia de karaoke es karaoke, no cumbia. Y NAVIDAD va
            // detras por lo mismo (una "cumbia navidena" se guarda por navidad, que es cuando se pone).
            if (Has(g, "karaoke")) return "Karaoke";
            if (Has(g, "navidad", "navide", "villancico", "christmas", "xmas")) return "Navidad";
            if (Has(g, "k-pop", "kpop", "j-pop", "jpop", "anime", "idol")) return "K-Pop";
            if (Has(g, "metal", "thrash", "death", "heavy", "hardcore", "grindcore")) return "Metal";
            if (Has(g, "punk")) return "Punk";
            if (Has(g, "gothic", "goth", "gotic", "g\u00f3tic", "darkwave")) return "Gotico";
            if (Has(g, "industrial")) return "Industrial";
            if (Has(g, "reggaeton", "reggaet", "reguet", "perreo", "dembow")) return "Reggaeton";
            if (Has(g, "hip", "rap", "trap")) return "Hip-Hop";
            if (Has(g, "salsa", "mereng", "bachata", "tropical", "vallenato", "guarach", "mambo", "chachacha",
                       "cha cha", "danzon", "danz\u00f3n", "guaguanco", "timba", "marimba", "son cubano")) return "Tropical";
            if (Has(g, "cumbia", "banda", "norte", "ranch", "mariach", "regional", "tejan", "grupe", "corrido",
                       "duranguense", "sonidero", "quebradita", "sierre", "huapango", "huasteco", "zapateado")) return "Regional";
            if (Has(g, "bolero", "tango", "ranchera", "balada", "romantic", "romant", "rom\u00e1nt", "vals", "serenata")) return "Bolero";
            if (Has(g, "flamenco", "rumba", "copla")) return "Flamenco";
            if (Has(g, "latin", "latino", "espan", "samba", "sertanejo", "pagode", "forro")) return "Latino";
            if (Has(g, "reggae", "ska", "dub")) return "Reggae";
            if (Has(g, "drum", "bass", "dnb", "d&b", "jungle", "breakbeat", "garage")) return "DnB";
            if (Has(g, "electro", "electr\u00f3n", "techno", "tecno", "house", "trance", "edm", "synth", "dance", "club", "dubstep", "rave", "hardstyle", "tribal")) return "Electronica";
            if (Has(g, "ambient", "chill", "lo-fi", "lofi", "downtempo", "new age", "meditat")) return "Chill";
            if (Has(g, "jazz", "swing", "bebop", "bossa")) return "Jazz";
            if (Has(g, "blues", "soul", "funk", "r&b", "rhythm", "motown")) return "Soul";
            if (Has(g, "gospel", "christian", "worship", "cristian", "alabanza")) return "Cristiana";
            if (Has(g, "classic", "clasic", "cl\u00e1sic", "orchestr", "orquest", "piano", "opera", "\u00f3pera", "symphon", "baroque", "instrumental")) return "Clasica";
            if (Has(g, "soundtrack", "score", "cinematic", "banda sonora")) return "Soundtrack";
            if (Has(g, "country", "bluegrass", "americana")) return "Country";
            if (Has(g, "folk", "acoustic", "celt")) return "Folk";
            if (Has(g, "disco")) return "Disco";
            if (Has(g, "oldies", "50s", "60s", "doo")) return "Oldies";
            if (Has(g, "world", "ethnic", "african", "arab", "india", "asian")) return "World";
            if (Has(g, "vocal", "capella", "capela")) return "Vocal";
            if (Has(g, "comedy", "spoken", "podcast", "hablado", "narracion", "narraci\u00f3n", "audiolibro")) return "Hablado";
            if (Has(g, "child", "kids", "infantil")) return "Infantil";
            if (Has(g, "pop")) return "Pop";
            if (Has(g, "rock", "grunge", "alternative", "indie")) return "Rock";
            return "Otros";
        }

        // EL COLOR DE CADA GENERO. Esta es LA tabla: no hay otra (GenreToColor pregunta aqui).
        //
        // Cada genero se queda en la familia de color que le toca -lo regional en naranjas, lo electronico en
        // turquesas, lo clasico en azules- pero repartidos DENTRO de la familia para que no se confundan entre
        // si. Antes habia parejas que eran el mismo color: Regional 225,120,30 y Latino 225,130,40 no se
        // distinguian de ninguna manera, ni Reggaeton de Hip-Hop. Medido con la distancia "redmean" (la que se
        // parece a lo que ve el ojo, no la de RGB a secas), la pareja mas parecida pasa de 25 a 53, y eso con
        // dos generos MAS en la tabla.
        private static Color ColorDeEtiqueta(string etiqueta)
        {
            switch (etiqueta)
            {
                case "Karaoke": return Color.FromArgb(70, 150, 245); // azul de escenario
                case "Navidad": return Color.FromArgb(125, 200, 70); // verde pino claro
                case "K-Pop": return Color.FromArgb(175, 100, 235); // lila claro
                case "Metal": return Color.FromArgb(215, 40, 45); // rojo sangre
                case "Punk": return Color.FromArgb(245, 85, 30); // naranja encendido
                case "Gotico": return Color.FromArgb(100, 55, 150); // violeta oscuro
                case "Industrial": return Color.FromArgb(145, 65, 80); // granate apagado
                case "Reggaeton": return Color.FromArgb(195, 60, 190); // magenta
                case "Hip-Hop": return Color.FromArgb(125, 70, 215); // violeta azulado
                case "Tropical": return Color.FromArgb(255, 130, 40); // naranja mango
                case "Regional": return Color.FromArgb(215, 120, 25); // naranja tierra
                case "Bolero": return Color.FromArgb(175, 80, 85); // vino rosado
                case "Flamenco": return Color.FromArgb(200, 130, 80); // arena tostada
                case "Latino": return Color.FromArgb(190, 85, 45); // terracota
                case "Reggae": return Color.FromArgb(40, 175, 85); // verde bandera
                case "DnB": return Color.FromArgb(15, 145, 150); // turquesa oscuro
                case "Electronica": return Color.FromArgb(35, 195, 210); // cian brillante
                case "Chill": return Color.FromArgb(95, 175, 165); // verde agua
                case "Jazz": return Color.FromArgb(225, 160, 40); // ambar
                case "Soul": return Color.FromArgb(185, 130, 45); // mostaza
                case "Cristiana": return Color.FromArgb(205, 195, 100); // oro palido
                case "Clasica": return Color.FromArgb(90, 100, 215); // azul indigo
                case "Soundtrack": return Color.FromArgb(110, 125, 200); // azul acero
                case "Country": return Color.FromArgb(140, 120, 85); // caqui
                case "Folk": return Color.FromArgb(120, 150, 90); // verde oliva
                case "Disco": return Color.FromArgb(225, 75, 175); // rosa neon
                case "Oldies": return Color.FromArgb(170, 115, 105); // rosa palo
                case "World": return Color.FromArgb(160, 95, 45); // marron
                case "Vocal": return Color.FromArgb(200, 175, 150); // crema
                case "Hablado": return Color.FromArgb(135, 140, 140); // gris
                case "Infantil": return Color.FromArgb(255, 190, 55); // amarillo vivo
                case "Pop": return Color.FromArgb(235, 55, 110); // rosa fuerte
                case "Rock": return Color.FromArgb(225, 95, 75); // coral
                default: return DefaultAccent;
            }
        }

        // EL COLOR DE UN GENERO CRUDO (el que trae el ID3). Antes esto era una segunda lista de palabras,
        // copia de la de GenreLabel, y las dos ya se habian desparejado: una cancion marcada "Balada" salia
        // con el color del Bolero en un sitio y con el azul de por defecto en otro. Ahora se traduce a
        // etiqueta y se le pide su color, asi que hay UN SOLO sitio donde vive el color de cada genero y no
        // se pueden volver a desparejar.
        private static Color GenreToColor(string genre) { return ColorDeEtiqueta(GenreLabel(genre)); }

        private Font Bold(float size) { return new Font(this.Font.FontFamily, size, FontStyle.Bold); }

        private void TransLabel(Label l, float size)
        {
            l.BackColor = Color.Transparent;
            l.ForeColor = Color.White;
            l.Font = Bold(size);
        }

        private void BuildUi()
        {
            this.Text = "Rocola";
            try { this.Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath); } catch { }   // estrella metalica (barra de tareas / Alt-Tab); el exe ya la lleva embebida
            this.StartPosition = FormStartPosition.CenterScreen;
            this.Size = new Size(1100, 780);
            this.MinimumSize = new Size(820, 600);
            this.BackColor = Color.FromArgb(10, 14, 40);
            this.FormBorderStyle = FormBorderStyle.None;     // PANTALLA COMPLETA al iniciar (sin barra de titulo)
            this.WindowState = FormWindowState.Maximized;    // borde nulo + maximizado = cubre toda la pantalla

            lblStatus = new Label(); TransLabel(lblStatus, 9.5f); lblStatus.Text = "Cargando musica...";
            buscaView = new BuscaView();   // la casilla de BUSCAR, en medio de la fila de arriba
            Controls.Add(buscaView);
            helpBar = new HelpBar();   // instrucciones con formas/colores (sin nombres de teclas)

            lblAttract = new Label();
            lblAttract.AutoSize = false;
            lblAttract.TextAlign = ContentAlignment.MiddleCenter;
            lblAttract.BackColor = Color.FromArgb(10, 12, 30);
            lblAttract.ForeColor = Color.FromArgb(250, 230, 50);
            lblAttract.Font = new Font(FontFamily.GenericSansSerif, 15f, FontStyle.Bold);
            lblAttract.Text = "¡ PRESIONA UN BOTON PARA USAR LA ROCOLA !";
            lblAttract.Visible = false;

            letterBar = new LetterBar();
            letterBar.Available = letterAvailable;
            letterBar.OnPick = delegate (char c)
            {
                if (c == VideoMark && (videoAlbums == null || videoAlbums.Count == 0)) return;
                if (c == TopMark) { BuildTopDiscs(); if (topDiscs == null || topDiscs.Count == 0) return; }
                currentLetter = c; page = 0; selAlbumIndex = 0; letterBar.Current = c;
                RefreshAlbums(); this.Focus();
            };

            headerView = new HeaderView();

            albumView = new AlbumView();
            albumView.Sky = formStars;   // MISMO campo de estrellas que el fondo del form: la rejilla pinta su ventana (una sola pieza, sin costuras)
            albumView.GetCover = LoadCoverAsync;
            // LA MARCA DE "YA LA PUSISTE". La pared no guarda la cola: pregunta. Asi no hay dos listas
            // que puedan decir cosas distintas, y apagar la marca es dejar de contestar.
            albumView.EnCola = delegate (Album a)
            {
                if (!marcaColaOn || a == null || a.Folder == null || colaDiscos.Count == 0) return false;
                return colaDiscos.ContainsKey(a.Folder);
            };
            albumView.GetCoverByPath = LoadCoverByPath;
            albumView.OnActivate = delegate (int local)
            {
                List<Album> list = CurrentList();
                int gi = page * PageSize + local;
                if (gi >= 0 && gi < list.Count) { selAlbumIndex = gi; albumView.Selected = local; EnterAlbum(list[gi]); }
            };

            panelSongs = new BgPanel();
            panelSongs.Sky = formStars;   // idem: el interior del disco pinta su ventana del MISMO campo compartido
            panelSongs.BackColor = Shade(DefaultAccent, 0.70);
            panelSongs.Visible = false;

            lblAlbum = new Label(); lblAlbum.BackColor = Color.Transparent; lblAlbum.ForeColor = Color.White; lblAlbum.Font = Bold(16f);

            cubeBox = new CubeBox();
            cubeBox.BackColor = Color.Transparent;

            songList = new SongListView();
            songList.BackColor = Shade(DefaultAccent, 0.76);
            songList.Font = Bold(13f);
            songList.RowH = 30;
            songList.GetSonando = delegate (int i)
            {
                if (sonandoKey.Length == 0 || i < 0 || i >= songItems.Count) return false;
                Track tk = songItems[i] as Track;
                string k = (tk != null) ? tk.Path : null;
                if (k == null) { VideoItem vi = songItems[i] as VideoItem; if (vi != null) k = vi.Path; }
                return k != null && string.Equals(k, sonandoKey, StringComparison.OrdinalIgnoreCase);
            };
            songList.GetQueuePos = delegate (int i)
            {
                if (i < 0 || i >= songItems.Count || colaPos.Count == 0) return 0;
                Track tk = songItems[i] as Track;
                string k = (tk != null) ? tk.Path : null;
                if (k == null) { VideoItem vi = songItems[i] as VideoItem; if (vi != null) k = vi.Path; }
                int pos;
                return (k != null && colaPos.TryGetValue(k, out pos)) ? pos : 0;
            };
            songList.GetGenero = delegate (int i)
            {
                if (i < 0 || i >= songItems.Count) return "";
                // En los discos de LO MAS SONADO cada cancion viene de un disco distinto, asi que se mira el
                // suyo y no el del monton. Lo demas lo resuelve la cascada (ver GeneroDeCancion).
                Album org = currentAlbum;
                if (currentAlbum != null && currentAlbum.IsTop && currentAlbum.TrackAlbums != null && i < currentAlbum.TrackAlbums.Count)
                    org = currentAlbum.TrackAlbums[i];
                return GeneroDeCancion(songItems[i] as Track, org);
            };
            songList.GetCount = delegate { return songItems.Count; };
            songList.GetText = delegate (int i) { return (i >= 0 && i < songItems.Count) ? songItems[i].ToString() : ""; };
            songList.GetRight = delegate (int i)   // duracion de la cancion (los videos no se pre-analizan)
            {
                if (i < 0 || i >= songItems.Count) return "";
                Track tk = songItems[i] as Track;
                if (tk != null) return DurText(tk.Path);
                VideoItem vi = songItems[i] as VideoItem;   // los videos solo traen duracion donde se pueden medir (rama HD)
                return (vi != null) ? DurText(vi.Path) : "";
            };
            songList.OnPick = delegate (int idx) { songSel = idx; FillSongPage(); UpdateTopSongVisuals(); };         // click simple
            songList.OnActivate = delegate (int idx) { songSel = idx; FillSongPage(); EnqueueSelectedSong(); };      // doble-click

            songPager = new SongPagerBar();
            songPager.Visible = false;
            songPager.BackColor = Shade(DefaultAccent, 0.70);
            panelSongs.Controls.Add(lblAlbum);
            panelSongs.Controls.Add(cubeBox);
            panelSongs.Controls.Add(songList);
            panelSongs.Controls.Add(songPager);

            // TARJETA DE LO QUE SUENA: lblNowTop lleva el TITULO (grande, blanco) y lblNow el ARTISTA (mas
            // chico, verde). Antes las dos eran la misma frase partida por ancho; ahora cada una dice una cosa.
            lblNow = new Label(); TransLabel(lblNow, 11.5f); lblNow.Text = ""; lblNow.AutoEllipsis = true;
            lblNow.ForeColor = Color.FromArgb(120, 230, 165);   // ESTETICA: verde "sonando" (se distingue de "siguiente")
            lblNowTop = new Label(); TransLabel(lblNowTop, 15f); lblNowTop.Text = "Nada reproduciendose"; lblNowTop.AutoEllipsis = true;
            lblNowTop.ForeColor = Color.FromArgb(236, 242, 255);   // el titulo, en blanco: es lo que se lee primero
            lblNowTop.TextAlign = ContentAlignment.MiddleLeft;
            lblNow.UseMnemonic = false; lblNowTop.UseMnemonic = false;   // un "&" del titulo es un "&", no un subrayado
            lblNext = new Label(); TransLabel(lblNext, 10.5f); lblNext.Text = "Sigue:  -"; lblNext.AutoEllipsis = true;
            lblNext.ForeColor = Color.FromArgb(150, 165, 200);
            lblNext.UseMnemonic = false;                        // igual que arriba: un "&" del titulo es un "&"
            pastCola = new PastillaView(); pastCola.Etiqueta = "En cola"; pastCola.Valor = "0";
            pastCola.Acento = Color.FromArgb(140, 205, 255);
            pastCred = new PastillaView(); pastCred.Etiqueta = "Inserta una moneda"; pastCred.Valor = "";
            pastCred.Acento = Color.FromArgb(255, 205, 90);
            pastGenero = new GeneroView(); pastGenero.Font = new Font(this.Font.FontFamily, 10f, FontStyle.Bold); pastGenero.Visible = false;
            lblMejorada = new Label(); TransLabel(lblMejorada, 12f); lblMejorada.Text = "MEJORADA";
            lblMejorada.TextAlign = ContentAlignment.MiddleLeft; lblMejorada.Visible = false;   // aparece solo si la cancion suena mejorada (PositionMejorada)

            miniCube = new CubeBox();
            miniCube.BackColor = Color.Transparent;
            miniCube.Visible = false;

            progress = new ProgressView();
            lblTime = new Label(); TransLabel(lblTime, 13f); lblTime.Text = "0:00 / 0:00";

            lblToast = new Label();
            lblToast.TextAlign = ContentAlignment.MiddleCenter;
            lblToast.BackColor = Color.FromArgb(40, 165, 90);
            lblToast.ForeColor = Color.White;
            lblToast.Font = Bold(14f);
            lblToast.Visible = false;

            searchOverlay = new SearchOverlay();
            searchOverlay.Sky = formStars;   // MISMO campo de estrellas que el resto: una sola pieza, sin costuras ni memoria doble
            searchOverlay.Visible = false;
            searchOverlay.GetCover = LoadCover;
            searchOverlay.GetCoverYa = PortadaEnMemoria;   // mientras se barren resultados, nada de encargos al disco
            // De que disco es cada resultado y de que genero. El genero lo va aprendiendo el paseo de fondo,
            // asi que puede llegar despues: por eso DatosVer, que hace que las tarjetas se rehagan al llegar.
            searchOverlay.GetDisco = delegate (SearchItem it)
            {
                if (it == null || it.AlbumRef == null) return "";
                if (it.Kind == 1) return "";                  // la tarjeta YA es el disco: no repetirlo
                return it.AlbumRef.Name ?? "";
            };
            searchOverlay.GetGenero = delegate (SearchItem it)
            {
                // La misma respuesta que dentro del disco: si es una cancion se le pregunta por ella; si es un
                // disco o un artista, por el disco. Antes el buscador y el interior podian decir cosas distintas.
                return (it != null) ? GeneroDeCancion(it.TrackRef, it.AlbumRef) : "";
            };
            searchOverlay.OnQueryChanged = RecomputeResults;
            searchOverlay.OnTecleo = AlTeclearBusqueda;
            searchOverlay.OnChoose = ChooseSearchResult;
            searchOverlay.OnClose = CloseSearch;

            attractView = new AttractView();
            attractView.Visible = false;
            attractView.GetCoverByPath = LoadCoverByPath;

            Controls.Add(lblStatus); Controls.Add(helpBar); Controls.Add(pastCred); Controls.Add(pastGenero);
            Controls.Add(letterBar); Controls.Add(headerView);
            Controls.Add(albumView); Controls.Add(panelSongs);
            Controls.Add(lblNowTop); Controls.Add(lblNow); Controls.Add(lblMejorada); Controls.Add(lblNext); Controls.Add(pastCola); Controls.Add(progress); Controls.Add(lblTime);
            Controls.Add(miniCube);
            Controls.Add(lblAttract);
            Controls.Add(lblToast);
            Controls.Add(searchOverlay);
            Controls.Add(attractView);

            // ----- DIAGNOSTICO TEMPORAL: letrero que muestra que tecla recibe la app -----
            // ----- Pantalla del ASISTENTE DE CONFIGURACION de botones -----
            lblConfig = new Label();
            lblConfig.AutoSize = false;
            lblConfig.TextAlign = ContentAlignment.MiddleCenter;
            lblConfig.BackColor = Color.FromArgb(8, 10, 26);
            lblConfig.ForeColor = Color.FromArgb(245, 248, 255);
            lblConfig.Font = new Font(FontFamily.GenericSansSerif, 20f, FontStyle.Bold);
            lblConfig.Text = "";
            lblConfig.Visible = false;
            Controls.Add(lblConfig);
            lblConfig.BringToFront();
        }

        private void LayoutControls()
        {
            if (albumView == null) return;
            int W = ClientSize.Width, H = ClientSize.Height, pad = 14;

            if (searchOverlay != null) searchOverlay.Bounds = SearchOverlayRect();
            if (attractView != null) attractView.Bounds = new Rectangle(0, 0, W, H);

            // PANTALLA COMPLETA del video: ocupa casi todo; arriba queda una franja con el aviso pulsante.
            if (videoFull && video != null)
            {
                int strip = 46;
                lblAttract.SetBounds(0, 0, W, strip);
                video.SetBounds(0, strip, W, H - strip);
                video.BringToFront();
                lblAttract.BringToFront();
                if (helpBar != null) helpBar.Visible = false;
                if (buscaView != null) buscaView.Visible = false;
                return;   // lo demas queda detras del video; se reacomoda al salir
            }
            if (helpBar != null) helpBar.Visible = true;
            if (lblAttract != null) lblAttract.Visible = false;

            // Con video, el contenido (letras, encabezado, rejilla) se encoge a la IZQUIERDA;
            // la barra inferior (lo de abajo) SIEMPRE ocupa todo el ancho.
            int splitX = videoOn ? (int)(W * 0.50) : (W - pad);
            int contentRight = videoOn ? (splitX - 12) : (W - pad);
            int contentW = Math.Max(220, contentRight - pad);

            // LA FILA DE ARRIBA, apretada. Las instrucciones ocupan 439 px de verdad y se les reservaban 580:
            // 141 px de aire. Y el ENCABEZADO de la seccion tenia una fila entera para el solo, 44 px de alto en
            // 1024x768. Los dos comparten ahora esta fila, y esos 44 px se los queda la rejilla de discos, que es
            // lo que la gente mira. El encabezado se dibuja pegado a la derecha y se encoge solo si le aprietan.
            int barraDer = videoOn ? contentRight : (W - pad);
            int helpX = pad;
            // La fila de arriba crece con la pantalla, como la de las letras: en una pantalla grande, una
            // fila clavada en 34 px deja la casilla de BUSCAR pequenita justo donde tiene que verse de lejos.
            // Con 768 de alto la cuenta da 34 exactos, asi que en la maquina del bar no cambia nada.
            // La fila va mas alta que antes (34 -> 44) porque la casilla de BUSCAR tiene que verse desde
            // lejos, de pie y de noche: es lo que decide si el cliente que no sabe usarla acaba poniendo su
            // cancion o se va. Los 10 px salen de la rejilla de discos, que tiene de sobra.
            int filaH = H * 44 / 768; if (filaH < 44) filaH = 44; else if (filaH > 76) filaH = 76;
            int helpW = Math.Max(120, Math.Min(HelpBar.Ancho(filaH), barraDer - helpX));
            if (helpBar != null) helpBar.SetBounds(helpX, 8, helpW, filaH);
            // LA CASILLA DE BUSCAR, EN MEDIO. Va centrada respecto a la pantalla entera -no respecto al
            // hueco que queda- porque el sitio donde el ojo la busca es el centro de arriba. Si no cabe sin
            // pisar las instrucciones, se corre a la derecha lo justo.
            int busX = helpX + helpW + 12, busW = 0;
            if (buscaView != null)
            {
                busW = Math.Min(BuscaView.Ancho(filaH), Math.Max(0, barraDer - busX));
                busX = SitioBusca(W, busW, busX, barraDer);
                buscaView.SetBounds(busX, 8, busW, filaH);
                buscaView.Visible = (busW >= 120 && !videoOn);
            }
            int headX = (buscaView != null && buscaView.Visible) ? (busX + busW + 12) : (helpX + helpW + 12);
            headerView.SetBounds(headX, 8, Math.Max(0, barraDer - headX), filaH);
            if (lblConfig != null) lblConfig.SetBounds(0, 0, W, H);   // asistente de config: pantalla completa

            // LA BARRA DE LETRAS CRECE CON LA PANTALLA. Estaba clavada en 40 px de alto: en 1024x768 se ve
            // bien, pero en una pantalla ancha cada casilla pasa de 100 px y la letra seguia siendo la misma
            // pizca perdida en medio de tanto hueco. Con 768 de alto la cuenta da 40 exactos, asi que en la
            // maquina del bar no cambia absolutamente nada.
            // ...y tambien con lo ANCHA que le queda cada casilla. En una pantalla ultra ancha las 29 casillas
            // se reparten mas de 3000 px: quedan de 117 de ancho por 40 de alto, una ranura achatada con una
            // letra chiquita perdida dentro. Se le pide al alto que acompane al ancho de casilla para que la
            // casilla siga siendo una casilla. En 1024x768 las dos cuentas dan 40 o menos, asi que la maquina
            // del bar no cambia en nada.
            int lettersY = 8 + filaH + 4;
            int lettersH = H * 40 / 768;
            int porCasilla = (contentW * 8) / (29 * 10);   // 0.80 del ancho de casilla
            if (porCasilla > lettersH) lettersH = porCasilla;
            if (lettersH < 40) lettersH = 40; else if (lettersH > 104) lettersH = 104;
            letterBar.SetBounds(pad, lettersY, contentW, lettersH);

            // LA FRANJA DE ESTADO, en grande. Es lo que se lee DE LEJOS -de pie, a dos metros de la maquina-
            // y estaba pensada para mirarla de cerca: letra chica, cubo de 64 y una barra de duracion de 16 px
            // que casi no se veia. Todo sube alrededor de un cuarto. La franja crece unos 20 px de alto y la
            // rejilla de discos los cede: la aurora, el horizonte y la textura de la franja se acomodan solos
            // porque todos salen de BotStripTop.
            // ==========  LA TARJETA DE LO QUE SUENA  ==========
            // La portada manda a la izquierda y a su lado, en renglones: el titulo, el artista, lo que sigue y
            // la barra de duracion con el reloj. A la derecha, creditos y cola en capsulas. Ocupa 96 px de alto
            // -18 menos que los cuatro renglones sueltos de antes- y esos 18 se los queda la rejilla de discos.
            // Los cuatro renglones de la tarjeta, medidos con la letra que toque y sin un pixel de sobra:
            // titulo, artista, lo que sigue, y la barra de duracion. La portada mide lo mismo que los cuatro
            // juntos, asi que la tarjeta es un bloque cuadrado a la izquierda y texto a la derecha.
            int hTit = Math.Max(24, (lblNowTop != null ? lblNowTop.Font.Height : 24) + 1);
            int hArt = Math.Max(18, (lblNow != null ? lblNow.Font.Height : 18) + 1);
            int hSig = Math.Max(17, (lblNext != null ? lblNext.Font.Height : 17) + 1);
            int progH = 12;
            int tarjetaH = hTit + hArt + hSig + 4 + progH + 2;
            int tarjetaY = H - pad - tarjetaH;
            int cubeSize = tarjetaH;
            int nowTopY = tarjetaY;                  // el titulo manda donde arranca la franja (ver BotStripTop)
            miniCube.SetBounds(pad, tarjetaY, cubeSize, cubeSize);

            // Las capsulas, arriba a la derecha. Se miden por su contenido: "Inserta una moneda" es mucho mas
            // ancha que "Creditos 3", y una capsula a medias se veria mal.
            int pastH = AltoPastilla(tarjetaH);
            int wCred = PastillaView.Ancho(pastCred.Etiqueta, pastCred.Valor, pastH, this.Font.FontFamily, false);
            int wCola = PastillaView.Ancho(pastCola.Etiqueta, pastCola.Valor, pastH, this.Font.FontFamily, pastCola.ConPortadas);
            int pastY = tarjetaY;
            pastCred.SetBounds(W - pad - wCred, pastY, wCred, pastH);
            pastCola.SetBounds(W - pad - wCred - 10 - wCola, pastY, wCola, pastH);

            int txtX = pad + cubeSize + 14;
            int derPast = W - pad - wCred - wCola - 24;             // hasta donde puede llegar el titulo
            int txtW = Math.Max(120, derPast - txtX);
            lblNowTop.SetBounds(txtX, tarjetaY, txtW, hTit);                  // el TITULO
            lblNow.SetBounds(txtX, tarjetaY + hTit, txtW, hArt);              // el ARTISTA

            int timeW = 130;
            int anchoDer = W - pad - txtX;
            int progW = Math.Max(50, anchoDer - timeW - 12);
            lblNext.SetBounds(txtX, tarjetaY + hTit + hArt, progW, hSig);     // lo que SIGUE
            int filaY = tarjetaY + hTit + hArt + hSig + 4;                    // y al pie, la barra con el reloj
            progress.SetBounds(txtX, filaY, progW, progH);
            lblTime.SetBounds(txtX + progW + 12, filaY - (24 - progH) / 2, timeW, 24);
            iaNowRowW = txtW; PositionMejorada();   // acomoda el letrero MEJORADA tras el artista

            int albumY = lettersY + lettersH + 10;
            // EL AVISO DE ESTADO ya no ocupa sitio propio en la fila de arriba: durante el uso normal esta
            // VACIO (solo habla al escanear o si algo falla), y le estabamos guardando 200 px al lado de las
            // instrucciones para nada. Ahora se pone encima del borde de la rejilla, que esta justo vacia en
            // los unicos momentos en que el aviso tiene algo que decir.
            lblStatus.SetBounds(pad, albumY + 4, Math.Max(120, contentW), 22);
            int albumBottom = nowTopY - 12;   // la rejilla termina antes del hueco reservado para la 2a linea
            int albumH = Math.Max(120, albumBottom - albumY);
            albumView.SetBounds(pad, albumY, contentW, albumH);
            panelSongs.SetBounds(pad, albumY, contentW, albumH);

            // Reproductor de video a la derecha (donde estan los cubos)
            if (video != null)
            {
                int vx = splitX;
                int vy = lettersY;
                int vw = Math.Max(120, (W - pad) - vx);
                int vh = Math.Max(90, albumBottom - vy);
                video.SetBounds(vx, vy, vw, vh);
                video.Visible = videoOn && !searchOpen;   // garantia: oculto si no hay video sonando (o si el buscador esta abierto)
            }

            LayoutSongsPanel();
#if ROCOLA_GPU
            // Un reacomodo REAL (video que entra o sale, cambio de tamano) mueve lo que la textura de UI tiene
            // horneado: se rehace YA, en el mismo cuadro. Pero LayoutControls tambien corre en CADA cambio de
            // cancion (PlayNext) sin que nada se mueva: la HUELLA evita rehornear y resubir la textura en vano
            // (un tropiezo de 10-20 ms por cancion en el CPU modesto, para nada).
            int huella = (ClientSize.Width * 131072) + (ClientSize.Height * 4) + (videoOn ? 2 : 0) + (videoFull ? 1 : 0);
            if (huella != layoutStamp)
            {
                layoutStamp = huella;
                uiOverlaySig = SigNada;
                if (gpuPanel != null) gpuPanel.UiUrgent = true;
            }
#endif
        }

        private void LayoutSongsPanel()
        {
            int w = panelSongs.ClientSize.Width, h = panelSongs.ClientSize.Height;
            lblAlbum.SetBounds(8, 8, Math.Max(50, w - 16), 32);
            int cube = Math.Min(h - 80, (int)(w * 0.40));
            if (cube < 80) cube = 80;
            cubeBox.SetBounds(12, 52, cube, cube);
            int listX = cube + 30, listW = Math.Max(60, w - cube - 42);
            if (songPager != null) songPager.SetBounds(listX, 52, listW, 24);   // instrucciones de pagina, ARRIBA de la lista
            songList.SetBounds(listX, 80, listW, Math.Max(60, h - 88));
            // La lista contiene SOLO la pagina actual (sin scroll); al cambiar el tamaño se reparte de nuevo.
            if (panelSongs.Visible && songItems.Count > 0 && songList.RowH > 0) FillSongPage();
        }

        private void Letter_Refresh() { letterBar.Current = currentLetter; letterBar.Invalidate(); }

        // El color de la seccion: dorado para lo mas sonado, el azul de los videos para los videos y, para una
        // letra, el color del genero que manda dentro de ella -el MISMO que luce arriba en la barra-.
        private Color AcentoSeccion()
        {
            if (currentLetter == TopMark) return Color.FromArgb(255, 205, 90);
            if (currentLetter == VideoMark) return Color.FromArgb(140, 220, 232);
            string et;
            if (letterTag != null && letterTag.TryGetValue(currentLetter, out et)) return ColorDeEtiqueta(et);
            return DefaultAccent;
        }

        private static readonly string[] AudioExt = { ".mp3", ".wav" };
        private static readonly string[] VideoExt = { ".mp4", ".avi", ".wmv", ".mpg", ".mpeg", ".mov", ".mkv", ".flv", ".m4v", ".vob", ".divx", ".3gp", ".asf" };

        private void LoadMusicFolder()
        {
            List<string> roots = AllMusicRoots();   // carpeta "musica" principal + las agregadas con Ctrl+F2 (otros discos)
            if (roots.Count > 0) StartScan(roots);
            else
            {
                lblStatus.Text = "No encontre musica. Conecta el disco donde este y eligelo en la ventana que se abre.";
                PideElegirMusica();
            }
        }

        // SIN MUSICA, LA VENTANA DE CARPETAS SE ABRE SOLA.
        //
        // Antes solo se escribia un letrero abajo diciendo "crea una carpeta musica al lado del .exe (o
        // agrega una con Ctrl+F2)". En la maquina del bar eso no sirve de nada: no hay ningun ".exe" a la
        // vista y hay que SABERSE una combinacion de teclas para poder hacer algo. Poner la musica es
        // mantenimiento -y ahi hay teclado y raton-, pero no puede hacer falta adivinar nada para llegar.
        //
        // EL SEGURO CONTRA EL BUCLE. La ventana, al cerrarse, vuelve a cargar la musica; si sigue sin haber,
        // esto se llamaria otra vez y se abriria sola para siempre, sin poder salir. Asi que se abre UNA vez
        // por sesion: si se cierra sin arreglar nada, se queda cerrada. Al proximo arranque vuelve a salir.
        private bool gestorAbierto = false;    // la ventana esta abierta AHORA
        private bool gestorOfrecido = false;   // ya se abrio sola una vez en esta sesion
        private void AbrePorFaltaDeMusica() { ShowMusicDirManager(true); }
        private void PideElegirMusica()
        {
            if (gestorAbierto || gestorOfrecido) return;
            gestorOfrecido = true;
            // Despues de que la pantalla este pintada: si no, la ventana saldria encima de una rocola a
            // medio dibujar.
            try { this.BeginInvoke(new MethodInvoker(AbrePorFaltaDeMusica)); } catch { }
        }

        private List<string> scanRoots;   // raices del escaneo en curso/vigente (las usa el worker; solo se asignan aqui)

        private void StartScan(List<string> roots)
        {
            if (scanner != null && scanner.IsBusy) return;   // ya hay un escaneo en curso (doble F5): ignorar
            libBuilding = true;   // desde aqui y hasta Completed, las listas son del worker
            if (searchOpen) CloseSearch();            // un re-escaneo invalida lo que el buscador muestra
            lastQuery = null; lastMatches = null;     // ...y su cache incremental (evita resultados huerfanos)
            bolsaLetra.Clear();                       // y lo guardado de cada letra suelta: apunta a fichas que ya no valen
            tracks.Clear(); albums.Clear(); byLetter.Clear(); letterAvailable.Clear(); searchIndex.Clear();
            BackToAlbums();
            scanRoots = roots;
            lblStatus.Text = "Buscando musica en: " + roots[0] + (roots.Count > 1 ? (" (+" + (roots.Count - 1) + " carpetas mas)") : "") + " ...";

            scanner = new BackgroundWorker();
            scanner.WorkerReportsProgress = true;
            scanner.DoWork += Scanner_DoWork;
            scanner.ProgressChanged += Scanner_ProgressChanged;
            scanner.RunWorkerCompleted += Scanner_RunWorkerCompleted;
            scanner.RunWorkerAsync(roots);
        }

        private void Scanner_DoWork(object sender, DoWorkEventArgs e)
        {
            List<string> roots = (List<string>)e.Argument;
            // CACHE DE BIBLIOTECA: si es valido, evita las DOS caminatas del disco (en HDD eran minutos).
            List<Track> ctk; List<string> cvd; Dictionary<string, string> ccv;
            if (TryLoadLibraryCache(roots, out ctk, out cvd, out ccv))
            {
                // ARMADO EN SEGUNDO PLANO: ordenar e indexar las 118 mil canciones tomaba 1-3 segundos
                // DEL HILO DE LA INTERFAZ al arrancar; aqui corre en el worker y el arranque no se congela.
                tracks.AddRange(ctk);
                PerfilaDisco(tracks);   // disco duro o SSD, decidido ANTES de la primera pagina de caratulas
                cachedVideoPaths = cvd; cachedCovers = ccv;
                BuildAlbums(roots); BuildVideoSection(roots); BuildSearchIndex();
                e.Result = true;    // vino del cache
                return;
            }
            // UN SOLO RECORRIDO del disco. Antes se caminaba el arbol DOS veces (una por el audio y otra
            // por el video) y ademas se pedia la lista de cada carpeta OTRA vez para buscar la portada: tres
            // lecturas de cada carpeta. Ahora se camina una sola vez y de esa misma lista salen las tres cosas.
            // El resultado se deja en cachedVideoPaths/cachedCovers, que es EXACTAMENTE lo que ya recibe el
            // camino del cache: de ahi en adelante todo sigue igual y sin volver a tocar el disco.
            List<Track> found = new List<Track>();
            List<string> audio = new List<string>();
            List<string> vids = new List<string>();
            Dictionary<string, string> covs = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            for (int r = 0; r < roots.Count; r++) ScanFolders(roots[r], audio, vids, covs);
            for (int i = 0; i < audio.Count; i++) found.Add(Track.FromFile(audio[i]));
            tracks.AddRange(found);
            PerfilaDisco(tracks);   // idem por el camino del escaneo fresco
            cachedVideoPaths = vids; cachedCovers = covs;
            BuildAlbums(roots); BuildVideoSection(roots); BuildSearchIndex();   // tambien en segundo plano
            e.Result = false;   // escaneo fresco
        }

        private void Scanner_ProgressChanged(object sender, ProgressChangedEventArgs e)
        {
            lblStatus.Text = "Encontradas " + ((int)e.UserState) + " canciones...";
        }

        private void Scanner_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
        {
            libBuilding = false;   // las listas vuelven a ser de la interfaz (tambien si hubo error)
            if (e.Error != null) { lblStatus.Text = "Error al escanear: " + e.Error.Message; return; }

            bool fromCache = (e.Result is bool) ? (bool)e.Result : false;

            letterAvailable.Clear();
            foreach (KeyValuePair<char, List<Album>> kv in byLetter) if (kv.Value.Count > 0) letterAvailable.Add(kv.Key);
            if (videoAlbums != null && videoAlbums.Count > 0) letterAvailable.Add(VideoMark);
            topDirty = true;   // OPTIMIZACION (TOP): la biblioteca se re-escaneo (nuevos Album/Track) -> reconstruir
            BuildTopDiscs();
            if (topDiscs != null && topDiscs.Count > 0) letterAvailable.Add(TopMark);   // hay estadisticas -> seccion "Lo mas sonado"
            LeeTintes(FirmaBiblioteca());   // el color de cada letra, si ya se calculo para esta misma biblioteca
            RecalculaGenerosArtista();      // y de esos generos de disco salen los del artista, sin leer nada mas
            nombreTag.Clear();              // biblioteca nueva: lo adivinado por el nombre se vuelve a mirar
            RecalculaLetras();

            string order = LetrasOrden;
            currentLetter = '#';
            // default: primera letra REAL disponible (NO arrancar en una seccion especial)
            bool gotReal = false;
            for (int i = 0; i < order.Length; i++) { char c = order[i]; if (c == TopMark || c == VideoMark) continue; if (letterAvailable.Contains(c)) { currentLetter = c; gotReal = true; break; } }
            if (!gotReal) for (int i = 0; i < order.Length; i++) if (letterAvailable.Contains(order[i])) { currentLetter = order[i]; break; }
            page = 0; selAlbumIndex = 0;
            if (albumView != null) albumView.ResetCellCache();   // re-escaneo: descarta celdas horneadas (etiqueta/portada pueden haber cambiado para el mismo Folder)
            RefreshAlbums();

            if (albums.Count == 0) lblStatus.Text = "No encontre MP3 en esa carpeta: " + MusicFolder;
            else lblStatus.Text = "";   // las instrucciones las muestra la barra de ayuda (formas/colores)

            StartThumbWarm();   // en segundo plano: construir las miniaturas que falten (1a vez tarda; luego todo vuela)
            StartDurScan();     // barrido RAPIDO: la duracion de toda la biblioteca en minutos (no espera al analisis pesado)
            StartPreScan();     // en segundo plano: medir volumen y duracion de las canciones nuevas (nivelado desde la 1a vez)

            if (!fromCache) SaveLibraryCacheAsync();   // escaneo fresco: guardar la biblioteca para el proximo arranque
            cachedVideoPaths = null; cachedCovers = null; lastVideoPaths = null;

            // REANUDACION tras corte de luz: con la biblioteca ya armada, restaura creditos/cola/cancion
            // guardados (solo el PRIMER armado; un F5 a media jornada no toca lo que este sonando).
            if (!stateRestored && nowPlaying == null && queue.Count == 0) RestoreState();
        }

        // PRECALENTADOR de miniaturas: hilo de MINIMA prioridad que va construyendo en disco la
        // miniatura de TODAS las caratulas que falten. La primera sesion en una maquina tarda unos
        // minutos en completarse (y se PAUSA mientras alguien usa la rocola para no estorbar);
        // a partir de ahi, abrir cualquier pagina es practicamente instantaneo para siempre.
        // ===================== PRE-ANALISIS DE LA BIBLIOTECA =====================
        // Antes, una cancion NUEVA sonaba a su volumen original la primera vez (aun no habia medida) y solo
        // quedaba nivelada a partir de la segunda. Con el pre-analisis eso se acabo: en segundo plano se MIDE
        // toda la biblioteca (sonoridad K-weighted, la misma norma que usa el nivelado, + la DURACION), asi que
        // cada cancion ya llega nivelada la PRIMERA vez que alguien la pone.
        // Para que no le robe la maquina a la rocola: hilo de prioridad MINIMA, espera a que nadie este usando
        // la rocola, cede el paso si hay video, y de cada cancion mide TRAMOS repartidos (no el archivo entero):
        // ~60 s bien elegidos dan practicamente la misma sonoridad integrada que el tema completo, a una fraccion
        // del costo. Lo medido se guarda en disco cada pocas canciones: se puede apagar la rocola sin perder nada.
        private bool eqDirty = false;             // hay huellas de EQ nuevas sin guardar (las escribe FlushEqIfDirty)
        // Vuelca las huellas del EQ recien medidas. Se llama de tanto en tanto (no por cancion): recalcular el
        // promedio de la biblioteca y reescribir el archivo en cada tema seria puro desgaste de disco.
        private void FlushEqIfDirty()
        {
            if (!eqDirty) return;
            eqDirty = false;
            RecomputeEqAvg();
            SaveEqCache();
        }
        // ---------- Archivo con el material de entrenamiento de la IA ----------
        // Formato binario compacto (millones de pares caben sin problema): cabecera "RIAD" + version + tamaños,
        // y luego cada par como 28 float de entrada + 12 float de objetivo. numpy lo lee de un tiron.
        private const int IaFramesPerSong = 192;   // cuadros COSECHADOS por cancion y pasada (repartidos por lo descomprimido)
        private const int IaPasadasMax = 8;        // pasadas del modo pasivo por cancion (cada una, cuadros distintos)
        // Traduccion entre el NIVEL apuntado en rocola_ia_hechas.txt y cuantas pasadas pasivas lleva la cancion:
        //   nivel 0 = ninguna;  1 = una;  2 = repasada A FONDO (ya dio todo lo suyo);  3..9 = 2..8 pasadas.
        // Los archivos viejos se siguen leyendo tal cual: en ellos solo hay niveles 1 y 2, con el mismo
        // significado que aqui.
        private static int IaPasadasDe(int nivel)
        { return (nivel <= 0) ? 0 : (nivel == 1) ? 1 : (nivel == 2) ? int.MaxValue : (nivel - 1); }
        private static int IaNivelDePasada(int pasadas)
        { return (pasadas <= 0) ? 1 : (pasadas + 2); }
        // CUANTO VALE cada nivel. No es su numero: el 2 -repasada A FONDO- es el TOPE, porque de esa
        // cancion ya no queda nada por sacar, aunque antes hubiera acumulado varias pasadas del pasivo
        // (que llevan numeros mas altos). Con esto el apunte sigue siendo de una sola direccion: una
        // cancion nunca baja de nivel, asi que no se puede volver a cosechar lo que ya se cosecho.
        private static int IaRango(int nivel) { return (nivel == 2) ? 100 : nivel; }
        private const int IaDeepFrames = 1536;     // A FONDO: cuadros APROVECHADOS, repartidos por TODA la cancion
        private const int IaWarmFrames = 64;       // los primeros no se usan: el acantilado aun se esta midiendo
        // TOPE del archivo de material. Existe para que el archivo siga siendo MANEJABLE: hay que poder copiarlo
        // a una USB y cargarlo en la PC donde se entrena. 24 GB cubren de sobra una biblioteca de ~20 mil
        // canciones aptas cosechadas a fondo, y caben holgados en una memoria de 64 GB (con formato exFAT o NTFS;
        // en FAT32 ningun archivo puede pasar de 4 GB, asi que ahi habria que bajarlo). El entrenador NO necesita
        // 24 GB de RAM: toma una muestra repartida por todo el archivo (ver ia/entrenar_ia.py). Se cambia con
        // ia_datos_mb= en la configuracion; 0 lo quita del todo.
        private long iaMaxBytes = 24L * 1024 * 1024 * 1024;
        private bool IaBudgetFull() { return iaMaxBytes > 0 && (long)iaPairsTotal * 160L + 16L >= iaMaxBytes; }
        private string IaInfoText()
        {
            long mb = ((long)iaPairsTotal * 160L + 16L) / (1024 * 1024);
            string tam = (mb >= 1024) ? ((mb / 1024.0).ToString("0.0") + " GB") : (mb.ToString("#,0") + " MB");
            return iaPairsTotal.ToString("#,0") + " ejemplos (" + tam
                   + (IaBudgetFull() ? ", tope alcanzado" : "") + ")";
        }
        private static readonly float[] IaCutsHz = { 11000f, 13000f, 15000f, 16500f, 18000f };   // cortes simulados
        // Las mismas rutas viven en varias tablas (sonoridad, duracion, EQ, cosecha de IA, repaso a fondo) y en
        // la propia lista de canciones. Con cien mil canciones eso eran CINCO copias del mismo texto, decenas de
        // megas tirados en una maquina de 4 GB. Compartiendo UNA sola copia por ruta se juntan todas en una, y
        // de paso las busquedas salen mas rapido (comparar dos iguales se resuelve por referencia).
        private static string Pool(string s) { return (s == null || s.Length == 0) ? s : string.Intern(s); }
        private string IaDataFile() { return RutaDatos("rocola_ia_datos.bin"); }
        private string IaDoneFile() { return RutaDatos("rocola_ia_hechas.txt"); }
        // Formato: "ruta" (nivel 1, el de siempre) o "N|ruta" (nivel N). Una ruta de Windows no puede llevar
        // "|", asi que distinguirlos es seguro y los archivos viejos se siguen leyendo tal cual.
        private void LoadIaDone()
        {
            try
            {
                string f = IaDoneFile();
                if (!File.Exists(f)) return;
                foreach (string line in File.ReadAllLines(f))
                {
                    string r = line.Trim(); if (r.Length == 0) continue;
                    int niv = 1;
                    if (r.Length > 2 && r[1] == '|') { int d = r[0] - '0'; if (d >= 1 && d <= 9) { niv = d; r = r.Substring(2); } }
                    // Si una cancion aparece dos veces manda la de MAS VALOR (ver IaRango): normalmente es
                    // la ultima, porque el archivo se escribe anadiendo al final, pero lo que decide es el
                    // valor y no la posicion. Asi un archivo escrito a medias o desordenado no puede hacer
                    // que se vuelva a cosechar algo ya cosechado.
                    r = Pool(r);
                    int ant; if (iaDone.TryGetValue(r, out ant) && IaRango(ant) >= IaRango(niv)) continue;
                    iaDone[r] = niv;
                }
            }
            catch { }
        }
        private readonly object iaDoneLock = new object();
        private volatile bool iaDoneDirty = false;   // hay canciones nuevas cosechadas sin apuntar en disco
        private readonly List<string> iaPend = new List<string>();   // lineas apuntadas y aun sin escribir
        // Apunta que de esta cancion ya se cosecho hasta "nivel". false si ya estaba en ese nivel o mas.
        private bool MarkIaDone(string path, int nivel)
        {
            lock (iaDoneLock)
            {
                int ant; if (iaDone.TryGetValue(path, out ant) && IaRango(ant) >= IaRango(nivel)) return false;
                iaDone[path] = nivel;
                iaPend.Add((nivel > 1 ? (nivel.ToString() + "|") : "") + path);
            }
            iaDoneDirty = true;
            return true;
        }
        // Se ANADE al final en vez de reescribir el archivo entero. Con cien mil canciones, reescribirlo cada
        // 10 canciones durante el repaso a fondo eran megas y megas al disco cada minuto, para nada.
        private void SaveIaDone()
        {
            List<string> nuevas;
            lock (iaDoneLock) { if (iaPend.Count == 0) return; nuevas = new List<string>(iaPend); iaPend.Clear(); }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    StringBuilder sb = new StringBuilder(nuevas.Count * 64 + 16);
                    for (int i = 0; i < nuevas.Count; i++) sb.Append(nuevas[i]).Append("\r\n");
                    lock (iaDoneLock) File.AppendAllText(IaDoneFile(), sb.ToString());
                }
                catch { }
            });
        }
        // ---- Canciones ya repasadas A FONDO (mismo formato que las de la IA: una ruta por linea) ----
        private string DeepDoneFile() { return RutaDatos("rocola_afondo.txt"); }
        private readonly object deepDoneLock = new object();
        private volatile bool deepDoneDirty = false;   // hay canciones repasadas sin apuntar en disco
        private readonly List<string> deepPend = new List<string>();   // rutas apuntadas y aun sin escribir
        private void LoadDeepDone()
        {
            try
            {
                string f = DeepDoneFile();
                if (!File.Exists(f)) return;
                foreach (string line in File.ReadAllLines(f)) { string r = line.Trim(); if (r.Length > 0) deepDone.Add(Pool(r)); }
            }
            catch { }
        }
        private void MarkDeepDone(string path)
        {
            lock (deepDoneLock) { if (!deepDone.Add(path)) return; deepPend.Add(path); }
            deepDoneDirty = true;
        }
        // Igual que la lista de la IA: se ANADE al final, no se reescribe entera cada 10 canciones.
        private void SaveDeepDone()
        {
            List<string> nuevas;
            lock (deepDoneLock) { if (deepPend.Count == 0) return; nuevas = new List<string>(deepPend); deepPend.Clear(); }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    StringBuilder sb = new StringBuilder(nuevas.Count * 64 + 16);
                    for (int i = 0; i < nuevas.Count; i++) sb.Append(nuevas[i]).Append("\r\n");
                    lock (deepDoneLock) File.AppendAllText(DeepDoneFile(), sb.ToString());
                }
                catch { }
            });
        }
        private void IaCountPairs()
        {
            try
            {
                FileInfo fi = new FileInfo(IaDataFile());
                iaPairsTotal = (fi.Exists && fi.Length > 16) ? (int)((fi.Length - 16) / 160) : 0;
            }
            catch { iaPairsTotal = 0; }
        }
        // Añade al archivo los pares de UNA cancion (solo se llama con canciones que si conservan sus agudos).
        // Con el repaso a fondo en varios hilos, esto lo llaman VARIOS a la vez: dos anadidos solapados
        // dejarian el archivo de material entrelazado y por tanto inservible. El candado cuesta nada al lado
        // de descomprimir una cancion, que es lo que hace el hilo justo antes de llegar aqui.
        private readonly object iaFileLock = new object();
        private void IaAppendPairs(List<float> pairs)
        {
            if (pairs == null || pairs.Count < 40) return;
            lock (iaFileLock)
            try
            {
                string f = IaDataFile();
                bool nuevo = !File.Exists(f) || new FileInfo(f).Length < 16;
                using (FileStream fs = new FileStream(f, FileMode.Append, FileAccess.Write))
                using (BinaryWriter bw = new BinaryWriter(fs))
                {
                    if (nuevo) { bw.Write((byte)'R'); bw.Write((byte)'I'); bw.Write((byte)'A'); bw.Write((byte)'D'); bw.Write(1); bw.Write(28); bw.Write(12); }
                    for (int i = 0; i < pairs.Count; i++) bw.Write(pairs[i]);
                }
                iaPairsTotal += pairs.Count / 40;
            }
            catch { }
        }

        // ---- Duraciones rapidas: "segundos|ruta" por linea, escritas POR ANADIDO ----
        private string DurFastFile() { return RutaDatos("rocola_duracion.txt"); }
        private void LoadDurFast()
        {
            try
            {
                string f = DurFastFile();
                if (!File.Exists(f)) return;
                foreach (string line in File.ReadAllLines(f))
                {
                    int bar = line.IndexOf('|');
                    if (bar <= 0 || bar >= line.Length - 1) continue;
                    float d;
                    if (!float.TryParse(line.Substring(0, bar), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out d) || d <= 0.01f) continue;
                    durFast[Pool(line.Substring(bar + 1))] = d;
                }
            }
            catch { }
        }
        private void SaveDurFast()
        {
            List<string> nuevas;
            lock (durFastLock) { if (durFastPend.Count == 0) return; nuevas = new List<string>(durFastPend); durFastPend.Clear(); }
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    StringBuilder sb = new StringBuilder(nuevas.Count * 64 + 16);
                    for (int i = 0; i < nuevas.Count; i++) sb.Append(nuevas[i]).Append("\r\n");
                    lock (durFastLock) File.AppendAllText(DurFastFile(), sb.ToString());
                }
                catch { }
            });
        }

        // Barrido RAPIDO de duraciones: abre cada archivo, lee cuanto dura y lo suelta. No descomprime nada.
        // Se salta lo que ya tiene duracion (por esta via o por el analisis completo). Prioridad minima y un
        // respiro por archivo para no quitarle disco a la musica; con video en pantalla se detiene del todo.
        // ==========  LO QUE ENSENA LA BARRA DE LETRAS  ==========
        // Debajo de cada letra va cuantas canciones hay detras, y la letra se pinta del color del genero que
        // MANDA dentro de ella. Lo primero es gratis (ya esta contado); lo segundo cuesta leer el ID3 de toda
        // la biblioteca, asi que se calcula una vez en segundo plano y se guarda.
        private string LetterTintFile() { return RutaDatos("rocola_letras.txt"); }

        // Con que biblioteca se calcularon los colores. Si esto cambia, hay que volver a leer los generos.
        private int FirmaBiblioteca() { return tracks.Count * 31 + albums.Count; }

        // Arma los dos diccionarios ENTEROS y se los entrega a la barra de una pieza. La barra los lee desde
        // el dibujado, asi que nunca puede pillar uno a medio llenar: o ve el de antes, o ve el nuevo.
        // El orden de siempre, pero solo con las que tienen algo detras. Si no hubiera ninguna -biblioteca
        // vacia o a medio leer- se deja "#": la barra nunca se queda sin una sola casilla, que la dejaria sin
        // ancho por casilla y sin nada donde estar parado.
        private const string LetrasOrden = "\u2605#ABCDEFGHIJKLMNOPQRSTUVWXYZ\u25BA";
        private string LetrasVisibles()
        {
            StringBuilder sb = new StringBuilder(LetrasOrden.Length);
            for (int i = 0; i < LetrasOrden.Length; i++)
            {
                char c = LetrasOrden[i];
                if (letterAvailable == null || letterAvailable.Contains(c)) sb.Append(c);
            }
            return (sb.Length > 0) ? sb.ToString() : "#";
        }

        // LO ALTA QUE ES LA CAPSULA DE CREDITOS / EN COLA, que es lo mismo que decir LO GRANDE QUE SALE SU
        // LETRA: la capsula se dibuja con cuerpos de 0.34 y 0.52 de su alto. Estaba clavada en 26 px, o sea
        // que los creditos y la cola salian en letra mas chica que todo lo demas de la franja... siendo lo
        // que el cliente tiene que poder leer de lejos, desde la barra del local. Ahora sale del alto de la
        // tarjeta de lo que suena, asi que acompana al resto: en 1024x768 pasa de 26 a 35 px.
        private static int AltoPastilla(int tarjetaH) { return Math.Max(26, (int)(tarjetaH * 0.44f)); }

        private void RecalculaLetras()
        {
            if (letterBar == null) return;
            // Mientras se re-escanea, las listas son del worker y byLetter se esta REHACIENDO. Este aviso puede
            // llegar justo entonces (lo manda el paseo de fondo por BeginInvoke), asi que aqui no se mira nada:
            // al terminar el escaneo se recalcula de todos modos.
            if (libBuilding) return;
            Dictionary<char, int> cuenta = new Dictionary<char, int>();
            foreach (KeyValuePair<char, List<Album>> kv in byLetter)
            {
                List<Album> la = kv.Value;
                if (la == null) continue;
                int n = 0;
                for (int i = 0; i < la.Count; i++) if (la[i] != null && la[i].Tracks != null) n += la[i].Tracks.Count;
                if (n > 0) cuenta[kv.Key] = n;
            }
            if (videoAlbums != null && videoAlbums.Count > 0)
            {
                // El mismo video puede estar en dos discos: se cuenta una sola vez.
                HashSet<string> vistos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    if (va == null || va.VideoFiles == null) continue;
                    for (int j = 0; j < va.VideoFiles.Count; j++) if (va.VideoFiles[j] != null) vistos.Add(va.VideoFiles[j]);
                }
                if (vistos.Count > 0) cuenta[VideoMark] = vistos.Count;
            }
            if (topDiscs != null && topDiscs.Count > 0)
            {
                int nt = 0;
                for (int i = 0; i < topDiscs.Count; i++) if (topDiscs[i] != null && topDiscs[i].Tracks != null) nt += topDiscs[i].Tracks.Count;
                if (nt > 0) cuenta[TopMark] = nt;
            }
            Dictionary<char, Color> tinte = new Dictionary<char, Color>();
            foreach (KeyValuePair<char, string> kv in letterTag) tinte[kv.Key] = ColorDeEtiqueta(kv.Value);
            letterBar.Counts = cuenta;
            letterBar.Tints = tinte;
            // LAS LETRAS VACIAS NI SE DIBUJAN. Antes salian las 29 casillas siempre y las que no tenian nada
            // se pintaban apagadas: ocupaban su sitio para no decir nada. Ahora la barra solo lleva las que
            // tienen contenido, asi que las que quedan se reparten TODO el ancho: la casilla de cada una es
            // mas grande -mas facil de atinar con el dedo- y, cuando la barra va estrecha (con un video puesto
            // al lado), la letra misma tambien crece, porque ahi el cuerpo lo limitaba el ancho de la casilla.
            letterBar.Letters = LetrasVisibles();
            letterBar.Invalidate();
            if (searchOverlay != null) { searchOverlay.DatosVer++; if (searchOpen) searchOverlay.Invalidate(); }
            // El genero de cada cancion tambien se ensena DENTRO del disco. Como se aprende en segundo plano,
            // puede llegar con el disco ya abierto: sin esto, las pastillas no saldrian hasta salir y volver.
            generoVer++;
            ActualizaGenero();   // el genero de lo que suena tambien se aprende de fondo: que aparezca sin esperar
            if (panelSongs != null && panelSongs.Visible) RefrescaLista();
        }

        // Lee del disco el color de cada letra. Solo vale si se calculo con la MISMA biblioteca que hay ahora
        // (se compara el numero de canciones); si no, se descarta y se vuelve a calcular en segundo plano.
        private void LeeTintes(int firmaAhora)
        {
            letterTag.Clear(); discTag.Clear();
            tintesPend = true;
            try
            {
                string f = LetterTintFile();
                if (!File.Exists(f)) return;
                string[] L = File.ReadAllLines(f);
                // v1 solo tenia letras; v2 lleva ademas el genero de cada disco. Un archivo v1 se descarta y se
                // vuelve a calcular: es un paseo de fondo, no una perdida.
                if (L.Length < 2 || L[0] != "ROCOLA-LETRAS v2") return;
                int firma;
                if (!L[1].StartsWith("n=") || !int.TryParse(L[1].Substring(2), out firma)) return;
                if (firma != firmaAhora) return;   // la biblioteca cambio: hay que recalcular
                for (int i = 2; i < L.Length; i++)
                {
                    string ln = L[i];
                    if (ln.Length < 5) continue;
                    if (ln[0] == 'L' && ln[1] == '|' && ln[3] == '|') letterTag[ln[2]] = ln.Substring(4);
                    else if (ln[0] == 'D' && ln[1] == '|')
                    {
                        int b = ln.LastIndexOf('|');
                        if (b > 2) discTag[ln.Substring(2, b - 2)] = ln.Substring(b + 1);
                    }
                }
                tintesPend = false;
            }
            catch { letterTag.Clear(); discTag.Clear(); tintesPend = true; }
        }

        private void GuardaTintes(int firma)
        {
            Dictionary<char, string> copia = new Dictionary<char, string>(letterTag);
            Dictionary<string, string> copiaD = new Dictionary<string, string>(discTag, StringComparer.OrdinalIgnoreCase);
            string ruta = LetterTintFile();
            System.Threading.ThreadPool.QueueUserWorkItem(delegate (object st)
            {
                try
                {
                    StringBuilder sb = new StringBuilder(64 + copiaD.Count * 64);
                    sb.Append("ROCOLA-LETRAS v2\r\n").Append("n=").Append(firma).Append("\r\n");
                    foreach (KeyValuePair<char, string> kv in copia)
                        sb.Append("L|").Append(kv.Key).Append('|').Append(kv.Value).Append("\r\n");
                    // La carpeta puede llevar barras y espacios, pero NO un salto de linea: se parte por el
                    // ULTIMO separador, asi que una carpeta con "|" dentro tampoco rompe nada.
                    foreach (KeyValuePair<string, string> kv in copiaD)
                        sb.Append("D|").Append(kv.Key).Append('|').Append(kv.Value).Append("\r\n");
                    EscribeSeguro(ruta, sb.ToString());
                }
                catch { }
            });
        }

        // Lo que va encontrando el paseo de fondo: por cada letra, la etiqueta de genero que mas se repite.
        private void PublicaTintes(int gen, char[] letras, string[] etiquetas, string[] discos, string[] etDiscos, bool ultimo, int firma)
        {
            if (gen != durScanGen) return;
            for (int i = 0; i < letras.Length && i < etiquetas.Length; i++) letterTag[letras[i]] = etiquetas[i];
            for (int i = 0; i < discos.Length && i < etDiscos.Length; i++) discTag[discos[i]] = etDiscos[i];
            RecalculaGenerosArtista();   // con los generos de disco nuevos, los del artista cambian
            if (ultimo) { tintesPend = false; GuardaTintes(firma); }
            RecalculaLetras();
        }

        // El color de un disco: el genero que manda dentro de el. Si aun no se sabe, el de siempre.
        private Color ColorDisco(Album a)
        {
            string et;
            if (a != null && a.Folder != null && discTag.TryGetValue(a.Folder, out et)) return ColorDeEtiqueta(et);
            return DefaultAccent;
        }
        private string EtiquetaDisco(Album a)
        {
            string et;
            if (a != null && a.Folder != null && discTag.TryGetValue(a.Folder, out et)) return et;
            return "";
        }

        // ===================== DE QUE GENERO ES UNA CANCION =====================
        // Muchisimos MP3 vienen SIN etiqueta de genero. Antes, a esas canciones se les ensenaba el genero que
        // MANDA en su disco y, en cuanto sonaban, la pastilla cambiaba a "Otros": la lista decia una cosa y el
        // reproductor otra. Eso es lo que se veia en un disco de Black Eyed Peas -todas marcadas "Pop" y al
        // ponerlas, nada-.
        //
        // Ahora hay UNA sola respuesta, la misma en la lista del disco, en el buscador y al sonar, y se busca
        // en este orden, de lo mas seguro a lo mas adivinado:
        //
        //   1. LA ETIQUETA DE LA PROPIA CANCION. Si la trae, no hay nada que adivinar.
        //   2. EL DISCO. El genero que mas se repite entre las canciones del disco que SI la traen. Es la
        //      mejor pista que queda: las canciones de un mismo disco son del mismo genero casi siempre.
        //   3. EL ARTISTA. Si NINGUNA cancion del disco trae etiqueta pero otro disco del mismo artista si,
        //      ese vale. Sale GRATIS: se cuenta sobre los generos de disco que la rocola ya sabe, sin abrir
        //      ni un archivo mas ni guardar nada nuevo.
        //   4. EL NOMBRE. En una rocola de bar media biblioteca esta en carpetas que ya lo dicen: "Cumbias
        //      Mix", "Banda 2020", "Salsa Clasica", "Baladas Romanticas". Se leen el nombre del disco, su
        //      carpeta y la carpeta de encima. Es un recorrido de texto corto, hecho UNA vez por disco y
        //      guardado, asi que no vuelve a costar.
        //
        // Y si despues de los cuatro no hay nada, NO SE INVENTA: no sale pastilla. Mejor sin etiqueta que con
        // una etiqueta falsa.
        private readonly Dictionary<string, string> artistTag = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, string> nombreTag = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);   // carpeta -> lo que dice su NOMBRE (ya resuelto)

        private string GeneroDeCancion(Track tk, Album org)
        {
            string et;
            if (tk != null && tk.Path != null && songGenre.TryGetValue(tk.Path, out et) && et.Length > 0) return et;   // 1
            if (tk != null && !string.IsNullOrEmpty(tk.Genre)) { et = GenreLabel(tk.Genre); if (et != "Otros") return et; }
            if (org == null) return "";
            if (org.Folder != null && discTag.TryGetValue(org.Folder, out et) && et.Length > 0) return et;              // 2
            if (!string.IsNullOrEmpty(org.Artist) && artistTag.TryGetValue(org.Artist, out et) && et.Length > 0) return et;   // 3
            return GeneroPorNombre(org);                                                                                // 4
        }

        // Que genero se repite mas entre los DISCOS de cada artista. Se rehace cuando llegan votos nuevos del
        // paseo de fondo; cada disco pesa lo que canciones tiene, para que un disco suelto de dos temas no le
        // gane a uno de veinte.
        private void RecalculaGenerosArtista()
        {
            artistTag.Clear();
            if (libBuilding || discTag.Count == 0 || albums == null) return;   // 'albums' es del worker mientras se re-escanea
            Dictionary<string, Dictionary<string, int>> votos = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < albums.Count; i++)
            {
                Album a = albums[i];
                if (a == null || a.Folder == null || string.IsNullOrEmpty(a.Artist)) continue;
                string et;
                if (!discTag.TryGetValue(a.Folder, out et) || string.IsNullOrEmpty(et)) continue;
                int peso = (a.Tracks != null && a.Tracks.Count > 0) ? a.Tracks.Count : 1;
                Dictionary<string, int> vv;
                if (!votos.TryGetValue(a.Artist, out vv)) { vv = new Dictionary<string, int>(); votos[a.Artist] = vv; }
                int ya; vv.TryGetValue(et, out ya); vv[et] = ya + peso;
            }
            foreach (KeyValuePair<string, Dictionary<string, int>> kv in votos)
            {
                string mejor = null; int mejorN = 0;
                foreach (KeyValuePair<string, int> vv in kv.Value) if (vv.Value > mejorN) { mejorN = vv.Value; mejor = vv.Key; }
                if (mejor != null) artistTag[kv.Key] = mejor;
            }
        }

        // Palabras que dentro de un NOMBRE de carpeta o de disco casi solo pueden querer decir el genero. Se
        // comparan como PALABRA ENTERA a proposito: sin eso "Metallica" saldria de Metal, "Discoteca" de Disco
        // y "Poporopo" de Pop. Y quien traduce cada palabra a su etiqueta es GenreLabel, el mismo de siempre:
        // asi no hay dos listas de generos que se puedan desparejar (lo vigila la bateria 'genero').
        private static readonly string[] NombrePal = {
            "cumbia", "cumbias", "salsa", "salsas", "bachata", "bachatas", "merengue", "merengues",
            "reggaeton", "reguetón", "reggaetón", "banda", "bandas", "nortena", "nortenas", "norteña", "norteñas",
            "corrido", "corridos", "ranchera", "rancheras", "mariachi", "mariachis", "grupera", "gruperas",
            "duranguense", "sonidero", "sonideros", "tejano", "tejanas", "regional", "tropical", "tropicales",
            "balada", "baladas", "romantica", "romanticas", "romántica", "románticas", "bolero", "boleros",
            "tango", "tangos", "flamenco", "rumba", "rumbas", "reggae", "ska",
            "rock", "pop", "metal", "punk", "rap", "trap", "hip-hop", "hiphop", "jazz", "blues", "funk", "soul",
            "disco", "tecno", "techno", "trance", "electronica", "electrónica", "dance",
            "clasica", "clásica", "classical", "instrumental", "infantil", "infantiles", "gospel", "country",
            "chill", "oldies", "soundtrack",
            // Lo que se ve de verdad en las carpetas de una rocola de bar y no estaba: sin esto, una carpeta
            // llamada "Karaokes" o "Vallenatos" se quedaba sin genero y por tanto sin color.
            "karaoke", "karaokes", "navidad", "navidenas", "navideñas", "villancicos",
            "vallenato", "vallenatos", "quebradita", "quebraditas", "huapango", "huapangos",
            "sierreno", "sierreño", "zapateado", "guaracha", "guarachas", "mambo", "mambos",
            "danzon", "danzón", "marimba", "grupero", "gruperos", "samba", "sambas", "bossa"
        };

        private string GeneroPorNombre(Album a)
        {
            if (a == null || a.Folder == null) return "";
            string ya;
            if (nombreTag.TryGetValue(a.Folder, out ya)) return ya;
            string et = "";
            try
            {
                // El nombre del disco, su carpeta y la de encima ("...\Cumbias\Los Angeles Azules"). Nada mas
                // arriba: subiendo se llega a carpetas del sistema que no dicen nada de la musica.
                string carp = Path.GetFileName(a.Folder.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
                string padre = "";
                try { DirectoryInfo di = Directory.GetParent(a.Folder); if (di != null) padre = di.Name; }
                catch { }
                et = EnNombre(a.Name);
                if (et.Length == 0) et = EnNombre(carp);
                if (et.Length == 0) et = EnNombre(padre);
            }
            catch { }
            nombreTag[a.Folder] = et;
            return et;
        }

        private static string EnNombre(string texto)
        {
            if (string.IsNullOrEmpty(texto)) return "";
            string t = texto.ToLowerInvariant();
            for (int i = 0; i < NombrePal.Length; i++)
            {
                if (!PalabraEntera(t, NombrePal[i])) continue;
                string et = GenreLabel(NombrePal[i]);
                if (!string.IsNullOrEmpty(et) && et != "Otros") return et;
            }
            return "";
        }

        // "cumbia" dentro de "Cumbia Mix" SI; dentro de "Sacumbiado" NO. Se comprueba que a los dos lados NO
        // haya letra ni numero (o sea: espacio, guion, punto, barra, parentesis... o el principio/final).
        private static bool PalabraEntera(string t, string pal)
        {
            int p = t.IndexOf(pal, StringComparison.Ordinal);
            while (p >= 0)
            {
                bool izq = (p == 0) || !char.IsLetterOrDigit(t[p - 1]);
                int f = p + pal.Length;
                bool der = (f >= t.Length) || !char.IsLetterOrDigit(t[f]);
                if (izq && der) return true;
                p = t.IndexOf(pal, p + 1, StringComparison.Ordinal);
            }
            return false;
        }

        // Lo que le falta a UN archivo: su duracion, sus votos de genero, o las dos cosas. Sirve para
        // visitarlo una sola vez en vez de dos (ver StartDurScan).
        private sealed class Visita { public string Ruta; public bool Dur; public List<int> Gen; }

        private void StartDurScan()
        {
            int myGen = ++durScanGen;
            List<string> pend = new List<string>();
            for (int i = 0; i < tracks.Count; i++)
            {
                Track tk = tracks[i];
                if (tk == null || tk.Path == null) continue;
                if (durCache.ContainsKey(tk.Path) || durFast.ContainsKey(tk.Path)) continue;
                pend.Add(tk.Path);
            }
            // Y LOS VIDEOS. Entraban ya en la tanda, pero se intentaban medir con NAudio y ahi no habia nada
            // que hacer con un mp4 o un avi: se quedaban sin duracion igual. Ahora se miden por su camino
            // (ver MideDuracionVideo). Van al final, despues de la musica, porque cuestan bastante mas.
            int cuantasCanciones = pend.Count;
            if (videoAlbums != null)
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    if (va == null || va.VideoFiles == null) continue;
                    for (int j = 0; j < va.VideoFiles.Count; j++)
                    {
                        string vp = va.VideoFiles[j];
                        if (vp == null || durCache.ContainsKey(vp) || durFast.ContainsKey(vp)) continue;
                        if (!pend.Contains(vp)) pend.Add(vp);   // el mismo video puede estar en dos discos
                    }
                }
            if (pend.Count > cuantasCanciones) Diag("duraciones: " + (pend.Count - cuantasCanciones) + " videos por medir");
            durScanLeft = pend.Count;

            // EL COLOR DE LAS LETRAS. Si hay que calcularlo, se prepara aqui la lista de (letra, archivo) y el
            // paseo de fondo le lee el ID3 a cada uno DESPUES de las duraciones. Se leen con un Track SUELTO,
            // no con el de la biblioteca, para no tocar desde este hilo nada que la pantalla este usando.
            char[] gLet = null; string[] gRuta = null; string[] gDisco = null;
            int firmaLet = FirmaBiblioteca();
            if (tintesPend)
            {
                List<char> cl = new List<char>(tracks.Count);
                List<string> rl = new List<string>(tracks.Count);
                List<string> dl = new List<string>(tracks.Count);
                foreach (KeyValuePair<char, List<Album>> kv in byLetter)
                {
                    List<Album> la = kv.Value; if (la == null) continue;
                    for (int i = 0; i < la.Count; i++)
                    {
                        if (la[i] == null || la[i].Tracks == null) continue;
                        List<Track> tt = la[i].Tracks;
                        string carp = la[i].Folder ?? "";
                        for (int j = 0; j < tt.Count; j++)
                            if (tt[j] != null && tt[j].Path != null) { cl.Add(kv.Key); rl.Add(tt[j].Path); dl.Add(carp); }
                    }
                }
                if (cl.Count > 0) { gLet = cl.ToArray(); gRuta = rl.ToArray(); gDisco = dl.ToArray(); }
            }

            if (pend.Count == 0 && gLet == null) return;
            if (pend.Count > 0) Diag("duraciones: faltan " + pend.Count);
            if (gLet != null) Diag("generos: " + gLet.Length + " por leer (color de las letras)");
            // UNA SOLA PASADA POR EL DISCO. Antes se recorria la biblioteca DOS veces: primero todas las
            // duraciones y despues todos los generos, abriendo cada archivo dos veces y en dos momentos
            // distintos, asi que el cabezal del disco hacia el viaje completo dos veces. Ahora se arma una
            // lista con lo que le falta a cada archivo y se visita UNA sola vez. Y se recorre ORDENADA POR
            // RUTA, que en un disco duro es la diferencia entre avanzar en linea recta y dar saltos: los
            // archivos de una misma carpeta estan juntos en el plato.
            Dictionary<string, Visita> mapa = new Dictionary<string, Visita>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < pend.Count; i++)
            {
                Visita v;
                if (!mapa.TryGetValue(pend[i], out v)) { v = new Visita(); v.Ruta = pend[i]; mapa[pend[i]] = v; }
                v.Dur = true;
            }
            if (gLet != null)
                for (int i = 0; i < gLet.Length; i++)
                {
                    Visita v;
                    if (!mapa.TryGetValue(gRuta[i], out v)) { v = new Visita(); v.Ruta = gRuta[i]; mapa[gRuta[i]] = v; }
                    if (v.Gen == null) v.Gen = new List<int>(1);
                    v.Gen.Add(i);   // el mismo archivo puede votar por varias letras: se lee UNA vez y vota todas
                }
            List<Visita> visitas = new List<Visita>(mapa.Count);
            foreach (Visita v in mapa.Values) visitas.Add(v);
            visitas.Sort(delegate (Visita a, Visita b) { return string.CompareOrdinal(a.Ruta, b.Ruta); });
            // El total de duraciones se cuenta sobre las VISITAS, no sobre la lista de entrada: si un mismo
            // archivo estaba dos veces (el mismo video en dos discos, por ejemplo) se visita una sola, y si
            // aqui se pusiera el numero de entradas el contador de "faltan" no llegaria nunca a cero.
            int durTotal = 0;
            for (int i = 0; i < visitas.Count; i++) if (visitas[i].Dur) durTotal++;
            int genTotal = (gLet != null) ? gLet.Length : 0;

            durScanTh = new System.Threading.Thread(delegate ()
            {
                List<string> lote = new List<string>(128);
                List<float> lotd = new List<float>(128);
                object medidorVideo = null;   // el reproductor con el que se miden los videos (de este hilo)
                Dictionary<char, Dictionary<string, int>> votos = new Dictionary<char, Dictionary<string, int>>();
                Dictionary<string, Dictionary<string, int>> votosD = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);
                int durHechas = 0, genHechas = 0;
                try
                {
                    System.Threading.Thread.Sleep(4000);   // deja respirar el arranque
                    for (int i = 0; i < visitas.Count; i++)
                    {
                        if (preScanStop || myGen != durScanGen) break;
                        while (!preScanStop && myGen == durScanGen && videoOn) System.Threading.Thread.Sleep(500);
                        if (preScanStop || myGen != durScanGen) break;
                        Visita v = visitas[i];
                        bool caro = false;   // hubo que leer el archivo entero (el respaldo), no solo la cabecera

                        // ---- LA DURACION ----
                        if (v.Dur)
                        {
                            float seg;
                            if (EsVideo(v.Ruta)) { seg = MideDuracionVideo(v.Ruta, ref medidorVideo); caro = true; }
                            else
                            {
                                seg = DuracionPorCabecera(v.Ruta);            // unos kilobytes
                                if (seg <= 0.01f) { seg = MideDuracionAudio(v.Ruta); caro = true; }   // respaldo: el archivo entero
                            }
                            if (seg > 0.01f) { lote.Add(v.Ruta); lotd.Add(seg); }
                            durHechas++;
                            // Se publica cada 128 archivos o al terminar, TAMBIEN si el lote viene vacio: un
                            // archivo roto no da duracion pero SI es avance; sin esto, el contador de "faltan"
                            // se quedaria clavado para siempre en el numero de archivos danados.
                            if (lote.Count >= 128 || durHechas >= durTotal)
                            {
                                string[] rr = lote.ToArray(); float[] dd = lotd.ToArray();
                                lote.Clear(); lotd.Clear();
                                int faltan = durTotal - durHechas;
                                try
                                {
                                    if (!IsHandleCreated) break;
                                    BeginInvoke((MethodInvoker)delegate { PublicaDuraciones(myGen, rr, dd, faltan); });
                                }
                                catch { break; }
                            }
                        }

                        // ---- EL GENERO, que es lo que da color a cada letra de la barra de arriba ----
                        // Se lee la etiqueta UNA vez por archivo, aunque vote por varias letras. Con un Track
                        // SUELTO, no con el de la biblioteca, para no tocar desde este hilo nada que la pantalla
                        // este usando.
                        if (v.Gen != null)
                        {
                            string et = "Otros";
                            try
                            {
                                string gg = Track.SoloGenero(v.Ruta);   // como mucho 32 KB, no la etiqueta entera
                                if (gg.Length > 0) et = GenreLabel(gg);
                            }
                            catch { }
                            for (int k = 0; k < v.Gen.Count; k++)
                            {
                                int gi = v.Gen[k];
                                Dictionary<string, int> vv2;
                                if (!votos.TryGetValue(gLet[gi], out vv2)) { vv2 = new Dictionary<string, int>(); votos[gLet[gi]] = vv2; }
                                int ya; vv2.TryGetValue(et, out ya); vv2[et] = ya + 1;
                                string carp = gDisco[gi];
                                if (carp.Length > 0)
                                {
                                    Dictionary<string, int> vd;
                                    if (!votosD.TryGetValue(carp, out vd)) { vd = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase); votosD[carp] = vd; }
                                    int yd; vd.TryGetValue(et, out yd); vd[et] = yd + 1;
                                }
                                genHechas++;
                            }
                            // Se publica cada 256 votos, y por eso la barra se va tinendo poco a poco en vez de
                            // cambiar de golpe al final.
                            bool finGen = (genHechas >= genTotal);
                            if ((genHechas & 255) < v.Gen.Count || finGen)
                            {
                                // El genero que MANDA en cada letra hasta ahora. "Otros" no gana nunca: una
                                // letra cuyas canciones no traen genero se queda con su blanco de siempre, que
                                // es mas honesto que pintarla del color de "no se sabe".
                                List<char> kl = new List<char>(); List<string> vl = new List<string>();
                                foreach (KeyValuePair<char, Dictionary<string, int>> kv in votos)
                                {
                                    string mejor = null; int mejorN = 0;
                                    foreach (KeyValuePair<string, int> vv in kv.Value)
                                        if (vv.Key != "Otros" && vv.Value > mejorN) { mejorN = vv.Value; mejor = vv.Key; }
                                    if (mejor != null) { kl.Add(kv.Key); vl.Add(mejor); }
                                }
                                // Lo mismo para los discos, que es lo que le da color a los resultados del buscador.
                                List<string> dk = new List<string>(); List<string> dv = new List<string>();
                                foreach (KeyValuePair<string, Dictionary<string, int>> kv in votosD)
                                {
                                    string mejor = null; int mejorN = 0;
                                    foreach (KeyValuePair<string, int> vv in kv.Value)
                                        if (vv.Key != "Otros" && vv.Value > mejorN) { mejorN = vv.Value; mejor = vv.Key; }
                                    if (mejor != null) { dk.Add(kv.Key); dv.Add(mejor); }
                                }
                                char[] ka = kl.ToArray(); string[] va = vl.ToArray(); bool ult = finGen;
                                string[] dka = dk.ToArray(); string[] dva = dv.ToArray();
                                try
                                {
                                    if (!IsHandleCreated) break;
                                    BeginInvoke((MethodInvoker)delegate { PublicaTintes(myGen, ka, va, dka, dva, ult, firmaLet); });
                                }
                                catch { break; }
                            }
                        }

                        // EL RESPIRO va con el trabajo que se acaba de hacer. Leer una cabecera son unos
                        // kilobytes: con 4 ms de pausa el disco queda MUCHO mas libre que antes con 12, porque
                        // antes cada archivo se leia entero. Si hubo que leerlo entero (el respaldo, o un
                        // video), se respira lo de siempre.
                        //
                        // Y EN SSD el respiro se JUNTA. Dormir 1 ms por archivo parece nada, pero en una
                        // biblioteca de cien mil canciones son casi dos minutos de puro dormir, y un SSD no
                        // necesita que se le deje descansar entre lectura y lectura: no hay cabezal que se
                        // recaliente. Se respira una vez cada 32 archivos -lo justo para que la interfaz tenga
                        // su turno, que para eso este hilo va ademas en la prioridad mas baja- y el repaso
                        // termina en una fraccion del tiempo. Si hubo que leer el archivo entero, se respira
                        // igual: eso si le cuesta al disco, tenga cabezal o no.
                        // Y el respiro va por el disco donde este ESTE archivo, no por un veredicto general:
                        // con la musica repartida entre un SSD y un disco duro, cada archivo se trata como
                        // merece el suyo (ver DiscoLento).
                        if (DiscoLento(v.Ruta)) System.Threading.Thread.Sleep(caro ? 12 : 4);
                        else if (caro || (i & 31) == 31) System.Threading.Thread.Sleep(1);
                    }
                }
                catch { }
                finally { SueltaMedidorVideo(ref medidorVideo); }   // el objeto COM se crea y se suelta en ESTE hilo, que es el STA
            });
            durScanTh.IsBackground = true;
            durScanTh.Priority = System.Threading.ThreadPriority.Lowest;
            // El reproductor de Windows es un objeto COM y solo se deja usar desde un hilo STA. Sin esto, la
            // duracion de los videos no se podria medir aqui.
            try { durScanTh.SetApartmentState(System.Threading.ApartmentState.STA); } catch { }
            durScanTh.Start();
        }
        private static bool EsVideo(string ruta)
        {
            if (ruta == null) return false;
            string ext = null;
            try { ext = Path.GetExtension(ruta).ToLowerInvariant(); } catch { }
            return ext != null && Array.IndexOf(VideoExt, ext) >= 0;
        }

        // Cuanto dura un archivo de MUSICA: lo abre, lee la cabecera y lo suelta. No descomprime nada.
        // CUANTO DURA UN MP3 SIN LEERLO ENTERO.
        //
        // Preguntarle la duracion a NAudio obliga a recorrer el archivo COMPLETO: va frame a frame, de
        // principio a fin, armando su indice. Para saber cuanto dura una cancion de 5 MB hay que leer los 5 MB.
        // Con veinte mil canciones eso son CIEN GIGAS de lectura, y en un disco duro mecanico es media hora de
        // cabezal trabajando: por eso el pre-analisis tardaba tanto y por eso molestaba mientras suena musica.
        //
        // Pero la duracion viene escrita en la CABECERA. Casi todos los MP3 traen una etiqueta Xing/Info (o
        // VBRI) con el numero EXACTO de frames, y los de tasa fija se resuelven con una division. En los dos
        // casos basta leer los primeros kilobytes. Si el archivo no trae ninguna de las dos cosas -o algo no
        // cuadra- se devuelve 0 y quien llama recurre al metodo lento de siempre: nunca se pierde una duracion.
        private static readonly int[] BrMpeg1 = { 0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 0 };
        private static readonly int[] BrMpeg2 = { 0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160, 0 };
        private static readonly int[] SrMpeg1 = { 44100, 48000, 32000, 0 };
        private static readonly int[] SrMpeg2 = { 22050, 24000, 16000, 0 };
        private static readonly int[] SrMpeg25 = { 11025, 12000, 8000, 0 };
        private static float DuracionPorCabecera(string ruta)
        {
            try
            {
                if (Path.GetExtension(ruta).ToLowerInvariant() != ".mp3") return 0f;   // solo MP3; el resto, por el camino lento
                using (FileStream fs = new FileStream(ruta, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 4096))
                {
                    long largo = fs.Length;
                    if (largo < 256) return 0f;
                    byte[] cab = new byte[10];
                    if (fs.Read(cab, 0, 10) != 10) return 0f;
                    // 1) LA ETIQUETA DE TEXTO del principio (ID3v2), que puede llevar dentro la caratula y
                    //    medir cientos de kilobytes. Su tamano viene en la propia cabecera: se salta de golpe.
                    long ini = 0;
                    if (cab[0] == (byte)'I' && cab[1] == (byte)'D' && cab[2] == (byte)'3')
                    {
                        // El tamano va en 4 bytes de 7 bits (el bit alto de cada uno no cuenta).
                        int tam = ((cab[6] & 0x7F) << 21) + ((cab[7] & 0x7F) << 14)
                                + ((cab[8] & 0x7F) << 7) + (cab[9] & 0x7F);
                        ini = 10 + tam;
                        if ((cab[5] & 0x10) != 0) ini += 10;   // con pie de etiqueta, diez bytes mas
                        if (ini <= 0 || ini >= largo) return 0f;
                    }
                    // 2) EL PRIMER FRAME. Se leen unos kilobytes desde ahi y se busca la marca de sincronismo.
                    //    Se tolera basura por delante (hay archivos con relleno entre la etiqueta y el audio).
                    fs.Position = ini;
                    byte[] buf = new byte[8192];
                    int n = fs.Read(buf, 0, buf.Length);
                    if (n < 64) return 0f;
                    for (int i = 0; i + 4 <= n; i++)
                    {
                        if (buf[i] != 0xFF || (buf[i + 1] & 0xE0) != 0xE0) continue;
                        int verBits = (buf[i + 1] >> 3) & 3;      // 3=MPEG1  2=MPEG2  0=MPEG2.5  (1 no existe)
                        int capa = (buf[i + 1] >> 1) & 3;         // 1 = capa III
                        if (verBits == 1 || capa != 1) continue;
                        int iBr = (buf[i + 2] >> 4) & 15, iSr = (buf[i + 2] >> 2) & 3;
                        int pad = (buf[i + 2] >> 1) & 1, modo = (buf[i + 3] >> 6) & 3;
                        bool mpeg1 = (verBits == 3);
                        int br = (mpeg1 ? BrMpeg1[iBr] : BrMpeg2[iBr]) * 1000;
                        int sr = mpeg1 ? SrMpeg1[iSr] : (verBits == 2 ? SrMpeg2[iSr] : SrMpeg25[iSr]);
                        if (br <= 0 || sr <= 0) continue;          // valores reservados: no era un frame
                        int porFrame = mpeg1 ? 1152 : 576;         // muestras que trae cada frame
                        bool mono = (modo == 3);
                        // 3) LA CUENTA EXACTA DE FRAMES, si el archivo la trae. Va justo detras de la
                        //    informacion lateral del primer frame, cuyo tamano depende de version y canales.
                        int lado = mpeg1 ? (mono ? 17 : 32) : (mono ? 9 : 17);
                        int xi = i + 4 + lado;
                        if (xi + 12 <= n)
                        {
                            bool xing = (buf[xi] == (byte)'X' && buf[xi + 1] == (byte)'i' && buf[xi + 2] == (byte)'n' && buf[xi + 3] == (byte)'g')
                                     || (buf[xi] == (byte)'I' && buf[xi + 1] == (byte)'n' && buf[xi + 2] == (byte)'f' && buf[xi + 3] == (byte)'o');
                            if (xing && (buf[xi + 7] & 1) != 0)
                            {
                                long frames = ((long)buf[xi + 8] << 24) + ((long)buf[xi + 9] << 16) + ((long)buf[xi + 10] << 8) + buf[xi + 11];
                                if (frames > 0)
                                {
                                    double seg = (double)frames * porFrame / sr;
                                    if (seg > 0.05 && seg < 36000) return (float)seg;
                                }
                            }
                        }
                        int vi = i + 4 + 32;   // VBRI (Fraunhofer) va siempre a 32 bytes del frame
                        if (vi + 18 <= n && buf[vi] == (byte)'V' && buf[vi + 1] == (byte)'B' && buf[vi + 2] == (byte)'R' && buf[vi + 3] == (byte)'I')
                        {
                            long frames = ((long)buf[vi + 14] << 24) + ((long)buf[vi + 15] << 16) + ((long)buf[vi + 16] << 8) + buf[vi + 17];
                            if (frames > 0)
                            {
                                double seg = (double)frames * porFrame / sr;
                                if (seg > 0.05 && seg < 36000) return (float)seg;
                            }
                        }
                        // 4) SIN ETIQUETA: si el archivo es de tasa FIJA la cuenta es una division. Se comprueba
                        //    que el frame siguiente cae donde debe y trae la misma tasa; si no, puede ser de tasa
                        //    variable sin etiqueta y ahi no se puede adivinar: que lo mida el camino lento.
                        int tamFrame = (mpeg1 ? 144 : 72) * br / sr + pad;
                        if (tamFrame < 24) continue;
                        int sig = i + tamFrame;
                        if (sig + 4 > n) return 0f;
                        if (buf[sig] != 0xFF || (buf[sig + 1] & 0xE0) != 0xE0) return 0f;
                        if (((buf[sig + 2] >> 4) & 15) != iBr) return 0f;   // otra tasa -> variable sin etiqueta
                        long fin = largo;
                        // La etiqueta de texto del FINAL (ID3v1) son 128 bytes que no son audio.
                        if (largo > 128 + ini)
                        {
                            fs.Position = largo - 128;
                            byte[] tres = new byte[3];
                            if (fs.Read(tres, 0, 3) == 3 && tres[0] == (byte)'T' && tres[1] == (byte)'A' && tres[2] == (byte)'G') fin = largo - 128;
                        }
                        long audio = fin - (ini + i);
                        if (audio <= 0) return 0f;
                        double s2 = (double)audio * 8.0 / br;
                        if (s2 > 0.05 && s2 < 36000) return (float)s2;
                        return 0f;
                    }
                }
            }
            catch { }
            return 0f;
        }

        // ABRIR UN MP3 SIN DEJAR NADA COLGANDO.
        //
        // NAudio arma el descompresor de MP3 -que por dentro es un "stream" de ACM, del sistema- y JUSTO
        // DESPUES reserva su buffer y termina de prepararse. Si algo falla en ese hueco -una cabecera rota, un
        // tamano absurdo, y de esos hay unos cuantos en cualquier biblioteca grande- suelta el error y cierra
        // el archivo, pero NO cierra el descompresor: se queda tirado. Un rato despues el recolector de basura
        // lo cierra por su cuenta, Windows contesta que ese descompresor ya no vale, y NAudio lanza la queja
        // desde el hilo del recolector, donde NADIE la puede recoger: la rocola se cierra entera, a media
        // cancion. Eso es lo que quedaba apuntado en el archivo de errores como "InvalidParameter calling
        // acmStreamClose", y por eso salia dos veces en diez dias y siempre de madrugada: es cuando el repaso
        // de la biblioteca abre miles de archivos, alguno de ellos roto.
        //
        // NAudio deja un gancho para armar el descompresor uno mismo. Se usa para apuntar CUAL creo: si la
        // apertura falla, lo cerramos NOSOTROS ahi mismo y no queda nada pendiente para el recolector.
        private static Mp3FileReader AbreMp3(string ruta)
        {
            NAudio.Wave.IMp3FrameDecompressor hecho = null;
            Mp3FileReader.FrameDecompressorBuilder armador = delegate(NAudio.Wave.WaveFormat wf)
            { hecho = Mp3FileReader.CreateAcmFrameDecompressor(wf); return hecho; };
            try { return new Mp3FileReader(ruta, armador); }
            catch { if (hecho != null) { try { hecho.Dispose(); } catch { } } throw; }
        }

        // Lector para MEDIR una cancion (no para que suene). Los MP3 van por el camino de arriba, que no deja
        // descompresores tirados; el resto de formatos, por donde siempre. Es EL MISMO montaje que usa NAudio
        // por dentro (el lector mas un canal de muestras), asi que lo medido no cambia ni en un bit.
        private sealed class LectorMedida : IDisposable
        {
            private readonly Mp3FileReader mp3;
            private readonly SampleChannel canal;
            private readonly AudioFileReader otro;
            public LectorMedida(string ruta)
            {
                if (ruta != null && ruta.EndsWith(".mp3", StringComparison.OrdinalIgnoreCase))
                {
                    Mp3FileReader r = AbreMp3(ruta);
                    try { canal = new SampleChannel(r, false); mp3 = r; r = null; }
                    finally { if (r != null) { try { r.Dispose(); } catch { } } }   // el canal fallo: el lector no se queda tirado
                }
                else otro = new AudioFileReader(ruta);
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return (mp3 != null) ? canal.WaveFormat : otro.WaveFormat; } }
            public TimeSpan TotalTime { get { return (mp3 != null) ? mp3.TotalTime : otro.TotalTime; } }
            public TimeSpan CurrentTime { set { if (mp3 != null) mp3.CurrentTime = value; else otro.CurrentTime = value; } }
            public float Volume { set { if (mp3 != null) canal.Volume = value; else otro.Volume = value; } }
            public int Read(float[] b, int o, int c) { return (mp3 != null) ? canal.Read(b, o, c) : otro.Read(b, o, c); }
            public void Dispose()
            {
                if (mp3 != null) { try { mp3.Dispose(); } catch { } }
                if (otro != null) { try { otro.Dispose(); } catch { } }
            }
        }

        private static float MideDuracionAudio(string ruta)
        {
            // Primero por la cabecera (unos kilobytes). Solo si eso no da nada se lee el archivo entero.
            float rapida = DuracionPorCabecera(ruta);
            if (rapida > 0.01f) return rapida;
            try
            {
                using (LectorMedida rd = new LectorMedida(ruta))
                {
                    double t = rd.TotalTime.TotalSeconds;
                    if (t > 0.05 && t < 36000) return (float)t;
                }
            }
            catch { }
            return 0f;
        }

        // Cuanto dura un VIDEO. NAudio no sabe abrir un mp4 ni un avi, asi que se le pregunta a quien SI sabe
        // y ademas ya esta en la maquina: el reproductor de Windows, el mismo que la rocola usa para poner los
        // videos. Se le pide un objeto SUELTO (no el de la pantalla, que estaria reproduciendo) y se le manda
        // "abre este archivo y dime cuanto dura" -newMedia-, que lee la cabecera SIN reproducir nada.
        //
        // La duracion no siempre esta lista en el mismo instante: el reproductor la va rellenando mientras
        // reconoce el archivo. Por eso se le da un momento, mirando de tanto en tanto, y si en tres segundos no
        // contesta se deja pasar (ese video se queda sin duracion, como estaba antes, y no se cuelga nada).
        // El medidor se crea UNA vez por tanda y lo lleva el propio hilo (por eso va por referencia y no en un
        // campo): crearlo por archivo seria carisimo, y tenerlo en un campo compartido se cruzaria con la tanda
        // siguiente si alguien vuelve a escanear la biblioteca mientras esta corre.
        private float MideDuracionVideo(string ruta, ref object wmpMedidor)
        {
            try
            {
                if (wmpMedidor == null)
                {
                    Type t = Type.GetTypeFromProgID("WMPlayer.OCX.7");
                    if (t == null) t = Type.GetTypeFromProgID("WMPlayer.OCX");
                    if (t == null) return 0f;                       // sin reproductor de Windows: no se puede medir
                    wmpMedidor = Activator.CreateInstance(t);
                    try { Set(wmpMedidor, "uiMode", "none"); } catch { }
                    try { object s2 = Get(wmpMedidor, "settings"); if (s2 != null) { Set(s2, "autoStart", false); Set(s2, "volume", 0); } } catch { }
                }
                object media = Call(wmpMedidor, "newMedia", ruta);
                if (media == null) return 0f;
                try
                {
                    for (int intento = 0; intento < 30; intento++)   // hasta ~3 s, mirando cada 100 ms
                    {
                        double d = 0;
                        try { object o = Get(media, "duration"); if (o != null) d = Convert.ToDouble(o); } catch { }
                        if (d > 0.05 && d < 36000) return (float)d;
                        if (preScanStop) break;
                        // El reproductor puede tardar en rellenar la duracion, y cuando lo hace avisa por la
                        // cola de mensajes de ESTE hilo. Si nadie la vacia, el aviso no llega nunca y todos los
                        // videos se irian por el tope de tres segundos sin duracion. Este hilo no tiene ventanas
                        // propias, asi que vaciarla aqui no puede repintar ni disparar nada de la rocola.
                        try { Application.DoEvents(); } catch { }
                        System.Threading.Thread.Sleep(100);
                    }
                }
                finally { try { System.Runtime.InteropServices.Marshal.ReleaseComObject(media); } catch { } }
            }
            catch { }
            return 0f;
        }
        private static void SueltaMedidorVideo(ref object wmpMedidor)
        {
            object w = wmpMedidor; wmpMedidor = null;
            if (w == null) return;
            try { Call(w, "close"); } catch { }
            try { System.Runtime.InteropServices.Marshal.ReleaseComObject(w); } catch { }
        }

        // Corre en el hilo de la interfaz: las tablas son suyas. "faltan" es el avance ABSOLUTO que reporta el
        // hilo (cuenta tambien los archivos rotos, que no traen duracion pero ya quedaron atras).
        private void PublicaDuraciones(int gen, string[] rutas, float[] segs, int faltan)
        {
            if (gen != durScanGen) return;   // generacion caducada (hubo re-escaneo): descartar
            for (int i = 0; i < rutas.Length; i++)
            {
                if (durFast.ContainsKey(rutas[i])) continue;
                durFast[rutas[i]] = segs[i];
                lock (durFastLock) durFastPend.Add(segs[i].ToString("0.##", System.Globalization.CultureInfo.InvariantCulture) + "|" + rutas[i]);
            }
            durScanLeft = faltan < 0 ? 0 : faltan;
            SaveDurFast();
            if (rutas.Length > 0 && panelSongs != null && panelSongs.Visible && songList != null)
            {
                RefrescaLista();
#if ROCOLA_GPU
                uiOverlaySig = SigNada;   // la lista va horneada en la textura de UI: hay que rehacerla para que se vean
#endif
            }
        }

        private const double PreSegSec = 20.0;    // duracion de cada tramo analizado
        private const int PreSegs = 3;            // cuantos tramos por cancion (repartidos por el tema)
        // QUE HAY QUE MEDIR. Devuelve la tanda -las canciones y los videos que aun no tienen medida- y, por
        // "elegibles", cuantos archivos de la biblioteca cuentan para la barra de avance del repaso a fondo.
        // EN QUE ORDEN CONVIENE MEDIR.
        //
        // Medir una cancion cuesta descomprimirla entera: 550 ms por minuto de cancion, unos 2.2 segundos
        // por cada una de cuatro minutos. Una biblioteca de 3000 son casi dos horas de trabajo, y en la
        // maquina del bar bastante mas. Recorrerla EN EL ORDEN EN QUE ESTA significa pasar noches midiendo
        // discos que nadie ha puesto nunca mientras las cinco que suenan cada viernes siguen sin nivelar y
        // sin poder decir los minutos que faltan.
        //
        // El trabajo total es el mismo. Lo que cambia es CUANDO llega el beneficio: primero lo que esta
        // pedido ahora mismo, luego lo mas sonado, luego lo mas reciente, y al final lo demas.
        //
        // Y EL ULTIMO DESEMPATE ES EL SITIO QUE OCUPABA, que no es un detalle: en .NET 3.5 List.Sort no es
        // estable, asi que sin el, dos canciones con los mismos numeros saldrian hoy en un orden y manana
        // en otro y el pre-analisis empezaria cada vez por un sitio distinto, en vez de continuar por
        // donde iba. Pura a proposito: recibe las listas, asi se le pueden dar casos a mano.
        internal static void OrdenaPorUso(List<string> pend, Dictionary<string, int> veces,
                                          Dictionary<string, long> recientes, HashSet<string> enCola)
        {
            if (pend == null || pend.Count < 2) return;
            int n = pend.Count;
            string[] ruta = pend.ToArray();
            int[] idx = new int[n];
            int[] cola = new int[n];
            int[] vez = new int[n];
            long[] rec = new long[n];
            for (int i = 0; i < n; i++)
            {
                idx[i] = i;
                string k = ruta[i];
                cola[i] = (enCola != null && k != null && enCola.Contains(k)) ? 0 : 1;
                int v = 0; if (veces != null && k != null) veces.TryGetValue(k, out v); vez[i] = v;
                long r = 0; if (recientes != null && k != null) recientes.TryGetValue(k, out r); rec[i] = r;
            }
            Array.Sort(idx, delegate (int a, int b)
            {
                if (cola[a] != cola[b]) return cola[a] - cola[b];          // lo pedido ahora mismo, primero
                if (vez[a] != vez[b]) return (vez[b] > vez[a]) ? 1 : -1;   // luego lo mas sonado
                if (rec[a] != rec[b]) return (rec[b] > rec[a]) ? 1 : -1;   // empatadas, la que sono hace menos
                return a - b;                                             // y si todo empata, como estaba
            });
            for (int i = 0; i < n; i++) pend[i] = ruta[idx[i]];
        }

        // APUNTAR LO QUE SE ACABA DE MEDIR. UN SOLO SITIO, y por eso vive aqui suelto: lo llaman el
        // pre-analisis y el calentador de la siguiente cancion. Con dos sitios que escriban las mismas tres
        // tablas, el dia que alguien arregle uno se olvidara del otro.
        //
        // SOBRESCRIBE lo que hubiera: estas medidas son de la cancion COMPLETA, asi que son mejores que lo
        // aprendido a medias oyendola (que promediaba entre pasadas).
        //
        // Las tablas son del hilo de la pantalla y no llevan candado -a proposito, para no pagarlo en cada
        // consulta-, asi que quien llame a esto tiene que estar EN ese hilo.
        private void PublicaMedida(string ruta, float rms, float dur, float[] eqCurve)
        {
            if (ruta == null) return;
            if (dur > 0.01f) durCache[ruta] = dur;
            if (rms > 0f) loudCache[ruta] = rms;   // incluido el silencio (ver LoudMudo)
            if (eqCurve != null) { eqCache[ruta] = eqCurve; eqCacheVer++; eqDirty = true; }   // huella tonal del EQ automatico
            if (panelSongs != null && panelSongs.Visible) RefrescaLista();   // que aparezca la duracion recien sabida
        }

        private List<string> TandaPorMedir(bool turbo, out int elegibles)
        {
            List<string> pend = new List<string>();
            elegibles = 0;
            for (int i = 0; i < tracks.Count; i++)
            {
                Track tk = tracks[i];
                if (tk == null || tk.Path == null) continue;
                // En modo NORMAL se salta lo ya medido. En ENTRENAMIENTO A FONDO entra toda la biblioteca MENOS
                // lo que ya recibio su repaso completo: asi, al detenerlo y volverlo a encender (o tras un apagon)
                // CONTINUA donde iba en vez de empezar por la primera cancion otra vez.
                elegibles++;
                if (!turbo && durCache.ContainsKey(tk.Path)) continue;
                if (turbo) { bool ya; lock (deepDoneLock) ya = deepDone.Contains(tk.Path); if (ya) continue; }
                pend.Add(tk.Path);
            }
            // Y LOS VIDEOS. No estaban: 'tracks' solo lleva canciones, los videos viven aparte (VideoFiles de
            // cada disco). Sin medirlos, el nivelado de los videos no tenia NADA con que trabajar y cada uno
            // sonaba con el volumen que trajera de fabrica: unos bien, otros tan bajos que casi no se oian.
            // Van al final de la tanda, despues de la musica, que es lo que mas se usa.
            //
            // Windows XP no puede hacerlo: el sonido de un mp4 lo descomprime Media Foundation, que llego con
            // Vista. Alli los primeros videos fallan al abrirse y el hilo del repaso deja de intentarlo.
            int cuantosVideos = 0;
            if (videoAlbums != null)
            {
                HashSet<string> vistos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);   // el mismo video puede estar en dos discos
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    if (va == null || va.VideoFiles == null) continue;
                    for (int j = 0; j < va.VideoFiles.Count; j++)
                    {
                        string vp = va.VideoFiles[j];
                        if (vp == null || !vistos.Add(vp)) continue;
                        if (!turbo && loudCache.ContainsKey(vp)) continue;
                        if (turbo) { bool ya; lock (deepDoneLock) ya = deepDone.Contains(vp); if (ya) continue; }
                        pend.Add(vp); cuantosVideos++;
                    }
                }
                elegibles += vistos.Count;
            }
            if (cuantosVideos > 0) Diag("nivelado: " + cuantosVideos + " videos por medir");

            // Y AHORA EL ORDEN, que es donde esta la ganancia (ver OrdenaPorUso). La rocola ya sabe lo que
            // se pone en este bar: lo lleva apuntado para la lista de "Lo mas sonado". Aqui se le pregunta.
            //
            // Las tablas se miran SOLO por las canciones de esta tanda y no al reves: con cien mil canciones
            // apuntadas, copiar las tablas enteras para ordenar unos cuantos miles seria trabajo de mas.
            HashSet<string> enCola = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < queue.Count; i++)
            {
                PlayItem it = queue[i];
                if (it == null) continue;
                string k = it.PathKey();
                if (k.Length > 0) enCola.Add(k);
            }
            Dictionary<string, int> veces = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            Dictionary<string, long> recientes = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < pend.Count; i++)
            {
                string k = pend[i];
                if (k == null || veces.ContainsKey(k)) continue;
                int v; long q;
                // Las canciones van en una tabla y los videos en otra, pero aqui vienen revueltos en la
                // misma tanda: se pregunta en las dos.
                if (songCounts.TryGetValue(k, out v) || videoCounts.TryGetValue(k, out v)) veces[k] = v;
                if (songSeq.TryGetValue(k, out q) || videoSeq.TryGetValue(k, out q)) recientes[k] = q;
            }
            OrdenaPorUso(pend, veces, recientes, enCola);
            return pend;
        }

        // ¿ESTA SOLA LA ROCOLA? En modo atraccion (a los 40 s sin que nadie toque un boton), sin nada
        // sonando y sin ningun video puesto. Es el rato en que no hay nadie eligiendo, no hay pared de
        // discos que dibujar -solo el cubo gigante- y no hay musica a la que no se le pueda fallar.
        private bool RocolaSola() { return attractOn && nowPlaying == null && !videoOn; }

        // CUANTOS CARRILES LE TOCAN AL PRE-ANALISIS.
        //
        // Antes usaba UNO siempre, salvo en el repaso a fondo que se enciende a mano: en una maquina de
        // ocho nucleos, un nucleo de ocho, tambien a las cuatro de la manana con el bar cerrado. Ahora
        // tambien se sueltan cuando la rocola esta SOLA.
        //
        // Lo que mas importa de esta cuenta no es que suelte, es QUE FRENE: con alguien usandola devuelve
        // uno SIEMPRE, en cualquier maquina. Si eso fallara, la rocola se pondria lenta justo cuando hay
        // gente delante, y eso seria peor que no haber tocado nada. Pura a proposito, para poder darle los
        // cuatro casos a mano.
        internal static int CarrilesPara(bool turbo, bool sola, bool discoLento, int nucleos, bool minisPorHacer)
        {
            // Disco lento: aqui no manda el procesador, manda el cabezal. Varios hilos pidiendo canciones a
            // la vez lo ponen a saltar y sale mas lento, no mas rapido.
            if (discoLento) return 1;
            if (!turbo && !sola) return 1;      // hay alguien: ni uno mas
            // Y MIENTRAS QUEDEN MINIATURAS, ellas primero. Las dos cosas se sueltan cuando la rocola esta
            // sola, y sueltas a la vez en una maquina de dos nucleos se pelean por el disco y salen las dos
            // peor. La miniatura es lo que SE VE en la pared; el pre-analisis no se ve hasta que suena.
            if (minisPorHacer) return 1;
            if (nucleos < 4) return 1;          // en la de dos nucleos del bar no hay nada que repartir
            int c = nucleos - 1;                // siempre un nucleo libre para la pantalla y la musica
            if (c > 4) c = 4;                   // y de ahi no se pasa: mas no gana y calienta la maquina
            return c;
        }

        // Con cuantos carriles esta corriendo AHORA (0 = no hay nadie corriendo).
        private int preScanCarriles;

        // Al entrar y al salir de la atraccion: si ahora tocan otros carriles, se vuelve a empezar. Y si
        // tocan los mismos NO SE TOCA NADA: sin esto, cualquiera que pase por delante cada 40 segundos
        // reiniciaria el pre-analisis dos veces por paseo y no avanzaria nunca.
        private void RevisaCarriles()
        {
            if (preScanCarriles <= 0) return;   // no hay pre-analisis corriendo
            if (CarrilesPara(preScanTurbo, RocolaSola(), diskSlow, Environment.ProcessorCount, minisPendientes > 0) == preScanCarriles) return;
            StartPreScan(false);
        }

        private void StartPreScan() { StartPreScan(true); }
        private void StartPreScan(bool respiroDeArranque)
        {
            preScanStop = false;
            // Cada llamada (arranque o re-escaneo con F5) abre una GENERACION nueva: el hilo anterior se da
            // por caducado en cuanto lo nota y sale solo. Antes se volvia con "ya hay uno trabajando", asi que
            // la musica AGREGADA despues no se media hasta reiniciar la rocola.
            int myGen = ++preScanGen;
            bool turbo = preScanTurbo;
            int elegibles;
            List<string> pend = TandaPorMedir(turbo, out elegibles);
            // CADA cuanto se vuelcan las tablas a disco. Un volcado reescribe ENTERAS las tablas de sonoridad y
            // de EQ: con cien mil canciones son ~17 MB por volcado. Hacerlo cada 10 canciones durante un repaso a
            // fondo son CIENTOS de gigas escritos para nada, y eso desgasta el SSD. Asi que el intervalo crece con
            // la biblioteca: en una chica se guarda tan seguido como siempre; en una grande, cada tanto (como mucho
            // se pierde un rato de trabajo si se va la luz, y lo perdido solo se vuelve a medir).
            int guardaCada = turbo ? 10 : 25;
            int escala = loudCache.Count / 500;                        // se calcula aqui, en el hilo de la interfaz
            if (escala > guardaCada) guardaCada = escala;              // (las tablas son suyas: leerlas desde el hilo de fondo seria una carrera)
            if (guardaCada > 300) guardaCada = 300;
            preScanLeft = pend.Count;
            // La barra del entrenamiento a fondo se mide sobre TODA la biblioteca (no sobre la tanda que queda),
            // para que al reanudar siga desde donde iba en vez de volver a arrancar en cero.
            preScanTotal = turbo ? elegibles : pend.Count;
            if (pend.Count == 0) return;
            // CUANTOS CARRILES. El repaso A FONDO es el trabajo mas largo que hace la rocola -descomprime la
            // biblioteca entera- y hasta ahora lo hacia UN solo hilo: en un equipo de ocho o dieciseis nucleos
            // eso es dejar quieto el 90% de la maquina durante horas.
            //
            // Se reparte solo cuando de verdad conviene, con la misma regla que ya usan las caratulas:
            //   - SOLO a fondo. El repaso normal esta pensado para no notarse y se queda en un carril.
            //   - SOLO en SSD. En un disco duro no manda el procesador, manda el cabezal: varios hilos
            //     pidiendo canciones a la vez lo ponen a saltar y sale mas lento, no mas rapido.
            //   - Siempre dejando un nucleo libre para la pantalla y la musica, y como mucho cuatro: mas
            //     carriles ya no ganan nada y calientan la maquina del bar para nada.
            // En la rocola de dos nucleos esto da 1, o sea exactamente lo de siempre.
            //
            // Y ADEMAS cuando la rocola esta SOLA (ver RocolaSola): en atraccion, sin musica y sin video no
            // hay nadie eligiendo ni nada a lo que fallarle. La cuenta esta aparte y se prueba con casos a
            // mano, porque lo que de verdad importa de ella es que con alguien delante devuelva uno.
            bool aSolas = RocolaSola();
            int carriles = CarrilesPara(turbo, aSolas, diskSlow, Environment.ProcessorCount, minisPendientes > 0);
            preScanCarriles = carriles;
            int siguiente = -1;      // de aqui saca cada carril la siguiente cancion (reparto por demanda: las
            int hechasTot = 0;       // canciones no duran lo mismo, y asi ninguno se queda esperando al otro)
            int vidBien = 0, vidMal = 0;
            int vivos = carriles;
            Diag("repaso: " + pend.Count + " archivos en " + carriles + " carril(es)");
            preScanTh = new System.Threading.Thread[carriles];
            for (int carril = 0; carril < carriles; carril++)
            preScanTh[carril] = new System.Threading.Thread(delegate ()
            {
                bool ultimo = false;
                try
                {
                    // El respiro del arranque se paga UNA vez, no en cada revision de carriles: entrar y
                    // salir de la atraccion no es encender la rocola, y esperar 15 s cada vez se comeria
                    // justo el rato que se queria aprovechar.
                    if (!turbo && respiroDeArranque) System.Threading.Thread.Sleep(15000);   // dejar respirar el arranque (y al calentador de caratulas)
                    for (; ; )
                    {
                        int i = System.Threading.Interlocked.Increment(ref siguiente);
                        if (i >= pend.Count) break;
                        if (preScanStop || myGen != preScanGen) break;
                        // En modo normal se espera a que la rocola este en reposo (si alguien la usa, o hay un
                        // video, este hilo no toca nada). En ENTRENAMIENTO A FONDO no espera a nadie: para eso
                        // se enciende, para que la maquina se dedique por completo a dejar todo calibrado.
                        while (!turbo && !preScanStop && myGen == preScanGen && (Environment.TickCount - lastInputTick < 8000 || videoOn))
                            System.Threading.Thread.Sleep(500);
                        if (preScanStop || myGen != preScanGen) break;
                        string ruta = pend[i];
                        // Si este equipo ya demostro que no sabe descomprimir el sonido de un video, los demas
                        // ni se intentan: seria fallar mil veces seguidas y dejar el contador de "faltan"
                        // clavado para siempre en el numero de videos.
                        bool esVid = EsVideo(ruta);
                        if (esVid && videoSinMedir) { System.Threading.Interlocked.Decrement(ref preScanLeft); continue; }
                        float rms, dur; float[] eqCurve;
                        if (!MeasureFile(ruta, turbo, out rms, out dur, out eqCurve))
                        {
                            System.Threading.Interlocked.Decrement(ref preScanLeft);
                            // Tres videos seguidos sin poder abrirse y ninguno bueno todavia: no son archivos
                            // rotos, es que aqui no hay con que descomprimirlos.
                            if (esVid && vidBien == 0 && System.Threading.Interlocked.Increment(ref vidMal) >= 3)
                            { videoSinMedir = true; Diag("nivelado: este equipo no puede medir los videos (no hay Media Foundation)"); }
                            continue;
                        }
                        if (esVid) System.Threading.Interlocked.Increment(ref vidBien);
                        // publicar en el hilo de la interfaz (las tablas son suyas): sin carreras
                        try
                        {
                            if (!IsHandleCreated || preScanStop || myGen != preScanGen) break;
                            BeginInvoke((MethodInvoker)delegate
                            {
                                if (myGen != preScanGen) return;   // llego de una generacion caducada: descartar
                                PublicaMedida(ruta, rms, dur, eqCurve);
                                if (preScanLeft > 0) System.Threading.Interlocked.Decrement(ref preScanLeft);
                            });
                        }
                        catch { break; }
                        // Apuntada como repasada a fondo (despues de encargar la publicacion, no antes: si algo
                        // fallara al publicar no queremos darla por hecha sin haber guardado su medida).
                        if (turbo) MarkDeepDone(ruta);
                        int hechas = System.Threading.Interlocked.Increment(ref hechasTot);
                        if ((hechas % guardaCada) == 0)
                            try { if (IsHandleCreated) BeginInvoke((MethodInvoker)delegate { SaveLoudCache(); FlushEqIfDirty(); if (iaDoneDirty) { iaDoneDirty = false; SaveIaDone(); } if (deepDoneDirty) { deepDoneDirty = false; SaveDeepDone(); } }); } catch { }
                        // Respiro entre archivos. Con algo SONANDO se descansa mas (decodificar cuesta CPU y no
                        // vale la pena arriesgar un corte en la musica), pero la espera se ajusta al equipo: con
                        // UN SOLO nucleo el pre-analisis compite de verdad con la reproduccion y hay que frenarlo
                        // fuerte; con dos o mas nucleos sobra maquina y puede avanzar bastante mas rapido.
                        int respiro;
                        if (turbo || RocolaSola()) respiro = 1;   // sola no hay de quien descansar
                        else if (nowPlaying != null) respiro = (Environment.ProcessorCount >= 2) ? (diskSlow ? 220 : 120) : (diskSlow ? 700 : 400);
                        else respiro = diskSlow ? 120 : 40;
                        System.Threading.Thread.Sleep(respiro);
                    }
                }
                catch { }
                finally
                {
                    // El volcado final lo hace el ULTIMO carril que termina, no todos: si no, con cuatro
                    // carriles se reescribirian las tablas enteras cuatro veces seguidas para nada.
                    ultimo = System.Threading.Interlocked.Decrement(ref vivos) == 0;
                    try { if (ultimo && IsHandleCreated && hechasTot > 0) BeginInvoke((MethodInvoker)delegate { SaveLoudCache(); FlushEqIfDirty(); if (iaDoneDirty) { iaDoneDirty = false; SaveIaDone(); } if (deepDoneDirty) { deepDoneDirty = false; SaveDeepDone(); } }); } catch { }
                }
            });
            for (int carril = 0; carril < carriles; carril++)
            {
                preScanTh[carril].IsBackground = true;
            // NUNCA por delante de la pantalla ni de la musica. A fondo iba en prioridad NORMAL, la misma que la
            // interfaz: en la maquina de dos nucleos ese hilo -que decodifica canciones enteras sin parar- le
            // quitaba el turno al dibujado, y el fondo estrellado se veia ir lento o a tirones. Por debajo de lo
            // normal sigue quedandose con TODO el tiempo que la interfaz no usa (que es casi todo), pero en
            // cuanto hay un cuadro que dibujar, manda el cuadro. En automatico, la minima de todas.
                preScanTh[carril].Priority = turbo ? System.Threading.ThreadPriority.BelowNormal : System.Threading.ThreadPriority.Lowest;
                preScanTh[carril].Start();
            }
        }

        // Mide un archivo SIN reproducirlo: sonoridad K-weighted (BS.1770, igual que el nivelado en vivo), duracion
        // y la HUELLA TONAL del EQ automatico (8 bandas, mismo bandpass y misma referencia que al oirla). Analiza
        // PreSegs tramos repartidos por el tema (o el tema entero si es corto). Devuelve false si no se pudo.
        // "aFondo" = modo ENTRENAMIENTO A FONDO: analiza la cancion COMPLETA en vez de por tramos (la medida
        // mas exacta posible) y saca mucho mas material para la IA. En automatico se queda con el muestreo,
        // que da practicamente la misma sonoridad a una fraccion del costo.
        private bool MeasureFile(string path, bool aFondo, out float rms, out float durSec, out float[] eqCurve)
        {
            rms = 0f; durSec = 0f; eqCurve = null;
            // De un VIDEO solo interesa CUANTO SUENA. Su sonido lo saca el reproductor de Windows, no
            // nosotros: no pasa por el ecualizador ni por el DSEE ni por los graves. Medirle la huella tonal
            // o cosechar cuadros para la IA seria trabajo y disco gastados en algo que nunca se usaria.
            bool esVideo = EsVideo(path);
            LectorMedida rd = null;
            try
            {
                rd = new LectorMedida(path);
                rd.Volume = 1.0f;
                int rate = rd.WaveFormat.SampleRate; if (rate < 8000) rate = 44100;
                int ch = rd.WaveFormat.Channels; if (ch < 1) ch = 1;
                double total = rd.TotalTime.TotalSeconds;
                if (total <= 0.05 || total > 36000) return false;   // vacio o absurdo (archivo roto)
                durSec = (float)total;
                float[] c1 = EqShelfHi(1681.974f, rate, 3.99984f, 0.70717f);   // mismas dos etapas del K-weighting
                float[] c2 = EqHighPass(38.1355f, rate, 0.50033f);             // que usa el nivelado en vivo
                float[] st = new float[ch * 8];
                float[] buf = new float[4096 * ch];
                double sumSq = 0; long nSamp = 0;
                // RECORTE DE ORIGEN: muestras pegadas al techo digital en rachas de 3 o mas. No es distorsion
                // que metamos nosotros: viene asi masterizada. Se cuenta aqui, en el recorrido que ya se hacia.
                long clipN = 0; int[] clipRun = new int[ch];
                float[][] bp = new float[8][]; float[] bpSt = new float[8 * 4];   // huella tonal: bandpass por banda
                if (!esVideo) for (int b = 0; b < 8; b++) bp[b] = EqBpf(EqCentros[b], rate);   // (de un video no se saca huella: se quedan en nulo y el filtro se salta)
                double[] bpSum = new double[8]; long bpN = 0;
                // COSECHA PARA LA IA: se analiza el canal 0 con el MISMO motor del DSEE. Los pares se guardan
                // en memoria y solo se escriben al final, si resulta que la cancion SI conserva sus agudos
                // (una cancion dañada no puede enseñar nada: los agudos reales ya no estan en el archivo).
                SpectralTap hv = null; float[] hvFrame = null, hvFeat = null, hvTgt = null;
                int hvFill = 0; List<float> hvPairs = null;
                long hvVistos = 0, hvVistosMax = IaFramesPerSong;   // cuadros con sonido que han pasado / hasta donde mirar
                int hvStride = 1, hvFase = 0;
                // El ACANTILADO se mide SIEMPRE, cosechemos o no para la IA. Es el dato que dice si una cancion
                // llego completa o el codec le talo los agudos, y de eso dependen dos cosas importantes: si sirve
                // para fijar el objetivo del EQ automatico, y que bandas suyas tiene sentido corregir. Cuesta unas
                // pocas decenas de FFT por cancion, nada al lado de descomprimirla entera.
                bool soloCorte = false;
                // tramos: si el tema es corto se analiza entero; si no, PreSegs ventanas repartidas evitando
                // el arranque y el final (intros/silencios finales no representan la sonoridad del tema).
                // A FONDO: un solo "tramo" que abarca la cancion entera. En automatico: PreSegs ventanas.
                // (Se decide AQUI, antes de la cosecha, porque de cuanto audio se va a descomprimir depende
                // cada cuantos cuadros conviene tomar uno.)
                int segs = (aFondo || total <= PreSegSec * PreSegs) ? 1 : PreSegs;
                double segLen = (segs == 1) ? total : PreSegSec;
                int cuadroLen = 2048;   // el de SpectralTap; se confirma al crearlo
                long framesTot = (long)(segs * segLen * rate / cuadroLen);
                int diana = aFondo ? IaDeepFrames : IaFramesPerSong;
                // El paso se REDONDEA HACIA ARRIBA a proposito: con la division a secas el ultimo cuadro caia
                // antes del final y se quedaba sin mirar el ultimo 15% de cada cancion.
                long pasoIa = (framesTot - IaWarmFrames + diana - 1) / Math.Max(1, diana);
                int strideIa = (pasoIa > 1) ? (int)pasoIa : 1;
                // ----- CUANTAS VECES SE MIRA CADA CANCION -----
                // Niveles apuntados en rocola_ia_hechas.txt: 0 = nunca; 1 = una pasada del modo PASIVO;
                // 2 = repasada A FONDO (esa ya dio todo lo que tenia); 3..9 = 2..8 pasadas del pasivo.
                //
                // Antes, en cuanto una cancion llegaba al nivel 1 el modo pasivo NO volvia a mirarla nunca. Con
                // la biblioteca entera en nivel 1 el archivo de material dejaba de crecer y ahi se quedaba para
                // siempre: por eso despues de dias encendida seguia en los mismos gigas. Ahora cada pasada mira
                // cuadros DISTINTOS de la misma cancion (ver hvFase), asi que el material sigue creciendo sin
                // que el repaso cueste ni un milisegundo mas por cancion. Se para cuando las fases se agotan
                // (pasado 'strideIa' ya se habrian repetido cuadros, que es engordar el archivo por gusto).
                int nivelPrevio; lock (iaDoneLock) { if (!iaDone.TryGetValue(path, out nivelPrevio)) nivelPrevio = 0; }
                int pasadas = IaPasadasDe(nivelPrevio);
                int nivelAhora; bool cosechar;
                if (aFondo) { nivelAhora = 2; cosechar = (nivelPrevio != 2); }
                else { nivelAhora = IaNivelDePasada(pasadas); cosechar = pasadas < Math.Min(IaPasadasMax, strideIa); }
                cosechar = cosechar && iaHarvestOn && !IaBudgetFull() && !esVideo;
                if (!cosechar && !esVideo)
                {
                    // Solo hace falta el acantilado: se analizan unos pocos cuadros y se para (ni se guardan pares).
                    try { hv = new SpectralTap(rate, 1); hvFrame = new float[hv.FrameLen]; soloCorte = true; hvVistosMax = IaWarmFrames + 24; }
                    catch { hv = null; }
                }
                if (cosechar)
                {
                    try
                    {
                        hv = new SpectralTap(rate, 1);
                        hvFrame = new float[hv.FrameLen]; hvFeat = new float[28]; hvTgt = new float[12];
                        hvPairs = new List<float>(4096);
                        // Los cuadros se toman REPARTIDOS por todo lo que se va a descomprimir, no seguidos
                        // desde el principio. Antes el modo pasivo cosechaba los 192 PRIMEROS: eso son 8,9
                        // segundos, siempre del mismo sitio de cada cancion, o sea que la red solo llegaba a
                        // ver esa rebanada de toda la biblioteca. Y dos cuadros pegados se parecen tanto que
                        // apilarlos engorda el archivo sin ensenar nada nuevo.
                        if (hv.FrameLen != cuadroLen)   // por si el cuadro cambiara: se rehace la cuenta
                        {
                            cuadroLen = hv.FrameLen;
                            framesTot = (long)(segs * segLen * rate / cuadroLen);
                            pasoIa = (framesTot - IaWarmFrames + diana - 1) / Math.Max(1, diana);
                            strideIa = (pasoIa > 1) ? (int)pasoIa : 1;
                        }
                        hvStride = strideIa;
                        hvFase = (hvStride > 1) ? (pasadas % hvStride) : 0;   // cada pasada, cuadros distintos
                        hvVistosMax = IaWarmFrames + (long)hvStride * diana;
                    }
                    catch { hv = null; }
                }
                for (int s = 0; s < segs && !preScanStop; s++)
                {
                    if (segs > 1)
                    {
                        double span = total * 0.80;                       // zona util: del 10% al 90% del tema
                        double pos = total * 0.10 + span * s / (double)segs;
                        if (pos + segLen > total) pos = Math.Max(0, total - segLen);
                        try { rd.CurrentTime = TimeSpan.FromSeconds(pos); } catch { }
                    }
                    long want = (long)(segLen * rate) * ch;
                    long got = 0;
                    while (got < want)
                    {
                        int want2 = (int)Math.Min(buf.Length, want - got);
                        int n = rd.Read(buf, 0, want2);
                        if (n <= 0) break;
                        got += n;
                        for (int i = 0; i + ch <= n; i += ch)
                        {
                            // HUELLA TONAL (EQ automatico): igual que en vivo, sobre la mezcla MONO del cuadro.
                            float m = buf[i];
                            for (int mc = 1; mc < ch; mc++) m += buf[i + mc];   // mc: el nombre c2 ya es el coeficiente del K-weighting
                            m /= ch;
                            for (int b2 = 0; b2 < 8; b2++)
                            {
                                float[] cf = bp[b2]; if (cf == null) continue;
                                int q = b2 * 4;
                                float o = cf[0] * m + cf[1] * bpSt[q] + cf[2] * bpSt[q + 1] - cf[3] * bpSt[q + 2] - cf[4] * bpSt[q + 3];
                                bpSt[q + 1] = bpSt[q]; bpSt[q] = m;
                                bpSt[q + 3] = bpSt[q + 2]; bpSt[q + 2] = o;
                                bpSum[b2] += o * o;
                            }
                            bpN++;
                            // canal 0 hacia el analizador de la IA (el DSEE tambien trabaja por canal)
                            if (hv != null && hvVistos < hvVistosMax)
                            {
                                hvFrame[hvFill++] = buf[i];
                                if (hvFill >= hvFrame.Length)
                                {
                                    hvFill = 0;
                                    double en = 0; for (int q = 0; q < hvFrame.Length; q++) en += hvFrame[q] * hvFrame[q];
                                    if (en / hvFrame.Length > 1e-8)   // saltar cuadros practicamente mudos
                                    {
                                        hvVistos++;
                                        // SOLO se le hace la FFT a los cuadros que van a servir. Antes se
                                        // analizaban TODOS los que pasaban hasta el tope y despues se tiraba
                                        // el trabajo de los que no tocaban: en el repaso a fondo eso eran mas
                                        // de tres cuartas partes de las FFT hechas para nada. Los primeros si
                                        // van seguidos: el acantilado necesita unos cuantos para asentarse.
                                        bool sirve = (hvVistos <= IaWarmFrames) || hvStride == 1
                                                     || (((hvVistos + hvFase) % hvStride) == 0);
                                        if (sirve)
                                        {
                                            hv.AnalyzeFrame(hvFrame, 0);
                                            if (!soloCorte && hvVistos > IaWarmFrames)   // acantilado ya estabilizado
                                                for (int q = 0; q < IaCutsHz.Length; q++)
                                                    if (hv.MakePair(IaCutsHz[q], hvFeat, hvTgt))
                                                    {
                                                        for (int z = 0; z < 28; z++) hvPairs.Add(hvFeat[z]);
                                                        for (int z = 0; z < 12; z++) hvPairs.Add(hvTgt[z]);
                                                    }
                                        }
                                    }
                                }
                            }
                            for (int c = 0; c < ch; c++)
                            {
                                int b = c * 8; float x = buf[i + c];
                                float y1 = c1[0]*x + c1[1]*st[b] + c1[2]*st[b+1] - c1[3]*st[b+2] - c1[4]*st[b+3];
                                st[b+1]=st[b]; st[b]=x; st[b+3]=st[b+2]; st[b+2]=y1;
                                float y2 = c2[0]*y1 + c2[1]*st[b+4] + c2[2]*st[b+5] - c2[3]*st[b+6] - c2[4]*st[b+7];
                                st[b+5]=st[b+4]; st[b+4]=y1; st[b+7]=st[b+6]; st[b+6]=y2;
                                sumSq += y2 * y2; nSamp++;
                                float ax = x < 0f ? -x : x;
                                if (ax >= 0.985f) { clipRun[c]++; if (clipRun[c] == 3) clipN += 3; else if (clipRun[c] > 3) clipN++; }
                                else clipRun[c] = 0;
                            }
                        }
                    }
                }
                // Solo las canciones COMPLETAS (sin acantilado, el mismo umbral que usa el DSEE para no tocarlas)
                // sirven de maestras: en las dañadas los agudos reales ya no existen y no hay nada que enseñar.
                if (hv != null && !soloCorte && hvPairs.Count >= 40 && hv.CutHz >= EqSanaHz)
                {
                    IaAppendPairs(hvPairs);
                    MarkIaDone(path, nivelAhora);
                }
                float corteHz = (hv != null) ? hv.CutHz : 0f;
                float corteLo = (hv != null) ? hv.CutLoHz : 0f;
                float recorte = (nSamp > 0) ? (float)((double)clipN / nSamp) : 0f;
                if (nSamp < 40000) return durSec > 0.01f;   // muy poco audio util: al menos queda la duracion
                rms = (float)Math.Sqrt(sumSq / nSamp);
                // SILENCIO DE VERDAD. Un archivo sin nada de sonido da cero, y con cero no se guardaba: se
                // quedaba como "sin medir", se volvia a medir en cada arranque para siempre, y no aparecia
                // nunca en la limpieza de videos mudos. Se le pone un valor minusculo -por debajo del umbral
                // con el que TODO el programa decide "esto no tiene medida util", asi que nadie va a intentar
                // subirlo cien mil veces- para que quede APUNTADO como medido y callado.
                if (rms < LoudMudo) rms = LoudMudo;
                // Huella tonal en dB por banda, referida a la MEDIANA del cuerpo (158 Hz - 5.6 kHz): exactamente
                // la misma cuenta que hace FinalizeEqMeasure al aprenderla oyendo la cancion.
                if (bpN >= 40000 && !esVideo)
                {
                    float[] curve = new float[EqLen];
                    curve[EqCut] = corteHz; curve[EqClip] = recorte; curve[EqCutLo] = corteLo;
                    for (int b = 0; b < 8; b++) curve[b] = (float)(10.0 * Math.Log10(bpSum[b] / bpN + 1e-12));
                    float[] cuerpo = { curve[1], curve[2], curve[3], curve[4], curve[5] };
                    Array.Sort(cuerpo);
                    float refDb = cuerpo[2];
                    for (int b = 0; b < 8; b++) curve[b] -= refDb;
                    eqCurve = curve;
                }
                return true;
            }
            catch { return durSec > 0.01f; }
            finally { if (rd != null) { try { rd.Dispose(); } catch { } } }
        }

        // CUANTO DURA UNA CANCION, Y EL UNICO SITIO QUE LO SABE.
        //
        // Manda la del analisis completo (que midio la cancion entera); si aun no la tiene, la del
        // barrido rapido. Devuelve 0 cuando no se sabe, y eso NO es lo mismo que cero segundos: quien
        // pregunta tiene que mirarlo y callarse en vez de inventar.
        //
        // Y aqui NO se le pregunta al archivo. El descompresor no sabe cuanto dura un MP3 hasta
        // recorrerlo entero cuando no trae cabecera Xing -medido: 3.87 ms de procesador en una cancion
        // de 4 minutos, mas la lectura de sus 9 MB del disco-. Multiplicado por toda la cola, y justo
        // en el instante en que alguien acaba de pulsar un boton. La duracion ya esta apuntada.
        private float SegundosDe(string path)
        {
            float d;
            if (path == null) return 0f;
            if (durCache.TryGetValue(path, out d) && d > 0.01f) return d;
            if (durFast.TryGetValue(path, out d) && d > 0.01f) return d;
            return 0f;
        }

        // Duracion "m:ss" de una cancion ya pre-analizada ("" si aun no se sabe).
        private string DurText(string path)
        {
            float d = SegundosDe(path);
            if (d <= 0f) return "";
            int tot = (int)(d + 0.5f);
            return (tot / 60) + ":" + (tot % 60).ToString("00");
        }

        // ============================== TU TURNO EN LA COLA ==============================
        //
        // La pastilla dice cuantas canciones van pedidas. Eso es un dato del LOCAL: al que acaba de
        // meter su moneda no le sirve saber que hay cuatro, le sirve saber CUAL ES LA SUYA y cuanto
        // falta. Y no es un detalle bonito: es la causa de que la gente vuelva a picarle al boton -a
        // veces gastando otro credito- creyendo que la maquina no le hizo caso.
        //
        // La cuenta va APARTE, en dos funciones puras que reciben numeros y devuelven un numero. Asi se
        // les pueden dar casos a mano y comprobar que contestan bien (pruebas/turno.cs), que con esto
        // metido dentro de la pantalla no se podria. Es la misma idea que ProponeEscalones en el medidor.

        // Los segundos que faltan para que empiece TU cancion, o -1 si NO SE PUEDE SABER.
        //
        // Basta con que de UNA de las que van por delante no se sepa la duracion -recien copiada al
        // disco, aun sin analizar- para que la cuenta entera deje de valer. Y entonces hay que decirlo,
        // no redondear: un "en ~11 min" que luego son veinte es peor que no decir nada, porque la
        // proxima vez ya nadie se lo cree.
        internal static double EsperaSegundos(double[] antesQueLaTuya, double restanDeLaQueSuena)
        {
            if (restanDeLaQueSuena < 0) return -1;
            double s = restanDeLaQueSuena;
            if (antesQueLaTuya != null)
                for (int i = 0; i < antesQueLaTuya.Length; i++)
                {
                    if (!(antesQueLaTuya[i] > 0)) return -1;
                    s += antesQueLaTuya[i];
                }
            return s;
        }

        // Y como se dice. Sin tiempo fiable se dice SOLO el puesto: sigue sirviendo y no miente.
        internal static string TextoTurno(int puesto, double segundos)
        {
            // Apagado desde Ctrl+F3 devuelve texto vacio, y con eso el aviso vuelve solo al "Cancion
            // agregada" de siempre: el interruptor vive AQUI, en el unico sitio que escribe el letrero,
            // y no repartido por los dos sitios que lo piden.
            if (!turnoOn || puesto <= 0) return "";
            string donde = (puesto == 1) ? "Tu cancion es la siguiente" : ("Tu cancion es la " + puesto + "a");
            if (segundos < 0) return donde;
            if (segundos < 60) return donde + " - en menos de 1 min";
            return donde + " - en ~" + (int)((segundos + 30) / 60) + " min";
        }

        // Lo que le queda a la que suena. Con un VIDEO se devuelve "no se sabe": el video no lo lleva la
        // cadena de la rocola sino el reproductor de fuera, asi que por donde va no se puede preguntar
        // sin adivinar, y adivinar aqui es justo lo que no se quiere.
        private double RestanDeLaQueSuena()
        {
            if (nowPlaying == null) return 0;
            if (nowPlaying.IsVideo) return -1;
            double tot = SegundosDe(nowPlaying.PathKey());
            if (tot <= 0) return -1;
            double va = 0; try { if (reader != null) va = reader.CurrentTime.TotalSeconds; } catch { }
            double q = tot - va;
            return (q > 0) ? q : 0;
        }
        // PRECALENTAR LA SIGUIENTE CANCION.
        //
        // Al arrancar una cancion, NAudio se recorre el MP3 COMPLETO para armar su indice de trozos (lo
        // necesita para poder moverse por la cancion y para saber cuanto dura), y eso pasa en el hilo de la
        // pantalla. En un disco duro mecanico, un archivo de 10 MB son unas decimas de segundo con la rocola
        // clavada, justo en el momento del cambio de cancion.
        //
        // Aqui se lee ese archivo ANTES, en segundo plano y sin ninguna prisa, para que cuando le toque ya
        // este en la memoria de Windows y abrirlo sea instantaneo. No se guarda nada: solo se pasa por
        // encima para que el sistema lo cachee. Va a 64 KB por vez con una pausa entre trozos (una cancion
        // de 10 MB se calienta en algo mas de un segundo, y quedan minutos por delante), cede el disco si
        // hay caratulas en camino o un video sonando, y se cancela sola si la cola cambia.
        private volatile int warmSongGen = 0;
        private string warmSongPath;
        private void PrecalientaSiguiente()
        {
            string ruta = null;
            for (int i = 0; i < queue.Count; i++)
            {
                PlayItem it = queue[i];
                if (it != null && !it.IsVideo && it.Song != null && it.Song.Path != null) { ruta = it.Song.Path; break; }
            }
            if (ruta == null) return;
            if (string.Equals(ruta, warmSongPath, StringComparison.OrdinalIgnoreCase)) return;   // ya calentada o calentandose
            warmSongPath = ruta;
            int mio = ++warmSongGen;
            // ¿YA ESTA MEDIDA? Se pregunta AQUI, que es el hilo de la pantalla y por tanto el dueño de las
            // tablas: no llevan candado -a proposito, para no pagarlo en cada consulta-, y el pre-analisis
            // escribe en ellas desde otro lado. Preguntarlo desde el hilo del calentador podria reventar
            // justo en el momento en que el otro esta metiendo una fila.
            bool yaMedida = durCache.ContainsKey(ruta);
            System.Threading.Thread t = new System.Threading.Thread(delegate ()
            {
                try
                {
                    System.Threading.Thread.Sleep(1500);   // que la cancion que acaba de empezar tenga el disco
                    if (mio != warmSongGen) return;
                    while (true)   // caratulas del primer plano o un video: el disco es para ellos
                    {
                        int busy; lock (coverLock) { busy = coverLoading.Count + coverQHi.Count + coverQLo.Count; }
                        if (busy == 0 && !videoOn) break;
                        System.Threading.Thread.Sleep(300);
                        if (mio != warmSongGen) return;
                    }
                    // TROZOS segun el disco. Un disco duro se lee a trozos chicos y con pausa entre trozo y
                    // trozo, para no dejar al cabezal ocupado si de pronto hace falta para otra cosa. Un SSD
                    // rinde al contrario: cuanto mas grande el trozo, menos veces se le molesta y antes acaba,
                    // asi que se le piden 256 KB de una y la cancion queda en memoria en un pestaneo.
                    // Y en los dos casos se avisa a Windows de que esto se va a leer DE PRINCIPIO A FIN
                    // (SequentialScan): con eso adelanta la lectura por su cuenta en vez de ir trozo a trozo.
                    bool lentoAqui = DiscoLento(ruta);
                    int trozo = lentoAqui ? (64 * 1024) : (256 * 1024);
                    byte[] buf = new byte[trozo];
                    using (FileStream fs = new FileStream(ruta, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, trozo, FileOptions.SequentialScan))
                    {
                        while (fs.Read(buf, 0, buf.Length) > 0)
                        {
                            if (mio != warmSongGen) return;
                            System.Threading.Thread.Sleep(lentoAqui ? 8 : 1);
                        }
                    }

                    // Y YA QUE ESTA LEIDA, SE MIDE.
                    //
                    // Medir una cancion cuesta dos cosas: leerla del disco y descomprimirla. La lectura
                    // acaba de pagarse aqui arriba, y hasta ahora se tiraba entera. Descomprimir lo que ya
                    // esta en la memoria del sistema cuesta 550 ms por minuto de cancion -medido-, unos 2.2
                    // segundos en una de cuatro minutos, y este hilo va en la prioridad mas baja que hay y
                    // tiene por delante los minutos que la cancion pase en la cola.
                    //
                    // A cambio, cuando le toque sonar ya viene nivelada de volumen A LA PRIMERA -antes solo
                    // a la segunda, porque la sonoridad se aprendia oyendola-, con su duracion apuntada y
                    // con el turno pudiendo decir los minutos que faltan.
                    if (yaMedida || mio != warmSongGen) return;
                    while (true)   // otra vez: si entro un video o hay caratulas en camino, primero ellos
                    {
                        int ocupado; lock (coverLock) { ocupado = coverLoading.Count + coverQHi.Count + coverQLo.Count; }
                        if (ocupado == 0 && !videoOn) break;
                        System.Threading.Thread.Sleep(300);
                        if (mio != warmSongGen) return;
                    }
                    float wrms, wdur; float[] weq;
                    if (!MeasureFile(ruta, false, out wrms, out wdur, out weq)) return;
                    if (mio != warmSongGen) return;
                    // Las tablas son del hilo de la pantalla: se le encarga a el que las escriba.
                    try
                    {
                        if (IsHandleCreated)
                            BeginInvoke((MethodInvoker)delegate { PublicaMedida(ruta, wrms, wdur, weq); });
                    }
                    catch { }
                }
                catch { }
            });
            t.IsBackground = true;
            t.Priority = System.Threading.ThreadPriority.Lowest;
            t.Start();
        }

        // CUANTAS MINIATURAS FALTAN POR HACER. Lo mantiene el calentador y lo consulta el pre-analisis
        // para apartarse: las miniaturas son lo que SE VE en la pared, asi que van primero. En la maquina
        // de dos nucleos del bar, sueltos los dos a la vez se pelean por el disco y salen los dos peor.
        private volatile int minisPendientes;

        private void StartThumbWarm()
        {
            warmGen++;
            int myGen = warmGen;
            List<Album> snap = new List<Album>(albums);
            System.Threading.Thread t = new System.Threading.Thread(delegate ()
            {
                try
                {
                    System.Threading.Thread.Sleep(12000);   // dejar respirar el arranque
                    // Antes de ponerse a construir, barrer lo antiguo (solo si la carpeta se hizo grande;
                    // ver BarreMiniaturas). Va aqui y no en el arranque para no gastar ni un milisegundo
                    // del rato en que la rocola esta apareciendo.
                    int barridas = BarreMiniaturas();
                    if (barridas > 0) Diag("miniaturas: barridas " + barridas + " de mas de " + MiniaturasDiasMax + " dias");
                    // CUANTAS FALTAN, antes de empezar. Es una pasada de File.Exists por disco -barata al
                    // lado de los 72 ms que cuesta hacer una- y con ella el pre-analisis sabe si tiene que
                    // apartarse: mientras queden miniaturas, mandan ellas, que son lo que se ve.
                    int faltan = 0;
                    for (int i = 0; i < snap.Count; i++)
                    {
                        Album a0 = snap[i];
                        if (a0 == null || a0.CoverPath == null) continue;
                        try { if (!File.Exists(ThumbCachePath(a0.CoverPath))) faltan++; } catch { }
                    }
                    minisPendientes = faltan;
                    if (faltan > 0) Diag("miniaturas: faltan " + faltan + " por hacer");
                    for (int i = 0; i < snap.Count; i++)
                    {
                        if (myGen != warmGen) return;   // recargaron la musica: este hilo ya caduco
                        Album a = snap[i];
                        if (a == null || a.CoverPath == null) continue;
                        try { if (File.Exists(ThumbCachePath(a.CoverPath))) continue; } catch { continue; }
                        // Si alguien uso la rocola hace poco, esperar (no robarle CPU ni DISCO a la interfaz).
                        //
                        // SALVO QUE ESTE SOLA. Hacer la miniatura de un disco cuesta 72 ms la primera vez
                        // contra 0.90 leyendola ya hecha -ochenta veces-, y con tres mil discos son tres
                        // minutos y medio de trabajo UNA vez en la vida de la rocola. Pero esperando ocho
                        // segundos sin botones antes de cada una, en un bar con gente eso no acaba nunca:
                        // semanas para tres minutos y medio, y mientras tanto la pared enseña las portadas
                        // llegando tarde. En atraccion, sin musica y sin video no hay a quien estorbar.
                        while (!RocolaSola() && Environment.TickCount - lastInputTick < 8000)
                        {
                            System.Threading.Thread.Sleep(400);
                            if (myGen != warmGen) return;
                        }
                        // si hay caratulas del primer plano en camino/formadas, o un VIDEO reproduciendose
                        // (el video lee del disco SIN colchon), cederles el disco por completo
                        while (true)
                        {
                            int busy; lock (coverLock) { busy = coverLoading.Count + coverQHi.Count + coverQLo.Count; }
                            if (busy == 0 && !videoOn) break;
                            System.Threading.Thread.Sleep(300);
                            if (myGen != warmGen) return;
                        }
                        coverSem.WaitOne();   // mismo turno unico de disco que las cargas normales
                        try
                        {
                            if (myGen != warmGen) return;
                            // si JUSTO llego trabajo del primer plano, soltar el turno y reintentar despues
                            bool fgBusy;
                            lock (coverLock) { fgBusy = (coverLoading.Count + coverQHi.Count + coverQLo.Count) > 0; }
                            if (fgBusy) { i--; System.Threading.Thread.Sleep(60); continue; }
                            Image im = DecodeCover(a.CoverPath);   // crea la miniatura en disco como efecto
                            if (im != null) im.Dispose();          // no ocupar memoria: solo queremos el disco
                        }
                        catch { }
                        finally { coverSem.Release(); }
                        if (minisPendientes > 0) minisPendientes--;
                        // Respiro largo en disco duro; en SSD el freno era el respiro, no el disco. Y sola no
                        // hay de quien descansar.
                        if (!RocolaSola()) System.Threading.Thread.Sleep(diskSlow ? 150 : 20);
                    }
                    minisPendientes = 0;   // se acabo la vuelta: ya no falta ninguna
                }
                catch { }
            });
            t.IsBackground = true;
            t.Priority = System.Threading.ThreadPriority.Lowest;
            t.Start();
        }

        // ===================== CACHE DE BIBLIOTECA (arranque rapido) =====================
        // El arranque hacia DOS caminatas completas del disco (audio y video) MAS ~una verificacion de
        // portada por cada disco: en disco duro, minutos. Aqui se guarda el resultado en un archivo y
        // los siguientes arranques lo leen en segundos. Se invalida solo si la carpeta de musica cambio
        // (cantidad de carpetas o fecha de la raiz). F5 siempre fuerza un re-escaneo completo.
        private string LibCacheFile() { return RutaDatos("rocola_biblioteca.txt"); }

        // En arranque desde cache: portadas resueltas SIN tocar el disco.
        // La portada de una carpeta: siempre sale del mapa que dejo el recorrido del disco (el escaneo fresco lo
        // arma sobre la marcha y el arranque por cache lo trae del archivo), asi que aqui ya no se toca el disco.
        private string FindCoverCached(string folder)
        {
            string cp;
            if (cachedCovers != null && cachedCovers.TryGetValue(folder, out cp)) return cp;
            return null;
        }

        // Firma de una raiz: fecha de modificacion + cantidad de subcarpetas (si cambia, hay que re-escanear).
        private static string RootSig(string root)
        {
            return Directory.GetLastWriteTimeUtc(root).Ticks + ":" + Directory.GetDirectories(root).Length;
        }
        private static string JoinRoots(List<string> roots)
        {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < roots.Count; i++) { if (i > 0) sb.Append('|'); sb.Append(roots[i]); }
            return sb.ToString();
        }

        private bool TryLoadLibraryCache(List<string> roots, out List<Track> outTracks, out List<string> outVideos, out Dictionary<string, string> outCovers)
        {
            outTracks = null; outVideos = null; outCovers = null;
            try
            {
                string f = LibCacheFile();
                if (!File.Exists(f)) return false;
                string[] L = File.ReadAllLines(f);
                if (L.Length < 7 || L[0] != "ROCOLA-LIB v2") return false;   // v2: multiples raices (Ctrl+F2)
                if (!L[1].StartsWith("roots=") || !string.Equals(L[1].Substring(6), JoinRoots(roots), StringComparison.OrdinalIgnoreCase)) return false;
                string sig = ""; try { StringBuilder ss = new StringBuilder(); for (int i = 0; i < roots.Count; i++) { if (i > 0) ss.Append('|'); ss.Append(RootSig(roots[i])); } sig = ss.ToString(); } catch { return false; }
                if (!L[2].StartsWith("sig=") || L[2].Substring(4) != sig) return false;   // alguna raiz cambio -> re-escanear
                if (!L[3].StartsWith("dirs=")) return false;   // linea reservada (compatibilidad de formato)

                int li = 4;
                int na; if (!L[li].StartsWith("A") || !int.TryParse(L[li].Substring(1), out na)) return false; li++;
                if (li + na > L.Length) return false;
                List<Track> tk = new List<Track>(na);
                for (int i = 0; i < na; i++) { string p = L[li + i]; if (p.Length > 0) tk.Add(Track.FromFile(p)); }
                li += na;
                int nv; if (li >= L.Length || !L[li].StartsWith("V") || !int.TryParse(L[li].Substring(1), out nv)) return false; li++;
                if (li + nv > L.Length) return false;
                List<string> vd = new List<string>(nv);
                for (int i = 0; i < nv; i++) { string p = L[li + i]; if (p.Length > 0) vd.Add(p); }
                li += nv;
                int nc; if (li >= L.Length || !L[li].StartsWith("C") || !int.TryParse(L[li].Substring(1), out nc)) return false; li++;
                if (li + nc > L.Length) return false;
                Dictionary<string, string> cv = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < nc; i++)
                {
                    string s = L[li + i]; int b = s.IndexOf('|'); if (b <= 0) continue;
                    cv[s.Substring(0, b)] = s.Substring(b + 1);
                }
                if (tk.Count == 0) return false;
                outTracks = tk; outVideos = vd; outCovers = cv;
                return true;
            }
            catch { return false; }
        }

        // Guarda la biblioteca en segundo plano (la copia de datos es instantanea; la escritura va al pool).
        private void SaveLibraryCacheAsync()
        {
            try
            {
                List<string> roots = (scanRoots != null && scanRoots.Count > 0) ? new List<string>(scanRoots) : AllMusicRoots();
                if (roots.Count == 0) return;
                List<string> ap = new List<string>(tracks.Count);
                for (int i = 0; i < tracks.Count; i++) ap.Add(tracks[i].Path);
                List<string> vp = (lastVideoPaths != null) ? new List<string>(lastVideoPaths) : new List<string>();
                Dictionary<string, string> cv = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < albums.Count; i++) if (albums[i].CoverPath != null) cv[albums[i].Folder] = albums[i].CoverPath;
                if (videoAlbums != null) for (int i = 0; i < videoAlbums.Count; i++) if (videoAlbums[i].CoverPath != null) cv[videoAlbums[i].Folder] = videoAlbums[i].CoverPath;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate (object st)
                {
                    try
                    {
                        StringBuilder sb = new StringBuilder(ap.Count * 64);
                        sb.Append("ROCOLA-LIB v2\r\n");
                        sb.Append("roots=").Append(JoinRoots(roots)).Append("\r\n");
                        sb.Append("sig=");
                        for (int i = 0; i < roots.Count; i++) { if (i > 0) sb.Append('|'); sb.Append(RootSig(roots[i])); }
                        sb.Append("\r\n");
                        sb.Append("dirs=0\r\n");   // linea reservada (el formato v1 la usaba; se conserva la posicion)
                        sb.Append("A").Append(ap.Count).Append("\r\n");
                        for (int i = 0; i < ap.Count; i++) sb.Append(ap[i]).Append("\r\n");
                        sb.Append("V").Append(vp.Count).Append("\r\n");
                        for (int i = 0; i < vp.Count; i++) sb.Append(vp[i]).Append("\r\n");
                        sb.Append("C").Append(cv.Count).Append("\r\n");
                        foreach (KeyValuePair<string, string> kv in cv) sb.Append(kv.Key).Append('|').Append(kv.Value).Append("\r\n");
                        EscribeSeguro(LibCacheFile(), sb.ToString());
                    }
                    catch { }
                });
            }
            catch { }
        }

        // Camina el arbol UNA vez y clasifica lo que encuentra: audio, video y la portada de cada carpeta.
        // Es el reemplazo de las dos caminatas separadas + el GetFiles extra que hacia FindCover por carpeta.
        private void ScanFolders(string root, List<string> audio, List<string> video, Dictionary<string, string> covers)
        {
            Stack<string> dirs = new Stack<string>();
            dirs.Push(root);
            while (dirs.Count > 0)
            {
                string dir = dirs.Pop();
                string[] files = null;
                try { files = Directory.GetFiles(dir); } catch { }
                if (files != null)
                {
                    for (int i = 0; i < files.Length; i++)
                    {
                        string ext = Path.GetExtension(files[i]).ToLowerInvariant();
                        if (Array.IndexOf(AudioExt, ext) >= 0) audio.Add(files[i]);
                        else if (Array.IndexOf(VideoExt, ext) >= 0) video.Add(files[i]);
                    }
                    if (!covers.ContainsKey(dir))
                    {
                        string cv = CoverFromList(dir, files);
                        if (cv != null) covers[dir] = cv;
                    }
                    if (audio.Count % 50 < files.Length) { try { scanner.ReportProgress(0, audio.Count); } catch { } }   // avance para la pantalla de arranque
                }
                string[] subs = null;
                try { subs = Directory.GetDirectories(dir); } catch { }
                if (subs != null)
                    foreach (string d in subs)
                    {
                        if (EsAtajo(d)) continue;                   // ver EsAtajo: si no, no se sale nunca
                        if (EsCarpetaDelSistema(d)) continue;       // Windows, los programas, la papelera...
                        dirs.Push(d);
                    }
            }
        }

        // CARPETAS DONDE NO PUEDE HABER MUSICA. Si se le dice a la rocola "la musica esta en este disco
        // entero", el recorrido se mete en la carpeta de Windows y en la de los programas, que son decenas
        // de miles de archivos y ni una sola cancion. Medido en la rocola de Linux, apuntando a la raiz: de
        // 40.000 carpetas miradas, el 90% estaban en sitios donde no puede haber musica.
        //
        // QUIEN LO SABE ES EL SISTEMA, cada uno a su manera. En Linux hay respuesta exacta -el sistema dice
        // de que TIPO es cada sitio montado- y por eso alli esto lo contesta Sistema. En Windows hay que ir
        // por el nombre, que son cuatro y bien conocidos. Se compara el nombre de la carpeta en cualquier
        // sitio del disco y no solo en la raiz: nadie llama "Windows" ni "$Recycle.Bin" a una carpeta de
        // musica, y asi tambien vale para un disco que se conecte a otra maquina.
        private static readonly string[] CarpetasDelSistema = {
            "windows", "winnt", "program files", "program files (x86)",
            "archivos de programa", "archivos de programa (x86)", "programdata",
            "$recycle.bin", "recycler", "system volume information", "recovery", "perflogs",
            "msocache", "config.msi", "documents and settings"
        };
        private static bool EsCarpetaDelSistema(string dir)
        {
            try
            {
                // El ultimo tramo, cortando por las dos barras: la ruta puede venir con cualquiera de las
                // dos, y ademas asi esto se puede comprobar desde una maquina que no sea Windows.
                string t = dir.TrimEnd('\\', '/');
                int c = t.LastIndexOfAny(new char[] { '\\', '/' });
                string n = (c >= 0) ? t.Substring(c + 1) : t;
                for (int i = 0; i < CarpetasDelSistema.Length; i++)
                    if (string.Equals(n, CarpetasDelSistema[i], StringComparison.OrdinalIgnoreCase)) return true;
            }
            catch { }
            return false;
        }

        // UNA CARPETA QUE EN REALIDAD ES UN ATAJO A OTRO SITIO. No se sigue, y no es capricho: en un disco de
        // verdad los hay que dan vueltas -"/usr/bin/X11" apunta a si mismo, "/proc/<numero>/root" lleva de
        // vuelta a la raiz- y el recorrido no sale de ahi JAMAS. Medido antes de esto, apuntando al disco
        // entero: 40.000 carpetas y 401.023 archivos en 19 segundos sin terminar; y en la prueba con dos
        // atajos, 77.741 canciones encontradas donde solo habia dos. Es lo mismo que hace cualquier buscador
        // de archivos del sistema.
        //
        // La carpeta que se ELIGIO si se mira aunque sea un atajo -si la eligieron, la quieren-: esto solo
        // decide si se BAJA a los atajos que haya dentro.
        //
        // Y NO SE PIERDE NADA POR EL CAMINO, esta comprobado archivo por archivo: barriendo el disco entero
        // de esta maquina, antes salian 1.657 rutas y ahora 1.582, pero los NOMBRES distintos son 102 en los
        // dos casos. Los 75 de diferencia eran el mismo archivo contado dos veces -"/lib" es un atajo a
        // "/usr/lib", asi que todo lo de dentro salia por partida doble-, que es exactamente la duplicacion
        // que todo esto existe para evitar.
        private static bool EsAtajo(string dir)
        {
            try { return (new DirectoryInfo(dir).Attributes & FileAttributes.ReparsePoint) != 0; }
            catch { return false; }
        }


        // La portada de una carpeta a partir de la lista de archivos que YA se leyo. Mismo criterio de siempre:
        // primero los nombres tipicos (en su orden de preferencia) y, si no hay ninguno, la primera imagen.
        private static string CoverFromList(string folder, string[] files)
        {
            for (int i = 0; i < CoverNames.Length; i++)
                for (int j = 0; j < files.Length; j++)
                    if (string.Equals(Path.GetFileName(files[j]), CoverNames[i], StringComparison.OrdinalIgnoreCase))
                        return Path.Combine(folder, CoverNames[i]);
            for (int i = 0; i < files.Length; i++)
            {
                string ext = Path.GetExtension(files[i]).ToLowerInvariant();
                if (Array.IndexOf(ImgExt, ext) >= 0) return files[i];
            }
            return null;
        }

        private static readonly char[] SepChars = { '\\', '/' };

        // La carpeta del DISCO de una cancion: la subcarpeta de PRIMER nivel bajo su raiz de musica.
        // Asi, si un disco tiene subcarpetas, TODA su musica (a cualquier profundidad) cae DENTRO del
        // mismo disco en vez de aparecer como discos aparte. Si la cancion esta suelta en la raiz, el
        // disco es la raiz misma. Si por lo que sea no cae bajo ninguna raiz, se usa su carpeta inmediata.
        private static string AlbumFolderFor(string filePath, List<string> roots)
        {
            string dir = Path.GetDirectoryName(filePath);
            if (string.IsNullOrEmpty(dir)) return "";
            if (roots != null)
                for (int r = 0; r < roots.Count; r++)
                {
                    string root = roots[r] == null ? "" : roots[r].TrimEnd('\\', '/');
                    if (root.Length == 0) continue;
                    if (string.Equals(dir, root, StringComparison.OrdinalIgnoreCase)) return dir;   // suelta en la raiz -> el disco ES la raiz
                    if (dir.Length > root.Length + 1
                        && dir.StartsWith(root, StringComparison.OrdinalIgnoreCase)
                        && (dir[root.Length] == '\\' || dir[root.Length] == '/'))
                    {
                        int slash = dir.IndexOfAny(SepChars, root.Length + 1);   // fin de la subcarpeta de 1er nivel
                        return (slash < 0) ? dir : dir.Substring(0, slash);      // raiz + 1a subcarpeta (lo mas profundo cae aqui)
                    }
                }
            return dir;   // fuera de toda raiz conocida: como antes (carpeta inmediata)
        }

        private void BuildAlbums(List<string> roots)
        {
            Dictionary<string, Album> byFolder = new Dictionary<string, Album>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < tracks.Count; i++)
            {
                Track t = tracks[i];
                string folder = AlbumFolderFor(t.Path, roots);
                if (folder == null) folder = "";
                Album al;
                if (!byFolder.TryGetValue(folder, out al)) { al = new Album(); al.Folder = folder; byFolder[folder] = al; }
                al.Tracks.Add(t);
            }

            albums = new List<Album>();
            foreach (KeyValuePair<string, Album> kv in byFolder)
            {
                Album al = kv.Value;
                string leaf = LeafName(al.Folder);
                string ar, nm;
                if (SplitArtist(leaf, out ar, out nm)) { al.Artist = ar; al.Name = nm; }
                else { al.Artist = leaf; al.Name = ""; }
                al.Letter = FirstLetter(al.Artist);
                al.CoverPath = FindCoverCached(al.Folder);
                al.Tracks.Sort(delegate (Track a, Track b) { return string.Compare(a.Title, b.Title, StringComparison.OrdinalIgnoreCase); });
                albums.Add(al);
            }

            albums.Sort(delegate (Album a, Album b)
            {
                int c = string.Compare(a.Artist, b.Artist, StringComparison.OrdinalIgnoreCase);
                if (c != 0) return c;
                return string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase);
            });

            byLetter = new Dictionary<char, List<Album>>();
            for (int i = 0; i < albums.Count; i++)
            {
                Album al = albums[i];
                List<Album> lst;
                if (!byLetter.TryGetValue(al.Letter, out lst)) { lst = new List<Album>(); byLetter[al.Letter] = lst; }
                lst.Add(al);
            }
        }

        private static string LeafName(string folder)
        {
            if (string.IsNullOrEmpty(folder)) return "Video";
            string s = folder.TrimEnd('\\', '/');
            string leaf = Path.GetFileName(s);
            return string.IsNullOrEmpty(leaf) ? s : leaf;
        }

        // Separa "Artista - Titulo" o "Artista-Titulo" (guion con o sin espacios). Toma el PRIMER guion.
        private static bool SplitArtist(string s, out string left, out string right)
        {
            left = (s ?? "").Trim(); right = "";
            if (string.IsNullOrEmpty(s)) return false;
            int idx = s.IndexOf(" - ", StringComparison.Ordinal); int len = 3;
            if (idx < 0) { idx = s.IndexOf('-'); len = 1; }
            if (idx <= 0) return false;
            left = s.Substring(0, idx).Trim();
            right = s.Substring(idx + len).Trim();
            return left.Length > 0;
        }

        private static bool AllDigits(string s)
        {
            if (string.IsNullOrEmpty(s)) return false;
            for (int i = 0; i < s.Length; i++) { char c = s[i]; if (c != ' ' && (c < '0' || c > '9')) return false; }
            return true;
        }

        private static string AlbumLabel(Album a)
        {
            if (a == null) return "";
            return (a.Name != null && a.Name.Length > 0) ? (a.Artist + " - " + a.Name) : a.Artist;
        }

        private void BuildVideoSection(List<string> roots)
        {
            // carpeta -> album de audio existente
            Dictionary<string, Album> byFolder = new Dictionary<string, Album>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < albums.Count; i++) { albums[i].VideoFiles.Clear(); byFolder[albums[i].Folder] = albums[i]; }

            Dictionary<string, Album> videoOnly = new Dictionary<string, Album>(StringComparer.OrdinalIgnoreCase);
            // Fuente unica: la lista de videos que ya viene lista (del cache al arrancar, o del recorrido del
            // disco en un escaneo fresco). Antes aqui se volvia a caminar TODO el arbol solo por los videos.
            List<string> vsrc = cachedVideoPaths ?? new List<string>();
            foreach (string vf in vsrc)
            {
                string folder = AlbumFolderFor(vf, roots);
                Album al;
                if (byFolder.TryGetValue(folder, out al)) al.VideoFiles.Add(vf);
                else if (videoOnly.TryGetValue(folder, out al)) al.VideoFiles.Add(vf);
                else
                {
                    al = new Album();
                    al.Folder = folder;
                    al.Artist = LeafName(folder);
                    al.Name = "";
                    al.Letter = FirstLetter(al.Artist);
                    al.CoverPath = FindCoverCached(folder);
                    al.VideoFiles.Add(vf);
                    videoOnly[folder] = al;
                }
            }

            videoAlbums = new List<Album>();
            for (int i = 0; i < albums.Count; i++) if (albums[i].VideoFiles.Count > 0) videoAlbums.Add(albums[i]);
            foreach (KeyValuePair<string, Album> kv in videoOnly) videoAlbums.Add(kv.Value);
            videoAlbums.Sort(delegate (Album a, Album b) { return string.Compare(a.Artist, b.Artist, StringComparison.OrdinalIgnoreCase); });
            for (int i = 0; i < videoAlbums.Count; i++) videoAlbums[i].VideoFiles.Sort(StringComparer.OrdinalIgnoreCase);
            lastVideoPaths = cachedVideoPaths;   // para guardar el cache
        }

        private void BuildSearchIndex()
        {
            searchIndex.Clear();
            // Mapa artista -> todos sus discos (para el cubo que cicla caratulas)
            Dictionary<string, List<Album>> artistAlbums = new Dictionary<string, List<Album>>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < albums.Count; i++)
            {
                Album a = albums[i];
                if (string.IsNullOrEmpty(a.Artist)) continue;
                List<Album> lst;
                if (!artistAlbums.TryGetValue(a.Artist, out lst)) { lst = new List<Album>(); artistAlbums[a.Artist] = lst; }
                lst.Add(a);
            }
            HashSet<string> artistSeen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < albums.Count; i++)
            {
                Album a = albums[i];
                if (!string.IsNullOrEmpty(a.Artist) && artistSeen.Add(a.Artist))
                {
                    SearchItem ar = new SearchItem();
                    ar.Kind = 0; ar.Display = a.Artist; ar.AlbumRef = a;
                    artistAlbums.TryGetValue(a.Artist, out ar.Albums);
                    searchIndex.Add(ar);
                }
                SearchItem alb = new SearchItem();
                alb.Kind = 1; alb.Display = a.Artist + " - " + a.Name; alb.AlbumRef = a;
                searchIndex.Add(alb);
                for (int j = 0; j < a.Tracks.Count; j++)
                {
                    Track t = a.Tracks[j];
                    SearchItem so = new SearchItem();
                    so.Kind = 2; so.Display = t.Artist + " - " + t.Title; so.TrackRef = t; so.AlbumRef = a;
                    searchIndex.Add(so);
                }
            }
            // La parte cara -limpiar acentos y sacar la marca de letras- es la misma cuenta repetida una vez
            // por entrada, y cada entrada solo depende de su propio texto: se puede repartir. Va aparte del
            // bucle de arriba a proposito, para que el indice quede armado y en orden ANTES de repartir.
            ClavesDelIndice();
        }

        // LAS CLAVES DEL BUSCADOR, REPARTIDAS ENTRE LOS NUCLEOS.
        //
        // Cada entrada mira solo su propio texto y escribe solo dentro de si misma, asi que no hay nada
        // compartido que proteger: ni candados ni esperas. Se reparte por TRAMOS y no de una en una porque
        // el trabajo de cada entrada es minusculo y ponerse de acuerdo costaria mas que hacerlo.
        //
        // Aqui si se usan todos los nucleos, al reves que en el repaso de la biblioteca: aquello dura horas
        // y convive con la musica sonando, y esto dura decimas de segundo mientras la rocola todavia esta
        // cargando, sin nada a lo que estorbar. Por debajo de 8000 entradas ni se reparte: arrancar los
        // hilos costaria mas que el trabajo.
        //
        // Al volver de los Join ya no queda nadie tocando el indice, y ademas Join deja a la vista de este
        // hilo todo lo que escribieron los otros: de aqui en adelante el indice se lee como siempre.
        private void ClavesDelIndice()
        {
            int n = searchIndex.Count;
            int hilos = 1;
            if (n >= 8000)
            {
                hilos = Environment.ProcessorCount;
                if (hilos > 4) hilos = 4;
                if (hilos < 1) hilos = 1;
            }
            if (hilos <= 1) { TramoDeClaves(0, n); return; }

            int trozo = (n + hilos - 1) / hilos;
            System.Threading.Thread[] th = new System.Threading.Thread[hilos - 1];
            for (int k = 1; k < hilos; k++)
            {
                int desde = k * trozo;
                int hasta = Math.Min(n, desde + trozo);
                th[k - 1] = new System.Threading.Thread(delegate () { TramoDeClaves(desde, hasta); });
                th[k - 1].IsBackground = true;
                th[k - 1].Start();
            }
            TramoDeClaves(0, Math.Min(n, trozo));   // el hilo que reparte tambien lleva su tramo
            for (int k = 0; k < th.Length; k++) th[k].Join();
        }

        private void TramoDeClaves(int desde, int hasta)
        {
            for (int i = desde; i < hasta; i++)
            {
                SearchItem si = searchIndex[i];
                si.Key = Normalize(si.Display);
                si.Mask = MarcaLetras(si.Key);
            }
        }

        private static char FirstLetter(string s)
        {
            if (string.IsNullOrEmpty(s)) return '#';
            string n = s.Trim();
            if (n.Length == 0) return '#';
            char c = char.ToUpperInvariant(n[0]);
            string norm = c.ToString().Normalize(NormalizationForm.FormD);
            for (int i = 0; i < norm.Length; i++)
                if (CharUnicodeInfo.GetUnicodeCategory(norm[i]) != UnicodeCategory.NonSpacingMark) { c = char.ToUpperInvariant(norm[i]); break; }
            if (c >= 'A' && c <= 'Z') return c;
            return '#';
        }

        private static readonly string[] CoverNames = { "portada.jpg", "portada.jpeg", "portada.png", "cover.jpg", "cover.png", "folder.jpg", "front.jpg" };
        private static readonly string[] ImgExt = { ".jpg", ".jpeg", ".png", ".bmp" };

        private List<Album> CurrentList()
        {
            if (libBuilding) return new List<Album>();   // el worker esta mutando las listas: no leerlas
            if (currentLetter == VideoMark) return videoAlbums ?? new List<Album>();
            if (currentLetter == TopMark) return topDiscs ?? new List<Album>();
            List<Album> list;
            if (!byLetter.TryGetValue(currentLetter, out list)) list = new List<Album>();
            return list;
        }

        private void RefreshAlbums()
        {
            if (currentLetter == TopMark) BuildTopDiscs();   // discos TOP siempre al dia
            List<Album> list = CurrentList();
            int totalPages = Math.Max(1, (list.Count + PageSize - 1) / PageSize);
            if (page < 0) page = 0;
            if (page >= totalPages) page = totalPages - 1;
            if (selAlbumIndex < 0) selAlbumIndex = 0;
            if (selAlbumIndex >= list.Count) selAlbumIndex = Math.Max(0, list.Count - 1);

            // Cambio de pagina/letra -> nueva "generacion": las cargas de la pagina anterior se descartan
            // GRATIS en la bomba (revisa la generacion antes de decodificar). Gracias a eso, la pagina
            // VISIBLE se pide AL INSTANTE, sin esperar nada -> sensacion de carga inmediata. El
            // asentamiento (timer) queda solo para la PRELECTURA de las paginas vecinas.
            bool newPage = false;
            string psig = currentLetter + "|" + page;
            if (psig != lastPageSig)
            {
                lastPageSig = psig; coverGen++;
                newPage = true;
                coversOnHold = true;   // sigue frenando las peticiones nacidas del PINTADO durante el hojeo
                if (coverSettleTimer != null) { coverSettleTimer.Stop(); coverSettleTimer.Start(); }
            }

            List<Album> pageList = new List<Album>();
            int start = page * PageSize;
            for (int i = start; i < start + PageSize && i < list.Count; i++) pageList.Add(list[i]);

            if (newPage)
                for (int i = 0; i < pageList.Count; i++) RequestCover(pageList[i], false, true);   // fila ALTA, ya mismo

            albumView.Page = pageList;
            // La pagina de AL LADO se va horneando mientras nadie toca nada (ver BakeAhead): al pasar de pagina
            // las casillas ya estan listas y el deslizamiento se ve fluido LA PRIMERA VEZ, no solo al volver.
            // Tambien en el ordenador del bar (sin tarjeta grafica), que es justo donde re-escalar 18 caratulas
            // en el momento de pulsar mas se nota.
            List<Album> siguiente = new List<Album>();
            for (int i = start + PageSize; i < start + PageSize * 2 && i < list.Count; i++) siguiente.Add(list[i]);
            albumView.SetAhead(siguiente);
            albumView.Selected = selAlbumIndex - start;
            albumView.SelAngle = 0;
            albumView.CancelHandoff();   // cambio de pagina/letra: cancela cualquier giro de relevo en curso
            albumView.Invalidate();

            headerView.Section = (currentLetter == VideoMark) ? "VIDEOS" : (currentLetter == TopMark) ? "LO MAS SONADO" : ("LETRA " + currentLetter);
            headerView.Page = page; headerView.Total = totalPages;
            headerView.Accent = AcentoSeccion();
            headerView.Invalidate();
            Letter_Refresh();
        }

        // SINCRONO: para portadas sueltas (cubo grande del disco, mini-cubo, buscador). Pocas a la vez.
        // SOLO MEMORIA: si la caratula no esta en cache, la ENCARGA en segundo plano y devuelve null;
        // al llegar se aplica sola (ApplyArrivedCover). Antes decodificaba AQUI MISMO, en el hilo de la
        // interfaz: en disco duro eso congelaba la pantalla al entrar a un disco, al cambiar de cancion
        // y al pintar el buscador (100-500ms por caratula). Ese era el grueso de los tirones.
        // Devuelve la caratula SOLO si ya esta en memoria. No encarga nada al disco. La usa el buscador
        // mientras el cliente barre resultados con la flecha (ver Portada en SearchOverlay).
        private Image PortadaEnMemoria(Album a)
        {
            if (a == null || a.CoverPath == null) return null;
            lock (coverLock) { Image c; if (coverCache.TryGetValue(a.CoverPath, out c)) return c; }
            return null;
        }

        private Image LoadCover(Album a)
        {
            if (a == null || a.CoverPath == null) return null;
            lock (coverLock) { Image c; if (coverCache.TryGetValue(a.CoverPath, out c)) return c; }
            RequestCover(a, false);   // encargar SIN el freno de hojeo (esto no es la rejilla)
            return null;
        }

        // ASINCRONO: para la rejilla (18 portadas por pagina). Devuelve la cacheada o null,
        // y carga en segundo plano para no trabar el cambio de pagina; al terminar, repinta.
        // El usuario se detuvo en una pagina: AHORA si pedimos sus caratulas.
        // (Las paginas que paso de largo nunca se piden: cero trabajo desperdiciado.)
        private void CoverSettle_Tick(object sender, EventArgs e)
        {
            coverSettleTimer.Stop();
            coversOnHold = false;
            List<Album> p = (albumView != null) ? albumView.Page : null;
            if (p != null) for (int i = 0; i < p.Count; i++) LoadCoverAsync(p[i]);
            // PRELECTURA: tambien se encargan las paginas vecinas (despues de la actual, por orden de
            // llegada). En disco duro, hojear con las flechas queda servido directo de la RAM.
            List<Album> all = CurrentList();
            PrefetchPage(all, page + 1);
            PrefetchPage(all, page - 1);
            if (!diskSlow)   // con SSD sobran lecturas: dos paginas de colchon; con HDD, solo una
            {
                PrefetchPage(all, page + 2);
                PrefetchPage(all, page - 2);
            }
        }

        private void PrefetchPage(List<Album> list, int p)
        {
            if (list == null || p < 0) return;
            int start = p * PageSize;
            if (start >= list.Count) return;
            int end = Math.Min(start + PageSize, list.Count);
            for (int i = start; i < end; i++) RequestCover(list[i], true, false);   // fila BAJA: nunca por delante de lo visible
        }

        // Una caratula recien decodificada llega del disco: se aplica donde haga falta.
        private void ApplyArrivedCover(string key)
        {
            try
            {
                if (albumView != null) albumView.RefreshCover(key);
                if (panelSongs != null && panelSongs.Visible && currentAlbum != null && cubeBox != null)
                {
                    if (currentAlbum.IsTop && currentAlbum.TrackCovers != null && songSel >= 0 && songSel < currentAlbum.TrackCovers.Count && currentAlbum.TrackCovers[songSel] == key)
                    { cubeBox.Cover = LoadCoverByPath(key); cubeBox.Invalidate(); }
                    else if (!currentAlbum.IsTop && currentAlbum.CoverPath == key)
                    { cubeBox.Cover = LoadCover(currentAlbum); cubeBox.Invalidate(); }
                }
                if (miniCube != null && miniCube.Visible && nowPlaying != null && nowPlaying.Disc != null && nowPlaying.Disc.CoverPath == key)
                {
                    miniCube.Cover = LoadCover(nowPlaying.Disc); miniCube.Invalidate();
                    // Y EL FONDO. La portada de la que suena puede llegar DESPUES de que empiece la
                    // cancion -se decodifica en otro hilo-, y entonces el color se calculo sin ella.
                    // Aqui ya esta: se vuelve a preguntar, y si ahora dice otra cosa, el fondo viaja
                    // hasta el color nuevo con el mismo fundido lento de siempre (bgAccentTarget).
                    if (fondoPortadaOn && !nowPlaying.IsVideo)
                    {
                        Color acc = ColorDeLoQueSuena(nowPlaying.Song, nowPlaying.Disc);
                        if (acc.ToArgb() != bgAccentTarget.ToArgb()) ApplyGenreBackground(nowPlaying.Song, nowPlaying.Disc);
                    }
                }
                if (searchOpen && searchOverlay != null) searchOverlay.Invalidate();
                // Y las portaditas de la cola: la que faltaba puede ser esta.
                if (pastCola != null && pastCola.ConPortadas) { LlenaPortaditas(); pastCola.Invalidate(); }
            }
            catch { }
        }

        private Image LoadCoverAsync(Album a) { return RequestCover(a, true, true); }

        // ----- DESPACHADOR DE CARATULAS CON PRIORIDAD -----
        // Antes todas las peticiones (pagina actual, prelectura de vecinas, lo que fuera) se formaban
        // revueltas en el mismo turno de disco: a veces las caratulas que ESTAS viendo esperaban detras
        // de la prelectura. Ahora hay dos filas: ALTA (lo visible) y BAJA (prelectura); una sola bomba
        // atiende el disco y SIEMPRE saca primero la fila alta.
        private class CoverJob { public string Key; public int Gen; }
        private readonly List<CoverJob> coverQHi = new List<CoverJob>();
        private readonly List<CoverJob> coverQLo = new List<CoverJob>();
        private int coverPumpCount = 0;   // hasta 2 bombas de decodificacion (una por nucleo)

        private Image RequestCover(Album a, bool respectHold) { return RequestCover(a, respectHold, true); }

        // Carga una caratula por RUTA directa (cache o encargo). Usado por los discos TOP (ciclado de
        // portadas y cambio de portada al navegar canciones).
        private Image LoadCoverByPath(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            lock (coverLock) { Image c; if (coverCache.TryGetValue(key, out c)) return c; }
            RequestCoverByPath(key, false);
            return null;
        }

        private void RequestCoverByPath(string key, bool highPriority)
        {
            if (string.IsNullOrEmpty(key)) return;
            lock (coverLock)
            {
                Image c;
                if (coverCache.TryGetValue(key, out c)) return;
                if (coverLoading.Contains(key)) return;
                coverLoading.Add(key);
                CoverJob j = new CoverJob(); j.Key = key; j.Gen = coverGen;
                if (highPriority) coverQHi.Add(j); else coverQLo.Add(j);
                if (coverPumpCount < coverCarriles)
                {
                    coverPumpCount++;
                    System.Threading.Thread t = new System.Threading.Thread(CoverPump);
                    t.IsBackground = true;
                    t.Priority = System.Threading.ThreadPriority.BelowNormal;   // decodificar caratulas NUNCA por delante de la interfaz/render (clave si el CPU es de un nucleo)
                    t.Start();
                }
            }
        }

        private Image RequestCover(Album a, bool respectHold, bool highPriority)
        {
            if (a == null || a.CoverPath == null) return null;
            string key = a.CoverPath;
            lock (coverLock)
            {
                Image c;
                if (coverCache.TryGetValue(key, out c)) return c;
                if (respectHold && coversOnHold) return null;   // hojeando rapido: todavia no pedir
                if (coverLoading.Contains(key)) return null;
                coverLoading.Add(key);
                CoverJob j = new CoverJob(); j.Key = key; j.Gen = coverGen;
                if (highPriority) coverQHi.Add(j); else coverQLo.Add(j);
                if (coverPumpCount < coverCarriles)   // SSD: un carril por nucleo (hasta 4); HDD: carril unico (cabezal)
                {
                    coverPumpCount++;
                    System.Threading.Thread t = new System.Threading.Thread(CoverPump);
                    t.IsBackground = true;
                    t.Priority = System.Threading.ThreadPriority.BelowNormal;   // idem: la caratula puede esperar; un cuadro perdido se NOTA
                    t.Start();
                }
            }
            return null;
        }

        // Una sola bomba de disco: fila ALTA primero, luego BAJA; termina y se apaga sola.
        private void CoverPump()
        {
            while (true)
            {
                CoverJob j = null;
                lock (coverLock)
                {
                    if (coverQHi.Count > 0) { j = coverQHi[0]; coverQHi.RemoveAt(0); }
                    else if (coverQLo.Count > 0) { j = coverQLo[0]; coverQLo.RemoveAt(0); }
                    else { coverPumpCount--; return; }
                }
                string key = j.Key;
                if (j.Gen != coverGen) { lock (coverLock) { coverLoading.Remove(key); } continue; }
                coverSem.WaitOne();   // turno unico de disco (compartido con el precalentador)
                try
                {
                    if (j.Gen != coverGen) { lock (coverLock) { coverLoading.Remove(key); } continue; }
                    Image thumb = DecodeCover(key);
                    lock (coverLock) { CachePut(key, thumb); coverLoading.Remove(key); }
                    try
                    {
                        if (this.IsHandleCreated)
                            this.BeginInvoke((MethodInvoker)delegate { ApplyArrivedCover(key); });
                    }
                    catch { }
                }
                finally { coverSem.Release(); }
            }
        }

        // Caché de miniaturas en DISCO: la 1a vez decodifica la portada grande y guarda una miniatura
        // pequeña; las siguientes veces lee la miniatura (leer ~30KB es muchisimo mas rapido que decodificar
        // un JPG grande del disco duro). Acelera enormemente volver a ver paginas ya vistas.
        private static string thumbDir;
        private static ImageCodecInfo jpegEnc;

        // DONDE VIVEN LAS MINIATURAS. Iban a la carpeta TEMPORAL del sistema, y eso las condenaba: es una
        // carpeta que por definicion se puede tirar, y Windows la limpia cada tanto -en la rocola de Linux
        // es peor todavia, porque alli esta EN LA MEMORIA y se borra al apagar-. O sea que la promesa de
        // aqui arriba -"la 1a vez tarda; luego todo vuela"- se rompia sola cada cierto tiempo y habia que
        // volver a decodificar la portada grande de cada disco. Medido: 16 ms la primera vez contra 1.5 ms
        // con la miniatura hecha, once veces mas.
        //
        // Ahora van con todo lo demas que la rocola guarda, en la carpeta de datos.
        private static string CarpetaMiniaturas()
        {
            if (thumbDir == null)
            {
                string d = RutaDatos("rocola_miniaturas");
                try { if (!Directory.Exists(d)) Directory.CreateDirectory(d); } catch { }
                thumbDir = d;
            }
            return thumbDir;
        }

        private static string ThumbCachePath(string coverPath)
        {
            ulong h = Fnv64(coverPath.ToLowerInvariant());
            return Path.Combine(CarpetaMiniaturas(), h.ToString("x16") + "_" + ThumbPx + ".jpg");
        }

        // EL BARRIDO. Al salir de la carpeta temporal ya nadie las borra nunca, asi que hay que barrer.
        // Pero NO por "esto ya no esta en la biblioteca": la rocola admite varios discos de musica, y
        // desconectar uno un fin de semana no puede costar reconstruir todas sus portadas. Se barre por
        // EDAD, y solo si la carpeta se ha hecho grande de verdad.
        //
        // El tope es holgado a proposito: una miniatura ocupa unos 23 KB, asi que 200 MB son casi nueve
        // mil discos. En una rocola normal esto no se dispara JAMAS; esta para que la carpeta no pueda
        // crecer sin final en una maquina que lleve anos cambiando de musica.
        //
        // La fecha que se mira es la de cuando se HIZO la miniatura, no la de cuando se uso: apuntar cada
        // uso seria escribir en el disco una vez por portada leida, que es justo lo que todo esto existe
        // para evitar. Como mucho se borra una que seguia en uso, y la proxima vez que se vea ese disco se
        // rehace sola: una portada, 16 ms, y ya esta otra vez.
        private const int MiniaturasTopeMb = 200;    // por debajo de esto no se barre nada
        private const int MiniaturasDiasMax = 365;   // y por encima, solo lo que lleve un ano sin rehacerse
        private static int BarreMiniaturas()
        {
            try
            {
                string d = CarpetaMiniaturas();
                if (d == null || !Directory.Exists(d)) return 0;
                string[] files = Directory.GetFiles(d, "*.jpg");
                long total = 0;
                List<string> viejas = new List<string>();
                DateTime corte = DateTime.UtcNow.AddDays(-MiniaturasDiasMax);
                for (int i = 0; i < files.Length; i++)
                {
                    try
                    {
                        FileInfo fi = new FileInfo(files[i]);
                        total += fi.Length;
                        if (fi.LastWriteTimeUtc < corte) viejas.Add(files[i]);
                    }
                    catch { }
                }
                if (total <= (long)MiniaturasTopeMb * 1024L * 1024L) return 0;
                int fuera = 0;
                for (int i = 0; i < viejas.Count; i++) { try { File.Delete(viejas[i]); fuera++; } catch { } }
                return fuera;
            }
            catch { return 0; }
        }

        private static ulong Fnv64(string s)
        {
            ulong hash = 1469598103934665603UL;
            for (int i = 0; i < s.Length; i++) { hash ^= s[i]; hash *= 1099511628211UL; }
            return hash;
        }

        private static void SaveThumb(Bitmap thumb, string cacheFile)
        {
            try
            {
                if (jpegEnc == null)
                    foreach (ImageCodecInfo ci in ImageCodecInfo.GetImageEncoders()) if (ci.MimeType == "image/jpeg") { jpegEnc = ci; break; }
                if (jpegEnc == null) { thumb.Save(cacheFile); return; }
                using (EncoderParameters ep = new EncoderParameters(1))
                {
                    ep.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 82L);
                    thumb.Save(cacheFile, jpegEnc, ep);
                }
            }
            catch { }
        }

        private static Image DecodeCover(string path)
        {
            string cacheFile = null;
            try { cacheFile = ThumbCachePath(path); } catch { }

            // 1) miniatura en cache -> leerla (rapido)
            if (cacheFile != null)
            {
                try
                {
                    if (File.Exists(cacheFile))
                    {
                        byte[] cdata;
                        if (diskProbeN < 16)   // perfilado: cronometra las primeras lecturas de miniaturas
                        {
                            System.Diagnostics.Stopwatch dsw = System.Diagnostics.Stopwatch.StartNew();
                            cdata = File.ReadAllBytes(cacheFile);
                            dsw.Stop();
                            DiskProbe((int)dsw.ElapsedMilliseconds);
                        }
                        else cdata = File.ReadAllBytes(cacheFile);   // I/O puro primero; GDI+ decodifica desde RAM
                        using (MemoryStream cms = new MemoryStream(cdata))
                        using (Image cimg = Image.FromStream(cms, false, false))
                        {
                            Bitmap tb = new Bitmap(ThumbPx, ThumbPx, PixelFormat.Format32bppPArgb);
                            using (Graphics g = Graphics.FromImage(tb))
                            {
                                // la miniatura YA mide ThumbPx: copia 1:1 (mismos pixeles, sin filtro caro)
                                g.InterpolationMode = InterpolationMode.NearestNeighbor;
                                g.DrawImage(cimg, 0, 0, ThumbPx, ThumbPx);
                            }
                            return tb;
                        }
                    }
                }
                catch { /* cache corrupta -> recodificar abajo */ }
            }

            // 2) decodificar la portada original y GUARDAR la miniatura para la proxima vez
            try
            {
                byte[] data = File.ReadAllBytes(path);   // I/O puro primero (lectura secuencial corta); GDI+ decodifica desde RAM
                using (MemoryStream ms = new MemoryStream(data))
                using (Image src = Image.FromStream(ms, false, false))
                {
                    Bitmap thumb = new Bitmap(ThumbPx, ThumbPx, PixelFormat.Format32bppPArgb);
                    using (Graphics g = Graphics.FromImage(thumb))
                    {
                        g.InterpolationMode = InterpolationMode.HighQualityBilinear;   // filtro original de la miniatura (1 vez por disco)
                        g.PixelOffsetMode = PixelOffsetMode.Half;
                        g.DrawImage(src, 0, 0, ThumbPx, ThumbPx);
                    }
                    if (cacheFile != null) SaveThumb(thumb, cacheFile);
                    return thumb;
                }
            }
            catch { return null; }
        }

        // Guarda en cache acotando el tamaño (FIFO). Llamar SIEMPRE bajo coverLock.
        // Las expulsadas NO se liberan aqui (el hilo de pantalla podria estar dibujandolas):
        // se mandan a la papelera y se liberan en el temporizador, cuando no hay repintado en curso.
        private void CachePut(string key, Image img)
        {
            if (coverCache.ContainsKey(key)) { coverCache[key] = img; return; }
            coverCache[key] = img;
            coverOrder.Enqueue(key);
            while (coverOrder.Count > TopeDePortadas())
            {
                string old = coverOrder.Dequeue();
                Image oldImg;
                if (coverCache.TryGetValue(old, out oldImg)) { coverCache.Remove(old); if (oldImg != null) coverTrash.Add(oldImg); }
            }
        }

        // Libera las carátulas expulsadas. Se llama desde el temporizador (mismo hilo que el dibujo,
        // asi que NUNCA hay un DrawImage en curso). No libera las que sigan en uso por el cubo del disco,
        // el mini-cubo o la animacion de disco (esas las recoge el GC cuando dejen de usarse).
        private void DrainCoverTrash()
        {
            List<Image> dump = null;
            lock (coverLock)
            {
                if (coverTrash.Count == 0) return;
                dump = new List<Image>(coverTrash);
                coverTrash.Clear();
            }
            Image pin1 = (miniCube != null) ? miniCube.Cover : null;
            Image pin2 = (cubeBox != null) ? cubeBox.Cover : null;
#if ROCOLA_GPU
            Image pin3 = transImg;   // la animacion de disco la esta dibujando AHORA: liberarla revienta el render
#else
            Image pin3 = null;
#endif
            for (int i = 0; i < dump.Count; i++)
            {
                Image im = dump[i];
                if (im == null) continue;
                if (im == pin1 || im == pin2 || im == pin3) continue;   // sigue en uso: que lo recoja el GC luego
                try { im.Dispose(); } catch { }
            }
        }

        private void SetSelectedLocal(int local, int dir)
        {
            albumView.MoveSelectionTo(local, dir);   // mueve con efecto de relevo (el anterior gira y se apaga)
            // Y SE REPINTA SOLO LO QUE CAMBIA: las dos casillas, no la pared entera. Medido con
            // pruebas/usando.cs a 1280x1024: 1.75 ms la pared entera contra 0.28 ms las dos casillas, o sea
            // que se repintaba el 92% de la pantalla para nada. Con el freno de flechas son hasta 25
            // pulsaciones por segundo, y ese trabajo se lo estaba quitando al sonido.
            //
            // El cambio de PAGINA y el de LETRA siguen repintando todo, que ahi si cambian las 18 casillas.
            Rectangle r = albumView.RectSeleccion();
            if (r.Width > 0 && r.Height > 0) albumView.Invalidate(r); else albumView.Invalidate();
        }

        private int PageDiscCount()
        {
            int total = CurrentList().Count;
            int c = total - page * PageSize;
            if (c < 0) c = 0;
            if (c > PageSize) c = PageSize;
            return c;
        }

        // Mueve la seleccion DENTRO de la pagina, con CICLO: derecha en el ultimo disco -> vuelve al
        // primero; izquierda en el primero -> va al ultimo. Nunca se atasca (agiliza busquedas cortas).
        private void MoveInPage(int delta)
        {
            int cnt = PageDiscCount();
            if (cnt == 0) return;
            int local = selAlbumIndex - page * PageSize + delta;
            local = ((local % cnt) + cnt) % cnt;   // modulo con negativos: -1 -> ultimo, cnt -> primero
            selAlbumIndex = page * PageSize + local;
            SetSelectedLocal(local, delta);
        }

        private void NextPage()
        {
            int total = CurrentList().Count;
            int totalPages = Math.Max(1, (total + PageSize - 1) / PageSize);
            if (page < totalPages - 1) { page++; selAlbumIndex = page * PageSize; RefreshAlbums(); DeslizaPagina(1); }
            else if (GotoLetter(1, true)) { page = 0; selAlbumIndex = 0; RefreshAlbums(); DeslizaPagina(1); }   // ultima pagina de la ultima seccion: CICLA al inicio
        }

        private void PrevPage()
        {
            if (page > 0) { page--; selAlbumIndex = page * PageSize; RefreshAlbums(); DeslizaPagina(-1); }
            else if (GotoLetter(-1, true))   // primera pagina de la primera seccion: CICLA al final
            {
                int total = CurrentList().Count;
                int tp = Math.Max(1, (total + PageSize - 1) / PageSize);
                page = tp - 1; selAlbumIndex = page * PageSize; RefreshAlbums(); DeslizaPagina(-1);
            }
        }

        // HOJEO: la pagina nueva entra deslizandose por el lado hacia el que vas. Solo por GPU: las casillas ya
        // se dibujan cada cuadro, asi que moverlas no cuesta un dibujo mas. Por CPU no se hace (ahi cada cuadro
        // es repintar de verdad, y eso si costaria).
        private void DeslizaPagina(int dir)
        {
#if ROCOLA_GPU
            if (gpuEnabled && albumView != null && albumView.Visible) albumView.StartSlide(dir, albumView.Width);
#endif
        }

        // Salta a la letra DISPONIBLE siguiente/anterior. Con 'wrap', al pasar el extremo CICLA al otro
        // lado (VIDEO -> TOP/#/A... y viceversa): el abecedario es una rueda, nunca se atasca.
        private bool GotoLetter(int dir, bool wrap)
        {
            string order = LetrasOrden;
            int n = order.Length;
            int idx = order.IndexOf(currentLetter);
            if (idx < 0) idx = 0;
            int steps = wrap ? n : (dir > 0 ? n - 1 - idx : idx);   // sin wrap: hasta el extremo; con wrap: la vuelta completa (incluye regresar a la misma si es la unica)
            for (int k = 1; k <= steps; k++)
            {
                int i = idx + dir * k;
                if (wrap) i = ((i % n) + n) % n;
                if (letterAvailable.Contains(order[i])) { currentLetter = order[i]; return true; }
            }
            return false;
        }

        private void ChangeLetter(int dir)
        {
            if (GotoLetter(dir, true)) { page = 0; selAlbumIndex = 0; RefreshAlbums(); DeslizaPagina(dir); }   // REGRESAR+izq/der: las letras CICLAN
        }

        // LA PORTADA QUE VUELA A LA COLA.
        //
        // Al poner una cancion, su portada sale de la pared y aterriza en la pastilla de la cola. Sin una
        // sola palabra, el cliente ve QUE paso y DONDE quedo su cancion: es la mejor señal posible para
        // alguien que no va a leer un letrero.
        //
        // Y NO SE ESCRIBE UNA ANIMACION NUEVA. La rocola ya sabia llevar una portada de un rectangulo a
        // otro girando -es la del disco que se abre-, asi que esto es un SEGUNDO USO de esa misma pieza
        // con otros dos extremos. De regalo nace apagable: obedece al interruptor de "animacion" que ya
        // existia, porque quien se planta es StartDiscTrans en su primera linea.
        private void VuelaALaCola(Album a)
        {
#if ROCOLA_GPU
            if (pastCola == null || !pastCola.Visible || pastCola.Height < 8) return;
            double ang; RectangleF desde = SelectedDiscRect(out ang);
            // El destino es un cuadrado del alto de la pastilla, centrado en ella: la portada llega, se
            // encoge hasta el tamaño de la capsula y ahi se acaba.
            float lado = pastCola.Height;
            RectangleF hasta = new RectangleF(pastCola.Left + (pastCola.Width - lado) / 2f, pastCola.Top, lado, lado);
            StartDiscTrans(desde, hasta, ang, ang + Math.PI, (a != null) ? RequestCover(a, false, true) : null);
#endif
        }

        private void EnterAlbum(Album a)
        {
#if ROCOLA_GPU
            // De DONDE sale la portada: hay que medirlo ANTES de cambiar de pantalla (luego ese cubo ya no
            // existe). Si se viene del buscador, el origen se fijo antes de cerrarlo.
            double angDesde; RectangleF desde;
            if (transNextFrom.Width >= 8f) { desde = transNextFrom; angDesde = transNextAngle; }
            else desde = SelectedDiscRect(out angDesde);
            transNextFrom = RectangleF.Empty;
#endif
            currentAlbum = a;
            browsingVideo = (currentLetter == VideoMark);
            bool showVideos = browsingVideo || (a != null && a.TopIsVideo);   // seccion VIDEOS o disco TOP de videos
            lblAlbum.Text = browsingVideo ? (AlbumLabel(a) + "   (video)") : AlbumLabel(a);
            songItems.Clear();
            if (showVideos)
            {
                for (int i = 0; i < a.VideoFiles.Count; i++) songItems.Add(new VideoItem(a.VideoFiles[i]));
            }
            else
            {
                for (int i = 0; i < a.Tracks.Count; i++) songItems.Add(a.Tracks[i]);
            }
            songSel = 0;
            songList.OlvidaPagina();   // disco nuevo: se llega a su pagina 1, no se hojea desde el disco anterior
            if (songPager != null) songPager.PonSinAnimar(0);
            FillSongPage();
            cubeBox.Cover = LoadCover(a);
            UpdateTopSongVisuals();   // disco TOP: portada/etiqueta de la cancion seleccionada
            cubeBox.Angle = 0;
            albumView.Visible = false;
            letterBar.Visible = false;
            headerView.Visible = false;
            panelSongs.Visible = true;
            this.Focus();
#if ROCOLA_GPU
            if (gpuPanel != null && gpuEnabled) SyncGpuFullScreen();   // aplica el modo disco YA (transicion atomica)
            // Ya con el interior puesto: la portada vuela de su casilla al cubo GRANDE del disco y se funde con el.
            double angHasta; RectangleF hasta = DiscCubeRect(out angHasta);
            StartDiscTrans(desde, hasta, angDesde, angHasta, (a != null) ? RequestCover(a, false, true) : null);
#endif
        }

#if ROCOLA_GPU
        // Arranca el VIAJE de una portada entre dos CUBOS: sale calcada sobre el cubo de origen (misma celda y
        // mismo giro, asi que no se nota el relevo), gira mientras vuela y aterriza calcada sobre el de destino,
        // donde se funde con el. Sirve para las cuatro transiciones: entrar a un disco (celda de la rejilla ->
        // cubo grande del disco), salir (al reves), entrar al modo atraccion (celda -> cubo gigante) y salir de
        // el. Si falta cualquier cosa (sin GPU, sin portada, cubo invisible) simplemente no se anima: la
        // animacion NUNCA es requisito para que la pantalla cambie.
        private void StartDiscTrans(RectangleF from, RectangleF to, double ang0, double ang1, Image cover)
        {
            transMode = 0; transImg = null;
            if (!transAnimOn) return;
            if (cover == null) { Diag("anim disco: SIN portada (aun no cargaba)"); return; }
            if (gpuPanel == null || !gpuEnabled) { Diag("anim disco: render por CPU, no se anima"); return; }
            if (from.Width < 8f || from.Height < 8f || to.Width < 8f || to.Height < 8f)
            { Diag("anim disco: celda invisible " + (int)from.Width + "x" + (int)from.Height + " -> " + (int)to.Width + "x" + (int)to.Height); return; }
            Diag("anim disco: arranca " + (int)from.Width + "x" + (int)from.Height + " -> " + (int)to.Width + "x" + (int)to.Height);
            transFrom = from; transTo = to; transImg = cover;
            transAng0 = ang0;
            // Un cubo de 4 caras iguales se ve EXACTAMENTE igual cada cuarto de vuelta, asi que basta con
            // ajustar el giro dentro de ese cuarto para aterrizar calcado sobre el cubo de destino. Al camino
            // corto (como mucho +/-45 grados) se le suma un cuarto de vuelta entero: se ve girar de verdad y
            // aun asi encaja al llegar. Mas vueltas en 0.26 s se verian frenéticas.
            const double Cuarto = Math.PI / 2.0;
            double d = ang1 - ang0;
            d -= Math.Floor(d / Cuarto) * Cuarto;          // 0..90 grados
            if (d > Cuarto * 0.5) d -= Cuarto;             // camino CORTO: -45..+45 grados
            transSpin = d + Cuarto;
            transMode = 1;
            transTick = Environment.TickCount;
        }
        private void AbortDiscTrans() { transMode = 0; transImg = null; }

        // Arranca la animacion de VENTANA del buscador (tipo macOS). Al ABRIR se anima la propia textura de UI
        // (que en ese momento YA es el buscador): no se copia ni se sube nada. Al CERRAR esa textura pasa a ser
        // la de navegacion, asi que se guarda una instantanea de lo que habia.
        private void StartWinTrans(bool abriendo)
        {
            AbortWinTrans();
            if (!transAnimOn) return;
            if (gpuPanel == null || !gpuEnabled) return;
            if (!abriendo)
            {
                if (gpuMode != 2 || uiOverlay == null) return;   // el buscador no llego a componerse: nada que animar
                if (uiOverlay.Width < 40 || uiOverlay.Height < 40) return;
                try { winSnap = uiOverlay.Clone(new Rectangle(0, 0, uiOverlay.Width, uiOverlay.Height), PixelFormat.Format32bppPArgb); }
                catch { winSnap = null; return; }
            }
            winMode = abriendo ? 1 : 2;
            winTick = Environment.TickCount;
            Diag(abriendo ? "anim buscador: abre" : "anim buscador: cierra");
        }
        private void AbortWinTrans()
        {
            winMode = 0;
            if (winSnap != null) { try { winSnap.Dispose(); } catch { } winSnap = null; }   // ya no se dibuja: liberarla es seguro
        }
#endif

        // Donde va el CUBO GIGANTE del modo atraccion. Lo usan el render (BuildGpuCubeState) y la animacion de
        // entrada/salida de la atraccion: uno solo lo calcula para que nunca se desfasen.
        private RectangleF AttractCubeRect()
        {
            int w = ClientSize.Width, h = ClientSize.Height;
            int side = (int)(Math.Min(w, h) * 0.40); if (side < 80) side = 80;
            return new RectangleF(w / 2 - side / 2, (h - side) / 2 - 30, side, side);
        }

#if ROCOLA_GPU
        // Los tres cubos de los que puede salir (o a los que puede llegar) el viaje de la portada. Cada uno
        // devuelve EXACTAMENTE la misma celda y el mismo giro con que el render dibuja ese cubo: por eso la
        // portada arranca y aterriza calcada, sin dar el salto que delataria el truco.

        // Cubo GRANDE del buscador (la vista previa del resultado elegido).
        private RectangleF SearchCubeRect(out double ang)
        {
            ang = 0;
            if (searchOverlay == null || !searchOpen) return RectangleF.Empty;   // en GPU el overlay no se pinta: mirar el estado, no Visible
            Rectangle r; Image ca, cb; float f;
            if (!searchOverlay.GetPreviewCube(out r, out ca, out cb, out f)) return RectangleF.Empty;
            if (r.Width < 8 || r.Height < 8) return RectangleF.Empty;
            ang = searchOverlay.PreviewAngle;
            return new RectangleF(searchOverlay.Left + r.X, searchOverlay.Top + r.Y, r.Width, r.Height);
        }

        // Cubo del disco SELECCIONADO en la rejilla.
        private RectangleF SelectedDiscRect(out double ang)
        {
            ang = 0;
            if (albumView == null || !albumView.Visible) return RectangleF.Empty;
            GpuCubeState st = albumView.BuildCubeState();
            if (!st.Sel.Has || st.Sel.W < 8f || st.Sel.H < 8f) return RectangleF.Empty;
            ang = st.Sel.Angle;
            return new RectangleF(albumView.Left + st.Sel.X, albumView.Top + st.Sel.Y, st.Sel.W, st.Sel.H);
        }

        // Cubo GRANDE del interior de un disco.
        private RectangleF DiscCubeRect(out double ang)
        {
            ang = 0;
            if (panelSongs == null || cubeBox == null) return RectangleF.Empty;
            GpuCubeInfo ci = new GpuCubeInfo();
            FillCubeBoxGeom(ref ci, cubeBox, panelSongs.Left + cubeBox.Left, panelSongs.Top + cubeBox.Top);
            if (ci.W < 8f || ci.H < 8f) return RectangleF.Empty;
            ang = ci.Angle;
            return new RectangleF(ci.X, ci.Y, ci.W, ci.H);
        }

        // Estado del VIAJE de la portada para el panel GPU. El recorrido va con suavizado quintico (arranca y
        // frena mas suave que el clasico, se nota "caro"); el giro es el camino corto hasta el cubo de destino
        // mas media vuelta; el bamboleo sube y baja (la portada se ladea al volar y llega derecha); el destello
        // acompana al vuelo; y el fundido entra al final, ya encima del cubo de destino, para que se relevan sin
        // costura. Es como lo pidio el operador: primero el acercamiento y despues el degradado.
        // Convierte el rms de cada banda en la altura 0..1 que se dibuja.
        // - En DECIBELIOS, no lineal: es como oye el oido, y ademas evita que el grave aplaste a todo lo demas.
        // - Con INCLINACION (SpecTilt): en musica real los agudos traen mucha menos energia; sin compensarlos la
        //   aurora seria una loma a la izquierda y nada mas.
        // - La ventana de dB puede ser FIJA porque la biblioteca ya viene nivelada: una cancion bajita y una
        //   fuerte llegan aqui al mismo volumen, asi que la aurora luce igual de viva en las dos.
        // - Sube al instante y baja despacio: asi marca el golpe y no tiembla.
        // Por que casi no se movia: dibujaba el NIVEL de cada banda, y el nivel de una cancion es practicamente
        // constante de principio a fin (para eso la rocola las nivela). O sea que el fondo se quedaba en la misma
        // forma toda la cancion y no se distinguia de un fondo fijo. Las estrellas si se mueven porque no miran el
        // nivel: miran cuanto SOBRESALE del momento anterior, que es lo que uno oye como ritmo.
        //
        // Ahora cada banda hace las dos cosas: un CUERPO estable (el nivel, para que la forma del fondo diga de que
        // va la cancion) y encima un GOLPE que sube cuando esa banda pega por encima de su propio promedio. El
        // golpe es la mitad de la altura, asi que el fondo respira de verdad con la musica sin volverse nervioso.
        private void AvanzaAurora()
        {
            for (int b = 0; b < SpecBands; b++)
            {
                float rms = specNow[b];
                float cuerpo = 0f;
                if (rms > 1e-6f)
                {
                    float db = (float)(20.0 * Math.Log10(rms)) + SpecTilt[b];
                    cuerpo = (db - SpecPisoDb) / SpecRangoDb;
                    if (cuerpo < 0f) cuerpo = 0f; else if (cuerpo > 1f) cuerpo = 1f;
                    cuerpo *= cuerpo * (3f - 2f * cuerpo);   // suavizado: aplana el ruido de fondo y realza los picos
                }
                // PISO MOVIL de la banda (~0.9 s): lo que esta banda ha venido sonando ultimamente.
                float piso = specPiso[b];
                piso += (rms - piso) * 0.045f;
                specPiso[b] = piso;
                // GOLPE: cuanto sobresale AHORA por encima de ese piso. Ataque instantaneo, caida rapida.
                float golpe = 0f;
                if (rms > piso * 1.18f + 0.0008f)
                {
                    golpe = (rms - piso) * 9f;
                    if (golpe > 1f) golpe = 1f;
                }
                float gp = specGolpe[b];
                specGolpe[b] = (golpe > gp) ? golpe : gp * 0.80f;   // ~0.25 s de caida a 24 cuadros/s
                float v = cuerpo * 0.55f + specGolpe[b] * cuerpo * 0.45f;   // el golpe solo luce donde ya hay banda
                if (v > 1f) v = 1f;
                float prev = specVis[b];
                specVis[b] = (v > prev) ? v : prev + (v - prev) * 0.22f;   // sube al instante, baja en ~0.2 s
            }
            // Y la PRESENCIA: sube y baja despacio, para que la aurora no aparezca ni desaparezca de golpe.
            // Sin musica NO cae a cero: cae al REPOSO, que ademas respira (ver AurReposo).
            auroraFase += AurReposoPaso;
            if (auroraFase > 6.2831853f) auroraFase -= 6.2831853f;
            float pico = 0f;
            for (int b = 0; b < SpecBands; b++) if (specVis[b] > pico) pico = specVis[b];
            bool hayMusica = pico > 0.02f;
            // Con musica sube DEPRISA (~1.3 s) hasta arriba; sin ella baja DESPACIO (~3 s) hasta el reposo, y
            // ahi se queda respirando a ese mismo ritmo lento, que es lo que la deja viva sin llamar la
            // atencion. La respiracion NO usa el ritmo rapido: si no, subiria a tirones y bajaria suave.
            // Y LA AURORA FRENA IGUAL. Respira desde antes que la pared, pero hasta ahora no se paraba con
            // nadie: seguia moviendose delante del que estaba eligiendo cancion. Es la misma queja, asi que
            // pasa por la misma cuenta, con la misma quietud y el mismo tope.
            float meta = hayMusica ? 1f : (AurReposo * Respiracion(AurReposoOnda, quietud, auroraFase));
            auroraPres += (meta - auroraPres) * (hayMusica ? 0.075f : 0.014f);
            if (auroraPres < 0f) auroraPres = 0f; else if (auroraPres > 1f) auroraPres = 1f;
        }

        // Estado del FONDO REACTIVO para el panel GPU. El relleno de color se apoya justo encima de la franja
        // de estado (BotStripTop), que es donde el cielo se acaba, y sube desde ahi. Nunca se apaga -sin
        // musica se queda en reposo, ver AurReposo- y se atenua junto con el fondo mientras se navega, para
        // que nunca le pelee a las portadas ni al texto.
        private GpuAurora BuildAuroraState()
        {
            GpuAurora g = new GpuAurora();
            if (auroraAmount <= 0.004f) return g;
            if (auroraPres <= 0.004f) return g;   // solo al arrancar, mientras la presencia sube desde cero
            int h = ClientSize.Height;
            g.Has = true; g.B = specVis;
            g.BaseY = BotStripTop(h) + 6f;
            // ALTO al que llega el color cuando una banda pega a tope. Ahora es un relleno que se desvanece
            // hacia arriba (antes eran focos), asi que puede ocupar bastante mas pantalla sin molestar: lo
            // fuerte se queda pegado abajo y lo de arriba ya casi no se ve. Eso es lo que hace que se note
            // crecer y encoger: con el ajuste de fabrica el color llega a casi el 40% de la pantalla en los
            // golpes y se encoge a menos de la decima parte cuando la cancion afloja.
            g.Alto = h * 1.02f * auroraAmount;
            // COLOR. La intensidad ya NO se dibuja con blanco -eso quemaba el centro y lavaba todo-, sino con
            // TONOS DEL MISMO COLOR: si el genero es morado, lo flojo sale morado oscuro y profundo, lo medio
            // sale del morado del genero, y lo fuerte sale de un morado claro. Nunca se sale de su familia, asi
            // que el fondo se lee como UN color con relieve en vez de como una mancha que se lava en el pico.
            // La escalera va abajo, en TonoPorNivel (la calcula el panel para cada punto).
            //
            // A lo ancho el tono tambien cambia -graves de un lado, agudos del otro- pero MUCHO mas suave que
            // antes (32 grados en vez de 98): asi los colores se funden en vez de parecer dos luces distintas.
            //
            // Y A LO ALTO cambia tambien: el PIE de la cortina lleva el color de la cancion y la PUNTA tira
            // hacia el violeta-rosa, que es lo que hace una aurora de verdad (ver GiroPunta).
            Color baseCol = ColorReactivo(bgAccent);
            float gp = GiroPunta(baseCol);
            g.Rgb = (uint)(GiraTono(baseCol, -10f, 1.00f).ToArgb() & 0x00FFFFFF);        // pie, extremo GRAVE (izquierda)
            g.Rgb2 = (uint)(GiraTono(baseCol, 22f, 0.98f).ToArgb() & 0x00FFFFFF);        // pie, extremo AGUDO (derecha)
            g.RgbA = (uint)(GiraTono(baseCol, gp - 12f, 0.98f).ToArgb() & 0x00FFFFFF);   // punta, extremo GRAVE
            g.Rgb2A = (uint)(GiraTono(baseCol, gp + 18f, 0.96f).ToArgb() & 0x00FFFFFF);  // punta, extremo AGUDO
            // ATENUACION al navegar (la misma idea que baja las estrellas al 45%: mientras alguien esta
            // eligiendo cancion, el fondo se calma y cansa menos la vista). La aurora ya no se queda casi como
            // estaba: baja al 65%. Antes no podia bajar porque estaba floja de por si y desaparecia; ahora sale
            // bastante mas fuerte, asi que en reposo -que es cuando nadie mira de cerca- luce entera, y en
            // cuanto alguien toca una tecla se serena hasta que vuelve a quedarse quieta.
            // 'quieto' va de 0 (alguien esta tocando botones) a 1 (nadie toca nada), siguiendo la misma
            // transicion suave que ya anima bgDim, asi que la aurora se calma y vuelve sin ningun salto.
            float quieto = (bgDim - BgDimLevel) / (1f - BgDimLevel);
            quieto = Clampf(quieto, 0f, 1f);
            g.Dim = (AurNavLevel + (1f - AurNavLevel) * quieto) * auroraPres;   // la presencia hace el fundido de entrada y de salida
            g.DimFilo = AurNavFilo + (1f - AurNavFilo) * quieto;
            // CUANTO HAY DE REPOSO en lo que se ve: 0 con la cancion sonando, 1 con la rocola callada. Es lo
            // que le dice al panel si tiene que dibujar la forma lenta (AurCalma) en vez de las bandas. Va
            // pegado a la presencia, asi que el relevo entre una y otra es el mismo fundido suave de siempre.
            // La cuenta se mide contra el punto MAS ALTO de la respiracion: asi, en todo el rato que la
            // rocola esta callada, el reposo vale 1 entero y su forma no cambia de tamano al respirar (lo que
            // respira es el brillo, que es la presencia). Con musica cae a cero solo.
            float cal = (1f - auroraPres) / (1f - AurReposo * (1f + AurReposoOnda));
            g.Calma = (cal < 0f) ? 0f : (cal > 1f ? 1f : cal);
            return g;
        }

        // COLOR DE LA CANCION para el fondo reactivo. NO vale el color del cielo: el cielo de abajo ya es el
        // color del genero apagado, asi que pintar encima el mismo color apagado no se ve. Aqui se toma el
        // color del genero y se sube a su brillo pleno, conservando el tono. Sobre el cielo oscuro eso SI se
        // ve: es el color de la cancion, no un aclarado del fondo. De ahi para abajo, la escalera de tonos
        // (TonoPorNivel) lo lleva de un tono hondo cuando afloja a uno claro cuando pega.
        private static Color ColorReactivo(Color accent)
        {
            int mx = accent.R; if (accent.G > mx) mx = accent.G; if (accent.B > mx) mx = accent.B;
            if (mx < 10) return Color.FromArgb(255, 60, 120, 235);   // sin genero: el azul de siempre
            return Color.FromArgb(255, accent.R * 250 / mx, accent.G * 250 / mx, accent.B * 250 / mx);
        }


        // CUANTO se gira el color al subir por la cortina (grados). En las auroras de verdad la punta tira
        // SIEMPRE hacia el violeta o el rosa, sea del color que sea el pie: el verde se vuelve magenta y el
        // cian se vuelve violeta. Girar siempre los mismos grados no sirve, porque desde un naranja te lleva
        // al verde pistacho y queda sucio. Aqui se gira hacia la zona violeta-rosa por el camino mas corto y
        // a poco mas de medio camino, con un giro MINIMO para que el color viaje tambien cuando el genero ya
        // es morado, y un TOPE para que nunca se vaya al otro lado de la rueda.
        internal static float GiroPunta(Color c)
        {
            float d = 300f - TonoDe(c);
            while (d > 180f) d -= 360f; while (d < -180f) d += 360f;
            float g = d * 0.55f;
            float mag = (g < 0f) ? -g : g;
            if (mag < 35f) g = (g < 0f) ? -35f : 35f;
            else if (mag > 75f) g = (g < 0f) ? -75f : 75f;
            return g;
        }

        private GpuTrans BuildTransState()
        {
            GpuTrans g = new GpuTrans();
            if (transMode == 0 || transImg == null) return g;
            float t = (Environment.TickCount - transTick) / (float)TransMs;   // avance EN VIVO: fluido a los fps del render
            if (t < 0f) t = 0f; else if (t > 1f) t = 1f;
            float e = t * t * t * (t * (t * 6f - 15f) + 10f);      // suavizado quintico
            RectangleF a = transFrom, b = transTo;
            g.Has = true; g.Bmp = transImg as Bitmap;
            if (g.Bmp == null) { g.Has = false; return g; }
            g.X = a.X + (b.X - a.X) * e; g.Y = a.Y + (b.Y - a.Y) * e;
            g.W = a.Width + (b.Width - a.Width) * e; g.H = a.Height + (b.Height - a.Height) * e;
            g.Angle = transAng0 + transSpin * e;                   // gira mientras viaja y llega alineado
            double s = Math.Sin(Math.PI * t);
            g.Tilt = (float)(s * 0.14);                            // bamboleo: se ladea y vuelve a enderezarse
            g.Glow = (float)s;                                     // destello: nace, brilla a media ruta y se apaga
            if (t < TransHold) g.Alpha = 1f;                       // opaca casi todo el viaje
            else { float k = (t - TransHold) / (1f - TransHold); g.Alpha = 1f - k * k * (3f - 2f * k); }
            return g;
        }

        // Estado de la animacion de VENTANA (el buscador) para el panel GPU, imitando a macOS:
        //  - ABRIENDO: entra al 86% de su tamano y un poco mas abajo, se pasa un pelin de su tamano final y
        //    REBOTA hasta asentarse, mientras aparece de golpe (el fundido acaba a media animacion). El rebote
        //    es algo mayor a lo ancho que a lo alto, asi que se "estira" un instante: es lo que le da vida.
        //  - CERRANDO: primero toma IMPULSO (crece un pelin) y luego se va encogiendo, hundiendose y acelerando.
        private GpuWin BuildWinState()
        {
            GpuWin g = new GpuWin();
            if (winMode == 0) return g;
            float t = (Environment.TickCount - winTick) / (float)WinMs;
            if (t < 0f) t = 0f;
            if (t >= 1f) return g;   // RED DE SEGURIDAD: pasado el tiempo se da por terminada aunque el temporizador
                                     // no la haya apagado todavia, asi la UI nunca se puede quedar escondida.
            if (winMode == 1)
            {
                float u = t - 1f;
                float e = 1f + 4.2f * u * u * u + 3.2f * u * u;      // frenado con REBOTE: se pasa ~1.3x y vuelve
                float ey = 1f + 3.2f * u * u * u + 2.2f * u * u;     // vertical: rebota menos -> se estira un instante
                g.Scale = 0.86f + 0.14f * e;
                g.ScaleY = 0.86f + 0.14f * ey;
                g.Dy = (1f - e) * 22f;                              // sube un poco al abrirse (y se pasa un pelin)
                g.Alpha = t * 2.4f; if (g.Alpha > 1f) g.Alpha = 1f; // ya visible en el primer tercio
                g.Bmp = null; g.HideUi = true;                      // se anima la PROPIA textura de UI (ya es el buscador)
            }
            else
            {
                float e = t * t;                                    // acelera (ease-in): se va rapido
                float imp = 0.34f * t * (1f - t) * (1f - t);         // IMPULSO: crece ~3% al arrancar y se desvanece
                g.Scale = 1f - 0.16f * e + imp;
                g.ScaleY = 1f - 0.16f * e + imp * 0.6f;             // estira un poco a lo ancho al tomar impulso
                g.Dy = e * 14f;                                     // se hunde un poco al cerrarse
                g.Alpha = 1f - e;
                g.Bmp = winSnap; if (g.Bmp == null) return g;       // la textura de UI ya es la de navegacion
                g.HideUi = false;                                   // esa UI (la rejilla) SI se dibuja: la ventana se va sobre ella
            }
            g.Has = true;
            return g;
        }
#endif

        private void BackToAlbums()
        {
#if ROCOLA_GPU
            Album saliendo = currentAlbum;   // para el viaje de vuelta (se usa mas abajo)
            double angDesde; RectangleF desde = DiscCubeRect(out angDesde);   // el cubo GRANDE del disco, antes de cerrarlo
#endif
            panelSongs.Visible = false;
            albumView.Visible = true;
            letterBar.Visible = true;
            headerView.Visible = true;
            this.Focus();
#if ROCOLA_GPU
            if (gpuPanel != null && gpuEnabled) SyncGpuFullScreen();   // aplica el modo navegacion YA: no ver el interior detras un instante
            // Ya con la rejilla puesta, la casilla del disco existe otra vez: ahi es donde aterriza la portada.
            double angHasta; RectangleF hasta = SelectedDiscRect(out angHasta);
            StartDiscTrans(desde, hasta, angDesde, angHasta, (saliendo != null) ? RequestCover(saliendo, false, true) : null);
#endif
        }

        private void NavigateToAlbum(Album a)
        {
            if (a == null) return;
            currentLetter = a.Letter;
            List<Album> list = CurrentList();
            int gi = list.IndexOf(a);
            if (gi < 0) gi = 0;
            selAlbumIndex = gi;
            page = (PageSize > 0) ? gi / PageSize : 0;
            if (panelSongs.Visible) BackToAlbums();
            RefreshAlbums();
        }

        // Mueve la seleccion en la lista de canciones. Paso de a UNO (arriba/abajo): CICLA en los extremos
        // (ultima -> primera y al reves), igual que los discos. Salto de PAGINA (izq/der): se detiene en los
        // bordes (teletransportarse de la ultima pagina a la primera a mitad de lista confundiria).
        private void MoveSong(int delta)
        {
            if (songItems.Count == 0) return;
            songSel += delta;
            if (delta == 1 && songSel >= songItems.Count) songSel = 0;
            else if (delta == -1 && songSel < 0) songSel = songItems.Count - 1;
            if (songSel < 0) songSel = 0;
            if (songSel >= songItems.Count) songSel = songItems.Count - 1;
            FillSongPage();
            UpdateTopSongVisuals();
        }

        // En un disco TOP: la portada del cubo y la etiqueta cambian a las del DISCO DE ORIGEN de la
        // cancion seleccionada (asi el cliente sabe de que artista/album es). En discos normales no hace nada.
        private void UpdateTopSongVisuals()
        {
            if (currentAlbum == null || !currentAlbum.IsTop) return;
            int i = songSel;
            if (currentAlbum.TrackCovers != null && i >= 0 && i < currentAlbum.TrackCovers.Count && cubeBox != null)
            {
                cubeBox.Cover = LoadCoverByPath(currentAlbum.TrackCovers[i]);
                cubeBox.Invalidate();
            }
            if (currentAlbum.TrackInfo != null && i >= 0 && i < currentAlbum.TrackInfo.Count && lblAlbum != null)
                lblAlbum.Text = AlbumLabel(currentAlbum) + "   /   " + currentAlbum.TrackInfo[i];
        }

        // Filas que caben en UNA pagina de la lista (se adapta a cualquier resolucion de pantalla).
        private int SongRowsPerPage()
        {
            return (songList != null) ? songList.RowsPerPage : 1;
        }

        // Apunta la lista a la PAGINA donde cae la seleccion (songSel) y actualiza la barra de paginas.
        // El CONTENIDO de la lista cambio (llego un genero, una duracion, se movio la cola...). La lista se
        // dibuja horneada, asi que ademas de repintar hay que avisar de que lo horneado ya no vale. Todos los
        // sitios que tocan el contenido pasan por aqui: asi no se puede olvidar ninguno (lo vigila la bateria).
        private void RefrescaLista()
        {
            if (songList == null) return;
            songList.Datos++;
            songList.Invalidate();
        }

        private void FillSongPage()
        {
            if (songItems.Count == 0)
            {
                if (songPager != null) songPager.Visible = false;
                songList.PageStart = 0; songList.Sel = -1; songList.Invalidate();
                return;
            }
            if (songSel < 0) songSel = 0;
            if (songSel >= songItems.Count) songSel = songItems.Count - 1;
            int rpp = SongRowsPerPage();
            int pages = (songItems.Count + rpp - 1) / rpp;
            int pg = songSel / rpp;
            // HOJEO ANIMADO: si la pagina cambia y el disco tiene mas de una, la que dejas sale por un lado y
            // la que eliges entra por el otro. Se avisa ANTES de mover PageStart, que es cuando lo horneado
            // todavia es la pagina que se va.
            int arranque = pg * rpp;
            if (pages > 1 && songList.PageStart != arranque && panelSongs != null && panelSongs.Visible)
                songList.StartSlide(arranque > songList.PageStart ? 1 : -1);
            songList.PageStart = arranque; songList.Sel = songSel; songList.Accent = bgAccent;
            songList.Invalidate();
            if (songPager != null)
            {
                songPager.Page = pg; songPager.Pages = pages;
                songPager.Visible = pages > 1;
                songPager.Invalidate();
            }
        }

        private void EnqueueSelectedSong()
        {
            if (songSel < 0 || songSel >= songItems.Count) return;
            object item = songItems[songSel];
            VideoItem vi = item as VideoItem;
            if (vi != null)
            {
                Album vdisc = currentAlbum;
                if (currentAlbum != null && currentAlbum.IsTop && currentAlbum.TrackAlbums != null && songSel >= 0 && songSel < currentAlbum.TrackAlbums.Count)
                    vdisc = currentAlbum.TrackAlbums[songSel];   // disco real de origen del video
                AddVideoToQueue(vi.Path, vdisc);
            }
            else
            {
                Album disc = currentAlbum;
                if (currentAlbum != null && currentAlbum.IsTop && currentAlbum.TrackAlbums != null && songSel >= 0 && songSel < currentAlbum.TrackAlbums.Count)
                    disc = currentAlbum.TrackAlbums[songSel];   // disco real de origen (no el de genero)
                AddSong((Track)item, disc);
            }
        }

        private void ToggleSearch() { if (searchOpen) CloseSearch(); else OpenSearch(); }

        private void EnterAttract()
        {
            // La rocola se queda sola: si ahora le tocan mas carriles para medir la biblioteca, se los toma.
            // Va lo PRIMERO, antes de armar la pantalla de atraccion, para no perder ese rato.
            RevisaCarriles();
#if ROCOLA_GPU
            AbortDiscTrans(); AbortWinTrans();   // lo que hubiera volando ya no aplica: la atraccion cambia toda la pantalla
#endif
            if (attractView == null || libBuilding) return;   // el worker esta armando 'albums': muestrearlo aqui seria una carrera (crash)
            // FIX: si la atraccion entra con el INTERIOR DE UN DISCO abierto, la textura de UI seguia
            // dibujando el interior encima del cielo de atraccion (la firma de UI mira el interior antes
            // que la atraccion) -> pantalla revuelta. Ademas el disco del cliente anterior quedaria
            // abierto al salir. Se cierra el interior ANTES de componer la atraccion, en ambos renders.
            if (panelSongs != null && panelSongs.Visible) BackToAlbums();
            // muestrear portadas repartidas por toda la coleccion (variedad) para el cubo
            List<string> covers = new List<string>();
            int na = albums.Count;
            if (na > 0)
            {
                int start = new Random().Next(na);
                int stride = (na > 120) ? na / 60 : 1;
                for (int k = 0; k < na * 2 && covers.Count < 60; k++)
                {
                    Album al = albums[(start + k * stride) % na];
                    if (al.CoverPath != null && !covers.Contains(al.CoverPath)) covers.Add(al.CoverPath);
                }
            }
            attractView.CycleCovers = covers;
            attractView.SongCount = tracks.Count;
            attractView.Phase = phase;
            for (int i = 0; i < covers.Count && i < 3; i++) RequestCoverByPath(covers[i], true);   // adelantar las primeras
            attractOn = true;
#if ROCOLA_GPU
            if (gpuEnabled && gpuPanel != null)
            {
                // La atraccion se compone por GPU: el control CPU no se pinta (queda oculto detras del panel).
                attractView.Visible = false;
                uiOverlaySig = SigNada;   // fuerza rehacer la textura de UI (textos de atraccion)
                gpuPanel.Visible = true; gpuPanel.BringToFront();
                SyncGpuFullScreen();   // aplica el modo atraccion YA (transicion atomica, como los demas modos)
                // La portada del disco que estaba elegido VUELA hasta el cubo gigante de la atraccion y se funde
                // con el: la misma animacion que al entrar a un disco, pero con el cubo gigante como destino.
                List<Album> lst = CurrentList();
                Album selAlb = (selAlbumIndex >= 0 && selAlbumIndex < lst.Count) ? lst[selAlbumIndex] : null;
                double angDesde; RectangleF desde = SelectedDiscRect(out angDesde);
                StartDiscTrans(desde, AttractCubeRect(), angDesde, attractView.Angle,
                               (selAlb != null) ? RequestCover(selAlb, false, true) : null);
            }
            else
#endif
            {
                attractView.Visible = true;
                attractView.BringToFront();
            }
        }

        private void ExitAttract()
        {
            // Y AQUI ES DONDE FRENA, que es lo que de verdad importa: alguien acaba de tocar un boton y el
            // pre-analisis vuelve a su unico carril antes de que se note nada en la pantalla.
            RevisaCarriles();
#if ROCOLA_GPU
            Image portadaAtraccion = null;   // la que muestra el cubo gigante AHORA: hay que leerla ANTES de apagar la atraccion
            double angAtraccion = 0;
            if (attractView != null && gpuPanel != null && gpuEnabled)
            { Image c2; float f2; attractView.GetCoverPair(out portadaAtraccion, out c2, out f2); angAtraccion = attractView.Angle; }
#endif
            attractOn = false;
            if (attractView != null) attractView.Visible = false;
#if ROCOLA_GPU
            uiOverlaySig = SigNada;   // rehace la textura de UI de inmediato (deja los textos de atraccion por la barra normal)
            if (gpuPanel != null && gpuEnabled)
            {
                SyncGpuFullScreen();   // aplica el modo navegacion YA (sin un cuadro mezclado de por medio)
                // Ya con la rejilla puesta: el cubo gigante se encoge hasta la casilla del disco elegido y se funde.
                double angHasta; RectangleF hasta = SelectedDiscRect(out angHasta);
                StartDiscTrans(AttractCubeRect(), hasta, angAtraccion, angHasta, portadaAtraccion);
            }
#endif
            this.Invalidate();
        }

        private void MarkSearchActivity() { searchLastActivity = DateTime.Now; }

        // ---------- CUANDO SE POSA LA CONSULTA ----------
        //
        // Mientras las letras estan entrando nadie esta leyendo los resultados, asi que moverlos en cada
        // una es trabajo tirado: 2.80 ms de rehacer y subir la pantalla completa a 1920, mas 3.07 ms de
        // rehornear las 40 tarjetas, POR LETRA. Se espera a que la persona pare.
        //
        // 220 ms. Se probaron 150 y se quedaba corto: a cinco letras por segundo -que es teclear normal en
        // un teclado de verdad- cada letra caia fuera de la espera y no se ahorraba nada. Con 220 entran los
        // dos ritmos rapidos y sigue siendo menos de lo que se tarda en leer una palabra. Y en la rocola del
        // bar, donde las letras se eligen con las flechas y tardan casi un segundo, esto no cambia nada: se
        // posa en cada letra, como siempre.
        internal const int PosarMs = 220;
        private int tecleoUltimo;                       // cuando entro la ultima letra
        private System.Windows.Forms.Timer posaTimer;

        // ¿Se posa YA, o se espera a que pare? Tras un rato sin teclear -abrir el buscador y escribir la
        // primera letra- se posa en el acto: si esa primera tardara, se notaria y pareceria que la rocola
        // no hace caso. Pura, para poder darle casos a mano.
        internal static bool PosarYa(int msDesdeLaUltimaTecla) { return msDesdeLaUltimaTecla >= PosarMs; }

        private void AlTeclearBusqueda()
        {
            int ahora = Environment.TickCount;
            bool ya = PosarYa(ahora - tecleoUltimo);
            tecleoUltimo = ahora;
            if (posaTimer != null) posaTimer.Stop();
            if (ya) { if (searchOverlay != null) searchOverlay.PosaConsulta(); return; }
            if (posaTimer != null) posaTimer.Start();
        }

        // El buscador NO cubre la franja de estado de abajo (cancion, progreso, creditos, cola): se
        // recorta su alto justo encima. La barra de estado va de (H - pad - 68) hacia abajo (ver
        // LayoutControls); aqui dejamos esa franja libre.
        private Rectangle SearchOverlayRect()
        {
            int W = ClientSize.Width, H = ClientSize.Height;
            int h = H - 14 - 68 - 4;          // tope de la barra de estado, menos un pequeno respiro
            if (h < 260) h = H;               // pantalla muy baja: cubrir todo (respaldo)
            return new Rectangle(0, 0, W, h);
        }

        private void OpenSearch()
        {
            searchOpen = true;
            searchLastActivity = DateTime.Now;
            lastQuery = null; lastMatches = null;   // empezar busqueda limpia
            if (video != null) video.Visible = false;   // el ActiveX se pinta encima del buscador; lo ocultamos
            searchOverlay.Accent = bgAccent;
            searchOverlay.SetQuery("");
            searchOverlay.Results = new List<SearchItem>();
            searchOverlay.SelRow = 1; searchOverlay.SelCol = 0;
            searchOverlay.Bounds = SearchOverlayRect();
#if ROCOLA_GPU
            if (gpuEnabled && gpuPanel != null)
            {
                // El buscador se compone por GPU: el control CPU NO se pinta (queda oculto detras del panel).
                // La entrada sigue funcionando por el formulario (ProcessCmdKey + Form_KeyPress con KeyPreview).
                searchOverlay.Visible = false;
                gpuPanel.Visible = true; gpuPanel.BringToFront();
                SyncGpuFullScreen();   // aplica el modo buscador YA (ShowAlbum=false + UI urgente): transicion atomica, sin ver la rejilla un instante
                StartWinTrans(true);   // la ventana del buscador se abre creciendo (tipo macOS)
            }
            else
#endif
            {
                searchOverlay.Visible = true;
                searchOverlay.BringToFront();
                searchOverlay.Focus();
            }
            searchOverlay.Invalidate();
        }

        private void CloseSearch()
        {
#if ROCOLA_GPU
            StartWinTrans(false);   // copia el buscador AHORA (en el proximo cuadro la textura de UI ya sera la rejilla)
#endif
            if (posaTimer != null) posaTimer.Stop();   // el buscador se va: no queda consulta que posar
            searchOpen = false;
            searchOverlay.Visible = false;
            if (videoOn && video != null) { video.Visible = true; video.BringToFront(); }
            this.Focus();
#if ROCOLA_GPU
            // Aplica el cambio de modo YA (no esperes al proximo AnimTimer, ~40ms). SyncGpuFullScreen detecta la
            // transicion buscador->navegacion y fuerza rehacer la UI en el MISMO cuadro en que reaparece la
            // rejilla de discos; si no, se veria la rejilla por los huecos del teclado un instante.
            if (gpuPanel != null && gpuEnabled) SyncGpuFullScreen();
#endif
        }

        // MARCA DE LETRAS. Un numero de 32 bits que dice QUE letras contiene un texto. Con el se descarta
        // de un plumazo, SIN mirarle el texto, toda entrada a la que le falte alguna letra de lo tecleado:
        // si al cliente le falta una sola de sus letras, esa cancion no puede casar ni entera ni por
        // palabras. Comparar dos numeros cuesta nada; recorrer el titulo tres veces, no.
        // Bits 0..25 = letras a..z ; bit 26 = alguna cifra ; bit 27 = cualquier otro caracter. Los espacios
        // no cuentan. Meter todo lo raro en un mismo bit es a proposito: puede dejar pasar candidatos de
        // mas -que luego descarta Score-, pero nunca puede tirar uno bueno.
        private static int MarcaLetras(string s)
        {
            int m = 0;
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (c == ' ') continue;
                if (c >= 'a' && c <= 'z') m |= 1 << (c - 'a');
                else if (c >= '0' && c <= '9') m |= 1 << 26;
                else m |= 1 << 27;
            }
            return m;
        }

        // OPTIMIZACION (busqueda): q.Split(' ') se calculaba DENTRO de Score, que corre por CADA
        // entrada de searchIndex (decenas de miles) en CADA tecla. Ahora se recibe ya calculado
        // (una sola vez por tecla desde RecomputeResults). El puntaje es identico.
        private static int Score(string cand, string q, string[] toks)
        {
            if (q.Length == 0) return 0;
            if (cand == q) return 10000;
            if (cand.StartsWith(q, StringComparison.Ordinal)) return 6000 - Math.Min(cand.Length, 2000);
            // UNA sola pasada por el texto. Antes se recorria DOS veces: una buscando " q" (empieza palabra)
            // y otra buscando "q" (en cualquier sitio). Para los que NO casan -que son la inmensa mayoria del
            // indice- las dos recorrian el texto ENTERO antes de rendirse. Ahora se busca "q" una vez y se
            // mira si la letra de delante era un espacio, que es lo mismo que buscar " q".
            int primera = -1;
            int pos = cand.IndexOf(q, StringComparison.Ordinal);
            while (pos >= 0)
            {
                if (primera < 0) primera = pos;
                if (pos > 0 && cand[pos - 1] == ' ') return 4000 - (pos - 1);
                pos = cand.IndexOf(q, pos + 1, StringComparison.Ordinal);
            }
            if (primera >= 0) return 2000 - Math.Min(primera, 1500);
            // Coincidencia por PALABRAS: todas las palabras de la consulta aparecen (en cualquier orden).
            // Asi "metallica black" encuentra "Metallica - Black Album", y "enter metallica" tambien.
            if (toks != null)
            {
                int sc = 0, real = 0;
                for (int i = 0; i < toks.Length; i++)
                {
                    string tk = toks[i];
                    if (tk.Length == 0) continue;
                    real++;
                    int at = cand.IndexOf(tk, StringComparison.Ordinal);
                    if (at < 0) return 0;   // falta una palabra -> no coincide
                    bool wordStart = (at == 0) || (cand[at - 1] == ' ');
                    sc += (wordStart ? 300 : 150) - Math.Min(at, 100);
                }
                if (real >= 2) return 800 + sc;   // menos que substring directo, pero cuenta como coincidencia
            }
            return 0;
        }

        private void RecomputeResults(string query)
        {
            MarkSearchActivity();
            if (libBuilding)   // el worker esta llenando searchIndex: no iterarlo (carrera = crash)
            {
                searchOverlay.Results = new List<SearchItem>();
                searchOverlay.Invalidate();
                return;
            }
            string q = Normalize(query);
            List<SearchItem> res = new List<SearchItem>();
            if (q.Length > 0)
            {
                // OPTIMIZACION (busqueda): partes derivadas de la consulta calculadas UNA vez por tecla,
                // no por cada candidato del indice.
                string[] toks = (q.IndexOf(' ') >= 0) ? q.Split(' ') : null;
                int qMask = MarcaLetras(q);
                // Incremental: si la nueva busqueda EMPIEZA con la anterior, las coincidencias nuevas
                // son un subconjunto de las anteriores -> re-evaluamos solo esas (mucho menos trabajo).
                List<SearchItem> source =
                    (lastQuery != null && lastQuery.Length > 0 && lastMatches != null && q.StartsWith(lastQuery, StringComparison.Ordinal))
                    ? lastMatches : searchIndex;

                // LA PRIMERA LETRA ES LA CARA. Con una sola letra tecleada, la marca de letras no descarta a
                // nadie -casi todas las canciones tienen una "a"- asi que hay que puntuar el indice ENTERO:
                // 3.2 ms de 20.000 entradas, contra 0.07 ms cuando ya hay tres letras. Y es la que mas se
                // nota, porque es la que abre cada busqueda.
                //
                // Como para una letra suelta el resultado es SIEMPRE el mismo mientras no cambie la musica, se
                // guarda: la primera vez que alguien teclea una "a" cuesta lo de siempre, y todas las demas
                // veces de la noche sale de memoria (medido: 10 veces menos, ver pruebas/bolsa.cs). Se guardan
                // tambien los puntos, porque el orden depende de ellos y cada busqueda los pisa.
                //
                // Cabe de sobra: con 8.000 canciones, la bolsa de la letra que mas casa son 96 KB.
                List<SearchItem> matches = null;
                BolsaLetra bolsa = null;
                if (q.Length == 1 && bolsaLetra.TryGetValue(q[0], out bolsa) && bolsa != null)
                {
                    matches = bolsa.Lista;
                    for (int i = 0; i < matches.Count; i++) matches[i].Score = bolsa.Puntos[i];   // los puntos, que otra busqueda los piso
                }
                else
                {
                    matches = new List<SearchItem>();
                    int cuantos = source.Count;
                    for (int i = 0; i < cuantos; i++)
                    {
                        SearchItem si = source[i];
                        if ((si.Mask & qMask) != qMask) continue;   // le falta alguna letra: imposible que case
                        int sc = Score(si.Key, q, toks);
                        if (sc > 0) { si.Score = sc; matches.Add(si); }
                    }
                    if (q.Length == 1)
                    {
                        BolsaLetra nb = new BolsaLetra();
                        nb.Lista = matches; nb.Puntos = new int[matches.Count];
                        for (int i = 0; i < matches.Count; i++) nb.Puntos[i] = matches[i].Score;
                        bolsaLetra[q[0]] = nb;
                    }
                }
                // De todo lo que casa solo se ENSENAN 40. Ordenar la lista entera para tirar el resto era el
                // gasto grande del buscador: con veinte mil canciones y una sola letra tecleada casan veinte
                // mil, y ordenarlas costaba 13 ms POR TECLA. Quedarse con los 40 mejores de una pasada cuesta
                // 0.19 ms. La lista sin ordenar se guarda igual, porque para acotar la busqueda de la tecla
                // siguiente lo unico que importa es QUIENES casan, no en que orden.
                lastMatches = matches; lastQuery = q;
                TomaMejores(matches, res, 40);
            }
            else { lastMatches = null; lastQuery = null; }
            searchOverlay.Results = res;
            searchOverlay.Invalidate();
        }

        // El orden en que se ensenan los resultados: primero el que mejor casa, a igualdad antes el artista
        // que el disco y antes el disco que la cancion, y a igualdad de todo, por nombre.
        private static int ComparaHit(SearchItem a, SearchItem b)
        {
            if (b.Score != a.Score) return b.Score - a.Score;
            if (a.Kind != b.Kind) return a.Kind - b.Kind;
            return string.Compare(a.Display, b.Display, StringComparison.OrdinalIgnoreCase);
        }

        // Los N mejores de una lista, SIN ordenar el resto. Se recorre una vez manteniendo una lista corta
        // ordenada: cada candidato solo se compara con el peor de los que ya estan dentro, y solo si lo mejora
        // se le hace sitio. Da exactamente los mismos N primeros que ordenarlo todo.
        private static void TomaMejores(List<SearchItem> src, List<SearchItem> dst, int n)
        {
            int cnt = src.Count;
            if (cnt <= 0 || n <= 0) return;
            if (n > cnt) n = cnt;
            SearchItem[] top = new SearchItem[n];
            int hay = 0;
            for (int i = 0; i < cnt; i++)
            {
                SearchItem v = src[i];
                if (hay < n)
                {
                    int j = hay++;
                    while (j > 0 && ComparaHit(top[j - 1], v) > 0) { top[j] = top[j - 1]; j--; }
                    top[j] = v;
                }
                else if (ComparaHit(v, top[n - 1]) < 0)
                {
                    int j = n - 1;
                    while (j > 0 && ComparaHit(top[j - 1], v) > 0) { top[j] = top[j - 1]; j--; }
                    top[j] = v;
                }
            }
            for (int i = 0; i < hay; i++) dst.Add(top[i]);
        }

        private void ChooseSearchResult(SearchItem it)
        {
            if (it == null) return;
            MarkSearchActivity();
            if (it.Kind == 2 && it.TrackRef != null)
            {
                PlayItem p = new PlayItem(); p.IsVideo = false; p.Song = it.TrackRef; p.Disc = it.AlbumRef;
                AddResult r = AddItem(p);
                if (r == AddResult.Added) ShowSongAddedToast(true);
                else if (r == AddResult.NoCredit) ShowSearchToast("Inserta una moneda", false);
                else ShowSearchToast("Esa cancion ya va seguida", false);
                return; // no cierra el buscador
            }
            else if (it.Kind == 1 && it.AlbumRef != null)
            {
#if ROCOLA_GPU
                transNextFrom = SearchCubeRect(out transNextAngle);   // la portada sale del CUBO GRANDE del buscador (luego ya no existe)
#endif
                CloseSearch(); NavigateToAlbum(it.AlbumRef); EnterAlbum(it.AlbumRef);
            }
            else if (it.Kind == 0 && it.AlbumRef != null) { CloseSearch(); NavigateToAlbum(it.AlbumRef); }
        }

        private void ShowSearchToast(string msg) { ShowSearchToast(msg, true); }
        private void ShowSearchToast(string msg, bool ok)
        {
            toastKind = ToastKind.Other;   // por defecto NO acumulable; cancion lo re-marca tras llamar
            searchOverlay.ToastMsg = msg;
            searchOverlay.ToastBack = ok ? Color.FromArgb(238, 40, 165, 90) : Color.FromArgb(238, 205, 130, 35);
            searchOverlay.ToastOn = true;
            searchOverlay.Invalidate();
            toastTimer.Stop(); toastTimer.Start();
        }

        // ¿La tecla kc esta asignada a ALGUN boton de la rocola? (las teclas configuradas tienen prioridad)
        private bool IsConfiguredKey(Keys kc)
        {
            return kc == keyUp || kc == keyDown || kc == keyLeft || kc == keyRight
                || kc == keyOK || kc == keyBack || kc == keyCoin || kc == keySkip;
        }
        // Cada accion responde a SU boton de rocola configurado Y a la tecla de PC por defecto.
        // La tecla de PC solo cuenta si NO esta tomada por otro boton configurado (evita choques).
        private bool IsUp(Keys kc) { return kc == keyUp || (kc == Keys.Up && !IsConfiguredKey(Keys.Up)); }
        private bool IsDown(Keys kc) { return kc == keyDown || (kc == Keys.Down && !IsConfiguredKey(Keys.Down)); }
        private bool IsLeft(Keys kc) { return kc == keyLeft || (kc == Keys.Left && !IsConfiguredKey(Keys.Left)); }
        private bool IsRight(Keys kc) { return kc == keyRight || (kc == Keys.Right && !IsConfiguredKey(Keys.Right)); }
        private bool IsOK(Keys kc) { return kc == keyOK || (kc == Keys.Enter && !IsConfiguredKey(Keys.Enter)); }
        private bool IsBack(Keys kc) { return kc == keyBack || (kc == Keys.Escape && !IsConfiguredKey(Keys.Escape)); }
        private bool IsCoin(Keys kc) { return kc == keyCoin || (kc == Keys.Insert && !IsConfiguredKey(Keys.Insert)); }
        private bool IsSkip(Keys kc) { return kc == keySkip || (kc == Keys.ShiftKey && !IsConfiguredKey(Keys.ShiftKey)); }
        // ¿Esta presionado AHORA el boton REGRESAR (rocola) o Esc (teclado)?  (para los combos)
        private bool BackHeld() { return KeyHeld(keyBack) || (KeyHeld(Keys.Escape) && !IsConfiguredKey(Keys.Escape)); }

        // ================== SALIR DE LA ROCOLA (Ctrl+Alt+Q, tres veces) ==================
        //
        // Aqui la rocola se cierra con Alt+F4, que lo manda Windows. Pero Alt+F4 no siempre esta: en un
        // equipo montado como quiosco -sin escritorio, con el teclado capado por directiva- puede estar
        // bloqueado, y entonces no queda forma de salir sin reiniciar la maquina. En la rocola de Linux
        // directamente no existe. Asi que hay una tecla propia, que no depende de nadie.
        //
        // TRES VECES y no una: en un bar la rocola esta al alcance de cualquiera, y una sola combinacion se
        // aprieta sin querer o por curiosear. Tres seguidas dentro de unos segundos no le pasan a nadie por
        // accidente, y las dos primeras solo avisan en pantalla, asi que el que lo hizo sin querer ve lo que
        // esta a punto de pasar y para. Si se tarda, la cuenta vuelve a empezar: dos de anoche no suman con
        // una de hoy.
        //
        // Devuelve 0 si esa tecla no es la de salir, o 1, 2 o 3 = cuantas van. Quien llama ensena el aviso
        // y, al llegar a 3, cierra. Va aparte para poder probarlo sin tener que simular teclados.
        private const int SalirVeces = 3;                 // cuantas veces hay que pulsarlo
        private const double SalirSegundos = 3.0;         // y dentro de cuanto, entre una y otra
        private int salirCuenta = 0;
        private DateTime salirUltima = DateTime.MinValue;

        private int PidenSalir(Keys keyData)
        {
            if (keyData != (Keys.Control | Keys.Alt | Keys.Q)) return 0;
            DateTime ahora = DateTime.Now;
            if ((ahora - salirUltima).TotalSeconds > SalirSegundos) salirCuenta = 0;   // se tardo: vuelta a empezar
            salirUltima = ahora;
            salirCuenta++;
            if (salirCuenta > SalirVeces) salirCuenta = SalirVeces;
            return salirCuenta;
        }

        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
        {
            // SALIR (Ctrl+Alt+Q x3). Va lo primero para que ninguna pantalla se quede con la tecla: tiene
            // que funcionar siempre, este donde este el cliente. Cierra con Close(), que es el camino de
            // siempre -el mismo que Alt+F4-: cerrar
            // A PROPOSITO borra el estado guardado y manana la rocola arranca limpia (solo un apagon -que
            // no corre nada- deja el archivo, y por eso al volver la luz reanuda creditos y cola).
            int vanSalir = PidenSalir(keyData);
            if (vanSalir > 0)
            {
                if (vanSalir >= SalirVeces) { Close(); return true; }
                ShowToast("Salir de la rocola: " + vanSalir + " de " + SalirVeces, Color.FromArgb(200, 130, 35));
                return true;
            }

            lastInput = DateTime.Now;   // cualquier tecla reinicia la inactividad
            lastInputTick = Environment.TickCount;   // el precalentador de miniaturas pausa si hay actividad
            if (attractOn)
            {
                // Cualquier boton despierta la rocola... pero la MONEDA ademas ACREDITA. Antes este return se
                // tragaba el pulso del monedero: el cliente metia su moneda durante la atraccion (el estado MAS
                // comun al acercarse, entra sola a los 40s de reposo) y SU DINERO SE PERDIA sin dar creditos.
                ExitAttract();
                Keys akc = keyData & Keys.KeyCode;
                if (IsCoin(akc) && (msg.LParam.ToInt64() & 0x40000000) == 0) AddCoin();   // mismo filtro de auto-repeticion que abajo
                return true;
            }

            // ASISTENTE DE CONFIGURACION: captura el boton que se presiona para cada funcion.
            if (configMode) { CaptureConfigKey(keyData, msg); return true; }

            bool wasFull = videoFull;
            Keys kc = keyData & Keys.KeyCode;   // tecla base (sin modificadores)

            // ===== ENTRADAS ESPECIALES: SIEMPRE funcionan (buscador, video en pantalla completa, donde sea) =====
            // MONEDA (filtra AUTO-REPETICION: si la señal queda "mantenida", el teclado la repite y sumaria
            // creditos de mas; cada pulso real del monedero trae su propio pulsar/soltar y pasa siempre)
            if (IsCoin(kc)) { if ((msg.LParam.ToInt64() & 0x40000000) == 0) { if (wasFull) ExitVideoFull(); AddCoin(); } return true; }

            // SALTAR: salta la cancion/video actual SIEMPRE (filtra auto-repeticion)
            if (IsSkip(kc) && (msg.LParam.ToInt64() & 0x40000000) == 0)
            {
                SkipSong();   // si el video estaba en pantalla completa, StopVideoPlayback ya sale de ella
                return true;
            }

            // Cualquier OTRA tecla, si el video esta en pantalla completa, solo "despierta" la rocola.
            if (wasFull) { ExitVideoFull(); return true; }

            // BRILLO DE INSTRUCCIONES: al pulsar un boton fisico, resalta su simbolo en la barra de ayuda.
            // Mover: arriba/abajo ROJO, izq/der AMARILLO (como las flechas de la cruceta). Guia visual.
            if (searchOpen && searchOverlay != null)   // barra del buscador (Mover / Poner-Elegir / Cerrar)
            {
                if (IsUp(kc) && BackHeld()) searchOverlay.FlashClose();
                else if (IsOK(kc)) searchOverlay.FlashOK();
                else if (IsUp(kc) || IsDown(kc)) searchOverlay.FlashMove(true);
                else if (IsLeft(kc) || IsRight(kc)) searchOverlay.FlashMove(false);
            }
            else if (helpBar != null && !attractOn)    // barra de navegacion / interior de disco
            {
                if (IsOK(kc)) helpBar.Flash(HelpBar.FEntrar);
                else if (IsBack(kc)) helpBar.Flash(HelpBar.FVolver);
                else if (IsUp(kc) || IsDown(kc)) helpBar.FlashMove(true);
                else if (IsLeft(kc) || IsRight(kc)) helpBar.FlashMove(false);
            }

            // F5 = recargar musica (mantenimiento; sin boton visible)
            if (keyData == Keys.F5) { try { File.Delete(LibCacheFile()); } catch { } LoadMusicFolder(); return true; }   // F5 ignora el cache: re-escaneo completo
#if ROCOLA_GPU
            if (keyData == Keys.F12) { GpuTestWindow.Toggle(); return true; }   // F12 = ventana de prueba del render por GPU (Direct3D 9)
            if (keyData == (Keys.Control | Keys.F12)) { ToggleAlbumGpu(); return true; }   // Ctrl+F12 = fondo de discos por GPU (experimental)
            if (keyData == (Keys.Control | Keys.F11))   // Ctrl+F11 = alterna el interior de disco entre GPU (por defecto) y CPU (valvula de escape)
            {
                gpuDiscTry = !gpuDiscTry;
                uiOverlaySig = SigNada;   // fuerza rehacer la textura de UI
                if (lblStatus != null) lblStatus.Text = "Interior de disco por " + (gpuDiscTry ? "GPU" : "CPU");
                SyncGpuFullScreen(); Invalidate(true);
                return true;
            }
            if (keyData == (Keys.Control | Keys.F1))   // Ctrl+F1 = muestra/oculta el contador de FPS (oculto por defecto)
            {
                gpuShowFps = !gpuShowFps;
                if (gpuPanel != null) gpuPanel.ShowFps = gpuShowFps;
                return true;
            }
#endif
            if (keyData == (Keys.Control | Keys.F2))   // Ctrl+F2 = gestor de carpetas de musica (agregar/quitar; otros discos)
            {
                ShowMusicDirManager();
                return true;
            }
            if (keyData == (Keys.Control | Keys.F3))   // Ctrl+F3 = ajuste del nivelado de volumen (que todo suene parejo)
            {
                ShowVolumeManager();
                return true;
            }
            if (keyData == Keys.F8 && !IsConfiguredKey(Keys.F8))    // F8 = relanzar el asistente de botones
            {
                if (searchOpen) CloseSearch();
                StartConfig();
                return true;
            }
            if (keyData == Keys.F10 && !IsConfiguredKey(Keys.F10))   // F10 = mantenimiento: pausa/reactiva el vigia de foco
            {
                maintMode = !maintMode;
                if (maintMode) { maintUntil = DateTime.Now.AddMinutes(30); ShowToast("Mantenimiento: vigia pausado 30 min", Color.FromArgb(200, 130, 35)); }
                else ShowToast("Vigia de pantalla reactivado");
                return true;
            }

            // ABRIR / CERRAR EL BUSCADOR: ROJO + ARRIBA. Antes era ROJO + VERDE y nadie lo encontraba,
            // porque no habia forma de saber que era un combo. Ahora los dos botones estan DIBUJADOS en la
            // casilla de BUSCAR que parpadea arriba en medio, asi que no hay nada que adivinar.
            if (IsUp(kc) && BackHeld()) { ToggleSearch(); return true; }

            // FRENO DE LA AUTO-REPETICION DE LAS FLECHAS.
            //
            // Manteniendo pulsada una flecha, el teclado manda unas treinta pulsaciones por segundo. Cada una
            // mueve la seleccion y encarga un repintado... y la pantalla no da mas de sesenta cuadros por
            // segundo, asi que la mitad de ese trabajo no lo llega a ver nadie: solo sirve para llenar la cola
            // y que la rocola se sienta pastosa. Es el mismo problema que ya se filtra en el boton de la
            // moneda y en el de saltar.
            //
            // Pero aqui NO se puede tirar la repeticion como alli: mantener pulsada una flecha para recorrer
            // la biblioteca es como se usa una rocola de botones, y quitarlo seria peor que el problema. Lo
            // que se hace es ponerle TOPE: como mucho un movimiento cada 40 ms, que son veinticinco por
            // segundo -mas rapido de lo que la pantalla puede ensenar-. La primera pulsacion siempre pasa,
            // asi que pulsar suelto se siente exactamente igual que antes.
            //
            // Va por TIEMPO y no por el bit de "esto es una repeticion" a proposito: ese bit es cosa de
            // Windows, y esta rocola tambien corre en Linux, donde puede no venir.
            if (IsLeft(kc) || IsRight(kc) || IsUp(kc) || IsDown(kc))
            {
                int ahora = Environment.TickCount;
                if (ahora - ultimaFlecha < MsEntreFlechas) return true;   // demasiado seguidas: esta se descarta
                ultimaFlecha = ahora;
            }

            if (searchOpen)
            {
                MarkSearchActivity();
                if (IsLeft(kc)) { searchOverlay.MoveSel(-1, 0); return true; }
                if (IsRight(kc)) { searchOverlay.MoveSel(1, 0); return true; }
                if (IsUp(kc)) { searchOverlay.MoveSel(0, -1); return true; }
                if (IsDown(kc)) { searchOverlay.MoveSel(0, 1); return true; }
                if (IsOK(kc)) { searchOverlay.PressSelected(); return true; }
                if (IsBack(kc)) { searchOverlay.Backspace(); return true; }   // REGRESAR = borrar letra; cerrar = REGRESAR+PONER
                // letras, numeros, Ñ, acentos, comillas, espacio y BORRAR los entrega KeyPress (admite TODO caracter)
                return base.ProcessCmdKey(ref msg, keyData);
            }

            if (panelSongs.Visible)
            {
                int rpc = SongRowsPerPage();   // misma cuenta que la paginacion: izq/der = pagina anterior/siguiente
                // Con ROJO mantenido, arriba/abajo NO navegan: queda reservado para el combo de ocultar
                // (ROJO+ARRIBA+ABAJO 5 s), asi la lista no salta mientras se mantiene el combo.
                if (IsUp(kc)) { if (!BackHeld()) MoveSong(-1); return true; }
                if (IsDown(kc)) { if (!BackHeld()) MoveSong(1); return true; }
                if (IsLeft(kc)) { MoveSong(-rpc); return true; }     // pagina anterior
                if (IsRight(kc)) { MoveSong(rpc); return true; }      // pagina siguiente
                if (IsOK(kc)) { EnqueueSelectedSong(); return true; }
                if (IsBack(kc)) { BackToAlbums(); return true; }
            }
            else
            {
                // REGRESAR + IZQ/DER = saltar de letra (A,B,C...). Solo IZQ/DER = mover de disco.
                if (IsLeft(kc)) { if (BackHeld()) ChangeLetter(-1); else MoveInPage(-1); return true; }
                if (IsRight(kc)) { if (BackHeld()) ChangeLetter(1); else MoveInPage(1); return true; }
                // Con ROJO mantenido, arriba/abajo NO paginan: reservado para el combo de vetar (5 s).
                if (IsUp(kc)) { if (!BackHeld()) NextPage(); return true; }
                if (IsDown(kc)) { if (!BackHeld()) PrevPage(); return true; }
                if (IsOK(kc)) { List<Album> l = CurrentList(); if (selAlbumIndex >= 0 && selAlbumIndex < l.Count) EnterAlbum(l[selAlbumIndex]); return true; }
                if (IsBack(kc)) { return true; }
            }
            return base.ProcessCmdKey(ref msg, keyData);
        }

        // =================== ASISTENTE DE CONFIGURACION DE BOTONES ===================
        private string KeysFile() { return RutaDatos("rocola_teclas.txt"); }

        // Carga el mapeo de botones. Devuelve true solo si estan los 8 completos.
        private bool LoadKeys()
        {
            try
            {
                string f = KeysFile();
                if (!File.Exists(f)) return false;
                Keys u = Keys.None, d = Keys.None, l = Keys.None, r = Keys.None, ok = Keys.None, bk = Keys.None, co = Keys.None, sk = Keys.None;
                string[] lines = File.ReadAllLines(f);
                for (int i = 0; i < lines.Length; i++)
                {
                    string s = lines[i].Trim();
                    int eq = s.IndexOf('=');
                    if (eq <= 0) continue;
                    string name = s.Substring(0, eq).Trim().ToLower();
                    int val;
                    if (!int.TryParse(s.Substring(eq + 1).Trim(), out val)) continue;
                    Keys k = (Keys)val;
                    if (name == "arriba") u = k;
                    else if (name == "abajo") d = k;
                    else if (name == "izquierda") l = k;
                    else if (name == "derecha") r = k;
                    else if (name == "poner") ok = k;
                    else if (name == "regresar") bk = k;
                    else if (name == "moneda") co = k;
                    else if (name == "saltar") sk = k;
                }
                if (u == Keys.None || d == Keys.None || l == Keys.None || r == Keys.None ||
                    ok == Keys.None || bk == Keys.None || co == Keys.None || sk == Keys.None) return false;
                keyUp = u; keyDown = d; keyLeft = l; keyRight = r; keyOK = ok; keyBack = bk; keyCoin = co; keySkip = sk;
                return true;
            }
            catch { return false; }
        }

        private void SaveKeys()
        {
            try
            {
                StringBuilder sb = new StringBuilder();
                sb.Append("arriba=").Append((int)keyUp).Append("\r\n");
                sb.Append("abajo=").Append((int)keyDown).Append("\r\n");
                sb.Append("izquierda=").Append((int)keyLeft).Append("\r\n");
                sb.Append("derecha=").Append((int)keyRight).Append("\r\n");
                sb.Append("poner=").Append((int)keyOK).Append("\r\n");
                sb.Append("regresar=").Append((int)keyBack).Append("\r\n");
                sb.Append("moneda=").Append((int)keyCoin).Append("\r\n");
                sb.Append("saltar=").Append((int)keySkip).Append("\r\n");
                EscribeSeguro(KeysFile(), sb.ToString());
            }
            catch { }
        }

        // Inicia el asistente (primera vez, o cuando se escriben diez ceros en el buscador).
        private void StartConfig()
        {
            if (searchOpen) CloseSearch();
            configMode = true;
            configStep = 0;
            for (int i = 0; i < configCap.Length; i++) configCap[i] = Keys.None;
            if (lblConfig != null) { lblConfig.Visible = true; lblConfig.BringToFront(); }
            UpdateConfigPrompt(null);
        }

        private void UpdateConfigPrompt(string warn)
        {
            if (lblConfig == null) return;
            string t = "CONFIGURACION DE BOTONES DE LA ROCOLA\r\n\r\n";
            t += "Paso " + (configStep + 1) + " de " + ConfigSteps.Length + "\r\n\r\n";
            t += "Presiona en la rocola el boton para:\r\n\r\n";
            t += ">>>   " + ConfigSteps[configStep] + "   <<<";
            if (warn != null) t += "\r\n\r\n" + warn;
            t += "\r\n\r\n\r\n(cada boton debe ser distinto)";
            lblConfig.Text = t;
            lblConfig.BringToFront();
        }

        // Captura el boton presionado durante la configuracion.
        private void CaptureConfigKey(Keys keyData, Message msg)
        {
            if ((msg.LParam.ToInt64() & 0x40000000) != 0) return;   // ignora auto-repeticion (boton mantenido)
            Keys k = keyData & Keys.KeyCode;
            if (k == Keys.None || k == Keys.Menu || k == Keys.ControlKey) return;   // ignora teclas vacias/control sueltas
            for (int j = 0; j < configStep; j++)
                if (configCap[j] == k) { UpdateConfigPrompt("Ese boton ya esta usado. Presiona OTRO."); return; }
            configCap[configStep] = k;
            configStep++;
            if (configStep >= ConfigSteps.Length) FinishConfig();
            else UpdateConfigPrompt(null);
        }

        private void FinishConfig()
        {
            keyUp = configCap[0]; keyDown = configCap[1]; keyLeft = configCap[2]; keyRight = configCap[3];
            keyOK = configCap[4]; keyBack = configCap[5]; keyCoin = configCap[6]; keySkip = configCap[7];
            SaveKeys();
            configMode = false;
            needConfig = false;
            if (lblConfig != null) lblConfig.Visible = false;
            this.Focus();
            ShowToast("¡Botones configurados!");
        }

        private void ShowToast(string text) { ShowToast(text, Color.FromArgb(40, 165, 90)); }
        private void ShowToast(string text, Color back)
        {
            toastKind = ToastKind.Other;   // por defecto NO acumulable; moneda/cancion lo re-marcan tras llamar
            int tw = ToastW, th = ToastH;
#if ROCOLA_GPU
            // Con el panel GPU el aviso es un cuadro mas de la GPU, no una etiqueta de Windows encima: entra
            // deslizandose y se va desvaneciendo, y sobre todo NO obliga a Windows a recortar el panel y
            // repintarlo (eso era un tiron justo al meter la moneda). Ver HorneaToast/BuildToastState.
            if (gpuEnabled)
            {
                HorneaToast(text, back);
                if (lblToast.Visible) lblToast.Visible = false;
                toastTimer.Stop(); toastTimer.Start();   // el temporizador sigue mandando para el aviso del buscador
                return;
            }
#endif
            lblToast.Text = text;
            lblToast.BackColor = back;
            tw = AnchoToast(text, lblToast.Font);   // misma pastilla que por GPU: se ajusta al texto
            lblToast.SetBounds((ClientSize.Width - tw) / 2, 80, tw, th);
            try { using (GraphicsPath gp = RoundRect(new Rectangle(0, 0, tw, th), 16)) lblToast.Region = new Region(gp); } catch { }  // esquinas redondeadas SIEMPRE
            lblToast.Visible = true;
            lblToast.BringToFront();
            toastTimer.Stop(); toastTimer.Start();
        }

        // El aviso se dibuja SIEMPRE en un bitmap de este tamano (por eso la textura se reusa y no cuesta nada),
        // pero la pastilla de color se ajusta al texto y va centrada dentro. Antes era fija en 380 y los avisos
        // largos ("No se pudo abrir el video: credito devuelto") salian cortados.
        private const int ToastW = 620, ToastH = 48, ToastMinW = 260;
        // Ancho de la pastilla para ESE texto (acotado): lo usan las dos formas de dibujarla, por GPU y por CPU,
        // para que se vea igual en las dos.
        internal static int AnchoToast(string text, Font font)
        {
            int w = TextRenderer.MeasureText(text, font).Width + 44;
            return w < ToastMinW ? ToastMinW : (w > ToastW ? ToastW : w);
        }
#if ROCOLA_GPU
        private Bitmap toastBmp; private int toastVer, toastTick = -1;
        private const int ToastMs = 1300, ToastInMs = 190, ToastOutMs = 260;   // ToastMs = lo mismo que dura el temporizador

        // Dibuja el aviso en su propio bitmap (se REUSA siempre el mismo: cero basura para el recolector) y le
        // sube la version, que es lo que hace que la GPU vuelva a subirlo.
        private void HorneaToast(string text, Color back)
        {
            if (toastBmp == null) toastBmp = new Bitmap(ToastW, ToastH, PixelFormat.Format32bppPArgb);
            PintaToast(toastBmp, text, back, lblToast.Font);
            toastVer++; toastTick = Environment.TickCount;
        }

        // El dibujo en si, aparte del estado: asi se puede ver y comprobar sin arrancar la rocola entera.
        internal static void PintaToast(Bitmap bmp, string text, Color back, Font font)
        {
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.Clear(Color.Transparent);
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;   // gris: ClearType deja flecos sobre transparente
                int tw = AnchoToast(text, font);   // el texto MANDA el ancho de la pastilla
                int x0 = (ToastW - tw) / 2;
                using (GraphicsPath gp = RoundRect(new Rectangle(x0, 0, tw, ToastH), 16))
                {
                    using (SolidBrush b = new SolidBrush(back)) g.FillPath(b, gp);
                    using (Pen pe = new Pen(Color.FromArgb(70, 255, 255, 255), 1.5f)) g.DrawPath(pe, gp);   // filo claro: lo despega del fondo
                }
                using (SolidBrush b = new SolidBrush(Color.White))
                using (StringFormat sf = new StringFormat())
                {
                    sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center;
                    sf.FormatFlags = StringFormatFlags.NoWrap; sf.Trimming = StringTrimming.EllipsisCharacter;
                    g.DrawString(text, font, b, new RectangleF(x0 + 10, 0, tw - 20, ToastH), sf);
                }
            }
        }

        // CURVA del aviso (funcion pura, para poder comprobarla): baja desde arriba mientras aparece, se queda
        // quieto, y al final sube un poco mientras se desvanece.
        internal static void CurvaToast(int dt, out float alpha, out float dy)
        {
            alpha = 1f; dy = 0f;
            if (dt < 0 || dt >= ToastMs) { alpha = 0f; return; }
            if (dt < ToastInMs)
            {
                float q = dt / (float)ToastInMs;
                float e = 1f - (1f - q) * (1f - q) * (1f - q);   // frenado suave al llegar
                alpha = e; dy = -30f * (1f - e);
            }
            else if (dt > ToastMs - ToastOutMs)
            {
                float q = (dt - (ToastMs - ToastOutMs)) / (float)ToastOutMs;
                alpha = 1f - q; dy = -16f * q;
            }
        }

        // Estado del aviso para la GPU: entra deslizandose desde arriba mientras aparece, se queda quieto, y
        // al final sube un poco mientras se desvanece. El avance va con el reloj, asi que se ve fluido a los
        // fps que de el equipo (no a los 24 del temporizador).
        private GpuToast BuildToastState()
        {
            GpuToast t = new GpuToast();
            if (toastTick < 0 || toastBmp == null) return t;
            int dt = Environment.TickCount - toastTick;
            if (dt < 0 || dt >= ToastMs) { toastTick = -1; return t; }
            float a, dy; CurvaToast(dt, out a, out dy);
            t.Has = true; t.Bmp = toastBmp; t.Ver = toastVer;
            t.X = (ClientSize.Width - ToastW) * 0.5f;
            t.Y = 80f + dy;
            t.Alpha = a;
            return t;
        }
#endif

        private static GraphicsPath RoundRect(Rectangle r, int radius)
        {
            int d = radius * 2;
            if (d > r.Width) d = r.Width;
            if (d > r.Height) d = r.Height;
            if (d < 1) d = 1;
            GraphicsPath p = new GraphicsPath();
            p.AddArc(r.X, r.Y, d, d, 180, 90);
            p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            p.CloseFigure();
            return p;
        }

        // ---- Cola unificada (canciones + videos, en orden) + creditos ----
        private enum AddResult { Added, NoCredit, Repeat }

        private AddResult AddItem(PlayItem it)
        {
            if (it == null) return AddResult.Repeat;
            if (credits <= 0)
            {   // sin creditos no se puede poner nada, y ademas la capsula se SACUDE: a las dos de la
                // manana nadie lee el letrero, pero un movimiento si se ve.
                if (pastCred != null) { pastCred.Aviso(); pastCred.Invalidate(); }
                return AddResult.NoCredit;
            }
            // no repetir lo mismo dos veces seguidas (lo ultimo en sonar/encolar)
            PlayItem last = (queue.Count > 0) ? queue[queue.Count - 1] : nowPlaying;
            if (last != null && string.Equals(last.PathKey(), it.PathKey(), StringComparison.OrdinalIgnoreCase)) return AddResult.Repeat;
            queue.Add(it); RefrescaCola(); PrecalientaSiguiente();
            // EL TURNO SE APUNTA AQUI Y NO EN EL AVISO, a proposito: aqui la cola esta como quedo justo
            // al meterla, y unas lineas mas abajo PlayNext puede sacar la primera y correrlo todo.
            turnoPuesto = queue.Count;
            double[] antes = new double[queue.Count - 1];
            for (int i = 0; i < queue.Count - 1; i++) antes[i] = SegundosDe(queue[i].PathKey());
            turnoSegs = EsperaSegundos(antes, RestanDeLaQueSuena());
            VuelaALaCola(it.Disc);   // se VE: la portada sale de la pared y aterriza en la pastilla de la cola
            if (iaVivo && !it.IsVideo && it.Song != null) IaRequestJob(it.Song.Path);   // IA EN VIVO: prepara desde que se encola (lista para cuando le toque)
            RecordPlay(it);                                              // estadisticas: cuenta lo pedido
            credits--;                                                   // cada cosa cuesta 1 credito
            UpdateCredits();
            if (nowPlaying == null) PlayNext();   // nada sonando -> arranca (PlayNext guarda el estado); si algo suena, solo se encola
            else { UpdateNowPlayingUI(); SaveState(); }   // estado vivo: cola/creditos cambiaron
            return AddResult.Added;
        }

        private void AddSong(Track t, Album disc)
        {
            if (t == null) return;
            PlayItem it = new PlayItem(); it.IsVideo = false; it.Song = t; it.Disc = disc;
            AddResult r = AddItem(it);
            if (r == AddResult.Added) ShowSongAddedToast(false);
            else if (r == AddResult.NoCredit) ShowToast("Inserta una moneda", Color.FromArgb(200, 130, 35));
            else ShowToast("Esa ya va seguida", Color.FromArgb(200, 130, 35));
        }

        // Aviso de cancion agregada, con acumulacion: si agregas varias rapido (mientras el aviso sigue),
        // dice "Cancion agregada", "Cancion agregada  X2", "X3"... para que quede claro cuantas van y no confunda.
        private void ShowSongAddedToast(bool search)
        {
            songTotal = SameToastActive(ToastKind.Song) ? songTotal + 1 : 1;
            // EL TURNO SUSTITUYE AL "X2". Antes, al pedir varias seguidas, el aviso contaba cuantas
            // llevabas; el turno dice algo mejor y lo dice solo, porque el puesto de la ultima YA sube
            // con cada una. Y si no se supiera el puesto -no deberia pasar- se vuelve al de siempre.
            string msg = TextoTurno(turnoPuesto, turnoSegs);
            if (msg.Length == 0) msg = songTotal > 1 ? "Cancion agregada  X" + songTotal : "Cancion agregada";
            if (search) ShowSearchToast(msg, true); else ShowToast(msg);
            MarkToast(ToastKind.Song);
        }

        private void AddVideoToQueue(string path, Album disc)
        {
            if (string.IsNullOrEmpty(path)) return;
            PlayItem it = new PlayItem(); it.IsVideo = true; it.VideoPath = path; it.Disc = disc;
            AddResult r = AddItem(it);
            if (r == AddResult.Added)
            {   // el video tambien dice su turno: para quien lo pidio es exactamente lo mismo
                string mv = TextoTurno(turnoPuesto, turnoSegs);
                ShowToast(mv.Length > 0 ? mv : "Video agregado a la cola");
            }
            else if (r == AddResult.NoCredit) ShowToast("Inserta una moneda", Color.FromArgb(200, 130, 35));
            else ShowToast("Ese video ya va seguido", Color.FromArgb(200, 130, 35));
        }

        // Suma creditos (la moneda) y actualiza el letrero
        private void AddCoin()
        {
            credits += CreditsPerCoin;
            // ANTES de UpdateCredits, a proposito: la pastilla se guarda el numero de AHORA para rodar
            // desde el, y quien lo cambia es la linea de mas abajo.
            if (pastCred != null) { pastCred.Moneda(); pastCred.Invalidate(); }
            statsCoins++; statsCreditsAdded += CreditsPerCoin; statsDirty = true;   // estadisticas
            UpdateCredits();
            SaveState();   // estado vivo: si se corta la luz, el dinero del cliente no se pierde
            // Monedas rapidas seguidas: el aviso SUMA (+4, +8, +12...) en vez de reiniciar; si ya paso su
            // tiempo (el usuario fue lento), arranca de nuevo en +4.
            coinTotal = SameToastActive(ToastKind.Coin) ? coinTotal + CreditsPerCoin : CreditsPerCoin;
            ShowToast("+" + coinTotal + " creditos", Color.FromArgb(40, 165, 90));
            MarkToast(ToastKind.Coin);
        }

        // ===================== ESTADO VIVO (reanudar tras un corte de luz) =====================
        // Guarda creditos + lo que suena + la cola en rocola_estado.txt (solo cambia en eventos: moneda,
        // encolar, cambio de cancion). Si se corta la luz, al volver la rocola RETOMA: la cancion que estaba
        // sonando arranca DESDE EL PRINCIPIO (a peticion: media cancion confunde mas de lo que ayuda), con su
        // cola y los creditos del cliente intactos. Para el CIERRE del negocio: SALTAR repetido vacia la cola
        // y, con todo vacio, una pulsacion de SALTAR borra los creditos -> estado vacio -> arranca limpia.
        // El archivo se DESCARTA por tres vias que distinguen "cierre" de "apagon": (1) apagado deliberado
        // (boton de poder -> Windows apaga, u Alt+F4) borra el archivo en OnFormClosing; (2) al cruzar las 7 AM
        // estando ociosa (CheckBusinessDayReset); (3) al restaurar, si el estado ya cruzo las 7 AM y no es reciente.
        // Un apagon no dispara nada de esto -> el archivo sobrevive y la rocola reanuda.
        private string StateFile() { return RutaDatos("rocola_estado.txt"); }
        private bool stateRestored = false;   // la restauracion corre UNA vez (al primer armado de biblioteca)

        // El estado de recuperacion pertenece a UN "dia del negocio", que ARRANCA a las 7 AM (hora del sistema): a
        // esa hora ya cerro, y nada de la noche anterior debe cruzar las 7 AM. Todo lo de antes de las 7 AM cuenta
        // como el dia ANTERIOR. Al pasar esa hora: el estado guardado se DESCARTA al restaurar (arranque limpio en
        // la manana) y se LIMPIA si la rocola sigue encendida (creditos/cola a cero) -> cada dia arranca en cero.
        private const int BusinessDayStartHour = 7;
        private const int DayResetIdleMins = 10;   // minutos OCIOSA (sin musica/cola/botones) para aplicar el reinicio de 7 AM: si te desvelas, NO te interrumpe
        private const int StateRecentMins = 30;    // si el estado se guardo hace menos de esto, se reanuda aunque cruce las 7 AM (fue un corte breve en plena sesion)
        private static DateTime BusinessDay(DateTime dt) { return dt.AddHours(-BusinessDayStartHour).Date; }
        private DateTime stateDay = BusinessDay(DateTime.Now);   // dia del negocio del estado vivo actual

        private void SaveState()
        {
            try
            {
                StringBuilder sb = new StringBuilder(256);
                sb.Append("ROCOLA-ESTADO v1\r\n");
                sb.Append("ts=").Append(DateTime.Now.Ticks).Append("\r\n");   // cuando se guardo (para descartarlo si cruza las 7 AM)
                sb.Append("creditos=").Append(credits).Append("\r\n");
                if (nowPlaying != null)
                    sb.Append("sonando=").Append(nowPlaying.IsVideo ? 'V' : 'S').Append('|').Append(nowPlaying.PathKey()).Append("\r\n");
                for (int i = 0; i < queue.Count; i++)
                    sb.Append("cola=").Append(queue[i].IsVideo ? 'V' : 'S').Append('|').Append(queue[i].PathKey()).Append("\r\n");
                EscribeSeguro(StateFile(), sb.ToString());   // archivo diminuto (<1KB): escritura sincrona sin costo notable
            }
            catch { }
        }

        // Al cruzar las 7 AM (nuevo dia del negocio) reinicia el estado guardado. PERO nunca interrumpe una sesion
        // en uso: si te DESVELAS, tu musica NO deja de sonar y tus creditos NO se tocan. El reinicio ESPERA a que la
        // rocola quede OCIOSA (nada sonando, cola vacia y sin botones un buen rato); recien entonces borra los
        // creditos que hayan quedado (de alguien que se fue) y el archivo guardado -> el dia arranca limpio.
        private void CheckBusinessDayReset()
        {
            if (BusinessDay(DateTime.Now) == stateDay) return;                          // mismo dia del negocio: comun, nada que hacer
            if (nowPlaying != null || queue.Count > 0) return;                          // hay musica o cola: EN USO -> se aplaza
            if ((DateTime.Now - lastInput).TotalMinutes < DayResetIdleMins) return;     // botones recientes: EN USO -> se aplaza
            stateDay = BusinessDay(DateTime.Now);                                       // ociosa y dia nuevo -> reinicia UNA vez
            if (credits > 0) { credits = 0; UpdateCredits(); }                          // creditos que quedaron de anoche -> a cero
            BorraSeguro(StateFile());                                                   // borra el estado guardado (y su copia) -> arranque limpio
            BackupLearnedData();                                                        // cierre del dia: respalda lo aprendido (una vez al dia)
        }

        // ===================== RESPALDO DE DATOS APRENDIDOS =====================
        // El disco puede morir (ya paso). La musica no se recupera, pero SI todo lo que la rocola aprendio:
        // volumenes nivelados, huellas del EQ, estadisticas de lo mas sonado, indice de biblioteca,
        // config, mapa de botones y el modelo de IA. Se copia a respaldo\<fecha>\ (y a respaldo_dir= si se
        // configuro, idealmente OTRO disco), guardando los 3 dias mas recientes. Son unos KB: barato y rapido.
        private string BackupBaseDir() { return RutaDatos("respaldo"); }
        private void BackupLearnedData()
        {
            string sp = CarpetaDatos, second = backupDir, baseDir = BackupBaseDir();
            string[] files = {
                LoudFile(), EqFile(), LibStatsFile(), LibCacheFile(), ConfigFile, KeysFile(),
                RutaLectura("rocola_ia.bin"), RutaLectura("rocola_eq_ia.bin"),
                Path.Combine(sp, "rocola_incompatibles.txt"),
                IaDoneFile(), DeepDoneFile(),  // sin estas dos, un repaso a fondo empezaria de cero y la IA repetiria ejemplos
                DurFastFile(), LetterTintFile()   // sin este, la barra tendria que releer el ID3 de toda la biblioteca
            };
            System.Threading.ThreadPool.QueueUserWorkItem(delegate   // fuera del hilo de la interfaz (no frena nada)
            {
                try
                {
                    string stamp = DateTime.Now.ToString("yyyy-MM-dd");
                    BackupTo(Path.Combine(baseDir, stamp), files); PruneBackups(baseDir, 3);
                    if (!string.IsNullOrEmpty(second))
                    { string s2 = Path.Combine(second, "respaldo_rocola"); try { BackupTo(Path.Combine(s2, stamp), files); PruneBackups(s2, 3); } catch { } }
                }
                catch { }
            });
        }
        private static void BackupTo(string dir, string[] files)
        {
            Directory.CreateDirectory(dir);
            for (int i = 0; i < files.Length; i++)
                try { if (File.Exists(files[i])) File.Copy(files[i], Path.Combine(dir, Path.GetFileName(files[i])), true); }
                catch { }
        }
        // Deja solo las 'keep' carpetas de respaldo mas recientes (por fecha de modificacion); borra el resto.
        private static void PruneBackups(string baseDir, int keep)
        {
            try
            {
                DirectoryInfo bd = new DirectoryInfo(baseDir);
                if (!bd.Exists) return;
                DirectoryInfo[] dirs = bd.GetDirectories();
                if (dirs.Length <= keep) return;
                Array.Sort(dirs, delegate (DirectoryInfo a, DirectoryInfo b) { return b.LastWriteTime.CompareTo(a.LastWriteTime); });
                for (int i = keep; i < dirs.Length; i++) { try { dirs[i].Delete(true); } catch { } }
            }
            catch { }
        }

        // Cuando se guardo el estado: la marca "ts=" (ticks); si falta (formato viejo), la fecha del archivo.
        private static DateTime SavedStateTime(string[] lines, string file)
        {
            for (int i = 0; i < lines.Length; i++)
                if (lines[i].StartsWith("ts="))
                { long t; if (long.TryParse(lines[i].Substring(3), out t) && t > 0) { try { return new DateTime(t); } catch { } } break; }
            try { return File.GetLastWriteTime(file); } catch { return DateTime.Now; }
        }

        // Reconstruye creditos/cola/cancion desde el archivo de estado (si hay algo que reanudar).
        private void RestoreState()
        {
            if (stateRestored) return;
            stateRestored = true;
            try
            {
                string f = StateFile();
                // Si el archivo bueno falta o quedo vacio -un corte de luz de los de antes- se lee la copia:
                // se pierde como mucho lo ultimo que se hizo, no el dinero entero del cliente.
                string[] L = LeeLineasSeguro(f);
                if (L == null || L.Length < 1) return;
                if (L[0] != "ROCOLA-ESTADO v1")
                {
                    try { if (File.Exists(f + ".bak")) L = File.ReadAllLines(f + ".bak"); } catch { }
                    if (L == null || L.Length < 1 || L[0] != "ROCOLA-ESTADO v1") return;
                }
                // El estado solo vale DENTRO del mismo dia del negocio (corte a las 7 AM): lo de anoche, visto ya en
                // la manana, se descarta (arranque limpio). PERO si se guardo hace poquito (corte breve en plena
                // sesion, p.ej. un parpadeo de luz justo al dar las 7 mientras te desvelas), se reanuda igual.
                DateTime saved = SavedStateTime(L, f);
                if (BusinessDay(DateTime.Now) != BusinessDay(saved) && (DateTime.Now - saved).TotalMinutes > StateRecentMins)
                { BorraSeguro(f); return; }
                // mapas ruta -> cancion/disco para reconstruir los elementos (solo lo que SIGA existiendo)
                Dictionary<string, Track> byPath = new Dictionary<string, Track>(StringComparer.OrdinalIgnoreCase);
                Dictionary<string, Album> discByPath = new Dictionary<string, Album>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < albums.Count; i++)
                    for (int j = 0; j < albums[i].Tracks.Count; j++)
                    {
                        Track t = albums[i].Tracks[j];
                        if (t != null && t.Path != null && !byPath.ContainsKey(t.Path)) { byPath[t.Path] = t; discByPath[t.Path] = albums[i]; }
                    }
                Dictionary<string, Album> vidDisc = new Dictionary<string, Album>(StringComparer.OrdinalIgnoreCase);
                if (videoAlbums != null)
                    for (int i = 0; i < videoAlbums.Count; i++)
                        for (int j = 0; j < videoAlbums[i].VideoFiles.Count; j++)
                        { string vp = videoAlbums[i].VideoFiles[j]; if (vp != null && !vidDisc.ContainsKey(vp)) vidDisc[vp] = videoAlbums[i]; }

                int cr = 0; PlayItem playing = null; List<PlayItem> q = new List<PlayItem>();
                for (int i = 1; i < L.Length; i++)
                {
                    string s = L[i];
                    if (s.Length == 0) continue;
                    if (s.StartsWith("creditos=")) { int.TryParse(s.Substring(9), out cr); continue; }
                    if (s.StartsWith("pos=")) continue;   // formato viejo: la posicion ya no se usa (siempre desde el principio)
                    bool isNow = s.StartsWith("sonando=");
                    if (!isNow && !s.StartsWith("cola=")) continue;
                    string v = s.Substring(s.IndexOf('=') + 1);
                    if (v.Length < 3 || v[1] != '|') continue;
                    bool isVid = (v[0] == 'V'); string path = v.Substring(2);
                    PlayItem it = null;
                    if (isVid)
                    {
                        bool exists = false; try { exists = File.Exists(path); } catch { }
                        if (exists) { it = new PlayItem(); it.IsVideo = true; it.VideoPath = path; Album d; vidDisc.TryGetValue(path, out d); it.Disc = d; }
                    }
                    else
                    {
                        Track t;
                        if (byPath.TryGetValue(path, out t)) { it = new PlayItem(); it.Song = t; Album d; discByPath.TryGetValue(path, out d); it.Disc = d; }
                    }
                    if (it == null) continue;   // el archivo ya no existe / se re-escaneo distinto: se omite
                    if (isNow) playing = it; else q.Add(it);
                }
                if (cr <= 0 && playing == null && q.Count == 0) return;   // estado vacio: arranque limpio
                credits = Math.Max(0, cr);
                UpdateCredits();
                queue.AddRange(q); RefrescaCola(); PrecalientaSiguiente();
                if (playing != null)
                {
                    queue.Insert(0, playing);   // lo que estaba sonando vuelve a entrar y arranca DESDE EL PRINCIPIO
                    RefrescaCola();
                    PlayNext();
                    ShowToast("Reanudando la musica");
                }
                else UpdateNowPlayingUI();
            }
            catch { }
        }

        // ===================== MOTOR DE ESTADISTICAS =====================
        private string LibStatsFile() { return RutaDatos("rocola_stats.txt"); }

        // Registra una reproduccion pedida (algo que entro a la cola con exito).
        private void RecordPlay(PlayItem it)
        {
            if (it == null) return;
            statsTotal++;
            if (it.IsVideo)
            {
                statsVideoTotal++;
                string vp = it.VideoPath;
                if (!string.IsNullOrEmpty(vp)) { int n; videoCounts.TryGetValue(vp, out n); videoCounts[vp] = n + 1; videoSeq[vp] = ++statsSeq; }
            }
            else if (it.Song != null && !string.IsNullOrEmpty(it.Song.Path))
            {
                statsSongTotal++;
                int n; songCounts.TryGetValue(it.Song.Path, out n); songCounts[it.Song.Path] = n + 1;
                songSeq[it.Song.Path] = ++statsSeq;
                if (!string.IsNullOrEmpty(it.Song.Genre) && !songGenre.ContainsKey(it.Song.Path)) songGenre[it.Song.Path] = GenreLabel(it.Song.Genre);
                string ar = it.Song.Artist;
                if (!string.IsNullOrEmpty(ar)) { int a; artistCounts.TryGetValue(ar, out a); artistCounts[ar] = a + 1; }
                // primera cancion contada -> habilitar la seccion "Lo mas sonado" en la barra de letras
                if (letterAvailable != null && !letterAvailable.Contains(TopMark)) { letterAvailable.Add(TopMark); RecalculaLetras(); }
            }
            statsDirty = true;
            topDirty = true;   // OPTIMIZACION (TOP): cambiaron counts/genero/artista -> reconstruir al entrar a TOP
        }

        private void StatsTimer_Tick(object sender, EventArgs e)
        {
            if (statsDirty) { statsDirty = false; SaveStats(true); }   // guardado periodico en segundo plano
        }

        // Mantiene el archivo acotado: descarta lo menos sonado (y mas viejo) para dejar entrar lo nuevo.
        private void PruneStats()
        {
            PruneCountDict(songCounts, songSeq, songGenre, SongStatCap, SongStatTarget);
            PruneCountDict(videoCounts, videoSeq, null, VideoStatCap, VideoStatTarget);
            PruneCountDict(artistCounts, null, null, ArtistStatCap, ArtistStatTarget);
            if (songGenre.Count > songCounts.Count)   // limpiar generos huerfanos
            {
                List<string> orphans = new List<string>();
                foreach (string k in songGenre.Keys) if (!songCounts.ContainsKey(k)) orphans.Add(k);
                for (int i = 0; i < orphans.Count; i++) songGenre.Remove(orphans[i]);
            }
        }

        private void PruneCountDict(Dictionary<string, int> counts, Dictionary<string, long> seq, Dictionary<string, string> extra, int cap, int target)
        {
            if (counts.Count <= cap) return;
            List<string> keys = new List<string>(counts.Keys);
            keys.Sort(delegate (string a, string b)
            {
                int ca = counts[a], cb = counts[b];
                if (ca != cb) return ca - cb;              // menos sonado primero (candidato a borrar)
                long sa = 0, sb = 0; if (seq != null) { seq.TryGetValue(a, out sa); seq.TryGetValue(b, out sb); }
                if (sa != sb) return (sa < sb) ? -1 : 1;   // mas viejo primero
                return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
            });
            int remove = counts.Count - target;
            for (int i = 0; i < remove && i < keys.Count; i++)
            {
                string k = keys[i];
                counts.Remove(k);
                if (seq != null) seq.Remove(k);
                if (extra != null) extra.Remove(k);
            }
        }

        // Claves ordenadas por recencia (mas viejo primero): al guardarse asi, al recargar se reconstruye
        // el orden de recencia leyendo el archivo de arriba hacia abajo.
        private List<string> KeysBySeq(Dictionary<string, int> counts, Dictionary<string, long> seq)
        {
            List<string> ks = new List<string>(counts.Keys);
            ks.Sort(delegate (string a, string b)
            {
                long sa = 0, sb = 0; seq.TryGetValue(a, out sa); seq.TryGetValue(b, out sb);
                if (sa != sb) return (sa < sb) ? -1 : 1;
                return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
            });
            return ks;
        }

        private void SaveStats(bool async)
        {
            PruneStats();   // acotar antes de escribir
            string text;
            try { text = BuildStatsText(); } catch { return; }   // se arma en el hilo de la interfaz (sin acceso cruzado a los diccionarios)
            // Este archivo tiene DOS escritores -uno de fondo cada tanto y otro sincrono al cerrar- y si se
            // pisaban se llevaban por delante "LO MAS SONADO" entero. El candado por archivo esta dentro de
            // EscribeSeguro, asi que aqui ya no hace falta acordarse de nada.
            if (async)
                System.Threading.ThreadPool.QueueUserWorkItem(delegate (object st)
                { try { EscribeSeguro(LibStatsFile(), text); } catch { } });
            else
                try { EscribeSeguro(LibStatsFile(), text); } catch { }   // al cerrar: sincrono (el proceso podria salir antes de un hilo de fondo)
        }

        private string BuildStatsText()
        {
            StringBuilder sb = new StringBuilder(songCounts.Count * 48 + 256);
            sb.Append("ROCOLA-STATS v1\r\n");
            sb.Append("total-reproducciones=").Append(statsTotal).Append("\r\n");
            sb.Append("total-canciones=").Append(statsSongTotal).Append("\r\n");
            sb.Append("total-videos=").Append(statsVideoTotal).Append("\r\n");
            sb.Append("monedas=").Append(statsCoins).Append("\r\n");
            sb.Append("creditos-cargados=").Append(statsCreditsAdded).Append("\r\n");
            sb.Append("[CANCIONES] count|ruta\r\n");
            List<string> sk = KeysBySeq(songCounts, songSeq);
            for (int i = 0; i < sk.Count; i++) sb.Append(songCounts[sk[i]]).Append('|').Append(sk[i]).Append("\r\n");
            sb.Append("[ARTISTAS] count|artista\r\n");
            foreach (KeyValuePair<string, int> kv in artistCounts) sb.Append(kv.Value).Append('|').Append(kv.Key).Append("\r\n");
            sb.Append("[VIDEOS] count|ruta\r\n");
            List<string> vk = KeysBySeq(videoCounts, videoSeq);
            for (int i = 0; i < vk.Count; i++) sb.Append(videoCounts[vk[i]]).Append('|').Append(vk[i]).Append("\r\n");
            sb.Append("[GENEROS] genero|ruta\r\n");
            foreach (KeyValuePair<string, string> kv in songGenre) sb.Append(kv.Value).Append('|').Append(kv.Key).Append("\r\n");
            return sb.ToString();
        }

        private void LoadStats()
        {
            try
            {
                string f = LibStatsFile();
                if (!File.Exists(f)) return;
                string[] L = File.ReadAllLines(f);
                if (L.Length < 1 || L[0] != "ROCOLA-STATS v1") return;
                int section = 0;   // 0=totales 1=canciones 2=artistas 3=videos
                for (int i = 1; i < L.Length; i++)
                {
                    string line = L[i];
                    if (line.Length == 0) continue;
                    if (line.StartsWith("[CANCIONES]")) { section = 1; continue; }
                    if (line.StartsWith("[ARTISTAS]")) { section = 2; continue; }
                    if (line.StartsWith("[VIDEOS]")) { section = 3; continue; }
                    if (line.StartsWith("[GENEROS]")) { section = 4; continue; }
                    if (section == 0)
                    {
                        int eq = line.IndexOf('=');
                        if (eq <= 0) continue;
                        string k = line.Substring(0, eq); long v;
                        if (!long.TryParse(line.Substring(eq + 1), out v)) continue;
                        if (k == "total-reproducciones") statsTotal = v;
                        else if (k == "total-canciones") statsSongTotal = v;
                        else if (k == "total-videos") statsVideoTotal = v;
                        else if (k == "monedas") statsCoins = v;
                        else if (k == "creditos-cargados") statsCreditsAdded = v;
                    }
                    else
                    {
                        int b = line.IndexOf('|');
                        if (b <= 0) continue;
                        string key = line.Substring(b + 1);
                        if (key.Length == 0) continue;
                        if (section == 4) { songGenre[key] = line.Substring(0, b); continue; }   // genero|ruta (lo de antes del | es la etiqueta, no un numero)
                        int cnt; if (!int.TryParse(line.Substring(0, b), out cnt)) continue;
                        if (section == 1) { songCounts[key] = cnt; songSeq[key] = ++statsSeq; }
                        else if (section == 2) artistCounts[key] = cnt;
                        else if (section == 3) { videoCounts[key] = cnt; videoSeq[key] = ++statsSeq; }
                    }
                }
            }
            catch { }
        }

        private class TopEntry { public Track T; public int C; public Album A; public string V; }

        // Construye el disco virtual "Lo mas sonado" con las canciones MAS PEDIDAS (de las estadisticas),
        // ordenadas de mas a menos. Se arma al entrar a la seccion, asi siempre refleja lo actual.
        // Construye los discos virtuales "TOP - <genero>" con las canciones mas pedidas de cada genero.
        private void BuildTopDiscs()
        {
            if (!topDirty && topDiscs != null) return;   // OPTIMIZACION (TOP): nada cambio -> reusar lo ya armado
            if (libBuilding) return;                     // el worker esta mutando albums/videoAlbums: iterarlos seria una carrera (crash). topDirty queda puesto -> se reconstruye al terminar
            topDirty = false;                            // limpio AQUI: cubre todas las salidas (incluidas las tempranas)
            topDiscs = new List<Album>();
            if (songCounts.Count == 0) return;

            // 1) recolectar todas las canciones pedidas que EXISTEN en la biblioteca, con su disco de origen
            List<TopEntry> all = new List<TopEntry>();
            for (int i = 0; i < albums.Count; i++)
            {
                Album al = albums[i];
                for (int j = 0; j < al.Tracks.Count; j++)
                {
                    Track t = al.Tracks[j];
                    int c;
                    if (t != null && t.Path != null && songCounts.TryGetValue(t.Path, out c))
                    { TopEntry te = new TopEntry(); te.T = t; te.C = c; te.A = al; all.Add(te); }
                }
            }
            if (all.Count == 0) return;

            // 2) agrupar por etiqueta de genero (las que no tengan genero capturado caen en "Otros")
            Dictionary<string, List<TopEntry>> byGenre = new Dictionary<string, List<TopEntry>>();
            List<string> order = new List<string>();
            for (int i = 0; i < all.Count; i++)
            {
                string gl;
                if (!songGenre.TryGetValue(all[i].T.Path, out gl) || string.IsNullOrEmpty(gl)) gl = "Otros";
                List<TopEntry> lst;
                if (!byGenre.TryGetValue(gl, out lst)) { lst = new List<TopEntry>(); byGenre[gl] = lst; order.Add(gl); }
                lst.Add(all[i]);
            }

            // 3) un disco virtual por genero
            List<Album> discs = new List<Album>();
            Dictionary<Album, long> totals = new Dictionary<Album, long>();
            for (int gi = 0; gi < order.Count; gi++)
            {
                string gl = order[gi];
                List<TopEntry> lst = byGenre[gl];
                lst.Sort(delegate (TopEntry x, TopEntry y)
                {
                    if (y.C != x.C) return y.C - x.C;
                    return string.Compare(x.T.Path, y.T.Path, StringComparison.OrdinalIgnoreCase);
                });
                int take = (lst.Count < TopMax) ? lst.Count : TopMax;
                Album d = new Album();
                d.IsTop = true; d.Letter = TopMark; d.Folder = "::TOP::" + gl;
                d.Artist = "TOP 100"; d.Name = gl;             // AlbumLabel -> "TOP 100 - Rock"
                d.Tracks = new List<Track>();
                d.TrackCovers = new List<string>();
                d.TrackInfo = new List<string>();
                d.TrackAlbums = new List<Album>();
                List<string> cycle = new List<string>();
                long total = 0;
                for (int i = 0; i < take; i++)
                {
                    TopEntry te = lst[i];
                    d.Tracks.Add(te.T);
                    d.TrackCovers.Add(te.A.CoverPath);
                    d.TrackInfo.Add(AlbumLabel(te.A));
                    d.TrackAlbums.Add(te.A);
                    if (te.A.CoverPath != null && !cycle.Contains(te.A.CoverPath)) cycle.Add(te.A.CoverPath);
                    total += te.C;
                }
                d.CycleCovers = cycle;
                d.CoverPath = (cycle.Count > 0) ? cycle[0] : null;
                totals[d] = total;
                discs.Add(d);
            }

            // 3a) discos TOP por ARTISTA muy puesto (hasta 10), RANKEADOS: "TOP #1 - <artista>" ... "TOP #10 - ..."
            {
                Dictionary<string, List<TopEntry>> byArtist = new Dictionary<string, List<TopEntry>>(StringComparer.OrdinalIgnoreCase);
                List<string> aOrder = new List<string>();
                for (int i = 0; i < all.Count; i++)
                {
                    string ar = all[i].T.Artist;
                    if (string.IsNullOrEmpty(ar)) continue;
                    List<TopEntry> lst;
                    if (!byArtist.TryGetValue(ar, out lst)) { lst = new List<TopEntry>(); byArtist[ar] = lst; aOrder.Add(ar); }
                    lst.Add(all[i]);
                }
                // candidatos: artistas con >=2 canciones distintas puestas (un solo tema no amerita disco)
                List<string> cand = new List<string>();
                Dictionary<string, long> aTot = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < aOrder.Count; i++)
                {
                    string ar = aOrder[i];
                    List<TopEntry> lst = byArtist[ar];
                    if (lst.Count < 2) continue;
                    long t = 0; for (int j = 0; j < lst.Count; j++) t += lst[j].C;
                    aTot[ar] = t; cand.Add(ar);
                }
                cand.Sort(delegate (string a, string b)
                {
                    long ta = aTot[a], tb = aTot[b];
                    if (tb != ta) return (tb > ta) ? 1 : -1;
                    return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
                });
                int amax = (cand.Count < 10) ? cand.Count : 10;   // hasta 10 artistas mas puestos
                for (int ai = 0; ai < amax; ai++)
                {
                    string ar = cand[ai];
                    List<TopEntry> lst = byArtist[ar];
                    lst.Sort(delegate (TopEntry x, TopEntry y)
                    {
                        if (y.C != x.C) return y.C - x.C;
                        return string.Compare(x.T.Path, y.T.Path, StringComparison.OrdinalIgnoreCase);
                    });
                    int take = (lst.Count < TopMax) ? lst.Count : TopMax;
                    Album d = new Album();
                    // RANKING VISIBLE: el puesto (#1..#10, por total de reproducciones) va en la etiqueta. Tambien
                    // va en Folder (la CLAVE de la celda horneada): si un artista cambia de puesto, su etiqueta se
                    // re-hornea; con la clave vieja se habria quedado el numero anterior pegado en el cache.
                    d.IsTop = true; d.Letter = TopMark; d.Folder = "::TOPART::" + (ai + 1) + "|" + ar;
                    d.Artist = "TOP #" + (ai + 1); d.Name = ar;             // AlbumLabel -> "TOP #1 - Depeche Mode"
                    d.Tracks = new List<Track>();
                    d.TrackCovers = new List<string>();
                    d.TrackInfo = new List<string>();
                    d.TrackAlbums = new List<Album>();
                    List<string> cyc = new List<string>();
                    for (int i = 0; i < take; i++)
                    {
                        TopEntry te = lst[i];
                        d.Tracks.Add(te.T);
                        d.TrackCovers.Add(te.A.CoverPath);
                        d.TrackInfo.Add(AlbumLabel(te.A));
                        d.TrackAlbums.Add(te.A);
                        if (te.A.CoverPath != null && !cyc.Contains(te.A.CoverPath)) cyc.Add(te.A.CoverPath);
                    }
                    d.CycleCovers = cyc;
                    d.CoverPath = (cyc.Count > 0) ? cyc[0] : null;
                    totals[d] = aTot[ar];
                    discs.Add(d);
                }
            }

            // 3b) disco TOP de VIDEOS (de videoCounts, recorriendo los discos con video)
            if (videoCounts.Count > 0 && videoAlbums != null)
            {
                List<TopEntry> vids = new List<TopEntry>();
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    for (int j = 0; j < va.VideoFiles.Count; j++)
                    {
                        string vf = va.VideoFiles[j];
                        int c;
                        if (vf != null && videoCounts.TryGetValue(vf, out c))
                        { TopEntry te = new TopEntry(); te.V = vf; te.C = c; te.A = va; vids.Add(te); }
                    }
                }
                if (vids.Count > 0)
                {
                    vids.Sort(delegate (TopEntry x, TopEntry y)
                    {
                        if (y.C != x.C) return y.C - x.C;
                        return string.Compare(x.V, y.V, StringComparison.OrdinalIgnoreCase);
                    });
                    int vtake = (vids.Count < TopMax) ? vids.Count : TopMax;
                    Album vd = new Album();
                    vd.IsTop = true; vd.TopIsVideo = true; vd.Letter = TopMark; vd.Folder = "::TOPVID::";
                    vd.Artist = "TOP 100"; vd.Name = "Videos";
                    vd.VideoFiles = new List<string>();
                    vd.TrackCovers = new List<string>();
                    vd.TrackInfo = new List<string>();
                    vd.TrackAlbums = new List<Album>();
                    List<string> vcyc = new List<string>();
                    long vtotal = 0;
                    for (int i = 0; i < vtake; i++)
                    {
                        TopEntry te = vids[i];
                        vd.VideoFiles.Add(te.V);
                        vd.TrackCovers.Add(te.A.CoverPath);
                        vd.TrackInfo.Add(AlbumLabel(te.A));
                        vd.TrackAlbums.Add(te.A);
                        if (te.A.CoverPath != null && !vcyc.Contains(te.A.CoverPath)) vcyc.Add(te.A.CoverPath);
                        vtotal += te.C;
                    }
                    vd.CycleCovers = vcyc;
                    vd.CoverPath = (vcyc.Count > 0) ? vcyc[0] : null;
                    totals[vd] = vtotal;
                    discs.Add(vd);
                }
            }

            // 4) ordenar por CLASE (genero primero, luego videos, luego artistas) y dentro de
            //    cada clase por total de reproducciones. Asi quedan agrupados y comodos de ver.
            discs.Sort(delegate (Album x, Album y)
            {
                int cx = x.TopIsVideo ? 1 : ((x.Folder != null && x.Folder.StartsWith("::TOPART::", StringComparison.Ordinal)) ? 2 : 0);
                int cy = y.TopIsVideo ? 1 : ((y.Folder != null && y.Folder.StartsWith("::TOPART::", StringComparison.Ordinal)) ? 2 : 0);
                if (cx != cy) return cx - cy;
                long tx = totals[x], ty = totals[y];
                if (ty != tx) return (ty > tx) ? 1 : -1;
                return string.Compare(x.Name, y.Name, StringComparison.OrdinalIgnoreCase);
            });
            topDiscs = discs;
        }

        // Algo que el cliente pago (cancion o video) no se pudo reproducir: como encolarlo costo 1 credito, se le
        // devuelve. Sube 1 credito y guarda el estado. El aviso ("credito devuelto") lo pone cada llamador.
        private void RefundCredit()
        {
            credits++;
            UpdateCredits();
            SaveState();   // estado vivo: los creditos cambiaron
        }

        private int pastCredAncho;   // el ancho con el que se acomodo la capsula de creditos la ultima vez

        private void UpdateCredits()
        {
            if (pastCred == null) return;
            if (credits <= 0) { pastCred.Etiqueta = "Inserta una moneda"; pastCred.Valor = ""; pastCred.Acento = Color.FromArgb(255, 205, 90); }
            else { pastCred.Etiqueta = "Creditos"; pastCred.Valor = credits.ToString(); pastCred.Acento = Color.FromArgb(120, 240, 140); }
            // Y SI AHORA PIDE OTRO ANCHO, HAY QUE VOLVER A ACOMODAR.
            //
            // Los dos letreros miden cosas muy distintas -"Creditos 1" y "Inserta una moneda" se llevan mas
            // de cien pixeles- y el ancho de la capsula se calcula al acomodar la pantalla, no aqui. Al
            // gastar el ultimo credito el texto pasaba al largo DENTRO de la capsula medida para el corto, y
            // se cortaba a media palabra. Se veia en la rocola del bar: "Inserta una mon".
            //
            // Solo si CAMBIO: de "Creditos 1" a "Creditos 2" mide lo mismo, y rehacer el acomodo de la
            // pantalla en cada moneda seria trabajo tirado veinte veces en una noche movida.
            if (pastCred.Height >= 8)
            {
                int quiere = PastillaView.Ancho(pastCred.Etiqueta, pastCred.Valor, pastCred.Height, this.Font.FontFamily, pastCred.ConPortadas);
                if (quiere != pastCredAncho) { pastCredAncho = quiere; LayoutControls(); }
            }
            pastCred.Invalidate();
        }

        // Reproduce el siguiente elemento (cancion o video). Tambien sirve para SALTAR el actual.
        private void PlayNext()
        {
            DisposePlaybackNow();      // detiene cualquier cancion (se desuscribe antes; no re-dispara)
            StopVideoPlayback();       // detiene cualquier video

            if (queue.Count == 0)
            {
                nowPlaying = null;
                RefrescaCola();   // que se borre la marca de "SONANDO" de la lista del disco
                progress.Value = 0; lblTime.Text = "0:00 / 0:00";
                ApplyGenreBackground(null, null);
                LayoutControls(); this.Invalidate();
                UpdateNowPlayingUI();
                SaveState();   // estado vivo: ya no suena nada (los creditos que queden se conservan)
                return;
            }

            nowPlaying = queue[0];
            queue.RemoveAt(0); RefrescaCola();   // (nowPlaying ya esta puesto: la marca de "SONANDO" sale en la misma pasada)
            SaveState();   // estado vivo: cambio lo que suena / la cola (para reanudar tras un corte de luz)

            if (nowPlaying.IsVideo)
            {
                bgAccentTarget = DefaultAccent;       // el video no tiene genero
                StartVideoItem(nowPlaying.VideoPath);
            }
            else
            {
                nowPlaying.Song.EnsureTags();         // lee ID3 ahora (genero -> color de fondo)
                // Se apunta SOLO si el archivo trae etiqueta de verdad. Antes se apuntaba siempre, y en una
                // cancion sin etiqueta eso guardaba "Otros" y PISABA lo que la cascada habia deducido: la
                // pastilla decia "Pop" en la lista y al ponerla cambiaba a "Otros". Ese era el fallo.
                if (nowPlaying.Song.Path != null && !string.IsNullOrEmpty(nowPlaying.Song.Genre))
                { songGenre[nowPlaying.Song.Path] = GenreLabel(nowPlaying.Song.Genre); statsDirty = true; topDirty = true; }   // captura genero para los discos TOP
                ApplyGenreBackground(nowPlaying.Song, nowPlaying.Disc);
                PlayTrack(nowPlaying.Song);
            }
            LayoutControls(); this.Invalidate();
            UpdateNowPlayingUI();
        }

        // SALTAR: salta el elemento actual (cancion o video). Los CREDITOS son LO ULTIMO de la fila: solo se
        // borran cuando ya no queda NADA sonando NI en cola (asi SALTAR nunca borra dinero mientras haya musica
        // pendiente). Con todo vacio, UNA pulsacion de SALTAR borra los creditos (para cerrar el negocio).
        private void SkipSong()
        {
            if (nowPlaying != null || queue.Count > 0) { PlayNext(); return; }   // salta (o reanuda la cola si quedo detenida); PlayNext guarda el estado
            if (credits > 0)
            {
                credits = 0; UpdateCredits(); SaveState();
                ShowToast("Creditos borrados", Color.FromArgb(200, 130, 35));
            }
        }

        // ===================  VIDEO (Windows Media Player ActiveX, por codigo)  ===================

        // Pantalla completa del video tras inactividad (para apreciarlo mejor). Deja una franja
        // arriba para el aviso "toca una tecla" (asi no encimamos nada sobre el ActiveX del video).
        private void EnterVideoFull()
        {
            if (videoFull || !videoOn || video == null) return;
            videoFull = true;
            LayoutControls();
            video.BringToFront();
            if (lblAttract != null) { lblAttract.Visible = true; lblAttract.BringToFront(); }
        }
        private void ExitVideoFull()
        {
            if (!videoFull) return;
            videoFull = false;
            if (lblAttract != null) lblAttract.Visible = false;
            LayoutControls();
            this.Invalidate();
        }

        // EL VOLUMEN BASE DE LOS VIDEOS, ELEGIDO SOLO.
        //
        // El reproductor de Windows solo sabe BAJAR: su volumen va de 0 a 100 y el 100 es el archivo tal cual.
        // No hay forma de sacarle mas de lo que el video trae grabado. Asi que la unica manera de que todos
        // suenen IGUAL es bajar los fuertes hasta donde llegan los flojos, y para eso hace falta dejar hueco:
        // con el base en 85, un video solo puede subir un 18% -1.4 dB- antes de toparse con el 100, y uno
        // grabado 10 dB por debajo se queda tan bajo como estaba, que es justo lo que se oye en la rocola.
        //
        // Aqui se miran TODOS los videos ya medidos y se elige el base MAS ALTO con el que todavia alcanzan
        // casi todos. Se da por perdido el 15% mas flojo -por tres videos rarisimos no vale la pena bajar la
        // biblioteca entera- y nunca se baja del 40 (8 dB), que es lo mas que tiene sentido alejar los videos
        // de las canciones. Si aun no hay medidas (o el equipo no puede medir), manda la perilla y ya.
        private const float VideoAutoFuera = 0.15f;   // fraccion de videos que se da por perdida
        private const int VideoBaseMin = 40;          // -8 dB: lo mas que se acepta bajar el conjunto
        private int VideoBase()
        {
            if (!videoAuto || !normalizeOn) return videoVol;   // sin nivelado no hay nada que emparejar: manda la perilla
            int firma = loudCache.Count * 31 + videoVol;
            firma = firma * 31 + (int)(normTarget * 100000f);
            if (firma == videoBaseFirma && videoBaseAuto >= 0) return videoBaseAuto;
            videoBaseFirma = firma;
            List<float> nec = new List<float>();
            if (videoAlbums != null && normTarget > 0.0001f)
            {
                HashSet<string> vistos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);   // el mismo video puede estar en dos discos
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    if (va == null || va.VideoFiles == null) continue;
                    for (int j = 0; j < va.VideoFiles.Count; j++)
                    {
                        string vp = va.VideoFiles[j]; float rms;
                        if (vp == null || !vistos.Add(vp)) continue;
                        if (!loudCache.TryGetValue(vp, out rms) || rms <= 0.0001f) continue;
                        float b = 100f * rms / normTarget;   // el base mas alto con el que ESTE video llega al objetivo
                        nec.Add((b > 100f) ? 100f : b);
                    }
                }
            }
            if (nec.Count < 8) { videoBaseAuto = videoVol; return videoBaseAuto; }   // sin medidas suficientes: la perilla
            nec.Sort();
            int v = (int)Math.Round(nec[(int)(nec.Count * VideoAutoFuera)]);
            if (v < VideoBaseMin) v = VideoBaseMin; else if (v > 100) v = 100;
            videoBaseAuto = v;
            return v;
        }
        // Cuantos videos llevan medida (para poder decirlo en los ajustes).
        private int VideosMedidos()
        {
            int n = 0;
            if (videoAlbums == null) return 0;
            HashSet<string> vistos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < videoAlbums.Count; i++)
            {
                Album va = videoAlbums[i];
                if (va == null || va.VideoFiles == null) continue;
                for (int j = 0; j < va.VideoFiles.Count; j++)
                {
                    string vp = va.VideoFiles[j]; float rms;
                    if (vp == null || !vistos.Add(vp)) continue;
                    if (loudCache.TryGetValue(vp, out rms) && rms > 0.0001f) n++;
                }
            }
            return n;
        }

        // LA VENTANA DE LIMPIEZA. Ensena la lista ENTERA -ruta y cuanto le falta a cada uno para sonar como
        // el resto- y no borra nada hasta que se pulsa el boton rojo. Es la unica parte de la rocola que
        // toca los archivos del cliente, asi que se hace a la vista y con red: van a la PAPELERA, y ademas
        // queda apuntado en rocola_borrados.txt que se fue y con que medida.
        private void ShowLimpiezaVideos()
        {
            List<float> db;
            List<string> mudos = VideosMudos(out db);
            FontFamily ff = FamiliaUi();
            using (Font fTit = new Font(ff, 13f, FontStyle.Bold))
            using (Font fDes = new Font(ff, 9f))
            using (Font fLis = new Font(ff, 9f))
            using (Font fBot = new Font(ff, 10f, FontStyle.Bold))
            using (Form dlg = new Form())
            {
                dlg.Text = "Rocola  -  Videos que no suenan";
                dlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                dlg.MaximizeBox = false; dlg.MinimizeBox = false; dlg.ShowInTaskbar = false; dlg.ShowIcon = false;
                dlg.StartPosition = FormStartPosition.CenterParent;
                dlg.ClientSize = new Size(820, 520);
                dlg.BackColor = Color.FromArgb(11, 14, 32);

                Label lTit = new Label(); lTit.SetBounds(20, 16, 780, 26); lTit.BackColor = Color.Transparent;
                lTit.ForeColor = Color.FromArgb(232, 240, 255); lTit.Font = fTit;
                lTit.Text = (mudos.Count == 0) ? "No hay videos mudos" : (mudos.Count + " videos que practicamente no suenan");

                Label lDes = new Label(); lDes.SetBounds(20, 46, 780, 54); lDes.BackColor = Color.Transparent;
                lDes.ForeColor = Color.FromArgb(150, 162, 196); lDes.Font = fDes;
                lDes.Text = (mudos.Count == 0)
                    ? "Todos los videos MEDIDOS suenan. Los que aun no se han medido no se cuentan aqui:\ndeja que el repaso de la biblioteca vaya haciendo su trabajo."
                    : ("Estan mas de 30 dB por debajo del volumen de las canciones: puesto en la rocola, el cliente no oiria nada.\n"
                       + "Solo salen los que YA se midieron. Se van a la PAPELERA de Windows, asi que si alguno resulta que si\n"
                       + "sonaba, se saca de ahi. Queda apuntado en rocola_borrados.txt, junto al programa.");

                ListBox lst = new ListBox();
                lst.SetBounds(20, 106, 780, 340);
                lst.BackColor = Color.FromArgb(16, 20, 44);
                lst.ForeColor = Color.FromArgb(214, 224, 246);
                lst.BorderStyle = BorderStyle.None;
                lst.Font = fLis;
                lst.SelectionMode = SelectionMode.None;
                lst.IntegralHeight = false;
                for (int i = 0; i < mudos.Count; i++)
                    lst.Items.Add(db[i].ToString("0", CultureInfo.InvariantCulture).PadLeft(4) + " dB    " + mudos[i]);

                BotonPlano bNo = new BotonPlano(); bNo.SetBounds(20, 462, 200, 40); bNo.Font = fBot;
                bNo.Text = "Dejarlos como estan";
                BotonPlano bSi = new BotonPlano(); bSi.SetBounds(560, 462, 240, 40); bSi.Font = fBot;
                bSi.Text = "Mandar los " + mudos.Count + " a la papelera";
                bSi.Relleno = Color.FromArgb(112, 40, 34); bSi.Borde = Color.FromArgb(196, 92, 76);
                bSi.Visible = mudos.Count > 0;

                bNo.Click += delegate { dlg.Close(); };
                bSi.Click += delegate
                {
                    bSi.Enabled = false; bSi.Text = "Borrando..."; bSi.Invalidate(); Application.DoEvents();
                    int n = BorraVideosMudos(mudos, db);
                    dlg.Close();
                    ShowToast(n > 0 ? (n + " videos a la papelera") : "No se pudo borrar (Windows dijo que no)",
                              n > 0 ? Color.FromArgb(40, 130, 90) : Color.FromArgb(150, 60, 45));
                };
                dlg.Controls.Add(lTit); dlg.Controls.Add(lDes); dlg.Controls.Add(lst);
                dlg.Controls.Add(bNo); dlg.Controls.Add(bSi);
                dlg.ShowDialog(this);
            }
        }

        // Los manda a la papelera, los quita de la biblioteca y deja constancia. Devuelve cuantos se fueron.
        private int BorraVideosMudos(List<string> mudos, List<float> db)
        {
            if (mudos == null || mudos.Count == 0) return 0;
            if (!ALaPapelera(mudos)) return 0;   // Windows no pudo: no se toca nada mas, la biblioteca queda igual
            // Se apunta lo que DE VERDAD se fue, comprobandolo archivo por archivo: Windows puede negarse con
            // alguno -en uso, sin permiso, en un disco de red sin papelera- y el apunte tiene que decir la
            // verdad, no lo que se pidio. Que no se pueda escribir no impide la limpieza.
            try
            {
                StringBuilder sb = new StringBuilder();
                string cuando = DateTime.Now.ToString("yyyy-MM-dd HH:mm");
                for (int i = 0; i < mudos.Count; i++)
                {
                    if (mudos[i] == null || File.Exists(mudos[i])) continue;
                    sb.Append(cuando).Append("  a la papelera  ")
                      .Append(((i < db.Count) ? db[i] : 0f).ToString("0", CultureInfo.InvariantCulture)).Append(" dB  ")
                      .Append(mudos[i]).Append("\r\n");
                }
                if (sb.Length > 0) File.AppendAllText(RutaDatos("rocola_borrados.txt"), sb.ToString());
            }
            catch { }
            int n = QuitaDeLaBiblioteca(mudos);
            SaveLoudCache();
            videoBaseFirma = -1;    // el volumen base automatico se decide con los que QUEDAN
            RecalculaLetras();
            RefreshAlbums();
            return n;
        }

        // Saca de la biblioteca los archivos que YA NO ESTAN en el disco, sin tener que re-escanear: de sus
        // discos, de la tabla de medidas y de las de duracion. Los discos que se queden sin un solo video
        // dejan de ser seccion de video, y si no queda ninguno, la casilla VIDEO se va de la barra.
        //
        // Se comprueba archivo por archivo que de verdad no este: si Windows dijo que si pero el archivo
        // sigue ahi -estaba en uso, sin permiso, en un disco de red sin papelera-, ese se queda como estaba.
        // Mejor que la biblioteca diga la verdad a que se pierda un video que si existe.
        private int QuitaDeLaBiblioteca(List<string> rutas)
        {
            if (rutas == null || rutas.Count == 0) return 0;
            HashSet<string> fuera = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int n = 0;
            for (int i = 0; i < rutas.Count; i++)
            {
                if (rutas[i] == null || File.Exists(rutas[i])) continue;
                fuera.Add(rutas[i]); n++;
                loudCache.Remove(rutas[i]); durCache.Remove(rutas[i]); durFast.Remove(rutas[i]);
            }
            if (n == 0) return 0;
            if (videoAlbums != null)
            {
                for (int i = 0; i < videoAlbums.Count; i++)
                {
                    Album va = videoAlbums[i];
                    if (va == null || va.VideoFiles == null) continue;
                    for (int j = va.VideoFiles.Count - 1; j >= 0; j--)
                        if (va.VideoFiles[j] != null && fuera.Contains(va.VideoFiles[j])) va.VideoFiles.RemoveAt(j);
                }
                for (int i = videoAlbums.Count - 1; i >= 0; i--)
                    if (videoAlbums[i] == null || videoAlbums[i].VideoFiles == null || videoAlbums[i].VideoFiles.Count == 0)
                        videoAlbums.RemoveAt(i);
            }
            if (cachedVideoPaths != null) cachedVideoPaths.RemoveAll(delegate (string v) { return v != null && fuera.Contains(v); });
            if (letterAvailable != null && (videoAlbums == null || videoAlbums.Count == 0)) letterAvailable.Remove(VideoMark);
            return n;
        }

        // ==========  LIMPIEZA: LOS VIDEOS QUE NO SUENAN  ==========
        //
        // En una biblioteca que lleva anos armandose acaban colandose videos con la pista de sonido rota,
        // muda o grabada tan bajo que no se oye nada. En la rocola son una loteria mala: el cliente paga, sale
        // el video y no suena. Aqui se localizan -de los que YA estan medidos; a uno sin medir no se le toca-
        // y se pueden mandar a la papelera.
        //
        // El corte son 30 dB por debajo del volumen objetivo de las canciones. No es "un poco bajo": es que
        // con el resto de la rocola a volumen normal, eso es un susurro que no se oye desde la barra.
        private const float LoudMudo = 0.00001f;   // marca de "medido y en silencio" (se guarda y se relee tal cual)
        private const float VideoMudoDb = -30f;    // a partir de aqui, para el local, no suena

        // Los videos medidos que practicamente no suenan, del mas callado al menos. En 'db' queda lo que le
        // falta a cada uno para llegar al volumen de las canciones (negativo).
        private List<string> VideosMudos(out List<float> db)
        {
            List<string> lista = new List<string>();
            db = new List<float>();
            if (videoAlbums == null || normTarget <= 0.0001f) return lista;
            float corte = (float)(normTarget * Math.Pow(10.0, VideoMudoDb / 20.0));
            List<KeyValuePair<string, float>> hall = new List<KeyValuePair<string, float>>();
            HashSet<string> vistos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < videoAlbums.Count; i++)
            {
                Album va = videoAlbums[i];
                if (va == null || va.VideoFiles == null) continue;
                for (int j = 0; j < va.VideoFiles.Count; j++)
                {
                    string vp = va.VideoFiles[j]; float rms;
                    if (vp == null || !vistos.Add(vp)) continue;
                    if (!loudCache.TryGetValue(vp, out rms)) continue;   // SIN MEDIR: ese no se toca, faltaria mas
                    if (rms > corte) continue;
                    hall.Add(new KeyValuePair<string, float>(vp, rms));
                }
            }
            hall.Sort(delegate (KeyValuePair<string, float> a, KeyValuePair<string, float> b) { return a.Value.CompareTo(b.Value); });
            for (int i = 0; i < hall.Count; i++)
            {
                lista.Add(hall[i].Key);
                db.Add((float)(20.0 * Math.Log10(Math.Max(hall[i].Value, 1e-9f) / normTarget)));
            }
            return lista;
        }

        // A LA PAPELERA, no al vacio. Es la misma operacion que hace el explorador de Windows al pulsar
        // Suprimir: si alguno resulta que si sonaba, se saca de la papelera y no ha pasado nada. Se mandan
        // TODOS de una sola llamada (la lista va con un cero entre archivo y archivo, y dos al final, que es
        // como la pide Windows). Devuelve true solo si Windows dijo que salio bien; si algo falla, no se
        // borra nada y el que llama lo cuenta.
        [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential, CharSet = System.Runtime.InteropServices.CharSet.Auto)]
        private struct SHFILEOPSTRUCT
        {
            public IntPtr hwnd;
            public int wFunc;
            [System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.LPTStr)] public string pFrom;
            [System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.LPTStr)] public string pTo;
            public short fFlags;
            [System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.Bool)] public bool fAnyOperationsAborted;
            public IntPtr hNameMappings;
            [System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.LPTStr)] public string lpszProgressTitle;
        }
        [System.Runtime.InteropServices.DllImport("shell32.dll", CharSet = System.Runtime.InteropServices.CharSet.Auto)]
        private static extern int SHFileOperation(ref SHFILEOPSTRUCT op);

        private static bool ALaPapelera(List<string> rutas)
        {
            if (rutas == null || rutas.Count == 0) return true;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rutas.Count; i++) { sb.Append(rutas[i]); sb.Append('\0'); }
            sb.Append('\0');
            SHFILEOPSTRUCT op = new SHFILEOPSTRUCT();
            op.wFunc = 3;                    // FO_DELETE
            op.pFrom = sb.ToString();
            op.fFlags = 0x0454;              // A LA PAPELERA (0x40) + sin preguntar (0x10) + sin ventanas (0x4 y 0x400)
            try { return SHFileOperation(ref op) == 0 && !op.fAnyOperationsAborted; }
            catch { return false; }
        }

        // Abre y reproduce un video en el reproductor de la derecha (lo llama PlayNext).
        // Volumen (0..100) con el que debe sonar un video: el base -la perilla, o lo que eligio el programa-,
        // mas los dB de "Subir TODO" (para que los videos sigan al resto), mas -si ese video ya fue medido-
        // el nivelado que lo lleva al MISMO volumen objetivo de las canciones.
        private int VideoVolumeFor(string path)
        {
            double v = VideoBase();
            float rms;
            if (normalizeOn && path != null && loudCache.TryGetValue(path, out rms) && rms > 0.0001f)
            {
                // NIVELADO. Este video esta medido, asi que se le pone el volumen justo para que suene como
                // los demas. Aqui "Subir TODO" NO entra, a proposito: el reproductor de Windows no pasa de
                // 100, o sea que ese de mas no lo puede dar, y lo unico que consigue es empujar los videos
                // contra el techo y deshacer el emparejado que se acaba de hacer. Con +6 dB de master, todos
                // los videos con algo de cuerpo se pegaban al 100 y volvian a sonar distinto entre si.
                double lv = normTarget / rms;
                if (lv < 0.15) lv = 0.15;        // no enterrar un video muy fuerte (max -16 dB)
                else if (lv > 4.0) lv = 4.0;     // ni intentar rescatar uno mudo (el tope real lo pone el 100 del WMP)
                v *= lv;
            }
            else v *= MasterLin();   // sin medida no hay nada que emparejar: que al menos siga a "Subir TODO"
            // EL MODO NOCHE VA AQUI FUERA, Y NO DENTRO DE MasterLin(). La rama de arriba -la del video YA
            // MEDIDO- se salta la ganancia general a proposito, asi que metiendolo alli esos videos, que en
            // una rocola usada son la mayoria, seguirian a todo volumen a las tres de la manana. Bajar si
            // se puede aunque subir no: el tope de 100 del WMP solo estorba hacia arriba.
            v *= FactorNoche();
            int r = (int)Math.Round(v);
            if (r < 0) r = 0; else if (r > 100) r = 100;   // el WMP no pasa de 100: un video muy bajito solo llega hasta ahi
            return r;
        }

        // Pone el volumen en el WMP solo si CAMBIO (el sondeo corre varias veces por segundo durante el fundido).
        private void SetVideoVolume(int v)
        {
            if (v == videoVolSet) return;
            videoVolSet = v;
            try
            {
                if (video == null) return;
                object ocx = video.GetOcxObj(); if (ocx == null) return;
                object settings = Get(ocx, "settings"); if (settings != null) Set(settings, "volume", v);
            }
            catch { }
        }

        private void StartVideoItem(string path)
        {
#if ROCOLA_GPU
            AbortDiscTrans(); AbortWinTrans();   // el video toma la pantalla: nada volando encima
#endif
            try
            {
                if (video == null)
                {
                    video = new VideoHost();
                    video.TabStop = false;
                    Controls.Add(video);
                    IntPtr forceHandle = video.Handle;   // fuerza la creacion del control ActiveX
                }
                video.Visible = !searchOpen;   // si el buscador esta abierto, el cuadro queda oculto (el audio sigue)

                object ocx = video.GetOcxObj();
                if (ocx == null) throw new Exception("control WMP nulo");

                Set(ocx, "uiMode", "none");
                Set(ocx, "stretchToFit", true);
                object settings = Get(ocx, "settings");
                videoVolSet = -1;   // fuerza el primer envio del volumen a este WMP recien apuntado
                int vol0 = VideoVolumeFor(path);
                if (settings != null) { Set(settings, "autoStart", true); Set(settings, "volume", vol0); }
                videoVolSet = vol0;
                Set(ocx, "URL", path);   // con autoStart=true deberia arrancar solo
                try { object c0 = Get(ocx, "controls"); if (c0 != null) Call(c0, "play"); } catch { }   // empujon explicito: autoStart no siempre engancha al instanciar el ActiveX

                videoOn = true;
                progress.Value = 0; lblTime.Text = "0:00 / 0:00";   // limpia el tiempo de la cancion anterior; VideoPoll lo llena con pos/dur del video
                videoLastPos = -1; videoProgressTick = Environment.TickCount; videoNudged = false; videoMaxPos = 0;   // arrancar el vigia de avance
                videoPoll.Interval = 400;   // sondeo normal (baja a 80 ms durante el fundido del final)
                video.BringToFront();
                videoPoll.Start();
                Diag("video: inicia");
            }
            catch (Exception ex)
            {
                videoOn = false;
                try { if (video != null) video.Visible = false; } catch { }
                RefundCredit();   // compensacion al cliente: el video no abrio
                ShowToast("No se pudo abrir el video: credito devuelto", Color.FromArgb(200, 80, 70));
                lblStatus.Text = "Video (WMP): " + ex.Message;
                Diag("video: NO ABRIO - " + ex.Message);
                // el video no arranco: pasar al siguiente sin trabar la cola (tras desenredar la pila de PlayNext)
                try { if (this.IsHandleCreated) this.BeginInvoke((MethodInvoker)delegate { PlayNext(); }); } catch { }
            }
        }

        // Detiene/oculta el video SIN tocar la cola (lo usan PlayNext y el cierre del buscador).
        private void StopVideoPlayback()
        {
            videoPoll.Stop();
            try { if (video != null) video.Visible = false; } catch { }   // ocultar PRIMERO (aunque el OCX truene al detener)
            try
            {
                if (video != null)
                {
                    object ocx = video.GetOcxObj();
                    if (ocx != null)
                    {
                        object controls = Get(ocx, "controls");
                        if (controls != null) Call(controls, "stop");
                        Set(ocx, "URL", "");
                    }
                }
            }
            catch { }
            videoOn = false;
            Diag("video: detenido");
            if (videoFull) ExitVideoFull();   // si estaba en pantalla completa, vuelve a la vista normal
        }

        private void VideoPoll_Tick(object sender, EventArgs e)
        {
            if (!videoOn || video == null) { videoPoll.Stop(); return; }
            int now = Environment.TickCount;
            int st = -1; double pos = -1, dur = -1;
            try
            {
                object ocx = video.GetOcxObj();
                if (ocx != null)
                {
                    object ps = Get(ocx, "playState");
                    if (ps != null) st = Convert.ToInt32(ps);
                    object controls = Get(ocx, "controls");
                    if (controls != null) { object cp = Get(controls, "currentPosition"); if (cp != null) pos = Convert.ToDouble(cp); }
                    object media = Get(ocx, "currentMedia");
                    if (media != null) { object d = Get(media, "duration"); if (d != null) dur = Convert.ToDouble(d); }
                }
            }
            catch { }

            if (pos > videoMaxPos) videoMaxPos = pos;

            // El tiempo/barra del VIDEO salen de aqui (ProgressTimer solo sirve a las canciones via 'reader',
            // que con video esta nulo). Sin esto el tiempo se quedaba congelado en lo ultimo de la cancion.
            if (pos >= 0 && dur > 0.5)
            {
                double frac = pos / dur; if (frac < 0) frac = 0; if (frac > 1) frac = 1;
                progress.Value = frac;
                lblTime.Text = Fmt(TimeSpan.FromSeconds(pos)) + " / " + Fmt(TimeSpan.FromSeconds(dur));
            }

            // FUNDIDO DE SALIDA del video: igual que las canciones, el final baja suave en vez de cortar en
            // seco. El video se da por terminado en dur-0.6 (ver abajo), asi que la rampa se mide contra ESE
            // final para que llegue a cero justo a tiempo. Durante el fundido se sondea mas seguido (80 ms)
            // para que la bajada se oiga continua; al terminar vuelve al sondeo normal.
            int volBase = VideoVolumeFor(nowPlaying != null ? nowPlaying.VideoPath : null);
            if (crossfadeSec > 0.01f && dur > 0.5 && pos >= 0)
            {
                double restan = (dur - 0.6) - pos;
                if (restan < crossfadeSec)
                {
                    double f = restan / crossfadeSec; if (f < 0) f = 0; else if (f > 1) f = 1;
                    videoPoll.Interval = 80;
                    SetVideoVolume((int)Math.Round(volBase * f));
                }
                else { videoPoll.Interval = 400; SetVideoVolume(volBase); }
            }
            else SetVideoVolume(volBase);

            // FIN NORMAL del video (sin reembolso, se reprodujo bien): MediaEnded (8); o la posicion
            // alcanzo la duracion (algunos archivos se congelan en el ultimo cuadro y NO reportan
            // MediaEnded -> esto era lo que dejaba la pantalla negra pegada); o Stopped tras reproducirse.
            bool reachedEnd = (dur > 0.5 && pos >= dur - 0.6);
            bool stoppedAfterPlaying = (st == 1 && videoMaxPos >= 3.0);
            if (st == 8 || reachedEnd || stoppedAfterPlaying) { PlayNext(); return; }

            // Stopped (1) SIN haberse reproducido = fallo real de arranque -> reembolso + saltar.
            if (st == 1 && videoMaxPos < 3.0)
            {
                try { LogError("video detenido sin reproducir: " + (nowPlaying != null ? nowPlaying.VideoPath : "?"), null); } catch { }
                RefundCredit();
                ShowToast("Video no disponible: credito devuelto", Color.FromArgb(200, 130, 35));
                PlayNext();
                return;
            }

            // VIGIA DE VIDEO COLGADO: si la posicion AVANZA, todo bien (se reinicia el cronometro). Si NO
            // avanza 12 segundos seguidos (y sin haber llegado al final), se da por fallido y se SALTA solo.
            if (pos > videoLastPos + 0.05) { videoLastPos = pos; videoProgressTick = now; }
            else if (now - videoProgressTick > 6000 && !videoNudged)
            {
                // 6s sin avanzar: un EMPUJON de rescate (play explicito) por si fue una traba transitoria
                // (no el codec). Si el archivo es reproducible pero se atoro, esto suele revivirlo.
                videoNudged = true;
                try { object oc = video.GetOcxObj(); if (oc != null) { object c = Get(oc, "controls"); if (c != null) Call(c, "play"); } } catch { }
            }
            else if (now - videoProgressTick > 12000)
            {
                // 12s sin avanzar pese al empujon: el sistema no puede con este archivo (codec ausente o
                // archivo ilegible). Se salta solo y se anota la ruta para identificarlo.
                try { LogError("video estancado (playState=" + st + "): " + (nowPlaying != null ? nowPlaying.VideoPath : "?"), null); }
                catch { }
                RefundCredit();   // compensacion al cliente: el video no se pudo reproducir
                ShowToast("Video no disponible: credito devuelto", Color.FromArgb(200, 130, 35));
                PlayNext();
            }
        }

        // Late-binding por reflexion: le hablamos al control WMP sin referencias COM ni 'dynamic'
        // (asi funciona igual en .NET 6 y en .NET 3.5/4.0 de XP).
        private static object Get(object o, string prop)
        {
            return o.GetType().InvokeMember(prop, BindingFlags.GetProperty, null, o, null);
        }
        private static void Set(object o, string prop, object val)
        {
            o.GetType().InvokeMember(prop, BindingFlags.SetProperty, null, o, new object[] { val });
        }
        private static object Call(object o, string method, params object[] args)
        {
            return o.GetType().InvokeMember(method, BindingFlags.InvokeMethod, null, o, args);
        }

        private void ApplyGenreBackground(Track t, Album org)
        {
            Color acc = ColorDeLoQueSuena(t, org);   // excepcion por artista (BTS=morado) y luego genero
            bgAccentTarget = acc;
            Color panel = Shade(acc, 0.70);
            Color list = Shade(acc, 0.76);
            panelSongs.BackColor = panel;
            if (songPager != null) { songPager.BackColor = panel; songPager.Invalidate(); }
            cubeBox.BackColor = Color.Transparent;
            songList.BackColor = list; songList.Accent = acc;
            RefrescaLista();
        }

        // ===== Puente con el motor de IA en vivo (carpeta compartida, mismo hash que daemon_ia.py) =====
        // Cache compartida con el motor. Por defecto: la MISMA que usa daemon_ia.py (ia\tiempo_real\cache),
        // hallada junto a la rocola -> rocola y motor coinciden SOLOS, sin configurar ni arrastrar nada.
        private string IaCache()
        {
            if (!string.IsNullOrEmpty(iaCacheDir)) return iaCacheDir;
            string py, dm;
            if (IaFindEngine(out py, out dm)) return Path.Combine(Path.GetDirectoryName(dm), "cache");
            return RutaDatos("ia_cache");
        }

        // Hash IDENTICO al de daemon_ia.py: sha1( ruta_absoluta_minusculas | tamano_bytes | mezcla )[:16].
        private static string IaHashFor(string path, string mezcla)
        {
            try
            {
                string full = Path.GetFullPath(path).ToLowerInvariant();
                long size = 0; try { size = new FileInfo(path).Length; } catch { }
                byte[] data = Encoding.UTF8.GetBytes(full + "|" + size + "|" + mezcla);
                using (System.Security.Cryptography.SHA1 sha = System.Security.Cryptography.SHA1.Create())
                {
                    byte[] h = sha.ComputeHash(data);
                    StringBuilder sb = new StringBuilder(40);
                    for (int i = 0; i < h.Length; i++) sb.Append(h[i].ToString("x2"));
                    return sb.ToString().Substring(0, 16);
                }
            }
            catch { return null; }
        }

        // Ruta de la version IA ya lista para esta cancion; la ruta ORIGINAL (con yaBuena=true) si el
        // motor ya la analizo y era de calidad completa (marca .orig: no gasta disco ni necesita IA);
        // o null si aun no hay nada en cache.
        private string IaEnhancedPath(string path, out bool yaBuena)
        {
            yaBuena = false;
            try
            {
                string h = IaHashFor(path, iaMezcla); if (h == null) return null;
                string dir = Path.Combine(IaCache(), "listos");
                string p = Path.Combine(dir, h + ".mp3"); if (File.Exists(p)) return IaTouch(p);   // cache nueva (MP3 320: ~5x mas canciones por GB)
                p = Path.Combine(dir, h + ".wav"); if (File.Exists(p)) return IaTouch(p);          // cache vieja (WAV), sigue valiendo
                if (File.Exists(Path.Combine(dir, h + ".orig"))) { yaBuena = true; return path; }
                return null;
            }
            catch { return null; }
        }

        // Marca "recien usada" la version de cache que va a sonar. La limpieza del motor borra por fecha
        // de ULTIMA LECTURA (lo menos escuchado primero), pero Windows suele tener apagada esa fecha en
        // discos secundarios: sin este toque explicito, la limpieza degradaria a "borrar lo mas viejo
        // aunque suene a diario" y esas canciones se reprocesarian una y otra vez.
        private static string IaTouch(string p)
        {
            try { File.SetLastAccessTime(p, DateTime.Now); } catch { }
            return p;
        }

        // Le pide al motor que procese esta cancion (deja un .job atomico). Barato e idempotente.
        private void IaRequestJob(string path)
        {
            try
            {
                if (string.IsNullOrEmpty(path)) return;
                string h = IaHashFor(path, iaMezcla); if (h == null) return;
                string pend = Path.Combine(IaCache(), "pendientes");
                string dirL = Path.Combine(IaCache(), "listos");                          // ya atendida (mejorada o marcada de calidad completa): no re-pedir
                if (File.Exists(Path.Combine(dirL, h + ".mp3")) || File.Exists(Path.Combine(dirL, h + ".wav"))
                    || File.Exists(Path.Combine(dirL, h + ".orig"))) return;
                Directory.CreateDirectory(pend);
                string job = Path.Combine(pend, h + ".job");
                if (File.Exists(job)) return;
                string esc = path.Replace("\\", "\\\\").Replace("\"", "\\\"");
                string json = "{\"src\":\"" + esc + "\",\"mezcla\":\"" + iaMezcla + "\"}";
                string tmp = job + ".tmp";
                File.WriteAllText(tmp, json);
                try { if (File.Exists(job)) File.Delete(job); } catch { }
                File.Move(tmp, job);   // aparicion atomica del job
            }
            catch { }
        }

        // ¿Esta corriendo el motor de IA? Primero el testigo mas fuerte: el PROCESO que esta rocola
        // lanzo sigue vivo (aunque Apollo apenas este cargando y el latido aun no exista). Si no,
        // el "latido" (motor.vivo, que el motor refresca cada ~3s desde un hilo, SIEMPRE, incluso
        // a mitad de un trabajo largo). Sin esto, el vigia lanzaba motores de mas: N Apollos a la
        // vez = toda la RAM/VRAM del equipo (el candado motor.lock del motor es la ultima barrera).
        private bool IaMotorAlive()
        {
            try
            {
                System.Diagnostics.Process p = iaMotorProc;
                if (p != null && !p.HasExited) return true;
                string v = Path.Combine(IaCache(), "motor.vivo"); return File.Exists(v) && (DateTime.Now - File.GetLastWriteTime(v)).TotalSeconds < 15;
            }
            catch { return false; }
        }

        // Busca el motor (Python del venv + daemon) junto al programa o hasta 5 niveles arriba (como la carpeta 'musica').
        private static bool IaFindEngine(out string python, out string daemon)
        {
            python = null; daemon = null;
            try
            {
                string dir = Application.StartupPath;
                for (int i = 0; i < 6 && dir != null; i++)
                {
                    string py = Path.Combine(dir, "ia\\upscale\\venv\\Scripts\\pythonw.exe");
                    string dm = Path.Combine(dir, "ia\\tiempo_real\\daemon_ia.py");
                    if (File.Exists(py) && File.Exists(dm)) { python = py; daemon = dm; return true; }
                    DirectoryInfo p = Directory.GetParent(dir);
                    dir = (p != null) ? p.FullName : null;
                }
            }
            catch { }
            return false;
        }

        // Lanza el motor de IA OCULTO (sin ventana) si no esta corriendo ya. Asi la IA en vivo "solo funciona":
        // el operador no cuida ninguna terminal. Si el motor no esta instalado, no pasa nada (la IA no actua).
        private System.Diagnostics.Process iaMotorProc;
        private int iaMotorLaunchTick = 0;
        private void IaEnsureMotor()
        {
            try
            {
                if (IaMotorAlive()) return;                       // ya corre (este arranque u otro): no duplicar
                if (iaMotorLaunchTick != 0 && Environment.TickCount - iaMotorLaunchTick < 20000) return;   // lanzado hace poco: dale ~20s a cargar Apollo antes de reintentar (sin enjambre)
                string py, dm;
                if (!IaFindEngine(out py, out dm)) return;        // sin motor: la IA en vivo simplemente no hace nada
                System.Diagnostics.ProcessStartInfo psi = new System.Diagnostics.ProcessStartInfo();
                psi.FileName = py;                                // pythonw.exe = sin ventana negra
                psi.Arguments = "\"" + dm + "\" --cache \"" + IaCache() + "\" --gpu " + iaGpu;
                psi.WorkingDirectory = Path.GetDirectoryName(dm);
                psi.UseShellExecute = false; psi.CreateNoWindow = true;
                psi.WindowStyle = System.Diagnostics.ProcessWindowStyle.Hidden;
                iaMotorProc = System.Diagnostics.Process.Start(psi);
                iaMotorLaunchTick = Environment.TickCount;
            }
            catch { }
        }

        // GPUs CUDA que el motor detecto (cache\gpus.txt: una linea por GPU, el indice es la posicion).
        // Lo escribe el motor al arrancar; si aun no existe, el selector muestra solo "Automatica".
        private string[] IaGpuList()
        {
            try
            {
                string f = Path.Combine(IaCache(), "gpus.txt");
                if (!File.Exists(f)) return new string[0];
                List<string> lines = new List<string>();
                foreach (string l in File.ReadAllLines(f)) if (l.Trim().Length > 0) lines.Add(l.Trim());
                return lines.ToArray();
            }
            catch { return new string[0]; }
        }

        // Reinicia el motor de IA (para aplicar YA un cambio de GPU): mata el que lanzo esta rocola,
        // suelta el freno de 20s y lo relanza con los argumentos nuevos. Si el motor corriendo es de
        // otro (iniciar_motor.bat a mano), no se puede matar desde aqui: el cambio aplica cuando muera.
        private void IaRestartMotor()
        {
            try { if (iaMotorProc != null && !iaMotorProc.HasExited) iaMotorProc.Kill(); } catch { }
            iaMotorProc = null; iaMotorLaunchTick = 0;
            if (iaVivo) IaEnsureMotor();
        }

        // Al encender la IA: prepara lo que ya esta sonando y en cola (para que la IA los alcance).
        private void IaRequestQueueJobs()
        {
            try
            {
                if (nowPlaying != null && !nowPlaying.IsVideo && nowPlaying.Song != null) IaRequestJob(nowPlaying.Song.Path);
                for (int i = 0; i < queue.Count; i++) if (!queue[i].IsVideo && queue[i].Song != null) IaRequestJob(queue[i].Song.Path);
            }
            catch { }
        }

        private void PlayTrack(Track t)
        {
            try
            {
                string iaSrc = t.Path;   // IA EN VIVO: si ya hay version mejorada en cache, suena ESA; si no, la original (y se pide para la proxima)
                iaNowEnhanced = false;
                if (iaVivo && t.Path != null)
                {
                    bool yaBuena;
                    string enh = IaEnhancedPath(t.Path, out yaBuena);
                    if (enh != null) iaSrc = enh; else IaRequestJob(t.Path);   // aun no lista: suena la original y se pide para la proxima
                    iaNowEnhanced = (enh != null && !yaBuena);   // [IA] solo si de verdad suena la version mejorada (con .orig suena el original tal cual)
                }
                // Y con ULTRA encendido, todo lo que NO suene por la version de Apollo lo atiende el DSEE
                // normal mientras tanto. Las marcadas .orig incluidas: ahi suena el original, y si le falta
                // banda el reconstructor la recrea; si no le falta, es un pase directo que no cuesta nada.
                RevisaRespaldoDsee();
                // Si la version de la CACHE no abre (la limpieza la borro justo en este instante, o quedo
                // un encode raro), NO se salta la cancion ni se anota el ORIGINAL como incompatible ni se
                // devuelve el credito: el archivo malo se borra (el motor lo regenera) y suena el original.
                try { reader = OpenAudio(iaSrc); }
                catch (Exception cex)
                {
                    if (iaSrc == t.Path) throw;                    // fallo el original de verdad: al catch de abajo
                    LogError("cache IA no abre (suena el original): " + Path.GetFileName(iaSrc), cex);
                    try { File.Delete(iaSrc); } catch { }          // solo puede ser un archivo de la cache (regenerable)
                    IaRequestJob(t.Path);                          // que el motor la vuelva a preparar
                    iaSrc = t.Path; iaNowEnhanced = false; RevisaRespaldoDsee();
                    reader = OpenAudio(t.Path);
                }
                reader.Volume = FixedVolume;   // se queda en 1.0 (crudo): el nivelado se aplica en LevelTap, tras medir el volumen REAL
                // NIVELADO: si esta cancion ya se oyo antes, se aplica la ganancia que la lleva al nivel comun; si es
                // nueva, va a su volumen original y se APRENDE su sonoridad en esta pasada (para nivelarla la proxima vez).
                curMeasurePath = (normalizeOn && !durCache.ContainsKey(t.Path)) ? t.Path : null;   // ya pre-analizada = medida COMPLETA y fiable: no se vuelve a medir (y se ahorra el K-weighting)
                curSumSq = 0; curSamples = 0;
                eqMeasPath = (EqMideHuella && !durCache.ContainsKey(t.Path)) ? t.Path : null;   // huella tonal: solo si no la trae ya del pre-analisis (que la mide completa)
                eqMeasCut = 0f;   // el acantilado es de ESTA cancion: se vuelve a medir
                eqMeasSum = new double[8]; eqMeasN = 0; eqMeasRate = 0;
                kwRate = 0;   // reinicia el estado del K-weighting: cada cancion mide desde cero (sin cola del filtro anterior)
                // NIVEL 2 (reconstructor espectral): solo se INSERTA en maquinas que cumplen requisitos; con
                // Active=false es un pase directo (costo ~cero). Ctrl+F3 lo alterna EN VIVO para comparar A/B.
                NAudio.Wave.ISampleProvider chain = reader;
                // DES-RECORTE: repara picos aplastados de origen (antes de medir y de DSEE). Ya sabemos, cancion
                // por cancion, si de verdad viene recortada; en las que NO -que son la mayoria- ni se pone en la
                // cadena: se ahorra su trabajo y su retardo de ~1.5 ms. Si aun no esta medida, se pone por si acaso.
                if (declipOn && DeclipVale(t.Path)) chain = new DeclipProvider(chain);
                if (sbrAllowed) { curSbr = new SpectralTap(chain, VentanaDsee()); curSbr.Active = DseeActivo(); chain = curSbr; }   // HD: ventana fina; respaldo espectral si ULTRA aun no tiene la version IA
                else curSbr = null;
                LevelTap tap = new LevelTap(chain, this);
                tap.Gain = NormGainFor(t.Path);
                tap.Excite = ExciteAmountFor(t.Path);   // realce de agudos: mas a las dañadas, menos a las que ya traen su aire
                tap.Master = MasterLin() * FactorNoche();  // SUBIR TODO (con rodilla suave anti-distorsion), y de madrugada mas bajo
                tap.EqDb = EqCorrFor(t.Path);      // EQ automatico: correccion aprendida (null la 1a vez que suena)
                curTap = tap;   // referencia para ajustar la ganancia en vivo (Ctrl+F3)
                // BAJO PSICOACUSTICO: despues de nivelar/ecualizar y ANTES del limitador, que es quien controla
                // los picos que anaden los armonicos.
                bassSongFactor = BassFactorFor(t.Path);   // cuanto le toca a ESTA cancion (1 = la perilla tal cual)
                bassAutoBase = BajoAuto(t.Path);          // y de cuanto se parte, si el bajo va en automatico
                curBass = new DeepBassProvider(tap, BassAmountNow());
                NAudio.Wave.ISampleProvider outChain = new LookaheadLimiter(curBass, 0.98f, 3.0);   // limitador con pre-escucha (picos limpios)
                if (crossfadeSec > 0.01f)
                {
                    // CUANTO DURA. Se pregunta primero a lo que el pre-analisis dejo apuntado, que es de
                    // donde lo saca tambien el turno de la cola. Preguntarselo AL ARCHIVO obliga a
                    // recorrerlo entero cuando no trae la cuenta escrita, que es lo normal: 3.87 ms y
                    // nueve megas de disco en una cancion de cuatro minutos, y aqui eso caeria en el hilo
                    // de la pantalla, en el instante en que el cliente acaba de soltar el boton. El camino
                    // largo se deja solo para las canciones de las que aun no se sabe nada.
                    long tf = 0;
                    try
                    {
                        int hz = reader.WaveFormat.SampleRate;
                        float yaSe = SegundosDe(t.Path);
                        tf = (yaSe > 0.01f) ? (long)(yaSe * hz) : (long)(reader.TotalTime.TotalSeconds * hz);
                    }
                    catch { }
                    outChain = new FadeProvider(outChain, tf, crossfadeSec);   // fundido suave de entrada/salida
                }
                // ===== SALIDA DE AUDIO (rama HD) =====
                // WASAPI compartido con muestras FLOTANTES: float de punta a punta hasta el motor de audio
                // moderno (sin bajar a 16 bits ni pasar por el mezclador clasico) y latencia menor. Si
                // CUALQUIER paso falla (driver raro, formato, Windows viejo), cae SOLO al WaveOut clasico
                // de siempre. salida= en config: auto (WASAPI si la maquina es HD) | wasapi | waveout.
                bool wantWasapi = outPref == "wasapi" || (outPref != "waveout" && tierHd);
                bool isWasapi = false;
                output = null;
                if (wantWasapi && Environment.OSVersion.Version.Major >= 6)
                {
                    NAudio.Wave.WasapiOut wa = null;
                    try
                    {
                        wa = new NAudio.Wave.WasapiOut(NAudio.CoreAudioApi.AudioClientShareMode.Shared, 300);   // 300ms: colchon comodo con latencia baja
                        wa.Init(new NAudio.Wave.SampleProviders.SampleToWaveProvider(outChain));   // FLOAT de punta a punta (nada de 16 bits)
                        wa.PlaybackStopped += Output_PlaybackStopped;
                        output = wa; isWasapi = true;
                    }
                    catch (Exception wex)
                    {
                        LogError("WasapiOut (cayendo a WaveOut)", wex);
                        if (wa != null) { try { wa.Dispose(); } catch { } }
                        output = null;
                    }
                }
                if (output == null)
                {
                    // Camino CLASICO: WaveOut con callback por ventana y 1 SEGUNDO de colchon (aguanta
                    // cualquier atoron). Rellenar 200ms de MP3 cuesta ~2-5ms de CPU: el colchon sale gratis.
                    WaveOut wo = new WaveOut();
                    wo.DesiredLatency = 1000;
                    // BLOQUES CORTOS. Por este camino el audio se rellena DESDE EL HILO DE LA PANTALLA,
                    // asi que cada vez que se vacia un bloque la interfaz se para en seco a descifrar MP3 y a
                    // pasarlo por toda la cadena de sonido. Con 5 bloques de 200 ms esa parada era larga y
                    // ocurria 5 veces por segundo: en una maquina justa se comia un cuadro entero cada vez, y
                    // eso se sentia como tirones MIENTRAS SUENA MUSICA (sobre todo en el buscador, que es lo
                    // que mas dibuja). Con 20 bloques de 50 ms se hace el MISMO trabajo total, pero repartido
                    // en pausas cuatro veces mas cortas, que caben de sobra dentro de un cuadro. El colchon
                    // sigue siendo de 1 segundo. (Por WASAPI esto no aplica: alli rellena su propio hilo.)
                    wo.NumberOfBuffers = 20;    // 20 bloques de 50ms (mismo segundo de colchon, pausas 4 veces mas cortas)
                    output = wo;
                    output.PlaybackStopped += Output_PlaybackStopped;
                    output.Init(new DitherWaveProvider16(outChain));   // 16 bits CON dither TPDF (menos aspereza en pasajes silenciosos)
                }
                audioVisualDelayMs = isWasapi ? 240 : 850;   // el pulso visual se alinea al colchon REAL de la salida en uso
                output.Play();
                progressTimer.Start();
                PrecalientaSiguiente();   // la que viene detras, leida en segundo plano (ver arriba)
            }
            catch (Exception ex)
            {
                lblStatus.Text = "No se pudo reproducir " + Path.GetFileName(t.Path) + " (" + ex.Message + ")";
                LogError("PlayTrack " + Path.GetFileName(t.Path), ex);
                NoteIncompatible(t.Path, ex);   // ni con el lector tolerante: deja la ruta en rocola_incompatibles.txt para repararla
                RefundCredit();   // la cancion que el cliente pago no sono: se le devuelve el credito
                ShowToast("No se pudo reproducir: credito devuelto", Color.FromArgb(200, 80, 70));
                DisposePlaybackNow();
                // OPTIMIZACION (estabilidad): antes era PlayNext() directo. Si varias canciones seguidas
                // no abren (archivos movidos/corruptos) se apilaba PlayTrack->PlayNext->PlayTrack... hasta
                // un posible StackOverflow. Via BeginInvoke se desenreda la pila (igual que en el video).
                try { if (this.IsHandleCreated) this.BeginInvoke((MethodInvoker)delegate { PlayNext(); }); } catch { }
            }
        }

        // Abre el audio. Camino NORMAL: FileAudioSource (rapido, para el 99.99% de los archivos). Si NAudio lo
        // rechaza (tipico: MP3 que CAMBIA de frecuencia a mitad -> "Got a frame at sample rate ..."), reintenta con
        // un lector TOLERANTE que reconstruye el MP3 dejando solo los frames de la frecuencia dominante. Si tampoco
        // asi, relanza el error original (el llamador lo anota y salta). El reintento NUNCA afecta a los archivos
        // sanos y, en el peor caso, hace lo mismo que antes: saltar.
        private IAudioSource OpenAudio(string path)
        {
            try { return new FileAudioSource(path); }
            catch
            {
                bool isMp3 = path != null && path.Length > 4 && path.EndsWith(".mp3", StringComparison.OrdinalIgnoreCase);
                if (isMp3)
                {
                    MemoryStream clean = null;
                    try
                    {
                        clean = BuildCleanMp3(path);
                        if (clean != null) return new TolerantMp3Source(clean);   // reconstruido a una sola frecuencia: ahora SI suena
                    }
                    catch { if (clean != null) { try { clean.Dispose(); } catch { } } }   // el tolerante tampoco pudo: cae al throw de abajo
                }
                throw;   // que el catch de PlayTrack muestre el aviso, lo anote y salte a la siguiente
            }
        }

        // Reconstruye un MP3 de frecuencia MEZCLADA como uno de una sola frecuencia (la dominante), copiando solo
        // los frames de esa frecuencia a memoria. NAudio 1.9 no soporta cambios de frecuencia dentro de un MP3;
        // esto le entrega un stream que SI puede reproducir. Los frames de la minoria (raros) se descartan: a lo
        // sumo un pequeño salto. Todo con la API de frames de NAudio, disponible en XP (decodificacion ACM).
        private static MemoryStream BuildCleanMp3(string path)
        {
            Dictionary<int, int> rateCount = new Dictionary<int, int>();
            using (FileStream fs = File.OpenRead(path))               // pasada 1: cuenta frecuencias -> elige la DOMINANTE
            {
                while (true)
                {
                    Mp3Frame f; try { f = Mp3Frame.LoadFromStream(fs); } catch { break; }
                    if (f == null) break;
                    int c; rateCount.TryGetValue(f.SampleRate, out c); rateCount[f.SampleRate] = c + 1;
                }
            }
            if (rateCount.Count == 0) return null;
            int domRate = 0, best = -1;
            foreach (KeyValuePair<int, int> kv in rateCount) if (kv.Value > best) { best = kv.Value; domRate = kv.Key; }

            MemoryStream ms = new MemoryStream();
            using (FileStream fs = File.OpenRead(path))               // pasada 2: copia SOLO los frames de la frecuencia dominante
            {
                while (true)
                {
                    Mp3Frame f; try { f = Mp3Frame.LoadFromStream(fs); } catch { break; }
                    if (f == null) break;
                    if (f.SampleRate == domRate && f.RawData != null) ms.Write(f.RawData, 0, f.RawData.Length);
                }
            }
            if (ms.Length < 2048) { ms.Dispose(); return null; }     // casi nada util: que el tolerante falle y se salte
            ms.Position = 0;
            return ms;
        }

        // Anota (una sola vez, incluso entre reinicios) una cancion que no se pudo reproducir, en rocola_incompatibles.txt
        // junto al .exe: lista lista para reconvertir esos pocos archivos (p.ej. con ffmpeg -ar 44100).
        private void NoteIncompatible(string path, Exception ex)
        {
            try
            {
                if (string.IsNullOrEmpty(path) || !incompatibleLogged.Add(path)) return;   // ya anotada
                string reason = (ex != null) ? ex.Message : "desconocido";
                if (reason.Length > 160) reason = reason.Substring(0, 160);
                File.AppendAllText(RutaDatos("rocola_incompatibles.txt"),
                    DateTime.Now.ToString("yyyy-MM-dd HH:mm") + "  |  " + path + "  |  " + reason + "\r\n");
            }
            catch { }
        }

        // Carga las rutas ya anotadas para no repetirlas en rocola_incompatibles.txt entre reinicios.
        private void LoadIncompatible()
        {
            try
            {
                string f = RutaDatos("rocola_incompatibles.txt");
                if (!File.Exists(f)) return;
                foreach (string line in File.ReadAllLines(f))
                {
                    int a = line.IndexOf("  |  ");
                    if (a < 0) continue;
                    int b = line.IndexOf("  |  ", a + 5);
                    string p = (b > a) ? line.Substring(a + 5, b - (a + 5)) : line.Substring(a + 5);
                    p = p.Trim();
                    if (p.Length > 0) incompatibleLogged.Add(Pool(p));
                }
            }
            catch { }
        }

        // Guarda el error completo (tipo + mensaje + pila) en rocola_error.txt junto al .exe,
        // para poder ver el metodo exacto que falta (p. ej. por una version equivocada de NAudio).
        private void LogError(string context, Exception ex)
        {
            try
            {
                string f = RutaDatos("rocola_error.txt");
                string msg = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "  [" + context + "]\r\n"
                           + (ex != null ? ex.ToString() : "(sin excepcion)") + "\r\n\r\n";
                try { FileInfo fi = new FileInfo(f); if (fi.Exists && fi.Length > 262144) fi.Delete(); } catch { }   // tope ~256KB
                File.AppendAllText(f, msg);
            }
            catch { }
        }

        private void Output_PlaybackStopped(object sender, StoppedEventArgs e)
        {
            // WASAPI (rama HD) avisa desde SU hilo de reproduccion; todo lo de abajo toca UI -> saltar al hilo de la interfaz
            if (InvokeRequired) { try { BeginInvoke((MethodInvoker)delegate { Output_PlaybackStopped(sender, e); }); } catch { } return; }
            if (e.Exception != null)
            {
                lblStatus.Text = "Aviso al reproducir: " + e.Exception.Message;
                LogError("PlaybackStopped", e.Exception);
                RefundCredit();   // la cancion que el cliente pago fallo al reproducirse: se le devuelve el credito
                ShowToast("No se pudo reproducir: credito devuelto", Color.FromArgb(200, 80, 70));
                playFailStreak++;
                if (playFailStreak >= 3)
                {
                    // Algo de fondo esta mal (NAudio o formato). Dejamos de saltar para no ciclar.
                    DisposePlaybackNow();
                    nowPlaying = null;
                    RefrescaCola();   // idem: sin cancion no hay marca de "SONANDO"
                    lblStatus.Text = "No se pudo reproducir. Detalle en rocola_error.txt (junto al programa)";
                    UpdateNowPlayingUI();
                    return;
                }
            }
            else playFailStreak = 0;   // termino bien una cancion -> reinicia el contador
            PlayNext();
        }

        private void DisposePlaybackNow()
        {
            progressTimer.Stop();
            if (output != null)
            {
                output.PlaybackStopped -= Output_PlaybackStopped;
                try { output.Stop(); } catch { }
                try { output.Dispose(); } catch { }
                output = null;
            }
            if (reader != null) { try { reader.Dispose(); } catch { } reader = null; }
            curTap = null; curSbr = null; curBass = null;   // ya no hay taps actuales
            FinalizeLoudMeasure();   // guarda la sonoridad medida de la cancion que acaba de sonar (audio ya detenido: sin carrera)
            FinalizeEqMeasure();     // y su huella tonal (mismo momento seguro)
            lock (levelLock) levelQ.Clear();   // sin cancion no hay trozos pendientes: el pulso cae a cero
            rmsLo = rmsMid = rmsHi = 0f; avgLo = avgMid = avgHi = 0f;
        }

        // La llama el hilo de audio con el bloque recien leido: lo parte en sub-trozos de ~50ms, calcula el
        // RMS de cada uno y lo encola con la MARCA DE TIEMPO en que ese trozo SONARA (ahora + colchon).
        // El temporizador de UI los consume cuando les llega su momento -> el pulso va CON lo que se oye.
        // Buffers reusables del hilo de audio (4 trozos x 3 bandas). ThreadStatic: sin asignar por bloque.
        [ThreadStatic] private static float[] tmpLo; [ThreadStatic] private static float[] tmpMid; [ThreadStatic] private static float[] tmpHi;
        [ThreadStatic] private static float[] tmpEsp;   // 4 trozos x 8 bandas
        [ThreadStatic] private static double[] tmpSum;  // sumas por banda: reusado (nada de asignar en el hilo de audio)
        public void ReportAudioBlock(float[] buffer, int offset, int count, int rate, int ch)
        {
            if (count <= 0) return;
            int samplesPerSec = Math.Max(1, rate * ch);
            int now = Environment.TickCount;
            int chunks = 4; int len = count / chunks;
            if (len < 256) { chunks = 1; len = count; }   // bloque chico: un solo trozo
            float[] tLo = tmpLo ?? (tmpLo = new float[4]);
            float[] tMid = tmpMid ?? (tmpMid = new float[4]);
            float[] tHi = tmpHi ?? (tmpHi = new float[4]);
            float[] tEsp = tmpEsp ?? (tmpEsp = new float[4 * SpecBands]);
            // ESCALERA del espectro: los coeficientes se calculan al ritmo de CUADROS (rate), porque la escalera
            // trabaja sobre la mezcla mono de cada cuadro y no muestra por muestra del stream entrelazado. Asi los
            // cortes caen en los mismos Hz de siempre pero con la MITAD de trabajo, y ademas la diferencia entre
            // canales deja de colarse como falso "aire". Se recalculan solo si cambia el formato.
            bool espectro = EspectroActivo;
            if (espectro && (specCoef == null || specRate != rate))
            {
                specRate = rate;
                specCoef = new float[SpecCortes.Length];
                for (int k = 0; k < SpecCortes.Length; k++)
                {
                    double a = 1.0 - Math.Exp(-2.0 * Math.PI * SpecCortes[k] / Math.Max(1, rate));
                    specCoef[k] = (float)(a < 0.0 ? 0.0 : (a > 1.0 ? 1.0 : a));
                }
                specLp = new float[SpecCortes.Length * SpecPolos];
            }
            float[] sc = specCoef, sl = specLp;
            double[] sSum = tmpSum ?? (tmpSum = new double[SpecBands]);
            int chEsp = ch < 1 ? 1 : ch;
            float invCh = 1f / chEsp;
            float fSum = 0f; int fCnt = 0;   // acumulador del cuadro en curso (sigue vivo entre trozos del bloque)
            // Dos filtros paso-bajo de una via separan el audio en 3 bandas: grave = lp1, medio = lp2-lp1, agudo = x-lp2.
            // Los coeficientes marcan cortes aproximados (~150 Hz y ~2 kHz sobre el stream interleaved); es un
            // visualizador, no un ecualizador: basta que "se sienta" la separacion. El estado persiste entre bloques.
            const float A1 = 0.012f, A2 = 0.13f;
            float lp1 = fLp1, lp2 = fLp2;
            for (int c = 0; c < chunks; c++)              // el RMS se calcula FUERA del lock (no retiene a la UI)
            {
                int start = offset + c * len;
                int end = (c == chunks - 1) ? offset + count : start + len;
                double sumLo = 0, sumMid = 0, sumHi = 0;
                int nEsp = 0;
                for (int b = 0; b < SpecBands; b++) sSum[b] = 0;
                for (int i = start; i < end; i++)
                {
                    float v = buffer[i];
                    lp1 += (v - lp1) * A1;               // paso-bajo grave
                    lp2 += (v - lp2) * A2;               // paso-bajo medio
                    float lo = lp1, mid = lp2 - lp1, hi = v - lp2;
                    sumLo += lo * lo; sumMid += mid * mid; sumHi += hi * hi;
                    if (!espectro) continue;             // aurora apagada (o sin GPU): la escalera ni se toca
                    fSum += v;                           // junta los canales del cuadro; la escalera corre UNA vez por cuadro
                    if (++fCnt < chEsp) continue;
                    float m = fSum * invCh; fSum = 0f; fCnt = 0;
                    // ESPECTRO: cada peldano de la escalera se queda con lo que el anterior dejo pasar,
                    // asi que la resta de dos peldanos consecutivos ES la banda que hay entre sus cortes.
                    float ant = 0f;
                    for (int k = 0; k < 7; k++)
                    {
                        int q = k * SpecPolos;
                        float x = m, ck = sc[k];
                        // Cada polo se lleva a una local: antes se leia su casilla del array DOS veces por
                        // vuelta (una para sumarle y otra para volver a leerla) y el coeficiente en cada
                        // vuelta. Las cuentas son las mismas y en el mismo orden: el sonido no cambia ni un bit.
                        for (int pp = 0; pp < SpecPolos; pp++)
                        {
                            float pv = sl[q + pp];
                            pv += (x - pv) * ck;
                            sl[q + pp] = pv;
                            x = pv;
                        }
                        float bnd = x - ant; ant = x;     // lo que este peldano deja pasar menos lo del anterior
                        sSum[k] += bnd * bnd;
                    }
                    float top = m - ant;                 // lo que queda por encima del ultimo corte: el aire
                    sSum[7] += top * top;
                    nEsp++;
                }
                int n = Math.Max(1, end - start), ne = Math.Max(1, nEsp);
                tLo[c] = (float)Math.Sqrt(sumLo / n);
                tMid[c] = (float)Math.Sqrt(sumMid / n);
                tHi[c] = (float)Math.Sqrt(sumHi / n);
                for (int b = 0; b < SpecBands; b++) tEsp[c * SpecBands + b] = (float)Math.Sqrt(sSum[b] / ne);
            }
            fLp1 = lp1; fLp2 = lp2;   // persiste el estado de los filtros para el proximo bloque
            specLp = sl;
            // NIVELADO PERCEPTUAL (K-weighting, tipo LUFS/BS.1770): en vez del RMS crudo, mide la sonoridad
            // PESADA por como la oye el humano (realza agudos ~+4 dB, quita sub-graves) via 2 biquads/canal.
            // Asi una cancion con mucho bajo (que el RMS crudo sobre-estima) y una brillante quedan de verdad
            // al mismo volumen PERCIBIDO. Solo durante el aprendizaje de esta cancion.
            if (curMeasurePath != null)
            {
                if (kwRate != rate || kwCoef1 == null)
                {
                    kwRate = rate;
                    kwCoef1 = EqShelfHi(1681.974f, rate, 3.99984f, 0.70717f);   // "head" shelf de BS.1770
                    kwCoef2 = EqHighPass(38.1355f, rate, 0.50033f);             // RLB high-pass
                    kwSt = new float[Math.Max(1, ch) * 8];
                }
                int ch3 = ch < 1 ? 1 : ch;
                float[] st = kwSt, c1 = kwCoef1, c2 = kwCoef2;
                double sumK = 0; long nK = 0;
                for (int i = offset; i + ch3 <= offset + count; i += ch3)
                {
                    for (int c = 0; c < ch3; c++)
                    {
                        int b = c * 8; float x = buffer[i + c];
                        float y1 = c1[0]*x + c1[1]*st[b] + c1[2]*st[b+1] - c1[3]*st[b+2] - c1[4]*st[b+3];
                        st[b+1]=st[b]; st[b]=x; st[b+3]=st[b+2]; st[b+2]=y1;
                        float y2 = c2[0]*y1 + c2[1]*st[b+4] + c2[2]*st[b+5] - c2[3]*st[b+6] - c2[4]*st[b+7];
                        st[b+5]=st[b+4]; st[b+4]=y1; st[b+7]=st[b+6]; st[b+6]=y2;
                        sumK += y2 * y2;
                    }
                    nK++;
                }
                curSumSq += sumK; curSamples += nK * ch3;   // energia K-pesada (misma escala que el RMS de antes)
            }
            // EQ AUTOMATICO: huella tonal de la cancion (energia por banda via bandpass RBJ, mezcla MONO).
            // Solo durante el aprendizaje de esta cancion; ~70 operaciones por cuadro, costo despreciable.
            if (eqMeasPath != null)
            {
                if (eqMeasRate != rate || eqMeasCoef == null)
                {
                    eqMeasRate = rate; eqMeasCoef = new float[8][]; eqMeasSt = new float[8 * 4];
                    for (int b = 0; b < 8; b++) eqMeasCoef[b] = EqBpf(EqCentros[b], rate);
                }
                int ch2 = ch < 1 ? 1 : ch;
                float[] st = eqMeasSt; double[] sums = eqMeasSum;
                for (int i = offset; i + ch2 <= offset + count; i += ch2)
                {
                    float m = buffer[i];
                    for (int c2 = 1; c2 < ch2; c2++) m += buffer[i + c2];
                    m /= ch2;
                    for (int b = 0; b < 8; b++)
                    {
                        float[] cf = eqMeasCoef[b]; if (cf == null) continue;
                        int q = b * 4;
                        float o = cf[0] * m + cf[1] * st[q] + cf[2] * st[q + 1] - cf[3] * st[q + 2] - cf[4] * st[q + 3];
                        st[q + 1] = st[q]; st[q] = m;
                        st[q + 3] = st[q + 2]; st[q + 2] = o;
                        sums[b] += o * o;
                    }
                    eqMeasN++;
                }
            }
            lock (levelLock)
            {
                for (int c = 0; c < chunks; c++)
                {
                    int atMs = now + (int)((long)(c * len) * 1000 / Math.Max(1, samplesPerSec));   // desfase del trozo dentro del bloque
                    float[] esp = null;
                    if (espectro)
                    {
                        esp = new float[SpecBands];   // 48 bytes por trozo (~20/seg): nada para el recolector
                        for (int b = 0; b < SpecBands; b++) esp[b] = tEsp[c * SpecBands + b];
                    }
                    levelQ.Enqueue(new Lvl(atMs, tLo[c], tMid[c], tHi[c], esp));
                }
                while (levelQ.Count > 96) levelQ.Dequeue();   // acotado (~5s de historial maximo)
            }
        }

        // Detecta el golpe de UNA banda contra su propio piso movil y devuelve su pulso (0..1) con ataque instantaneo
        // y caida rapida. Como cada banda tiene MENOS energia que el total, sube algo la sensibilidad. Igual para las 3.
        private static float BandBeat(float rms, ref float avg, float lev)
        {
            avg += (rms - avg) * 0.06f;                                                     // piso movil (~0.7s)
            float beat = (rms > avg * 1.22f + 0.006f) ? Math.Min(1f, (rms - avg) * 11f) : 0f;   // cuanto SOBRESALE del piso
            float tgt = Math.Max(beat, Math.Min(1f, rms * 3.0f) * 0.22f);                  // golpe dominante + fondo suave
            if (tgt > lev) lev = tgt; else lev *= 0.78f;                                    // ataque instantaneo, caida rapida
            return lev < 0.003f ? 0f : lev;
        }

        private void UpdateNowPlayingUI()
        {
            if (nowPlaying != null)
            {
                string tit, art;
                nowPlaying.TituloArtista(out tit, out art);
                nowFullText = tit; nowArtista = art;
            }
            else { nowFullText = "Nada reproduciendose"; nowArtista = ""; }
            iaBadgeKind = MejKind();   // dorado = version IA (Apollo); plateado = DSEE espectral reconstruyendo DE VERDAD
            ActualizaGenero();    // la pastilla del genero, antes de acomodar: manda en el ancho del artista
            PositionMejorada();   // pone titulo y artista y coloca el letrero MEJORADA
            lblNext.Text = (queue.Count > 0) ? "Sigue:  " + queue[0].Display() : "Sigue:  -";
            pastCola.Valor = queue.Count.ToString();
            LlenaPortaditas();
            pastCola.Invalidate();
            if (miniCube != null)
            {
                if (nowPlaying != null)
                {
                    Image nueva = LoadCover(nowPlaying.Disc);
                    // EL RELEVO: si ya habia un cubo puesto con otra portada, no se cambia de golpe; el
                    // cubo da media vuelta y la nueva aparece en el camino. La primera cancion de la
                    // noche, y la portada que llega tarde a la que YA suena, entran sin giro: ahi no hay
                    // relevo de nada que enseñar.
                    if (relevoOn && miniCube.Visible && miniCube.Cover != null && nueva != null && !object.ReferenceEquals(nueva, miniCube.Cover))
                        miniCube.Relevo(nueva);
                    else if (!miniCube.Girando) miniCube.Cover = nueva;
                    miniCube.Visible = true;
                }
                else { miniCube.Cover = null; miniCube.Visible = false; }
                miniCube.Invalidate();
            }
        }

        // 0 = sin letrero, 1 = plateado (DSEE espectral RECONSTRUYENDO de verdad), 2 = dorado (version IA).
        // El plateado exige que la puerta interna del reconstructor este actuando: con el switch prendido
        // pero la cancion ya completa (pase directo) NO hay letrero, porque no se esta mejorando nada.
        private int MejKind()
        {
            if (nowPlaying == null || nowPlaying.IsVideo) return 0;
            if (iaNowEnhanced) return 2;
            SpectralTap sp = curSbr;
            return (DseeActivo() && sp != null && sp.Mejorando) ? 1 : 0;
        }

        // Coloca el letrero "MEJORADA" justo despues del texto de "Reproduciendo" (misma fila). Si el
        // titulo es largo, lblNow se ENCOGE (elipsa antes) para que el letrero siempre quepa sin encimarse.
        private void PositionMejorada()
        {
            if (lblMejorada == null || lblNow == null || lblNowTop == null) return;
            bool on = (iaBadgeKind != 0 && nowPlaying != null);
            int bw = 0;
            if (on)
            {
                lblMejorada.ForeColor = (iaBadgeKind == 2) ? IaGoldBase : IaSilverBase;   // color base: el brillo lo anima el tick (CPU) o un halo que recorre (GPU)
                bw = TextRenderer.MeasureText(lblMejorada.Text, lblMejorada.Font).Width + 4;
            }
            // El titulo va arriba y el artista debajo; el letrero se pone detras del ARTISTA, que es el renglon
            // corto, para no comerle sitio al titulo.
            if (lblNowTop.Text != nowFullText) lblNowTop.Text = nowFullText;
            if (lblNow.Text != nowArtista) lblNow.Text = nowArtista;
            if (lblNowTop.Width != iaNowRowW) lblNowTop.Width = iaNowRowW;

            // LA PASTILLA DEL GENERO va en este mismo renglon, entre el artista y el letrero: es de la
            // cancion, igual que el artista, y en el renglon de arriba -el titulo- no cabria sin comerle
            // sitio a lo unico que de verdad hay que leer entero.
            int gw = (pastGenero != null) ? pastGenero.AnchoQuePide() : 0;
            int anchoArt = iaNowRowW - (on ? bw + 12 : 0) - (gw > 0 ? gw + 12 : 0);
            if (anchoArt < 60) anchoArt = 60;
            if (lblNow.Width != anchoArt) lblNow.Width = anchoArt;

            int tw = TextRenderer.MeasureText(lblNow.Text, lblNow.Font).Width;
            if (tw > anchoArt) tw = anchoArt;
            int x = lblNow.Left + tw + 12;
            if (gw > 0)
            {
                int gh = Math.Min(pastGenero.AltoQuePide(), lblNow.Height);
                pastGenero.SetBounds(x, lblNow.Top + (lblNow.Height - gh) / 2, gw, gh);
                if (!pastGenero.Visible) pastGenero.Visible = true;
                x += gw + 12;
            }
            else if (pastGenero != null && pastGenero.Visible) pastGenero.Visible = false;

            if (!on) { if (lblMejorada.Visible) lblMejorada.Visible = false; return; }
            lblMejorada.SetBounds(x, lblNow.Top, bw, 22);
            lblMejorada.Visible = true;
        }

        // DE QUE ES LO QUE SUENA. La misma respuesta que dentro del disco y que en el buscador (GeneroDeCancion),
        // asi que las tres dicen lo mismo. Un VIDEO no lleva: no hay de donde sacarla. Si no se sabe, no sale
        // pastilla -mejor sin etiqueta que con una inventada-.
        private void ActualizaGenero()
        {
            if (pastGenero == null) return;
            string et = (nowPlaying != null && !nowPlaying.IsVideo) ? GeneroDeCancion(nowPlaying.Song, nowPlaying.Disc) : "";
            if (et == pastGenero.Texto) return;
            pastGenero.Texto = et;
            pastGenero.Tinte = (et.Length > 0) ? ColorDeEtiqueta(et) : DefaultAccent;
            PositionMejorada();   // el ancho del artista depende de si hay pastilla y de lo que mida
            // El genero se aprende en segundo plano, asi que puede llegar con la cancion ya sonando. El fondo
            // va del mismo color, asi que se entera aqui en vez de esperar a la siguiente.
            if (nowPlaying != null && !nowPlaying.IsVideo && panelSongs != null)
            {
                Color acc = ColorDeLoQueSuena(nowPlaying.Song, nowPlaying.Disc);
                if (acc.ToArgb() != bgAccentTarget.ToArgb()) ApplyGenreBackground(nowPlaying.Song, nowPlaying.Disc);
            }
        }

        // Reparte el texto entre la linea de ARRIBA (ancho completo) y la de ABAJO (la que comparte fila con el
        // letrero, asi que va mas estrecha). Si entra entero en la de abajo, la de arriba se queda vacia y se ve
        // exactamente igual que siempre. Se corta por ESPACIO; si una sola palabra no cabe, se corta por letra
        // antes que dejar el titulo mochado. Lo que aun sobre lo elipsa la propia etiqueta.
        private static void PartirNow(string texto, Font f, int anchoArriba, int anchoAbajo, out string arriba, out string abajo)
        {
            arriba = ""; abajo = texto ?? "";
            if (abajo.Length == 0 || anchoAbajo < 20) return;
            if (TextRenderer.MeasureText(abajo, f).Width <= anchoAbajo) return;   // cabe de una: nada que partir
            int tope = anchoArriba - 6;   // margen: la textura de la GPU dibuja con GDI+ y mide un pelo mas ancho
            int corte = -1;
            for (int i = 0; i < abajo.Length; i++)
            {
                if (abajo[i] != ' ') continue;
                if (TextRenderer.MeasureText(abajo.Substring(0, i), f).Width > tope) break;
                corte = i;   // el ultimo espacio que todavia cabe arriba
            }
            if (corte > 0) { arriba = abajo.Substring(0, corte); abajo = abajo.Substring(corte + 1); return; }
            // ni un espacio util (un titulo de una sola palabra larguisima): se corta por letra
            int n = 0;
            while (n + 1 < abajo.Length && TextRenderer.MeasureText(abajo.Substring(0, n + 1), f).Width <= tope) n++;
            if (n > 0 && n < abajo.Length) { arriba = abajo.Substring(0, n); abajo = abajo.Substring(n); }
        }

        // Anima el brillo del letrero MEJORADA. Sin panel GPU encima (gpuCovered=false) las letras RESPIRAN
        // de color (repintar una etiqueta chica es barato); con el panel GPU el texto va FIJO en la textura de
        // la franja y el brillo es un destello que RECORRE las letras (FillUiGlows): cero rehechas de textura.
        private void TickMejorada(bool gpuCovered)
        {
            if (lblMejorada == null) return;
            int k = MejKind();   // en cuanto el reconstructor ACTUA (~0.1s) el plateado aparece y queda TODA la cancion; el dorado (version IA) dura toda la cancion de origen
            if (k != iaBadgeKind || (k != 0) != lblMejorada.Visible) { iaBadgeKind = k; PositionMejorada(); }
            if (!lblMejorada.Visible) return;
            if (!gpuCovered)
            {
                double pm = 0.5 + 0.5 * Math.Sin(phase * 2.8);
                lblMejorada.ForeColor = LerpColor((iaBadgeKind == 2) ? IaGoldBase : IaSilverBase,
                                                  (iaBadgeKind == 2) ? IaGoldHi : IaSilverHi, pm);
            }
            else
            {
                Color bc = (iaBadgeKind == 2) ? IaGoldBase : IaSilverBase;
                if (lblMejorada.ForeColor.ToArgb() != bc.ToArgb()) lblMejorada.ForeColor = bc;   // al volver de CPU: color base fijo en la textura
            }
        }

        private void ProgressTimer_Tick(object sender, EventArgs e)
        {
            if (reader == null) return;
            TimeSpan cur = reader.CurrentTime, tot = reader.TotalTime;
            if (tot.TotalSeconds > 0) progress.Value = cur.TotalSeconds / tot.TotalSeconds;
            lblTime.Text = Fmt(cur) + " / " + Fmt(tot);
            // (la posicion ya NO se guarda: al reanudar tras un corte de luz la cancion arranca desde el
            // principio, asi que el estado solo se escribe en eventos -> cero escrituras periodicas a disco)
        }

        // DONDE VA LA CASILLA DE BUSCAR en la fila de arriba: en el MEDIO DE LA PANTALLA, que es donde el
        // ojo la busca. Si centrada pisaria las instrucciones se corre a la derecha lo justo, y si aun asi no
        // cabe antes del encabezado se pega al final del hueco. 'minX' es donde acaban las instrucciones y
        // 'derecha' donde acaba la barra.
        private static int SitioBusca(int W, int busW, int minX, int derecha)
        {
            int x = minX;
            int centrado = (W - busW) / 2;
            if (centrado > x) x = centrado;
            if (x + busW > derecha) { x = derecha - busW; if (x < minX) x = minX; }
            return x;
        }

#if ROCOLA_GPU
        // Donde arranca la franja de abajo. Solo lo usa el dibujado por tarjeta grafica: es donde se acaba
        // el cielo y donde empieza la tira de lo que suena.
        private int BotStripTop(int h)
        {
            int t = (lblNowTop != null) ? lblNowTop.Top - 10 : (lblNow != null ? lblNow.Top - 10 : h - 104);   // la franja arranca justo encima de la tarjeta
            if (t < h / 2) t = h / 2;
            if (t > h - 8) t = h - 8;
            if (t < 0) t = 0;   // pantalla de alto ridiculo (arrancando, o minimizada): nunca por delante del borde
            return t;
        }

        private static uint ToD3D(Color c) { return 0xFF000000u | ((uint)c.R << 16) | ((uint)c.G << 8) | (uint)c.B; }

        private bool gpuEnabled;                          // render por GPU activo. Por defecto SI (se guarda al alternar con Ctrl+F12)
        private bool gpuShowFps;                          // mostrar el contador de FPS (diagnostico). Oculto por defecto; Ctrl+F1 lo alterna
        private bool gpuDiscTry = true;                   // interior de disco por GPU (por defecto). Ctrl+F11 lo alterna a CPU como valvula de escape
        private int gpuMode = -1;                          // modo GPU actual (nav/buscador/disco/atraccion); al cambiar se rehace la UI atomica
        private int layoutStamp = -1;                      // huella del ultimo reacomodo: solo un cambio REAL rehace la textura de UI
        private Bitmap uiOverlay; private int uiOverlayVer; private long uiOverlaySig = SigNada;   // textura de las barras (UI)

        // Ctrl+F12: alterna el render entre GPU (Direct3D 9, por defecto) y CPU, y GUARDA la preferencia.
        private void ToggleAlbumGpu() { ApplyAlbumGpu(!gpuEnabled, true, true); }

        // Aplica el modo de render. 'on' = destino (GPU/CPU); 'announceFail' = avisar si el dispositivo no inicia;
        // 'persist' = guardar la preferencia (solo cuando lo pide el usuario con Ctrl+F12, no en el arranque). El
        // panel GPU (Direct3D 9) cubre toda la ventana y compone: fondo estrellado + cubos + barras + mini-cubo.
        private void ApplyAlbumGpu(bool on, bool announceFail, bool persist)
        {
            if (lblGpu == null)
            {
                lblGpu = new Label();
                lblGpu.AutoSize = false; lblGpu.Size = new Size(380, 26);
                lblGpu.Location = new Point(ClientSize.Width - 390, 46);
                lblGpu.BackColor = Color.FromArgb(200, 0, 0, 0); lblGpu.ForeColor = Color.Yellow;
                lblGpu.Font = new Font(FontFamily.GenericMonospace, 10f, FontStyle.Bold);
                lblGpu.TextAlign = ContentAlignment.MiddleCenter; lblGpu.Visible = false;
                Controls.Add(lblGpu);
            }
            if (gpuPanel == null)
            {
                gpuPanel = new GpuPanel();
                gpuPanel.ShowFps = gpuShowFps;
                gpuPanel.TopeFps = fpsTope;   // 0 = que lo decida el panel por el refresco de la pantalla
                AplicaEfectosGpu();           // y las perillas de los efectos (Ctrl+F3 -> Imagen y rendimiento)
                gpuPanel.GetPulse = delegate { return audioLevel; };
                gpuPanel.GetAurora = delegate { return BuildAuroraState(); };   // aurora del horizonte (espectro)
                gpuPanel.GetToast = delegate { return BuildToastState(); };     // aviso flotante (moneda, cancion agregada...)
                gpuPanel.GetTrans = delegate { return BuildTransState(); };   // zoom al entrar/salir de un disco
                gpuPanel.GetWin = delegate { return BuildWinState(); };        // ventana del buscador abriendo/cerrando
                gpuPanel.GetGrid = albumView.BuildGpuGrid;   // rejilla de discos: cada celda su propio quad con textura cacheada (hojear = elegir texturas + posiciones)
                gpuPanel.GetContour = delegate { return albumView.ContourSpriteBmp; };          // resalte de seleccion
                gpuPanel.GetContourRect = delegate {
                    Rectangle r = albumView.ContourScreenRect();
                    if (r.Width > 0) r.Offset(albumView.Left, albumView.Top);   // coords de albumView -> pantalla
                    return r;
                };
                gpuPanel.GetCubeState = delegate { return BuildGpuCubeState(); };   // album (offset a pantalla) + mini-cubo
                gpuPanel.GetUi = delegate { return uiOverlay; };                    // textura PRINCIPAL de la UI (altura segun el modo)
                gpuPanel.GetUiVersion = delegate { return EnsureUiOverlay(); };
                gpuPanel.GetUiBot = delegate { return uiBotOverlay; };              // franja de ESTADO de abajo (textura chica aparte: el reloj no rehace la principal)
                gpuPanel.GetUiBotVersion = delegate { return EnsureUiBotOverlay(); };
                gpuPanel.GetUiGlows = FillUiGlows;                                   // halos animados (destello de boton, pulso de letra, TOP, atraccion): quads GPU, sin re-subir textura
                // Las piezas vivas del buscador (tarjeta y tecla elegidas): imagenes chicas aparte, encima de
                // la grande. Sin esto, mover el recuadro re-subia la pantalla completa (ver EnsureUiPieza).
                gpuPanel.PiezasN = NumPiezas;
                gpuPanel.GetPieza = delegate(int i) { return uiPieza[i]; };
                gpuPanel.GetPiezaRect = delegate(int i) { return uiPiezaRect[i]; };
                gpuPanel.GetPiezaVersion = delegate(int i) { return EnsureUiPieza(i); };
                Controls.Add(gpuPanel);
            }
            if (on && !gpuEnabled)
            {
                albumView.InvalidateCubeCache();         // cubeCache fresco para subirlo a la GPU
                uiOverlaySig = SigNada;                     // fuerza reconstruir la textura de UI
                gpuPanel.AlbumRect = albumView.Bounds;
                gpuPanel.Bounds = new Rectangle(0, 0, ClientSize.Width, ClientSize.Height);   // PANTALLA COMPLETA
                gpuPanel.SkyTop = ToD3D(SkyColor(bgAccent)); gpuPanel.SkyMid = ToD3D(SkyColorMid(bgAccent)); gpuPanel.SkyBot = ToD3D(SkyColor2(bgAccent)); gpuPanel.NebColor = ToD3D(ColorNebulosa(bgAccent));
                gpuPanel.Visible = true; gpuPanel.BringToFront();
                if (gpuPanel.StartGpu())
                {
                    gpuEnabled = true; lblGpu.Visible = false; KeepVideoOnTop();
                    gpuPanel.PrecalientaAnimaciones(ThumbPx, ToastW, ToastH);   // texturas de las animaciones creadas YA, no en la primera que se vea
                }
                else { gpuPanel.Visible = false; Diag("render: FALLO el dispositivo D3D9 (sigue CPU)"); if (announceFail) { lblGpu.Text = "GPU: fallo el dispositivo (sigue CPU)"; lblGpu.Visible = true; lblGpu.BringToFront(); } }
            }
            else if (!on && gpuEnabled)
            {
                gpuEnabled = false;
                gpuPanel.StopGpu(); gpuPanel.Visible = false;
                SueltaPiezas();     // las piezas vivas del buscador solo existen para la tarjeta grafica
                if (albumView != null) albumView.GpuCovered = false;   // vuelve a pintar la rejilla por CPU (ya no hay panel encima)
                if (lblGpu != null) lblGpu.Visible = false;
                Invalidate(true);   // repinta la UI normal (CPU) que estaba tapada por el panel
            }
            if (persist) { gpuPrefOn = gpuEnabled; SaveConfigPrefs(); }   // recuerda la eleccion para el proximo arranque
        }


        // Estado de los cubos que giran (en coords de PANTALLA). En navegacion: album (seleccionado + relevo).
        // En el buscador: el cubo de vista previa. El mini-cubo de la barra inferior es comun a ambos.
        private GpuCubeState BuildGpuCubeState()
        {
            GpuCubeState st;
            if (attractOn && attractView != null)   // MODO ATRACCION: cubo gigante centrado que cicla portadas (con fundido)
            {
                st = new GpuCubeState();
                Image ca, cb; float f;
                attractView.GetCoverPair(out ca, out cb, out f);   // puede dar null (portadas aun cargando): el cubo muestra relleno azulado
                RectangleF cubo = AttractCubeRect();   // mismo rectangulo que usa la animacion de entrada/salida
                st.Sel.Has = true;
                st.Sel.X = cubo.X; st.Sel.Y = cubo.Y; st.Sel.W = cubo.Width; st.Sel.H = cubo.Height;
                st.Sel.Angle = attractView.Angle; st.Sel.CoverA = ca as Bitmap; st.Sel.CoverB = cb as Bitmap; st.Sel.Fade = f;
                return st;   // en atraccion no hay mini-cubo (no suena nada)
            }
            if (searchOpen && searchOverlay != null)
            {
                st = new GpuCubeState();
                Rectangle area; Image ca, cb; float f;
                bool cubOk = searchOverlay.GetPreviewCube(out area, out ca, out cb, out f);
#if ROCOLA_GPU
                if (winMode == 1) cubOk = false;   // abriendo: la ventana se anima entera, un cubo suelto encima la delataria
#endif
                if (cubOk)
                {
                    area.Offset(searchOverlay.Left, searchOverlay.Top);   // coords del buscador -> pantalla
                    st.Sel.Has = true; st.Sel.X = area.X; st.Sel.Y = area.Y; st.Sel.W = area.Width; st.Sel.H = area.Height;
                    st.Sel.Angle = searchOverlay.PreviewAngle; st.Sel.CoverA = ca as Bitmap; st.Sel.CoverB = cb as Bitmap; st.Sel.Fade = f;
                }
            }
            else if (panelSongs != null && panelSongs.Visible && cubeBox != null)
            {
                st = new GpuCubeState();
                if (cubeBox.Cover != null)   // el cubo GRANDE del interior (gira); coords de panelSongs -> pantalla
                {
                    st.Sel.Has = true;
                    FillCubeBoxGeom(ref st.Sel, cubeBox, panelSongs.Left + cubeBox.Left, panelSongs.Top + cubeBox.Top);
                }
            }
            else
            {
                st = albumView.BuildCubeState();
                int ox = albumView.Left, oy = albumView.Top;
                if (st.Sel.Has) { st.Sel.X += ox; st.Sel.Y += oy; }
                if (st.Relay.Has) { st.Relay.X += ox; st.Relay.Y += oy; }
            }
            if (miniCube != null && miniCube.Visible && miniCube.Cover != null)   // mini-cubo (barra inferior): comun
            {
                st.Mini.Has = true;
                FillCubeBoxGeom(ref st.Mini, miniCube, miniCube.Left, miniCube.Top);
            }
            return st;
        }

        // Encuadre + bamboleo de un CubeBox (grande o mini) para que el cubo por GPU COINCIDA con el de CPU:
        // CubeBox.OnPaint dibuja el cubo al 78% del control (centrado) y lo inclina +/-10 grados segun Phase.
        // Sin esto el cubo por GPU salia mas grande (100% del control) y sin el bamboleo (giro plano).
        private static void FillCubeBoxGeom(ref GpuCubeInfo info, CubeBox cb, int screenX, int screenY)
        {
            int side = (int)(Math.Min(cb.Width, cb.Height) * 0.78);
            if (side < 1) side = 1;
            info.X = screenX + (cb.Width - side) / 2;
            info.Y = screenY + (cb.Height - side) / 2;
            info.W = side; info.H = side;
            info.Angle = cb.Angle;
            info.CoverA = cb.Cover as Bitmap;
            info.Tilt = (float)(10.0 * Math.Sin(cb.Phase * 0.9) * Math.PI / 180.0);   // mismo bamboleo que CubeBox.OnPaint
        }

        // Muestra/oculta el panel GPU (a pantalla completa) segun el modo: en NAVEGACION y en el BUSCADOR
        // (ambos se componen por GPU). En disco/video/atraccion/config se oculta y deja ver los controles CPU.
        // El cuadro del video (WMP) es una ventana HIJA hermana del panel GPU: si el panel acaba de
        // mostrarse, su BringToFront lo dejo por delante y taparia el video. Esto lo regresa arriba.
        private void KeepVideoOnTop() { try { if (videoOn && video != null && video.Visible) video.BringToFront(); } catch { } }

        private void SyncGpuFullScreen()
        {
            if (gpuPanel == null || !gpuEnabled) return;
            bool cfgOn = (lblConfig != null && lblConfig.Visible);
            // VIDEO con la interfaz por GPU (video_gpu=1, por defecto): un video en ventana YA NO manda todo
            // a render por CPU. Antes videoOn apagaba nav/disco/atraccion y la pantalla ENTERA (fondo
            // estrellado incluido) se repintaba por CPU mientras WMP decodificaba: en 2 nucleos ese era el
            // "rendimiento raro" con video, y como las animaciones son SOLO por GPU, con video sonando no
            // podian verse nunca (solo la del buscador, el unico modo que ya ignoraba el video). El cuadro
            // del video queda ENCIMA del panel (KeepVideoOnTop) y Windows recorta el panel donde el video
            // esta: no se pisan. Si en algun fierro se viera mal, video_gpu=0 vuelve al comportamiento de
            // antes. El video a PANTALLA COMPLETA si sigue apagando el panel: ahi el es dueno de todo.
            bool videoBlocks = videoOn && !videoGpuOn;
            bool notBlockedByVideoCfg = !videoBlocks && !videoFull && !cfgOn;
            bool noBlock = notBlockedByVideoCfg && !attractOn;
            bool disc = panelSongs != null && panelSongs.Visible;
            bool nav = albumView.Visible && !searchOpen && !disc && noBlock;
            // El VIDEO no bloquea el BUSCADOR: OpenSearch OCULTA el cuadro del video (el audio sigue), asi que
            // el panel GPU puede componer el buscador encima sin taparlo. Antes el video SI lo bloqueaba y el
            // buscador "se abria" INVISIBLE (panel oculto por video + overlay CPU oculto por GPU): el cliente
            // solo veia desaparecer y reaparecer el video. Nav/disco SI siguen bloqueados (ahi el video se VE).
            bool search = searchOpen && !attractOn && !cfgOn && !videoFull;
            // Interior de disco por GPU (por defecto). El bug de la lista era que RenderContent usaba
            // TextRenderer (GDI), que ignora la traslacion del Graphics: sobre la textura de UI (trasladada
            // a la posicion del panel) el texto caia en 0,0. Ya usa DrawString (GDI+), que la respeta.
            // Ctrl+F11 (gpuDiscTry) alterna a CPU como valvula de escape. Navegacion y buscador van por GPU.
            bool discGpu = disc && gpuDiscTry && !searchOpen && noBlock;
            bool attract = attractOn && notBlockedByVideoCfg;   // modo atraccion (reposo): cubo gigante + estrellas por GPU
            // Al CAMBIAR de modo, rehacer la textura de UI en el MISMO cuadro que cambia lo que se dibuja
            // (ShowAlbum, cubos): si no, se ve un instante el modo viejo detras del nuevo (p.ej. la rejilla de
            // discos por los huecos del teclado al cerrar el buscador). UiUrgent salta la limitacion de franja.
            int mode = search ? 2 : discGpu ? 3 : attract ? 4 : nav ? 1 : 0;
            if (mode != gpuMode) { gpuMode = mode; uiOverlaySig = SigNada; gpuPanel.UiUrgent = true; Diag("render: modo GPU " + mode + (videoOn ? " (video sonando)" : "")); }
            // Mientras el video SE VE, el panel baja a ~30 cuadros por segundo: el resto del equipo es para
            // el video (WMP decodifica por CPU en el fierro modesto). Sin video (o con el buscador abierto,
            // que lo oculta) vuelve al maximo.
            // Con el video a la vista, el panel se limita a 30 cuadros por segundo para dejarle equipo al
            // video... pero SOLO donde hace falta. En la maquina de dos nucleos, el decodificador del video y
            // el dibujado se pelean por los mismos nucleos y limitar ayuda de verdad; con cuatro o mas, el
            // video tiene los suyos y limitar el dibujado solo hace que se vea peor sin ganar nada. (Y el
            // limitador ya no se come nueve cuadros por el reloj gordo de Windows: ver Program y OnIdle.)
            gpuPanel.ThrottleMs = (videoOn && video != null && video.Visible && Environment.ProcessorCount < 4) ? 33 : 0;
            albumView.GpuCovered = (nav || search || discGpu || attract);   // panel GPU encima: albumView no repinta por CPU (evita rebuild invisible al paginar)
            if (nav || search || discGpu || attract)
            {
                if (gpuPanel.Left != 0 || gpuPanel.Top != 0 || gpuPanel.Width != ClientSize.Width || gpuPanel.Height != ClientSize.Height)
                    gpuPanel.Bounds = new Rectangle(0, 0, ClientSize.Width, ClientSize.Height);
                gpuPanel.AlbumRect = albumView.Bounds;
                gpuPanel.ShowAlbum = nav;   // solo en navegacion se dibuja la rejilla de cubos (buscador/disco/atraccion la cubren)
                if (!gpuPanel.Visible) { gpuPanel.Visible = true; gpuPanel.BringToFront(); KeepVideoOnTop(); }
            }
            else if (gpuPanel.Visible) { gpuPanel.Visible = false; Invalidate(true); }   // disco(CPU)/video/etc: deja ver los controles normales
        }

        // Donde EMPIEZA la franja de estado de abajo (la que va en su propia textura chica).
        // Reconstruye la textura PRINCIPAL de la UI SOLO si cambio algo (firma). Devuelve la version.
        // La textura mide LO QUE EL MODO NECESITA, no la pantalla completa: en NAVEGACION solo la franja superior
        // (instrucciones + letras + encabezado, ~140px) -> rehacerla y subirla al paginar cuesta ~7x menos que
        // antes. Buscador/disco/atraccion usan hasta la franja de estado (que tiene su propia textura, mas abajo).
        private int EnsureUiOverlay()
        {
            int w = ClientSize.Width, h = ClientSize.Height;
            if (w < 8 || h < 8) return uiOverlayVer;
            int mainH;
            if (searchOpen || (panelSongs != null && panelSongs.Visible) || attractOn) mainH = BotStripTop(h);
            else
            {
                mainH = 60;   // navegacion: hasta el fondo del encabezado/letras/instrucciones
                if (helpBar != null && helpBar.Bottom > mainH) mainH = helpBar.Bottom;
                if (letterBar != null && letterBar.Visible && letterBar.Bottom > mainH) mainH = letterBar.Bottom;
                if (headerView != null && headerView.Bottom > mainH) mainH = headerView.Bottom;
                if (lblStatus != null && lblStatus.Text != null && lblStatus.Text.Length > 0 && lblStatus.Bottom > mainH) mainH = lblStatus.Bottom;
                mainH += 6;
            }
            if (mainH > h) mainH = h; if (mainH < 8) mainH = 8;
            long sig = UiSig();
            if (uiOverlay != null && uiOverlay.Width == w && uiOverlay.Height == mainH && sig == uiOverlaySig) return uiOverlayVer;
            if (uiOverlay == null || uiOverlay.Width != w || uiOverlay.Height != mainH)
            {
                if (uiOverlay != null) uiOverlay.Dispose();
                uiOverlay = new Bitmap(w, mainH, PixelFormat.Format32bppPArgb);
            }
            using (Graphics g = Graphics.FromImage(uiOverlay))
            {
                g.Clear(Color.Transparent);
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;   // gris: ClearType deja flecos sobre transparente
                if (searchOpen && searchOverlay != null)
                {
                    System.Drawing.Drawing2D.GraphicsState gs = g.Save();   // BUSCADOR (su UI sin starfield ni cubo)
                    g.TranslateTransform(searchOverlay.Left, searchOverlay.Top);
                    searchOverlay.RenderContent(g, new Rectangle(0, 0, searchOverlay.Width, searchOverlay.Height), true);
                    g.Restore(gs);
                }
                else if (panelSongs != null && panelSongs.Visible)
                {
                    DrawCtrlOverlay(g, helpBar);   // instrucciones ARRIBA tambien dentro del disco (guian al usuario, como en software)
                    System.Drawing.Drawing2D.GraphicsState gs = g.Save();   // INTERIOR DE DISCO: etiqueta + lista + barra de paginas (el cubo grande lo pone la GPU)
                    g.TranslateTransform(panelSongs.Left, panelSongs.Top);   // los controles del disco son hijos de panelSongs
                    DrawLabelOverlay(g, lblAlbum);
                    DrawCtrlOverlay(g, songList);
                    if (songPager != null && songPager.Visible) DrawCtrlOverlay(g, songPager);
                    g.Restore(gs);
                }
                else if (attractOn)   // MODO ATRACCION: solo los dos textos (el cubo gigante y las estrellas los pone la GPU)
                {
                    RectangleF cuboA = AttractCubeRect();   // mismo rectangulo que el cubo y que la animacion
                    int cubeBottom = (int)(cuboA.Y + cuboA.Height);
                    string line1 = (attractView != null && attractView.SongCount > 0) ? (attractView.SongCount.ToString("#,0") + " canciones") : "Tu rocola";
                    using (Font fBig = new Font(FontFamily.GenericSansSerif, 24f, FontStyle.Bold))
                    using (Font fSmall = new Font(FontFamily.GenericSansSerif, 15f, FontStyle.Bold))
                    using (StringFormat sfc = new StringFormat())
                    using (SolidBrush tb = new SolidBrush(Color.White))
                    {
                        sfc.Alignment = StringAlignment.Center; sfc.LineAlignment = StringAlignment.Center;
                        g.DrawString(line1, fBig, tb, new RectangleF(0, cubeBottom + 18, w, 36), sfc);
                        tb.Color = Color.FromArgb(235, 255, 220, 120);   // FIJO: el "respiro" lo pone un halo por GPU (FillUiGlows) -> esta textura no se rehace nunca en atraccion
                        g.DrawString("toca un boton para elegir", fSmall, tb, new RectangleF(0, cubeBottom + 58, w, 28), sfc);
                    }
                }
                else
                {
                    DrawCtrlOverlay(g, helpBar);
                    DrawCtrlOverlay(g, buscaView);
                    DrawCtrlOverlay(g, letterBar);
                    DrawCtrlOverlay(g, headerView);
                    DrawLabelOverlay(g, lblStatus);
                }
                // Las etiquetas de estado de abajo YA NO van aqui: tienen su propia textura chica
                // (EnsureUiBotOverlay), asi el reloj de la cancion no rehace esta textura 2 veces/seg.
                // El contador de FPS tampoco: lo pinta el GpuPanel en su propia textura pequeña.
            }
            uiOverlaySig = sig; uiOverlayVer++;
            return uiOverlayVer;
        }

        // Reconstruye la textura de la FRANJA DE ESTADO de abajo (sonando/siguiente/tiempo/creditos/cola/
        // progreso) SOLO si cambio algo. Es una tira chica (~90px de alto): el tic del reloj y la barra de
        // progreso (~2 cambios/seg con musica) cuestan ~10x menos que rehacer la pantalla completa de antes.
        private Bitmap uiBotOverlay; private int uiBotVer; private long uiBotLastSig = SigNada;
        private int EnsureUiBotOverlay()
        {
            int w = ClientSize.Width, h = ClientSize.Height;
            if (w < 8 || h < 8) return uiBotVer;
            int top = BotStripTop(h);
            int bh = h - top;
            long sig = UiBotSig();
            if (uiBotOverlay != null && uiBotOverlay.Width == w && uiBotOverlay.Height == bh && sig == uiBotLastSig) return uiBotVer;
            if (uiBotOverlay == null || uiBotOverlay.Width != w || uiBotOverlay.Height != bh)
            {
                if (uiBotOverlay != null) uiBotOverlay.Dispose();
                uiBotOverlay = new Bitmap(w, bh, PixelFormat.Format32bppPArgb);
            }
            using (Graphics g = Graphics.FromImage(uiBotOverlay))
            {
                g.Clear(Color.Transparent);
                if (!attractOn)   // en atraccion la pantalla es limpia: la franja queda transparente
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;   // gris: ClearType deja flecos sobre transparente
                    g.TranslateTransform(0, -top);   // las etiquetas estan en coords del form; la tira empieza en 'top'
                    DrawLabelOverlay(g, lblNowTop);   // 2a linea del titulo (vacia casi siempre: no dibuja nada)
                    DrawLabelOverlay(g, lblNow);
                    if (lblMejorada != null && lblMejorada.Visible) DrawLabelOverlay(g, lblMejorada);   // letrero MEJORADA (su brillo es un halo por quad, no rehace esta textura)
                    if (pastGenero != null && pastGenero.Visible) DrawCtrlOverlay(g, pastGenero);
                    DrawLabelOverlay(g, lblNext);
                    DrawLabelOverlay(g, lblTime);
                    DrawCtrlOverlay(g, pastCred);
                    DrawCtrlOverlay(g, pastCola);
                    DrawCtrlOverlay(g, progress);
                }
            }
            uiBotLastSig = sig; uiBotVer++;
            return uiBotVer;
        }

        // ---------- LAS PIEZAS VIVAS DEL BUSCADOR ----------
        //
        // La tecla elegida, en SU PROPIA imagen chica y con su sitio. Antes iba horneada dentro de la imagen
        // de pantalla completa, asi que mover el recuadro obligaba a rehacerla y re-subirla entera: 7 MB por
        // pulsacion a 1080p (ver UiSig). Ahora es lo mismo que ya se hacia con la franja de estado de abajo:
        // una imagen chica aparte, que se rehace solo cuando cambia de verdad. Una tecla son unos 38 KB.
        //
        // SOLO LA TECLA, y no la tarjeta de los resultados. Al principio eran las dos y estaba mal: moverse
        // por los resultados cambia ademas el cubo de la portada y el texto de debajo, que si van dentro de
        // la imagen grande. Sacarlo de la firma dejaba el cubo y el texto viejos, y el teclado sin volver.
        internal const int NumPiezas = 2;
        private readonly Bitmap[] uiPieza = new Bitmap[NumPiezas];
        private readonly Rectangle[] uiPiezaRect = new Rectangle[NumPiezas];
        private readonly long[] uiPiezaSig = new long[NumPiezas];
        private readonly int[] uiPiezaVer = new int[NumPiezas];

        private void SueltaPiezas()
        {
            for (int i = 0; i < NumPiezas; i++)
            {
                if (uiPieza[i] != null) { uiPieza[i].Dispose(); uiPieza[i] = null; }
                uiPiezaRect[i] = Rectangle.Empty; uiPiezaSig[i] = SigNada; uiPiezaVer[i]++;
            }
        }

        // Prepara la pieza 'cual' y devuelve su version (sube cuando la imagen cambia). Con el buscador
        // cerrado no hay piezas: se sueltan y se contesta que no hay nada que dibujar.
        private int EnsureUiPieza(int cual)
        {
            if (cual < 0 || cual >= NumPiezas) return 0;
            if (!searchOpen || searchOverlay == null)
            {
                if (uiPieza[cual] != null) { uiPieza[cual].Dispose(); uiPieza[cual] = null; uiPiezaRect[cual] = Rectangle.Empty; uiPiezaVer[cual]++; uiPiezaSig[cual] = SigNada; }
                return uiPiezaVer[cual];
            }
            Rectangle donde;
            if (!searchOverlay.PiezaViva(cual, out donde) || donde.Width < 1 || donde.Height < 1)
            {
                if (uiPieza[cual] != null) { uiPieza[cual].Dispose(); uiPieza[cual] = null; uiPiezaRect[cual] = Rectangle.Empty; uiPiezaVer[cual]++; uiPiezaSig[cual] = SigNada; }
                return uiPiezaVer[cual];
            }
            long sig = SigBase;
            sig = Mix(sig, cual); sig = Mix(sig, donde.X); sig = Mix(sig, donde.Y);
            sig = Mix(sig, donde.Width); sig = Mix(sig, donde.Height);
            sig = Mix(sig, searchOverlay.SelResult); sig = Mix(sig, searchOverlay.SelRow);
            sig = Mix(sig, searchOverlay.SelCol); sig = Mix(sig, searchOverlay.FocusResults);
            Color acPieza = searchOverlay.Accent;   // a una local: es un tipo por valor dentro de un Control
            sig = Mix(sig, searchOverlay.Query); sig = Mix(sig, acPieza.ToArgb());
            sig = Mix(sig, searchOverlay.DatosVer);
            // Solo la caja de lo escrito mira LO TECLEADO. Metiendolo en la firma de todas, la tecla
            // elegida se reharia en cada letra sin que hubiera cambiado nada de ella.
            if (cual == SearchOverlay.PiezaEscrito) sig = Mix(sig, searchOverlay.Escrito);
            if (sig == SigNada) sig = 1L;

            // El sitio se guarda SIEMPRE (aunque la imagen no cambie): al desplazarse la lista, la misma
            // tarjeta puede tener que dibujarse unos pixeles mas alla.
            Rectangle enPantalla = donde;
            enPantalla.Offset(searchOverlay.Left, searchOverlay.Top);
            uiPiezaRect[cual] = enPantalla;
            if (uiPieza[cual] != null && uiPieza[cual].Width == donde.Width && uiPieza[cual].Height == donde.Height && sig == uiPiezaSig[cual])
                return uiPiezaVer[cual];
            if (uiPieza[cual] == null || uiPieza[cual].Width != donde.Width || uiPieza[cual].Height != donde.Height)
            {
                if (uiPieza[cual] != null) uiPieza[cual].Dispose();
                uiPieza[cual] = new Bitmap(donde.Width, donde.Height, PixelFormat.Format32bppPArgb);
            }
            using (Graphics g = Graphics.FromImage(uiPieza[cual]))
            {
                g.Clear(Color.Transparent);
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;   // igual que la imagen grande
                // SE LE PASA EL DESPLAZAMIENTO; NO SE MUEVE EL LIENZO. La primera version movia el lienzo
                // (TranslateTransform) y en Mono se veia perfecto... pero en Windows el texto de la tecla lo
                // dibuja el SISTEMA (TextRenderer), y ese trabaja en pixeles de verdad: no hace caso a las
                // trasformaciones. La letra se iba fuera de la imagen chica y en el bar la tecla elegida
                // salia como un rectangulo rosa VACIO. Con el desplazamiento por delante cae donde debe en
                // los dos sitios.
                searchOverlay.DibujaPiezaViva(g, cual, -donde.X, -donde.Y);
            }
            uiPiezaSig[cual] = sig; uiPiezaVer[cual]++;
            return uiPiezaVer[cual];
        }

        // Llena el buffer con los HALOS ANIMADOS de la UI, en coords de pantalla. La GPU los dibuja como quads
        // aditivos: TODA animacion continua (destello del boton pulsado, pulso de la letra actual, dorado del TOP,
        // respiro del texto de atraccion) vive AQUI y no en la textura de UI -> la textura solo se rehace cuando
        // cambia un TEXTO real. Antes estos pulsos re-horneaban y RE-SUBIAN la pantalla completa hasta ~13+10
        // veces/seg: ese era el stuttering de la rocola. Devuelve cuantos escribio.
        private int FillUiGlows(GpuPanel.UiGlow[] buf)
        {
            if (buf == null) return 0;
            int n = 0;
            if (searchOpen && searchOverlay != null)
            {
                int sx = searchOverlay.Left, sy = searchOverlay.Top;
                for (int k = 0; k < 3 && n < buf.Length; k++)
                {
                    float cx, cy, r; int argb;
                    if (searchOverlay.GetHintGlow(k, out cx, out cy, out r, out argb))
                    { buf[n].Cx = sx + cx; buf[n].Cy = sy + cy; buf[n].R = r; buf[n].Argb = (uint)argb; n++; }
                }
            }
            else if (attractOn)
            {
                // Respiro DORADO detras de "toca un boton para elegir" (el texto va fijo en la textura).
                int w = ClientSize.Width, h = ClientSize.Height;
                int side = (int)(Math.Min(w, h) * 0.40); if (side < 80) side = 80;
                int cubeBottom = (h - side) / 2 - 30 + side;
                double p = 0.5 + 0.5 * Math.Sin(phase * 3.0);
                buf[n].Cx = w / 2f; buf[n].Cy = cubeBottom + 72; buf[n].R = 150f;
                buf[n].Argb = (uint)Color.FromArgb((int)(16 + 38 * p), 255, 220, 120).ToArgb(); n++;
            }
            else
            {
                if (helpBar != null && helpBar.Visible)   // destello del boton pulsado (navegacion e interior de disco)
                {
                    int hx = helpBar.Left, hy = helpBar.Top;
                    for (int k = 0; k < 4 && n < buf.Length; k++)
                    {
                        float cx, cy, r; int argb;
                        if (helpBar.GetFlashGlow(k, out cx, out cy, out r, out argb))
                        { buf[n].Cx = hx + cx; buf[n].Cy = hy + cy; buf[n].R = r; buf[n].Argb = (uint)argb; n++; }
                    }
                }
                if (buscaView != null && buscaView.Visible && n < buf.Length)
                {
                    float bcx, bcy, br;
                    if (buscaView.GetLatido(out bcx, out bcy, out br))
                    {
                        double p = 0.5 + 0.5 * Math.Sin(phase * 2.4);   // el mismo ritmo que por CPU
                        buf[n].Cx = buscaView.Left + bcx; buf[n].Cy = buscaView.Top + bcy; buf[n].R = br;
                        buf[n].Argb = (uint)Color.FromArgb((int)(30 + 70 * p), 90, 190, 255).ToArgb(); n++;
                    }
                }
                if (letterBar != null && letterBar.Visible)
                {
                    float cx, cy, r;
                    if (n < buf.Length && letterBar.GetCurrentGlow(out cx, out cy, out r))   // pulso de la letra actual
                    {
                        double p = 0.5 + 0.5 * Math.Sin(phase * 2.2);   // mismo ritmo que antes, pero ahora a cuadro pleno y GRATIS
                        buf[n].Cx = letterBar.Left + cx; buf[n].Cy = letterBar.Top + cy; buf[n].R = r;
                        buf[n].Argb = (uint)Color.FromArgb((int)(45 + 65 * p), 110, 180, 255).ToArgb(); n++;
                    }
                    if (n < buf.Length && letterBar.GetTopGlow(out cx, out cy, out r))       // dorado pulsante del marcador TOP
                    {
                        double p = 0.5 + 0.5 * Math.Sin(phase * 2.6);
                        buf[n].Cx = letterBar.Left + cx; buf[n].Cy = letterBar.Top + cy; buf[n].R = r;
                        buf[n].Argb = (uint)Color.FromArgb((int)(22 + 50 * p), 255, 205, 90).ToArgb(); n++;
                    }
                }
            }
            // Letrero "MEJORADA" (franja de estado, visible en todos los modos menos atraccion): un resplandor
            // suave que RESPIRA + un destello que RECORRE las letras cada ~4s (reflejo metalico, plateado o
            // dorado). El texto va FIJO en la textura de la franja: estos halos no rehacen NINGUNA textura.
            if (!attractOn && lblMejorada != null && lblMejorada.Visible && n + 1 < buf.Length)
            {
                bool gold = (iaBadgeKind == 2);
                float cy2 = lblMejorada.Top + lblMejorada.Height / 2f;
                double pb = 0.5 + 0.5 * Math.Sin(phase * 2.8);
                buf[n].Cx = lblMejorada.Left + lblMejorada.Width / 2f; buf[n].Cy = cy2;
                buf[n].R = lblMejorada.Width * 0.72f;
                buf[n].Argb = (uint)(gold ? Color.FromArgb((int)(9 + 15 * pb), 255, 210, 100)
                                          : Color.FromArgb((int)(8 + 13 * pb), 205, 225, 255)).ToArgb(); n++;
                double sw = (phase * 0.22) % 1.0;   // ciclo ~4s: 55% barrido de izq a der, 45% descanso
                if (sw < 0.55)
                {
                    double t = sw / 0.55;
                    int a = (int)(95 * Math.Sin(Math.PI * t));   // entra y sale suave
                    buf[n].Cx = lblMejorada.Left + (float)(t * lblMejorada.Width); buf[n].Cy = cy2; buf[n].R = 26f;
                    buf[n].Argb = (uint)(gold ? Color.FromArgb(a, 255, 232, 150) : Color.FromArgb(a, 240, 248, 255)).ToArgb(); n++;
                }
            }
            return n;
        }

        // FIRMA de lo que hay que dibujar. Se compara CADA CUADRO para saber si hay que rehacer la textura,
        // asi que no puede armar una cadena: eso eran dos StringBuilder y dos cadenas nuevas por cuadro (~70 KB
        // por segundo de basura para el recolector, que es justo lo que provoca microtirones). Ahora se mezcla
        // todo en un numero de 64 bits (FNV-1a), sin reservar ni un byte. Dos estados distintos podrian caer en
        // el mismo numero, pero con 64 bits eso es 1 entre 18 trillones: y ni asi se rompe nada, solo tardaria
        // un cambio de texto en verse hasta el siguiente cambio.
        private const long SigNada = 0L;                     // valor imposible de la mezcla: fuerza rehacer
        private const long SigBase = unchecked((long)1469598103934665603L);
        private static long Mix(long h, int v) { unchecked { h ^= (uint)v; h *= 1099511628211L; } return h; }
        private static long Mix(long h, long v) { return Mix(Mix(h, (int)v), (int)(v >> 32)); }
        private static long Mix(long h, bool b) { return Mix(h, b ? 1 : 0); }
        private static long Mix(long h, string t) { return Mix(h, t == null ? 0 : t.GetHashCode()); }
        private long UiSig()
        {
            long sb = SigBase;
            sb = Mix(sb, ClientSize.Width); sb = Mix(sb, ClientSize.Height);
            if (searchOpen && searchOverlay != null)   // parte superior = buscador
            {
                sb = Mix(sb, 'S'); sb = Mix(sb, searchOverlay.Query);
                sb = Mix(sb, searchOverlay.Results == null ? 0 : searchOverlay.Results.Count);
                sb = Mix(sb, searchOverlay.ToastOn); sb = Mix(sb, searchOverlay.ToastMsg);
                // LA TECLA ELEGIDA YA NO ENTRA AQUI. Entraba, y eso significaba que pulsar una flecha -que
                // solo cambia QUE tecla lleva el recuadro- obligaba a rehacer y RE-SUBIR la pantalla completa:
                // 5.91 ms por pulsacion a 1080p, el 35% de un cuadro. Ahora la tecla elegida sale como PIEZA
                // VIVA aparte, en su propia imagen chica (ver SearchOverlay.PiezaViva y EnsureUiPieza),
                // exactamente igual que ya se hacia con el destello de los botones y la franja de abajo.
                //
                // PERO ESTAS DOS SI TIENEN QUE ESTAR, y sacarlas fue un error que se vio en el bar:
                //   FocusResults cambia MEDIA PANTALLA -donde estaba el teclado se pone el cubo de la
                //     portada-. Sin el, al volver de los resultados al teclado la imagen no se rehacia y EL
                //     TECLADO NO VOLVIA A APARECER hasta cerrar y abrir el buscador.
                //   SelResult, con el cubo delante, cambia que disco se ensena y el texto de debajo.
                // Moverse por los RESULTADOS, por tanto, sigue rehaciendo la pantalla; moverse por las TECLAS
                // -que es lo que se hace al teclear- ya no.
                sb = Mix(sb, searchOverlay.FocusResults); sb = Mix(sb, searchOverlay.SelResult);
            }
                  // El DESTELLO del boton pulsado YA NO entra en la firma: lo dibuja la GPU como halo aparte (FillUiGlows),
                  // asi que su desvanecido no re-hornea ni re-sube la textura del teclado -> tecleo fluido con brillo suave.
                  // Tampoco la fase del teclado (carisima). En reposo la firma es constante -> 0 reconstrucciones.
            else if (panelSongs != null && panelSongs.Visible)   // INTERIOR DE DISCO: etiqueta, seleccion, pagina
                // La GEOMETRIA entra en la firma: al arrancar o terminar un video, LayoutControls REACOMODA el
                // interior (con video, la lista y el cubo se comprimen a la mitad izquierda). Sin la geometria,
                // la firma no cambiaba y la textura quedaba horneada con las posiciones VIEJAS -la lista flotando
                // donde ya no va- hasta salir y volver a entrar al disco. El cubo no lo sufria (es en vivo).
            {
                sb = Mix(sb, 'D'); sb = Mix(sb, lblAlbum != null ? lblAlbum.Text : ""); sb = Mix(sb, songSel); sb = Mix(sb, songItems.Count);
                sb = Mix(sb, songList != null ? songList.PageStart : 0); sb = Mix(sb, bgAccent.ToArgb());
                sb = Mix(sb, colaVer);   // sin esto, la marca "EN COLA" no saldria hasta que algo mas cambiara
                sb = Mix(sb, generoVer);   // idem para las pastillas de genero, que se aprenden en segundo plano
                sb = Mix(sb, panelSongs.Left); sb = Mix(sb, panelSongs.Top); sb = Mix(sb, panelSongs.Width); sb = Mix(sb, panelSongs.Height);
                // Mientras la pagina se desliza, la firma tiene que cambiar en cada cuadro o la textura no se
                // rehace y la animacion no se veria mover (igual que la capsula de la barra de letras).
                if (songList != null && songList.Sliding) sb = Mix(sb, (int)(songList.SlidePaso * 128f));
                if (songPager != null && songPager.Animando) sb = Mix(sb, (int)(songPager.Paso * 128f));
            }
            else if (attractOn)                        // MODO ATRACCION: solo la cantidad de canciones (el pulso del texto va como halo por quad)
            { sb = Mix(sb, 'A'); sb = Mix(sb, attractView != null ? attractView.SongCount : 0); }
            else if (letterBar != null)                // parte superior = navegacion (A-Z + encabezado)
            {
                sb = Mix(sb, 'N'); sb = Mix(sb, letterBar.Current); sb = Mix(sb, letterBar.Letters);
                sb = Mix(sb, letterBar.Available == null ? 0 : letterBar.Available.Count);
                // Los NUMEROS y los COLORES de las letras los va aprendiendo el paseo de fondo, y el
                // DESLIZAMIENTO al cambiar de letra se mueve solo. Sin esto, en modo GPU la textura no se
                // rehacia: los numeros no aparecian hasta cambiar de letra y el deslizamiento no se veia.
                sb = Mix(sb, letterBar.DatosSig());
                // La casilla de BUSCAR entra por si esta abierta o cerrada, NO por su parpadeo: el parpadeo
                // lo pone la tarjeta como halo aparte, y meterlo aqui obligaria a rehacer la textura entera
                // veinticuatro veces por segundo.
                if (buscaView != null) { sb = Mix(sb, buscaView.Visible); sb = Mix(sb, buscaView.Abierto); }
                if (letterBar.AnimViva) sb = Mix(sb, (int)(letterBar.AnimPaso * 64f));
                if (headerView != null)
                {
                    Color acCab = headerView.Accent;   // a una local: es un tipo por valor dentro de un Control
                    sb = Mix(sb, headerView.Section); sb = Mix(sb, headerView.Page);
                    sb = Mix(sb, headerView.Total); sb = Mix(sb, acCab.ToArgb());
                }
                sb = Mix(sb, lblStatus != null ? lblStatus.Text : "");
            }
            // NI la fase del pulso de la letra NI el destello del boton pulsado (FlashSig) entran ya en la firma:
            // ambos los dibuja la GPU como halos aparte (FillUiGlows). Antes obligaban a rehacer Y RE-SUBIR esta
            // textura ~13 veces/seg en navegacion (pulso) y ~10 veces por CADA tecla (destello): ESE era el
            // stuttering de la rocola al paginar. Ahora, quieto en una pagina, la firma es constante -> 0 rehechas.
            // Las etiquetas de estado de abajo (sonando/tiempo/creditos/progreso) van en SU PROPIA textura chica
            // (UiBotSig/EnsureUiBotOverlay): el reloj de la cancion ya no rehace la pantalla completa 2 veces/seg.
            // El FPS tambien va en su propia textura (1/seg, diminuta).
            return (sb == SigNada) ? 1L : sb;   // que nunca coincida con "sin firma"
        }

        // Firma de la FRANJA DE ESTADO de abajo (sonando/siguiente/tiempo/creditos/cola/progreso): cambia ~2
        // veces/seg con musica sonando, pero su textura es una tira chica (~400KB vs ~4MB de pantalla completa).
        private long UiBotSig()
        {
            long sb = SigBase;
            sb = Mix(sb, ClientSize.Width); sb = Mix(sb, ClientSize.Height);
            if (attractOn) return Mix(sb, 'A');   // en atraccion la franja va limpia (transparente)
            if (lblNowTop != null) sb = Mix(sb, lblNowTop.Text);
            if (lblNow != null) sb = Mix(sb, lblNow.Text);
            if (lblMejorada != null && lblMejorada.Visible) { sb = Mix(sb, 'M'); sb = Mix(sb, iaBadgeKind); sb = Mix(sb, lblMejorada.Left); sb = Mix(sb, lblMejorada.ForeColor.ToArgb()); }
            if (pastGenero != null && pastGenero.Visible) { Color tg = pastGenero.Tinte; sb = Mix(sb, pastGenero.Texto); sb = Mix(sb, tg.ToArgb()); sb = Mix(sb, pastGenero.Left); }
            if (lblNext != null) sb = Mix(sb, lblNext.Text);
            if (lblTime != null) sb = Mix(sb, lblTime.Text);
            if (pastCred != null) { Color ac = pastCred.Acento; sb = Mix(sb, pastCred.Etiqueta); sb = Mix(sb, pastCred.Valor); sb = Mix(sb, ac.ToArgb()); sb = Mix(sb, pastCred.Left); sb = Mix(sb, pastCred.Paso); }
            if (pastCola != null)
            {
                sb = Mix(sb, pastCola.Valor); sb = Mix(sb, pastCola.Left); sb = Mix(sb, pastCola.Mas);
                // Y CUALES son. Sin esto, con tarjeta grafica una portadita que llega tarde -se decodifica
                // en otro hilo- no se veria aparecer: la firma no cambiaria y la textura no se reharia.
                if (pastCola.Portadas != null)
                    for (int i = 0; i < pastCola.Portadas.Length; i++)
                        sb = Mix(sb, (pastCola.Portadas[i] != null) ? 1 : 0);
            }
            if (progress != null) { sb = Mix(sb, (int)(progress.Value * 300)); sb = Mix(sb, progress.Accent.ToArgb()); }
            return (sb == SigNada) ? 1L : sb;   // que nunca coincida con "sin firma"
        }

        // Dibuja un control (HelpBar/LetterBar/ProgressView) en la textura de UI, en su posicion del form.
        private static void DrawCtrlOverlay(Graphics g, Control c)
        {
            if (c == null || c.Width < 1 || c.Height < 1) return;
            System.Drawing.Drawing2D.GraphicsState st = g.Save();
            g.TranslateTransform(c.Left, c.Top);
            HelpBar hb = c as HelpBar;
            if (hb != null) hb.RenderContent(g, true);   // forGpu: sus pulsos van como halos por quad, no en la textura
            else { HeaderView hv = c as HeaderView; if (hv != null) hv.RenderContent(g);
            else { LetterBar lb = c as LetterBar; if (lb != null) lb.RenderContent(g, true);
            else { PastillaView pa = c as PastillaView; if (pa != null) pa.RenderContent(g);
            else { ProgressView pv = c as ProgressView; if (pv != null) pv.RenderContent(g);
            else { GeneroView gv = c as GeneroView; if (gv != null) gv.RenderContent(g);
            else { SongListView sl = c as SongListView; if (sl != null) sl.RenderContent(g);
            else { SongPagerBar sp = c as SongPagerBar; if (sp != null) sp.RenderContent(g);
            else { BuscaView bv = c as BuscaView; if (bv != null) bv.RenderContent(g, true); } } } } } } } }
            g.Restore(st);
        }

        // Dibuja el texto de una etiqueta en la textura de UI, respetando su fuente, color, alineacion y caja.
        // GDI reusables (StringFormat + pincel al que se muta el color): esto se llama ~6-7 veces por cada
        // reconstruccion de la textura de UI (que ocurre ~13fps en navegacion por el brillo de la letra).
        [ThreadStatic] private static StringFormat lblSf;
        [ThreadStatic] private static SolidBrush lblBr;
        private static void DrawLabelOverlay(Graphics g, Label l) { DrawLabelOverlay(g, l, (l != null) ? l.ForeColor : Color.White); }
        private static void DrawLabelOverlay(Graphics g, Label l, Color color)
        {
            if (l == null || string.IsNullOrEmpty(l.Text)) return;
            StringFormat sf = lblSf ?? (lblSf = new StringFormat());
            SolidBrush b = lblBr ?? (lblBr = new SolidBrush(Color.White)); b.Color = color;
            sf.FormatFlags = StringFormatFlags.NoWrap; sf.Trimming = StringTrimming.EllipsisCharacter;
            ContentAlignment a = l.TextAlign;
            if ((a & (ContentAlignment.TopLeft | ContentAlignment.MiddleLeft | ContentAlignment.BottomLeft)) != 0) sf.Alignment = StringAlignment.Near;
            else if ((a & (ContentAlignment.TopRight | ContentAlignment.MiddleRight | ContentAlignment.BottomRight)) != 0) sf.Alignment = StringAlignment.Far;
            else sf.Alignment = StringAlignment.Center;
            if ((a & (ContentAlignment.TopLeft | ContentAlignment.TopCenter | ContentAlignment.TopRight)) != 0) sf.LineAlignment = StringAlignment.Near;
            else if ((a & (ContentAlignment.BottomLeft | ContentAlignment.BottomCenter | ContentAlignment.BottomRight)) != 0) sf.LineAlignment = StringAlignment.Far;
            else sf.LineAlignment = StringAlignment.Center;
            g.DrawString(l.Text, l.Font, b, (RectangleF)l.Bounds, sf);
        }

#endif

        // ---------- PRECALENTADO: QUE LA PRIMERA VEZ VAYA COMO LAS DEMAS ----------
        //
        // Casi todo lo que la rocola dibuja se HORNEA la primera vez que hace falta -el teclado del buscador
        // son 40 teclas con su degradado, su contorno y su letra; la lista de un disco se guarda hecha para
        // poder deslizarla- y eso cae DENTRO del primer cuadro: el cliente pulsa, la rocola se para a hornear
        // y el movimiento arranca a tirones. De la segunda vez en adelante va fino.
        //
        // Medido con pruebas/primera.cs en el servidor (en la rocola del bar hay que multiplicar por 4 o 5):
        //
        //     el buscador al abrirse .... 20.8 ms la 1a vez contra 1.9 ms despues
        //     la lista de un disco ......  3.6 ms  ...  contra 0.2 ms
        //     el encabezado y la pastilla de creditos: 0.02 y 0.06 ms de mas. NO se precalientan, no ganan nada.
        //
        // AQUI SOLO VAN LAS PANTALLAS QUE AL ENCENDER NO SE VEN. La pared de discos y la barra de letras
        // tambien cuestan su primera vez, pero es que ELLAS SON la pantalla de arranque: ese cuadro se paga
        // igual, adelantarlo no adelanta nada. El buscador, la lista de un disco y la pantalla de reposo
        // aparecen despues, y ahi si se gana entero.
        //
        // Y se calienta DIBUJANDO de verdad, una vez, en un mapa de bits de usar y tirar. Se podria llamar a
        // mano a cada Ensure*/Hornea*, pero esa lista se queda vieja en cuanto alguien anada un dibujo nuevo;
        // dibujando se pasa por el MISMO camino que el dibujo de verdad y se calienta lo que ese camino
        // calienta, hoy y dentro de un ano.
        private int precalPaso = 0;             // que pieza toca (-1 = ya esta todo caliente)
        private int precalReintentos = 0;       // si una pieza aun no tiene tamano, se reintenta un rato
        private const int PrecalQuieta = 400;   // ms sin tocar nada para ponerse a calentar

        // UNA pieza por latido, y solo con la rocola quieta: igual que el horneado de la pagina de al lado
        // (BakeAhead) y que el precalentador de portadas. Asi la rocola enciende igual de rapido que siempre
        // y en unos segundos esta todo caliente, sin quitarle la maquina a nadie.
        private void PrecalientaUnPoco()
        {
            if (precalPaso < 0) return;
            if (Environment.TickCount - lastInputTick < PrecalQuieta) return;   // hay alguien usandola: ahora no
            bool hecho = false;
            try
            {
                switch (precalPaso)
                {
                    case 0:
                        hecho = EnSeco(searchOverlay, delegate (Graphics g)
                        { searchOverlay.RenderContent(g, new Rectangle(0, 0, searchOverlay.Width, searchOverlay.Height), false); });
                        break;
                    case 1:
                        hecho = EnSeco(songList, delegate (Graphics g) { songList.RenderContent(g); });
                        break;
                    case 2:
                        // La pantalla de reposo no tiene RenderContent aparte: se le pide su propio dibujado,
                        // que es lo mismo que hace la pantalla cuando le toca pintarse.
                        hecho = EnSeco(attractView, delegate (Graphics g)
                        {
                            using (PaintEventArgs pe = new PaintEventArgs(g, new Rectangle(0, 0, attractView.Width, attractView.Height)))
                                InvokePaint(attractView, pe);
                        });
                        break;
                    default:
                        precalPaso = -1; Diag("precalentado: las pantallas que no se ven al encender, ya horneadas");
                        return;
                }
            }
            catch { hecho = true; }   // precalentar es un lujo: si una pieza no se deja dibujar aun, se pasa a la siguiente
            if (hecho || ++precalReintentos > 60) { precalPaso++; precalReintentos = 0; }
        }

        // Dibuja un control una vez en un mapa de bits de usar y tirar. Nada de esto se ve: lo unico que hace
        // es que lo que ese dibujo hornea quede hecho. false = todavia no tiene tamano, se reintenta luego.
        private bool EnSeco(Control c, Action<Graphics> dibuja)
        {
            if (c == null || c.Width < 8 || c.Height < 8) return false;
            using (Bitmap b = new Bitmap(c.Width, c.Height, PixelFormat.Format32bppPArgb))
            using (Graphics g = Graphics.FromImage(b))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
                dibuja(g);
            }
            return true;
        }

        // Al cambiar la RESOLUCION lo horneado deja de servir -esta hecho al tamano de antes- y hay que
        // volver a calentar; si no, la primera vez despues del cambio vuelve a trabarse.
        //
        // Con el color de acento NO se hace, a proposito: el acento cambia con cada cancion (es el color del
        // genero), asi que volver a calentar en cada cambio seria estar horneando toda la noche para ahorrar
        // una vez. Ahi se deja que se rehornee solo cuando de verdad se dibuje.
        private void VuelveAPrecalentar() { precalPaso = 0; precalReintentos = 0; }

        private void AnimTimer_Tick(object sender, EventArgs e)
        {
            phase += 0.045;
            frameTick++;
            // OPTIMIZACION CLAVE: los brillos del fondo se mueven MENOS DE MEDIO PIXEL por cuadro, asi
            // que repintar TODA la pantalla 25 veces/seg por ellos es desperdicio. El fondo completo se
            // repinta 1 de cada 3 cuadros (~8/seg, indistinguible en blobs borrosos); el cubo que gira
            // se repinta SOLO en su casilla a velocidad plena. Esto recorta ~3x el costo fijo de CPU.
            bool fullFrame = (frameTick % 3) == 0;   // fondo completo 1 de cada 3 (~8fps): el fondo es estatico, repintarlo mas seguido solo gasta CPU (clave en el CPU lento de la rocola)

#if ROCOLA_GPU
            // FIN de las animaciones. El AVANCE no se calcula aqui: lo calcula el render (60 fps), asi que el
            // zoom es fluido aunque este temporizador vaya a 24. Aqui solo se apagan al cumplirse su tiempo.
            if (transMode != 0 && Environment.TickCount - transTick >= TransMs) AbortDiscTrans();
            if (winMode != 0 && Environment.TickCount - winTick >= WinMs) AbortWinTrans();
#endif
            DrainCoverTrash();   // libera carátulas expulsadas (seguro: no hay repintado en curso)
#if ROCOLA_GPU
            // Con la rocola quieta, se van horneando las casillas de la pagina de al lado: cuando alguien pase
            // de pagina, ya estan listas y el deslizamiento sale fluido de una. Dos casillas por vuelta y con
            // tope de 4 ms: si alguien esta usando la rocola en ese momento, no le quita nada.
            if (gpuEnabled && albumView != null && albumView.Visible && !attractOn && !searchOpen && !videoOn
                && transMode == 0 && winMode == 0 && !albumView.Sliding) albumView.BakeAhead();
#endif
            PrecalientaUnPoco();   // y las pantallas que al encender no se ven, horneadas antes de que hagan falta
            CheckBusinessDayReset();   // al cruzar las 7 AM: reinicia el estado (nada de anoche cruza el corte del dia)
            AvanzaModoNoche();         // y de 11pm a 7am, el volumen baja 4 dB (bajando poco a poco, sin escalon)
            // VIGIA DEL MOTOR DE IA: si DSEE ULTRA esta activo y el motor no responde (recien arrancado, o se
            // cayo), lo (re)lanza OCULTO. Cada ~10s. Asi el motor va integrado con el release: nunca hay que
            // abrir un .bat a mano, y si el motor muere se revive solo.
            if (iaVivo && Environment.TickCount - iaMotorCheckTick > 10000) { iaMotorCheckTick = Environment.TickCount; if (!IaMotorAlive()) IaEnsureMotor(); }

            // BEAT: toma el RMS cuyo momento de OIRSE ya llego (medido ~0.85s antes, al llenar el colchon) y
            // detecta GOLPES contra un piso movil: el pulso visual cae encima del golpe que se esta oyendo,
            // con ataque INSTANTANEO y caida rapida (pulso marcado), mas un fondo suave para que no muera
            // entre golpes. Antes era una envolvente de sonoridad adelantada ~1s: no transmitia el ritmo.
            int nowT = Environment.TickCount;
            lock (levelLock)
                while (levelQ.Count > 0 && nowT - (levelQ.Peek().At + audioVisualDelayMs) >= 0)
                { Lvl l = levelQ.Dequeue(); rmsLo = l.Lo; rmsMid = l.Mid; rmsHi = l.Hi; if (l.Esp != null) Array.Copy(l.Esp, specNow, SpecBands); }
            if (nowPlaying == null) { rmsLo = rmsMid = rmsHi = 0f; for (int b = 0; b < SpecBands; b++) specNow[b] = 0f; }
#if ROCOLA_GPU
            // Con un VIDEO en pantalla el audio sale del reproductor de Windows y NO pasa por la cadena, asi que no
            // llegan bandas nuevas: sin esto el fondo se quedaria CONGELADO con la forma de la ultima cancion durante
            // todo el video. (El pulso no lo sufre: su detector de golpes se apaga solo contra su piso movil.)
            if (videoOn || !EspectroActivo) for (int b = 0; b < SpecBands; b++) specNow[b] = 0f;
            AvanzaAurora();   // el fondo lo dibuja el panel GPU; por CPU ni se calcula
#endif
            // Cada banda detecta su propio golpe contra su propio piso movil (ataque instantaneo, caida rapida). Asi
            // el bombo (graves) y los platillos/voz (agudos) laten por separado y se SIENTE la separacion de beats.
            levLo = BandBeat(rmsLo, ref avgLo, levLo);
            levMid = BandBeat(rmsMid, ref avgMid, levMid);
            levHi = BandBeat(rmsHi, ref avgHi, levHi);
            // LA DERIVA DEL CAMPO DE ESTRELLAS, UNA VEZ POR LATIDO Y CON EL RELOJ EN LA MANO. Va aqui y no en
            // el dibujado porque el dibujado no ocurre a un ritmo parejo -depende de lo que toque rehacer en
            // cada momento- y el fondo tiene que deslizarse liso, no a tirones. El campo es UNO solo y lo
            // comparten el fondo, la pared de discos, el interior y el buscador: una sola cuenta los mueve a
            // todos a la vez y sin costuras.
            formStars.AvanzaDeriva(Math.Max(levLo, Math.Max(levMid, levHi)));
#if ROCOLA_GPU
            audioLevel = Math.Max(levLo, Math.Max(levMid, levHi));   // nivel GLOBAL para la tarjeta grafica: el mas fuerte de las 3
#endif

            // ATENUACION del starfield mientras se navega con musica sonando (ver BgDimLevel); transicion suave.
            float dimTgt = (nowPlaying != null && !attractOn && (DateTime.Now - lastInput).TotalSeconds < BgDimIdleSecs) ? BgDimLevel : 1f;
            bgDim += (dimTgt - bgDim) * 0.12f;
            if (Math.Abs(bgDim - dimTgt) < 0.01f) bgDim = dimTgt;
            // LA RESPIRACION va APARTE de bgDim y no dentro, a proposito: bgDim es de quien sale la cuenta
            // de 'quieto' que calma la aurora, y metiendosela dentro se armaria una pescadilla que se muerde
            // la cola. Aqui se multiplican al final, para pintar.
            quietud = PasoQuietud(quietud, (DateTime.Now - lastInput).TotalSeconds < BgDimIdleSecs);
            respiraFase += RespiraPaso;
            if (respiraFase > 6.2831853f) respiraFase -= 6.2831853f;
            // DOS COSAS DISTINTAS, y hay que tenerlas separadas.
            //
            // 'bgDimResp' es la atenuacion al navegar CON la respiracion encima, y va a las estrellas y a
            // los destellos. 'bgRespiro' es SOLO la respiracion, y es la que va a los colores del CIELO.
            //
            // Mezclarlas seria un fallo gordo: la atenuacion al navegar baja al 45%, y aplicada al cielo
            // dejaria toda la pantalla a media luz en cuanto alguien toca un boton con musica sonando. El
            // cielo no se atenua -nunca se atenuo- pero si respira.
            bgRespiro = respiraOn ? Respiracion(respiraFuerza, quietud, respiraFase) : 1f;
            bgDimResp = bgDim * bgRespiro;
            albumView.BgDim = bgDimResp;
            if (panelSongs != null) panelSongs.BgDim = bgDimResp;   // el interior del disco comparte el mismo campo: atenua igual
            if (searchOverlay != null) searchOverlay.BgDim = bgDimResp;
            // Mientras la atenuacion CAMBIA, repinta el fondo del form (franjas de arriba/abajo) para que atenuen
            // junto con la rejilla: el campo es UNA SOLA PIEZA (si no, se veria una banda mas clara arriba/abajo).
            //
            // Y el umbral hace aqui un segundo trabajo que importa en la maquina del bar: la respiracion mueve
            // el brillo tan despacio que la mayoria de los cuadros no lo cambian lo bastante para verse, y esos
            // no obligan a repintar nada. Medido con el 2.5% de fabrica: 61 repintados en las 720 vueltas de
            // reloj que dura un ciclo, uno de cada once.
            if (Math.Abs(bgDimResp - bgDimPrev) > 0.0015f) this.Invalidate();
            bgDimPrev = bgDimResp;
#if ROCOLA_GPU
            if (gpuPanel != null) gpuPanel.Dim = bgDimResp;
#endif

            bool transitioning = (bgAccent.R != bgAccentTarget.R || bgAccent.G != bgAccentTarget.G || bgAccent.B != bgAccentTarget.B);
            if (transitioning)
            {
                bgAccent = LerpColor(bgAccent, bgAccentTarget, 0.16);
                if (Math.Abs(bgAccent.R - bgAccentTarget.R) <= 2 && Math.Abs(bgAccent.G - bgAccentTarget.G) <= 2 && Math.Abs(bgAccent.B - bgAccentTarget.B) <= 2)
                    bgAccent = bgAccentTarget;
                this.Invalidate();   // tambien con buscador abierto: el fondo es barato y la franja de estado debe recolorear
            }
            albumView.BgAccent = bgAccent;
#if ROCOLA_GPU
            SyncGpuFullScreen();   // muestra/oculta el panel GPU (pantalla completa) segun el modo, ANTES de los returns por modo
            if (gpuPanel != null && gpuPanel.Visible)
            {
                if (attractOn)   // atraccion: cielo nocturno fijo (sin musica, no sigue al genero)
                { gpuPanel.SkyTop = 0xFF06081Au; gpuPanel.SkyMid = 0xFF0C0E28u; gpuPanel.SkyBot = 0xFF12143Au; }
                else
                {
                    // EL CIELO RESPIRA AQUI. Estos tres colores se le pasan al panel ya calculados, asi que
                    // multiplicarlos no cuesta nada de tarjeta grafica: son tres numeros por cuadro. Antes la
                    // respiracion iba solo a 'Dim', que mueve las estrellas y los destellos y deja el cielo
                    // igual: la superficie grande -la que uno llama "la pared"- no se enteraba, y por eso no
                    // se veia respirar.
                    gpuPanel.SkyTop = ToD3D(EscalaBrillo(SkyColor(bgAccent), bgRespiro));
                    gpuPanel.SkyMid = ToD3D(EscalaBrillo(SkyColorMid(bgAccent), bgRespiro));
                    gpuPanel.SkyBot = ToD3D(EscalaBrillo(SkyColor2(bgAccent), bgRespiro));
                    gpuPanel.NebColor = ToD3D(ColorNebulosa(bgAccent));
                }   // el degradado sigue al genero
            }
#endif
            if (progress != null) progress.Accent = bgAccent;   // ESTETICA: la barra de progreso sigue el color del genero

            if (searchOpen)
            {
                if ((DateTime.Now - searchLastActivity).TotalSeconds >= 60) { CloseSearch(); return; }   // 1 min sin actividad
                searchOverlay.Accent = bgAccent;
                searchOverlay.Phase = phase;
                searchOverlay.PulseLo = levLo; searchOverlay.PulseMid = levMid; searchOverlay.PulseHi = levHi;   // cada estrella late con SU banda
                searchOverlay.CubeAngle += 0.075;   // gira mas rapido
                // El cuadro COMPLETO una de cada tres veces (~8/seg, el mismo criterio que el fondo del resto del
                // programa); en los otros dos, solo lo que de verdad se mueve. Repintar la pantalla entera 24 veces
                // por segundo era el gasto fijo mas grande de la rocola. (No-op si el buscador va por GPU: el
                // control esta oculto y lo dibuja el panel.)
                if (fullFrame) searchOverlay.Invalidate();
                else searchOverlay.InvalidarVivo();
                bool sGpu = false;
#if ROCOLA_GPU
                sGpu = (gpuPanel != null && gpuPanel.Visible);   // panel GPU encima: el mini-cubo lo dibuja la GPU (repintar el control seria invisible)
#endif
                if (miniCube.Visible) { miniCube.Phase = phase; miniCube.Avanza(0.06); if (!sGpu || miniCube.Girando) miniCube.Invalidate(); }   // el angulo avanza siempre (la GPU lo lee)
                TickMejorada(sGpu);   // la franja de estado sigue visible bajo el buscador: el letrero sigue brillando
                return;
            }

            // Y lo mismo para el INTERIOR DE UN DISCO: a los 30 s sin tocar nada, de vuelta a la pared de
            // discos (ver DiscoIdleSecs). Con un video puesto no: ahi el disco abierto es lo de menos y el
            // video manda. Ni con el asistente de botones a la vista.
            // Ni con el asistente de botones a la vista, ni en MANTENIMIENTO: mientras el operador tiene
            // abierta una ventana de ajustes, sacarle el disco de debajo seria de lo mas molesto.
            if (panelSongs != null && panelSongs.Visible && !videoOn && !searchOpen && !maintMode
                && (lblConfig == null || !lblConfig.Visible)
                && (DateTime.Now - lastInput).TotalSeconds >= DiscoIdleSecs)
            { BackToAlbums(); return; }

            // VIDEO A PANTALLA COMPLETA tras inactividad (para apreciarlo mejor)
            if (videoOn && !videoFull && (DateTime.Now - lastInput).TotalSeconds > 8) EnterVideoFull();
            if (videoFull)
            {
                if (lblAttract != null)
                {
                    double pz = 0.5 + 0.5 * Math.Sin(phase * 4.0);   // aviso AMARILLO PULSANTE
                    lblAttract.ForeColor = Color.FromArgb((int)(140 + 115 * pz), (int)(110 + 125 * pz), (int)(0 + 60 * pz));
                }
                return;   // no repintamos lo de atras: el video va mas fluido en pantalla completa
            }

            // MODO ATRACCION: en reposo, sin nada sonando, mostrar la pantalla estrellada con el cubo.
            // (nunca durante un re-escaneo: EnterAttract muestrea 'albums' y el worker lo esta mutando)
            if (!attractOn && nowPlaying == null && queue.Count == 0 && !searchOpen && !videoOn && !libBuilding
                && albums.Count > 0 && (lblConfig == null || !lblConfig.Visible)
                && (DateTime.Now - lastInput).TotalSeconds > AttractIdleSecs)
                EnterAttract();
            if (attractOn)
            {
                attractView.Phase = phase; attractView.Angle += 0.05; attractView.Invalidate();
                return;
            }

            bool albumGpuBg = false;
#if ROCOLA_GPU
            albumGpuBg = (gpuPanel != null && gpuPanel.Visible);   // el panel GPU (opaco, pantalla completa) tapa los controles CPU: repintarlos seria trabajo invisible que ademas corta el bucle de render GPU
#endif
            // (CPU) La pagina de AL LADO se hornea mientras nadie toca nada, igual que en la version con tarjeta
            // grafica: al pulsar "siguiente" las casillas ya estan hechas y no hay que re-escalar 18 caratulas en
            // ese instante. Con tope de dos por vuelta y 4 ms, asi que quien este usando la rocola no lo nota.
            if (!albumGpuBg && albumView != null && albumView.Visible) albumView.BakeAhead();
            // HOJEO dentro de un disco: sin tarjeta grafica la lista y su letrero se repintan solos hasta que
            // llegan. (Con tarjeta no hace falta: el hojeo entra en la firma de la textura y se rehace sola.)
            if (!albumGpuBg && panelSongs != null && panelSongs.Visible)
            {
                if (songList != null && songList.Sliding) songList.Invalidate();
                if (songPager != null && songPager.Animando) songPager.Invalidate();
            }

            // (CPU) Anima el BRILLO del boton pulsado en la barra de ayuda: sin esto el destello se disparaba
            // pero nadie repintaba el control -> no se veia. Repinta mientras dura (~0.4s) y UNA vez mas al
            // expirar (para borrar el ultimo halo). En GPU lo dibuja el panel como halo aparte (FillUiGlows).
            // La ceremonia de la moneda: mientras cae, la capsula se repinta. Con tarjeta grafica no hace
            // falta repintar el control -lo dibuja la textura de la interfaz-, pero su firma tiene que
            // cambiar, y de eso se encarga UiBotSig mirando el mismo Paso.
            if (pastCred != null && pastCred.Animando && !albumGpuBg) pastCred.Invalidate();
            if (helpBar != null)
            {
                int hfs = helpBar.FlashSig();
                if ((hfs != 0 || helpFlashPrev != 0) && helpBar.Visible && !albumGpuBg) helpBar.Invalidate();
                helpFlashPrev = hfs;
            }
            if (buscaView != null && buscaView.Visible)
            {
                buscaView.Phase = phase; buscaView.Abierto = searchOpen;
                if (!albumGpuBg) buscaView.Invalidate();   // en GPU el latido es un halo aparte: la textura no se rehace
            }
            if (letterBar.Visible)
            {
                letterBar.Phase = phase;
                // Solo se repintan los dos trozos que laten, no la barra entera (ver ZonasLatido). En GPU no
                // se repinta nada: el pulso de la letra es un halo por quad (FillUiGlows).
                if (!albumGpuBg)
                {
                    Rectangle zl1, zl2;
                    if (letterBar.ZonasLatido(out zl1, out zl2))
                    {
                        if (zl1.Width > 0) letterBar.Invalidate(zl1);
                        if (zl2.Width > 0) letterBar.Invalidate(zl2);
                    }
                    else letterBar.Invalidate();
                }
            }
            TickMejorada(albumGpuBg);   // brillo del letrero MEJORADA (plateado=DSEE, dorado=IA)
            if (albumView.Visible && !albumGpuBg) { albumView.Phase = phase; albumView.PulseLo = levLo; albumView.PulseMid = levMid; albumView.PulseHi = levHi; albumView.AnimTick(fullFrame || transitioning); }
#if ROCOLA_GPU
            else if (albumView.Visible && albumGpuBg) { albumView.Phase = phase; albumView.StepSpinGpu(); }   // el giro avanza aunque el fondo+cubos los pinte la GPU (sin repintar por CPU)
#endif
            if (panelSongs.Visible)
            {
                panelSongs.Accent = bgAccent;
                if ((fullFrame || transitioning) && !albumGpuBg) { panelSongs.Invalidate(); lblAlbum.Invalidate(); }   // glows: 1 de cada 3 (solo si el CPU esta a la vista)
                cubeBox.Phase = phase; cubeBox.Angle += 0.06;   // el angulo/bamboleo avanzan SIEMPRE (la GPU los lee via BuildGpuCubeState)
                if (!albumGpuBg) cubeBox.Invalidate();          // el cubo grande por CPU solo se repinta si se ve
            }
            if (miniCube.Visible) { miniCube.Phase = phase; miniCube.Avanza(0.06); if (!albumGpuBg || miniCube.Girando) miniCube.Invalidate(); }   // idem mini-cubo (en GPU lo dibuja el panel)
        }

        private static string Fmt(TimeSpan t) { return ((int)t.TotalMinutes) + ":" + t.Seconds.ToString("00"); }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            preScanStop = true;   // que el pre-analisis suelte el archivo y termine
            DisposePlaybackNow();
            // APAGADO DELIBERADO vs APAGON. El boton de poder de la rocola esta configurado en Windows para APAGAR
            // -> al presionarlo, Windows avisa y ESTE evento se dispara (CloseReason.WindowsShutDown; tambien Alt+F4
            // = UserClosing). Ahi borramos el estado vivo para que manana arranque LIMPIA. En cambio, un APAGON corta
            // la corriente de golpe y no corre NADA de esto: el archivo SOBREVIVE y, al volver la luz, la rocola
            // REANUDA (creditos + cola). Es decir, la sola presencia del archivo al arrancar delata que fue apagon.
            if (e.CloseReason == CloseReason.WindowsShutDown || e.CloseReason == CloseReason.UserClosing)
                BorraSeguro(StateFile());
            if (iaMotorProc != null) try { if (!iaMotorProc.HasExited) iaMotorProc.Kill(); } catch { }   // motor que lanzamos: se va con la rocola
            base.OnFormClosing(e);
        }

        // ==========  BOTON REDONDEADO  ==========

        // Fuente de audio para reproducir: expone lo que la rocola necesita (muestras float para el tap + medicion,
        // volumen, y tiempo actual/total para la barra de progreso). Dos implementaciones: la NORMAL (AudioFileReader,
        // cualquier formato) y la TOLERANTE (MP3 con frecuencia mezclada que NAudio rechazaria).
        private interface IAudioSource : NAudio.Wave.ISampleProvider, IDisposable
        {
            float Volume { set; }
            TimeSpan CurrentTime { get; }
            TimeSpan TotalTime { get; }
        }

        // Camino NORMAL para la cancion que suena: float + volumen + tiempos en un solo objeto.
        //
        // Los MP3 van aparte, por el mismo camino que usa el repaso de la biblioteca (AbreMp3). El lector de
        // NAudio tiene ahi una trampa por partida doble: arma el descompresor de MP3 y despues sigue
        // preparandose, y si algo falla en ese hueco -una cabecera rota, y de esas hay unas cuantas en
        // cualquier biblioteca grande- no cierra ni el descompresor ni el archivo. Lo que queda tirado lo
        // acaba cerrando el recolector de basura, Windows contesta que ya no vale, y la queja sale por un
        // hilo donde NADIE la puede recoger: se cierra la rocola entera. Por aqui se abren menos archivos que
        // en el repaso, pero se abren TODOS los que alguien pide en el bar. Es el mismo montaje que hace
        // NAudio por dentro (el lector mas un canal de muestras), asi que no cambia ni una muestra.
        private sealed class FileAudioSource : IAudioSource
        {
            private readonly Mp3FileReader mp3;
            private readonly SampleChannel canal;
            private readonly AudioFileReader r;
            public FileAudioSource(string path)
            {
                if (path != null && path.EndsWith(".mp3", StringComparison.OrdinalIgnoreCase))
                {
                    Mp3FileReader m = AbreMp3(path);
                    try { canal = new SampleChannel(m, false); mp3 = m; m = null; }
                    finally { if (m != null) { try { m.Dispose(); } catch { } } }   // el canal fallo: el lector no se queda tirado
                }
                else r = new AudioFileReader(path);
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return (mp3 != null) ? canal.WaveFormat : r.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count)
            { return (mp3 != null) ? canal.Read(buffer, offset, count) : r.Read(buffer, offset, count); }
            public float Volume { set { if (mp3 != null) canal.Volume = value; else r.Volume = value; } }
            public TimeSpan CurrentTime { get { return (mp3 != null) ? mp3.CurrentTime : r.CurrentTime; } }
            public TimeSpan TotalTime { get { return (mp3 != null) ? mp3.TotalTime : r.TotalTime; } }
            public void Dispose()
            {
                if (mp3 != null) { try { mp3.Dispose(); } catch { } }
                if (r != null) { try { r.Dispose(); } catch { } }
            }
        }

        // Camino TOLERANTE: reproduce un MP3 ya reconstruido a una sola frecuencia (stream en memoria). Mp3FileReader
        // decodifica (float via SampleChannel, que ademas da el volumen); el tiempo actual/total sale del Mp3FileReader.
        private sealed class TolerantMp3Source : IAudioSource
        {
            private readonly MemoryStream ms;
            private readonly Mp3FileReader mp3;
            private readonly SampleChannel sample;
            public TolerantMp3Source(MemoryStream cleanMp3)
            {
                ms = cleanMp3;
                mp3 = new Mp3FileReader(ms);
                sample = new SampleChannel(mp3, false);
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return sample.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count) { return sample.Read(buffer, offset, count); }
            public float Volume { set { sample.Volume = value; } }
            public TimeSpan CurrentTime { get { return mp3.CurrentTime; } }
            public TimeSpan TotalTime { get { return mp3.TotalTime; } }
            public void Dispose() { try { mp3.Dispose(); } catch { } try { ms.Dispose(); } catch { } }
        }

        // ==========  IA PROPIA: RED DE ENVOLVENTE ESPECTRAL (NIVEL 3, rama HD)  ==========
        // Un MLP chico (28 -> 48 -> 48 -> 12, tanh) ENTRENADO POR NOSOTROS (ia/entrenar_ia.py) que, viendo la
        // FORMA del espectro que sobrevivio al codec (24 bandas log + sonoridad + posicion del corte +
        // planitud), PREDICE la envolvente correcta de la banda perdida (12 sub-bandas sobre el corte,
        // relativas a la costura). El reconstructor espectral la usa EN VEZ de la caida fija de -9 dB/octava:
        // platillos recuperan su brillo real, pasajes oscuros se quedan oscuros. Pesos en rocola_ia.bin junto
        // al exe (formato RIA1); sin archivo, el reconstructor sigue con su curva fija (cero cambio). La
        // inferencia son ~4300 multiplicaciones por ventana (~23ms): costo despreciable hasta en un Atom.
        // Los dos modelos. El del DSEE re-crea la envolvente de los agudos (28 datos de la ventana -> 12 sub-bandas).
        // El del EQ mira la parte del espectro que los codecs NO tocan (el cuerpo, 158 Hz - 5.6 kHz) y dice cuanto
        // grave y cuanto aire tendria una cancion BIEN GRABADA con ese mismo cuerpo: 5 entradas -> 3 salidas.
        private static readonly RedChica NeuralEnv = new RedChica(28, 12);
        private static readonly RedChica EqNet = new RedChica(EqNetIn, EqNetOut);
        private const int EqNetIn = 5, EqNetOut = 3;
        private static readonly int[] EqNetSalida = { 0, 6, 7 };   // que bandas predice: 50 Hz, 10 kHz y 15.8 kHz

        // Red neuronal chica cargada de un archivo RIA1 (capas de pesos+sesgos, ocultas con tanh y la de salida
        // lineal). La usan DOS cosas distintas, cada una con su modelo y su contrato de entradas/salidas: el DSEE
        // para la envolvente de los agudos que re-crea, y el EQ automatico para su objetivo por cancion.
        private sealed class RedChica
        {
            public volatile bool Loaded;
            private float[][] W, B;            // pesos (fila-mayor) y sesgos por capa
            private int[] rOut, cIn;           // dimensiones por capa
            private float[] buf1, buf2;        // buffers de trabajo (sin asignar por ventana)
            private readonly int nIn, nOut;    // contrato: cuantas entradas y cuantas salidas debe tener el modelo
            public RedChica(int entradas, int salidas) { nIn = entradas; nOut = salidas; }

            public void TryLoad(string path)
            {
                try
                {
                    if (!File.Exists(path)) return;
                    byte[] d = File.ReadAllBytes(path);
                    if (d.Length < 12 || d[0] != (byte)'R' || d[1] != (byte)'I' || d[2] != (byte)'A' || d[3] != (byte)'1') return;
                    int p = 4;
                    int nl = BitConverter.ToInt32(d, p); p += 4;
                    if (nl < 1 || nl > 8) return;
                    float[][] w = new float[nl][], b = new float[nl][];
                    int[] ro = new int[nl], ci = new int[nl]; int maxDim = 0;
                    for (int L = 0; L < nl; L++)
                    {
                        int r = BitConverter.ToInt32(d, p); p += 4;
                        int c = BitConverter.ToInt32(d, p); p += 4;
                        if (r < 1 || r > 512 || c < 1 || c > 512) return;
                        w[L] = new float[r * c]; b[L] = new float[r];
                        for (int i = 0; i < r * c; i++) { w[L][i] = BitConverter.ToSingle(d, p); p += 4; }
                        for (int i = 0; i < r; i++) { b[L][i] = BitConverter.ToSingle(d, p); p += 4; }
                        ro[L] = r; ci[L] = c; if (r > maxDim) maxDim = r; if (c > maxDim) maxDim = c;
                    }
                    if (ci[0] != nIn || ro[nl - 1] != nOut) return;   // el modelo no es para este uso
                    for (int L = 1; L < nl; L++) if (ci[L] != ro[L - 1]) return;
                    buf1 = new float[maxDim]; buf2 = new float[maxDim];
                    W = w; B = b; rOut = ro; cIn = ci;
                    Loaded = true;
                }
                catch { Loaded = false; }
            }

            // y = red(x). Capas ocultas con tanh; la de salida lineal. Devuelve false si no hay modelo.
            public bool Predict(float[] x, float[] y)
            {
                float[][] w = W, b = B;
                if (!Loaded || w == null) return false;
                float[] cur = x, nxt = buf1;
                int curN = cIn[0];
                for (int L = 0; L < w.Length; L++)
                {
                    int r = rOut[L]; float[] wl = w[L], bl = b[L];
                    float[] dst = (L == w.Length - 1) ? y : nxt;
                    for (int i = 0; i < r; i++)
                    {
                        float s = bl[i]; int off = i * curN;
                        for (int j = 0; j < curN; j++) s += wl[off + j] * cur[j];
                        dst[i] = (L == w.Length - 1) ? s : (float)Math.Tanh(s);
                    }
                    cur = dst; curN = r;
                    nxt = (cur == buf1) ? buf2 : buf1;   // alterna buffers (la entrada x no se toca)
                }
                return true;
            }
        }

        // ==========  RECONSTRUCTOR ESPECTRAL DE AGUDOS (el DSEE "serio"; NIVEL 2)  ==========
        // Trabaja como el DSEE de Sony pero sin red neuronal: parte el audio en ventanas (STFT de 2048 puntos,
        // solape 50%, ventana raiz-de-Hann en analisis Y sintesis: con el espectro intacto la reconstruccion
        // es EXACTA), LOCALIZA el "acantilado" donde el codec corto los agudos y RE-CREA la banda faltante
        // transponiendola UNA OCTAVA hacia arriba (bin destino t <- bin fuente t/2, como el SBR de HE-AAC),
        // con la magnitud EMPATADA en la costura y decayendo ~9 dB/octava (como decae la musica real). La fase
        // se hereda de la fuente (suena natural, no metalico). Archivos ya completos (WAV / 320kbps, corte
        // >= ~19.3 kHz) pasan INTACTOS: sin acantilado no se toca ni un bin. Costo: ~3-5% de CPU (4 FFT de
        // 2048 por ciclo de ~23ms en estereo); por eso SOLO se ofrece si la maquina cumple requisitos
        // (ProbeAudioTier). Active se alterna EN VIVO desde Ctrl+F3 para comparar A/B (al alternar hay un
        // microcorte de ~46ms: es el colchon del STFT llenandose; normal y esperado).
        private sealed class SpectralTap : NAudio.Wave.ISampleProvider
        {
            private readonly int Frame, Hop;   // 2048 normal; 4096 en NIVEL HD (bins mas finos = deteccion y costura mas limpias)
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly int ch, rate;
            private readonly float binHz;
            public volatile bool Active;                   // false = pase directo (costo ~cero)
            private bool wasActive;                        // para reiniciar el colchon al alternar (A/B)
            private readonly float[][] inBuf, outAcc;      // por canal: ventana de entrada y acumulador de solape
            private int fill;                              // muestras acumuladas (por canal) en inBuf
            private float[] re, im;                        // espectro de trabajo (se INTERCAMBIA con el del otro canal del par)
            private float[] reB, imB;                      // espectro del segundo canal del par (solo si hay 2 o mas)
            private readonly float[] win;                  // ventana raiz-de-Hann
            private readonly int[] bitrev; private readonly float[] twCos, twSin, twSinNeg;   // tablas de la FFT (el seno tambien cambiado de signo: ver Fft)
            private readonly float[] inter;                // buffer intercalado para leer del origen
            private readonly float[] outQ; private int qHead, qLen;   // FIFO de salida (intercalado)
            private float cutHz;                           // acantilado suavizado (0 = aun sin medir)

            private volatile bool mejoro;                  // ya reconstruyo al menos UNA vez en esta cancion
            // La cancion FUE mejorada en esta reproduccion: en cuanto Regenerate() actua un cuadro, esto
            // queda prendido hasta que la cancion cambie (cada cancion estrena su propio SpectralTap).
            // Es un SEGURO, no un termometro: el letrero plateado no parpadea aunque la medicion del
            // acantilado vaya y venga; una cancion ya completa (que nunca se reconstruye) jamas lo prende.
            public bool Mejorando { get { return Active && mejoro; } }
            private bool srcEnded;
            private readonly float[] iaIn = new float[28], iaOut = new float[12];   // IA propia: entrada/salida de la red (reusables)

            public SpectralTap(NAudio.Wave.ISampleProvider s, int frameSize)
            {
                Frame = (frameSize >= 4096) ? 4096 : 2048; Hop = Frame / 2;   // solo potencias de 2 conocidas
                src = s;
                ch = Math.Max(1, s.WaveFormat.Channels);
                rate = Math.Max(8000, s.WaveFormat.SampleRate);
                binHz = (float)rate / Frame;
                inBuf = new float[ch][]; outAcc = new float[ch][];
                for (int c = 0; c < ch; c++) { inBuf[c] = new float[Frame]; outAcc[c] = new float[Frame]; }
                re = new float[Frame]; im = new float[Frame];
                if (ch >= 2) { reB = new float[Frame]; imB = new float[Frame]; }   // los canales se procesan de dos en dos (ver ProcessFrame)
                win = new float[Frame];
                for (int i = 0; i < Frame; i++) win[i] = (float)Math.Sqrt(0.5 - 0.5 * Math.Cos(2.0 * Math.PI * i / Frame));   // raiz de Hann: analisis*sintesis = Hann, que al 50% suma EXACTO 1
                bitrev = new int[Frame];
                twCos = new float[Frame / 2]; twSin = new float[Frame / 2]; twSinNeg = new float[Frame / 2];
                BuildFftTables();
                inter = new float[Hop * ch];
                outQ = new float[Frame * ch * 2];          // FIFO holgado (nunca acumula mas de Hop*ch)
            }

            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }

            public int Read(float[] buffer, int offset, int count)
            {
                bool act = Active;
                if (act != wasActive)   // alternado en vivo: reinicia el colchon (microcorte de ~46ms) y sigue
                {
                    wasActive = act;
                    fill = 0; qHead = 0; qLen = 0;
                    for (int c = 0; c < ch; c++) Array.Clear(outAcc[c], 0, Frame);
                }
                if (!act) return src.Read(buffer, offset, count);   // pase directo

                int written = 0;
                while (written < count)
                {
                    if (qLen > 0)                                    // hay salida lista: entregarla
                    {
                        // De golpe, no muestra a muestra. Esto corre por CADA muestra que sale del
                        // reconstructor (88.200 por segundo en estereo) y antes llevaba una comprobacion de
                        // vuelta al principio del circular en cada una. Como mucho son dos copias en bloque:
                        // hasta el final del circular y, si daba la vuelta, lo que quede desde el principio.
                        // A MANO, NO CON Array.Copy, Y NO ES CAPRICHO. Lo que llega aqui como float[] es
                        // EL MISMO OBJETO que NAudio le entrega al reproductor como byte[]: su WaveBuffer
                        // solapa las dos vistas en la misma memoria a proposito. Escribir muestra a muestra
                        // funciona -para numeros no se comprueba el tipo-, pero Array.Copy SI lo comprueba,
                        // ve un byte[] donde le dicen float[] y lanza un error que MATA la cancion. Eso era
                        // lo que cortaba la musica al encender el DSEE.
                        int take = Math.Min(qLen, count - written);
                        int hasta = outQ.Length - qHead;
                        int t1 = (take < hasta) ? take : hasta;
                        int dst = offset + written;
                        for (int k = 0; k < t1; k++) buffer[dst + k] = outQ[qHead + k];
                        if (t1 < take)
                        {
                            int dst2 = dst + t1, resto = take - t1;
                            for (int k = 0; k < resto; k++) buffer[dst2 + k] = outQ[k];
                        }
                        qHead += take; if (qHead >= outQ.Length) qHead -= outQ.Length;
                        qLen -= take; written += take;
                        continue;
                    }
                    if (srcEnded) break;                             // origen agotado y FIFO vacio -> fin (WaveOut detiene)
                    int need = (Frame - fill) * ch;                  // llenar la ventana de analisis
                    if (need > inter.Length) need = inter.Length;
                    int got = src.Read(inter, 0, need);
                    if (got <= 0)
                    {
                        srcEnded = true;
                        if (fill > 0)                                // cola final: completar con silencio y procesar una vez
                        {
                            for (int c = 0; c < ch; c++) Array.Clear(inBuf[c], fill, Frame - fill);
                            fill = Frame; ProcessFrame();
                        }
                        continue;
                    }
                    int frames = got / ch;
                    if (ch == 2)
                    {   // el caso normal, con los dos arrays sacados FUERA del bucle (dentro, cada muestra
                        // volvia a buscar inBuf[c] en la tabla de arrays y a comprobar sus limites)
                        float[] b0 = inBuf[0], b1 = inBuf[1];
                        for (int f = 0, k = 0; f < frames; f++, k += 2) { b0[fill + f] = inter[k]; b1[fill + f] = inter[k + 1]; }
                    }
                    else
                        for (int f = 0; f < frames; f++)
                            for (int c = 0; c < ch; c++) inBuf[c][fill + f] = inter[f * ch + c];
                    fill += frames;
                    if (fill >= Frame) ProcessFrame();
                }
                return written;
            }

            // Procesa UNA ventana completa: FFT -> (detector + regeneracion) -> iFFT -> solape-y-suma.
            // Emite Hop muestras por canal al FIFO y desliza entrada/salida media ventana.
            // Tablas de la FFT (inversion de bits y factores de giro). Las comparten el camino de
            // reproduccion y el de solo analisis, para que ambos calculen EXACTAMENTE el mismo espectro.
            private void BuildFftTables()
            {
                for (int i = 1, j = 0; i < Frame; i++)
                {
                    int bit = Frame >> 1;
                    for (; (j & bit) != 0; bit >>= 1) j ^= bit;
                    j |= bit; bitrev[i] = j;
                }
                for (int k = 0; k < Frame / 2; k++)
                {
                    twCos[k] = (float)Math.Cos(2.0 * Math.PI * k / Frame);
                    twSin[k] = (float)Math.Sin(2.0 * Math.PI * k / Frame);
                    twSinNeg[k] = -twSin[k];   // la ida usa el seno cambiado de signo y la vuelta el normal
                }
            }

            // ---------- COSECHA DE MATERIAL PARA LA IA ----------
            // Para ENSEÑARLE a la red hacen falta pares "esto queda / estos eran los agudos reales". En un MP3
            // dañado los agudos reales YA NO EXISTEN, asi que solo sirven las canciones que aun los conservan:
            // a esas se les corta el agudo A PROPOSITO y se guarda lo que habia arriba. Todo esto usa las MISMAS
            // funciones que la reproduccion (BuildIaFeatures, Hz, la FFT), asi que el material de entrenamiento
            // coincide EXACTAMENTE con lo que la red vera en vivo: si no, lo aprendido no serviria de nada.
            public SpectralTap(int rateHz, int channels)   // solo analisis: no reproduce, no lee de ninguna fuente
            {
                // EL TAMANO DE CUADRO HAY QUE PONERLO AQUI. En esta rama 'Frame' es un CAMPO (el nivel HD usa
                // 4096 para afinar mas), no una constante, y este constructor no lo ponia: se quedaba en CERO.
                // Con Frame=0 este analizador no analizaba NADA -ni una FFT, ni el acantilado- asi que el
                // pre-analisis no juntaba ni un ejemplo para la IA y tampoco media a que altura el MP3 talo
                // los agudos. Se usan 2048, que es el cuadro del reconstructor normal y el mismo con el que
                // cosecha la otra rama: asi el material entrenado vale igual en las dos.
                Frame = 2048; Hop = Frame / 2;
                src = null; ch = channels < 1 ? 1 : channels; rate = rateHz < 8000 ? 44100 : rateHz;
                binHz = (float)rate / Frame;
                re = new float[Frame]; im = new float[Frame]; win = new float[Frame];
                for (int i = 0; i < Frame; i++) win[i] = (float)Math.Sqrt(0.5 - 0.5 * Math.Cos(2.0 * Math.PI * i / Frame));
                bitrev = new int[Frame]; twCos = new float[Frame / 2]; twSin = new float[Frame / 2]; twSinNeg = new float[Frame / 2];
                BuildFftTables();
            }
            public int FrameLen { get { return Frame; } }
            public float CutHz { get { return cutHz; } }   // acantilado detectado hasta ahora (0 = aun sin medir)
            public float CutLoHz { get { return cutLoHz; } }   // por ABAJO: donde la grabacion deja de tener grave (0 = sin medir)

            // Analiza UN cuadro (Frame muestras de UN canal) y actualiza el acantilado. Igual que en vivo.
            public void AnalyzeFrame(float[] mono, int off)
            {
                for (int i = 0; i < Frame; i++) { re[i] = mono[off + i] * win[i]; im[i] = 0f; }
                Fft(false);
                DetectCliff();
            }
            // Con el cuadro ya analizado, arma un par de entrenamiento simulando un corte en cutHzSim:
            // entrada = lo que la red veria (solo mira POR DEBAJO del corte) y objetivo = la energia REAL que
            // hay ARRIBA, en la misma escala que la red debe predecir (log10 de la banda contra la costura).
            public bool MakePair(float cutHzSim, float[] featOut, float[] tgtOut)
            {
                int ny = Frame / 2;
                int cut = (int)(cutHzSim / binHz);
                if (cut < 64) return false;
                int topBin = Math.Min((int)(Math.Min(20500f, ny * binHz * 0.95f) / binHz), Math.Min(2 * cut - 2, ny - 4));
                if (topBin <= cut + 4) return false;
                if (!BuildIaFeatures(cut)) return false;
                for (int i = 0; i < 28; i++) featOut[i] = iaIn[i];
                float n2 = (float)Frame * (float)Frame;
                int sa = Hz(cut * binHz * 0.92f); if (sa >= cut) sa = cut - 1;
                double seamE = 0; for (int k = sa; k < cut; k++) seamE += re[k] * re[k] + im[k] * im[k];
                seamE = seamE / ((cut - sa) * n2) + 1e-12;
                float fc = cut * binHz, top = topBin * binHz;
                for (int j = 0; j < 12; j++)
                {
                    int a = Hz(fc * (float)Math.Pow(top / fc, j / 12.0));
                    int b = Hz(fc * (float)Math.Pow(top / fc, (j + 1) / 12.0));
                    if (a < cut) a = cut; if (b > topBin) b = topBin;
                    if (b <= a) return false;
                    double realE = 0; for (int k = a; k < b; k++) realE += re[k] * re[k] + im[k] * im[k];
                    realE = realE / ((b - a) * n2) + 1e-12;
                    float y = (float)Math.Log10(realE / seamE);
                    if (y > 0.1f) y = 0.1f; else if (y < -4f) y = -4f;   // mismos topes que aplica la reproduccion
                    tgtOut[j] = y;
                }
                return true;
            }

            // DOS CANALES POR EL PRECIO DE UNA FFT.
            //
            // Esto era, con diferencia, lo mas caro de toda la cadena de sonido: cuatro FFT de 2048 puntos por
            // ventana en estereo (ida y vuelta, por canal), el 73% del coste del audio... y todo ello en el
            // MISMO hilo que dibuja la pantalla, o sea tiempo robado a los cuadros.
            //
            // El truco es viejo y exacto: la musica es una senal REAL, asi que su espectro es simetrico y media
            // FFT compleja se estaba desperdiciando. Metiendo el canal izquierdo en la parte real y el derecho
            // en la imaginaria, UNA sola FFT trae los dos espectros mezclados, y se desenredan con esa misma
            // simetria (ver SeparaCanales). A la vuelta igual: se juntan los dos espectros ya arreglados en uno
            // solo y una sola FFT inversa devuelve los dos canales, uno en la parte real y otro en la imaginaria.
            //
            // Cuatro FFT pasan a ser DOS. No es una aproximacion ni un atajo: da lo mismo que antes salvo el
            // ultimo pelo de redondeo de los flotantes (~1e-7, unas mil veces por debajo del ultimo bit de 16).
            // Con un numero impar de canales, el que sobra va por el camino de siempre.
            private void ProcessFrame()
            {
                int cn = 0;
                for (; cn + 1 < ch; cn += 2)
                {
                    float[] x0 = inBuf[cn], x1 = inBuf[cn + 1];
                    for (int i = 0; i < Frame; i++) { float w = win[i]; re[i] = x0[i] * w; im[i] = x1[i] * w; }
                    Fft(false);
                    SeparaCanales();             // re/im = espectro del canal par ; reB/imB = el del impar
                    if (cn == 0) DetectCliff();  // el acantilado es del ARCHIVO: se mide en el canal 0 y aplica a todos
                    Regenerate();                // canal par
                    Intercambia(); Regenerate(); Intercambia();   // canal impar (Regenerate trabaja sobre re/im)
                    // se vuelven a juntar: parte real = canal par, parte imaginaria = canal impar
                    for (int i = 0; i < Frame; i++) { float t = re[i] - imB[i]; im[i] = im[i] + reB[i]; re[i] = t; }
                    Fft(true);
                    float[] a0 = outAcc[cn], a1 = outAcc[cn + 1];
                    for (int i = 0; i < Frame; i++) { float w = win[i]; a0[i] += re[i] * w; a1[i] += im[i] * w; }
                }
                for (; cn < ch; cn++)            // canal suelto (mono, o un numero impar de canales)
                {
                    float[] xin = inBuf[cn];
                    for (int i = 0; i < Frame; i++) { re[i] = xin[i] * win[i]; im[i] = 0f; }
                    Fft(false);
                    if (cn == 0) DetectCliff();
                    Regenerate();
                    Fft(true);
                    float[] acc = outAcc[cn];
                    for (int i = 0; i < Frame; i++) acc[i] += re[i] * win[i];
                }
                for (int f = 0; f < Hop; f++)      // la primera mitad ya recibio sus DOS solapes: lista para salir
                    for (int c = 0; c < ch; c++)
                    { int tail = qHead + qLen; if (tail >= outQ.Length) tail -= outQ.Length; outQ[tail] = outAcc[c][f]; qLen++; }
                for (int c = 0; c < ch; c++)
                {
                    Array.Copy(outAcc[c], Hop, outAcc[c], 0, Frame - Hop); Array.Clear(outAcc[c], Frame - Hop, Hop);
                    Array.Copy(inBuf[c], Hop, inBuf[c], 0, Frame - Hop);
                }
                fill = Frame - Hop;
            }

            // Desenreda los dos espectros que vienen dentro de una sola FFT. Se apoya en que el espectro de una
            // senal real es simetrico: la mitad de arriba es el reflejo de la de abajo. Cada pareja de bins
            // (k y su reflejo N-k) se lee ENTERA antes de escribir nada, porque las cuatro salidas se calculan
            // con esos mismos dos numeros y se escriben justo encima.
            private void SeparaCanales()
            {
                int n = Frame, h = n >> 1;
                float[] r0 = re, i0 = im, r1 = reB, i1 = imB;
                r1[0] = i0[0]; i1[0] = 0f; i0[0] = 0f;       // el bin 0 y el del medio son su propio reflejo
                r1[h] = i0[h]; i1[h] = 0f; i0[h] = 0f;
                for (int k = 1; k < h; k++)
                {
                    int m = n - k;
                    float ar = r0[k], ai = i0[k], br = r0[m], bi = i0[m];
                    float pr = (ar + br) * 0.5f, pi = (ai - bi) * 0.5f;   // canal par
                    float qr = (ai + bi) * 0.5f, qi = (br - ar) * 0.5f;   // canal impar
                    r0[k] = pr; i0[k] = pi; r0[m] = pr; i0[m] = -pi;
                    r1[k] = qr; i1[k] = qi; r1[m] = qr; i1[m] = -qi;
                }
            }

            // Pone el espectro del otro canal del par en re/im (y viceversa). Son cuatro asignaciones de
            // referencia: asi Regenerate -y todo lo que cuelga de el- trabaja sobre el canal que toca sin
            // enterarse de nada ni copiar un solo numero.
            private void Intercambia() { float[] tr = re, ti = im; re = reB; im = imB; reB = tr; imB = ti; }

            private int Hz(float hz) { int b = (int)(hz / binHz); int ny = Frame / 2; return b < 1 ? 1 : (b > ny - 1 ? ny - 1 : b); }

            // Localiza el "acantilado" del codec: la frecuencia MAS ALTA donde todavia hay energia comparable
            // a la banda media (4-8 kHz). Suavizado entre ventanas para que no baile; en silencio no se mide.
            private void DetectCliff()
            {
                int b4 = Hz(4000f), b8 = Hz(8000f);
                if (b8 <= b4 + 4) return;
                double refE = 0; for (int b = b4; b < b8; b++) refE += re[b] * re[b] + im[b] * im[b];
                refE /= (b8 - b4);
                if (refE < 1e-10) return;                        // silencio: conservar la medida previa
                float top = Math.Min(20000f, (Frame / 2) * binHz * 0.94f);
                float found = 0f;
                for (float hz = top - 300f; hz >= 9000f; hz -= 300f)
                {
                    int a = Hz(hz), b = Hz(hz + 300f); if (b <= a) b = a + 1;
                    double e = 0; for (int k = a; k < b; k++) e += re[k] * re[k] + im[k] * im[k];
                    e /= (b - a);
                    if (e > refE * 0.002) { found = hz + 300f; break; }   // ~-27 dB de la banda media: aqui sigue VIVO
                }
                if (found <= 0f) found = 9000f;                  // nada vivo arriba de 9k: el corte anda por ahi
                cutHz = (cutHz <= 0f) ? found : (cutHz * 0.85f + found * 0.15f);
                DetectCliffLow(refE);
            }

            // El acantilado de ABAJO. Muchas grabaciones viejas (y los vinilos pasados a digital) no tienen NADA
            // por debajo de 60-80 Hz: ahi el grave profundo no esta en el archivo, no es que la bocina no lo de.
            // Saber donde empieza a haber grave de verdad sirve para decidir cuanta ayuda necesita cada cancion.
            private float cutLoHz;
            private void DetectCliffLow(double refE)
            {
                float found = 0f;
                for (float hz = 25f; hz <= 140f; hz += 5f)
                {
                    int a = Hz(hz), b = Hz(hz + 5f); if (b <= a) b = a + 1;
                    double e = 0; for (int k = a; k < b; k++) e += re[k] * re[k] + im[k] * im[k];
                    e /= (b - a);
                    if (e > refE * 0.02) { found = hz; break; }   // aqui ya hay grave de verdad
                }
                if (found <= 0f) found = 140f;                   // nada vivo por debajo de 140: grabacion muy flaca
                cutLoHz = (cutLoHz <= 0f) ? found : (cutLoHz * 0.85f + found * 0.15f);
            }

            // Re-crea la banda por ENCIMA del acantilado: t <- t/2 (una octava abajo = contenido REAL que
            // sobrevivio). La ENVOLVENTE (cuanto suena cada sub-banda nueva) la decide la IA PROPIA si hay
            // modelo cargado (rocola_ia.bin); si no, la curva clasica: costura empatada y ~-9 dB/octava.
            private void Regenerate()
            {
                if (cutHz <= 0f || cutHz >= 19300f) return;      // sin medida aun, o archivo ya completo
                int ny = Frame / 2;
                int cut = (int)(cutHz / binHz);
                if (cut < 64) return;                             // corte absurdamente bajo: no inventar tanto
                mejoro = true;                                    // desde aqui SI se reconstruye (neural o clasico): el letrero queda toda la cancion
                int topBin = Math.Min((int)(Math.Min(20500f, ny * binHz * 0.95f) / binHz), Math.Min(2 * cut - 2, ny - 4));
                if (topBin <= cut + 4) return;
                if (NeuralEnv.Loaded && RegenNeural(cut, topBin)) return;   // IA propia: envolvente APRENDIDA
                double mBelow = 0, mSrc = 0;                      // costura: magnitud media bajo el corte vs banda fuente
                for (int k = cut - 6; k < cut; k++) mBelow += Math.Sqrt(re[k] * re[k] + im[k] * im[k]);
                int s0 = cut >> 1;
                for (int k = s0; k < s0 + 6; k++) mSrc += Math.Sqrt(re[k] * re[k] + im[k] * im[k]);
                if (mSrc < 1e-9) return;
                float g = (float)(mBelow / mSrc) * 0.85f;         // empatada con colchon (que la costura NUNCA suba)
                if (g > 1.1f) g = 1.1f;
                if (g <= 1e-6f) return;
                float step = (float)Math.Pow(10.0, -0.45 / cut);  // ~-9 dB por octava (una octava = cut bins)
                float f = g;
                for (int t = cut; t <= topBin; t++)
                {
                    int s = t >> 1;                               // fuente: una octava abajo (siempre < cut: contenido real)
                    re[t] += re[s] * f; im[t] += im[s] * f;
                    int m = Frame - t;                            // espejo (frecuencias negativas): la señal sigue siendo real
                    re[m] = re[t]; im[m] = -im[t];
                    f *= step;
                }
            }

            // ---- IA PROPIA: caracteristicas + envolvente aprendida ----
            // CONTRATO RIA1 (debe COINCIDIR EXACTO con ia/entrenar_ia.py):
            //   entrada[0..23]  = log10(energia media por bin, |X/N|^2) de 24 bandas log de 200 Hz al corte,
            //                     restandoles su media (forma espectral, invariante al volumen)
            //   entrada[24]     = esa media (sonoridad global, log10)
            //   entrada[25]     = corte en Hz / 20000
            //   entrada[26]     = planitud de las ultimas 8 bandas bajo el corte (log10 geo - log10 arit; <= 0)
            //   entrada[27]     = 0 (reservado)
            //   salida[0..11]   = log10(energia objetivo / energia de la COSTURA) por 12 sub-bandas log del
            //                     corte a min(2*corte, 20 kHz)   [costura = banda 0.92*corte .. corte]
            private bool BuildIaFeatures(int cut)
            {
                float n2 = (float)Frame * (float)Frame;
                float fc = cut * binHz;
                if (fc < 1200f) return false;
                double sum = 0;
                for (int i = 0; i < 24; i++)
                {
                    int a = Hz(200f * (float)Math.Pow(fc / 200f, i / 24.0));
                    int b = Hz(200f * (float)Math.Pow(fc / 200f, (i + 1) / 24.0));
                    if (b <= a) b = a + 1;
                    double e = 0; for (int k = a; k < b; k++) e += re[k] * re[k] + im[k] * im[k];
                    iaIn[i] = (float)Math.Log10(e / ((b - a) * n2) + 1e-12);
                    sum += iaIn[i];
                }
                float mean = (float)(sum / 24.0);
                for (int i = 0; i < 24; i++) iaIn[i] -= mean;
                iaIn[24] = mean;
                iaIn[25] = fc / 20000f;
                double am = 0, gm = 0;
                for (int i = 16; i < 24; i++) { am += Math.Pow(10.0, iaIn[i] + mean); gm += iaIn[i] + mean; }
                iaIn[26] = (float)(gm / 8.0 - Math.Log10(am / 8.0 + 1e-12));
                iaIn[27] = 0f;
                return true;
            }

            private bool RegenNeural(int cut, int topBin)
            {
                if (!BuildIaFeatures(cut)) return false;
                if (!NeuralEnv.Predict(iaIn, iaOut)) return false;
                float n2 = (float)Frame * (float)Frame;
                int sa = Hz(cut * binHz * 0.92f); if (sa >= cut) sa = cut - 1;
                double seamE = 0; for (int k = sa; k < cut; k++) seamE += re[k] * re[k] + im[k] * im[k];
                seamE = seamE / ((cut - sa) * n2) + 1e-12;
                float fc = cut * binHz, top = topBin * binHz;
                for (int j = 0; j < 12; j++)
                {
                    int a = Hz(fc * (float)Math.Pow(top / fc, j / 12.0));
                    int b = Hz(fc * (float)Math.Pow(top / fc, (j + 1) / 12.0));
                    if (a < cut) a = cut; if (b > topBin) b = topBin; if (b <= a) continue;
                    double mapped = 0;                               // energia de la fuente transpuesta en esta sub-banda
                    for (int t = a; t < b; t++) { int s = t >> 1; mapped += re[s] * re[s] + im[s] * im[s]; }
                    mapped = mapped / ((b - a) * n2);
                    if (mapped < 1e-14) continue;                    // fuente muda: nada que transponer aqui
                    float yj = iaOut[j]; if (yj > 0.1f) yj = 0.1f; else if (yj < -4f) yj = -4f;   // tope: nunca mas fuerte que la costura (+~1dB)
                    float sc = (float)Math.Sqrt(seamE * Math.Pow(10.0, yj) / mapped) * 0.9f;      // 0.9 = colchon
                    if (sc > 3f) sc = 3f;
                    for (int t = a; t < b; t++)
                    {
                        int s = t >> 1;
                        re[t] += re[s] * sc; im[t] += im[s] * sc;
                        int m = Frame - t;                           // espejo: la señal sigue siendo real
                        re[m] = re[t]; im[m] = -im[t];
                    }
                }
                return true;
            }

            // FFT radix-2 iterativa en sitio (tablas precalculadas). inverse=true incluye la escala 1/N.
            //
            // Es lo mas caro del reconstructor, y el bucle de mas adentro se recorre unas once mil veces por
            // cada FFT. Dos detalles que ahi dentro cuestan:
            //   - el signo del seno depende de si es ida o vuelta, y se estaba decidiendo EN CADA VUELTA del
            //     bucle. Ahora hay una segunda tabla con el seno ya cambiado de signo y se elige UNA vez.
            //   - los arreglos se leian del objeto en cada acceso. Sacados a variables locales, el traductor
            //     puede dejarlos en registros y ademas se ahorra comprobar sus limites tantas veces.
            private void Fft(bool inverse)
            {
                int n = Frame;
                float[] r = re, m = im;
                int[] br = bitrev;
                for (int i = 0; i < n; i++)
                {
                    int j = br[i];
                    if (j > i) { float t = r[i]; r[i] = r[j]; r[j] = t; t = m[i]; m[i] = m[j]; m[j] = t; }
                }
                float[] tc = twCos, ts = inverse ? twSin : twSinNeg;
                for (int size = 2; size <= n; size <<= 1)
                {
                    int half = size >> 1, tstep = n / size;
                    for (int i = 0; i < n; i += size)
                    {
                        int k = 0;
                        for (int j = i; j < i + half; j++, k += tstep)
                        {
                            float wr = tc[k], wi = ts[k];
                            int b = j + half;
                            float rb = r[b], mb = m[b];
                            float tr = rb * wr - mb * wi;
                            float ti = rb * wi + mb * wr;
                            r[b] = r[j] - tr; m[b] = m[j] - ti;
                            r[j] += tr; m[j] += ti;
                        }
                    }
                }
                if (inverse)
                {
                    float sc = 1f / n;
                    for (int i = 0; i < n; i++) { r[i] *= sc; m[i] *= sc; }
                }
            }
        }

        // Convierte flotante -> 16 bits con DITHER TPDF. El truncado directo (SampleToWaveProvider16) mete
        // distorsion de cuantizacion en pasajes MUY silenciosos (finales de cancion, colas de reverb): el
        // ultimo bit "escalona" la senal y suena a aspereza. El dither triangular de +-1 LSB convierte ese
        // error en un ruido de fondo parejo e inaudible (mucho mas natural, es lo que hace un CD bien
        // masterizado). Redondea en vez de truncar. ~4 operaciones por muestra. (En HD, WASAPI sale en
        // flotante puro y no pasa por aqui; esto ayuda a la salida WaveOut de 16 bits de respaldo.)
        private sealed class DitherWaveProvider16 : NAudio.Wave.IWaveProvider
        {
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly NAudio.Wave.WaveFormat fmt;
            private float[] fbuf;
            private uint rs;   // estado xorshift para el dither (mas barato que System.Random)
            public DitherWaveProvider16(NAudio.Wave.ISampleProvider s)
            {
                src = s;
                fmt = new NAudio.Wave.WaveFormat(s.WaveFormat.SampleRate, 16, s.WaveFormat.Channels);
                rs = (uint)Environment.TickCount | 1u;   // semilla != 0 (xorshift no arranca en 0)
            }
            // Un uniforme [0,1) barato (xorshift32). Dos restados = dither TRIANGULAR (TPDF), estadisticamente
            // identico a Random.NextDouble (media 0, varianza 1/6, rango +/-1) pero ~1.5x mas rapido: y esto
            // corre en CADA muestra de 16 bits, SIEMPRE, en el fierro modesto de la rocola.
            private float NextUni() { rs ^= rs << 13; rs ^= rs >> 17; rs ^= rs << 5; return (rs >> 8) * (1f / 16777216f); }
            public NAudio.Wave.WaveFormat WaveFormat { get { return fmt; } }
            public int Read(byte[] buffer, int offset, int count)
            {
                int need = count / 2;                                  // muestras de 16 bits que caben
                if (fbuf == null || fbuf.Length < need) fbuf = new float[need];
                int got = src.Read(fbuf, 0, need);
                int bo = offset;
                for (int i = 0; i < got; i++)
                {
                    float d = NextUni() - NextUni();    // triangular en (-1..1) LSB
                    float x = fbuf[i] * 32767f + d;
                    int q = (int)Math.Floor(x + 0.5f);                 // redondeo (no truncado)
                    if (q > 32767) q = 32767; else if (q < -32768) q = -32768;
                    buffer[bo++] = (byte)(q & 0xFF);
                    buffer[bo++] = (byte)((q >> 8) & 0xFF);
                }
                return got * 2;
            }
        }

        // DES-RECORTE (declipper): muchos MP3 de la "guerra del volumen" vienen con los picos APLASTADOS
        // de fabrica (el maestro se grabo recortado): se oye aspero en las partes fuertes. Esto detecta los
        // "techos planos" (varias muestras seguidas pegadas al maximo digital) y RECONSTRUYE el pico redondo
        // que deberia haber ahi, continuando la trayectoria de la onda (arco parabolico) hasta aterrizar en
        // la salida del techo. Solo actua en recortes al TOPE digital (~0.985+), el caso tipico; el pico
        // reconstruido puede pasar de 1.0 y eso esta bien: el limitador del final lo baja LIMPIO. Si la senal
        // no viene recortada, pasa BIT-EXACTA (solo con ~1.5 ms de retardo). Por canal, sin tocar el estereo.
        // BAJO PSICOACUSTICO. Las bocinas de un local no bajan de ~80 Hz: el grave profundo de la musica
        // simplemente NO SALE por ellas. Subirlo con EQ no sirve -solo gasta amplificador y hace toser al cono-,
        // asi que en vez de eso se generan los ARMONICOS de esa nota grave (el doble y el triple de su
        // frecuencia), que la bocina SI reproduce, y el oido reconstruye solo la nota que falta. Es un efecto
        // conocido: la "fundamental ausente". Era la mitad que le faltaba a la cadena: habia realce de agudos
        // (DSEE) y nada abajo.
        // El grave se toma de la MEZCLA MONO -en casi toda la musica el bajo va al centro- y los mismos
        // armonicos se suman a los dos canales: el grave sale centrado y sin rarezas de fase.
        // Con Amount = 0 devuelve el audio tal cual (costo cero), asi que se deja SIEMPRE en la cadena y se
        // mueve en vivo desde Ctrl+F3 para comparar A/B sin cambiar de cancion.
        private sealed class DeepBassProvider : NAudio.Wave.ISampleProvider
        {
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly int ch;
            public volatile float Amount;      // 0..1 (perilla de Ctrl+F3)
            private float lp1, lp2, lp3;       // aislar el grave profundo (3 polos = 18 dB/oct)
            private float env;                 // energia del grave (ataque rapido, caida lenta)
            private float hpS, lpS;            // banda por donde salen los armonicos
            private readonly float aLow, aHp, aLp, aAtk, aRel;
            public DeepBassProvider(NAudio.Wave.ISampleProvider s, float amount)
            {
                src = s; ch = Math.Max(1, s.WaveFormat.Channels); Amount = amount;
                int fs = s.WaveFormat.SampleRate; if (fs < 8000) fs = 44100;
                aLow = Coef(100f, fs);    // por debajo de aqui esta lo que la bocina no puede dar
                aHp = Coef(95f, fs);      // los armonicos salen de ~95 Hz...
                aLp = Coef(320f, fs);     // ...a ~320 Hz, donde cualquier bocina responde bien
                aAtk = Coef(1f / (2f * (float)Math.PI * 0.004f), fs);   // 4 ms: agarra el golpe del bombo
                aRel = Coef(1f / (2f * (float)Math.PI * 0.150f), fs);   // 150 ms: no bombea
            }
            private static float Coef(float hz, int fs)
            {
                float a = (float)(1.0 - Math.Exp(-2.0 * Math.PI * hz / fs));
                return a < 0f ? 0f : (a > 1f ? 1f : a);
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count)
            {
                int n = src.Read(buffer, offset, count);
                float amt = Amount;
                if (n <= 0 || amt <= 0.001f) return n;   // apagado: pase directo
                float mix = amt * 0.85f;
                int end = offset + n - (ch - 1);   // solo cuadros COMPLETOS (si sobra una muestra suelta, pasa tal cual)
                for (int i = offset; i < end; i += ch)
                {
                    float m = buffer[i];
                    for (int c = 1; c < ch; c++) m += buffer[i + c];
                    if (ch > 1) m /= ch;
                    // 1) aislar el grave que la bocina NO puede reproducir
                    lp1 += (m - lp1) * aLow;
                    lp2 += (lp1 - lp2) * aLow;
                    lp3 += (lp2 - lp3) * aLow;
                    float low = lp3;
                    // 2) seguir su energia: asi los armonicos respiran con el bajo y no con el resto
                    float a = low < 0f ? -low : low;
                    env += (a - env) * (a > env ? aAtk : aRel);
                    float h = 0f;
                    if (env > 1e-4f)   // en silencio no se inventa nada (no amplificar el ruido de fondo)
                    {
                        // 3) NORMALIZAR antes de generar: asi el timbre del bajo no cambia con el volumen.
                        //    x^2 da el 2o armonico y x^3 el 3o. Hacen falta DOS armonicos SEGUIDOS para que
                        //    el oido reconstruya la nota; solo con el 2o se oiria una octava mas arriba.
                        float nz = low / env;
                        if (nz > 1.5f) nz = 1.5f; else if (nz < -1.5f) nz = -1.5f;
                        float n2 = nz * nz;
                        h = ((n2 - 0.5f) * 0.8f + n2 * nz * 0.6f) * env;
                    }
                    // 4) dejar SOLO la banda que la bocina si da (el paso-alto tambien quita el continuo del x^2)
                    hpS += (h - hpS) * aHp; h -= hpS;
                    lpS += (h - lpS) * aLp; h = lpS * mix;
                    for (int c = 0; c < ch; c++) buffer[i + c] += h;   // el mismo grave a los dos canales: centrado
                }
                return n;
            }
        }

        private sealed class DeclipProvider : NAudio.Wave.ISampleProvider
        {
            private const float Thresh = 0.985f;   // umbral del techo digital
            private const int MinRun = 3;          // menos de 3 muestras al tope = pico sano (no se toca)
            private const int MaxRun = 64;         // mas de ~1.5 ms plano = a proposito (sintetizador); no se toca
            private const int D = MaxRun + 4;      // retardo: el techo entero cabe dentro antes de salir
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly int ch;
            private readonly float[] delay;        // circular: D cuadros * canales
            private int dpos;                      // cuadro de escritura actual
            private int primed;                    // cuadros cargados (mientras se llena sale silencio: ~1.5 ms una vez)
            private readonly int[] runLen;         // por canal: muestras seguidas pegadas al techo
            private readonly int[] runSign;        // por canal: signo del techo actual (+1/-1)
            private readonly float[] preVal;       // por canal: la muestra justo ANTES del techo
            private readonly float[] preSlope;     // por canal: pendiente de entrada al techo
            private readonly float[] last1, last2; // por canal: las dos muestras anteriores (para la pendiente)
            private readonly bool[] tooLong;       // por canal: el techo se paso de MaxRun (abandonar)
            public DeclipProvider(NAudio.Wave.ISampleProvider s)
            {
                src = s; ch = Math.Max(1, s.WaveFormat.Channels);
                delay = new float[D * ch];
                runLen = new int[ch]; runSign = new int[ch]; preVal = new float[ch]; preSlope = new float[ch];
                last1 = new float[ch]; last2 = new float[ch]; tooLong = new bool[ch];
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }
            private void Repair(int c, float landing)
            {
                int L = runLen[c];
                if (L < MinRun || L > MaxRun || tooLong[c]) return;
                // arco: p(i) = preVal + preSlope*i + a2*i^2, con p(L+1) = landing (aterriza en la salida del techo)
                float lp1 = L + 1f;
                float a2 = (landing - preVal[c] - preSlope[c] * lp1) / (lp1 * lp1);
                int sgn = runSign[c];
                for (int i = 1; i <= L; i++)
                {
                    int idx = dpos - L + (i - 1); if (idx < 0) idx += D;   // posicion del i-esimo cuadro del techo
                    int q = idx * ch + c;
                    float orig = delay[q];
                    float p = preVal[c] + preSlope[c] * i + a2 * i * i;
                    if (p > 4f) p = 4f; else if (p < -4f) p = -4f;         // tope de cordura del arco
                    // nunca por DEBAJO del techo grabado: en el peor caso queda igual que venia (cero riesgo)
                    if (sgn > 0) { if (p > orig) delay[q] = p; }
                    else { if (p < orig) delay[q] = p; }
                }
            }
            public int Read(float[] buffer, int offset, int count)
            {
                int n = src.Read(buffer, offset, count);
                if (n <= 0) return n;
                int frames = n / ch;
                for (int f = 0; f < frames; f++)
                {
                    int bi = offset + f * ch, di = dpos * ch;
                    for (int c = 0; c < ch; c++)
                    {
                        float x = buffer[bi + c];
                        float ax = x < 0f ? -x : x;
                        int sgn = x >= 0f ? 1 : -1;
                        if (ax >= Thresh)
                        {
                            if (runLen[c] > 0 && sgn != runSign[c])   // salto de techo + a techo - (onda cuadrada): cerrar y abrir
                            { Repair(c, x); runLen[c] = 0; tooLong[c] = false; }
                            if (runLen[c] == 0)
                            { runSign[c] = sgn; preVal[c] = last1[c]; preSlope[c] = last1[c] - last2[c]; }
                            runLen[c]++;
                            if (runLen[c] > MaxRun) tooLong[c] = true;
                        }
                        else if (runLen[c] > 0)
                        { Repair(c, x); runLen[c] = 0; tooLong[c] = false; }
                        last2[c] = last1[c]; last1[c] = x;
                        float outv = delay[di + c];            // sale la muestra de hace D cuadros (ya reparada si toco)
                        delay[di + c] = x;
                        buffer[bi + c] = (primed < D) ? 0f : outv;
                    }
                    dpos++; if (dpos >= D) dpos = 0;
                    if (primed < D) primed++;
                }
                return n;
            }
        }

        // LIMITADOR CON PRE-ESCUCHA (lookahead): en vez de recortar el pico en seco (lo que mete distorsion
        // aspera al subir el volumen), mira unos milisegundos HACIA ADELANTE y baja la ganancia SUAVE antes de
        // que llegue el pico, recuperandola despacio. Asi se puede subir mucho el volumen y que suene fuerte pero
        // LIMPIO. Aplica la MISMA ganancia a los dos canales (no mueve la imagen estereo). ~5 operaciones por
        // muestra: barato hasta en la XP. Va al final de la cadena, tras el nivelado/realce.
        private sealed class LookaheadLimiter : NAudio.Wave.ISampleProvider
        {
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly int ch;
            private readonly float ceiling;    // techo (0..1): la senal nunca lo pasa
            private readonly int look;         // frames de pre-escucha (retardo)
            private readonly float[] delay;    // retardo circular: look frames * canales
            private int dpos;                  // frame actual del circular
            private int primed;                // frames ya cargados (durante el cebado sale silencio)
            private float env = 1f;            // ganancia de reduccion actual (1 = sin reducir)
            private int hold;                  // frames que faltan para que el pico que la bajo SALGA del retardo
            private readonly float atk, rel;   // bajada (rapida) y recuperacion (lenta)
            public LookaheadLimiter(NAudio.Wave.ISampleProvider s, float ceilingLin, double lookMs)
            {
                src = s; ch = Math.Max(1, s.WaveFormat.Channels); ceiling = ceilingLin;
                int rate = s.WaveFormat.SampleRate; if (rate < 8000) rate = 44100;
                look = Math.Max(16, (int)(lookMs * 0.001 * rate));
                delay = new float[look * ch];
                atk = 1f - (float)Math.Exp(-9.0 / look);            // llega al 99.99% de la bajada DENTRO de la pre-escucha
                rel = 1f - (float)Math.Exp(-1.0 / (0.12 * rate));   // recupera en ~120 ms
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count)
            {
                int n = src.Read(buffer, offset, count);
                if (n <= 0) return n;
                int frames = n / ch;
                for (int f = 0; f < frames; f++)
                {
                    int bi = offset + f * ch;
                    float peak = 0f;
                    for (int c = 0; c < ch; c++) { float a = buffer[bi + c]; if (a < 0f) a = -a; if (a > peak) peak = a; }
                    float target = (peak > ceiling) ? (ceiling / peak) : 1f;
                    // ATACAR, RETENER, Y SOLO ENTONCES SOLTAR.
                    //
                    // Antes la ganancia seguia la muestra que ENTRA, pero lo que sale es la de hace 3 ms. Al
                    // pasar un golpe, la ganancia bajaba en el momento en que el pico ENTRABA... y en cuanto
                    // el golpe empezaba a decaer las muestras siguientes ya no pedian reduccion, asi que la
                    // ganancia empezaba a SOLTAR mientras el pico seguia dentro del retardo. Cuando el pico
                    // llegaba por fin a la salida, la ganancia ya no estaba abajo del todo, se pasaba del
                    // techo y lo cortaba en seco la red de seguridad: la punta de la onda salia APLANADA
                    // hasta dos milisegundos, que es lo que se oye como aspereza en un bombo o una tarola.
                    //
                    // El arreglo es de manual: cuando se ataca, se apunta cuantos frames faltan para que ese
                    // pico salga del retardo, y hasta entonces NO se suelta. Asi la ganancia sigue abajo
                    // justo cuando el pico cruza la salida, que es para lo que existe la pre-escucha.
                    if (target < env) { env += atk * (target - env); hold = look; }
                    else if (hold > 0) hold--;                          // el pico que la bajo aun no ha salido
                    else env += rel * (target - env);                   // ya salio: soltar despacio
                    int di = dpos * ch;
                    for (int c = 0; c < ch; c++)
                    {
                        float outv = delay[di + c] * env;    // muestra de hace look frames, ya con la ganancia bajada
                        delay[di + c] = buffer[bi + c];       // guarda la entrante
                        if (primed < look) outv = 0f;         // cebado: los primeros look frames salen en silencio
                        else if (outv > ceiling) outv = ceiling;    // red de seguridad si un transitorio se colo
                        else if (outv < -ceiling) outv = -ceiling;
                        buffer[bi + c] = outv;
                    }
                    dpos++; if (dpos >= look) dpos = 0;
                    if (primed < look) primed++;
                }
                return n;
            }
        }

        // FUNDIDO de SALIDA (fade suave al TERMINAR cada cancion): baja el volumen suave en vez de cortar en
        // seco, para que el paso al siguiente tema no sea un tajo. NO lleva fundido de ENTRADA a proposito:
        // arrancar desde silencio se oia "bajo" al principio en la rocola. NO solapa dos canciones (un crossfade
        // con solape pediria rehacer el motor y arriesgar la fiabilidad del negocio). Va al FINAL de la cadena
        // (tras el limitador); la medicion de volumen no se ve afectada (va antes, en LevelTap). Lineal = sin clics.
        private sealed class FadeProvider : NAudio.Wave.ISampleProvider
        {
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly int ch;
            private readonly long fadeFrames;    // frames de rampa del fundido de salida
            private long totalFrames;            // frames totales (0 = desconocido o muy corta: sin fundido de salida)
            private long pos;                    // frames ya entregados
            public FadeProvider(NAudio.Wave.ISampleProvider s, long total, double fadeSec)
            {
                src = s; ch = Math.Max(1, s.WaveFormat.Channels);
                int rate = s.WaveFormat.SampleRate; if (rate < 8000) rate = 44100;
                fadeFrames = (long)(fadeSec * rate); if (fadeFrames < 1) fadeFrames = 1;
                totalFrames = total;
                if (totalFrames > 0 && totalFrames < fadeFrames * 4) totalFrames = 0;   // cancion muy corta: sin fundido de salida
            }
            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count)
            {
                int n = src.Read(buffer, offset, count);
                if (n <= 0) return n;
                int frames = n / ch;
                // Fuera de los ultimos segundos no hay nada que hacer, y eso es TODA la cancion menos el final.
                // Antes se recorria muestra a muestra igualmente para acabar multiplicando por uno.
                if (totalFrames <= 0 || pos + frames <= totalFrames - fadeFrames) { pos += frames; return n; }
                for (int f = 0; f < frames; f++)
                {
                    long rem = totalFrames - (pos + f);                                 // frames que faltan para el final
                    if (rem >= fadeFrames) continue;
                    float g = (rem <= 0) ? 0f : (float)((double)rem / fadeFrames);      // fundido de SALIDA
                    int bi = offset + f * ch; for (int c = 0; c < ch; c++) buffer[bi + c] *= g;
                }
                pos += frames;
                return n;
            }
        }

        // ==========  RENDER DEL CUBO (compartido)  ==========
        // TANGENTE HIPERBOLICA aproximada (Pade 3/2), para la saturacion suave del realce de agudos. La de la
        // libreria matematica se llamaba UNA VEZ POR MUESTRA Y CANAL -88,200 veces por segundo- y era de lo mas
        // caro que hacia la cadena de audio. Esta cuesta 5.6 veces menos (medido: del 0.23% de un nucleo al
        // 0.04%) y dibuja la misma curva: se aparta como mucho 0.024, y como el realce entra al 7% en el peor
        // caso, en la salida eso queda 56 dB por debajo de la senal. Inaudible.
        // OJO: la red neuronal del DSEE usa la tangente DE VERDAD y ahi no se toca, porque el modelo se entreno
        // con esa; ademas alli se llama unas 2,600 veces por segundo, o sea nada.
        internal static float TanhRapida(float x)
        {
            if (!(x > -3f)) return -1f;   // atrapa tambien NaN: ninguna comparacion con NaN es cierta
            if (x > 3f) return 1f;
            float x2 = x * x;
            return x * (27f + x2) / (27f + 9f * x2);
        }

        // Toma el nivel de audio (RMS) del bloque recien leido SIN modificar el sonido: solo observa el
        // buffer que ya lleno el lector y lo reporta. Sirve para que las estrellas laten con la musica.
        // Como el colchon es de ~1s, el nivel va algo adelantado de lo que se oye (envolvente de energia).
        private class LevelTap : NAudio.Wave.ISampleProvider
        {
            private readonly NAudio.Wave.ISampleProvider src;
            private readonly Form1 owner;
            public float Gain = 1f;   // NIVELADO: ganancia de volumen de esta cancion (1 = sin cambio). Se aplica DESPUES de medir el nivel crudo.
            public float Master = 1f; // SUBIR TODO: ganancia general (dB de Ctrl+F3) para todas las canciones. Los picos que se pasen los redondea la RODILLA SUAVE de abajo (no recorte aspero).
            // REALCE DE AGUDOS (exciter armonico, tipo DSEE): separa la banda alta con un paso-alto de un polo,
            // la satura suave (tanh: crea armonicos NUEVOS por encima, el "aire" que el MP3 recorta) y mezcla
            // una pizca de vuelta. Todo en el dominio del tiempo: ~2 operaciones y un tanh por muestra, ~1-2%
            // de CPU en la rocola (nada de FFT). 0 = apagado (la pasada ni se ejecuta si tampoco hay nivelado).
            public float Excite = 0f;   // intensidad 0..1 (perilla en Ctrl+F3; ajustable en vivo)
            private float[] exLp;       // estado del filtro del exciter (uno por canal)
            // EQ AUTOMATICO: correccion en dB por banda (8) o null = apagado. Se aplica con biquads
            // PEAKING (RBJ) en cascada, SOLO en las bandas con correccion real (0 dB = identidad exacta,
            // el biquad ni se crea). ~9 operaciones por muestra por banda activa (tipico: 2-4 bandas).
            public volatile float[] EqDb;
            private float[] eqDbUsed;   // referencia aplicada (los coeficientes se recalculan solo si cambia)
            private float[][] eqCoef;   // 8 biquads (null = banda sin correccion)
            private float[] eqSt;       // estados: canal * banda * 4
            private int eqActivos;
            public LevelTap(NAudio.Wave.ISampleProvider s, Form1 o) { src = s; owner = o; }
            public NAudio.Wave.WaveFormat WaveFormat { get { return src.WaveFormat; } }
            public int Read(float[] buffer, int offset, int count)
            {
                int n = src.Read(buffer, offset, count);
                if (n > 0 && owner != null)
                {
                    // RED DE SEGURIDAD, y no es teorica: en una biblioteca con miles de archivos pobres o
                    // recortados, uno dañado puede decodificar a NaN o a infinito. Eso no seria "un ruido y
                    // ya": se queda PEGADO. Casi todo lo que viene despues arrastra un estado -el piso movil
                    // del detector de golpes, la ganancia del limitador, la sonoridad que se esta midiendo de
                    // la cancion, el promedio del EQ- y en cuanto entra un NaN esas cuentas ya no vuelven a
                    // valer: el limitador se quedaria mudo el resto de la noche. Aqui se corta de raiz, ANTES
                    // de medir nada. Es UNA comparacion por muestra, y de paso atrapa los valores absurdos
                    // (un archivo roto que devuelve 1e30) que reventarian el nivelado.
                    { int fin0 = offset + n; for (int i = offset; i < fin0; i++) { float x0 = buffer[i]; if (!(x0 >= -4f && x0 <= 4f)) buffer[i] = 0f; } }
                    owner.ReportAudioBlock(buffer, offset, n, WaveFormat.SampleRate, WaveFormat.Channels);   // mide el nivel CRUDO (beat + sonoridad + huella tonal) ANTES de tocar nada
                    float g = Gain * Master, ex = Excite;
                    float[] eqDb = EqDb;
                    bool exOn = ex > 0.001f, eqOn = eqDb != null;
                    if (eqOn && !ReferenceEquals(eqDb, eqDbUsed))
                    {
                        int ch0 = WaveFormat.Channels; if (ch0 < 1) ch0 = 1;
                        eqCoef = new float[8][]; eqActivos = 0;
                        for (int b = 0; b < 8; b++) { eqCoef[b] = Form1.EqPeak(Form1.EqCentros[b], WaveFormat.SampleRate, eqDb[b]); if (eqCoef[b] != null) eqActivos++; }
                        eqSt = new float[ch0 * 32];
                        eqDbUsed = eqDb;
                    }
                    if (eqOn && eqActivos == 0) eqOn = false;
                    if (g != 1f || exOn || eqOn)   // nivelado + EQ + realce en UNA pasada (el limitador de la cadena controla los picos)
                    {
                        int ch = WaveFormat.Channels; if (ch < 1) ch = 1;
                        if (exOn && (exLp == null || exLp.Length < ch)) exLp = new float[ch];
                        const float A = 0.55f;    // paso-alto ~5.5 kHz (a 44.1k): la banda donde el MP3 pierde el "aire"
                        float mix = ex * 0.5f;    // tope de mezcla: el realce es una PIZCA (el exceso suena aspero)
                        int end = offset + n, ci = 0;
                        for (int i = offset; i < end; i++)
                        {
                            float v = buffer[i] * g;
                            if (eqOn)
                            {
                                int p0 = ci * 32;
                                for (int b = 0; b < 8; b++)
                                {
                                    float[] cf = eqCoef[b]; if (cf == null) continue;
                                    int q = p0 + b * 4;
                                    float o = cf[0] * v + cf[1] * eqSt[q] + cf[2] * eqSt[q + 1] - cf[3] * eqSt[q + 2] - cf[4] * eqSt[q + 3];
                                    eqSt[q + 1] = eqSt[q]; eqSt[q] = v;
                                    eqSt[q + 3] = eqSt[q + 2]; eqSt[q + 2] = o;
                                    v = o;
                                }
                            }
                            if (exOn)
                            {
                                float lp = (exLp[ci] += (v - exLp[ci]) * A);
                                float h = v - lp;                                   // solo la banda alta que sobrevivio
                                v += Form1.TanhRapida(h * 2.5f) * 0.4f * mix;      // saturacion suave = armonicos nuevos por encima (brillo/presencia)
                            }
                            if (exOn || eqOn) { ci++; if (ci >= ch) ci = 0; }
                            // El control de picos ya NO se hace aqui (era una rodilla que distorsiona al empujar):
                            // lo hace el LIMITADOR CON PRE-ESCUCHA al final de la cadena, que baja la ganancia suave
                            // ANTES del pico. Aqui la senal sale CRUDA (puede pasar de 1.0; el limitador la controla).
                            buffer[i] = v;
                        }
                    }
                }
                return n;
            }
        }

        // Campo de estrellas reutilizable: cielo + estrellas titilantes (mas brillantes) + estrellas
        // fugaces ocasionales. Lo usan el fondo de navegacion (teñido por genero) y el modo atraccion
        // (cielo negro y estrellas multicolor). El titileo es LENTO a proposito para verse suave aun a 8fps.
        private class Starfield
        {
            public bool Varied = false;   // true = colores variados (atraccion); false = blanco->tinte (genero)
            public float Density = 1f;    // multiplicador de cantidad de estrellas (el fondo del form usa menos)
            // MENOS ESTRELLAS DETRAS DE LAS LETRAS.
            //
            // La rocola tiene dos franjas de texto que no se mueven: el abecedario de arriba y la barra de
            // estado de abajo. El cielo pasa por detras de las dos, y una estrella justo detras de una letra
            // le quita contraste: se lee peor de lejos, que es como se lee en un bar.
            //
            // Con esto encendido, una estrella que caiga en una de esas dos franjas se vuelve a tirar: casi
            // siempre acaba en otro sitio, y las pocas que insisten se quedan. Asi las franjas quedan mas
            // despejadas SIN quedarse vacias -un hueco negro se notaria mas que las estrellas- y sin perder
            // ni una del cielo: se mueven, no se pierden.
            //
            // EL AZAR DE VOLVER A TIRAR VA APARTE, y esto importa mas de lo que parece. Si se tirara del
            // mismo azar que todo lo demas, cada tiro de mas correria la fila entera y saldria OTRO cielo
            // distinto: otras estrellas, otros brillos, otros colores. Con un azar propio, el cielo es
            // exactamente el mismo con esto encendido o apagado, y lo unico que cambia es DONDE caen las
            // pocas que estorbaban. Se vio en la bateria: al hacerlo mal, el cielo perdia 13 de 56.
            public bool QuietBands = false;
            // Que parte de la pantalla ocupan esas franjas. Son de sobra a proposito: cubren el texto y un
            // poco mas, para que ninguna estrella quede pegada al filo de una letra.
            private const float FranjaArriba = 0.13f, FranjaAbajo = 0.88f;
            // Cuantas veces se vuelve a tirar. Con una sola, de cada cuatro estrellas que caian detras de
            // las letras se queda una: bastantes menos, pero no cero.
            private const int TirosFranja = 1;
            private static bool EnFranja(float y) { return y < FranjaArriba || y > FranjaAbajo; }
            public float Dim = 1f;        // atenuacion del starfield (1 = normal; ~0.45 mientras se navega con musica). Solo estrellas/brillos, no el cielo

            // QUE SE DIBUJA. Solo hay dos cosas en el cielo, las mismas por CPU y por tarjeta grafica para
            // que se vea igual por los dos caminos: la ESTRELLA de cinco puntas -las medianas y las grandes-
            // y el PUNTO redondo del polvo del fondo, que mide dos o tres pixeles y ahi una silueta no seria
            // una silueta, seria una mancha con pelusa. Quien es quien lo dice 'Kind', que ya lo decia.
            internal const int FormaEstrella = 0, FormaPunto = 1;
            // Bri: lo brillante que es, de 0 a 255, en una escala CONTINUA. Antes solo habia tres escalones
            // -grande, mediana, polvo- y por eso el cielo se veia hecho de tres cosas repetidas; un cielo de
            // verdad tiene un punado de estrellas fuertes y cientos que apenas se adivinan.
            // Rayos: si lleva las cuatro rayitas cruzadas. Las llevan MUY pocas (ver Ensure).
            private struct Star { public float X, Y; public int Size, Kind; public byte R, G, B, Bri; public bool Rayos; public float Tint, Off, Spd; public byte Band; }   // Band: 0=graves,1=medios,2=agudos
            private struct Shoot { public bool On; public float X, Y, VX, VY; public float Life, MaxLife; }
            private Star[] stars;
            private int sw = -1, sh = -1;
            private SolidBrush sb;
            private Pen sp;
            // ESTETICA (glow): sprites de resplandor radial pre-horneados UNA sola vez y COMPARTIDOS por todas
            // las instancias. Se estampan detras del nucleo de cada estrella: fuerte en la grande, tenue en la
            // chica, nada en los puntos -> "brillan de verdad" sin contaminar visualmente.
            private static Bitmap[] glowPal;   // ESTETICA/RENDIMIENTO: un sprite de glow PRE-HORNEADO por color (sin matriz por estrella)
            private static readonly Color[] glowCols = {
                Color.White,                          // 0 blanco
                Color.FromArgb(255, 120, 120),        // 1 rojo
                Color.FromArgb(255, 180, 110),        // 2 naranja
                Color.FromArgb(255, 225, 140),        // 3 dorado
                Color.FromArgb(150, 255, 180),        // 4 verde
                Color.FromArgb(150, 235, 255),        // 5 cian
                Color.FromArgb(150, 180, 255),        // 6 azul
                Color.FromArgb(225, 165, 255)         // 7 violeta/rosa
            };
            private static readonly object glowLock = new object();
            private readonly PointF[] spk = new PointF[4];   // buffer reusable de las rayitas (sin asignar por estrella)
            private Shoot[] shoots = new Shoot[2];
            private int nextShoot = 0, lastTick = 0;
            // TITILEO por CUADROS HORNEADOS: K capas con el MISMO patron de estrellas a distinto brillo.
            // Rotarlas (una copia por cuadro) reproduce el titileo SIN recalcular ~120 estrellas por cuadro:
            // recupera el efecto animado al costo de una copia (no de recalculo) -> fluido en el CPU lento.
            private const int TwK = 8;
            private Bitmap[] layers;
            private int lw = -1, lh = -1;
            private readonly Random rnd = new Random();
            // Cache del cuadro: el starfield se dibuja a un bitmap y solo se reconstruye cada ~110ms
            // (para el titileo). Asi cada Draw es un blit barato aunque lo pidan muchas veces seguidas
            // los controles transparentes encima (etiquetas de estado, lblAlbum, cubeBox). Antes se
            // redibujaban ~89 rectangulos en cada repintado transparente -> tormenta -> traba/crash.
            private Bitmap cache;
            private int cw = -1, ch = -1, cSky = 0, cTint = 0, lastBuild = 0;
            private int cSky2 = 0;                                        // color inferior del degradado del cache
            private int sBucket = int.MinValue, lBucket = int.MinValue;   // "minuto" del patron actual (cambia cada 60s)
            // PANTALLA COMPLETA como UNA SOLA PIEZA: el campo de estrellas se hornea al tamano de TODA la pantalla
            // (SkyFullW x SkyFullH) y cada fondo (franjas del form, rejilla de discos, interior del disco) pinta
            // solo su VENTANA (offset SkyOffsetX/Y). Asi las estrellas cruzan los bordes de las secciones sin
            // cortarse ni desalinearse: el patron, el cielo y la densidad son continuos entre secciones.
            public int SkyOffsetX = 0, SkyOffsetY = 0, SkyFullW = 0, SkyFullH = 0;
            private int FullW(int w) { return SkyFullW > w ? SkyFullW : w; }   // ancho de pantalla completa (>= la ventana); si no se fijo, la ventana ES la pantalla
            private int FullH(int h) { return SkyFullH > h ? SkyFullH : h; }
            public Color SkyMid = Color.Empty;                            // color INTERMEDIO (azul noche); si Empty -> 2 paradas (punto medio)
            public Color Acento = Color.Empty;                            // el color del GENERO que suena: es con el que se tinen las nebulosas
            private LinearGradientBrush skyBrush;                         // pincel de cielo en DEGRADADO (cacheado, ligado al genero)
            private int gbW = -1, gbOff = -99999, gbFull = -1, gbTop = 0, gbMid = 0, gbBot = 0;
            private Bitmap skyCache;                                       // RENDIMIENTO: cielo (degradado) HORNEADO a bitmap; se copia por cuadro en vez de rellenar el degradado cada vez
            private int scW = -1, scH = -1;
            private int fscTop = 0, fscMid = 0, fscBot = 0;               // colores con los que se horneo el cielo de pantalla completa (se re-hornea solo al cambiar genero/tamano)
            // DERIVA con la musica (igual que la version GPU): al sonar, el campo entero se desliza LENTO en diagonal
            // (abajo-derecha) y se envuelve por los bordes. Barato: en la vista de discos solo desplaza el blit de la
            // capa de estrellas (toroidal); en el buscador desplaza cada estrella. Solo avanza en repintados COMPLETOS.
            private int driftLastMs; private float driftEnv, driftX, driftY;
            private const float DriftVX = 18f, DriftVY = 9f;             // px/seg (derecha, abajo): lento, diagonal 2:1 (como GPU)

            // Avanza la deriva segun el RELOJ. Se llama UNA vez por latido de la animacion, desde el form, y no
            // desde el dibujado: si se avanzara al dibujar, la deriva iria al ritmo al que toque rehacer las
            // cosas -que no es constante- y el fondo se veria a tirones aunque la cuenta fuera correcta.
            public void AvanzaDeriva(float pulse)
            {
                int now = Environment.TickCount;
                float dt = (driftLastMs == 0) ? 0f : (now - driftLastMs) / 1000f;
                driftLastMs = now;
                if (dt < 0f) dt = 0f; else if (dt > 0.2f) dt = 0.2f;   // acota saltos (tras un hueco largo, p.ej. saliendo de GPU)
                float tgt = (pulse > 0.02f) ? 1f : 0f;
                driftEnv += (tgt - driftEnv) * (tgt > driftEnv ? Math.Min(1f, dt * 2.5f) : Math.Min(1f, dt * 0.6f));   // ataque medio, caida lenta
                int w = (lw > 0) ? lw : 0, h = (lh > 0) ? lh : 0;
                driftX += driftEnv * DriftVX * dt; if (w > 0) driftX %= w;   // env>=0 -> solo crece; modulo -> [0,w)
                driftY += driftEnv * DriftVY * dt; if (h > 0) driftY %= h;
            }
            private void UpdateDrift(int w, int h, float pulse) { AvanzaDeriva(pulse); }

            // Pincel de cielo en degradado vertical CONTINUO: el degradado abarca TODA la pantalla (SkyFullH)
            // y se desplaza segun donde esta este fondo (SkyOffsetY), para que las secciones no se noten
            // divididas (todo se ve como una sola pieza). Cacheado: se recrea solo al cambiar tamano/posicion/colores.
            private void EnsureSkyBrush(int w, int h, Color top, Color bottom)
            {
                int off = SkyOffsetY;
                int full = (SkyFullH > h) ? SkyFullH : h;
                Color mid = (SkyMid.A == 0)
                    ? Color.FromArgb(255, (top.R + bottom.R) / 2, (top.G + bottom.G) / 2, (top.B + bottom.B) / 2)   // sin mid: punto medio (= 2 paradas)
                    : SkyMid;
                int t = top.ToArgb(), m = mid.ToArgb(), b = bottom.ToArgb();
                if (skyBrush != null && gbW == w && gbOff == off && gbFull == full && gbTop == t && gbMid == m && gbBot == b) return;
                if (skyBrush != null) { skyBrush.Dispose(); skyBrush = null; }
                LinearGradientBrush lgb = new LinearGradientBrush(new Rectangle(0, -off, w, full + 1), top, bottom, LinearGradientMode.Vertical);
                ColorBlend cb = new ColorBlend(3);
                cb.Colors = new Color[] { top, mid, bottom };          // negro arriba -> azul noche en medio -> resplandor/azul abajo
                cb.Positions = new float[] { 0f, 0.42f, 1f };          // negro SOLO en el cenit; el azul domina casi toda la pantalla; genero abajo
                lgb.InterpolationColors = cb;
                skyBrush = lgb;
                gbW = w; gbOff = off; gbFull = full; gbTop = t; gbMid = m; gbBot = b;
            }

            // Hornea un sprite de resplandor por color (una vez). Caro de crear, baratisimo de estampar despues.
            private static void EnsureGlow()
            {
                if (glowPal != null) return;
                lock (glowLock)
                {
                    if (glowPal != null) return;
                    Bitmap[] g2 = new Bitmap[glowCols.Length];
                    for (int i = 0; i < glowCols.Length; i++) g2[i] = BakeGlow(48, 185, glowCols[i]);   // glow FUERTE por color
                    glowPal = g2;
                }
            }

            // Glow del MISMO COLOR que la estrella: elige el sprite pre-horneado mas cercano (sin matriz por estrella).
            private static Bitmap GlowFor(int r, int g, int b)
            {
                Bitmap[] gp = glowPal;
                if (gp == null) return null;
                int best = 0, bd = int.MaxValue;
                for (int i = 0; i < glowCols.Length; i++)
                {
                    int dr = r - glowCols[i].R, dg = g - glowCols[i].G, db = b - glowCols[i].B;
                    int d = dr * dr + dg * dg + db * db;
                    if (d < bd) { bd = d; best = i; }
                }
                return gp[best];
            }

            private static Bitmap BakeGlow(int size, int peakAlpha, Color color)
            {
                Bitmap bmp = new Bitmap(size, size, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(bmp))
                using (GraphicsPath gp = new GraphicsPath())
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    gp.AddEllipse(0, 0, size, size);
                    using (PathGradientBrush pgb = new PathGradientBrush(gp))
                    {
                        pgb.CenterPoint = new PointF(size / 2f, size / 2f);
                        pgb.CenterColor = Color.FromArgb(peakAlpha, color.R, color.G, color.B);   // nucleo del color de la estrella
                        pgb.SurroundColors = new Color[] { Color.FromArgb(0, color.R, color.G, color.B) };   // se desvanece a transparente
                        g.FillEllipse(pgb, 0, 0, size, size);
                    }
                }
                return bmp;
            }

            // LAS CUATRO RAYITAS CRUZADAS de las estrellas mas brillantes. No las hace la estrella: las hace
            // el diafragma de la camara, y son justo lo que hace que una foto del cielo parezca una foto.
            //
            // Las lleva un punado y nada mas -las que marca Ensure-, porque repartidas por todas el cielo
            // parece purpurina. Tres rombos encajados de menos a mas cortos y mas opacos: sale una raya que
            // se afila hacia fuera sin tener que degradar nada.
            private void DrawRayos(Graphics g, SolidBrush b, float px, float py, float R, Color col, float brillo, int kind)
            {
                // La MEDIANA lleva las rayitas mas cortas y bastante mas tenues que la grande. Esa diferencia
                // es la que evita el efecto purpurina: si todas las llevaran igual de marcadas, sesenta
                // estrellas con cruz serian sesenta chispas y no un cielo. Asi la mediana se lee como una
                // estrella pequena de verdad y la grande sigue mandando en la escena.
                float largo = R * ((kind == 2) ? 4.2f : 3.0f), ancho = R * 0.22f;
                int tope = (kind == 2) ? 120 : 62;
                for (int paso = 0; paso < 3; paso++)
                {
                    float L = largo * (1f - paso * 0.30f), A = ancho * (1f + paso * 1.1f);
                    int alfa = (int)((34 + paso * 26) * brillo); if (alfa > tope) alfa = tope; if (alfa < 1) continue;
                    b.Color = Color.FromArgb(alfa, col);
                    spk[0] = new PointF(px - L, py); spk[1] = new PointF(px, py - A); spk[2] = new PointF(px + L, py); spk[3] = new PointF(px, py + A);
                    g.FillPolygon(b, spk);
                    spk[0] = new PointF(px, py - L); spk[1] = new PointF(px + A, py); spk[2] = new PointF(px, py + L); spk[3] = new PointF(px - A, py);
                    g.FillPolygon(b, spk);
                }
            }
            // El NUCLEO: chiquito y tirando a blanco. Es lo que hace que una estrella "queme" en vez de
            // parecer una pelusa: el color vive en el halo, y el centro casi siempre se ve blanco.
            private void DrawNucleo(Graphics g, SolidBrush b, float px, float py, float R, int cr, int cg, int cb, int a)
            {
                int nr = cr + 70; if (nr > 255) nr = 255;
                int ng = cg + 70; if (ng > 255) ng = 255;
                int nb = cb + 70; if (nb > 255) nb = 255;
                b.Color = Color.FromArgb(a, nr, ng, nb);
                float d = R * 1.1f; if (d < 1.2f) d = 1.2f;
                g.FillEllipse(b, px - d * 0.5f, py - d * 0.5f, d, d);
            }

            // CUANTO HALO lleva cada estrella, y no es el mismo para todas. Las GRANDES son las
            // protagonistas del cielo y con el halo generoso se leen como luces de verdad en vez de como
            // pegatinas. A las MEDIANAS ese mismo halo las convertia en pompas: un disco borroso de quince
            // pixeles con un punto blanco dentro, que es justo lo que se veia mal. Ahora lo llevan apretado,
            // y lo que las hace estrella son sus rayitas, no el borron. (El polvo del fondo no lleva halo:
            // va como punto de un pixel y punto.) Los numeros salieron de dibujar el cielo y mirarlo.
            private static float HaloDe(int kind) { return (kind == 2) ? 1.15f : 0.60f; }

            private void Ensure(int w, int h)
            {
                int bucket = 0;   // patron FIJO: regenerarlo cada minuto obligaba a re-hornear ~120 estrellas (glow+destello) -> tiron periodico en la rocola
                if (stars != null && sw == w && sh == h && sBucket == bucket) return;
                sw = w; sh = h; sBucket = bucket;
                Random r = new Random((20260620 + bucket * 40503) & 0x7FFFFFFF);   // seed FIJO (bucket=0): el patron ya no rota por minuto (regenerarlo daba un tiron periodico)
                Random rFranja = new Random(0x5A5A3C3C);   // azar APARTE, solo para apartar estrellas de las franjas de texto (ver QuietBands)
                // CUANTAS. Cuatro veces mas que antes, y casi todas diminutas: un cielo de verdad tiene un
                // punado de estrellas fuertes y cientos que apenas se adivinan, y eso es lo que da sensacion
                // de fondo. No cuesta lo que parece: el POLVO -tres cuartas partes- se hornea UNA vez en el
                // cielo y no entra en las ocho capas de titileo (ver BakeStarFrame), asi que lo que se hornea
                // ocho veces sigue siendo mas o menos lo mismo que antes.
                int n = (int)(((double)(w * h) / 1700) * Density);
                int lo = (int)(300 * Density); if (lo < 60) lo = 60;
                if (n < lo) n = lo; if (n > 1400) n = 1400;

                // DE QUE COLOR ES UNA ESTRELLA. Las de verdad van de blanco-azulado a blanco, amarillo y
                // naranja: no hay estrellas verdes ni violetas, y la inmensa mayoria de las que se ven son
                // casi blancas. Con la paleta de rotulador de antes el cielo parecia confeti.
                Color[] palTemp = {
                    Color.FromArgb(155, 176, 255), Color.FromArgb(170, 191, 255),   // 0-1  azul-blanco (las mas calientes)
                    Color.FromArgb(202, 215, 255), Color.FromArgb(228, 235, 255),   // 2-3  blanco-azul
                    Color.FromArgb(248, 247, 255), Color.FromArgb(255, 255, 250),   // 4-5  blancas
                    Color.FromArgb(255, 244, 234), Color.FromArgb(255, 237, 205),   // 6-7  blanco-amarillo (como el Sol)
                    Color.FromArgb(255, 218, 165), Color.FromArgb(255, 199, 142),   // 8-9  naranjas
                    Color.FromArgb(255, 178, 128)                                    // 10   naranja hondo
                };

                stars = new Star[n];
                // DONDE SE PONEN.
                //
                // Un cielo de verdad no esta espolvoreado con regularidad de papel pintado: tiene grumos,
                // parejas y zonas mas vacias. Por eso una parte cae alrededor de unos pocos centros y el
                // resto suelta por cualquier sitio. Pero eso tenia DOS fallos, y los dos se veian, sobre
                // todo en pantalla ancha:
                //
                // 1) LAS HILERAS DE LOS BORDES. La que caia fuera de la pantalla se PEGABA al borde en vez
                //    de volver a tirarse. Como los grumos son campanas, muchas caian fuera... y acababan
                //    todas en la misma linea: medido, el 15% del cielo formaba cuatro hileras pegadas a los
                //    cantos. Ahora la que cae fuera se vuelve a tirar, y si tras varios intentos sigue
                //    fuera se pone suelta en cualquier sitio.
                //
                // 2) LOS GRUMOS ESTIRADOS. El tamano del grumo iba en fraccion de la pantalla, asi que en
                //    una pantalla ancha salia estirado a lo ancho: en 2560x1080 el cielo se repartia el
                //    doble de ancho que de alto, o sea bandas horizontales en vez de grumos. Ahora el radio
                //    se mide en PIXELES y el grumo sale redondo se ponga la pantalla como se ponga.
                //
                // Y ademas hay menos estrellas atadas a los grumos que antes, para que el cielo quede
                // repartido de forma pareja y los grumos se noten sin amontonar.
                int nc = 10 + r.Next(5);
                float[] ccx = new float[nc], ccy = new float[nc], ccr = new float[nc];
                for (int c = 0; c < nc; c++)
                {
                    // Los centros no se pegan al canto: un grumo con el centro en el borde deja media
                    // campana fuera y vuelve a amontonar todo en esa orilla.
                    ccx[c] = 0.10f + (float)r.NextDouble() * 0.80f;
                    ccy[c] = 0.10f + (float)r.NextDouble() * 0.80f;
                    ccr[c] = h * (0.10f + (float)r.NextDouble() * 0.14f);   // RADIO EN PIXELES
                }
                int grandes = 0;
                for (int i = 0; i < n; i++)
                {
                    Star s = new Star();
                    float px = 0f, py = 0f;
                    for (int intento = 0; ; intento++)
                    {
                        if (intento < 6 && r.Next(100) < 25)
                        {
                            int c = r.Next(nc);
                            // El mismo radio en pixeles en los dos ejes -> el grumo sale redondo.
                            px = ccx[c] + Gauss(r) * ccr[c] / w;
                            py = ccy[c] + Gauss(r) * ccr[c] / h;
                        }
                        else { px = (float)r.NextDouble(); py = (float)r.NextDouble(); }
                        if (px >= 0.004f && px <= 0.996f && py >= 0.004f && py <= 0.996f) break;
                    }
                    // Si cayo detras de una de las dos franjas de texto, se vuelve a tirar CON EL AZAR DE AL
                    // LADO, que no corre la fila del azar principal (ver QuietBands).
                    if (QuietBands && EnFranja(py))
                    {
                        for (int t = 0; t < TirosFranja; t++)
                        {
                            float nx = (float)rFranja.NextDouble(), ny = (float)rFranja.NextDouble();
                            if (nx < 0.004f || nx > 0.996f || ny < 0.004f || ny > 0.996f) continue;
                            px = nx; py = ny;
                            if (!EnFranja(py)) break;
                        }
                    }
                    s.X = px; s.Y = py;

                    // LO BRILLANTE QUE ES, con una curva bien inclinada: casi todas debilisimas, unas pocas
                    // fuertes. De aqui salen el tamano, el brillo y a que grupo va (polvo / mediana / grande).
                    double m = Math.Pow(r.NextDouble(), 4.6);
                    // DE QUE GRUPO ES. El corte de las medianas sube de 0.34 a 0.55: antes una de cada seis
                    // estrellas era "mediana" -unas noventa en pantalla- y eran justo las que se veian como
                    // pompas. Ahora son la mitad, y las que dejan de serlo pasan a ser polvo de un pixel,
                    // que es como se ve de verdad la inmensa mayoria del cielo.
                    s.Kind = (m > 0.80) ? 2 : (m > 0.55) ? 1 : 0;
                    // Y la mediana ademas ENCOGE (era 4-5, ahora 3): lo que la hace estrella son sus
                    // rayitas, no su bulto. El polvo se queda en un pixel clavado.
                    s.Size = (s.Kind == 2) ? (5 + (int)(m * 4)) : (s.Kind == 1) ? 3 : 1;
                    // TODA la que se vea lleva rayitas. Antes las llevaban diez o doce y las otras noventa se
                    // quedaban de bola redonda: una bola redonda solo pasa por estrella si es diminuta, y
                    // esas no lo eran. Con las rayitas escaladas por tamano (ver DrawRayos) el cielo entero
                    // se lee como estrellas en vez de como puntos gordos.
                    s.Rayos = (s.Kind != 0);
                    // El suelo del brillo no puede ser tan bajo: con 0.16 la mitad del cielo quedaba en alfa
                    // 40 sobre un punto de un pixel, o sea invisible, y el cielo se veia mas vacio que antes
                    // teniendo el doble de estrellas.
                    float bri = (float)(0.26 + m * 0.74);
                    s.Bri = (byte)(bri * 255f);
                    if (s.Kind == 2) grandes++;
                    // A QUE FRECUENCIA late: las grandes con los graves (bombo), las medianas entre medios y
                    // agudos. El polvo no late (ni reacciona ni titila: vive horneado en el cielo).
                    s.Band = (s.Kind == 2) ? (byte)0 : (byte)(1 + r.Next(2));

                    // El color por temperatura, con la curva de siempre: casi todas blancas. Y una parte del
                    // polvo se tine hacia el genero que suena, que es lo que ata el cielo con la musica.
                    int q = r.Next(100);
                    int idx = (q < 14) ? r.Next(2) : (q < 34) ? 2 + r.Next(2) : (q < 68) ? 4 + r.Next(2)
                            : (q < 88) ? 6 + r.Next(2) : (q < 97) ? 8 + r.Next(2) : 10;
                    Color ct = palTemp[idx];
                    s.R = ct.R; s.G = ct.G; s.B = ct.B; s.Tint = 0f;
                    if (!Varied && s.Kind == 0 && r.Next(100) < 22)
                    { s.R = 255; s.G = 255; s.B = 255; s.Tint = 0.45f + (float)r.NextDouble() * 0.55f; }

                    s.Off = (float)(r.NextDouble() * Math.PI * 2);
                    s.Spd = 0.6f + (float)r.NextDouble() * 1.6f;   // titileo LENTO
                    stars[i] = s;
                }
                if (sb == null) sb = new SolidBrush(Color.White);
                if (sp == null) sp = new Pen(Color.White, 2.2f);
            }

            // Un numero al azar con forma de campana (Box-Muller): sirve para que las estrellas caigan
            // ALREDEDOR de un centro, apinandose cerca y ralas lejos, que es como se agrupan de verdad.
            private static float Gauss(Random r)
            {
                double u1 = 1.0 - r.NextDouble(), u2 = r.NextDouble();
                return (float)(Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2));
            }

            // Patron FIJO (sin fundido): el campo de estrellas ya no cambia cada minuto. Antes el fundido +
            // la regeneracion provocaban un tiron periodico (re-hornear ~120 estrellas) y 3s de repintados
            // extra por minuto, costoso en el CPU lento de la rocola. Se mantiene 1 (sin atenuar) siempre.
            private static float StarFade() { return 1f; }

            public void Draw(Graphics g, int w, int h, Color skyTop, Color skyBottom, Color tint, double phase, bool shooting, float pulse)
            {
                if (w < 4 || h < 4) return;
                Ensure(w, h);
                int now = Environment.TickCount;
                int dt = now - lastBuild;
                bool needNew = cache == null || cw != w || ch != h;
                // En repintados PARCIALES (p.ej. solo la casilla del cubo que gira encima) NO reconstruimos
                // el cuadro entero: basta copiar el cache. Asi el +framerate (~24fps) no desperdicia CPU
                // redibujando ~120 estrellas para una franja minima; el fondo completo se refresca en los
                // repintados completos (cuando el recorte cubre toda la vista: buscador y atraccion cada cuadro).
                RectangleF clip = g.ClipBounds;
                bool partial = !needNew && (clip.Width < w - 1 || clip.Height < h - 1);
                bool rebuild = needNew
                    || (!partial && (cSky != skyTop.ToArgb() || cSky2 != skyBottom.ToArgb() || cTint != tint.ToArgb() || dt >= RefrescoMs || dt < 0));
                if (rebuild)
                {
                    if (needNew)
                    {
                        if (cache != null) cache.Dispose();
                        cache = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                        cw = w; ch = h;
                    }
                    using (Graphics cg = Graphics.FromImage(cache))
                        RenderInto(cg, w, h, skyTop, skyBottom, tint, phase, pulse);
                    cSky = skyTop.ToArgb(); cSky2 = skyBottom.ToArgb(); cTint = tint.ToArgb(); lastBuild = now;
                }
                g.DrawImageUnscaled(cache, 0, 0);
                // LAS FUGACES VAN AQUI, EN VIVO, no dentro de lo que se hornea. Una fugaz cruza la pantalla en
                // un segundo: si viajara dentro del horneado avanzaria a saltos, uno por cada vez que se rehace
                // el cielo. Fuera, va fluida aunque el cielo se rehaga de tarde en tarde, que es justo lo que
                // permite rehacerlo de tarde en tarde. (Es la misma division que usa DrawReactive.)
                if (shooting) DrawShoots(g, w, h);
            }

            // CADA CUANTO SE REHACE EL CIELO cuando se dibuja en vivo (o sea, en la pantalla de atraccion:
            // el resto del programa copia capas ya horneadas). Rehacerlo es dibujar las seiscientas estrellas
            // una a una, y a 24 veces por segundo eso era la mayor parte del gasto de la pantalla que MAS
            // tiempo pasa encendida en un bar: la de reposo. Lo unico que se pierde rehaciendolo menos a
            // menudo es que las estrellas titilan mas despacio, y 200 ms es exactamente el ritmo al que
            // titilan en todo el resto del programa (ver CurrentStarLayerIndex), asi que ademas va parejo.
            public int RefrescoMs = 40;

            // Dibuja un cuadro completo del starfield (cielo + estrellas + fugaces) sobre el bitmap cache.
            private void RenderInto(Graphics g, int w, int h, Color skyTop, Color skyBottom, Color tint, double phase, float pulse)
            {
                EnsureSkyBrush(w, h, skyTop, skyBottom);
                g.FillRectangle(skyBrush, 0, 0, w, h);
                pulse *= Dim;                       // atenuado mientras se navega: el beat tambien baja
                double boost = pulse * 0.62;        // el audio sube el brillo de las estrellas (medianas/grandes)
                int armUp = (int)(pulse * 7.0);     // y agranda las puntas del destello con el beat
                float fade = StarFade() * Dim;      // fundido out/in del patron (cada minuto) x atenuacion al navegar
                EnsureGlow();                       // ESTETICA: sprites de resplandor (horneados una vez)
                g.InterpolationMode = InterpolationMode.Bilinear;
                g.SmoothingMode = SmoothingMode.AntiAlias;   // ESTETICA: el sparkle se ve liso (una sola pieza)
                float gfade = fade < 0f ? 0f : (fade > 1f ? 1f : fade);   // el glow encoge a 0 en el parpadeo del patron (sync con los nucleos)
                UpdateDrift(w, h, pulse);           // deriva con la musica (RenderInto solo corre en reconstruccion completa, ~24fps)
                int dx = (int)driftX, dy = (int)driftY;
                for (int i = 0; i < stars.Length; i++)
                {
                    Star s = stars[i];
                    bool reactive = (s.Kind != 0);   // BEAT (audio) + glow SOLO en medianas (1) y grandes (2); los puntos NO
                    double tw = (0.70 + 0.42 * (0.5 + 0.5 * Math.Sin(phase * s.Spd + s.Off)) + (reactive ? boost : 0.0)) * fade;
                    int a = (int)(tw * s.Bri); if (a > 255) a = 255; if (a < 0) a = 0;
                    int cr, cg, cb;
                    if (s.Tint > 0f) { cr = (int)(255 + (tint.R - 255) * s.Tint); cg = (int)(255 + (tint.G - 255) * s.Tint); cb = (int)(255 + (tint.B - 255) * s.Tint); }
                    else { cr = s.R; cg = s.G; cb = s.B; }
                    int px = (int)(s.X * w) + dx; if (px >= w) px -= w;   // + deriva con la musica (envuelve)
                    int py = (int)(s.Y * h) + dy; if (py >= h) py -= h;
                    // UN PUNTO DE LUZ: halo del mismo color detras y un nucleo chiquito tirando a blanco. El
                    // beat agranda el halo solo en medianas/grandes; el polvo va como punto fijo, sin halo.
                    float bri = s.Bri / 255f;
                    if (reactive)
                    {
                        int gd = (int)((s.Size * 3 + 6 + (int)(pulse * 10)) * gfade * HaloDe(s.Kind));   // el beat agranda el glow y el fundido lo encoge
                        Bitmap gb = GlowFor(cr, cg, cb);
                        if (gb != null && gd > 0) g.DrawImage(gb, new Rectangle(px - gd / 2, py - gd / 2, gd, gd));
                        if (s.Rayos) DrawRayos(g, sb, px, py, s.Size + armUp, Color.FromArgb(cr, cg, cb), bri * (float)tw, s.Kind);
                        DrawNucleo(g, sb, px, py, s.Size, cr, cg, cb, a);
                    }
                    else { sb.Color = Color.FromArgb(a, cr, cg, cb); float ds = s.Size < 1 ? 1 : s.Size; g.FillEllipse(sb, px - ds / 2f, py - ds / 2f, ds, ds); }
                }
            }

            // Fondo del formulario (franjas): cielo cacheado + estrellas TITILANTES por cuadros horneados.
            public void DrawCached(Graphics g, int w, int h, Color skyTop, Color skyBottom)
            {
                if (w < 4 || h < 4) return;
                EnsureLayers(w, h);          // arma el patron de estrellas: el cielo necesita el polvo ya repartido
                EnsureSkyCache(w, h, skyTop, skyBottom);
                BlitSkyAndStars(g, w, h);
            }

            // LA NEBLINA DE LA VIA LACTEA Y LAS NEBULOSAS.
            //
            // Son manchas grandes y muy suaves, o sea justo lo que se puede dibujar CHIQUITO y estirar sin
            // que se note: se hornean a un CUARTO de tamano (en 1024x768, 256x192 = 190 KB cada una) y se
            // estiran al copiarlas. Dibujarlas a tamano real serian trescientas manchas de gradiente radial
            // en cada cambio de cancion; asi son doscientas manchas UNA vez, al arrancar, y luego una copia.
            private Bitmap hazeMask, nebMask;
            private int nblW = -1, nblH = -1;
            private void EnsureNieblas(int FW, int FH)
            {
                int mw = FW / 4, mh = FH / 4;
                if (mw < 8) mw = 8; if (mh < 8) mh = 8;
                if (hazeMask != null && nblW == mw && nblH == mh) return;
                if (hazeMask != null) { hazeMask.Dispose(); hazeMask = null; }
                if (nebMask != null) { nebMask.Dispose(); nebMask = null; }
                nblW = mw; nblH = mh;
                Random r = new Random(20260620);   // fijo: la misma via lactea siempre, no una distinta por arranque

                hazeMask = new Bitmap(mw, mh, PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(hazeMask))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    // La banda cruza en diagonal, de abajo-izquierda a arriba-derecha, y se hace de muchas
                    // manchas tenues encimadas: asi tiene grumos y bordes irregulares en vez de ser una franja.
                    float x0 = -mw * 0.08f, y0 = mh * 0.86f, x1 = mw * 1.08f, y1 = mh * 0.06f;
                    for (int i = 0; i < 240; i++)
                    {
                        float t = (float)r.NextDouble();
                        float ancho = mh * (0.075f + 0.045f * (float)Math.Sin(t * 3.1));
                        float x = x0 + (x1 - x0) * t + Gauss(r) * ancho * 0.55f;
                        float y = y0 + (y1 - y0) * t + Gauss(r) * ancho;
                        // Y SE APAGA HACIA ABAJO. Abajo del todo el cielo lleva el resplandor del horizonte,
                        // y una neblina blanca encima de el no se lee como via lactea: se lee como una mancha
                        // gris. Ademas es lo que pasa de verdad, que las luces del pueblo se la comen.
                        float fy = 1f - y / mh; if (fy < 0f) fy = 0f; if (fy > 1f) fy = 1f;
                        int al = (int)(6f * (0.10f + 0.90f * fy * fy)); if (al < 1) continue;
                        Mancha(g, x, y, mh * (0.05f + (float)r.NextDouble() * 0.10f), Color.FromArgb(214, 226, 255), al);
                    }
                    // Y las VETAS DE POLVO que la cruzan: en el cielo de verdad son nubes que tapan lo de
                    // detras, y son las que hacen que la via lactea se lea como algo con volumen.
                    for (int i = 0; i < 24; i++)
                    {
                        float t = (float)r.NextDouble();
                        float x = x0 + (x1 - x0) * t + Gauss(r) * mh * 0.05f;
                        float y = y0 + (y1 - y0) * t + Gauss(r) * mh * 0.055f;
                        Mancha(g, x, y, mh * (0.04f + (float)r.NextDouble() * 0.085f), Color.FromArgb(8, 10, 26), 34);
                    }
                }

                nebMask = new Bitmap(mw, mh, PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(nebMask))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    // Van en la MITAD DE ARRIBA del cielo a proposito: abajo el degradado ya lleva el
                    // resplandor del genero, y una nebulosa del mismo color encima de el no se lee como una
                    // nebulosa, se lee como suciedad.
                    for (int k = 0; k < 3; k++)
                    {
                        float cx = mw * (0.14f + (float)r.NextDouble() * 0.72f);
                        float cy = mh * (0.10f + (float)r.NextDouble() * 0.42f);
                        for (int i = 0; i < 20; i++)
                            Mancha(g, cx + Gauss(r) * mw * 0.075f, cy + Gauss(r) * mh * 0.08f,
                                   mh * (0.07f + (float)r.NextDouble() * 0.14f), Color.White, 4);
                        Mancha(g, cx, cy, mh * 0.07f, Color.White, 7);   // el corazon, un pelin mas encendido
                    }
                }
            }

            // Una mancha de luz redonda que se desvanece hacia fuera: la pieza con la que estan hechas la
            // neblina y las nebulosas.
            private static void Mancha(Graphics g, float cx, float cy, float rad, Color c, int alfaCentro)
            {
                if (rad < 1f) rad = 1f;
                using (GraphicsPath gp = new GraphicsPath())
                {
                    gp.AddEllipse(cx - rad, cy - rad, rad * 2, rad * 2);
                    using (PathGradientBrush pgb = new PathGradientBrush(gp))
                    {
                        pgb.CenterPoint = new PointF(cx, cy);
                        pgb.CenterColor = Color.FromArgb(alfaCentro, c);
                        pgb.SurroundColors = new Color[] { Color.FromArgb(0, c) };
                        g.FillEllipse(pgb, cx - rad, cy - rad, rad * 2, rad * 2);
                    }
                }
            }

            // Hornea el cielo (degradado) al tamano de la PANTALLA COMPLETA (FullW x FullH) y lo reutiliza. Cada
            // fondo copia solo su ventana (en BlitSkyAndStars, con offset), asi el degradado es CONTINUO entre las
            // secciones sin costuras. Copiar un bitmap es mas barato que rellenar un degradado de 3 paradas por
            // cuadro (clave en alta resolucion). Se re-hornea solo al cambiar tamano de pantalla o colores (genero).
            private int saltados;   // cuantos cuadros seguidos se ha dejado el cielo como estaba (ver abajo)
            private void EnsureSkyCache(int w, int h, Color top, Color bottom)
            {
                int FW = FullW(w), FH = FullH(h);
                Color mid = (SkyMid.A == 0)
                    ? Color.FromArgb(255, (top.R + bottom.R) / 2, (top.G + bottom.G) / 2, (top.B + bottom.B) / 2)   // sin mid: punto medio
                    : SkyMid;
                Color acento = Acento;
                // El acento entra en la firma: si no, al cambiar de genero el cielo no se re-hornearia y las
                // nebulosas se quedarian del color de la cancion anterior.
                int t = top.ToArgb(), m = mid.ToArgb(), b = bottom.ToArgb() ^ (acento.A == 0 ? 0 : acento.ToArgb() * 31);
                if (skyCache != null && scW == FW && scH == FH && fscTop == t && fscMid == m && fscBot == b) { saltados = 0; return; }
                // EL CIELO NO SE REHORNEA EN CADA CUADRO DEL DESLIZAMIENTO.
                //
                // Al cambiar de cancion, el color del genero se desliza del anterior al nuevo en unos
                // veinticinco cuadros. Cada uno es un color distinto, y con un color distinto habia que
                // rehornear el cielo ENTERO -el degradado a pantalla completa, la via lactea y las nebulosas
                // estiradas desde su dibujo pequeno, y el polvo-. Eso son 6 ms a 1024x768, 16 a 1920x1080 y
                // 27 a 2560x1440... por cuadro. En pantalla grande, cada cambio de cancion pedia casi medio
                // segundo de trabajo de mas justo cuando la rocola tiene que arrancar la cancion siguiente.
                //
                // Se rehornea uno de cada cuatro. Durante ese segundo el FONDO se desliza a saltitos de
                // cuatro cuadros -en un degradado liso y oscuro no se nota- y todo lo demas (pastillas,
                // bordes, letreros) sigue deslizandose cuadro a cuadro. Y lo importante: NO se redondea
                // ningun color. En cuanto el deslizamiento para, el siguiente horneado es con el color
                // EXACTO, asi que el cielo acaba siendo exactamente el que le toca a esa cancion.
                // (Se probo redondear el color a escalones en vez de esto: se veia. El degradado lleva
                // colores muy oscuros y ahi un escalon de nada es un cambio grande en proporcion.)
                if (skyCache != null && scW == FW && scH == FH && saltados < 3) { saltados++; return; }
                saltados = 0;
                if (skyCache == null || scW != FW || scH != FH)
                {
                    if (skyCache != null) skyCache.Dispose();
                    skyCache = new Bitmap(FW, FH, PixelFormat.Format32bppPArgb);
                    scW = FW; scH = FH;
                }
                EnsureNieblas(FW, FH);
                using (Graphics sg = Graphics.FromImage(skyCache))
                {
                    using (LinearGradientBrush lgb = new LinearGradientBrush(new Rectangle(0, 0, FW, FH + 1), top, bottom, LinearGradientMode.Vertical))
                    {
                        ColorBlend cb = new ColorBlend(3);
                        cb.Colors = new Color[] { top, mid, bottom };          // negro arriba -> azul noche en medio -> resplandor/genero abajo
                        cb.Positions = new float[] { 0f, 0.42f, 1f };          // negro SOLO en el cenit; el azul domina casi toda la pantalla
                        lgb.InterpolationColors = cb;
                        sg.FillRectangle(lgb, 0, 0, FW, FH);
                    }
                    sg.InterpolationMode = InterpolationMode.Bilinear;
                    // LAS NEBULOSAS, del color de lo que suena. Su dibujo esta horneado en blanco a un cuarto
                    // de tamano y aqui solo se estira y se tine con una matriz de color: al cambiar de cancion
                    // esto es UNA copia, no volver a dibujar ochenta manchas.
                    if (nebMask != null)
                    {
                        // Con el color del GENERO, no con el suelo del degradado: ese es un marron oscuro ya
                        // mezclado con el cielo, y tenir con el solo ensuciaba.
                        // Y el color se lleva a medias con un violeta azulado. El del genero a secas es
                        // demasiado terroso para una nebulosa; mezclado, se sigue notando de que color va la
                        // cancion pero parece cielo.
                        Color a0 = (acento.A == 0) ? bottom : acento;
                        Color acc = Color.FromArgb((a0.R + 140) / 2, (a0.G + 120) / 2, (a0.B + 255) / 2);
                        using (ImageAttributes ia = new ImageAttributes())
                        {
                            ColorMatrix cm = new ColorMatrix();
                            cm.Matrix00 = acc.R / 255f; cm.Matrix11 = acc.G / 255f; cm.Matrix22 = acc.B / 255f;
                            ia.SetColorMatrix(cm);
                            sg.DrawImage(nebMask, new Rectangle(0, 0, FW, FH), 0, 0, nebMask.Width, nebMask.Height, GraphicsUnit.Pixel, ia);
                        }
                    }
                    // LA VIA LACTEA: la banda de neblina, tambien horneada a un cuarto y estirada. Va del
                    // mismo blanco azulado siempre, que es de lo que esta hecha de verdad.
                    if (hazeMask != null) sg.DrawImage(hazeMask, new Rectangle(0, 0, FW, FH));
                    // EL POLVO YA NO VA AQUI: ver BakeStarFrame. Horneado en el cielo se quedaba clavado
                    // mientras el resto del campo se desliza, y eso -mas de la mitad de las estrellas quietas
                    // y el resto moviendose- se ve peor que si no se moviera nada.
                }
                fscTop = t; fscMid = m; fscBot = b;
            }

            // Pinta la VENTANA de este fondo dentro del campo de PANTALLA COMPLETA: cielo OPACO por copia directa
            // (SourceCopy, rapido) + la capa de estrellas del cuadro de titileo ACTUAL encima (SourceOver). Ambos
            // bitmaps son de pantalla completa; se dibujan corridos por (-SkyOffsetX, -SkyOffsetY) y el recorte del
            // pintor deja ver solo su seccion. Como todas las secciones leen el MISMO bitmap a la MISMA posicion de
            // pantalla, las estrellas cruzan los bordes sin cortarse ni desalinearse (todo es UNA SOLA PIEZA).
            // 'advance'=false (repintado PARCIAL: la casilla del cubo que gira) reusa la capa del ultimo repintado
            // completo: si avanzara por reloj, la casilla mostraria un cuadro de titileo distinto al del resto.
            private int shownLayer = -1;   // capa mostrada en el ultimo repintado completo
            private void BlitSkyAndStars(Graphics g, int w, int h) { BlitSkyAndStars(g, w, h, true); }
            private void BlitSkyAndStars(Graphics g, int w, int h, bool advance)
            {
                int offX = SkyOffsetX, offY = SkyOffsetY;
                CompositingMode ocm = g.CompositingMode;
                g.CompositingMode = CompositingMode.SourceCopy;   // cielo opaco: copia directa (sin mezclar alfa)
                g.DrawImageUnscaled(skyCache, -offX, -offY);      // la ventana [offX,offY] cae en (0,0); el recorte del pintor limita el area
                g.CompositingMode = CompositingMode.SourceOver;   // estrellas con transparencia encima
                if (advance || shownLayer < 0 || layers == null || shownLayer >= layers.Length) shownLayer = CurrentStarLayerIndex();
                Bitmap sl = (layers != null && shownLayer >= 0 && shownLayer < layers.Length) ? layers[shownLayer] : null;
                if (sl != null) BlitEstrellas(g, sl, w, h, offX, offY);
                g.CompositingMode = ocm;
            }

            // LAS ESTRELLAS, CORRIDAS POR LA DERIVA Y ENVOLVIENDO POR LOS BORDES.
            //
            // El campo de estrellas esta horneado al tamano de la pantalla completa y cada vista copia SU ventana.
            // Al sonar musica el campo entero se desliza despacio en diagonal, asi que la ventana que hay que
            // copiar se corre con el; cuando esa ventana se sale por un borde, lo que falta se toma del otro
            // lado, que es lo que hace que el campo parezca infinito y no tenga principio ni final.
            //
            // Se copian los MISMOS pixeles que antes -como mucho en cuatro trozos en vez de uno, y solo cuando
            // la ventana cae justo encima de la costura-, asi que no cuesta mas que antes.
            private void BlitEstrellas(Graphics g, Bitmap sl, int w, int h, int offX, int offY)
            {
                int FW = sl.Width, FH = sl.Height;
                if (FW < 1 || FH < 1) return;
                int sx = (int)((offX - (int)driftX) % FW); if (sx < 0) sx += FW;
                int sy = (int)((offY - (int)driftY) % FH); if (sy < 0) sy += FH;
                int w1 = FW - sx; if (w1 > w) w1 = w;
                int h1 = FH - sy; if (h1 > h) h1 = h;
                if (Dim < 0.985f) sl = CapaAtenuada(sl);   // atenuado mientras se navega con musica: ver abajo
                Trozo(g, sl, 0, 0, w1, h1, sx, sy);
                if (w1 < w) Trozo(g, sl, w1, 0, w - w1, h1, 0, sy);
                if (h1 < h) Trozo(g, sl, 0, h1, w1, h - h1, sx, 0);
                if (w1 < w && h1 < h) Trozo(g, sl, w1, h1, w - w1, h - h1, 0, 0);
            }
            private void Trozo(Graphics g, Bitmap sl, int dx, int dy, int dw, int dh, int sx, int sy)
            {
                if (dw < 1 || dh < 1) return;
                g.DrawImage(sl, new Rectangle(dx, dy, dw, dh), sx, sy, dw, dh, GraphicsUnit.Pixel);
            }

            // LA COPIA ATENUADA, HORNEADA APARTE.
            //
            // Mientras alguien esta eligiendo cancion con musica sonando, el fondo se atenua para que no le
            // pelee a las portadas. Atenuar AL PEGAR obliga a la libreria de dibujo a pasar por CADA pixel
            // aplicando una matriz de color, y eso cuesta VEINTE VECES lo que copiar la capa tal cual: 5.24 ms
            // contra 0.27 en 1024x768. O sea que la rocola se ponia veinte veces mas pesada justo en el momento
            // en que tiene que ir mas suelta, y en la maquina del bar eso es medio nucleo tirado.
            //
            // La capa de titileo solo cambia cinco veces por segundo y la atenuacion se queda quieta en cuanto
            // termina de bajar, asi que la copia atenuada se hornea UNA vez y se reusa en los cuadros que vienen
            // detras. Se ve exactamente igual: es la misma cuenta, hecha una vez en vez de veinticuatro.
            private Bitmap capaAtenuada; private Bitmap capaAtenuadaDe; private int capaAtenuadaKey = -1;
            private Bitmap CapaAtenuada(Bitmap sl)
            {
                int key = (int)(Dim * 50f);   // mismos escalones que la matriz: no se rehace por un pelo de nada
                if (capaAtenuada != null && capaAtenuadaDe == sl && capaAtenuadaKey == key
                    && capaAtenuada.Width == sl.Width && capaAtenuada.Height == sl.Height) return capaAtenuada;
                if (capaAtenuada == null || capaAtenuada.Width != sl.Width || capaAtenuada.Height != sl.Height)
                {
                    if (capaAtenuada != null) capaAtenuada.Dispose();
                    capaAtenuada = new Bitmap(sl.Width, sl.Height, PixelFormat.Format32bppPArgb);
                }
                EnsureDimIA();
                using (Graphics cg = Graphics.FromImage(capaAtenuada))
                {
                    cg.CompositingMode = CompositingMode.SourceCopy;   // copia exacta, sin mezclar con lo que hubiera
                    cg.DrawImage(sl, new Rectangle(0, 0, sl.Width, sl.Height), 0, 0, sl.Width, sl.Height, GraphicsUnit.Pixel, dimIA);
                }
                capaAtenuadaDe = sl; capaAtenuadaKey = key;
                return capaAtenuada;
            }

            // Atributos de imagen con el alfa de la atenuacion (cacheados; la matriz se rehace solo si Dim cambio de escalon)
            private ImageAttributes dimIA; private int dimIAKey = -1;
            private void EnsureDimIA()
            {
                int key = (int)(Dim * 50f);   // escalones de 0.02: sin rehacer la matriz cada cuadro durante la transicion
                if (dimIA != null && dimIAKey == key) return;
                if (dimIA == null) dimIA = new ImageAttributes();
                ColorMatrix cm = new ColorMatrix(); cm.Matrix33 = Dim;
                dimIA.SetColorMatrix(cm, ColorMatrixFlag.Default, ColorAdjustType.Bitmap);
                dimIAKey = key;
            }

            // Indice del cuadro de titileo segun el reloj (rota ~5 veces/seg). Los armonicos son ENTEROS, asi
            // que el set entero cicla y el titileo se repite suave y continuo, sin recalcular nada por cuadro.
            private int CurrentStarLayerIndex()
            {
                if (layers == null || layers.Length == 0) return -1;
                int idx = (Environment.TickCount / 200) % layers.Length;
                if (idx < 0) idx += layers.Length;
                return idx;
            }

            // Vista de discos (VENTANA del campo COMPARTIDO de pantalla completa): cielo cacheado + estrellas
            // titilantes + LATIDO con la musica. El cielo y las estrellas salen del MISMO bitmap de pantalla
            // completa que pinta el fondo del form, corridos por (SkyOffsetX/Y): por eso las estrellas cruzan
            // los bordes de las secciones sin costura. El latido y las fugaces solo en repintado COMPLETO (en el
            // parcial de la casilla del cubo se reusa la capa: no relatir ni relanzar fugaces por una franja).
            // pLo/pMid/pHi = pulso de graves/medios/agudos (0..1). Cada estrella late con SU banda (ver DrawBeatFlare).
            public void DrawReactive(Graphics g, int w, int h, Color skyTop, Color skyBottom, float pLo, float pMid, float pHi)
            {
                if (w < 4 || h < 4) return;
                EnsureLayers(w, h);          // arma el patron de estrellas: el cielo necesita el polvo ya repartido
                EnsureSkyCache(w, h, skyTop, skyBottom);
                RectangleF clip = g.ClipBounds;
                bool full = (clip.Width >= w - 1 && clip.Height >= h - 1);   // repintado COMPLETO (no la casilla del cubo)
                BlitSkyAndStars(g, w, h, full);
                float pMax = Math.Max(pLo, Math.Max(pMid, pHi));
                // EL LATIDO, TAMBIEN EN LOS REPINTADOS PARCIALES. Antes solo se dibujaba en los completos, y
                // eso significaba que el trozo repintado -la casilla del cubo que gira, y ahora la casilla que
                // se elige- se quedaba SIN los halos de las estrellas hasta el siguiente cuadro completo: los
                // halos parpadeaban ahi dentro. Cuesta casi nada porque DrawBeatFlare descarta de un vistazo
                // las estrellas que caen fuera del recorte, y en un repintado parcial son casi todas.
                if (pMax * Dim > 0.04f) DrawBeatFlare(g, w, h, pLo * Dim, pMid * Dim, pHi * Dim);   // latido por banda (atenuado al navegar)
                if (full) DrawShoots(g, w, h);
            }

            // LATIDO con la musica: a las estrellas medianas/grandes (las que llevan glow) les estampa un glow
            // EXTRA que crece con la energia del audio. Es barato: ~40 sprites pre-horneados, no recalculo ni
            // pasada de pantalla completa. Del MISMO color (sprite por color). Solo en repintado completo. Las
            // estrellas se posicionan en coordenadas de PANTALLA COMPLETA menos el offset de la ventana; las que
            // caen fuera se saltan (el resto las recorta el clip del pintor).
            // Cada estrella late con SU banda (grandes=graves, medianas=medios/agudos): recibe los 3 pulsos y usa el
            // de su Band. Las estrellas cuya banda NO esta sonando no reciben halo -> se VE la separacion de beats.
            private void DrawBeatFlare(Graphics g, int w, int h, float pLo, float pMid, float pHi)
            {
                if (stars == null) return;
                int FW = FullW(w), FH = FullH(h), offX = SkyOffsetX, offY = SkyOffsetY;
                // Se mira contra el RECORTE, no contra la ventana entera: en un repintado parcial eso descarta
                // casi las seiscientas estrellas con una resta, sin llegar a dibujar nada.
                RectangleF rec = g.ClipBounds;
                for (int i = 0; i < stars.Length; i++)
                {
                    Star s = stars[i];
                    if (s.Kind == 0) continue;   // los puntos no reaccionan
                    float pulse = (s.Band == 0) ? pLo : (s.Band == 1) ? pMid : pHi;   // el pulso de SU frecuencia
                    if (pulse <= 0.02f) continue;   // su banda no suena ahora: sin halo (asi se nota la separacion)
                    int gd = s.Size * 2 + 4 + (int)(pulse * 16f);   // el halo crece con el golpe de su banda
                    int px = (int)(s.X * FW) + (int)driftX - offX; if (px >= FW) px -= FW;   // la estrella se movio: su halo con ella
                    int py = (int)(s.Y * FH) + (int)driftY - offY; if (py >= FH) py -= FH;
                    if (px + gd < rec.Left || px - gd > rec.Right || py + gd < rec.Top || py - gd > rec.Bottom) continue;   // fuera del recorte: se salta
                    int cr, cg, cb;
                    if (s.Tint > 0f) { cr = 255; cg = 255; cb = 255; } else { cr = s.R; cg = s.G; cb = s.B; }
                    Bitmap gb = GlowFor(cr, cg, cb);
                    if (gb == null) continue;
                    g.DrawImage(gb, new Rectangle(px - gd / 2, py - gd / 2, gd, gd));
                }
            }

            // Hornea los TwK cuadros de titileo UNA vez (al arrancar / al cambiar de tamano de PANTALLA). Se hornean
            // al tamano de la pantalla COMPLETA (FullW x FullH), no al de la ventana: asi un solo juego de capas
            // sirve a todas las secciones (fondo del form, rejilla, interior del disco) y cada una copia su ventana.
            // El patron es fijo; lo unico que cambia entre cuadros es el brillo de cada estrella -> al rotarlos titila.
            private void EnsureLayers(int w, int h)
            {
                int FW = FullW(w), FH = FullH(h);
                Ensure(FW, FH);
                if (layers != null && lw == FW && lh == FH && lBucket == sBucket) return;
                if (layers != null) { for (int k = 0; k < layers.Length; k++) if (layers[k] != null) layers[k].Dispose(); }
                if (capaAtenuada != null) { capaAtenuada.Dispose(); capaAtenuada = null; }   // apuntaba a una capa que ya no existe
                capaAtenuadaDe = null; capaAtenuadaKey = -1;
                layers = new Bitmap[TwK];
                lw = FW; lh = FH; lBucket = sBucket;
                EnsureGlow();
                for (int j = 0; j < TwK; j++) layers[j] = BakeStarFrame(FW, FH, j);
            }

            // Un cuadro de titileo: el patron con el brillo de cada estrella en la fase j (armonicos enteros
            // -> el set cicla exacto). Solo se ejecuta al hornear, no por cuadro, asi que puede ser detallado.
            private Bitmap BakeStarFrame(int w, int h, int j)
            {
                Bitmap bmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                using (Graphics lg = Graphics.FromImage(bmp))
                using (SolidBrush b = new SolidBrush(Color.White))
                {
                    lg.Clear(Color.Transparent);
                    lg.InterpolationMode = InterpolationMode.Bilinear;
                    lg.SmoothingMode = SmoothingMode.AntiAlias;
                    double ph = 2.0 * Math.PI * j / TwK;   // fase de este cuadro
                    for (int i = 0; i < stars.Length; i++)
                    {
                        Star s = stars[i];
                        // EL POLVO SI ENTRA AQUI, y antes no. Vivia horneado en el bitmap del cielo -una sola
                        // vez en vez de ocho- pero el cielo no se desliza: se queda pegado a la pantalla. Con la
                        // deriva andando, eso dejaba mas de la mitad de las estrellas clavadas mientras el resto
                        // se movia. Aqui se hornea con las demas y el campo entero se desliza como una pieza.
                        // No cuesta nada en marcha: son rectangulitos de un pixel y solo se hornean al arrancar
                        // o al cambiar de tamano de pantalla, no por cuadro.
                        if (s.Kind == 0)
                        {
                            SmoothingMode osm2 = lg.SmoothingMode;
                            lg.SmoothingMode = SmoothingMode.None;   // una estrella lejana es un pixel, no una manchita suavizada
                            int cr0, cg0, cb0;
                            if (s.Tint > 0f) { cr0 = 255; cg0 = 255; cb0 = 255; } else { cr0 = s.R; cg0 = s.G; cb0 = s.B; }
                            b.Color = Color.FromArgb(s.Bri, cr0, cg0, cb0);
                            int d0 = s.Size < 1 ? 1 : (s.Size > 2 ? 2 : s.Size);
                            lg.FillRectangle(b, (int)(s.X * w) - d0 / 2, (int)(s.Y * h) - d0 / 2, d0, d0);
                            lg.SmoothingMode = osm2;
                            continue;
                        }
                        int harm = 1 + (i % 2);   // armonico ENTERO (1 o 2: bien muestreado con TwK=8) -> el set cicla exacto
                        double tw = 0.62 + 0.38 * (0.5 + 0.5 * Math.Sin(ph * harm + s.Off));   // titileo 0.62..1.00
                        int a = (int)(tw * s.Bri); if (a > 255) a = 255; if (a < 0) a = 0;
                        int px = (int)(s.X * w), py = (int)(s.Y * h);
                        int cr2, cg2, cb2;
                        if (s.Tint > 0f) { cr2 = 255; cg2 = 255; cb2 = 255; }   // tenidas -> blancas
                        else { cr2 = s.R; cg2 = s.G; cb2 = s.B; }
                        int gd = (int)((s.Size * 3 + 6) * HaloDe(s.Kind));
                        Bitmap gb = GlowFor(cr2, cg2, cb2);   // glow del MISMO COLOR (sprite pre-horneado)
                        if (gb != null)
                        {
                            Rectangle gr = new Rectangle(px - gd / 2, py - gd / 2, gd, gd);
                            if (a >= 250) lg.DrawImage(gb, gr);
                            else using (ImageAttributes ia = new ImageAttributes())   // el glow tambien titila (matriz solo al hornear)
                            {
                                ColorMatrix cm = new ColorMatrix(); cm.Matrix33 = (float)tw;
                                ia.SetColorMatrix(cm);
                                lg.DrawImage(gb, gr, 0, 0, gb.Width, gb.Height, GraphicsUnit.Pixel, ia);
                            }
                        }
                        if (s.Rayos) DrawRayos(lg, b, px, py, s.Size, Color.FromArgb(cr2, cg2, cb2), (s.Bri / 255f) * (float)tw, s.Kind);
                        DrawNucleo(lg, b, px, py, s.Size, cr2, cg2, cb2, a);
                    }
                }
                return bmp;
            }

            private void DrawShoots(Graphics g, int w, int h)
            {
                int now = Environment.TickCount;
                float dt = (lastTick == 0) ? 0f : (now - lastTick) / 1000f;
                if (dt < 0f) dt = 0f; if (dt > 0.12f) dt = 0.12f;   // acotar saltos
                lastTick = now;

                if (now - nextShoot >= 0)   // RESTA, no >=: sobrevive el desbordamiento de TickCount (~25 dias encendida)
                {
                    nextShoot = now + 7000 + rnd.Next(9000);   // una fugaz cada 7-16s
                    for (int i = 0; i < shoots.Length; i++)
                        if (!shoots[i].On)
                        {
                            Shoot ns = new Shoot();
                            ns.On = true;
                            ns.X = (float)(rnd.NextDouble() * w * 0.55);
                            ns.Y = (float)(rnd.NextDouble() * h * 0.45);
                            float spd = (w + h) * 0.55f;                 // px por segundo
                            ns.VX = spd; ns.VY = spd * (0.35f + (float)rnd.NextDouble() * 0.30f);
                            ns.MaxLife = 1.0f + (float)rnd.NextDouble() * 0.5f; ns.Life = ns.MaxLife;
                            shoots[i] = ns;
                            break;
                        }
                }
                for (int i = 0; i < shoots.Length; i++)
                {
                    if (!shoots[i].On) continue;
                    Shoot s = shoots[i];
                    float k = s.Life / s.MaxLife; if (k < 0f) k = 0f;
                    int la = (int)(230 * k * Dim);   // atenuada mientras se navega con musica
                    float tx = s.X - s.VX * 0.10f, ty = s.Y - s.VY * 0.10f;   // estela corta
                    sp.Color = Color.FromArgb(la, 255, 255, 255);
                    g.DrawLine(sp, tx, ty, s.X, s.Y);
                    sb.Color = Color.FromArgb(Math.Min(255, la + 25), 255, 255, 255);
                    g.FillRectangle(sb, (int)s.X - 1, (int)s.Y - 1, 3, 3);
                    s.X += s.VX * dt; s.Y += s.VY * dt; s.Life -= dt;
                    if (s.Life <= 0f || s.X > w + 60 || s.Y > h + 60) s.On = false;
                    shoots[i] = s;
                }
            }
        }

        // Modo atraccion: pantalla negra con estrellas titilantes y un cubo gigante girando que cicla
        // portadas de la coleccion (con fundido). Aparece en reposo para llamar al cliente.
        private class AttractView : Control
        {
            public double Phase = 0;
            public double Angle = 0;
            public List<string> CycleCovers = new List<string>();
            public Func<string, Image> GetCoverByPath;
            public int SongCount { get; set; }   // propiedad (no campo): un campo de una clase por-referencia (Control) dispara la advertencia CS1690 al usarlo

            private SolidBrush sb;
            private Bitmap blendBmp;
            private Font fBig, fSmall; private StringFormat sfCen;

            private Starfield attractStars = new Starfield();

            public AttractView()
            {
                attractStars.Varied = true;   // estrellas multicolor en el modo atraccion
                // El cubo gigante gira a 24 por segundo, pero las estrellas no tienen por que: titilan al
                // mismo ritmo que en el resto del programa. Rehacer el cielo entero 24 veces por segundo era
                // el grueso del gasto de esta pantalla, y es la que mas horas pasa encendida.
                attractStars.RefrescoMs = 200;
                SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
            }

            private void EnsureRes()
            {
                if (sb == null) sb = new SolidBrush(Color.White);
                if (fBig == null) fBig = new Font(FontFamily.GenericSansSerif, 24f, FontStyle.Bold);
                if (fSmall == null) fSmall = new Font(FontFamily.GenericSansSerif, 15f, FontStyle.Bold);
                if (sfCen == null) { sfCen = new StringFormat(); sfCen.Alignment = StringAlignment.Center; sfCen.LineAlignment = StringAlignment.Center; }
            }

            private Image BlendInto(Image a, Image b, float f)
            {
                if (blendBmp == null) blendBmp = new Bitmap(320, 320, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(blendBmp))
                {
                    g.Clear(Color.Black);
                    g.InterpolationMode = InterpolationMode.Bilinear;
                    Rectangle dst = new Rectangle(0, 0, blendBmp.Width, blendBmp.Height);
                    if (a != null) g.DrawImage(a, dst);
                    if (b != null && f > 0f)
                    {
                        ColorMatrix cm = new ColorMatrix(); cm.Matrix33 = f;
                        using (ImageAttributes ia = new ImageAttributes())
                        {
                            ia.SetColorMatrix(cm, ColorMatrixFlag.Default, ColorAdjustType.Bitmap);
                            g.DrawImage(b, dst, 0, 0, b.Width, b.Height, GraphicsUnit.Pixel, ia);
                        }
                    }
                }
                return blendBmp;
            }

            // Par de portadas a fundir + factor (0..1) segun la fase. Lo usa el CPU (BlendInto) y tambien la
            // GPU (que hace el fundido como en los discos TOP, sin generar el bitmap mezclado).
            public bool GetCoverPair(out Image a, out Image b, out float f)
            {
                a = null; b = null; f = 0f;
                if (CycleCovers == null || CycleCovers.Count == 0 || GetCoverByPath == null) return false;
                int m = CycleCovers.Count;
                double cyc = 4.2, hold = 3.0;
                double total = cyc * m;
                double pos = Phase - Math.Floor(Phase / total) * total;
                int idx = (int)(pos / cyc) % m;
                double within = pos - idx * cyc;
                if (within > hold) f = (float)((within - hold) / (cyc - hold));
                if (f < 0f) f = 0f; else if (f > 1f) f = 1f;
                a = GetCoverByPath(CycleCovers[idx]);
                b = (m > 1) ? GetCoverByPath(CycleCovers[(idx + 1) % m]) : null;
                return a != null || b != null;
            }

            private Image CurrentCover()
            {
                Image a, b; float f;
                if (!GetCoverPair(out a, out b, out f)) return null;
                if (f <= 0.002f || b == null) return a;
                if (a == null) return b;
                return BlendInto(a, b, f);
            }

            protected override void OnPaint(PaintEventArgs e)
            {
                Graphics g = e.Graphics;
                int w = Width, h = Height;
                if (w < 8 || h < 8) return;
                EnsureRes();
                attractStars.SkyOffsetY = 0; attractStars.SkyFullH = h;
                attractStars.Draw(g, w, h, Color.FromArgb(255, 6, 8, 26), Color.FromArgb(255, 18, 20, 54), Color.White, Phase, true, 0f);   // cielo nocturno en degradado (atraccion: sin musica)

                // cubo gigante central rotando + ciclando portadas (con fundido)
                int side = (int)(Math.Min(w, h) * 0.40);
                if (side < 80) side = 80;
                Rectangle area = new Rectangle(w / 2 - side / 2, (h - side) / 2 - 30, side, side);
                g.InterpolationMode = InterpolationMode.Bilinear;
                Cube.Draw(g, area, CurrentCover(), Angle);

                // textos
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                string line1 = (SongCount > 0) ? (SongCount.ToString("#,0") + " canciones") : "Tu rocola";
                sb.Color = Color.White;
                g.DrawString(line1, fBig, sb, new RectangleF(0, area.Bottom + 18, w, 36), sfCen);
                double pz = 0.5 + 0.5 * Math.Sin(Phase * 3.0);
                sb.Color = Color.FromArgb((int)(150 + 105 * pz), 255, 220, 120);
                g.DrawString("toca un boton para elegir", fSmall, sb, new RectangleF(0, area.Bottom + 58, w, 28), sfCen);
            }
        }

        private static class Cube
        {
            // OPTIMIZACION (render): estos 3 arreglos se asignaban en CADA llamada a Draw, y Draw se
            // llama varias veces por cuadro (cubo seleccionado, relevo, cubeBox, miniCube, buscador,
            // atraccion). Reutilizarlos via [ThreadStatic] elimina cientos de asignaciones/seg.
            [ThreadStatic] private static double[] exBuf;
            [ThreadStatic] private static double[] depthBuf;
            [ThreadStatic] private static int[] orderBuf;
            [ThreadStatic] private static SolidBrush faceBrush;   // pincel reusable (cara/oscurecido): antes asignaba 1-2 por cara y cuadro
            [ThreadStatic] private static Pen edgePen;            // lapiz de contorno reusable (antes 1 por cuadro)

            public static void Draw(Graphics g, Rectangle bounds, Image cover, double angle)
            {
                double cx = bounds.X + bounds.Width / 2.0;
                int y0 = bounds.Y;
                int H = bounds.Height;
                double R = bounds.Width / 2.0;
                double DEG = Math.PI / 180.0;

                double[] ex = exBuf ?? (exBuf = new double[4]);
                for (int k = 0; k < 4; k++) ex[k] = cx + R * Math.Cos(angle + 45 * DEG + k * 90 * DEG);
                double[] depth = depthBuf ?? (depthBuf = new double[4]);
                for (int k = 0; k < 4; k++) depth[k] = Math.Sin(angle + 90 * DEG + k * 90 * DEG);

                int[] order = orderBuf ?? (orderBuf = new int[4]);
                order[0] = 0; order[1] = 1; order[2] = 2; order[3] = 3;
                for (int i = 0; i < 4; i++)
                    for (int j = 0; j < 3 - i; j++)
                        if (depth[order[j]] > depth[order[j + 1]]) { int tmp = order[j]; order[j] = order[j + 1]; order[j + 1] = tmp; }

                for (int oi = 0; oi < 4; oi++)
                {
                    int k = order[oi];
                    if (depth[k] <= 0.0) continue;
                    int left = (int)Math.Round(Math.Min(ex[k], ex[(k + 1) % 4]));
                    int right = (int)Math.Round(Math.Max(ex[k], ex[(k + 1) % 4]));
                    int w = right - left;
                    if (w < 1) continue;
                    Rectangle rect = new Rectangle(left, y0, w, H);
                    SolidBrush fb = faceBrush ?? (faceBrush = new SolidBrush(Color.Black));
                    if (cover != null) g.DrawImage(cover, rect);
                    else { fb.Color = Color.FromArgb(60, 70, 110); g.FillRectangle(fb, rect); }
                    int darken = (int)((1.0 - depth[k]) * 130);
                    if (darken > 0) { fb.Color = Color.FromArgb(darken, 0, 0, 0); g.FillRectangle(fb, rect); }
                }

                double minx = ex[0], maxx = ex[0];
                for (int k = 1; k < 4; k++) { if (ex[k] < minx) minx = ex[k]; if (ex[k] > maxx) maxx = ex[k]; }
                Pen ep = edgePen ?? (edgePen = new Pen(Color.FromArgb(120, 0, 0, 0), 1));
                g.DrawRectangle(ep, (int)Math.Round(minx), y0, (int)Math.Round(maxx - minx), H - 1);
            }
        }

        // Estado del "brillo" de los simbolos de la barra de instrucciones al pulsar sus botones (halo que
        // decae). UN BRILLO POR SIMBOLO: en los COMBOS (p.ej. REGRESAR mantenido + PONER) se encienden VARIOS
        // a la vez y cada uno decae por su cuenta. (Antes habia UN solo brillo global: el nuevo pisaba al
        // anterior y en los combos solo se veia uno.) El color se fija al dispararlo (asi Mover puede ser
        // ROJO en arriba/abajo o AMARILLO en izq/der). Lo comparten HelpBar (4 simbolos) y el buscador (3).
        private sealed class InstrFlash
        {
            private const int Ms = 420;
            private readonly int[] tick = new int[4];      // momento del disparo por simbolo (0 = nunca disparado)
            private readonly Color[] cols = new Color[4];
            public void Fire(int w, Color c)
            {
                if (w < 0 || w >= tick.Length) return;
                int t = Environment.TickCount;
                tick[w] = (t == 0) ? 1 : t;   // 0 esta reservado como "nunca"
                cols[w] = c;
            }
            public float Level(int w)
            {
                if (w < 0 || w >= tick.Length || tick[w] == 0) return 0f;
                int dt = Environment.TickCount - tick[w];
                if (dt < 0 || dt > Ms) return 0f;
                return 1f - (float)dt / Ms;
            }
            public Color Col(int w) { return (w >= 0 && w < cols.Length) ? cols[w] : Color.White; }
            public int Sig()   // cambia mientras dure ALGUN brillo (para animarlo por CPU); 0 = todo apagado
            {
                int now = Environment.TickCount, s = 0;
                for (int w = 0; w < tick.Length; w++)
                {
                    if (tick[w] == 0) continue;
                    int dt = now - tick[w];
                    if (dt < 0 || dt > Ms) continue;
                    s = s * 37 + (w + 1) * 1000 + dt / 40;
                }
                return s;
            }
        }

        // Halo suave (radial) centrado en un simbolo de instrucciones; intensidad segun 'level' (0..1).
        private static void GlowAround(Graphics g, float leftX, float cy, float symW, float level, Color c)
        {
            if (level <= 0.02f) return;
            float cx = leftX + symW / 2f, r = symW * 0.9f + 6f;
            using (GraphicsPath gp = new GraphicsPath())
            {
                gp.AddEllipse(cx - r, cy - r, 2 * r, 2 * r);
                using (PathGradientBrush pb = new PathGradientBrush(gp))
                {
                    pb.CenterPoint = new PointF(cx, cy);
                    pb.CenterColor = Color.FromArgb((int)(level * 215), c);
                    pb.SurroundColors = new Color[] { Color.FromArgb(0, c) };
                    g.FillPath(pb, gp);
                }
            }
        }

        // Ayudantes para dibujar los controles fisicos como FORMAS (circulo rojo/verde, cruceta).
        // GDI reusables para las formas de instrucciones (se llaman muchas veces por cuadro): pincel al que se
        // le muta el color, contorno blanco fijo y un buffer de 3 puntos. Evita asignar objetos GDI por forma.
        [ThreadStatic] private static SolidBrush ctrlB;
        [ThreadStatic] private static Pen ctrlOutline;
        [ThreadStatic] private static PointF[] ctrlTri3;
        private static SolidBrush CB(Color c) { if (ctrlB == null) ctrlB = new SolidBrush(c); else ctrlB.Color = c; return ctrlB; }
        private static Pen COut() { return ctrlOutline ?? (ctrlOutline = new Pen(Color.FromArgb(130, 255, 255, 255), 1.4f)); }

        private static float CtrlDot(Graphics g, float x, int cy, int d, Color c)
        {
            g.FillEllipse(CB(c), x, cy - d / 2f, d, d);
            g.DrawEllipse(COut(), x, cy - d / 2f, d, d);
            return x + d;
        }
        private static float CtrlTxt(Graphics g, Font f, string s, float x, int cy, Color c)
        {
            SizeF sz = g.MeasureString(s, f);
            g.DrawString(s, f, CB(c), x, cy - sz.Height / 2f);
            return x + sz.Width;
        }
        private static void CtrlTri(Graphics g, Color c, PointF a, PointF b, PointF d)
        {
            PointF[] p = ctrlTri3 ?? (ctrlTri3 = new PointF[3]);
            p[0] = a; p[1] = b; p[2] = d;
            g.FillPolygon(CB(c), p);
        }
        private static float CtrlPad(Graphics g, float x, int cy, int sz)   // cruceta: arriba/abajo rojo, izq/der amarillo
        {
            Color red = Color.FromArgb(228, 72, 72), yellow = Color.FromArgb(242, 206, 72);
            float cx = x + sz / 2f, t = sz * 0.34f, w = t / 1.4f;
            CtrlTri(g, red, new PointF(cx, cy - sz / 2f), new PointF(cx - w, cy - sz / 2f + t), new PointF(cx + w, cy - sz / 2f + t));
            CtrlTri(g, red, new PointF(cx, cy + sz / 2f), new PointF(cx - w, cy + sz / 2f - t), new PointF(cx + w, cy + sz / 2f - t));
            CtrlTri(g, yellow, new PointF(x, cy), new PointF(x + t, cy - w), new PointF(x + t, cy + w));
            CtrlTri(g, yellow, new PointF(x + sz, cy), new PointF(x + sz - t, cy - w), new PointF(x + sz - t, cy + w));
            return x + sz;
        }
        // Icono del BOTON IZQUIERDA (flecha amarilla, mismo color que la cruceta horizontal)
        private static float CtrlDirLeft(Graphics g, float x, int cy, int sz, Color c)
        {
            PointF[] pts = ctrlTri3 ?? (ctrlTri3 = new PointF[3]);
            pts[0] = new PointF(x, cy); pts[1] = new PointF(x + sz, cy - sz * 0.5f); pts[2] = new PointF(x + sz, cy + sz * 0.5f);
            g.FillPolygon(CB(c), pts); g.DrawPolygon(COut(), pts);
            return x + sz;
        }
        // Icono del BOTON DERECHA (flecha amarilla, espejo de la izquierda)
        private static float CtrlDirRight(Graphics g, float x, int cy, int sz, Color c)
        {
            PointF[] pts = ctrlTri3 ?? (ctrlTri3 = new PointF[3]);
            pts[0] = new PointF(x + sz, cy); pts[1] = new PointF(x, cy - sz * 0.5f); pts[2] = new PointF(x, cy + sz * 0.5f);
            g.FillPolygon(CB(c), pts); g.DrawPolygon(COut(), pts);
            return x + sz;
        }

        // Barra de ayuda: instrucciones con FORMAS y COLORES de los botones fisicos. Sin nombres de teclas.
        private class HelpBar : Control
        {
            // BUSCAR ya no esta aqui: tiene su propia casilla grande y parpadeante en medio de la fila, con
            // los dos botones dibujados. Aqui se quedan los tres que se usan a cada rato.
            public const int FMover = 0, FEntrar = 1, FVolver = 2;   // simbolo a resaltar
            private static readonly Color RedC = Color.FromArgb(228, 72, 72), GreenC = Color.FromArgb(72, 212, 112), YellowC = Color.FromArgb(242, 206, 72);
            private readonly InstrFlash flash = new InstrFlash();

            public HelpBar()
            {
                SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.SupportsTransparentBackColor, true);
                BackColor = Color.Transparent;
            }

            // El usuario pulso un boton: resalta (brillo que decae) el simbolo correspondiente.
            public void Flash(int which) { flash.Fire(which, which == FEntrar ? GreenC : which == FVolver ? RedC : Color.White); }
            public void FlashMove(bool vertical) { flash.Fire(FMover, vertical ? RedC : YellowC); }   // arriba/abajo ROJO, izq/der AMARILLO
            public int FlashSig() { return flash.Sig(); }
            private Font hbFont;   // fuente cacheada: la barra se redibuja ~13fps (glow) -> no crear una por cuadro

            protected override void OnPaint(PaintEventArgs e) { e.Graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit; RenderContent(e.Graphics, false); }
            // Centro/radio de los 4 halos (Buscar/Mover/Entrar/Volver), guardados al maquetar. En GPU el destello
            // NO se hornea en la textura: lo dibuja la GPU como quad (GetFlashGlow) -> pulsar un boton (p.ej. al
            // PAGINAR rapido) ya no re-hornea ni re-sube la textura de UI ~10 veces por tecla.
            private readonly float[] fgX = new float[3], fgY = new float[3], fgW = new float[3];
            private void StoreGlow(int k, float leftX, float cy, float symW) { fgX[k] = leftX + symW / 2f; fgY[k] = cy; fgW[k] = symW * 0.9f + 6f; }
            public bool GetFlashGlow(int k, out float cx, out float cy, out float r, out int argb)
            {
                cx = cy = r = 0f; argb = 0;
                if (k < 0 || k > 2) return false;
                float lvl = flash.Level(k);
                if (lvl <= 0.02f) return false;
                cx = fgX[k]; cy = fgY[k]; r = fgW[k];
                Color c = flash.Col(k);
                argb = Color.FromArgb((int)(lvl * 215f), c.R, c.G, c.B).ToArgb();   // alfa = brillo del destello; rgb = su color
                return true;
            }
            // LO QUE MIDE DE VERDAD. El acomodo le reservaba 400 px a ojo, y como sobraban, la casilla de
            // BUSCAR quedaba corrida a la derecha en vez de en el centro de la pantalla. Se mide una sola vez
            // por alto de fila (la letra es fija) y se guarda: esto se llama al acomodar, no al dibujar.
            private static int anchoAlto = -1, anchoCache = -1;
            public static int Ancho(int alto)
            {
                if (anchoAlto == alto) return anchoCache;
                int d = Math.Min(20, alto - 8); if (d < 12) d = 12;
                float gap = 7, grp = 20, x = 2;
                using (Font f = new Font(FontFamily.GenericSansSerif, 9.5f, FontStyle.Bold))
                using (Bitmap b = new Bitmap(1, 1))
                using (Graphics g = Graphics.FromImage(b))
                {
                    x += d + 4;                                                       // la cruceta
                    x += gap + g.MeasureString("Mover", f).Width + grp;
                    x += d + gap + g.MeasureString("Entrar / Poner", f).Width + grp;
                    x += d + gap + g.MeasureString("Volver", f).Width;
                }
                anchoAlto = alto; anchoCache = (int)x + 8;   // un pelin de aire al final
                return anchoCache;
            }

            public void RenderContent(Graphics g) { RenderContent(g, false); }
            // Dibuja la leyenda en un Graphics cualquiera (el control, o la textura de UI del modo GPU). El
            // llamador fija el TextRenderingHint: ClearType para pantalla; AntiAlias (gris) para la textura
            // transparente del modo GPU (ClearType deja flecos de color sobre fondo transparente).
            // forGpu=true: NO hornea el halo del boton pulsado (lo pone la GPU via GetFlashGlow); solo guarda posiciones.
            public void RenderContent(Graphics g, bool forGpu)
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                int cy = Height / 2;
                Color txt = Color.FromArgb(228, 234, 250);
                int d = Math.Min(20, Height - 8); if (d < 12) d = 12;
                float gap = 7, grp = 20;
                if (hbFont == null) hbFont = new Font(FontFamily.GenericSansSerif, 9.5f, FontStyle.Bold);
                Font f = hbFont;
                float x = 2;
                StoreGlow(FMover, x, cy, d + 4);
                if (!forGpu) GlowAround(g, x, cy, d + 4, flash.Level(FMover), flash.Col(FMover));        // MOVER = cruceta (color segun direccion)
                x = CtrlPad(g, x, cy, d + 4);
                x = CtrlTxt(g, f, "Mover", x + gap, cy, txt) + grp;
                StoreGlow(FEntrar, x, cy, d);
                if (!forGpu) GlowAround(g, x, cy, d, flash.Level(FEntrar), flash.Col(FEntrar));           // ENTRAR/PONER = punto verde
                x = CtrlDot(g, x, cy, d, GreenC);
                x = CtrlTxt(g, f, "Entrar / Poner", x + gap, cy, txt) + grp;
                StoreGlow(FVolver, x, cy, d);
                if (!forGpu) GlowAround(g, x, cy, d, flash.Level(FVolver), flash.Col(FVolver));           // VOLVER = punto rojo
                x = CtrlDot(g, x, cy, d, RedC);
                x = CtrlTxt(g, f, "Volver", x + gap, cy, txt);
            }
        }

        // ==========  VISTA DE DISCOS (fondo animado estilo PS2 + cubos)  ==========
        // Panel con fondo estrellado (reactivo al genero), para el modo "dentro del disco"
        private class BgPanel : Panel
        {
            public Color Accent = DefaultAccent;
            public float BgDim = 1f;   // atenuacion del starfield mientras se navega con musica (el form la anima; igual que la rejilla)
            public BgPanel()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
            }
            protected override void OnPaintBackground(PaintEventArgs e) { /* todo en OnPaint */ }
            public Starfield Sky;   // COMPARTIDO con el fondo del form: este panel pinta su VENTANA del mismo campo (una sola pieza)
            protected override void OnPaint(PaintEventArgs e)
            {
                Graphics g = e.Graphics;
                int w = Width, h = Height;
                if (w < 4 || h < 4) return;

                // VENTANA del campo COMPARTIDO de pantalla completa: cielo + estrellas salen del mismo bitmap que
                // pinta el fondo del form, corridos por (Left, Top). Cacheado: solo se copia (rapido) y va fluido,
                // y las estrellas cruzan el borde con las franjas de arriba/abajo sin cortarse.
                if (Sky == null) return;
                Sky.SkyOffsetX = this.Left; Sky.SkyOffsetY = this.Top;
                Sky.SkyFullW = (this.Parent != null) ? this.Parent.ClientSize.Width : w;
                Sky.SkyFullH = (this.Parent != null) ? this.Parent.ClientSize.Height : h;
                Sky.SkyMid = SkyColorMid(Accent); Sky.Acento = Accent;
                Sky.Dim = BgDim;   // en sincronia con la rejilla y las franjas (una sola pieza)
                Sky.DrawCached(g, w, h, SkyColor(Accent), SkyColor2(Accent));   // cielo en degradado CONTINUO; un cubo transparente girando encima
            }

        }

        private class AlbumView : Control
        {
            public List<Album> Page = new List<Album>();
            public int Selected = 0;
            public double SelAngle = 0;
            public double Phase = 0;
            public Color BgAccent = DefaultAccent;
            public Func<Album, Image> GetCover;
            public Func<string, Image> GetCoverByPath;   // discos TOP: caratula por ruta (ciclado)
            public Action<int> OnActivate;
#if ROCOLA_GPU
            public bool GpuCovered;   // el panel GPU (pantalla completa, opaco) tapa esta vista: no malgastes su OnPaint (rejilla+estrellas) por CPU
#endif
            public float BgDim = 1f;  // atenuacion del starfield mientras se navega con musica (el form la anima)

            private Bitmap cubeCache;
            private int cacheW = -1, cacheH = -1;
            private string cacheSig = null;
            // CACHE DE CELDAS: cada disco (portada estatica + etiqueta) se HORNEA a un bitmap UNA vez y luego se
            // COPIA (blit 1:1) en cubeCache al paginar. Antes cada pagina re-ESCALABA 18 portadas y re-MAQUETABA
            // 18 etiquetas (ajuste de linea) -> carisimo al paginar rapido. Ahora paginar es casi solo copias.
            // Nace: cuando se horneo. Hace falta para saber si una casilla chica es de ESTE deslizamiento o
            // quedo de uno de hace rato (ver PeekOrBakeCell).
            private sealed class CellSprite { public Bitmap Bmp; public bool HasCover; public int Uso; public int Nace; }
            // CUANTO SE ENCOGE la casilla mientras la pagina se desliza. A la mitad de lado son la CUARTA
            // PARTE de pixeles, y por tanto la cuarta parte de bytes subidos a la tarjeta grafica: ahi es
            // donde de verdad se atasca el hojeo rapido. El DIBUJO no era el problema y se midio -las 18
            // casillas enteras cuestan 2.9 ms a 1280x1024, y a la mitad 1.7-; lo caro es la subida.
            private const float CeldaChica = 0.5f;
            // EL INTERRUPTOR DE TODO ESTO (Ctrl+F3 -> Imagen). Manda sobre las DOS cosas a la vez -la media
            // resolucion y el aplazar el re-horneado- porque las dos son lo mismo visto de dos maneras:
            // aligerar el momento en que la pagina se mueve. Apagado, la pared se dibuja pasando paginas
            // exactamente como antes de que esto existiera. Lo pone el formulario, como Page o Sky.
            public bool HojeoLigero = true;
            private readonly Dictionary<string, CellSprite> cellCache = new Dictionary<string, CellSprite>();
            private int cellCacheW = -1, cellCacheH = -1;   // tamano con el que se horneo (si cambia, se limpia todo)
            private int cellUso;                            // reloj de uso: sube cada vez que se toca una casilla
            // CUANTAS CASILLAS CABEN EN EL CAJON: las doce paginas de historial que se midieron como el punto
            // dulce (ver CeldasHistorialPaginas), salvo que a este tamano de pantalla no quepan en el techo de
            // memoria. El suelo son las seis de siempre.
            private int capCeldas = 6 * PageSize;
            private int keepCeldas = 4 * PageSize;   // a cuantas se baja al podar
            private void RecalculaCajon(int w, int h)
            {
                long porCasilla = (long)Math.Max(1, w / Cols) * Math.Max(1, h / Rows) * 4L;
                long techo = ((long)CacheCeldasMb() * 1024L * 1024L) / Math.Max(porCasilla, 1L);
                long cabe = CeldasHistorialPaginas * PageSize;
                if (cabe > techo) cabe = techo;
                if (cabe < 6 * PageSize) cabe = 6 * PageSize;   // nunca menos historial que antes
                capCeldas = (int)cabe;
                // Al podar se baja un octavo (y al menos dos paginas): asi la poda no salta en cada pagina.
                int baja = capCeldas / 8; if (baja < 2 * PageSize) baja = 2 * PageSize;
                keepCeldas = capCeldas - baja;
                if (keepCeldas < 4 * PageSize) keepCeldas = 4 * PageSize;
            }
            private bool cubesPending;                       // (CPU) quedan celdas por hornear: se reparte en varios repintados (como en GPU) para no congelar en equipos lentos
            private const int CpuBakeBudget = 9;             // (CPU) celdas horneadas por repintado (media pagina): una pagina nueva se llena en 2 pasadas, sin congelon
#if ROCOLA_GPU
            // La rejilla por GPU ya NO usa una textura a pantalla completa (cubeCache): el panel pide las celdas
            // con BuildGpuGrid y dibuja cada disco como su propio quad. cubeCache queda solo para el render por CPU.
            public Bitmap ContourSpriteBmp { get { EnsureContourSprite(); return contourSprite; } }   // sprite del resalte (lo hornea si falta: el panel GPU lo lee aunque el OnPaint por CPU este suprimido)
            public Rectangle ContourScreenRect()                     // donde va el contorno (celda seleccionada)
            {
                if (contourSprite == null || Page == null || Selected < 0 || Selected >= Page.Count) return Rectangle.Empty;
                if (Sliding) return Rectangle.Empty;   // hojeando: nada seleccionado hasta que la pagina termine de entrar
                int w = Width, h = Height; if (w < 8 || h < 8) return Rectangle.Empty;
                int cw = w / Cols, ch = h / Rows; if (cw < 4 || ch < 4) return Rectangle.Empty;
                Rectangle area, lbl; Geometry(w, h, Selected, out area, out lbl);
                Rectangle fr = area; fr.Inflate(4, 4);
                return new Rectangle(fr.X - ContourMargin, fr.Y - ContourMargin, contourSprite.Width, contourSprite.Height);
            }

            // --- Cubos que GIRAN (seleccionado + relevo) para el modo GPU ---
            // En CPU se dibujan ENCIMA de los cubos estaticos en cada cuadro (Cube.Draw). En GPU le pasamos
            // al panel la celda, el angulo y la(s) portada(s): el panel sube la portada como textura UNA vez
            // (al cambiar) y dibuja el cubo girando como GEOMETRIA. Asi el giro casi no cuesta CPU.

            // Avanza el giro SIN repintar por CPU (el fondo y los cubos los pinta la GPU). Lo llama el
            // temporizador a 24fps cuando el fondo GPU esta activo, en vez de AnimTick (que invalida y repinta).
            public void StepSpinGpu() { StepSpin(); }

            // Arma el estado de los cubos que giran para que el panel GPU los dibuje (mismo aspecto que CPU).
            public GpuCubeState BuildCubeState()
            {
                GpuCubeState st = new GpuCubeState();
                int w = Width, h = Height;
                if (Page == null || w < 8 || h < 8) return st;
                int cw = w / Cols, ch = h / Rows;
                if (cw < 4 || ch < 4) return st;
                // HOJEANDO: la rejilla entera se desliza, pero el cubo que gira y el resalte se dibujan en su
                // sitio fijo. Si se pintaran, se verian clavados y girando mientras todo lo demas pasa de
                // largo. Durante el deslizamiento no hay nada seleccionado; el cubo aparece -plano y quieto,
                // porque el giro tampoco avanza (ver StepSpin)- justo cuando la pagina nueva termina de entrar.
                if (Sliding) return st;
                if (Selected >= 0 && Selected < Page.Count)
                {
                    Rectangle a, l; Geometry(w, h, Selected, out a, out l);
                    Image ca, cb; float f; SelectedCovers(out ca, out cb, out f);
                    st.Sel.Has = true; st.Sel.X = a.X; st.Sel.Y = a.Y; st.Sel.W = a.Width; st.Sel.H = a.Height;
                    st.Sel.Angle = SelAngle; st.Sel.CoverA = ca as Bitmap; st.Sel.CoverB = cb as Bitmap; st.Sel.Fade = f;
                }
                if (prevIdx >= 0 && prevIdx != Selected && prevIdx < Page.Count)   // RELEVO: el que dejamos, girando y decayendo
                {
                    Rectangle a2, l2; Geometry(w, h, prevIdx, out a2, out l2);
                    st.Relay.Has = true; st.Relay.X = a2.X; st.Relay.Y = a2.Y; st.Relay.W = a2.Width; st.Relay.H = a2.Height;
                    st.Relay.Angle = prevAngle; st.Relay.CoverA = ((GetCover != null) ? GetCover(Page[prevIdx]) : null) as Bitmap;
                }
                return st;
            }

            private const int GridBakeBudget = 6;   // celdas NUEVAS horneadas por cuadro (barrer paginas nuevas sin bajar fps)
            // HOJEO: la pagina nueva ENTRA deslizandose por el lado hacia el que vas. No cuesta un solo dibujo
            // mas -las casillas ya se pintan cada cuadro-, solo cambian de sitio; por eso es practicamente gratis.
            // El avance se calcula EN VIVO con el reloj (no con el temporizador de 24): se ve fluido a los fps
            // que de el equipo, igual que las demas animaciones de la rocola.
            public const int SlideMs = 230;
            private int slideTick = -1; private float slideFrom;
            public void StartSlide(int dir, int ancho)   // dir: +1 la nueva entra por la derecha, -1 por la izquierda
            {
                if (ancho < 8) { slideTick = -1; return; }
                slideFrom = dir * (float)ancho; slideTick = Environment.TickCount;
            }
            public bool Sliding { get { return slideTick >= 0 && Environment.TickCount - slideTick < SlideMs; } }
            // CURVA del hojeo (funcion pura, para poder comprobarla): devuelve cuanto FALTA por recorrer
            // (1 = recien empieza, 0 = ya llego) y la opacidad de entrada.
            internal static float CurvaHojeo(int dt, out float alpha)
            {
                alpha = 1f;
                if (dt < 0 || dt >= SlideMs) return 0f;
                float t = dt / (float)SlideMs;
                float e = 1f - (1f - t) * (1f - t) * (1f - t);   // frenado suave al llegar (cubico)
                alpha = t < 0.45f ? (t / 0.45f) : 1f;
                return 1f - e;
            }
            // Devuelve el desplazamiento de este cuadro y, de paso, el desvanecido de entrada.
            private float SlideNow(out float alpha)
            {
                alpha = 1f;
                if (slideTick < 0) return 0f;
                int dt = Environment.TickCount - slideTick;
                if (dt < 0 || dt >= SlideMs) { slideTick = -1; return 0f; }
                return slideFrom * CurvaHojeo(dt, out alpha);
            }

            // Llena 'buf' con las celdas (disco estatico + etiqueta) de la pagina actual, en coords de PANTALLA (el
            // panel GPU es a pantalla completa). Cada celda trae su bitmap ya horneado para que el panel lo suba como
            // su PROPIA textura (cacheada por Folder). Se llama cada cuadro: para celdas cacheadas es casi gratis; las
            // nuevas se hornean con presupuesto (el resto sale null y el panel las salta hasta el proximo cuadro).
            public int BuildGpuGrid(GpuGridCell[] buf)
            {
                if (Page == null || buf == null) return 0;
                int w = Width, h = Height;
                if (w < 8 || h < 8) return 0;
                int cw = w / Cols, ch = h / Rows;
                if (cw < 4 || ch < 4) return 0;
                if (cellCacheW != w || cellCacheH != h) { ClearCellCache(); cellCacheW = w; cellCacheH = h; RecalculaCajon(w, h); }   // tamano nuevo: rehornear (y el cajon cambia de tope: la casilla mide otra cosa)
                else if (cellCache.Count > capCeldas) PodaCeldas();                                              // lleno: fuera las mas viejas
                int side, labelH, gap; CellMetrics(cw, ch, out side, out labelH, out gap);
                // MIENTRAS LA PAGINA SE MUEVE, LAS CASILLAS VAN A MEDIA RESOLUCION. Ocupan el mismo hueco en
                // pantalla -la tarjeta las estira- pero pesan la cuarta parte al subirlas, que es lo que se
                // atasca hojeando rapido. Va antes de SlideNow porque SlideNow apaga el deslizamiento al
                // acabarse, y esta pagina todavia es de las que se estaban moviendo.
                bool chica = Sliding && HojeoLigero;
                float alpha; float dx = SlideNow(out alpha);   // hojeo: desplazamiento y desvanecido de ESTE cuadro
                int ox = this.Left, oy = this.Top;   // coords de albumView -> pantalla (mismo criterio que los cubos que giran)
                int budget = GridBakeBudget;
                int bakeT0 = Environment.TickCount;   // tope de TIEMPO ademas del de cantidad: en el CPU lento de la
                int n = 0;                            // rocola 6 horneadas podian pasar de 16ms -> cuadro perdido al paginar
                for (int i = 0; i < Page.Count && i < PageSize && n < buf.Length; i++)
                {
                    Rectangle area, lbl; Geometry(w, h, i, out area, out lbl);
                    Album a = Page[i];
                    buf[n].Key = ClaveCasilla(a);   // CON la marca: el panel cachea sus texturas por esta clave
                    buf[n].Bmp = PeekOrBakeCell(a, cw, side, labelH, gap, (GetCover != null) ? GetCover(a) : null, ref budget, chica);
                    buf[n].Slot = i;
                    buf[n].X = ox + (i % Cols) * cw + dx; buf[n].Y = oy + area.Y; buf[n].W = cw; buf[n].H = side + gap + labelH;
                    buf[n].A = alpha;
                    n++;
                    if (budget < GridBakeBudget && budget > 0 && Environment.TickCount - bakeT0 >= 6) budget = 0;   // ~6ms horneando: el resto al proximo cuadro
                }
                return n;
            }
#endif

            // PRE-HORNEADO de la pagina de al lado: mientras nadie toca nada, se van dejando listas las casillas
            // que se veran al pasar de pagina. Asi el hojeo se ve fluido LA PRIMERA VEZ y no solo al volver.
            // Vale para las DOS versiones: en la del bar (sin tarjeta grafica) es donde mas se agradece, porque
            // ahi re-escalar 18 caratulas justo al pulsar es lo que se siente como un tiron.
            public List<Album> Ahead;
            private int aheadPos;
            public void SetAhead(List<Album> lista) { Ahead = lista; aheadPos = 0; }
            public void BakeAhead()
            {
                if (Ahead == null || aheadPos >= Ahead.Count) return;
                int w = Width, h = Height;
                if (w < 8 || h < 8) return;
                int cw = w / Cols, ch = h / Rows;
                if (cw < 4 || ch < 4 || cellCacheW != w || cellCacheH != h) return;   // otro tamano: ya se rehorneara solo
                int side, labelH, gap; CellMetrics(cw, ch, out side, out labelH, out gap);
                int budget = 2;   // dos casillas por vuelta (~24 por segundo): invisible y en dos segundos hay pagina
                int t0 = Environment.TickCount;
                while (aheadPos < Ahead.Count && budget > 0 && Environment.TickCount - t0 < 4)
                {
                    Album a = Ahead[aheadPos++];
                    PeekOrBakeCell(a, cw, side, labelH, gap, (GetCover != null) ? GetCover(a) : null, ref budget);
                }
            }
            private Pen cPenGlow, cPenMid, cPenLine;   // contorno del disco seleccionado (cacheadas; antes se creaban por cuadro)
            private Bitmap contourSprite; private Size contourSpriteSize = Size.Empty;   // contorno HORNEADO (3 trazos AA -> 1 copia); todas las casillas miden igual
            private Font lblFont; private SolidBrush lblBrush; private StringFormat lblSF;       // recursos de etiquetas (reusables)
            private Bitmap blendBmp;   // para el fundido suave de portadas del cubo TOP
            public Starfield Sky;   // COMPARTIDO con el fondo del form: esta vista pinta su VENTANA del mismo campo (una sola pieza)
            public float PulseLo = 0f, PulseMid = 0f, PulseHi = 0f;   // pulso 0..1 por banda (graves/medios/agudos): cada estrella late con SU frecuencia

            private Image BlendInto(Image a, Image b, float f)
            {
                // 192 basta: el cubo se dibuja a ~154px; antes 320 gastaba el doble de relleno en cada fundido.
                if (blendBmp == null) blendBmp = new Bitmap(192, 192, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(blendBmp))
                {
                    g.Clear(Color.Black);
                    g.InterpolationMode = InterpolationMode.Bilinear;
                    Rectangle dst = new Rectangle(0, 0, blendBmp.Width, blendBmp.Height);
                    if (a != null) g.DrawImage(a, dst);
                    if (b != null && f > 0f)
                    {
                        ColorMatrix cm = new ColorMatrix(); cm.Matrix33 = f;
                        using (ImageAttributes ia = new ImageAttributes())
                        {
                            ia.SetColorMatrix(cm, ColorMatrixFlag.Default, ColorAdjustType.Bitmap);
                            g.DrawImage(b, dst, 0, 0, b.Width, b.Height, GraphicsUnit.Pixel, ia);
                        }
                    }
                }
                return blendBmp;
            }

            // Portadas a fundir del disco SELECCIONADO: para discos TOP cicla sus portadas (ca actual, cb
            // siguiente, f = mezcla 0..1); para discos normales devuelve la suya en ca (cb=null, f=0). La
            // usan OnPaint (CPU, que las funde a una imagen) y el modo GPU (que funde en dos pasadas).
            private void SelectedCovers(out Image ca, out Image cb, out float f)
            {
                ca = null; cb = null; f = 0f;
                if (Page == null || Selected < 0 || Selected >= Page.Count) return;
                Album selA = Page[Selected];
                if (selA != null && selA.CycleCovers != null && selA.CycleCovers.Count > 0 && GetCoverByPath != null)
                {
                    int m = selA.CycleCovers.Count;
                    double cyc = 3.8, hold = 2.6;
                    double total = cyc * m;
                    double pos = Phase - Math.Floor(Phase / total) * total;
                    int idx = (int)(pos / cyc) % m;
                    double within = pos - idx * cyc;
                    float ff = 0f;
                    if (within > hold) ff = (float)((within - hold) / (cyc - hold));
                    if (ff < 0f) ff = 0f; else if (ff > 1f) ff = 1f;
                    ca = GetCoverByPath(selA.CycleCovers[idx]);
                    cb = (m > 1) ? GetCoverByPath(selA.CycleCovers[(idx + 1) % m]) : null;
                    if (ca == null && GetCover != null) ca = GetCover(selA);   // mientras carga
                    f = ff;
                }
                else ca = (GetCover != null) ? GetCover(selA) : null;
            }

            // Caratula del disco SELECCIONADO ya FUNDIDA a una sola imagen (la usa el render por CPU).
            private Image SelectedCover()
            {
                Image ca, cb; float f; SelectedCovers(out ca, out cb, out f);
                return (cb == null || f <= 0.002f) ? ca : BlendInto(ca, cb, f);
            }

            private void EnsureLabelRes()
            {
                if (lblFont == null) lblFont = new Font(this.Font.FontFamily, 10f, FontStyle.Bold);
                if (lblBrush == null) lblBrush = new SolidBrush(Color.White);
                if (lblSF == null)
                {
                    lblSF = new StringFormat();
                    lblSF.Alignment = StringAlignment.Center; lblSF.LineAlignment = StringAlignment.Center;
                    lblSF.Trimming = StringTrimming.EllipsisCharacter;
                    lblSF.FormatFlags = StringFormatFlags.LineLimit;
                }
            }

            // Avanza el giro e invalida lo MINIMO: en cuadros intermedios solo la casilla del cubo que
            // gira (y la del relevo si lo hay); el cuadro completo (fondo+brillos) va 1 de cada 3.
            public void AnimTick(bool fullFrame)
            {
                Rectangle d = SpinRect();
                StepSpin();
                Rectangle d2 = SpinRect();
                if (fullFrame) { Invalidate(); return; }
                if (d2 != Rectangle.Empty) d = (d == Rectangle.Empty) ? d2 : Rectangle.Union(d, d2);
                if (d != Rectangle.Empty) Invalidate(d);
            }

            // QUE TROZO DE LA PARED CAMBIA AL MOVER LA SELECCION: la casilla que se deja y la que se elige,
            // CON SUS LETREROS.
            //
            // Es el hermano de SpinRect, y la diferencia importa: SpinRect es para el GIRO del cubo, que no
            // toca el letrero, asi que solo mete la portada. Al MOVERSE si cambia el letrero -el del disco
            // elegido se ve distinto-, y si se dejara fuera se quedaria el letrero viejo en pantalla.
            //
            // Antes, moverse repintaba la pared ENTERA -el cielo estrellado y las 18 casillas- cuando solo
            // cambian dos: 1.75 ms por pulsacion a 1280x1024, el 92% de la pantalla para nada, y con el freno
            // de flechas hasta 25 veces por segundo, justo mientras la maquina esta descomprimiendo el audio.
            public Rectangle RectSeleccion()
            {
                if (Page == null || Page.Count == 0) return Rectangle.Empty;
                int w = Width, h = Height; if (w < 8 || h < 8) return Rectangle.Empty;
                Rectangle r = UneCasilla(Rectangle.Empty, w, h, Selected);
                return UneCasilla(r, w, h, prevIdx);   // la que se acaba de dejar (sigue girando y apagandose)
            }

            private Rectangle UneCasilla(Rectangle r, int w, int h, int i)
            {
                if (i < 0 || i >= Page.Count) return r;
                Rectangle area, lbl;
                Geometry(w, h, i, out area, out lbl);
                area.Inflate(16, 16);                  // el contorno blanco brillante se sale de la portada
                Rectangle u = Rectangle.Union(area, lbl);
                return (r == Rectangle.Empty) ? u : Rectangle.Union(r, u);
            }

            // Rectangulo que abarca el cubo seleccionado (girando) y el cubo en relevo, con margen
            // suficiente para el contorno blanco brillante.
            private Rectangle SpinRect()
            {
                if (Page == null || Page.Count == 0) return Rectangle.Empty;
                int w = Width, h = Height; if (w < 8 || h < 8) return Rectangle.Empty;
                Rectangle r = Rectangle.Empty, area, lbl;
                if (Selected >= 0 && Selected < Page.Count)
                { Geometry(w, h, Selected, out area, out lbl); area.Inflate(16, 16); r = area; }
                if (prevIdx >= 0 && prevIdx < Page.Count)
                { Geometry(w, h, prevIdx, out area, out lbl); area.Inflate(16, 16); r = (r == Rectangle.Empty) ? area : Rectangle.Union(r, area); }
                return r;
            }

            // Relevo de giro: al cambiar de cubo, el ANTERIOR da un giro rapido que decae (se "pasa la energia"),
            // y el NUEVO arranca plano. Asi se ve cual se dejo y cual es el actual, aunque se mueva muy rapido.
            private int prevIdx = -1;        // cubo que se acaba de dejar (gira y se apaga)
            private double prevAngle = 0;    // su angulo actual
            private float prevSpin = 0f;     // su velocidad de giro (decae)
            private float spinDir = 1f;      // sentido del giro (segun la direccion del movimiento)

            // Mueve la seleccion DENTRO de la pagina con efecto de relevo (lo llama el movimiento izq/der).
            public void MoveSelectionTo(int newSel, int dir)
            {
                int cnt = (Page != null) ? Page.Count : 0;
                if (newSel != Selected && Selected >= 0 && Selected < cnt)
                {
                    prevIdx = Selected;            // el que dejamos
                    prevAngle = SelAngle;          // continua desde donde iba
                    prevSpin = 0.7f * (dir >= 0 ? 1f : -1f);   // golpe de giro en el sentido del movimiento
                }
                spinDir = (dir >= 0 ? 1f : -1f);
                Selected = newSel;
                SelAngle = 0;                      // el nuevo empieza plano (y arranca a girar)
            }

            // Cancela cualquier relevo en curso (al cambiar de pagina/letra, donde los cubos ya no son los mismos).
            public void CancelHandoff() { prevIdx = -1; prevSpin = 0f; }

            // Avanza el giro del cubo actual y el del cubo en relevo (lo llama el temporizador, 24fps).
            public void StepSpin()
            {
#if ROCOLA_GPU
                if (Sliding) return;   // pasando de pagina: no hay cubo a la vista, y asi el nuevo empieza plano
#endif
                SelAngle += 0.06 * spinDir;
                if (prevIdx >= 0)
                {
                    if (Math.Abs(prevSpin) > 0.02f) { prevAngle += prevSpin; prevSpin *= 0.85f; }
                    else
                    {
                        // ya casi parado: lo asentamos al multiplo de 2π mas cercano (queda plano, sin salto)
                        double target = Math.Round(prevAngle / (2 * Math.PI)) * (2 * Math.PI);
                        prevAngle += (target - prevAngle) * 0.25;
                        if (Math.Abs(target - prevAngle) < 0.03) prevIdx = -1;
                    }
                }
            }

            public AlbumView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
            }

            // Fuerza reconstruir la capa de cubos (cuando llega una portada en segundo plano)
            public void InvalidateCubeCache() { cacheSig = null; Invalidate(); }
            // Descarta las celdas horneadas (p.ej. tras re-escanear la biblioteca: mismo Folder pero etiqueta/portada
            // pueden haber cambiado). Fuerza rehornear en el proximo RebuildCubes.
            public void ResetCellCache() { ClearCellCache(); cellCacheW = cellCacheH = -1; cacheSig = null; Invalidate(); }

            protected override void OnMouseClick(MouseEventArgs e)
            {
                int cw = Width / Cols, ch = Height / Rows;
                if (cw > 0 && ch > 0)
                {
                    int col = e.X / cw, row = e.Y / ch;
                    if (col >= 0 && col < Cols && row >= 0 && row < Rows)
                    {
                        int idx = row * Cols + col;
                        if (Page != null && idx < Page.Count) { Selected = idx; if (OnActivate != null) OnActivate(idx); }
                    }
                }
                base.OnMouseClick(e);
            }

            private string Sig()
            {
                if (Page == null || Page.Count == 0) return "0";
                return Page.Count.ToString() + "|" + (Page[0].Folder == null ? "" : Page[0].Folder) + "|" + (Page[Page.Count - 1].Folder == null ? "" : Page[Page.Count - 1].Folder);
            }

            private void Geometry(int w, int h, int i, out Rectangle cubeArea, out Rectangle labelRect)
            {
                int cw = w / Cols, ch = h / Rows;
                int col = i % Cols, row = i / Cols;
                Rectangle cell = new Rectangle(col * cw, row * ch, cw, ch);
                int labelH = 38, padX = 8, gap = 3, padY = 6;   // labelH = 2 lineas; etiqueta pegada al cubo
                int side = Math.Min(cell.Width - 2 * padX, cell.Height - labelH - gap - 2 * padY);
                if (side < 10) side = 10;
                int blockH = side + gap + labelH;
                int top = cell.Y + Math.Max(padY, (cell.Height - blockH) / 2);   // centra cubo+etiqueta en la celda
                cubeArea = new Rectangle(cell.X + (cell.Width - side) / 2, top, side, side);
                labelRect = new Rectangle(cell.X + 2, cubeArea.Bottom + gap, cell.Width - 4, labelH);
            }

            // Dimensiones de la celda (cuadro del disco) IGUAL que las calcula Geometry, para hornear/colocar.
            private static void CellMetrics(int cw, int ch, out int side, out int labelH, out int gap)
            {
                labelH = 38; gap = 3; int padX = 8, padY = 6;
                side = Math.Min(cw - 2 * padX, ch - labelH - gap - 2 * padY);
                if (side < 10) side = 10;
            }

            // Clave de cache de la celda: Folder (estable y unico) para discos normales. Para discos TOP ("Lo mas
            // sonado"), que reusan el mismo Folder sintetico pero cuya portada cambia al variar las reproducciones,
            // se le agrega la ruta de portada: asi se re-hornea cuando cambia (la etiqueta es fija). null = no cachea.
            // Se pide para CADA casilla en CADA cuadro (el panel la usa de clave de su cache de texturas). En los
            // discos normales es la carpeta tal cual, sin gasto; en los TOP habia que pegar carpeta+portada, y eso
            // era una cadena nueva por casilla y por cuadro: en la pagina de LO MAS SONADO, seis por cuadro a 60
            // cuadros por segundo. Ahora se arma UNA vez y se guarda en el propio disco.
            private static string CellKey(Album a)
            {
                if (a == null || a.Folder == null) return null;
                if (!a.IsTop) return a.Folder;
                string cp = a.CoverPath ?? "";
                if (a.KeyCache == null || a.KeyFrom != cp) { a.KeyFrom = cp; a.KeyCache = a.Folder + "|" + cp; }
                return a.KeyCache;
            }

            // LA CLAVE DE LA CASILLA, CON LA MARCA PUESTA. UN SOLO SITIO, y por eso existe.
            //
            // El palomito de "ya la pusiste" va HORNEADO DENTRO del mapa de bits de la casilla, asi que al
            // pedir una cancion hay que hornear una casilla NUEVA: por eso la clave lleva un "#q" pegado.
            // Eso estaba bien puesto en los dos sitios que hornean... y no en el tercero, el que le entrega
            // la rejilla a la tarjeta grafica, que ademas es el que manda: el panel cachea sus texturas por
            // esa clave. Resultado: la rocola horneaba la casilla con marca, se la daba al panel, y el panel
            // reusaba la textura vieja SIN marca. El adorno entero estaba invisible en las dos maquinas de
            // Windows, y tampoco desaparecia nunca al vaciarse la cola.
            //
            // Pegar el "#q" en un tercer sitio habria sido repetir el error. Ahora los tres piden aqui.
            //
            // Y NO CUESTA UNA CADENA NUEVA POR CUADRO: la variante con marca se arma UNA vez por disco y se
            // guarda en el propio disco, igual que la clave base. Esto se pide para cada casilla en cada
            // cuadro -dieciocho, sesenta veces por segundo-, y pegar cadenas ahi seria basura sin fin.
            private string ClaveCasilla(Album a)
            {
                string k = CellKey(a);
                if (k == null || EnCola == null || !EnCola(a)) return k;
                if (a.KeyQ == null || !object.ReferenceEquals(a.KeyQDe, k)) { a.KeyQDe = k; a.KeyQ = k + "#q"; }
                return a.KeyQ;
            }

            // Hornea la celda de un disco (portada estatica en angulo 0 + etiqueta a 2 lineas) a un bitmap propio.
            private Bitmap BakeCell(Album a, int cw, int side, int labelH, int gap, Image cover)
            { return BakeCell(a, cw, side, labelH, gap, cover, 1f); }

            // 'esc' encoge la casilla, para el hojeo (ver CeldaChica).
            //
            // SE ENCOGE EL DIBUJO, NO LAS MEDIDAS, y esto no es un capricho: la letra del rotulo tiene tamano
            // FIJO -no sale de 'labelH', ver EnsureLabelRes-, asi que pasando las medidas partidas por dos el
            // disco menguaria pero el nombre seguiria igual de grande: enorme para su hueco, y cortado.
            // Encogiendo el pincel sale la MISMA casilla, igual de proporcionada, solo que con menos pixeles.
            public Func<Album, bool> EnCola;   // ¿este disco tiene algo pedido? (lo contesta el form)

            private Bitmap BakeCell(Album a, int cw, int side, int labelH, int gap, Image cover, float esc)
            {
                int bw = cw, bh = side + gap + labelH;
                bool encoge = (esc > 0f && esc < 0.999f);
                if (encoge)
                {
                    bw = (int)(cw * esc); if (bw < 1) bw = 1;
                    bh = (int)((side + gap + labelH) * esc); if (bh < 1) bh = 1;
                }
                Bitmap bmp = new Bitmap(bw, bh, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(bmp))
                {
                    g.Clear(Color.Transparent);
                    if (encoge) g.ScaleTransform(esc, esc);
                    g.InterpolationMode = InterpolationMode.Bilinear;   // mas rapido que bicubico (CPU vieja); las portadas ya son de buena resolucion
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    Rectangle rDisco = new Rectangle((cw - side) / 2, 0, side, side);
                    Cube.Draw(g, rDisco, cover, 0.0);   // disco centrado (mismo x que Geometry)
                    if (EnCola != null && EnCola(a)) Palomito(g, rDisco);
                    EnsureLabelRes();
                    g.DrawString(AlbumLabel(a), lblFont, lblBrush, new Rectangle(2, side + gap, cw - 4, labelH), lblSF);   // etiqueta pegada al disco
                }
                return bmp;
            }

            // EL PALOMITO DE "YA LA PUSISTE". Va en la esquina de arriba a la derecha del disco, que es la
            // unica de las cuatro que no pisa ni la etiqueta ni el recuadro de seleccion. Verde, el mismo
            // de la cola, para que se lea sin explicarlo: verde = tuya, ya va.
            private static void Palomito(Graphics g, Rectangle disco)
            {
                float d = disco.Width * 0.26f; if (d < 13f) d = 13f;
                float x = disco.Right - d * 0.92f, y = disco.Top - d * 0.08f;
                using (SolidBrush b = new SolidBrush(Color.FromArgb(236, 120, 230, 165)))
                    g.FillEllipse(b, x, y, d, d);
                using (Pen aro = new Pen(Color.FromArgb(150, 10, 40, 26), Math.Max(1f, d * 0.07f)))
                    g.DrawEllipse(aro, x, y, d, d);
                using (Pen p = new Pen(Color.FromArgb(255, 10, 44, 28), Math.Max(1.6f, d * 0.15f)))
                {
                    p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; p.LineJoin = LineJoin.Round;
                    g.DrawLines(p, new PointF[] {
                        new PointF(x + d * 0.27f, y + d * 0.52f),
                        new PointF(x + d * 0.44f, y + d * 0.70f),
                        new PointF(x + d * 0.75f, y + d * 0.32f) });
                }
            }

            // Devuelve el bitmap horneado de la celda del album; lo re-hornea si falta o si cambio el estado de
            // portada (placeholder -> cargada). Clave = CellKey(a) (ver arriba). Sin clave no se cachea.
            private Bitmap GetOrBakeCell(Album a, int cw, int side, int labelH, int gap, Image cover)
            {
                string key = ClaveCasilla(a);
                // LA MARCA ENTRA EN LA LLAVE, y por eso no hace falta avisar a nadie de nada: al pedir una
                // cancion, la llave de ese disco cambia, la casilla no esta en la caja y se hornea con su
                // palomito. Y la version sin marca se queda guardada para cuando la cancion ya sono.
                bool hasCover = (cover != null);
                CellSprite cs = null;
                if (key != null && cellCache.TryGetValue(key, out cs) && cs.Bmp != null && cs.HasCover == hasCover)
                { cs.Uso = ++cellUso; return cs.Bmp; }   // reutiliza (paginar = solo copiar)
                Bitmap bmp = BakeCell(a, cw, side, labelH, gap, cover);
                if (key != null)
                {
                    if (cs != null && cs.Bmp != null && cs.Bmp != bmp) cs.Bmp.Dispose();   // reemplaza el placeholder por la version con portada
                    cellCache[key] = new CellSprite { Bmp = bmp, HasCover = hasCover, Uso = ++cellUso };
                }
                return bmp;
            }

            // Como GetOrBakeCell pero con PRESUPUESTO de horneado por cuadro (para la rejilla por GPU): si la celda
            // no esta cacheada y no queda presupuesto, devuelve la version vieja (placeholder) si la hay, o null (el
            // panel la salta y aparece en el siguiente cuadro). Asi un barrido de paginas NUEVAS no hornea 18 celdas
            // de golpe -> los fps no bajan. Comparte cellCache con GetOrBakeCell (mismas claves).
            // Cuando empezo el deslizamiento de pagina que hay en curso, o -1 si no hay ninguno. Sin tarjeta
            // grafica las paginas no se deslizan -no existe ese camino-, asi que ahi siempre es -1.
#if ROCOLA_GPU
            private int TickHojeo { get { return slideTick; } }
#else
            private int TickHojeo { get { return -1; } }
#endif

            private Bitmap PeekOrBakeCell(Album a, int cw, int side, int labelH, int gap, Image cover, ref int budget)
            { return PeekOrBakeCell(a, cw, side, labelH, gap, cover, ref budget, false); }

            // 'chica' = la pagina se esta deslizando, asi que la casilla va a media resolucion. Se guarda con
            // su propia clave para que la entera siga ahi: al parar hay que volver a ella.
            private Bitmap PeekOrBakeCell(Album a, int cw, int side, int labelH, int gap, Image cover, ref int budget, bool chica)
            {
                string key = ClaveCasilla(a);
                bool hasCover = (cover != null);
                string k = (key == null) ? null : (chica ? key + "#c" : key);
                CellSprite cs = null;
                if (k != null) cellCache.TryGetValue(k, out cs);
                // MIENTRAS LA PAGINA SE MUEVE NO SE REHACE UNA CASILLA PORQUE HAYA LLEGADO SU PORTADA.
                //
                // Normalmente, en cuanto la portada aparece, la casilla se vuelve a hornear Y a subir entera a
                // la tarjeta para cambiar el disco vacio por el de verdad. Pero pasando paginas rapido las
                // portadas no estan listas NUNCA, asi que el momento mas apretado era justo el que hacia el
                // doble de trabajo. Se aplaza a que la pagina pare: un cuarto de segundo despues, y sin nadie
                // mirando el detalle de una casilla que va volando.
                //
                // Solo se aplaza lo horneado EN ESTE deslizamiento, y para eso esta 'Nace': una casilla chica
                // que quedo de un hojeo de hace un rato SI se rehace, porque si no una pagina ya visitada se
                // veria con los discos vacios para siempre.
                bool recien = chica && HojeoLigero && cs != null && TickHojeo >= 0 && cs.Nace - TickHojeo >= 0;
                if (cs != null && cs.Bmp != null && (cs.HasCover == hasCover || recien))
                { cs.Uso = ++cellUso; return cs.Bmp; }   // cacheada -> gratis
                // sin presupuesto: usa la vieja (placeholder) si hay. Cuenta como uso: se esta viendo AHORA
                // MISMO, asi que la poda no puede llevarsela por delante.
                if (budget <= 0)
                {
                    if (cs != null && cs.Bmp != null) { cs.Uso = ++cellUso; return cs.Bmp; }
                    // Y ANTES QUE DEJAR UN HUECO, la de la OTRA resolucion: la tarjeta la estira y se ve un
                    // pelo blanda un cuadro, que es infinitamente mejor que un agujero en la pared.
                    CellSprite otra;
                    if (key != null && cellCache.TryGetValue(chica ? key : key + "#c", out otra) && otra.Bmp != null)
                    { otra.Uso = ++cellUso; return otra.Bmp; }
                    return null;
                }
                budget--;
                Bitmap bmp = BakeCell(a, cw, side, labelH, gap, cover, chica ? CeldaChica : 1f);
                if (k != null)
                {
                    if (cs != null && cs.Bmp != null && cs.Bmp != bmp) cs.Bmp.Dispose();
                    cellCache[k] = new CellSprite { Bmp = bmp, HasCover = hasCover, Uso = ++cellUso, Nace = Environment.TickCount };
                }
                return bmp;
            }

            // AL LLENARSE EL CAJON SE TIRABAN TODAS LAS CASILLAS. El que estaba hojeando perdia de golpe hasta
            // las paginas que acababa de ver, y retroceder UNA sola pagina obligaba a re-escalar 18 caratulas y
            // re-maquetar 18 nombres: un tiron cada seis paginas. Ahora se tiran solo las MAS VIEJAS y se quedan
            // las ultimas vistas, que son justo a las que se vuelve.
            private void PodaCeldas()
            {
                int sobran = cellCache.Count - keepCeldas;
                if (sobran <= 0) return;
                // El corte: por debajo de ese valor de uso se tira. Son ~100 numeros y esto pasa una vez cada
                // varias paginas, asi que ordenarlos no cuesta nada al lado de hornear una sola casilla.
                int[] usos = new int[cellCache.Count];
                int k = 0;
                foreach (CellSprite cs in cellCache.Values) usos[k++] = cs.Uso;
                Array.Sort(usos);
                int corte = usos[sobran];
                List<string> fuera = new List<string>(sobran);
                foreach (KeyValuePair<string, CellSprite> kv in cellCache)
                    if (kv.Value.Uso < corte) fuera.Add(kv.Key);
                for (int i = 0; i < fuera.Count; i++)
                {
                    CellSprite cs = cellCache[fuera[i]];
                    if (cs.Bmp != null) cs.Bmp.Dispose();
                    cellCache.Remove(fuera[i]);
                }
            }

            private void ClearCellCache()
            {
                foreach (CellSprite cs in cellCache.Values) if (cs.Bmp != null) cs.Bmp.Dispose();
                cellCache.Clear();
            }

            // Compone la rejilla en cubeCache (bitmap a pantalla completa) para el render por CPU. En modo GPU NO se
            // usa (el panel dibuja cada disco como su propio quad via BuildGpuGrid); OnPaint por CPU esta suprimido.
            private void RebuildCubes(int w, int h)
            {
                if (cubeCache == null || cubeCache.Width != w || cubeCache.Height != h)
                {
                    if (cubeCache != null) cubeCache.Dispose();
                    cubeCache = new Bitmap(w, h);
                }
                if (cellCacheW != w || cellCacheH != h) { ClearCellCache(); cellCacheW = w; cellCacheH = h; RecalculaCajon(w, h); }   // tamano nuevo: las celdas horneadas ya no encajan (y el cajon cambia de tope)
                else if (cellCache.Count > capCeldas) PodaCeldas();                                             // lleno: fuera las mas viejas (nunca la pagina que se ve)
                int budget = CpuBakeBudget;   // HORNEADO REPARTIDO (como en GPU): a lo mas CpuBakeBudget celdas nuevas por repintado; el
                cubesPending = false;         // resto queda para el proximo (OnPaint re-invalida). Evita el congelon de hornear 18 de golpe.
                using (Graphics g = Graphics.FromImage(cubeCache))
                {
                    g.Clear(Color.Transparent);
                    if (Page == null) return;
                    int cw = w / Cols, ch = h / Rows;
                    if (cw < 4 || ch < 4) return;
                    int side, labelH, gap; CellMetrics(cw, ch, out side, out labelH, out gap);
                    for (int i = 0; i < Page.Count && i < PageSize; i++)
                    {
                        // Todos los discos van estaticos (angulo 0). El seleccionado (y el de relevo) se dibujan
                        // girando ENCIMA en OnPaint; como girando nunca son mas angostos, lo tapan. Asi el cache
                        // NO depende de la seleccion -> moverse entre discos no lo reconstruye (fluido).
                        Rectangle area, lbl; Geometry(w, h, i, out area, out lbl);
                        Bitmap cell = PeekOrBakeCell(Page[i], cw, side, labelH, gap, (GetCover != null) ? GetCover(Page[i]) : null, ref budget);
                        if (cell != null) g.DrawImageUnscaled(cell, (i % Cols) * cw, area.Y);   // copia 1:1 (sin re-escalar portada ni re-maquetar texto)
                        else if (Page[i] != null && Page[i].Folder != null) cubesPending = true;   // solo celdas CACHEABLES se completan luego (convergen); las raras sin Folder no bloquean el bucle
                    }
                }
            }

            // Cuando llega UNA caratula, redibuja SOLO ese cubo en el cache (no los 18).
            // Asi pasar de pagina no dispara reconstrucciones completas repetidas (evita el tiron en XP).
            public void RefreshCover(string coverPath)
            {
                if (Page == null || coverPath == null) return;
                int w = Width, h = Height;
                if (cubeCache == null || cubeCache.Width != w || cubeCache.Height != h) { InvalidateCubeCache(); return; }
                int cw = w / Cols, ch = h / Rows;
                if (cw < 4 || ch < 4) return;
                int side, labelH, gap; CellMetrics(cw, ch, out side, out labelH, out gap);
                bool any = false;
                Rectangle dirtyR = Rectangle.Empty;
                using (Graphics g = Graphics.FromImage(cubeCache))
                {
                    for (int i = 0; i < Page.Count && i < PageSize; i++)
                    {
                        if (Page[i] == null || Page[i].CoverPath != coverPath) continue;
                        int col = i % Cols, row = i / Cols;
                        Rectangle cell = new Rectangle(col * cw, row * ch, cw, ch);
                        Rectangle area, lbl; Geometry(w, h, i, out area, out lbl);
                        // rehornea la celda CON la portada (GetOrBakeCell detecta que HasCover cambio) y actualiza
                        // el cache: revisitar la pagina sigue siendo instantaneo. Luego la copia en cubeCache.
                        Bitmap cell2 = GetOrBakeCell(Page[i], cw, side, labelH, gap, (GetCover != null) ? GetCover(Page[i]) : null);
                        g.CompositingMode = CompositingMode.SourceCopy;   // deja la celda transparente antes de recomponer
                        using (SolidBrush tb = new SolidBrush(Color.Transparent)) g.FillRectangle(tb, cell);
                        g.CompositingMode = CompositingMode.SourceOver;
                        g.DrawImageUnscaled(cell2, col * cw, area.Y);
                        dirtyR = (dirtyR == Rectangle.Empty) ? cell : Rectangle.Union(dirtyR, cell);
                        any = true;
                    }
                }
                if (any && dirtyR != Rectangle.Empty) Invalidate(dirtyR);   // solo su celda: 18 caratulas ya NO son 18 repintados completos
                // En modo GPU (cubeCache es null) esta ruta no se ejecuta: la portada llega a la rejilla por GPU sola,
                // porque BuildGpuGrid consulta GetCover cada cuadro y re-hornea la celda cuando la portada aparece.
            }

            private const int ContourMargin = 8;   // margen del sprite del contorno (para el resplandor ancho de 11px)

            // Hornea el sprite del contorno de seleccion (3 trazos AA -> 1 copia). Es INDEPENDIENTE de cual celda
            // este seleccionada (todas miden igual): solo se re-hornea al cambiar de tamano. Lo llaman el OnPaint
            // (CPU) y el panel GPU (via ContourSpriteBmp), asi existe aunque el OnPaint por CPU este suprimido.
            private void EnsureContourSprite()
            {
                int w = Width, h = Height;
                if (w < 8 || h < 8) return;
                int cw = w / Cols, ch = h / Rows;
                if (cw < 4 || ch < 4) return;
                Rectangle area, lbl; Geometry(w, h, 0, out area, out lbl);
                Rectangle fr = area; fr.Inflate(4, 4);
                Size need = new Size(fr.Width + 2 * ContourMargin, fr.Height + 2 * ContourMargin);
                if (contourSprite != null && contourSpriteSize == need) return;
                if (cPenGlow == null)
                {
                    cPenGlow = new Pen(Color.FromArgb(20, 255, 255, 255), 11f);   // resplandor ancho y tenue
                    cPenMid = new Pen(Color.FromArgb(45, 255, 255, 255), 6f);     // resplandor medio
                    cPenLine = new Pen(Color.FromArgb(235, 255, 255, 255), 2.4f); // linea nitida
                }
                if (contourSprite != null) contourSprite.Dispose();
                contourSprite = new Bitmap(need.Width, need.Height, PixelFormat.Format32bppPArgb);
                using (Graphics cg = Graphics.FromImage(contourSprite))
                using (GraphicsPath cp = RoundRect(new Rectangle(ContourMargin, ContourMargin, fr.Width, fr.Height), 10))
                {
                    cg.SmoothingMode = SmoothingMode.AntiAlias;
                    cg.DrawPath(cPenGlow, cp);
                    cg.DrawPath(cPenMid, cp);
                    cg.DrawPath(cPenLine, cp);
                }
                contourSpriteSize = need;
            }

            protected override void OnPaint(PaintEventArgs e)
            {
                Graphics g = e.Graphics;
                int w = Width, h = Height;
                if (w < 8 || h < 8) { g.Clear(Shade(BgAccent, 0.82)); return; }
                // Cuando el fondo GPU (pantalla completa, opaco) esta encima, TODO esto queda oculto. Reconstruir
                // la rejilla + pintar estrellas + cubo por CPU en cada Invalidate (p.ej. al paginar, que llama
                // Invalidate por cambio de pagina) era trabajo invisible que ademas SALTABA la franja de la GPU
                // -> tirones al hojear. El panel GPU dibuja la rejilla por su cuenta (BuildGpuGrid, un quad/celda).
#if ROCOLA_GPU
                if (GpuCovered) return;
#endif

                bool sizeChanged = (cacheW != w || cacheH != h);
                string sig = Sig();
                if (sizeChanged || cubeCache == null || sig != cacheSig || cubesPending) RebuildCubes(w, h);   // ya NO se reconstruye por cambio de seleccion; cubesPending completa el horneado repartido
                cacheW = w; cacheH = h; cacheSig = sig;

                if (Sky != null)
                {
                    Sky.SkyOffsetX = this.Left; Sky.SkyOffsetY = this.Top;   // VENTANA del campo COMPARTIDO de pantalla completa (una sola pieza con las franjas)
                    Sky.SkyFullW = (this.Parent != null) ? this.Parent.ClientSize.Width : w;
                    Sky.SkyFullH = (this.Parent != null) ? this.Parent.ClientSize.Height : h;
                    Sky.SkyMid = SkyColorMid(BgAccent); Sky.Acento = BgAccent;
                    Sky.Dim = BgDim;   // atenuado mientras se navega con musica (vuelve solo tras 10s sin botones)
                    Sky.DrawReactive(g, w, h, SkyColor(BgAccent), SkyColor2(BgAccent), PulseLo, PulseMid, PulseHi);   // fondo titilante + LATIDO por banda (grandes=graves, medianas=medios/agudos)
                }
                g.DrawImageUnscaled(cubeCache, 0, 0);

                if (Page != null && Selected >= 0 && Selected < Page.Count)
                {
                    int cw = w / Cols, ch = h / Rows;
                    if (cw >= 4 && ch >= 4)
                    {
                        Rectangle area, lbl;
                        Geometry(w, h, Selected, out area, out lbl);
                        g.InterpolationMode = InterpolationMode.Bilinear;
                        // Contorno blanco con resplandor del disco SELECCIONADO (ademas del giro), para ubicarlo facil.
                        Rectangle fr = area; fr.Inflate(4, 4);
                        EnsureContourSprite();   // sprite horneado (3 trazos AA -> 1 copia); solo se re-hornea al cambiar tamano
                        if (contourSprite != null) g.DrawImageUnscaled(contourSprite, fr.X - ContourMargin, fr.Y - ContourMargin);
                        Cube.Draw(g, area, SelectedCover(), SelAngle);
                    }
                }

                // Cubo de RELEVO: el que acabamos de dejar sigue girando (rapido y decayendo) sobre su
                // posicion. Como el cubo girando nunca es mas angosto que el del cache, lo tapa sin fantasma.
                if (prevIdx >= 0 && prevIdx != Selected && Page != null && prevIdx < Page.Count)
                {
                    int cw = w / Cols, ch = h / Rows;
                    if (cw >= 4 && ch >= 4)
                    {
                        Rectangle area2, lbl2;
                        Geometry(w, h, prevIdx, out area2, out lbl2);
                        g.InterpolationMode = InterpolationMode.Bilinear;
                        Cube.Draw(g, area2, (GetCover != null) ? GetCover(Page[prevIdx]) : null, prevAngle);
                    }
                }
                if (cubesPending) Invalidate();   // quedan celdas por hornear: pide otro repintado para completarlas (repartido, sin congelar)
            }
        }

        // ==========  VIDEO: host del control ActiveX de Windows Media Player  ==========
        // (CLSID del OCX de wmp.dll)
        private class VideoHost : AxHost
        {
            public VideoHost() : base("6bf52a52-394a-11d3-b153-00c04f79faa6") { }
            public object GetOcxObj() { return this.GetOcx(); }
        }

        // Un elemento de la cola: una cancion O un video. Disc = disco para el cubo de abajo.
        private class PlayItem
        {
            public bool IsVideo;
            public Track Song;
            public string VideoPath;
            public Album Disc;
            public string PathKey()
            {
                if (IsVideo) return VideoPath ?? "";
                return (Song != null && Song.Path != null) ? Song.Path : "";
            }
            public string Display()
            {
                if (IsVideo)
                {
                    // Mostrar "album - nombre del video": el disco (carpeta) MAS el nombre del archivo.
                    string disc = (Disc != null && !string.IsNullOrEmpty(Disc.Artist)) ? Disc.Artist : "";
                    string file = "";
                    try { file = System.IO.Path.GetFileNameWithoutExtension(VideoPath); } catch { }
                    string n;
                    if (disc.Length > 0 && file.Length > 0) n = disc + " - " + file;
                    else if (file.Length > 0) n = file;
                    else n = disc;
                    return "\u25BA Video:  " + n;
                }
                return (Song != null) ? (Song.Artist + " - " + Song.Title) : "";
            }

            // Lo mismo, pero PARTIDO: arriba lo que suena y debajo de quien es. La franja de abajo los pone en
            // dos renglones distintos, con distinto tamano y distinto color, asi que no vale con una sola
            // cadena "Artista - Titulo" cortada por el guion (hay titulos con guiones).
            public void TituloArtista(out string titulo, out string artista)
            {
                if (IsVideo)
                {
                    string disc = (Disc != null && !string.IsNullOrEmpty(Disc.Artist)) ? Disc.Artist : "";
                    string file = "";
                    try { file = System.IO.Path.GetFileNameWithoutExtension(VideoPath); } catch { }
                    titulo = (file.Length > 0) ? file : disc;
                    artista = "\u25BA Video" + ((disc.Length > 0 && file.Length > 0) ? ("  -  " + disc) : "");
                    return;
                }
                titulo = (Song != null && !string.IsNullOrEmpty(Song.Title)) ? Song.Title : "";
                artista = (Song != null && !string.IsNullOrEmpty(Song.Artist)) ? Song.Artist : "";
            }
        }

        // Un archivo de video dentro de un disco; en la lista se ve solo el nombre sin extension
        private class VideoItem
        {
            public string Path;
            public VideoItem(string p) { Path = p; }
            public override string ToString()
            {
                try { return System.IO.Path.GetFileNameWithoutExtension(Path); }
                catch { return Path; }
            }
        }

        // ==========  CUBO DE LA CANCION (gira + se inclina)  ==========
        private class CubeBox : Control
        {
            public Image Cover;
            public double Angle;
            public double Phase;

            // ---------- EL RELEVO ----------
            // Al entrar la siguiente cancion, la portada del cubito de abajo se cambiaba DE GOLPE: un
            // cuadro con una y el siguiente con otra. A dos metros, de noche y con los amigos hablando,
            // eso no es un cambio: es que de pronto hay otra cosa ahi y nadie sabe desde cuando.
            //
            // Ahora el cubo da MEDIA VUELTA y la portada nueva aparece en el camino. Y el momento del
            // cambio no es uno cualquiera: a la mitad el cubo lleva 90 grados girados, y como las cuatro
            // caras llevan la misma imagen, 90 grados dejan el cubo con EXACTAMENTE la misma silueta que
            // al empezar. Asi el cambio no puede dar un salto de forma -solo cambia la imagen-, y cambia
            // justo en el punto mas rapido del giro, que es cuando menos se le mira la cara.
            //
            // Y con tarjeta grafica sale gratis: el panel ya lee Angle y Cover en cada cuadro, asi que
            // no hay ni una linea de dibujo nueva.
            private const int RelMs = 420;
            private int relTick;          // 0 = no hay relevo en marcha
            private Image relNueva;       // la portada que entra
            private double relGirado;     // cuanto lleva puesto de la media vuelta

            public void Relevo(Image nueva)
            {
                if (relTick != 0 && object.ReferenceEquals(relNueva, nueva)) return;   // esa ya viene en camino
                relNueva = nueva;
                relGirado = 0;
                relTick = Environment.TickCount; if (relTick == 0) relTick = 1;
            }
            public bool Girando { get { return relTick != 0; } }

            // Avanza el giro. Sin relevo, el paso de siempre. Con relevo, ademas, la media vuelta.
            // El giro lo lleva el cubo y no el reloj de la pantalla: si no, habria que repetir la cuenta
            // de la media vuelta en los dos sitios desde donde se le da cuerda.
            public void Avanza(double paso)
            {
                Angle += paso;
                if (relTick == 0) return;
                int dt = Environment.TickCount - relTick;
                if (dt < 0) dt = 0;
                double u = (dt >= RelMs) ? 1.0 : (dt / (double)RelMs);
                double e = u * u * (3.0 - 2.0 * u);        // arranca y frena suave; a la mitad es donde mas corre
                double meta = Math.PI * e;
                Angle += meta - relGirado;                 // lo que falte para ir por donde toca
                relGirado = meta;
                if (relNueva != null && e >= 0.5) { Cover = relNueva; relNueva = null; }
                if (u >= 1.0) relTick = 0;
            }

            public CubeBox()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.FromArgb(10, 15, 44);
            }

            protected override void OnPaint(PaintEventArgs e)
            {
                Graphics g = e.Graphics;
                if (this.BackColor.A == 255) g.Clear(this.BackColor);
                int w = Width, h = Height;
                if (w < 12 || h < 12) return;
                g.InterpolationMode = InterpolationMode.Bilinear;
                g.SmoothingMode = SmoothingMode.AntiAlias;

                int side = (int)(Math.Min(w, h) * 0.78);
                Rectangle area = new Rectangle((w - side) / 2, (h - side) / 2, side, side);

                float cx = w / 2f, cy = h / 2f;
                float tilt = (float)(10.0 * Math.Sin(Phase * 0.9));
                GraphicsState st = g.Save();
                g.TranslateTransform(cx, cy);
                g.RotateTransform(tilt);
                g.TranslateTransform(-cx, -cy);
                Cube.Draw(g, area, Cover, Angle);
                g.Restore(st);
            }
        }

        // ==========  TIRA DE LETRAS (con brillo animado)  ==========
        // Barra de paginas de la lista de canciones: "Pagina X de Y" al centro, y a los lados las
        // instrucciones VARIABLES con flechas DIBUJADAS (la fuente de XP no trae flechas unicode):
        //   [<] pagina 1        Pagina 2 de 3        pagina 3 [>]
        private class SongPagerBar : Control
        {
            private int pagina = 0; // pagina actual (desde 0)
            public int Pages = 1;   // total de paginas
            private Font pgFont;    // fuente cacheada (esta barra se redibuja al paginar / con el brillo)

            // "Pagina 2 de 5" cambiaba de golpe mientras la lista de debajo se deslizaba, y las dos cosas
            // contaban lo mismo yendo cada una por su lado. Ahora el letrero acompana a la lista: el numero
            // viejo se va hacia el mismo lado y el nuevo entra detras, con la MISMA curva y la misma duracion.
            private int animTick = -1; private int pagAnt = 0; private float animDir;
            public int Page
            {
                get { return pagina; }
                set
                {
                    if (value == pagina) return;
                    animDir = (value > pagina) ? 1f : -1f;
                    pagAnt = pagina; pagina = value; animTick = Environment.TickCount;
                }
            }
            public bool Animando { get { return animTick >= 0 && Environment.TickCount - animTick < SongListView.SlideMs; } }
            public float Paso
            {
                get
                {
                    if (animTick < 0) return 1f;
                    int dt = Environment.TickCount - animTick;
                    return (dt >= SongListView.SlideMs) ? 1f : (dt / (float)SongListView.SlideMs);
                }
            }
            // Cuanto falta por recorrer, con la curva de la lista. Cero = ya llego.
            private float FaltaAhora()
            {
                if (animTick < 0) return 0f;
                int dt = Environment.TickCount - animTick;
                if (dt < 0 || dt >= SongListView.SlideMs) { animTick = -1; return 0f; }
                return SongListView.CurvaLista(dt);
            }
            // Al abrir un disco el letrero se pone donde toque, sin viaje.
            public void PonSinAnimar(int p) { pagina = p; animTick = -1; }

            public SongPagerBar()
            {
                SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint |
                         ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }
            // Dibuja la barra de paginas en cualquier Graphics (el control, o la textura de UI del modo GPU).
            public void RenderContent(Graphics g)
            {
                int w = Width, h = Height;
                g.FillRectangle(CB(BackColor), 0, 0, w, h);   // pincel reusable (mutado)
                if (Pages <= 1 || w < 60 || h < 10) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                int cy = h / 2;
                Color txt = Color.FromArgb(228, 236, 252);
                Color dim = Color.FromArgb(175, 188, 215);
                Color yellow = Color.FromArgb(242, 206, 72);   // mismo amarillo que la cruceta izq/der
                if (pgFont == null) pgFont = new Font(FontFamily.GenericSansSerif, 9.5f, FontStyle.Bold);
                Font f = pgFont;
                {
                    // Centro: Pagina X de Y. Mientras se hojea, el numero viejo sale y el nuevo entra; el
                    // viaje es corto (un tercio del ancho) porque lo que tiene que leerse es el numero, no
                    // el movimiento. Las flechas de los lados NO viajan: son botones y deben quedarse quietas.
                    float falta = FaltaAhora();
                    string c = "Pagina " + (pagina + 1) + " de " + Pages;
                    SizeF cs = g.MeasureString(c, f);
                    float viaje = w / 3f;
                    if (falta > 0.001f)
                    {
                        string cAnt = "Pagina " + (pagAnt + 1) + " de " + Pages;
                        SizeF as_ = g.MeasureString(cAnt, f);
                        int aAnt = (int)(255f * falta); if (aAnt > 255) aAnt = 255; else if (aAnt < 0) aAnt = 0;
                        g.DrawString(cAnt, f, CB(Color.FromArgb(aAnt, txt)),
                                     (w - as_.Width) / 2f - animDir * viaje * (1f - falta), cy - as_.Height / 2f);
                    }
                    int aNue = (int)(255f * (1f - falta)); if (aNue > 255) aNue = 255; else if (aNue < 0) aNue = 0;
                    g.DrawString(c, f, CB(Color.FromArgb(aNue, txt)),
                                 (w - cs.Width) / 2f + animDir * viaje * falta, cy - cs.Height / 2f);

                    // Izquierda: [<] pagina anterior (solo si existe)
                    if (Page > 0)
                    {
                        float x = 4;
                        x = CtrlDirLeft(g, x, cy, 11, yellow) + 5;
                        CtrlTxt(g, f, "pagina " + Page, x, cy, dim);
                    }
                    // Derecha: pagina siguiente [>] (solo si existe)
                    if (Page < Pages - 1)
                    {
                        string r = "pagina " + (Page + 2);
                        SizeF rs = g.MeasureString(r, f);
                        float xr = w - 4 - 11 - 5 - rs.Width;
                        xr = CtrlTxt(g, f, r, xr, cy, dim) + 5;
                        CtrlDirRight(g, xr, cy, 11, yellow);
                    }
                }
            }
        }

        private class LetterBar : Control
        {
            private SolidBrush pulseBrush; private Pen pulsePen;                       // resaltado de letra (reusables)
            private GraphicsPath pulsePath; private RectangleF pulseBox = RectangleF.Empty;  // trayectoria cacheada
            private GraphicsPath goldPath; private RectangleF goldBox = RectangleF.Empty;    // marcador TOP dorado
            private SolidBrush goldBrush; private Pen goldPen; private SolidBrush goldTextBrush;
            private Bitmap stripCache; private int scW = -1, scH = -1; private char scCur = '\0';
            private string scLetters; private int scAvailN = -2; private int scDatos = 0;     // firma de la tira cacheada
            private Font fMain, fVideo, fNum;
            private float fontSlot = -1f, fontAlto = -1f;   // cuerpos elegidos, y para que hueco de ancho y alto
            private string lblVideo = "VIDEO";                          // palabra, o simbolo si no cabe
            private StringFormat sfCen; private SolidBrush whiteB;
            public string Letters = "\u2605#ABCDEFGHIJKLMNOPQRSTUVWXYZ\u25BA";
            // AL CAMBIAR DE LETRA la capsula se DESLIZA de la casilla que dejas a la que eliges, en vez de
            // aparecer de golpe al otro lado de la barra. Dura poco y frena al llegar: eso es lo que hace que
            // se lea como un movimiento y no como un parpadeo.
            private const int AnimMs = 190;
            private char cur = '#', animDesde = '\0';
            private readonly System.Diagnostics.Stopwatch animReloj = new System.Diagnostics.Stopwatch();
            public char Current
            {
                get { return cur; }
                set
                {
                    if (value == cur) return;
                    // Solo se desliza si las dos casillas existen; si no, cambio seco (que es lo que habia).
                    if (Letters != null && Letters.IndexOf(cur) >= 0 && Letters.IndexOf(value) >= 0)
                    { animDesde = cur; animReloj.Reset(); animReloj.Start(); }
                    cur = value;
                }
            }
            // 0 = acaba de salir, 1 = ya llego. Fuera de la animacion vale 1.
            public float AnimPaso
            {
                get
                {
                    if (!animReloj.IsRunning) return 1f;
                    double ms = animReloj.Elapsed.TotalMilliseconds;
                    if (ms >= AnimMs) { animReloj.Stop(); return 1f; }
                    float t = (float)(ms / AnimMs);
                    float q = 1f - t;
                    return 1f - q * q * q;   // frena al llegar
                }
            }
            // Ojo: NO vale con preguntarle al cronometro si anda, porque quien lo para es la lectura de
            // AnimPaso. Si nadie la ha leido todavia, el cronometro sigue andando aunque el tiempo ya haya
            // pasado, y entonces "hay animacion" mentiria (y en modo GPU obligaria a rehacer la textura para
            // siempre). Se mira el tiempo, que es la verdad.
            public bool AnimViva
            {
                get { return animReloj.IsRunning && animReloj.Elapsed.TotalMilliseconds < AnimMs; }
            }
            public double Phase = 0;
            public HashSet<char> Available;
            // Cuantas canciones hay detras de cada letra, y de que color es el genero que MANDA en ella. Form1
            // los REEMPLAZA enteros cuando el rastreo de fondo aprende mas generos (nunca los toca por dentro),
            // asi que aqui se pueden leer sin candado: o se ve el diccionario viejo o se ve el nuevo, entero.
            public Dictionary<char, int> Counts;
            public Dictionary<char, Color> Tints;
            public Action<char> OnPick;

            public LetterBar()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
            }

            protected override void OnMouseClick(MouseEventArgs e)
            {
                int n = Letters.Length;
                if (n == 0 || Width <= 0) { base.OnMouseClick(e); return; }
                // CON DECIMALES, igual que se DIBUJA. Con division entera la casilla en la que crees pinchar y
                // la que la barra dibuja se iban separando hacia la derecha -en 1024 casi un tercio de casilla
                // al final, y con un video al lado MAS DE UNA CASILLA ENTERA-: pinchabas una letra y te llevaba
                // a la de al lado.
                float slot = (float)Width / n;
                int i = (int)(e.X / slot);
                if (i < 0) i = 0; else if (i >= n) i = n - 1;
                if (OnPick != null) OnPick(Letters[i]);
                base.OnMouseClick(e);
            }

            private void EnsureRes()
            {
                if (whiteB == null) whiteB = new SolidBrush(Color.White);
                if (sfCen == null)
                {
                    sfCen = new StringFormat();
                    sfCen.Alignment = StringAlignment.Center; sfCen.LineAlignment = StringAlignment.Center;
                    sfCen.FormatFlags = StringFormatFlags.NoWrap;   // una etiqueta JAMAS se parte en renglones
                }
            }

            // ---------- REPARTO DE ALTO ----------
            // Debajo de cada letra va su numero de canciones, pero solo si hay sitio (con un video al lado la
            // barra se queda a la mitad de ancho y ahi no se leeria) Y solo si de verdad hay algun numero que
            // ensenar: reservarle el renglon a un numero que nunca llega deja las letras subidas, pegadas al
            // techo de la barra y con un hueco vacio debajo.
            private bool HayCuenta(float slot, int h)
            {
                if (Counts == null || slot < 21f || h < 34 || Letters == null) return false;
                return HayNumeros();
            }
            private float AltoCuenta(float slot, int h) { return HayCuenta(slot, h) ? h * 0.30f : 0f; }

            // EL CUERPO DE LETRA SE ELIGE SEGUN EL HUECO QUE HAY. "VIDEO" mide 36 px y la casilla 34 con la
            // pantalla entera; y con un video puesto al lado la barra se encoge a la mitad, asi que no cabe.
            // Antes se dibujaba con un cuerpo fijo dentro de su casilla y GDI+ lo partia en varios renglones,
            // que ademas no cabian de alto: se veia "VI / D / EO" recortado. Ahora se busca el cuerpo mas
            // grande con el que QUEPA, y como el formato ya no deja partir renglon, no puede volver a pasar.
            private void AjustaFuentes(Graphics g, float slot, int h)
            {
                float altoL = h - AltoCuenta(slot, h);
                if (fMain != null && Math.Abs(fontSlot - slot) < 0.5f && Math.Abs(fontAlto - altoL) < 0.5f) return;
                if (fMain != null) fMain.Dispose();
                if (fVideo != null) fVideo.Dispose();
                if (fNum != null) { fNum.Dispose(); fNum = null; }
                float hueco = slot - 2f;
                // EL CUERPO SALE DEL ALTO DE LA BARRA, no de un numero fijo. Con 40 px de barra da los 10.5
                // puntos de siempre, asi que en 1024x768 no cambia nada; pero en una pantalla ancha, donde la
                // barra crece, las letras crecen con ella en vez de quedarse chiquitas y perdidas en medio de
                // una casilla de 100 pixeles.
                float cuerpo = altoL * 0.375f;
                fMain = CuerpoQueQuepa(g, "W", hueco, cuerpo);
                // La estrella no lleva cuerpo de letra: se dibuja, y su tamano sale de la casilla. Sale del
                // ALTO -como el de las letras- y se recorta si la casilla es tan estrecha que no cabria.
                radioEstrella = altoL * 0.25f;
                if (radioEstrella > hueco * 0.50f) radioEstrella = hueco * 0.50f;
                if (radioEstrella < 2f) radioEstrella = 2f;
                Font fPal = CuerpoQueQuepa(g, "VIDEO", hueco, cuerpo * 0.72f);
                if (g.MeasureString("VIDEO", fPal).Width <= hueco)
                {
                    lblVideo = "VIDEO"; fVideo = fPal;
                }
                else
                {
                    // Ni bajando el cuerpo cabe la palabra: ahi se pone el SIMBOLO, que ocupa lo mismo que una
                    // letra, se lee igual de lejos y dice lo mismo.
                    fPal.Dispose();
                    lblVideo = "\u25BA";
                    fVideo = CuerpoQueQuepa(g, "\u25BA", hueco, cuerpo);
                }
                if (AltoCuenta(slot, h) > 0f) fNum = CuerpoQueQuepa(g, "8888", hueco, cuerpo * 0.62f);
                fontSlot = slot; fontAlto = altoL;
            }
            // El cuerpo pedido, encogido de medio en medio lo justo para que 'muestra' quepa a lo ancho de su
            // casilla. Nunca baja de 5 puntos: por debajo no se leeria de todos modos.
            private Font CuerpoQueQuepa(Graphics g, string muestra, float hueco, float cuerpo)
            {
                if (!(cuerpo > 5f)) cuerpo = 5f;
                for (; ; )
                {
                    Font f = new Font(this.Font.FontFamily, cuerpo, FontStyle.Bold);
                    if (cuerpo <= 5f || g.MeasureString(muestra, f).Width <= hueco) return f;
                    f.Dispose();
                    cuerpo -= 0.5f;
                }
            }

            // ---------- COLOR DE CADA LETRA ----------
            // El del genero que manda dentro de ella, pero SUBIDO hacia el blanco: el color puro de un genero
            // oscuro (el metal es rojo sangre, el gotico morado profundo) no se leeria en una franja de 40
            // pixeles vista de pie a dos metros. Asi conserva la familia y se sigue leyendo de lejos.
            private Color TonoLetra(char ch, bool hay)
            {
                if (!hay) return Color.FromArgb(104, 114, 144);          // sin canciones: apagada, como siempre
                Color g;
                if (Tints == null || !Tints.TryGetValue(ch, out g)) return Color.FromArgb(232, 238, 250);
                return Color.FromArgb(255,
                    g.R + (int)((255 - g.R) * 0.45f),
                    g.G + (int)((255 - g.G) * 0.45f),
                    g.B + (int)((255 - g.B) * 0.45f));
            }

            // Firma de los datos que se pintan en la tira: si cambia, hay que rehacerla. El rastreo de fondo
            // va aprendiendo generos y contando canciones, y la barra tiene que enterarse.
            public int DatosSig() { return FirmaDatos(); }

            private Dictionary<char, int> fCnt; private Dictionary<char, Color> fTin;
            private int fVal, fNCnt = -1, fNTin = -1; private bool fOk;
            private int FirmaDatos()
            {
                // Se recorrian 29 letras con dos busquedas de diccionario cada una, DOS veces por cuadro: al
                // dibujar y al firmar la textura de la GPU. Y el resultado casi nunca cambia -solo cuando el
                // paseo de fondo aprende algo-. Como Form1 REEMPLAZA los diccionarios enteros (nunca los toca
                // por dentro), basta con mirar si siguen siendo los mismos objetos y del mismo tamano.
                int nC = (Counts == null) ? -1 : Counts.Count, nT = (Tints == null) ? -1 : Tints.Count;
                if (fOk && ReferenceEquals(fCnt, Counts) && ReferenceEquals(fTin, Tints) && fNCnt == nC && fNTin == nT)
                    return fVal;
                fVal = CalculaFirma();
                fCnt = Counts; fTin = Tints; fNCnt = nC; fNTin = nT; fOk = true;
                return fVal;
            }
            private int CalculaFirma()
            {
                int f = 17;
                for (int i = 0; i < Letters.Length; i++)
                {
                    char c = Letters[i];
                    int n = 0; if (Counts != null) Counts.TryGetValue(c, out n);
                    int t = 0; Color col;
                    if (Tints != null && Tints.TryGetValue(c, out col)) t = col.ToArgb();
                    f = f * 31 + n; f = f * 31 + t;
                }
                return f;
            }

            // Lo mismo para "hay algun numero que ensenar": tambien recorria las 29 letras, y se pregunta
            // varias veces por cuadro (al repartir el alto, al elegir los cuerpos y al situar los halos).
            private bool hcVal; private bool hcOk;
            private Dictionary<char, int> hcCnt; private int hcN = -1;
            private bool HayNumeros()
            {
                int nC = (Counts == null) ? -1 : Counts.Count;
                if (hcOk && ReferenceEquals(hcCnt, Counts) && hcN == nC) return hcVal;
                bool r = false;
                if (Counts != null && Letters != null)
                    for (int i = 0; i < Letters.Length; i++)
                    {
                        int n;
                        if (Counts.TryGetValue(Letters[i], out n) && n > 0) { r = true; break; }
                    }
                hcVal = r; hcCnt = Counts; hcN = nC; hcOk = true;
                return r;
            }

            // ---------- EL RIEL DE VIDRIO ----------
            // La fila se apoya en un riel oscuro con un brillo arriba: deja de flotar sobre el fondo y se lee
            // como una pieza de la maquina, no como texto suelto encima del cielo.
            private void Riel(Graphics g, int w, int h)
            {
                RectangleF r = new RectangleF(0, 1, w - 1, h - 2);
                using (GraphicsPath p = RoundRectF(r, 12))
                {
                    using (LinearGradientBrush lb = new LinearGradientBrush(
                               new RectangleF(r.X, r.Y, r.Width, r.Height + 1),
                               Color.FromArgb(96, 34, 46, 88), Color.FromArgb(64, 14, 20, 46), 90f))
                        g.FillPath(lb, p);
                    using (Pen bo = new Pen(Color.FromArgb(58, 140, 180, 255), 1f)) g.DrawPath(bo, p);
                }
                float hb = h * 0.32f;
                using (GraphicsPath p2 = RoundRectF(new RectangleF(3, 2.5f, w - 7, hb), 7))
                using (LinearGradientBrush hl = new LinearGradientBrush(new RectangleF(3, 2.5f, w - 7, hb + 1),
                           Color.FromArgb(34, 190, 215, 255), Color.FromArgb(0, 190, 215, 255), 90f))
                    g.FillPath(hl, p2);
            }

            // LA ESTRELLA DE "LO MAS SONADO" SE DIBUJA, NO SE ESCRIBE.
            //
            // Antes se escribia, como se escribe una A: se le pedia a la letra de Windows el simbolo "estrella
            // negra". Y en Windows XP eso no funciona. La rocola pide Segoe UI, que en XP no existe, Windows le
            // da Tahoma, y Tahoma de XP trae el juego de simbolos WGL4, donde la estrella NO esta. Cuando a
            // Windows le piden un simbolo que no tiene, pinta un rectangulo vacio: eso era lo que se veia en la
            // rocola del bar, un rectangulo en el sitio de la estrella. En la otra maquina si se veia bien, que
            // es por lo que no se noto.
            //
            // Dibujada con lineas se ve igual en cualquier maquina, no depende de las letras que tenga Windows
            // instaladas, y ademas cuesta menos que escribir texto.
            private static readonly PointF[] estrellaUnidad = FormaEstrella();
            private readonly PointF[] estrellaPts = new PointF[10];   // se rellena y se reusa: cero basura por cuadro
            private float radioEstrella = 6f;
            private static PointF[] FormaEstrella()
            {
                // Cinco puntas: se va alternando el radio de fuera y el de dentro cada 36 grados. La proporcion
                // 0.382 es la de siempre, la misma que usan las estrellas de las letras de Windows.
                PointF[] p = new PointF[10];
                const double dentro = 0.382;
                for (int i = 0; i < 10; i++)
                {
                    double a = (-90 + i * 36) * Math.PI / 180.0;
                    double r = ((i & 1) == 0) ? 1.0 : dentro;
                    // El 0.09549 baja la estrella para que quede centrada POR SU DIBUJO: la punta de arriba
                    // llega mas lejos que las dos patas de abajo, asi que sin esto se veria alta.
                    p[i] = new PointF((float)(Math.Cos(a) * r), (float)(Math.Sin(a) * r + 0.09549));
                }
                return p;
            }
            // Rellena la estrella centrada en 'r' y corrida (dx,dy). Es el reemplazo exacto del texto de antes.
            private void Estrella(Graphics g, Brush b, RectangleF r, float dx, float dy)
            {
                float cx = r.X + r.Width * 0.5f + dx, cy = r.Y + r.Height * 0.5f + dy, ra = radioEstrella;
                for (int i = 0; i < 10; i++)
                    estrellaPts[i] = new PointF(cx + estrellaUnidad[i].X * ra, cy + estrellaUnidad[i].Y * ra);
                g.FillPolygon(b, estrellaPts);
            }
            // La estrella con el mismo RELIEVE que las letras: sombra debajo y filo claro arriba.
            private void EstrellaGrabada(Graphics g, SolidBrush b, RectangleF r, Color tono, bool hay)
            {
                b.Color = Color.FromArgb(hay ? 150 : 70, 0, 0, 0);
                Estrella(g, b, r, 0f, 1.4f);
                b.Color = hay ? Color.FromArgb(66, 190, 215, 255) : Color.FromArgb(26, 150, 170, 210);
                Estrella(g, b, r, 0f, -1.1f);
                b.Color = tono;
                Estrella(g, b, r, 0f, 0f);
            }

            // Una letra con RELIEVE: sombra debajo y filo claro arriba, como grabada en cristal.
            private void Grabada(Graphics g, SolidBrush b, string txt, Font f, RectangleF r, Color tono, bool hay)
            {
                b.Color = Color.FromArgb(hay ? 150 : 70, 0, 0, 0);
                g.DrawString(txt, f, b, new RectangleF(r.X, r.Y + 1.4f, r.Width, r.Height), sfCen);
                b.Color = hay ? Color.FromArgb(66, 190, 215, 255) : Color.FromArgb(26, 150, 170, 210);
                g.DrawString(txt, f, b, new RectangleF(r.X, r.Y - 1.1f, r.Width, r.Height), sfCen);
                b.Color = tono;
                g.DrawString(txt, f, b, r, sfCen);
            }

            // Dibuja el riel y TODAS las letras (menos la actual y la estrella, que van en vivo) en una tira
            // reusable. Solo se rehace al cambiar de letra, de tamano, de disponibles o de datos.
            private void RebuildStrip(int w, int h, int n, float slot)
            {
                if (stripCache == null || stripCache.Width != w || stripCache.Height != h)
                {
                    if (stripCache != null) stripCache.Dispose();
                    stripCache = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                }
                float bajo = AltoCuenta(slot, h);
                float altoL = h - bajo;
                using (Graphics g = Graphics.FromImage(stripCache))
                using (SolidBrush tb = new SolidBrush(Color.White))
                {
                    g.Clear(Color.Transparent);
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    Riel(g, w, h);
                    // Una raya finisima entre casilla y casilla: ORDENA la fila sin llamar la atencion.
                    using (Pen sep = new Pen(Color.FromArgb(24, 150, 175, 225)))
                        for (int i = 1; i < n; i++)
                            g.DrawLine(sep, i * slot, 10, i * slot, h - 10);
                    for (int i = 0; i < n; i++)
                    {
                        char ch = Letters[i];
                        bool isTop = (ch == TopMark);
                        bool avail = (Available == null) || Available.Contains(ch);
                        RectangleF rL = new RectangleF(i * slot, 0, slot, altoL);
                        if (ch != Current && !(isTop && avail))   // la actual y la estrella encendida van en vivo
                        {
                            bool isVideo = (ch == VideoMark);
                            if (isTop) EstrellaGrabada(g, tb, rL, Color.FromArgb(122, 116, 96), avail);
                            else Grabada(g, tb, isVideo ? lblVideo : ch.ToString(), isVideo ? fVideo : fMain,
                                         rL, TonoLetra(ch, avail), avail);
                        }
                        if (bajo > 0f && fNum != null) Cuenta(g, tb, ch, i, slot, h, bajo, avail);
                    }
                }
            }

            // El numero de canciones que hay detras de una letra, debajo de ella y en su mismo color pero mas
            // apagado: el cliente ve de un vistazo donde esta lo gordo y deja de entrar a letras casi vacias.
            private void Cuenta(Graphics g, SolidBrush b, char ch, int i, float slot, int h, float bajo, bool avail)
            {
                int cuantas = 0;
                if (Counts == null || !Counts.TryGetValue(ch, out cuantas) || cuantas <= 0) return;
                Color tono = TonoLetra(ch, avail);
                b.Color = Color.FromArgb(avail ? 185 : 105,
                                         (tono.R * 3 + 90) / 4, (tono.G * 3 + 105) / 4, (tono.B * 3 + 150) / 4);
                g.DrawString(TextoCuenta(cuantas), fNum, b, new RectangleF(i * slot, h - bajo - 1f, slot, bajo), sfCen);
            }
            // El hueco esta medido para CUATRO cifras. Una biblioteca con mas de 9999 canciones en una sola
            // letra escribiria un numero mas largo del que cabe, asi que a partir de ahi se dice en miles.
            private static string TextoCuenta(int n)
            {
                if (n < 10000) return n.ToString();
                int miles = n / 1000;
                return (miles > 999 ? 999 : miles) + "k";
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics, false); }
            // Casilla de la letra ACTUAL (para el pulso por GPU): centro/radio en coords del control.
            // false si no aplica (la actual es TOP, que lleva su propio halo dorado, o no esta en la tira).
            public bool GetCurrentGlow(out float cx, out float cy, out float r)
            {
                cx = cy = r = 0f;
                int n = Letters.Length; if (n == 0 || Width < 4 || Height < 4) return false;
                if (Current == TopMark) return false;
                int i = Letters.IndexOf(Current); if (i < 0) return false;
                float slot = (float)Width / n;
                float altoL = Height - AltoCuenta(slot, Height);
                cx = XCapsula(i, slot) + slot / 2f; cy = altoL / 2f;   // mientras se desliza, el halo va con ella
                r = Math.Max(slot, altoL) * 0.75f;
                return true;
            }
            // Casilla del marcador TOP (para su dorado pulsante por GPU); false si TOP no esta disponible.
            public bool GetTopGlow(out float cx, out float cy, out float r)
            {
                cx = cy = r = 0f;
                int n = Letters.Length; if (n == 0 || Width < 4 || Height < 4) return false;
                if (Available == null || !Available.Contains(TopMark)) return false;
                int i = Letters.IndexOf(TopMark); if (i < 0) return false;
                float slot = (float)Width / n;
                float altoL = Height - AltoCuenta(slot, Height);
                cx = i * slot + slot / 2f; cy = altoL / 2f;
                r = Math.Max(slot, altoL) * 0.75f;
                return true;
            }
            // QUE TROZOS DE LA BARRA CAMBIAN DE UN CUADRO A OTRO.
            //
            // Solo dos laten: la casilla elegida y la estrellita de LO MAS SONADO. Las otras veintiocho letras
            // viven en una tira ya horneada que no se mueve. Repintar la barra ENTERA por esos dos latidos
            // costaba el triple de lo necesario -0.35 ms contra 0.11 en una barra de 1024 px- y eso son
            // veinticuatro veces por segundo, todo el rato que la rocola esta encendida.
            //
            // Devuelve false cuando hay que repintarla entera: mientras la capsula viaja de una letra a otra
            // cambia media barra, y ahi no hay atajo que valga.
            public bool ZonasLatido(out Rectangle uno, out Rectangle dos)
            {
                uno = Rectangle.Empty; dos = Rectangle.Empty;
                if (Width < 8 || Height < 8) return false;
                if (AnimViva) return false;
                float cx, cy, r;
                if (GetCurrentGlow(out cx, out cy, out r)) uno = CajaLatido(cx, r);
                if (GetTopGlow(out cx, out cy, out r)) dos = CajaLatido(cx, r);
                return uno.Width > 0 || dos.Width > 0;
            }
            private Rectangle CajaLatido(float cx, float r)
            {
                int x = (int)(cx - r) - 2, an = (int)(r * 2) + 5;   // con aire: el halo se sale de la casilla
                if (x < 0) { an += x; x = 0; }
                if (x + an > Width) an = Width - x;
                return (an < 1) ? Rectangle.Empty : new Rectangle(x, 0, an, Height);
            }

            // La X de la casilla elegida AHORA MISMO: mientras dura el deslizamiento va entre la casilla que
            // se deja y la que se elige; el resto del tiempo es la de destino y punto.
            private float XCapsula(int iDestino, float slot)
            {
                float paso = AnimPaso;
                if (paso >= 1f) return iDestino * slot;
                int iDe = (Letters != null) ? Letters.IndexOf(animDesde) : -1;
                if (iDe < 0) return iDestino * slot;
                return (iDe + (iDestino - iDe) * paso) * slot;
            }

            public void RenderContent(Graphics g) { RenderContent(g, false); }
            // Dibuja la barra de letras en cualquier Graphics (el control, o la textura de UI del modo GPU).
            // forGpu=true: brillos FIJOS (mitad del pulso) en la textura; el pulso vivo lo ponen los halos por
            // quad (GetCurrentGlow/GetTopGlow) -> la textura de UI ya no se rehace ~13 veces/seg por esta barra.
            public void RenderContent(Graphics g, bool forGpu)
            {
                int w = Width, h = Height, n = (Letters == null) ? 0 : Letters.Length;
                if (w < 4 || h < 4 || n == 0) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                float slot = (float)w / n;
                double pulse = forGpu ? 0.45 : 0.5 + 0.5 * Math.Sin(Phase * 2.2);
                EnsureRes();
                AjustaFuentes(g, slot, h);
                float bajo = AltoCuenta(slot, h);
                float altoL = h - bajo;

                // TIRA CACHEADA: el riel y las ~28 letras solo se redibujan al cambiar letra/tamano/datos.
                // Por cuadro: copiar la tira + la letra ACTUAL con su capsula + la estrella (antes: ~28 textos).
                int availN = (Available == null) ? -1 : Available.Count;
                int datos = FirmaDatos();
                if (stripCache == null || scW != w || scH != h || scCur != Current || scLetters != Letters
                    || scAvailN != availN || scDatos != datos)
                {
                    RebuildStrip(w, h, n, slot);
                    scW = w; scH = h; scCur = Current; scLetters = Letters; scAvailN = availN; scDatos = datos;
                }
                g.DrawImageUnscaled(stripCache, 0, 0);

                // LA CASILLA ELEGIDA: una capsula de NEON, del mismo material que la aurora del fondo -halo por
                // fuera, contorno encendido y el centro casi vacio- en vez de una caja azul plana.
                for (int i = 0; i < n; i++)
                {
                    char ch = Letters[i];
                    if (ch != Current || ch == TopMark) continue;   // TOP lo dibuja el bloque dorado
                    bool isVideo = (ch == VideoMark);
                    string lbl = isVideo ? lblVideo : ch.ToString();
                    Font useF = isVideo ? fVideo : fMain;
                    float paso = AnimPaso, xCap = XCapsula(i, slot);
                    RectangleF slotRect = new RectangleF(i * slot, 0, slot, altoL);
                    // Mientras la capsula viaja, la letra de destino no puede quedarse en blanco: la tira
                    // cacheada la deja fuera (es la elegida), asi que aqui se dibuja con su color normal y se
                    // va poniendo blanca conforme la capsula llega.
                    if (paso < 1f)
                    {
                        // Se reusa la brocha de siempre: Grabada le pone el color que necesita, y mas abajo se
                        // le vuelve a poner el suyo antes de usarla. Una brocha nueva por cuadro seria basura
                        // para el recolector justo mientras algo se esta moviendo.
                        bool hayD = (Available == null) || Available.Contains(ch);
                        Grabada(g, whiteB, lbl, useF, slotRect, TonoLetra(ch, hayD), hayD);
                    }
                    RectangleF box = new RectangleF(xCap + 3.5f, 3.5f, slot - 7f, altoL - 7f);
                    if (pulsePath == null || box != pulseBox)   // misma casilla -> misma trayectoria
                    {
                        if (pulsePath != null) pulsePath.Dispose();
                        pulsePath = RoundRectF(box, 9);
                        pulseBox = box;
                    }
                    if (pulseBrush == null) pulseBrush = new SolidBrush(Color.Black);
                    if (pulsePen == null) pulsePen = new Pen(Color.Black, 2.6f);
                    pulsePen.LineJoin = LineJoin.Round;
                    for (int k = 5; k >= 1; k--)   // el halo: pasadas cada vez mas anchas y mas tenues
                    {
                        pulsePen.Color = Color.FromArgb(9 + (int)(pulse * 7 * (6 - k)), 120, 190, 255);
                        pulsePen.Width = k * 2.4f;
                        g.DrawPath(pulsePen, pulsePath);
                    }
                    pulseBrush.Color = Color.FromArgb(26 + (int)(pulse * 30), 70, 150, 240);
                    g.FillPath(pulseBrush, pulsePath);
                    pulsePen.Color = Color.FromArgb(120 + (int)(pulse * 70), 130, 200, 255); pulsePen.Width = 2.6f;
                    g.DrawPath(pulsePen, pulsePath);
                    pulsePen.Color = Color.FromArgb(215 + (int)(pulse * 40), 225, 242, 255); pulsePen.Width = 1.1f;
                    g.DrawPath(pulsePen, pulsePath);
                    whiteB.Color = (paso >= 1f) ? Color.White : Color.FromArgb((int)(255 * paso), 255, 255, 255);
                    g.DrawString(lbl, useF, whiteB, slotRect, sfCen);
                    break;
                }

                // LA ESTRELLITA DORADA de "lo mas sonado": siempre pulsando para llamar la atencion del
                // cliente (solo si hay algo dentro). Se dibuja en vivo este o no seleccionada.
                int topI = Letters.IndexOf(TopMark);
                if (topI >= 0 && Available != null && Available.Contains(TopMark))
                {
                    RectangleF gsl = new RectangleF(topI * slot, 0, slot, altoL);
                    double gpu = forGpu ? 0.5 : 0.5 + 0.5 * Math.Sin(Phase * 2.6);   // GPU: brillo FIJO en la textura (el pulso dorado lo pone el halo por quad, GetTopGlow)
                    bool topSel = (Current == TopMark);
                    if (goldTextBrush == null) goldTextBrush = new SolidBrush(Color.Black);
                    if (topSel)
                    {
                        // SELECCIONADA: capsula dorada, del mismo corte que la de neon de las letras.
                        RectangleF gbx = new RectangleF(XCapsula(topI, slot) + 3.5f, 3.5f, gsl.Width - 7f, altoL - 7f);
                        int ga = 80 + (int)(gpu * 150);
                        if (goldPath == null || gbx != goldBox) { if (goldPath != null) goldPath.Dispose(); goldPath = RoundRectF(gbx, 9); goldBox = gbx; }
                        if (goldBrush == null) goldBrush = new SolidBrush(Color.Black);
                        if (goldPen == null) goldPen = new Pen(Color.Black, 2.2f);
                        goldPen.LineJoin = LineJoin.Round;
                        goldBrush.Color = Color.FromArgb(ga, 255, 200, 40);
                        goldPen.Color = Color.FromArgb(235, 255, 228, 130); goldPen.Width = 2.2f;
                        g.FillPath(goldBrush, goldPath);
                        g.DrawPath(goldPen, goldPath);
                        goldTextBrush.Color = Color.White;
                        Estrella(g, goldTextBrush, gsl, 0f, 0f);
                    }
                    else
                    {
                        // NO seleccionada: brilla SOLO la estrella (sin caja, para no confundir con seleccion).
                        // halo dorado tenue (4 pasadas desplazadas) + la estrella dorada pulsante encima.
                        int hAlpha = 35 + (int)(gpu * 55);
                        goldTextBrush.Color = Color.FromArgb(hAlpha, 255, 205, 90);
                        Estrella(g, goldTextBrush, gsl, -1f, 0f);
                        Estrella(g, goldTextBrush, gsl, 1f, 0f);
                        Estrella(g, goldTextBrush, gsl, 0f, -1f);
                        Estrella(g, goldTextBrush, gsl, 0f, 1f);
                        int gb = 60 + (int)(gpu * 70); if (gb > 255) gb = 255;
                        goldTextBrush.Color = Color.FromArgb(255, 255, 210, gb);   // dorado pulsante brillante
                        Estrella(g, goldTextBrush, gsl, 0f, 0f);
                    }
                }
            }

            private static GraphicsPath RoundRectF(RectangleF r, int radius)
            {
                GraphicsPath p = new GraphicsPath();
                float d = radius * 2;
                if (d > r.Height) d = r.Height;
                if (d > r.Width) d = r.Width;
                if (d < 2) d = 2;
                p.AddArc(r.X, r.Y, d, d, 180, 90);
                p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
                p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
                p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
                p.CloseFigure();
                return p;
            }
        }

        // ==========  ENCABEZADO DE LA SECCION  ==========
        // Antes era una etiqueta de texto plano: "LO MAS SONADO    -    pagina 1 de 3". Ahora el nombre de la
        // seccion va en SU color -el mismo que la letra luce en la barra de arriba- y las paginas se ven de un
        // vistazo como puntitos: cuantas hay y en cual estas se sabe sin leer, que es lo que le sirve a alguien
        // que esta de pie delante de la maquina.
        private class HeaderView : Control
        {
            public string Section = "";
            public int Page = 0, Total = 1;
            public Color Accent = DefaultAccent;

            private Font fSec, fPag; private float fontAlto = -1f;
            private SolidBrush brocha; private StringFormat sfIzq;

            public HeaderView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
                this.TabStop = false;   // aqui no se pincha nada: antes era una etiqueta, que nunca tomaba el foco
            }

            private void EnsureRes(int h)
            {
                if (brocha == null) brocha = new SolidBrush(Color.White);
                if (sfIzq == null) sfIzq = CreaSfDibuja(StringAlignment.Near);
                if (fSec != null && Math.Abs(fontAlto - h) < 0.5f) return;
                if (fSec != null) fSec.Dispose();
                if (fPag != null) fPag.Dispose();
                // Los cuerpos salen del alto del propio encabezado: con 28 px dan los 12.5 puntos de siempre.
                fSec = new Font(this.Font.FontFamily, h * 0.446f, FontStyle.Bold);
                fPag = new Font(this.Font.FontFamily, h * 0.303f, FontStyle.Bold);
                fontAlto = h;
            }

            // El color del acento, subido hacia el blanco lo justo para que un genero oscuro se siga leyendo.
            private static Color Claro(Color c)
            {
                return Color.FromArgb(255, c.R + (int)((255 - c.R) * 0.40f),
                                           c.G + (int)((255 - c.G) * 0.40f),
                                           c.B + (int)((255 - c.B) * 0.40f));
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }
            public void RenderContent(Graphics g)
            {
                int w = Width, h = Height;
                if (w < 8 || h < 8) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                EnsureRes(h);
                Color ac = Claro(Accent);

                // SE MIDE TODO ANTES DE PINTAR NADA. Este encabezado comparte fila con las instrucciones, asi
                // que el sitio que le toca cambia con la pantalla. Y lo que quepa se pega a la DERECHA, para
                // que no quede colgando en medio de un hueco.
                float pw0 = Math.Max(3f, h * 0.13f);
                float anchoNombre = pw0 + h * 0.32f + AnchoTexto(g, Section, fSec) + 4f;
                int pag0 = Page; if (pag0 < 0) pag0 = 0; else if (Total > 0 && pag0 >= Total) pag0 = Total - 1;

                // LA RAYITA SEPARADORA se dibuja SIEMPRE que detras del nombre venga algo, lleve puntitos o no.
                // Su ancho estaba metido DENTRO de la cuenta de los puntitos, asi que en una letra con mas de
                // doce paginas -que no lleva puntitos- el reparto se quedaba corto justo por ella y el
                // "pagina X de Y" se caia entero... teniendo 150 px de sitio libre al lado. Eso era lo de
                // "LETRA B" sin numero de paginas, y por eso las letras con pocas paginas si se veian bien.
                // Ahora va por su cuenta y se cuenta siempre.
                float anchoSep = h * 0.5f;

                float r0 = Math.Max(2.2f, h * 0.115f), paso0 = r0 * 3.4f;
                // El punto de la pagina en la que estas lleva un halo alrededor, bastante mas ancho que el
                // punto. Se reservaba el punto pelado, asi que estando en la ultima pagina el halo se salia por
                // el borde y se veia cortado. Se reserva el halo.
                float halo0 = r0 * 1.35f * 2.1f;
                float anchoPuntos0 = (Total > 1 && Total <= 12) ? (halo0 + (Total - 1) * paso0 + halo0) : 0f;

                // EL NUMERO DE PAGINA SIEMPRE SE DICE. Antes era todo o nada: si "pagina 3 de 18" no cabia
                // entero no se dibujaba nada, y el cliente se quedaba sin saber cuantas paginas hay -que es
                // justo el dato que necesita para decidir si sigue pasando-. Ahora, si no cabe la frase larga,
                // se prueba una mas corta, y luego la mas corta de todas.
                string[] formas = new string[] { "pagina " + (pag0 + 1) + " de " + Total,
                                                 (pag0 + 1) + " de " + Total,
                                                 (pag0 + 1) + "/" + Total };
                float[] anchoForma = new float[formas.Length];
                for (int i = 0; i < formas.Length; i++) anchoForma[i] = h * 0.45f + AnchoTexto(g, formas[i], fPag) + 8f;

                // Se prueba con los puntitos puestos y, si aun asi no entra ninguna forma, se quitan: los
                // puntitos dicen en que pagina estas de un vistazo, pero el numero es el UNICO que dice cuantas
                // hay en total, asi que si hay que elegir gana el numero.
                bool conPuntos0 = anchoPuntos0 > 0f;
                int forma = -1;
                if (Total > 1)
                    for (int intento = 0; intento < 2 && forma < 0; intento++)
                    {
                        if (intento == 1) { if (!conPuntos0) break; conPuntos0 = false; }
                        float libre = w - anchoNombre - anchoSep - (conPuntos0 ? anchoPuntos0 : 0f);
                        for (int i = 0; i < formas.Length; i++)
                            if (anchoForma[i] <= libre) { forma = i; break; }
                    }
                if (conPuntos0 && anchoNombre + anchoSep + anchoPuntos0 > w) conPuntos0 = false;
                string txt0 = (forma >= 0) ? formas[forma] : "";
                bool algoDetras = conPuntos0 || forma >= 0;
                float total0 = anchoNombre + (algoDetras ? anchoSep : 0f)
                             + (conPuntos0 ? anchoPuntos0 : 0f) + ((forma >= 0) ? anchoForma[forma] : 0f);
                // Pegado a la derecha, con 2 px de aire: medir un texto y dibujarlo no dan exactamente lo mismo
                // -el dibujo se pasa como un pixel- y sin ese aire la ultima letra se salia de la caja.
                float x = (total0 + 2f < w) ? (w - total0 - 2f) : 0f;

                // Una pastilla del color de la seccion delante del nombre: ata el encabezado con la letra que
                // esta encendida arriba, para que se vea que hablan de lo mismo.
                float pw = Math.Max(3f, h * 0.13f), ph = h * 0.58f;
                using (SolidBrush pb = new SolidBrush(Color.FromArgb(230, ac)))
                using (GraphicsPath pp = Redondo(new RectangleF(x, (h - ph) / 2f, pw, ph), pw / 2f))
                    g.FillPath(pb, pp);
                x += pw + h * 0.32f;

                // EL NOMBRE MANDA, pero no puede comerse la fila entera: si no cabe con el cuerpo elegido, se
                // encoge hasta caber. Y lo que venga detras solo se dibuja SI CABE ENTERO; nada se dibuja "a
                // medias" ni se sale por la derecha.
                string sec = Section ?? "";
                Font fUsar = fSec; Font fApreta = null;
                float tope = Math.Max(10f, w - x);
                float anchoSec = AnchoTexto(g, sec, fUsar);
                if (anchoSec > tope)
                {
                    float cuerpo = fSec.SizeInPoints;
                    while (cuerpo > 6f)
                    {
                        cuerpo -= 0.5f;
                        if (fApreta != null) fApreta.Dispose();
                        fApreta = new Font(this.Font.FontFamily, cuerpo, FontStyle.Bold);
                        anchoSec = AnchoTexto(g, sec, fApreta);
                        if (anchoSec <= tope) break;
                    }
                    if (fApreta != null) fUsar = fApreta;
                }
                brocha.Color = Color.FromArgb(160, 0, 0, 0);
                g.DrawString(sec, fUsar, brocha, new RectangleF(x, 1.4f, tope, h), sfIzq);
                brocha.Color = ac;
                g.DrawString(sec, fUsar, brocha, new RectangleF(x, 0, tope, h), sfIzq);
                if (fApreta != null) fApreta.Dispose();
                x += anchoSec;

                if (!algoDetras) return;   // una sola pagina, o no cabe nada mas
                int pag = pag0;
                float r = r0, paso = paso0;
                bool conPuntos = conPuntos0;

                using (Pen sep = new Pen(Color.FromArgb(70, 150, 175, 225)))
                    g.DrawLine(sep, x, h * 0.26f, x, h * 0.74f);
                x += anchoSep;

                // LOS PUNTITOS. Con muchas paginas no caben ni se contarian de un vistazo, asi que a partir de
                // doce se dice con numeros y ya.
                if (conPuntos)
                {
                    float cy = h / 2f;
                    for (int i = 0; i < Total; i++)
                    {
                        float cx = x + halo0 + i * paso;
                        bool esta = (i == pag);
                        float rr = esta ? r * 1.35f : r;
                        if (esta)
                        {
                            using (SolidBrush halo = new SolidBrush(Color.FromArgb(60, ac)))
                                g.FillEllipse(halo, cx - rr * 2.1f, cy - rr * 2.1f, rr * 4.2f, rr * 4.2f);
                            using (SolidBrush b2 = new SolidBrush(ac))
                                g.FillEllipse(b2, cx - rr, cy - rr, rr * 2f, rr * 2f);
                        }
                        else
                            using (Pen p2 = new Pen(Color.FromArgb(120, 150, 168, 205), Math.Max(1f, r * 0.5f)))
                                g.DrawEllipse(p2, cx - rr * 0.75f, cy - rr * 0.75f, rr * 1.5f, rr * 1.5f);
                    }
                    x += halo0 + (Total - 1) * paso + halo0;
                }

                if (forma < 0) return;
                x += h * 0.45f;
                // Ultima comprobacion con el ancho que de verdad ocupo el nombre (si hubo que encogerlo sobra
                // sitio, y si el reparto se quedo corto por un pelo se acorta la frase antes que callarse). Solo
                // se calla si no cabe ni "3/18": entonces si, mejor nada que un numero a medias -"pagina 3 de 1"
                // con la ultima cifra comida ademas dice algo FALSO-.
                while (AnchoTexto(g, txt0, fPag) > w - x && forma < formas.Length - 1) txt0 = formas[++forma];
                if (AnchoTexto(g, txt0, fPag) > w - x) return;
                brocha.Color = Color.FromArgb(150, 160, 190);
                g.DrawString(txt0, fPag, brocha, new RectangleF(x, 0, Math.Max(10f, w - x), h), sfIzq);
            }

            private static GraphicsPath Redondo(RectangleF r, float radio)
            {
                GraphicsPath p = new GraphicsPath();
                float d = radio * 2;
                if (d > r.Height) d = r.Height;
                if (d > r.Width) d = r.Width;
                if (d < 2) d = 2;
                p.AddArc(r.X, r.Y, d, d, 180, 90);
                p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
                p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
                p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
                p.CloseFigure();
                return p;
            }
        }

        // ==========  PASTILLA (creditos, cola)  ==========
        // Un dato suelto dentro de una capsula: la etiqueta en gris y el numero en el color que le toca. Antes
        // eran dos textos sueltos apilados en una esquina; en una capsula se leen como una UNIDAD y de lejos se
        // distingue el numero, que es lo unico que el cliente necesita ver.
        // ==========  LA CASILLA DE BUSCAR  ==========
        //
        // Antes, para buscar por nombre habia que apretar ROJO y VERDE A LA VEZ. Nadie lo descubria: no
        // estaba escrito en ninguna parte que fuera un combo, y el cliente que llega por primera vez -de
        // noche, con prisa y con los amigos mirando- no se pone a probar parejas de botones. O sea que la
        // forma MAS RAPIDA de poner una cancion -saber el nombre y escribirlo- era la unica que nadie usaba.
        //
        // Ahora hay una casilla grande en medio de la parte de arriba, con una lupa, que PARPADEA en azul
        // para que se vea desde lejos, y AL LADO estan dibujados los dos botones que hay que apretar: el
        // rojo, un mas, y la flecha de arriba. No hay nada que leer ni que adivinar: se ve que son dos y
        // se ve cuales son.
        private class BuscaView : Control
        {
            public bool Abierto = false;      // con el buscador abierto la casilla se queda encendida fija
            public double Phase = 0;          // para el parpadeo
            private Font fTxt; private float fAlto = -1f;

            public BuscaView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
                this.TabStop = false;
            }

            // Lo que mide de ancho con ese alto. El acomodo necesita saberlo ANTES de dibujar nada.
            public static int Ancho(int alto)
            {
                int d = Sim(alto);
                // lupa + hueco + "BUSCAR" + hueco + rojo + mas + flecha, con aire a los lados
                return (int)(d * 1.15f) + 8 + (int)(alto * 2.05f) + 12 + d + 10 + d + 8 + (int)(d * 0.9f) + 22;
            }
            private static int Sim(int alto) { int d = (int)(alto * 0.52f); if (d < 12) d = 12; if (d > 30) d = 30; return d; }

            protected override void OnPaint(PaintEventArgs e)
            {
                e.Graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                RenderContent(e.Graphics);
            }

            public void RenderContent(Graphics g) { RenderContent(g, false); }
            // forGpu=true: se dibuja a brillo FIJO. El parpadeo lo pone la tarjeta grafica como un halo
            // aparte (FillUiGlows); si parpadeara aqui, habria que rehacer y volver a subir la textura de la
            // interfaz entera veinticuatro veces por segundo, que es justo lo que no se puede hacer.
            public void RenderContent(Graphics g, bool forGpu)
            {
                int w = Width, h = Height;
                if (w < 30 || h < 12) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                if (fTxt == null || fAlto != h)
                { if (fTxt != null) fTxt.Dispose(); fTxt = new Font(FontFamily.GenericSansSerif, Math.Max(8f, h * 0.30f), FontStyle.Bold); fAlto = h; }

                // EL PARPADEO. Con el buscador cerrado late para llamar la atencion; con el buscador abierto
                // se queda fija y encendida, porque ya cumplio su trabajo y parpadeando distraeria.
                double lat = (Abierto || forGpu) ? 1.0 : (0.45 + 0.55 * (0.5 + 0.5 * Math.Sin(Phase * 2.4)));
                Color azul = Color.FromArgb(90, 190, 255);
                Rectangle r = new Rectangle(0, 0, w - 1, h - 1);
                using (GraphicsPath gp = RoundedPath(r, Math.Min(14, h / 2)))
                {
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb((int)(28 + 58 * lat), azul))) g.FillPath(sb, gp);
                    using (Pen pn = new Pen(Color.FromArgb((int)(110 + 145 * lat), azul), 2f)) g.DrawPath(pn, gp);
                }

                int cy = h / 2, d = Sim(h);
                float x = 11;
                Color tinta = Color.FromArgb((int)(170 + 85 * lat), 235, 245, 255);
                x = Lupa(g, x, cy, (int)(d * 1.15f), tinta);
                x = CtrlTxt(g, fTxt, "BUSCAR", x + 8, cy, tinta) + 12;
                // Y los dos botones que hay que apretar, dibujados tal cual son.
                x = CtrlDot(g, x, cy, d, Color.FromArgb(228, 72, 72)) + 4;
                x = CtrlTxt(g, fTxt, "+", x, cy, tinta) + 6;
                Flecha(g, x, cy, (int)(d * 0.9f), Color.FromArgb(228, 72, 72));
            }

            // Donde va el halo del parpadeo cuando lo dibuja la tarjeta grafica (coordenadas dentro del control).
            public bool GetLatido(out float cx, out float cy, out float r)
            {
                cx = Width / 2f; cy = Height / 2f; r = Width * 0.55f;
                return !Abierto && Width > 30 && Height > 12;
            }

            // La lupa: un aro y su mango.
            private static float Lupa(Graphics g, float x, int cy, int d, Color c)
            {
                float aro = d * 0.72f;
                using (Pen pn = new Pen(c, Math.Max(2f, d * 0.13f)))
                {
                    g.DrawEllipse(pn, x, cy - aro / 2f, aro, aro);
                    float m = aro * 0.72f;
                    g.DrawLine(pn, x + aro * 0.85f, cy + aro * 0.35f, x + aro * 0.85f + m * 0.5f, cy + aro * 0.35f + m * 0.5f);
                }
                return x + d;
            }

            // La flecha de ARRIBA, en una tecla redondeada: se lee como un boton, no como un adorno.
            private static void Flecha(Graphics g, float x, int cy, int d, Color c)
            {
                Rectangle k = new Rectangle((int)x, cy - d / 2, d, d);
                using (GraphicsPath gp = RoundedPath(k, Math.Max(3, d / 4)))
                {
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(70, c))) g.FillPath(sb, gp);
                    using (Pen pn = new Pen(Color.FromArgb(215, c), 1.6f)) g.DrawPath(pn, gp);
                }
                float cx = x + d / 2f, t = d * 0.30f, an = d * 0.24f;
                CtrlTri(g, c, new PointF(cx, cy - t), new PointF(cx - an, cy + t * 0.62f), new PointF(cx + an, cy + t * 0.62f));
            }
        }

        private class PastillaView : Control
        {
            public string Etiqueta = "", Valor = "";
            public Color Acento = DefaultAccent;

            // ---------- LAS PORTADITAS DE LA COLA ----------
            // "En cola  3" es un dato del local: dice CUANTAS hay. Tres portaditas dicen lo mismo y
            // ademas CUALES son, que es lo que el cliente quiere saber para no volver a pedir la que
            // ya pidio. Se ven las tres primeras; si hay mas, la tercera lleva un "+2" en la esquina.
            public bool ConPortadas;      // esta capsula lleva hueco para portaditas (la de la cola si, la de la moneda no)
            public Image[] Portadas;      // las tres primeras de la cola (huecos vacios donde no haya)
            public int Mas;               // cuantas quedan detras de las tres
            private const int Huecos = 3;

            private Font fEtq, fVal, fMas; private float fontAlto = -1f;
            private SolidBrush brocha; private StringFormat sfCen;

            // ---------- LA CEREMONIA DE LA MONEDA ----------
            // El numero de creditos cambiaba de 0 a 1 y se acabo. Es informacion correcta y, a dos metros,
            // de noche y con los amigos hablando, invisible. Aqui la moneda CAE, el numero RUEDA y la
            // capsula DESTELLA: es el instante en que el dinero se vuelve musica y tiene que notarse
            // desde la barra. Es lo mismo dicho de una forma que no hay que leer.
            private int monTick, rodTick, aviTick;   // 0 = esa parte no esta corriendo
            private string rodDe = "";               // el numero de ANTES, el que se va rodando hacia arriba
            private const int MonMs = 420, RodMs = 240, AviMs = 520, DestMs = 520;

            public void Moneda()
            {
                int t = Environment.TickCount; if (t == 0) t = 1;
                monTick = t;
                rodTick = t + MonMs;      // el numero rueda cuando la moneda ATERRIZA, no antes
                rodDe = Valor ?? "";      // se guarda AHORA: quien llama todavia no ha puesto el nuevo
            }
            // Cuando no hay creditos: la capsula se sacude. Hoy solo salia un letrero, y a las dos de la
            // manana nadie lee letreros -el cliente sigue picandole al boton creyendo que esta descompuesta-.
            public void Aviso()
            {
                int t = Environment.TickCount; if (t == 0) t = 1;
                aviTick = t;
            }
            // Si hay algo moviendose. Lo preguntan el reloj de la pantalla, para repintar, y la firma de la
            // textura de la interfaz, para rehacerse: sin eso, CON TARJETA GRAFICA la moneda no se veria
            // caer -la textura no cambiaria y la animacion se quedaria congelada dentro de ella-.
            public bool Animando
            {
                get
                {
                    int t = Environment.TickCount;
                    return (monTick != 0 && t - monTick < MonMs + DestMs)
                        || (aviTick != 0 && t - aviTick < AviMs);
                }
            }
            // Un numero que cambia mientras dura la animacion, y SOLO entonces: quieta, la firma no se
            // mueve y la textura no se rehace ni una vez de mas.
            public int Paso { get { return Animando ? (Environment.TickCount / 16) : 0; } }

            public PastillaView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
                this.TabStop = false;
            }

            // Lo que mide de ancho una pastilla con ese contenido y ese alto. Lo usa el acomodo, que necesita
            // saberlo ANTES de dibujar nada (y por eso mide con TextRenderer, sin Graphics).
            //
            // 'conPortadas' dice si ESTA capsula lleva portaditas, y no CUANTAS lleva ahora mismo, a
            // proposito. El ancho de la capsula de la cola manda hasta donde puede llegar el TITULO de la
            // cancion (derPast, en el acomodo); si dependiera de la cola, el titulo se repartiria de otra
            // manera en dos lineas cada vez que alguien pide algo, y el nombre de la que suena bailaria
            // solo, sin que nadie lo hubiera tocado. Se mide siempre el hueco de las tres, llenas o vacias.
            public static int Ancho(string etiq, string valor, int alto, FontFamily fam, bool conPortadas)
            {
                // Se mide con GDI+, que es con lo que RenderContent la PINTA. Antes se media con TextRenderer,
                // que es GDI: otro motor, otros anchos. En la pantalla del bar la diferencia eran dos pixeles y
                // pasaba desapercibida; en una pantalla grande crecia con el cuerpo de la letra y se comia el
                // final de "Inserta una moneda".
                using (Font fe = new Font(fam, alto * 0.34f, FontStyle.Bold))
                using (Font fv = new Font(fam, alto * 0.52f, FontStyle.Bold))
                {
                    int w = AnchoTexto(etiq, fe);
                    if (!string.IsNullOrEmpty(valor)) w += AnchoTexto(valor, fv) + (int)(alto * 0.22f);
                    if (conPortadas) w += AnchoPortaditas(alto);
                    return w + (int)(alto * 0.9f);
                }
            }
            // El hueco de las tres portaditas: el suyo propio, lo que las separa y lo que las separa del numero.
            private static int LadoPortadita(int alto) { return (int)(alto * 0.52f); }
            private static int AnchoPortaditas(int alto)
            {
                return Huecos * LadoPortadita(alto) + (Huecos - 1) * (int)(alto * 0.09f) + (int)(alto * 0.20f);
            }

            private void EnsureRes(int h)
            {
                if (brocha == null) brocha = new SolidBrush(Color.White);
                if (sfCen == null) sfCen = CreaSfDibuja(StringAlignment.Center);
                if (fEtq != null && Math.Abs(fontAlto - h) < 0.5f) return;
                if (fEtq != null) fEtq.Dispose();
                if (fVal != null) fVal.Dispose();
                if (fMas != null) fMas.Dispose();
                fEtq = new Font(this.Font.FontFamily, h * 0.34f, FontStyle.Bold);
                fVal = new Font(this.Font.FontFamily, h * 0.52f, FontStyle.Bold);
                fMas = new Font(this.Font.FontFamily, LadoPortadita(h) * 0.34f, FontStyle.Bold);
                fontAlto = h;
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }
            public void RenderContent(Graphics g)
            {
                int w = Width, h = Height;
                if (w < 8 || h < 8) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                EnsureRes(h);
                int t = Environment.TickCount;
                // LA SACUDIDA del aviso de sin creditos: dos idas y venidas que se apagan solas.
                System.Drawing.Drawing2D.GraphicsState stSac = null;
                if (aviTick != 0)
                {
                    int da = t - aviTick;
                    if (da >= 0 && da < AviMs)
                    {
                        float ua = da / (float)AviMs;
                        float dx = (float)(Math.Sin(ua * 18.0) * h * 0.13 * (1.0 - ua));
                        stSac = g.Save(); g.TranslateTransform(dx, 0f);
                    }
                    else if (da >= AviMs) aviTick = 0;
                }
                using (GraphicsPath p = RoundRectF(new RectangleF(0.5f, 0.5f, w - 1, h - 1), h / 2f))
                {
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(52, Acento))) g.FillPath(b, p);
                    using (Pen pe = new Pen(Color.FromArgb(95, Acento), 1f)) g.DrawPath(pe, p);
                    // EL DESTELLO: el borde se enciende y se apaga cuando la moneda aterriza. Es lo que se
                    // ve desde lejos, cuando el numero ya es demasiado chico para leerse.
                    float br = 0f;
                    if (monTick != 0) { int dd = t - (monTick + MonMs); if (dd >= 0 && dd < DestMs) br = 1f - dd / (float)DestMs; }
                    if (aviTick != 0) { int da2 = t - aviTick; if (da2 >= 0 && da2 < AviMs) br = Math.Max(br, 1f - da2 / (float)AviMs); }
                    if (br > 0.01f)
                    {
                        using (SolidBrush b2 = new SolidBrush(Color.FromArgb((int)(70 * br), Acento))) g.FillPath(b2, p);
                        using (Pen pe2 = new Pen(Color.FromArgb((int)(210 * br), Acento), 2f)) g.DrawPath(pe2, p);
                    }
                }
                // El contenido va CENTRADO: al acomodo se le puede dar un pelo mas de ancho del justo y sigue
                // viendose bien, en vez de quedar pegado a un lado.
                string et = Etiqueta ?? "", va = Valor ?? "";
                float we = g.MeasureString(et, fEtq).Width;
                float wv = (va.Length > 0) ? g.MeasureString(va, fVal).Width : 0f;
                float hueco = (va.Length > 0) ? h * 0.18f : 0f;
                float wPort = ConPortadas ? AnchoPortaditas(h) : 0f;
                float x = (w - (we + wv + hueco + wPort)) / 2f;
                if (x < h * 0.25f) x = h * 0.25f;
                brocha.Color = Color.FromArgb(215, 205, 214, 238);
                g.DrawString(et, fEtq, brocha, new RectangleF(x, 0, we + 6, h), sfCen);
                float xv = x + we + hueco;
                // EL NUMERO RUEDA COMO UN ODOMETRO: el de antes sube y se va, el nuevo entra por abajo. Se
                // recorta a su hueco para que ninguno de los dos asome fuera de la capsula.
                float rp = -1f;
                if (monTick != 0) { int dr = t - rodTick; if (dr < 0) rp = 0f; else if (dr < RodMs) rp = dr / (float)RodMs; }
                if (rp >= 0f)
                {
                    float sube = (float)(1.0 - Math.Pow(1.0 - rp, 3));   // frena al llegar, como un rodillo
                    System.Drawing.Drawing2D.GraphicsState st = g.Save();
                    g.SetClip(new RectangleF(xv - 3f, 1f, Math.Max(wv, 10f) + 12f, h - 2f), CombineMode.Intersect);
                    brocha.Color = Acento;
                    if (rodDe.Length > 0)
                        g.DrawString(rodDe, fVal, brocha, new RectangleF(xv, -h * sube, wv + 6, h), sfCen);
                    if (va.Length > 0)
                        g.DrawString(va, fVal, brocha, new RectangleF(xv, h * (1f - sube), wv + 6, h), sfCen);
                    g.Restore(st);
                }
                else if (va.Length > 0)
                {
                    brocha.Color = Acento;
                    g.DrawString(va, fVal, brocha, new RectangleF(xv, 0, wv + 6, h), sfCen);
                }

                // LAS PORTADITAS DE LA COLA, detras del numero. Los huecos vacios se insinuan apenas: dicen
                // "aqui van las que pidas" sin pelearle la vista a nada.
                if (ConPortadas)
                {
                    int lado = LadoPortadita(h);
                    int sep = (int)(h * 0.09f);
                    float py = (h - lado) / 2f;
                    float px0 = xv + wv + h * 0.20f;
                    InterpolationMode antes = g.InterpolationMode;
                    g.InterpolationMode = InterpolationMode.HighQualityBilinear;   // achicar una portada a 20 px sin que salga a granos
                    for (int i = 0; i < Huecos; i++)
                    {
                        RectangleF rq = new RectangleF(px0 + i * (lado + sep), py, lado, lado);
                        Image im = (Portadas != null && i < Portadas.Length) ? Portadas[i] : null;
                        using (GraphicsPath ph = RoundRectF(rq, lado * 0.22f))
                        {
                            if (im != null)
                            {
                                System.Drawing.Drawing2D.GraphicsState sp = g.Save();
                                g.SetClip(ph, CombineMode.Intersect);
                                g.DrawImage(im, rq);
                                g.Restore(sp);
                                using (Pen pe = new Pen(Color.FromArgb(120, 235, 240, 255), 1f)) g.DrawPath(pe, ph);
                            }
                            else using (Pen pe = new Pen(Color.FromArgb(52, Acento), 1f)) g.DrawPath(pe, ph);
                        }
                    }
                    g.InterpolationMode = antes;
                    // Y SI HAY MAS DE TRES, cuantas quedan detras. Sin esto, una cola de nueve se veria
                    // igual que una de tres y el numero de al lado parecerian dos cosas que no cuadran.
                    if (Mas > 0)
                    {
                        RectangleF ru = new RectangleF(px0 + (Huecos - 1) * (lado + sep), py, lado, lado);
                        float hb = lado * 0.46f;
                        using (GraphicsPath ph = RoundRectF(ru, lado * 0.22f))
                        {
                            System.Drawing.Drawing2D.GraphicsState sp = g.Save();
                            g.SetClip(ph, CombineMode.Intersect);
                            using (SolidBrush b3 = new SolidBrush(Color.FromArgb(205, 8, 11, 28)))
                                g.FillRectangle(b3, ru.X, ru.Bottom - hb, ru.Width, hb);
                            brocha.Color = Color.FromArgb(238, 232, 240, 255);
                            g.DrawString("+" + Mas, fMas, brocha, new RectangleF(ru.X, ru.Bottom - hb, ru.Width, hb), sfCen);
                            g.Restore(sp);
                        }
                    }
                }

                // LA MONEDA. Entra por arriba, gira -se aplasta a lo ancho, que es como se ve girar una
                // moneda- y aterriza sobre el numero con un botecito.
                if (monTick != 0)
                {
                    int dt = t - monTick;
                    if (dt >= 0 && dt < MonMs)
                    {
                        float u = dt / (float)MonMs;
                        float d = h * 0.44f;
                        float cx = (va.Length > 0 || rodDe.Length > 0) ? xv + Math.Max(wv, 10f) * 0.5f : w * 0.5f;
                        float cy = -d + (h * 0.5f + d) * (u * u);
                        if (u > 0.74f) cy -= (float)Math.Abs(Math.Sin((u - 0.74f) * 12.0)) * h * 0.16f * ((1f - u) / 0.26f);
                        float aw = Math.Max(d * 0.16f, d * (float)Math.Abs(Math.Cos(u * 11.5)));
                        using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 246, 206, 96)))
                            g.FillEllipse(b, cx - aw * 0.5f, cy - d * 0.5f, aw, d);
                        using (Pen pe = new Pen(Color.FromArgb(190, 255, 242, 196), 1.2f))
                            g.DrawEllipse(pe, cx - aw * 0.5f, cy - d * 0.5f, aw, d);
                    }
                    if (dt >= MonMs + DestMs) monTick = 0;
                }
                if (stSac != null) g.Restore(stSac);
            }

            private static GraphicsPath RoundRectF(RectangleF r, float radio)
            {
                GraphicsPath p = new GraphicsPath();
                float d = radio * 2;
                if (d > r.Height) d = r.Height;
                if (d > r.Width) d = r.Width;
                if (d < 2) d = 2;
                p.AddArc(r.X, r.Y, d, d, 180, 90);
                p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
                p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
                p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
                p.CloseFigure();
                return p;
            }
        }

        // ==========  PASTILLA DE GENERO  ==========
        // La misma que sale en la lista de un disco y en los resultados del buscador -relleno muy tenue del
        // color del genero, borde fino y el texto en ese color aclarado-, pero como control suelto, para
        // ponerla en la franja de abajo: asi, al sonar una cancion, tambien se ve DE QUE ES.
        //
        // Se mide sola: le da su ancho y su alto al acomodo, que es quien la coloca detras del artista.
        private class GeneroView : Control
        {
            private string texto = "";
            public string Texto
            {
                get { return texto; }
                set { string v = value ?? ""; if (v != texto) { texto = v; medido = false; Invalidate(); } }
            }
            public Color Tinte = DefaultAccent;

            private bool medido; private int anchoPide, altoPide;
            private SolidBrush brocha; private StringFormat sfCen;

            public GeneroView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
                this.TabStop = false;
            }
            protected override void OnFontChanged(EventArgs e) { base.OnFontChanged(e); medido = false; }

            private void Mide()
            {
                if (medido) return;
                anchoPide = (texto.Length > 0) ? AnchoTexto(texto, this.Font) + 20 : 0;
                altoPide = this.Font.Height + 6;
                medido = true;
            }
            public int AnchoQuePide() { Mide(); return anchoPide; }
            public int AltoQuePide() { Mide(); return altoPide; }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }
            public void RenderContent(Graphics g)
            {
                int w = Width, h = Height;
                if (w < 6 || h < 6 || texto.Length == 0) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                if (brocha == null) brocha = new SolidBrush(Color.White);
                if (sfCen == null) sfCen = CreaSfDibuja(StringAlignment.Center);
                using (GraphicsPath p = RoundedPath(new Rectangle(0, 0, w - 1, h - 1), Math.Min(7, (h - 1) / 2)))
                {
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(60, Tinte))) g.FillPath(b, p);
                    using (Pen pe = new Pen(Color.FromArgb(120, Tinte), 1f)) g.DrawPath(pe, p);
                }
                brocha.Color = Lighten(Tinte, 0.45);
                g.DrawString(texto, this.Font, brocha, new RectangleF(0, 0, w, h), sfCen);
            }
        }

        // ==========  BARRA DE PROGRESO  ==========
        private class ProgressView : Control
        {
            private double _value;
            public double Value { get { return _value; } set { double v = value < 0 ? 0 : (value > 1 ? 1 : value); if (v != _value) { _value = v; Invalidate(); } } }
            private Color _accent = DefaultAccent;   // ESTETICA: la barra toma el color del genero que suena
            public Color Accent { get { return _accent; } set { if (value.ToArgb() != _accent.ToArgb()) { _accent = value; Invalidate(); } } }

            private SolidBrush trackB; private Pen trackP;   // riel: colores fijos -> se cachean (se dibuja en cada reconstruccion de UI)

            public ProgressView()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
                this.BackColor = Color.Transparent;
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }
            // Dibuja la barra de progreso en cualquier Graphics (el control, o la textura de UI del modo GPU).
            public void RenderContent(Graphics g)
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                int w = Width, h = Height;
                if (w < 4 || h < 4) return;

                // Riel HUNDIDO: oscuro translucido + borde interior tenue (parece rebajado, no plano).
                Rectangle track = new Rectangle(0, 0, w - 1, h - 1);
                if (trackB == null) { trackB = new SolidBrush(Color.FromArgb(130, 6, 10, 26)); trackP = new Pen(Color.FromArgb(40, 255, 255, 255), 1f); }
                using (GraphicsPath tp = RoundedPath(track, h / 2))
                {
                    g.FillPath(trackB, tp);
                    g.DrawPath(trackP, tp);
                }

                int fw = (int)(_value * (w - 2));
                if (fw >= 3)
                {
                    Rectangle fill = new Rectangle(1, 1, fw, h - 3);
                    int rad = Math.Max(1, (h - 3) / 2);
                    using (GraphicsPath fp = RoundedPath(fill, rad))
                    {
                        // halo "neon" alrededor del relleno (acorde al cielo estrellado)
                        using (Pen glow = new Pen(Color.FromArgb(70, Lighten(_accent, 0.5)), 3f)) { glow.LineJoin = LineJoin.Round; g.DrawPath(glow, fp); }
                        // cuerpo: degradado vertical brillante arriba -> acento abajo
                        using (LinearGradientBrush fb = new LinearGradientBrush(new Rectangle(fill.X, fill.Y, fill.Width, fill.Height + 1), Lighten(_accent, 0.6), Shade(_accent, 0.1), LinearGradientMode.Vertical))
                            g.FillPath(fb, fp);
                        // gloss: franja clara en la mitad superior (aspecto vidrioso)
                        Rectangle gloss = new Rectangle(fill.X + 1, fill.Y + 1, Math.Max(1, fill.Width - 2), Math.Max(1, (fill.Height - 1) / 2));
                        using (GraphicsPath gpath = RoundedPath(gloss, Math.Max(1, gloss.Height / 2)))
                        using (LinearGradientBrush gb = new LinearGradientBrush(new Rectangle(gloss.X, gloss.Y, gloss.Width, gloss.Height + 1), Color.FromArgb(150, 255, 255, 255), Color.FromArgb(15, 255, 255, 255), LinearGradientMode.Vertical))
                            g.FillPath(gb, gpath);
                        // borde nitido brillante
                        using (Pen edge = new Pen(Color.FromArgb(180, Lighten(_accent, 0.65)), 1f)) g.DrawPath(edge, fp);
                    }
                }
            }
        }

        // ==========  LISTA DE CANCIONES (dibujada a mano, no ListBox nativo) ==========
        // Reemplaza al ListBox: asi el interior del disco se puede componer por GPU (un control nativo no se
        // puede poner sobre D3D). Es una VISTA de UNA pagina: la seleccion global la maneja el form (songSel).
        private class SongListView : Control
        {
            public Func<int> GetCount;          // total de items (songItems.Count)
            public Func<int, string> GetText;   // texto del item i
            public Func<int, string> GetRight;   // texto CORTO a la derecha del item i (la duracion); "" = nada
            public Func<int, int> GetQueuePos;   // 0 = no esta pedida; n = va en el puesto n de la cola
            // SEPARADO de la cola a proposito: una cancion puede estar SONANDO y ADEMAS estar pedida otra
            // vez, y el cliente necesita las dos cosas -que la esta oyendo, y que ya la va a volver a oir-.
            // Con un solo dato una marca tapaba a la otra.
            public Func<int, bool> GetSonando;
            public Func<int, string> GetGenero;  // etiqueta de genero del item i ("" = aun no se sabe)
            public int PageStart = 0;           // primer item de la pagina visible
            public int Sel = 0;                 // seleccion GLOBAL (entre todas las paginas)
            public int Datos = 0;               // sube cuando cambia el CONTENIDO (cola, generos, duraciones): obliga a rehornear
            public int RowH = 30;
            public Color Accent = DefaultAccent;   // color del genero (para el resaltado)
            public Action<int> OnActivate;      // doble-click sobre un item (encolar)
            public Action<int> OnPick;          // click simple: fija la seleccion

            private SolidBrush hlB; private Pen hlP;
            private SolidBrush txtB; private StringFormat txtFmt; private SolidBrush bgB;
            private SolidBrush durB; private StringFormat durFmt;   // duracion: gris suave, pegada a la derecha
            // El circulito del numero de pista y la marca de "ya pedida". Todo cacheado: la lista se redibuja
            // entera cada vez que cambia algo, y crear una brocha por fila seria basura por gusto.
            private SolidBrush colaB;
            private Font fNum, fCola; private float fontFuente = -1f;
            private StringFormat cenFmt;
            // EL CIRCULITO Y LA PASTILLA, HORNEADOS. Dibujar dos elipses suavizadas por fila costaba 80 us por
            // fila -mas que todo el resto de la fila junta- y la pastilla otros 55. Como son SIEMPRE la misma
            // figura, se pintan una vez a un mapa de bits y despues cada fila solo las copia. Lo unico que se
            // sigue dibujando por fila es el numero, que si cambia.
            private Bitmap bmpCirc, bmpCircCola, bmpCircSon;
            // Las pastillas se hornean POR ANCHO: cada texto mide lo suyo ("SONANDO" no mide lo mismo que
            // "EN COLA 12"), y con un ancho fijo el texto se salia -de ahi que se leyera "SONAND"-.
            private readonly Dictionary<int, Bitmap> hornoPastV = new Dictionary<int, Bitmap>();
            private readonly Dictionary<int, Bitmap> hornoPastA = new Dictionary<int, Bitmap>();
            private int hornoPastAlto = -1;
            private Bitmap Pastilla(bool ambar, int w, int h)
            {
                if (h != hornoPastAlto) { TiraPastillas(); hornoPastAlto = h; }
                Dictionary<int, Bitmap> horno = ambar ? hornoPastA : hornoPastV;
                Bitmap b;
                if (horno.TryGetValue(w, out b) && b != null) return b;
                b = HorneaPastilla(w, h, ambar ? SonAmbar : ColaVerde);
                horno[w] = b;
                return b;
            }
            private void TiraPastillas()
            {
                foreach (Bitmap b in hornoPastV.Values) if (b != null) b.Dispose();
                foreach (Bitmap b in hornoPastA.Values) if (b != null) b.Dispose();
                hornoPastV.Clear(); hornoPastA.Clear();
            }
            private Bitmap[] bmpDig, bmpDigCola, bmpDigSon;   // las diez cifras, tambien horneadas
            private int hornoLado = -1, digW, digH;
            private float hornoCuerpo = -1f;
            private static Bitmap HorneaCirculo(int lado, Color c, bool fuerte)
            {
                if (lado < 3) lado = 3;
                Bitmap b = new Bitmap(lado, lado, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(b))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    RectangleF r = new RectangleF(0.6f, 0.6f, lado - 1.7f, lado - 1.7f);
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(fuerte ? 70 : 34, c))) g.FillEllipse(sb, r);
                    using (Pen p = new Pen(Color.FromArgb(fuerte ? 150 : 60, c), 1f)) g.DrawEllipse(p, r);
                }
                return b;
            }
            private static Bitmap HorneaPastilla(int w, int h, Color c)
            {
                if (w < 4) w = 4;
                if (h < 4) h = 4;
                Bitmap b = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(b))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    using (GraphicsPath gp = RoundedPath(new Rectangle(0, 0, w - 1, h - 1), h / 2))
                    {
                        using (SolidBrush sb = new SolidBrush(Color.FromArgb(52, c))) g.FillPath(sb, gp);
                        using (Pen p = new Pen(Color.FromArgb(110, c), 1f)) g.DrawPath(p, gp);
                    }
                }
                return b;
            }
            // Las diez cifras, de un ancho comun para que los numeros queden alineados entre filas.
            private void HorneaCifras(Font f, Color c, out Bitmap[] destino, out int w, out int h)
            {
                w = 6; h = 8;
                using (Bitmap med = new Bitmap(4, 4))
                using (Graphics g = Graphics.FromImage(med))
                    for (int d = 0; d < 10; d++)
                    {
                        SizeF sz = g.MeasureString(((char)('0' + d)).ToString(), f, 999, StringFormat.GenericTypographic);
                        if (sz.Width > w) w = (int)Math.Ceiling(sz.Width);
                        if (sz.Height > h) h = (int)Math.Ceiling(sz.Height);
                    }
                w += 2; h += 2;
                destino = new Bitmap[10];
                using (StringFormat sf = new StringFormat())
                {
                    sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center;
                    sf.FormatFlags = StringFormatFlags.NoWrap;
                    using (SolidBrush sb = new SolidBrush(c))
                        for (int d = 0; d < 10; d++)
                        {
                            Bitmap b = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                            using (Graphics g = Graphics.FromImage(b))
                            {
                                g.SmoothingMode = SmoothingMode.AntiAlias;
                                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
                                g.Clear(Color.Transparent);
                                g.DrawString(((char)('0' + d)).ToString(), f, sb, new RectangleF(0, 0, w, h), sf);
                            }
                            destino[d] = b;
                        }
                }
            }
            // Pinta un numero copiando sus cifras ya horneadas, centrado en 'cx'.
            // marca: 0 = normal, 1 = pedida (verde), 2 = sonando ahora (ambar)
            private void PintaNumero(Graphics g, int v, float cx, float cy, int marca)
            {
                Bitmap[] set = (marca == 2) ? bmpDigSon : (marca == 1) ? bmpDigCola : bmpDig;
                if (set == null) return;
                if (v < 0) v = 0;
                int cifras = (v < 10) ? 1 : (v < 100) ? 2 : (v < 1000) ? 3 : 4;
                int x = (int)(cx - cifras * digW * 0.5f), y = (int)(cy - digH * 0.5f);
                int div = 1;
                for (int k = 1; k < cifras; k++) div *= 10;
                for (int k = 0; k < cifras; k++)
                {
                    int d = (v / div) % 10; div /= 10;
                    if (d >= 0 && d <= 9) g.DrawImageUnscaled(set[d], x + k * digW, y);
                }
            }

            // PASTILLA DE GENERO ya dibujada. Se hornea UNA por etiqueta (son una docena en toda la rocola)
            // y luego cada fila solo la copia. Dibujar por fila un rectangulo redondeado con borde mas su
            // texto era justo lo que encarecia la lista, y la lista se repinta entera al moverse por ella.
            private readonly Dictionary<string, Bitmap> hornoGen = new Dictionary<string, Bitmap>();
            private float hornoGenCuerpo = -1f;
            private Bitmap HorneaGenero(string etiqueta)
            {
                if (string.IsNullOrEmpty(etiqueta) || fCola == null) return null;
                if (Math.Abs(hornoGenCuerpo - fCola.SizeInPoints) > 0.01f) { TiraHornoGen(); hornoGenCuerpo = fCola.SizeInPoints; }
                Bitmap b;
                if (hornoGen.TryGetValue(etiqueta, out b)) return b;
                Color c = ColorDeEtiqueta(etiqueta);
                int w, h;
                using (Bitmap med = new Bitmap(4, 4))
                using (Graphics mg = Graphics.FromImage(med))
                {
                    SizeF sz = mg.MeasureString(etiqueta, fCola, 999, StringFormat.GenericTypographic);
                    w = (int)Math.Ceiling(sz.Width) + 16;
                    h = (int)Math.Ceiling(sz.Height) + 5;
                }
                if (w < 8) w = 8; if (h < 8) h = 8;
                b = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(b))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
                    g.Clear(Color.Transparent);
                    // El MISMO aspecto que la pastilla de genero de los resultados del buscador: relleno muy
                    // tenue del color del genero, borde fino y el texto en ese color aclarado.
                    using (GraphicsPath gp = RoundedPath(new Rectangle(0, 0, w - 1, h - 1), Math.Min(7, (h - 1) / 2)))
                    {
                        using (SolidBrush sb = new SolidBrush(Color.FromArgb(60, c))) g.FillPath(sb, gp);
                        using (Pen pn = new Pen(Color.FromArgb(120, c), 1f)) g.DrawPath(pn, gp);
                    }
                    using (StringFormat sf = new StringFormat())
                    {
                        sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center;
                        sf.FormatFlags = StringFormatFlags.NoWrap;
                        using (SolidBrush sb = new SolidBrush(Lighten(c, 0.45)))
                            g.DrawString(etiqueta, fCola, sb, new RectangleF(0, 0, w, h), sf);
                    }
                }
                hornoGen[etiqueta] = b;
                return b;
            }
            private void TiraHornoGen()
            {
                foreach (Bitmap b in hornoGen.Values) if (b != null) b.Dispose();
                hornoGen.Clear();
            }

            private void EnsureHorno(int lado, int ph)
            {
                if (bmpDig == null || Math.Abs(hornoCuerpo - fNum.SizeInPoints) > 0.01f)
                {
                    if (bmpDig != null) for (int i = 0; i < bmpDig.Length; i++) if (bmpDig[i] != null) bmpDig[i].Dispose();
                    if (bmpDigCola != null) for (int i = 0; i < bmpDigCola.Length; i++) if (bmpDigCola[i] != null) bmpDigCola[i].Dispose();
                    if (bmpDigSon != null) for (int i = 0; i < bmpDigSon.Length; i++) if (bmpDigSon[i] != null) bmpDigSon[i].Dispose();
                    int w1, h1, w2, h2, w3, h3;
                    HorneaCifras(fNum, Color.FromArgb(178, 190, 218), out bmpDig, out w1, out h1);
                    HorneaCifras(fNum, ColaVerde, out bmpDigCola, out w2, out h2);
                    HorneaCifras(fNum, SonAmbar, out bmpDigSon, out w3, out h3);
                    digW = Math.Max(w1, Math.Max(w2, w3)); digH = Math.Max(h1, Math.Max(h2, h3));
                    hornoCuerpo = fNum.SizeInPoints;
                }
                if (bmpCirc == null || hornoLado != lado)
                {
                    if (bmpCirc != null) bmpCirc.Dispose();
                    if (bmpCircCola != null) bmpCircCola.Dispose();
                    if (bmpCircSon != null) bmpCircSon.Dispose();
                    bmpCirc = HorneaCirculo(lado, NumGris, false);
                    bmpCircCola = HorneaCirculo(lado, ColaVerde, true);
                    bmpCircSon = HorneaCirculo(lado, SonAmbar, true);
                    hornoLado = lado;
                }
                if (hornoPastAlto != ph) { TiraPastillas(); hornoPastAlto = ph; }   // otro alto de fila: se rehornean
            }
            private static readonly Color ColaVerde = Color.FromArgb(120, 230, 165);
            // AMBAR para la que suena AHORA. Deliberadamente de otra familia de color que el verde de "ya
            // pedida": de un vistazo, y a la distancia a la que se mira una rocola, tienen que distinguirse
            // sin leer. Verde = la vas a oir; ambar = la estas oyendo.
            private static readonly Color SonAmbar = Color.FromArgb(255, 198, 104);
            private static readonly Color NumGris = Color.FromArgb(150, 170, 220);

            public SongListView()
            {
                SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer, true);
                BackColor = Shade(DefaultAccent, 0.76);
            }

            // ================= HOJEAR DENTRO DE UN DISCO =================
            // Un disco con mas de una pagina cambiaba de pagina DE GOLPE: catorce canciones se convertian en
            // otras catorce sin que nada dijera hacia donde te habias movido, y era facil perderse. Ahora la
            // pagina que dejas SALE por un lado y la que eliges ENTRA por el otro, con el mismo frenado suave
            // y la misma duracion que ya usa la pared de discos: la rocola se mueve toda igual.
            //
            // Y se puede hacer sin que cueste nada porque las dos paginas van HORNEADAS: dibujar una cuesta
            // 1,8 ms y durante la animacion hacen falta las dos en cada cuadro (3,7 ms, que en el equipo de
            // XP serian bastantes mas y romperian el movimiento). Horneadas, cada cuadro son dos copias.
            public const int SlideMs = 230;
            private int slideTick = -1; private float slideDesde;
            private Bitmap hornoPag, hornoAnt;          // la pagina de ahora y la que se esta yendo
            private long hornoSig = long.MinValue;      // que hay horneado (pagina, seleccion, tamano, datos...)
            private int hornoAncho = -1, hornoAlto = -1;

            // dir: +1 la nueva entra por la DERECHA (vas hacia delante), -1 por la izquierda.
            public void StartSlide(int dir)
            {
                int w = ClientSize.Width;
                if (w < 8 || hornoPag == null) { slideTick = -1; return; }   // sin nada horneado no hay de donde salir
                // Los dos mapas de bits se INTERCAMBIAN, no se tiran: uno pasa a ser la pagina que se va y en
                // el otro se dibuja encima la que entra. Tirarlos obligaria a reservar dos megas en cada
                // cambio de pagina, y hojeando deprisa eso son recogidas de basura -o sea, tirones- justo
                // mientras la animacion esta corriendo.
                Bitmap t = hornoAnt; hornoAnt = hornoPag; hornoPag = t;
                hornoSig = long.MinValue;
                slideDesde = dir * (float)w; slideTick = Environment.TickCount;
            }
            public bool Sliding { get { return slideTick >= 0 && Environment.TickCount - slideTick < SlideMs; } }
            // Olvida lo horneado y corta cualquier hojeo en curso. Se llama al ABRIR un disco: si no, venir de
            // la pagina 3 de otro disco haria "hojear" hasta la 1 del nuevo, que no significa nada.
            public void OlvidaPagina()
            {
                slideTick = -1;
                if (hornoAnt != null) { hornoAnt.Dispose(); hornoAnt = null; }
                if (hornoPag != null) { hornoPag.Dispose(); hornoPag = null; }
                hornoSig = long.MinValue; hornoAncho = hornoAlto = -1;
            }
            // Cuanto lleva hecha la animacion (0..1). Entra en la firma de la textura de UI del modo GPU: sin
            // eso la textura no se rehace y la animacion no se veria mover.
            public float SlidePaso
            {
                get
                {
                    if (slideTick < 0) return 1f;
                    int dt = Environment.TickCount - slideTick;
                    return (dt >= SlideMs) ? 1f : (dt / (float)SlideMs);
                }
            }
            // CURVA del hojeo (la misma que la pared de discos, para que las dos se muevan igual): devuelve
            // cuanto FALTA por recorrer, de 1 (recien empieza) a 0 (ya llego).
            internal static float CurvaLista(int dt)
            {
                if (dt < 0 || dt >= SlideMs) return 0f;
                float t = dt / (float)SlideMs;
                return (1f - t) * (1f - t) * (1f - t);   // frenado suave al llegar (cubico)
            }
            private float DesplazaAhora()
            {
                if (slideTick < 0) return 0f;
                int dt = Environment.TickCount - slideTick;
                if (dt < 0 || dt >= SlideMs) { slideTick = -1; return 0f; }   // el mapa de la pagina vieja se GUARDA: es el otro lado del intercambio
                return slideDesde * CurvaLista(dt);
            }

            // Lo que identifica al mapa de bits horneado. Si algo de esto cambia, hay que volver a dibujarlo.
            private long FirmaPagina(int w, int h)
            {
                long k = 17;
                k = k * 31 + PageStart; k = k * 31 + Sel; k = k * 31 + Datos;
                k = k * 31 + w; k = k * 31 + h; k = k * 31 + RowH;
                k = k * 31 + Accent.ToArgb(); k = k * 31 + BackColor.ToArgb();
                k = k * 31 + (int)(Font.SizeInPoints * 64f);
                k = k * 31 + ((GetCount != null) ? GetCount() : 0);
                return k;
            }

            // Asegura que 'hornoPag' es la pagina de ahora, dibujada tal cual. El fondo del horneado es OPACO
            // -el mismo relleno que pinta la lista- asi que copiarlo despues da EXACTAMENTE los mismos pixeles
            // que dibujarlo directo. (Hornear sobre transparente NO valdria: el texto suavizado sale mas fino.)
            private void AseguraHorneada(int w, int h)
            {
                long sig = FirmaPagina(w, h);
                if (hornoPag != null && hornoSig == sig && hornoAncho == w && hornoAlto == h) return;
                if (hornoPag == null || hornoAncho != w || hornoAlto != h)
                {
                    if (hornoPag != null) hornoPag.Dispose();
                    if (hornoAnt != null && (hornoAncho != w || hornoAlto != h)) { hornoAnt.Dispose(); hornoAnt = null; slideTick = -1; }
                    hornoPag = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
                    hornoAncho = w; hornoAlto = h;
                }
                using (Graphics gb = Graphics.FromImage(hornoPag)) PintaPagina(gb, PageStart);
                hornoSig = sig;
            }

            // Lo que ve el cliente: la pagina horneada, y mientras se hojea, las DOS deslizandose.
            public void RenderContent(Graphics g)
            {
                int w = ClientSize.Width, h = ClientSize.Height;
                if (w < 4 || h < 4) return;
                AseguraHorneada(w, h);
                float dx = DesplazaAhora();
                if (dx == 0f || hornoAnt == null) { g.DrawImageUnscaled(hornoPag, 0, 0); return; }
                // La que SE VA sale por el lado contrario al que entra la nueva.
                g.DrawImageUnscaled(hornoAnt, (int)(dx - slideDesde), 0);
                g.DrawImageUnscaled(hornoPag, (int)dx, 0);
            }

            public int RowsPerPage { get { int ih = Math.Max(1, RowH); return Math.Max(1, ClientSize.Height / ih); } }

            protected override void OnPaintBackground(PaintEventArgs e) { /* todo en OnPaint */ }
            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics); }

            // Dibuja la pagina visible en cualquier Graphics (el control, o la textura de UI del modo GPU).
            // El fondo es OPACO (como el ListBox): la lista tapa el starfield donde esta (igual que en CPU).
            // Dibuja UNA pagina entera (la que empiece en 'arranque'). Antes esto era RenderContent tal cual;
            // se separo para poder HORNEARLA a un mapa de bits y despues solo copiarla: dibujar una pagina
            // cuesta 1,8 ms -son catorce filas con su texto, su numero, su genero y su duracion- y al hojear
            // hacen falta DOS a la vez, en cada cuadro de la animacion. Horneada, cada cuadro es una copia.
            private void PintaPagina(Graphics g, int arranque)
            {
                int w = ClientSize.Width, h = ClientSize.Height;
                if (w < 4 || h < 4) return;
                int n = (GetCount != null) ? GetCount() : 0;
                int rpp = RowsPerPage;
                if (hlB == null) { hlB = new SolidBrush(Color.Black); hlP = new Pen(Color.Black, 1.4f); }
                if (txtB == null)
                {   // GDI+ (DrawString), NO TextRenderer: TextRenderer usa GDI e IGNORA la traslacion del Graphics,
                    txtB = new SolidBrush(Color.White);   // asi que sobre la textura de UI (trasladada) el texto caia en 0,0
                    txtFmt = new StringFormat();
                    txtFmt.FormatFlags = StringFormatFlags.NoWrap;
                    txtFmt.Trimming = StringTrimming.EllipsisCharacter;
                    txtFmt.Alignment = StringAlignment.Near;
                    txtFmt.LineAlignment = StringAlignment.Center;
                }
                if (bgB == null) bgB = new SolidBrush(BackColor); else bgB.Color = BackColor;
                if (colaB == null)
                {
                    colaB = new SolidBrush(Color.Black);
                    cenFmt = CreaSfDibuja(StringAlignment.Center);
                }
                float cuerpo = Font.SizeInPoints;
                if (fNum == null || Math.Abs(fontFuente - cuerpo) > 0.01f)
                {
                    if (fNum != null) fNum.Dispose();
                    if (fCola != null) fCola.Dispose();
                    fNum = new Font(Font.FontFamily, cuerpo * 0.78f, FontStyle.Bold);
                    fCola = new Font(Font.FontFamily, cuerpo * 0.72f, FontStyle.Bold);
                    fontFuente = cuerpo;
                }
                g.FillRectangle(bgB, 0, 0, w, h);
                g.SmoothingMode = SmoothingMode.AntiAlias;
                float rad = Math.Min(11f, RowH * 0.34f);        // el circulito del numero
                float xTexto = 16 + rad * 2 + 10;
                // ALTO de las marcas. Sale del circulito del numero, pero ese va TOPADO (rad no pasa de 11)
                // para que en una fila alta no quede un circulo gigante... y la letra si crece con la fila. En
                // una pantalla grande eso dejaba el texto MAS ALTO que su propia pastilla, asomando por arriba
                // y por abajo. Asi que la pastilla crece tambien si hace falta para envolver a su letra.
                int hCola = Math.Max((int)(rad * 1.64f), fCola.Height + 4);
                EnsureHorno((int)(rad * 2), hCola);
                for (int row = 0; row < rpp; row++)
                {
                    int idx = arranque + row;
                    if (idx >= n) break;
                    Rectangle r = new Rectangle(0, row * RowH, w, RowH);
                    if (idx == Sel)
                    {
                        Rectangle hl = new Rectangle(r.X + 4, r.Y + 3, r.Width - 8, r.Height - 6);
                        hlB.Color = Color.FromArgb(150, Lighten(Accent, 0.15));
                        hlP.Color = Color.FromArgb(180, Lighten(Accent, 0.45));
                        using (GraphicsPath gp = RoundedPath(hl, 9)) { g.FillPath(hlB, gp); g.DrawPath(hlP, gp); }
                    }
                    // EL NUMERO DE PISTA en un circulito, y en VERDE si esa cancion ya esta pedida. Antes no
                    // habia forma de saber que ya la habias puesto: la volvias a pedir y gastabas otro credito.
                    // (y en AMBAR si es la que esta sonando en este momento)
                    int pos = (GetQueuePos != null) ? GetQueuePos(idx) : 0;
                    bool suena = (GetSonando != null) && GetSonando(idx);
                    bool enCola = pos > 0;
                    int marca = suena ? 2 : (enCola ? 1 : 0);   // el circulito manda lo mas urgente: que SUENA
                    float cy = r.Y + RowH * 0.5f;
                    g.DrawImageUnscaled((marca == 2) ? bmpCircSon : (marca == 1) ? bmpCircCola : bmpCirc, 16, (int)(cy - rad));
                    PintaNumero(g, idx + 1, 16 + rad, cy, marca);
                    // DURACION a la derecha (m:ss). Se dibuja primero para saber cuanto ancho quitarle al
                    // titulo: asi un nombre largo se corta con "..." ANTES de encimarse con la duracion.
                    string dur = (GetRight != null) ? GetRight(idx) : "";
                    int durW = 0;
                    if (!string.IsNullOrEmpty(dur))
                    {
                        if (durB == null)
                        {
                            durB = new SolidBrush(Color.White);
                            durFmt = new StringFormat();
                            durFmt.FormatFlags = StringFormatFlags.NoWrap;
                            durFmt.Alignment = StringAlignment.Far;
                            durFmt.LineAlignment = StringAlignment.Center;
                        }
                        durW = 58;
                        durB.Color = (idx == Sel) ? Color.FromArgb(235, 245, 255) : Color.FromArgb(175, 190, 215);
                        g.DrawString(dur, Font, durB, new Rectangle(r.Right - durW - 14, r.Y, durW, r.Height), durFmt);
                    }
                    // EL GENERO, en una pastillita, justo al lado de la duracion. Es el mismo genero y el
                    // mismo color que ya salen en los resultados del buscador: la rocola habla siempre igual.
                    int quitaGen = 0;
                    string gen = (GetGenero != null) ? GetGenero(idx) : null;
                    if (!string.IsNullOrEmpty(gen))
                    {
                        Bitmap pg = HorneaGenero(gen);
                        // Solo si sobra sitio: en una pantalla estrecha manda el nombre de la cancion.
                        if (pg != null && pg.Width + 18 <= (r.Width - (int)xTexto) / 2)
                        {
                            // Los 18 son los huecos de los dos lados: asi la pastilla nunca llega a rozar ni la
                            // duracion (a su derecha) ni la marca de "ya pedida" ni el nombre (a su izquierda).
                            quitaGen = pg.Width + 18;
                            g.DrawImageUnscaled(pg, r.Right - 20 - durW - pg.Width, (int)(cy - pg.Height * 0.5f));
                        }
                    }
                    // LAS DOS MARCAS CONVIVEN. Una cancion puede estar sonando Y estar pedida otra vez, y el
                    // cliente necesita saber las dos cosas: que la esta oyendo, y que ya la va a volver a oir.
                    // Antes la de la cola tapaba a la de sonando y parecia que no estaba sonando.
                    // Cada pastilla se mide POR SU TEXTO: con un ancho fijo, "SONANDO" no cabia y salia
                    // "SONAND". El triangulito de play delante deja claro cual es incluso sin leer la palabra.
                    int quitaCola = 0;
                    float xMarca = r.Right - 14 - durW - quitaGen;
                    if (enCola)
                    {
                        string t = "EN COLA " + pos;
                        int wp = AnchoTexto(g, t, fCola) + hCola;
                        xMarca -= wp;
                        RectangleF cr = new RectangleF(xMarca, cy - hCola * 0.5f, wp, hCola);
                        g.DrawImageUnscaled(Pastilla(false, wp, hCola), (int)cr.X, (int)cr.Y);
                        colaB.Color = ColaVerde;
                        g.DrawString(t, fCola, colaB, cr, cenFmt);
                        xMarca -= 8; quitaCola += wp + 8;
                    }
                    if (suena)
                    {
                        // U+25BA y no U+25B6: son dos triangulitos casi identicos, pero el otro no esta en el
                        // juego de simbolos que trae Windows XP y alli saldria un rectangulo vacio.
                        const string t = "\u25BA SONANDO";
                        int wp = AnchoTexto(g, t, fCola) + hCola;
                        xMarca -= wp;
                        RectangleF cr = new RectangleF(xMarca, cy - hCola * 0.5f, wp, hCola);
                        g.DrawImageUnscaled(Pastilla(true, wp, hCola), (int)cr.X, (int)cr.Y);
                        colaB.Color = SonAmbar;
                        g.DrawString(t, fCola, colaB, cr, cenFmt);
                        quitaCola += wp + 8;
                    }
                    if (quitaCola > 0) quitaCola += 4;   // un pelo de aire antes del nombre
                    // El nombre acaba SEIS PIXELES antes de lo primero que haya a su derecha. Antes se restaba
                    // un margen distinto del que usa la marca de "ya pedida", y un nombre largo llegaba a
                    // tocarla; ahora se calcula desde el mismo borde para los dos y siempre queda separacion.
                    int derContenido = r.Right - 14 - durW - quitaGen - quitaCola;
                    Rectangle tr = new Rectangle(r.X + (int)xTexto, r.Y, Math.Max(10, derContenido - 6 - r.X - (int)xTexto), r.Height);
                    string text = (GetText != null) ? GetText(idx) : "";
                    g.DrawString(text, Font, txtB, tr, txtFmt);   // GDI+: respeta la traslacion del Graphics (en el control es identidad; en la textura de UI lleva la lista a su sitio)
                }
            }

            private int RowIndexAt(int y) { int row = y / Math.Max(1, RowH); return PageStart + row; }

            protected override void OnMouseClick(MouseEventArgs e)
            {
                int idx = RowIndexAt(e.Y);
                if (GetCount != null && idx >= 0 && idx < GetCount() && OnPick != null) OnPick(idx);
                base.OnMouseClick(e);
            }
            protected override void OnMouseDoubleClick(MouseEventArgs e)
            {
                int idx = RowIndexAt(e.Y);
                if (GetCount != null && idx >= 0 && idx < GetCount() && OnActivate != null) OnActivate(idx);
                base.OnMouseDoubleClick(e);
            }
        }

        // ==========  BUSCADOR EN PANTALLA  ==========
        private enum KKind { Char, Space, Back, Choose }

        private class SearchKey
        {
            public KKind Kind;
            public char Ch;
            public string Label;
            public RectangleF R;
        }

        private class SearchOverlay : Control
        {
            public string Query = "";
            public List<SearchItem> Results = new List<SearchItem>();
            // De que disco es y de que genero cada resultado. Los pone Form1 (el genero lo aprende el paseo de
            // fondo). 'DatosVer' sube cuando eso cambia y entra en la firma del cache de las tarjetas: sin el,
            // los colores que llegan tarde no se verian hasta teclear otra cosa.
            public Func<SearchItem, string> GetDisco;
            public Func<SearchItem, string> GetGenero;
            public int DatosVer;
            public int SelRow = 1;
            public int SelCol = 0;
            public bool FocusResults = false;
            public int SelResult = 0;
            private int resCols = 1, resRowsPerCol = 8;   // dimensiones de la cuadricula de resultados (se fijan al pintar)
            public double CubeAngle = 0;
            public double Phase = 0;
            public Color Accent = DefaultAccent;
            public Func<Album, Image> GetCover;
            public Action<string> OnQueryChanged;
            public Action<SearchItem> OnChoose;
            public Action OnClose;
            public bool ToastOn = false;
            public string ToastMsg = "";
            public Color ToastBack = Color.FromArgb(238, 40, 165, 90);
            private Rectangle cubeRect = Rectangle.Empty;
            public double PreviewAngle { get { return CubeAngle; } }   // angulo del cubo de vista previa (lo dibuja la GPU)
            // Calcula EN VIVO el cubo de vista previa (celda + par de portadas a fundir) para que la GPU lo
            // dibuje como geometria. Devuelve false si no hay cubo de vista previa visible ahora.
            public bool GetPreviewCube(out Rectangle area, out Image ca, out Image cb, out float f)
            {
                area = Rectangle.Empty; ca = null; cb = null; f = 0f;
                int W = Width, H = Height;
                if (W < 60 || H < 60) return false;
                if (!(FocusResults && Results != null && Results.Count > 0 && GetCover != null)) return false;
                int M = 30, contentY = M + 70 + 28, contentH = H - contentY - M;
                if (contentH < 60) return false;
                int kbW = (int)((W - 2 * M) * 0.52);
                return ComputePreview(new Rectangle(M, contentY, kbW, contentH), out ca, out cb, out f, out area);
            }
            private readonly List<Image> artistCovers = new List<Image>();
            private Bitmap blendBmp;
            // COMPARTIDO con el fondo del form, igual que la rejilla de discos y el interior del disco: este
            // control pinta su VENTANA del mismo campo. Antes el buscador era el UNICO que se armaba su propio
            // campo de estrellas, y eso costaba doble: por un lado otro juego de bitmaps de pantalla completa
            // en memoria, por otro que su cielo era OTRO -las estrellas saltaban al abrir el buscador-.
            public Starfield Sky;
            public float PulseLo = 0f, PulseMid = 0f, PulseHi = 0f;   // pulso 0..1 por banda (graves/medios/agudos)
            public float BgDim = 1f;        // atenuacion del starfield mientras se navega con musica (el form la anima)
            // Brillo de la barra de instrucciones del buscador (Mover / Poner-Elegir / Cerrar) al pulsar.
            public const int SMover = 0, SPoner = 1, SCerrar = 2;
            private static readonly Color SRed = Color.FromArgb(228, 72, 72), SGreen = Color.FromArgb(72, 212, 112), SYellow = Color.FromArgb(242, 206, 72);
            private readonly InstrFlash hintFlash = new InstrFlash();
            public void FlashMove(bool vertical) { hintFlash.Fire(SMover, vertical ? SRed : SYellow); }   // arriba/abajo ROJO, izq/der AMARILLO
            public void FlashOK() { hintFlash.Fire(SPoner, SGreen); }
            public void FlashClose() { hintFlash.Fire(SCerrar, Color.White); }
            // Centro/radio de los 3 halos del hint bar (Mover/Poner/Cerrar), guardados al maquetar. En GPU el halo NO
            // se hornea en la textura: lo dibuja la GPU como quad (GetHintGlow) para que el desvanecido no re-suba la textura.
            private readonly float[] hgCx = new float[3], hgCy = new float[3], hgR = new float[3];
            private void StoreHintGlow(int k, float leftX, float cy, float symW) { hgCx[k] = leftX + symW / 2f; hgCy[k] = cy; hgR[k] = symW * 0.9f + 6f; }
            // La flecha de ARRIBA en una tecla redondeada, igual que en la casilla de BUSCAR de la fila de
            // arriba: el cliente ve el MISMO dibujo antes de entrar y dentro, asi que no tiene que aprender
            // dos cosas.
            private static float FlechaArriba(Graphics g, float x, int cy, int d, Color c)
            {
                Rectangle k = new Rectangle((int)x, cy - d / 2, d, d);
                using (GraphicsPath gp = RoundedPath(k, Math.Max(3, d / 4)))
                {
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(70, c))) g.FillPath(sb, gp);
                    using (Pen pn = new Pen(Color.FromArgb(215, c), 1.6f)) g.DrawPath(pn, gp);
                }
                float cx = x + d / 2f, t = d * 0.30f, an = d * 0.24f;
                CtrlTri(g, c, new PointF(cx, cy - t), new PointF(cx - an, cy + t * 0.62f), new PointF(cx + an, cy + t * 0.62f));
                return x + d;
            }
            public bool GetHintGlow(int k, out float cx, out float cy, out float r, out int argb)
            {
                cx = cy = r = 0f; argb = 0;
                if (k < 0 || k > 2) return false;
                float lvl = hintFlash.Level(k);   // k == SMover/SPoner/SCerrar (0/1/2)
                if (lvl <= 0.02f) return false;
                cx = hgCx[k]; cy = hgCy[k]; r = hgR[k];
                Color c = hintFlash.Col(k);
                argb = Color.FromArgb((int)(lvl * 215f), c.R, c.G, c.B).ToArgb();   // alfa = brillo del destello; rgb = su color
                return true;
            }
            // Recursos de pintado CACHEADOS: el buscador creaba ~90 objetos GDI por cuadro (fuentes,
            // pinceles y plumas, incluso por cada tecla y resultado) a 24fps. Ahora todo es reusable.
            private Font fQuery, fHint, fToast, fHead, fEmpty, fRes, fResSub, fPrevT, fPrevS, fPrevH;
            private Font fChar, fSp; private float fKh = -1f;   // fuentes del teclado (dependen de su altura)
            private SolidBrush sbS; private Pen pnS;            // pincel/pluma reusables (se les muta color/grosor)
            // CACHE del teclado SIN seleccion: las ~40 teclas (con degradado, contorno y texto) son carisimas
            // de redibujar cada vez (RoundedPath + LinearGradientBrush por tecla). Como el teclado es estatico,
            // se dibuja UNA vez a un bitmap y luego solo se copia + se pinta EN VIVO la tecla seleccionada.
            private Bitmap kbCache; private int kbCacheW = -1, kbCacheH = -1, kbCacheAccent; private float kbCacheKh = -1f;
            private Point kbCacheOrigin;
            // CACHE de la lista de resultados (mismo motivo que el teclado): ~40 tarjetas con degradado, contorno
            // y 2 textos cada una. Los resultados dependen SOLO de la consulta, asi que se cachean por Query y
            // solo se pinta EN VIVO la tarjeta seleccionada. Moverse por teclas/resultados deja de dar tirones.
            private Bitmap resCache; private string resCacheQuery = "\0"; private int resCacheW = -1, resCacheH = -1, resCacheAccent, resCacheDatos = -1;
            private SolidBrush marcaB;   // el resaltado de lo tecleado (reusable)
            private Point resCacheOrigin;
            // HORNOS DE LA TARJETA DE RESULTADO. Todas las tarjetas miden lo mismo, asi que su fondo (rectangulo
            // redondeado relleno + borde, con antialias) se dibuja UNA vez a un bitmap y luego cada tarjeta lo
            // copia. Igual la pastilla del genero, de la que solo hay una docena distintas en toda la rocola.
            // Antes se dibujaban a mano en las CUARENTA tarjetas cada vez que el cliente tecleaba una letra.
            private Bitmap bmpTarj, bmpTarjSel;
            private int hornoTarjW = -1, hornoTarjH = -1, hornoTarjAc;
            private readonly Dictionary<string, Bitmap> hornoGen = new Dictionary<string, Bitmap>();
            private void EnsureHornoTarjeta(int w, int h)
            {
                int ac = Accent.ToArgb();
                if (bmpTarj != null && hornoTarjW == w && hornoTarjH == h && hornoTarjAc == ac) return;
                if (bmpTarj != null) bmpTarj.Dispose();
                if (bmpTarjSel != null) bmpTarjSel.Dispose();
                bmpTarj = HorneaTarjeta(w, h, false);
                bmpTarjSel = HorneaTarjeta(w, h, true);
                hornoTarjW = w; hornoTarjH = h; hornoTarjAc = ac;
            }
            // El borde se traza CENTRADO en el contorno de la tarjeta: la mitad de fuera cae sobre el fondo.
            // Por eso el bitmap lleva un margen de MargenTarj a cada lado y se pega desplazado: asi lo que
            // sale en pantalla es identico al pixel a dibujarla a mano, que es lo que se hacia antes.
            private const int MargenTarj = 3;
            private Bitmap HorneaTarjeta(int w, int h, bool sel)
            {
                if (w < 2) w = 2; if (h < 2) h = 2;
                Bitmap b = new Bitmap(w + 2 * MargenTarj, h + 2 * MargenTarj, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(b))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    using (GraphicsPath gp = RoundedPath(new Rectangle(MargenTarj, MargenTarj, w, h), 8))
                    {
                        using (SolidBrush sb = new SolidBrush(sel ? Shade(Accent, 0.26) : Shade(Accent, 0.50))) g.FillPath(sb, gp);
                        using (Pen pn = new Pen(Color.FromArgb(sel ? 215 : 100, 160, 200, 245), sel ? 2f : 1.1f)) g.DrawPath(pn, gp);
                    }
                }
                return b;
            }
            private Bitmap HorneaGeneroRes(Graphics medidor, string etiqueta)
            {
                Bitmap b;   // el color sale del GENERO, no del color de la seccion: no caduca nunca
                if (hornoGen.TryGetValue(etiqueta, out b)) return b;
                Color c = ColorDeEtiqueta(etiqueta);
                Size gs = TextRenderer.MeasureText(medidor, etiqueta, fResSub, new Size(9999, 99), TextFormatFlags.NoPadding);
                int w = gs.Width + 14, h = 15;
                if (w < 8) w = 8;
                b = new Bitmap(w + 2 * MargenTarj, h + 2 * MargenTarj, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(b))
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.Clear(Color.Transparent);
                    using (GraphicsPath gp = RoundedPath(new Rectangle(MargenTarj, MargenTarj, w, h), 7))
                    {
                        using (SolidBrush sb = new SolidBrush(Color.FromArgb(60, c))) g.FillPath(sb, gp);
                        using (Pen pn = new Pen(Color.FromArgb(120, c), 1f)) g.DrawPath(pn, gp);
                    }
                }
                hornoGen[etiqueta] = b;
                return b;
            }
            // Los tres rotulos posibles (ARTISTA/ALBUM/CANCION) miden siempre lo mismo: se mide una vez.
            private readonly int[] anchoRotulo = { -1, -1, -1 };
            private int altoLetra = -1;   // alto de una letra en la fuente del nombre: es siempre el mismo
            private int AnchoRotulo(Graphics g, int kind, string tag)
            {
                if (kind < 0 || kind > 2) return TextRenderer.MeasureText(g, tag, fResSub, new Size(9999, 99), TextFormatFlags.NoPadding).Width;
                if (anchoRotulo[kind] < 0)
                    anchoRotulo[kind] = TextRenderer.MeasureText(g, tag, fResSub, new Size(9999, 99), TextFormatFlags.NoPadding).Width;
                return anchoRotulo[kind];
            }

            private void EnsurePaintRes()
            {
                if (fQuery != null) return;
                fQuery = new Font(FontFamily.GenericSansSerif, 20f, FontStyle.Bold);
                fHint = new Font(FontFamily.GenericSansSerif, 9.5f, FontStyle.Bold);
                fToast = new Font(FontFamily.GenericSansSerif, 15.5f, FontStyle.Bold);
                fHead = new Font(FontFamily.GenericSansSerif, 13f, FontStyle.Bold);
                fEmpty = new Font(FontFamily.GenericSansSerif, 11f, FontStyle.Italic);
                fRes = new Font(FontFamily.GenericSansSerif, 10.5f, FontStyle.Bold);
                fResSub = new Font(FontFamily.GenericSansSerif, 7.5f, FontStyle.Bold);
                fPrevT = new Font(FontFamily.GenericSansSerif, 15f, FontStyle.Bold);
                fPrevS = new Font(FontFamily.GenericSansSerif, 11f, FontStyle.Regular);
                fPrevH = new Font(FontFamily.GenericSansSerif, 11f, FontStyle.Bold);
                sbS = new SolidBrush(Color.Black);
                pnS = new Pen(Color.Black, 1f);
            }

            private readonly List<List<SearchKey>> rows = new List<List<SearchKey>>();
            private readonly List<KeyValuePair<RectangleF, int>> resultRects = new List<KeyValuePair<RectangleF, int>>();

            public SearchOverlay()
            {
                this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.Selectable, true);
                this.TabStop = true;
                this.BackColor = Color.FromArgb(8, 12, 36);
                BuildKeys();
            }

            private void BuildKeys()
            {
                AddRow("1234567890");
                AddRow("QWERTYUIOP");
                AddRow("ASDFGHJKL\u00D1");
                AddRow("ZXCVBNM");
                List<SearchKey> sp = new List<SearchKey>();
                sp.Add(new SearchKey { Kind = KKind.Space, Label = "ESPACIO" });
                sp.Add(new SearchKey { Kind = KKind.Back, Label = "BORRAR" });
                rows.Add(sp);
            }

            private void AddRow(string s)
            {
                List<SearchKey> row = new List<SearchKey>();
                for (int i = 0; i < s.Length; i++)
                    row.Add(new SearchKey { Kind = KKind.Char, Ch = s[i], Label = s[i].ToString() });
                rows.Add(row);
            }

            // REPINTADO PARCIAL. El buscador se repintaba ENTERO veinticuatro veces por segundo: a pantalla
            // completa eso es rehacer el fondo estrellado -que late con la musica- mas dos copias grandes (el
            // teclado y las tarjetas) en CADA cuadro. Casi nada de eso cambia de un cuadro al siguiente: lo unico
            // que se mueve solo es el cubo que gira y el destello del boton recien pulsado. Esto repinta SOLO eso;
            // el cuadro completo se pide una de cada tres veces. Al pulsar una tecla se sigue repintando entero,
            // asi que la respuesta al cliente es la misma de siempre.
            public void InvalidarVivo()
            {
                if (ToastOn) { Invalidate(); return; }   // el aviso flotante entra y sale: ahi si toca todo
                int W = Width, H = Height;
                if (W < 60 || H < 60) return;
                int M = 30, kbW = (int)((W - 2 * M) * 0.52);
                int der = Math.Min(W, M + kbW + 10);   // sin pasar a la mitad derecha: alli las tarjetas estan quietas
                // Se marcan varios trozos SUELTOS, no uno grande que los englobe: Windows suma zonas, asi que
                // aunque la tecla elegida este abajo del todo y las ayudas arriba, lo que se repinta de verdad
                // son esos dos trocitos y no la franja entera que va de uno a otro.
                // 1) la franja de las ayudas, con margen de sobra: el halo del destello se sale de la linea del texto
                Invalidate(new Rectangle(0, Math.Max(0, M + 46), der, 112));
                // 2) el cubo que gira, con su texto debajo
                if (cubeRect.Width > 1 && cubeRect.Height > 1) Invalidate(Rectangle.Inflate(cubeRect, 26, 84));
                // 3) con el teclado a la vista, la tecla ELEGIDA respira (su borde late al ritmo de la fase)
                else if (SelRow >= 0 && SelRow < rows.Count && SelCol >= 0 && SelCol < rows[SelRow].Count)
                {
                    Rectangle kr = Rectangle.Round(rows[SelRow][SelCol].R);
                    kr.Inflate(10, 10);
                    Invalidate(kr);
                }
            }

            // LO TECLEADO Y LO QUE MANDA EN LOS RESULTADOS SON DOS COSAS.
            //
            // Antes eran la misma, y por eso cada letra rehacia y subia la textura de pantalla completa:
            // 2.80 ms por pulsacion a 1920 -7.3 MB- mas 3.07 ms de rehornear las 40 tarjetas. Quien teclea
            // suelta cinco o diez letras por segundo, asi que eso pasaba diez veces en un segundo, en la
            // escena que el medidor señala como la peor.
            //
            // Mientras las letras estan entrando NADIE esta leyendo los resultados; lo que si tiene que
            // verse al instante es lo que se escribe. Asi que 'Escrito' se apunta letra a letra y va en su
            // propia imagen chica (ver PiezaEscrito), y 'Query' -la que manda en los resultados y en la
            // firma de la pantalla completa- se POSA cuando la persona para de teclear. Las consultas
            // intermedias, que nadie llega a leer, ni se buscan ni se hornean.
            public string Escrito = "";
            public void SetQuery(string q) { Query = q; Escrito = q; FocusResults = false; SelResult = 0; Invalidate(); }
            public void TypeChar(char c) { Escrito += c; Tecleo(); }
            public void Backspace() { if (Escrito.Length > 0) Escrito = Escrito.Substring(0, Escrito.Length - 1); Tecleo(); }

            // Una letra entra: se ve al momento, y nada mas. La caja de lo escrito es una imagen chica
            // aparte, asi que repintarla no arrastra ni el cielo ni el teclado.
            public Action OnTecleo;
            private void Tecleo()
            {
                if (OnTecleo != null) OnTecleo();
                Rectangle arriba, derecha;
                if (ToastOn || !ZonasAlEscribir(out arriba, out derecha)) Invalidate(); else Invalidate(arriba);
            }

            // Y aqui es donde los resultados se enteran. Lo llama el formulario cuando la persona para.
            public void PosaConsulta()
            {
                if (Query == Escrito) return;   // ya estaban enseñando esto: no hay nada que rehacer
                Query = Escrito;
                Changed();
            }
            // AL TECLEAR NO CAMBIA MEDIA PANTALLA. Escribir una letra toca la caja de lo escrito y las
            // tarjetas de la derecha, y nada mas: el teclado se queda exactamente igual, tecla por tecla.
            // Marcando solo esas dos zonas, lo que hay que volver a copiar debajo -el cielo- se reduce a la
            // mitad, y el teclado horneado no se copia en absoluto. A 1920x1080 eso es lo que se notaba al
            // escribir rapido.
            //
            // La UNICA vez que el lado del teclado si cambia es cuando se venia de estar en los resultados:
            // alli habia un cubo girando en su sitio y ahora vuelven las teclas. Ese caso pide todo.
            // Los resultados pasan a otra consulta. Cuesta: rehornear las 40 tarjetas son 3.07 ms. Por eso
            // esto ya NO se llama en cada letra, sino cuando la consulta se posa.
            private void Changed()
            {
                bool veniaDeResultados = FocusResults;
                FocusResults = false; SelResult = 0;
                if (OnQueryChanged != null) OnQueryChanged(Query);
                Rectangle arriba, derecha;
                if (veniaDeResultados || ToastOn || !ZonasAlEscribir(out arriba, out derecha)) { Invalidate(); return; }
                // Dos trozos SUELTOS, no uno que los englobe: Windows suma zonas y repinta solo estas dos.
                Invalidate(arriba); Invalidate(derecha);
            }

            // LAS DOS ZONAS QUE CAMBIAN AL ESCRIBIR UNA LETRA: la caja de lo escrito con su barra de ayudas,
            // y la columna de resultados. En medio queda el teclado, que no cambia.
            // Va en un metodo aparte para que la prueba pueda pedir ESTAS zonas y no una copia de la cuenta:
            // si fueran dos copias, cambiar una y olvidar la otra dejaria medio buscador congelado sin que la
            // prueba se enterara, que es exactamente el fallo que esta vigilando.
            public bool ZonasAlEscribir(out Rectangle arriba, out Rectangle derecha)
            {
                arriba = Rectangle.Empty; derecha = Rectangle.Empty;
                int W = Width, H = Height;
                if (W < 60 || H < 60) return false;
                int M = 30, kbW = (int)((W - 2 * M) * 0.52);
                arriba = new Rectangle(0, 0, W, M + 70 + 28);
                int rx = Math.Max(0, M + kbW + 10);
                derecha = new Rectangle(rx, 0, Math.Max(1, W - rx), H);
                return true;
            }

            public void MoveSel(int dx, int dy)
            {
                if (FocusResults)
                {
                    int cap = Math.Max(1, resCols * resRowsPerCol);
                    int n = Math.Min((Results != null) ? Results.Count : 0, cap);
                    if (n == 0) { if (dx < 0) FocusResults = false; Invalidate(); return; }
                    if (SelResult < 0) SelResult = 0;
                    if (SelResult >= n) SelResult = n - 1;
                    int rpc = (resRowsPerCol > 0) ? resRowsPerCol : 1;
                    int col = SelResult / rpc, row = SelResult % rpc;
                    if (dx < 0 && col == 0) { FocusResults = false; Invalidate(); return; }   // izquierda en 1a columna -> teclado
                    if (dy != 0)
                    {
                        int nr = row + dy; if (nr < 0) nr = 0; if (nr >= rpc) nr = rpc - 1;
                        int ni = col * rpc + nr; if (ni < n) SelResult = ni;
                    }
                    if (dx != 0)
                    {
                        int nc = col + dx; if (nc < 0) nc = 0;
                        int ni = nc * rpc + row; if (ni >= n) ni = n - 1;
                        if (ni >= 0) SelResult = ni;
                    }
                    Invalidate();
                    return;
                }
                if (rows.Count == 0) return;
                if (dy != 0)
                {
                    SelRow += dy;
                    if (SelRow < 0) SelRow = 0;
                    if (SelRow >= rows.Count) SelRow = rows.Count - 1;
                    if (SelCol >= rows[SelRow].Count) SelCol = rows[SelRow].Count - 1;
                }
                if (dx != 0)
                {
                    if (dx > 0 && SelCol >= rows[SelRow].Count - 1 && Results != null && Results.Count > 0)
                    {
                        FocusResults = true; SelResult = 0; Invalidate(); return;
                    }
                    SelCol += dx;
                    if (SelCol < 0) SelCol = 0;
                    if (SelCol >= rows[SelRow].Count) SelCol = rows[SelRow].Count - 1;
                }
                Invalidate();
            }

            public void PressSelected()
            {
                if (FocusResults)
                {
                    if (Results != null && SelResult >= 0 && SelResult < Results.Count && OnChoose != null) OnChoose(Results[SelResult]);
                    return;
                }
                if (SelRow < 0 || SelRow >= rows.Count) return;
                if (SelCol < 0 || SelCol >= rows[SelRow].Count) return;
                Activate(rows[SelRow][SelCol]);
            }

            private void Activate(SearchKey k)
            {
                if (k.Kind == KKind.Char) TypeChar(k.Ch);
                else if (k.Kind == KKind.Space) TypeChar(' ');
                else if (k.Kind == KKind.Back) Backspace();
                else if (k.Kind == KKind.Choose) { if (Results != null && Results.Count > 0 && OnChoose != null) OnChoose(Results[0]); }
            }

            protected override void OnMouseClick(MouseEventArgs e)
            {
                if (!FocusResults)
                {
                    for (int r = 0; r < rows.Count; r++)
                        for (int c = 0; c < rows[r].Count; c++)
                            if (rows[r][c].R.Contains(e.X, e.Y)) { SelRow = r; SelCol = c; Activate(rows[r][c]); Invalidate(); base.OnMouseClick(e); return; }
                }
                else if (cubeRect != Rectangle.Empty && cubeRect.Contains(e.X, e.Y))
                {
                    FocusResults = false; Invalidate(); base.OnMouseClick(e); return;
                }
                for (int i = 0; i < resultRects.Count; i++)
                    if (resultRects[i].Key.Contains(e.X, e.Y))
                    {
                        int idx = resultRects[i].Value;
                        if (Results != null && idx >= 0 && idx < Results.Count && OnChoose != null) OnChoose(Results[idx]);
                        base.OnMouseClick(e); return;
                    }
                base.OnMouseClick(e);
            }

            protected override void OnPaint(PaintEventArgs e) { RenderContent(e.Graphics, e.ClipRectangle, false); }

            // Dibuja el buscador en cualquier Graphics. forGpu=true: NO pinta el starfield ni el cubo de vista
            // previa (los pone la GPU: starfield de fondo + cubo como geometria); aqui solo la UI (transparente).
            // LA PIEZA QUE CAMBIA AL MOVERSE: la tecla elegida.
            //
            // Se dibuja EN VIVO encima del teclado cacheado, y eso ya estaba bien. El problema era que iba
            // DENTRO de la imagen de pantalla completa, y la tecla elegida entraba en la firma de esa imagen:
            // pulsar una flecha obligaba a REHACERLA Y RE-SUBIRLA entera a la tarjeta grafica. Medido: 5.91 ms
            // por pulsacion a 1080p, el 35% de un cuadro; y como las flechas no frenaban la auto-repeticion,
            // mantener una pulsada eran ~30 de esas por segundo. ESO era lo que hundia los cuadros por segundo
            // al teclear, hasta en una maquina potente: el gasto no es pintar -de eso la tarjeta va sobrada-
            // sino rehacer la imagen en el procesador y empujar siete megas por el bus.
            //
            // Ahora sale APARTE, en su propia imagen chica, igual que la franja de estado de abajo (ver
            // EnsureUiBotOverlay). Moverse por el teclado ya no toca la imagen grande.
            //
            // SOLO LA TECLA. La tarjeta elegida de los resultados se probo tambien y se quito: moverse por
            // los resultados cambia ademas el cubo de la portada y el texto de debajo, que van dentro de la
            // imagen grande, asi que esa mitad hay que rehacerla igual.
            //
            // Que sale IGUAL esta comprobado pixel a pixel, y no es suerte: la pieza se rellena OPACA, asi que
            // tapa entero su hueco y no hay borde suavizado que se mezcle dos veces (ver pruebas/mover.cs).
            public const int PiezaTecla = 0;
            // Y la caja de lo escrito, que es la que cambia en CADA letra. Antes iba dentro de la imagen de
            // pantalla completa y por eso teclear costaba 2.80 ms por pulsacion a 1920 (7.3 MB); aqui es una
            // tira de unos cientos de KB.
            public const int PiezaEscrito = 1;
            private bool paraGpu;   // dibujando para la imagen de pantalla completa: la tecla elegida va aparte

            // Donde va la pieza, en coords del buscador. false = ahora no hay ninguna que dibujar.
            //
            // Con los RESULTADOS enfocados no hay: ahi el teclado ni se dibuja -en su hueco va el cubo de la
            // portada- y sus teclas ni siquiera tienen sitio asignado. Devolver una igual dejaba una tecla
            // suelta flotando encima del cubo, que es justo lo que se veia en el bar.
            public bool PiezaViva(int cual, out Rectangle donde)
            {
                donde = Rectangle.Empty;
                if (cual == PiezaEscrito)
                {
                    // La caja de lo escrito se ve SIEMPRE que el buscador esta abierto, tambien con el foco
                    // en los resultados: es donde se lee lo que se busco.
                    Rectangle cj = CajaEscrito();
                    if (cj.Width < 8 || cj.Height < 8) return false;
                    donde = Rectangle.Inflate(cj, 2, 2);
                    return true;
                }
                if (cual != PiezaTecla || FocusResults) return false;
                if (SelRow < 0 || SelRow >= rows.Count || SelCol < 0 || SelCol >= rows[SelRow].Count) return false;
                Rectangle kr = Rectangle.Round(rows[SelRow][SelCol].R);
                if (kr.Width < 2 || kr.Height < 2) return false;   // el teclado aun no se ha repartido
                donde = Rectangle.Inflate(kr, 2, 2);
                return true;
            }

            // Y la dibuja. El desplazamiento va POR PARAMETRO y no moviendo el lienzo: el texto lo pinta el
            // sistema (TextRenderer) en pixeles de verdad y no hace caso a las trasformaciones, asi que
            // moviendo el lienzo la letra se iba fuera de la imagen chica (ver EnsureUiPieza).
            public void DibujaPiezaViva(Graphics g, int cual, int dx, int dy)
            {
                if (cual == PiezaEscrito)
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    DibujaCajaEscrito(g, dx, dy, true);
                    return;
                }
                if (cual != PiezaTecla || FocusResults) return;
                if (SelRow < 0 || SelRow >= rows.Count || SelCol < 0 || SelCol >= rows[SelRow].Count) return;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                DrawOneKey(g, SelRow, SelCol, true, dx, dy);
            }

            // LA CAJA DONDE SE ESCRIBE. Su sitio lo saben los dos caminos: el dibujado normal y la imagen
            // chica que la lleva cuando hay tarjeta grafica.
            public Rectangle CajaEscrito() { int M = 30; return new Rectangle(M, M, Width - 2 * M, 70); }

            // Y como se dibuja. El desplazamiento va POR PARAMETRO y no moviendo el lienzo, por lo mismo que
            // en DibujaPiezaViva: el texto lo pinta el sistema en pixeles de verdad y no hace caso a las
            // trasformaciones.
            private void DibujaCajaEscrito(Graphics g, int dx, int dy, bool sinParpadeo)
            {
                Rectangle qb = CajaEscrito(); qb.Offset(dx, dy);
                EnsurePaintRes();
                using (GraphicsPath gp = RoundedPath(qb, 16))
                {
                    sbS.Color = Shade(Accent, 0.42); g.FillPath(sbS, gp);
                    pnS.Color = Lighten(Accent, 0.35); pnS.Width = 2f; g.DrawPath(pnS, gp);
                }
                // Con tarjeta grafica el cursor NO parpadea (fijo): parpadear obligaria a rehacer esta imagen
                // una vez por segundo aunque nadie estuviera escribiendo.
                bool caretOn = sinParpadeo || Math.Sin(Phase * 3.0) > 0;
                string shown = "Buscar:  " + Escrito + (caretOn ? "|" : "");
                TextRenderer.DrawText(g, shown, fQuery, new Rectangle(qb.X + 18, qb.Y, qb.Width - 30, qb.Height), Color.White, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
            }

            public void RenderContent(Graphics g, Rectangle clip, bool forGpu)
            {
                int W = Width, H = Height;
                if (W < 60 || H < 60) return;
                paraGpu = forGpu;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                if (forGpu) clip = new Rectangle(0, 0, W, H);

                if (!forGpu)
                {
                    // EL CIELO, POR EL CAMINO RAPIDO. El buscador era el unico sitio que lo redibujaba entero
                    // -las seiscientas estrellas, una a una, con su halo- en cada repintado. A 1920x1080 eso
                    // costaba 8.2 ms POR CUADRO, y como al teclear se repinta todo, cada letra costaba 20 ms:
                    // de ahi el bajon de imagenes por segundo al escribir, peor cuanto mas grande la pantalla.
                    // Ahora hace lo mismo que la rejilla de discos: copia el cielo ya horneado y las estrellas
                    // ya horneadas (dos copias), y encima le pone EN VIVO solo lo que de verdad se mueve, que
                    // es el latido de las medianas/grandes y las fugaces. Se ve igual y cuesta una decima parte.
                    if (Sky != null)
                    {
                        Sky.SkyOffsetX = this.Left; Sky.SkyOffsetY = this.Top;
                        Sky.SkyFullW = (this.Parent != null) ? this.Parent.ClientSize.Width : W;
                        Sky.SkyFullH = (this.Parent != null) ? this.Parent.ClientSize.Height : H;
                        Sky.SkyMid = SkyColorMid(Accent); Sky.Acento = Accent;
                        Sky.Dim = BgDim;   // atenuado mientras se navega con musica
                        Sky.DrawReactive(g, W, H, SkyColor(Accent), SkyColor2(Accent), PulseLo, PulseMid, PulseHi);
                    }
                }

                int M = 30;   // el mismo margen que usa CajaEscrito: de aqui cuelga todo el reparto de abajo
                Rectangle qb = CajaEscrito();
                Rectangle hintRect = new Rectangle(qb.X, qb.Bottom + 2, qb.Width, 26);
                if (qb.IntersectsWith(clip) || hintRect.IntersectsWith(clip))
                {
                    EnsurePaintRes();
                    // CON TARJETA GRAFICA la caja de lo escrito NO se dibuja aqui: va en su propia imagen
                    // chica (PiezaEscrito), que es lo que hace que teclear no rehaga los siete megas de la
                    // pantalla completa en cada letra. Sin tarjeta se dibuja aqui, como siempre.
                    if (!forGpu) DibujaCajaEscrito(g, 0, 0, false);
                    {
                        Font hf = fHint;
                        int hcy = hintRect.Y + hintRect.Height / 2;
                        Color htx = Color.FromArgb(214, 222, 242);
                        int hd = 20; float hgap = 7, hgrp = 20;   // MISMO tamano que la barra principal
                        float hx = hintRect.X;
                        // Guarda el centro/radio del halo (para dibujarlo por GPU). En GPU NO se hornea aqui (forGpu);
                        // en CPU si se pinta como siempre. Asi el destello se anima por GPU sin re-subir la textura.
                        StoreHintGlow(SMover, hx, hcy, hd + 2);
                        if (!forGpu) GlowAround(g, hx, hcy, hd + 2, hintFlash.Level(SMover), hintFlash.Col(SMover));   // MOVER = cruceta (color segun direccion)
                        hx = CtrlPad(g, hx, hcy, hd + 2);
                        hx = CtrlTxt(g, hf, "Mover", hx + hgap, hcy, htx) + hgrp;
                        StoreHintGlow(SPoner, hx, hcy, hd);
                        if (!forGpu) GlowAround(g, hx, hcy, hd, hintFlash.Level(SPoner), hintFlash.Col(SPoner));        // PONER/ELEGIR = punto verde
                        hx = CtrlDot(g, hx, hcy, hd, SGreen);
                        hx = CtrlTxt(g, hf, "Poner / Elegir", hx + hgap, hcy, htx) + hgrp;
                        // CERRAR = los MISMOS dos botones con los que se abrio (rojo + arriba). Antes era
                        // rojo + verde, que ademas chocaba con el verde de "poner": el cliente que queria
                        // salir apretaba el verde y ponia una cancion sin querer.
                        StoreHintGlow(SCerrar, hx, hcy, hd * 2 + 3);
                        if (!forGpu) GlowAround(g, hx, hcy, hd * 2 + 3, hintFlash.Level(SCerrar), hintFlash.Col(SCerrar));   // CERRAR = rojo + arriba
                        hx = CtrlDot(g, hx, hcy, hd, SRed) + 3;
                        hx = CtrlTxt(g, hf, "+", hx, hcy, htx) + 3;
                        hx = FlechaArriba(g, hx, hcy, hd, SRed);
                        hx = CtrlTxt(g, hf, "Cerrar", hx + hgap, hcy, htx);
                    }
                }

                int contentY = M + 70 + 28;
                int contentH = H - contentY - M;
                if (contentH < 60) return;
                int kbW = (int)((W - 2 * M) * 0.52);   // teclado mas angosto -> resultados mas anchos (caben 2 columnas)
                Rectangle kbRegion = new Rectangle(M, contentY, kbW, contentH);
                Rectangle resRegion = new Rectangle(M + kbW + 20, contentY, (W - 2 * M) - kbW - 20, contentH);

                bool showCube = FocusResults && Results != null && Results.Count > 0 && GetCover != null;
                if (showCube)
                {
                    if (forGpu)
                    {
                        Image ca, cb; float f; Rectangle area;
                        if (ComputePreview(kbRegion, out ca, out cb, out f, out area)) DrawPreviewInfo(g, kbRegion, area);   // el cubo lo dibuja la GPU; aqui solo el texto/ayuda
                    }
                    else if (kbRegion.IntersectsWith(clip)) DrawPreviewCube(g, kbRegion);
                }
                else
                {
                    cubeRect = Rectangle.Empty;
                    LayoutKeys(kbRegion);
                    if (kbRegion.IntersectsWith(clip)) DrawKeys(g, kbRegion);
                }
                if (resRegion.IntersectsWith(clip)) DrawResults(g, resRegion);

                if (ToastOn) DrawToast(g, W, H);
            }

            private void DrawToast(Graphics g, int W, int H)
            {
                int tw = 400, th = 56;
                Rectangle r = new Rectangle((W - tw) / 2, 104, tw, th);
                EnsurePaintRes();
                using (GraphicsPath gp = RoundedPath(r, 16))
                {
                    sbS.Color = ToastBack; g.FillPath(sbS, gp);
                    pnS.Color = Lighten(ToastBack, 0.45); pnS.Width = 2.4f; g.DrawPath(pnS, gp);
                }
                TextRenderer.DrawText(g, ToastMsg, fToast, r, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
            }

            private void LayoutKeys(Rectangle region)
            {
                int rowsN = rows.Count;
                if (rowsN == 0) return;
                float gap = 6;
                float rowH = (region.Height - gap * (rowsN - 1)) / rowsN;
                int cols = 10;
                float keyW = (region.Width - gap * (cols - 1)) / cols;
                for (int r = 0; r < rows.Count; r++)
                {
                    float y = region.Y + r * (rowH + gap);
                    if (r < 4)
                    {
                        int c = rows[r].Count;
                        float totalW = c * keyW + gap * (c - 1);
                        float x0 = region.X + (region.Width - totalW) / 2f;
                        for (int c2 = 0; c2 < c; c2++)
                            rows[r][c2].R = new RectangleF(x0 + c2 * (keyW + gap), y, keyW, rowH);
                    }
                    else
                    {
                        int n = rows[r].Count;
                        float[] frac;
                        if (n == 2) frac = new float[] { 0.60f, 0.40f };          // ESPACIO mas ancho, BORRAR
                        else if (n == 3) frac = new float[] { 0.40f, 0.28f, 0.32f };
                        else { frac = new float[n]; for (int q = 0; q < n; q++) frac[q] = 1f / n; }
                        float avail = region.Width - gap * (n - 1);
                        float x = region.X;
                        for (int c2 = 0; c2 < n; c2++)
                        {
                            float fw = avail * frac[c2];
                            rows[r][c2].R = new RectangleF(x, y, fw, rowH);
                            x += fw + gap;
                        }
                    }
                }
            }

            private void DrawKeys(Graphics g, Rectangle region)
            {
                if (rows.Count == 0 || rows[0].Count == 0) return;
                float kh = rows[0][0].R.Height;
                if (kh < 8) kh = 8;
                EnsurePaintRes();
                if (fChar == null || fKh != kh)   // fuentes del teclado: solo se recrean si cambia su altura
                {
                    if (fChar != null) fChar.Dispose();
                    if (fSp != null) fSp.Dispose();
                    fChar = new Font(FontFamily.GenericSansSerif, Math.Max(12f, kh * 0.42f), FontStyle.Bold);
                    fSp = new Font(FontFamily.GenericSansSerif, Math.Max(9f, kh * 0.24f), FontStyle.Bold);
                    fKh = kh;
                }
                if (region.Width < 2 || region.Height < 2) return;
                // CACHE de las teclas SIN seleccion: se rehace solo si cambia tamano/altura/color (casi nunca).
                // Dibujar 40 teclas (degradado + contorno + texto) en cada cuadro era lo que hundia el FPS del
                // buscador; ahora se copia el cache + SOLO la tecla seleccionada en vivo (barato).
                int accentArgb = Accent.ToArgb();
                if (kbCache == null || kbCacheW != region.Width || kbCacheH != region.Height || kbCacheAccent != accentArgb || kbCacheKh != kh)
                {
                    if (kbCache == null || kbCache.Width != region.Width || kbCache.Height != region.Height)   // REUSA si el tamano no cambio (p.ej. solo cambio el color)
                    {
                        if (kbCache != null) kbCache.Dispose();
                        kbCache = new Bitmap(region.Width, region.Height, PixelFormat.Format32bppPArgb);
                    }
                    using (Graphics cg = Graphics.FromImage(kbCache))
                    {
                        cg.Clear(Color.Transparent);
                        cg.SmoothingMode = SmoothingMode.AntiAlias;
                        for (int r = 0; r < rows.Count; r++)
                            for (int c = 0; c < rows[r].Count; c++)
                                DrawOneKey(cg, r, c, false, -region.X, -region.Y);   // TODAS sin seleccion, en coords del bitmap
                    }
                    kbCacheW = region.Width; kbCacheH = region.Height; kbCacheAccent = accentArgb; kbCacheKh = kh; kbCacheOrigin = region.Location;
                }
                g.DrawImageUnscaled(kbCache, kbCacheOrigin.X, kbCacheOrigin.Y);
                // Tecla seleccionada EN VIVO encima: su relleno es opaco y tapa la version sin seleccion del cache.
                // Con tarjeta grafica NO se dibuja aqui: sale como PIEZA VIVA aparte (ver PiezaViva).
                if (!paraGpu && SelRow >= 0 && SelRow < rows.Count && SelCol >= 0 && SelCol < rows[SelRow].Count)
                    DrawOneKey(g, SelRow, SelCol, true, 0, 0);
            }

            // Dibuja UNA tecla. dx/dy desplaza el rect (para el cache: coords relativas al bitmap). Se usa
            // Offset directo -en vez de TranslateTransform del Graphics- porque TextRenderer (GDI) IGNORA la
            // transformacion y el texto caeria fuera del cache.
            private void DrawOneKey(Graphics g, int r, int c, bool sel, int dx, int dy)
            {
                SearchKey k = rows[r][c];
                Rectangle kr = Rectangle.Round(k.R); kr.Offset(dx, dy);
                if (kr.Width < 2 || kr.Height < 2) return;
                double kp = 0.5 + 0.5 * Math.Sin(Phase * 2.2 - (r * 0.55 + c * 0.32));
                using (GraphicsPath gp = RoundedPath(kr, 10))
                {
                    Color top = sel ? Lighten(Accent, 0.32) : Lighten(Shade(Accent, 0.34), 0.10 + 0.14 * kp);
                    Color bot = sel ? Accent : Shade(Accent, 0.55);
                    using (LinearGradientBrush b = new LinearGradientBrush(kr, top, bot, LinearGradientMode.Vertical)) g.FillPath(b, gp);
                    if (sel)
                    {
                        int a = 130 + (int)((0.5 + 0.5 * Math.Sin(Phase * 2.6)) * 120);
                        pnS.Color = Color.FromArgb(a, 170, 215, 255); pnS.Width = 2.8f; g.DrawPath(pnS, gp);
                    }
                    else
                    {
                        int a = 85 + (int)(kp * 130);
                        pnS.Color = Color.FromArgb(a, 150, 200, 255); pnS.Width = 1.7f; g.DrawPath(pnS, gp);
                    }
                }
                Font use = (k.Kind == KKind.Char) ? fChar : fSp;
                // EN LA TECLA DE BORRAR, EL BOTON ROJO AL LADO. El rojo borra una letra sin tener que ir
                // hasta esta tecla, pero eso no lo sabe nadie: es un atajo invisible. Dibujando el boton
                // DENTRO de la tecla que hace lo mismo, el cliente lo entiende sin que nadie se lo diga, y
                // de paso deja de pasearse por el teclado para borrar una letra mal puesta.
                // El boton va DEBAJO de la palabra, no al lado: "BORRAR" ya llena la tecla de lado a lado, y
                // la tecla es alta de sobra. Asi el boton sale grande -que es lo que hay que ver desde la
                // silla- sin apretujar nada.
                if (k.Kind == KKind.Back && kr.Width > 70 && kr.Height > 56)
                {
                    int d = kr.Height / 4; if (d > 34) d = 34;
                    TextRenderer.DrawText(g, k.Label, use, new Rectangle(kr.X, kr.Y, kr.Width, kr.Height - d - 6),
                                          Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
                    CtrlDot(g, kr.X + (kr.Width - d) / 2f, kr.Bottom - 8 - d / 2, d, Color.FromArgb(228, 72, 72));
                    return;
                }
                TextRenderer.DrawText(g, k.Label, use, kr, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
            }

            private void DrawResults(Graphics g, Rectangle region)
            {
                resultRects.Clear();
                EnsurePaintRes();
                int top = region.Y + 30;
                int areaH = region.Bottom - top;
                int n = 0, cardH = 38;
                if (areaH < 28) { resCols = 1; resRowsPerCol = 1; }
                else
                {
                    int gapY = 5, gapX = 8, colMinW = 185;
                    int cols = (region.Width + gapX) / (colMinW + gapX);
                    if (cols < 1) cols = 1; if (cols > 2) cols = 2;            // hasta 2 columnas en este panel
                    int colW = (region.Width - (cols - 1) * gapX) / cols;
                    int rowsPerCol = (areaH + gapY) / (cardH + gapY);
                    if (rowsPerCol < 1) rowsPerCol = 1;
                    resCols = cols; resRowsPerCol = rowsPerCol;
                    int capacity = cols * rowsPerCol;
                    n = (Results != null) ? Math.Min(Results.Count, capacity) : 0;
                    if (FocusResults && n > 0) { if (SelResult < 0) SelResult = 0; if (SelResult >= n) SelResult = n - 1; }
                    for (int i = 0; i < n; i++)   // solo geometria (barato): rects absolutos para el raton y para pintar
                    {
                        int col = i / rowsPerCol, row = i % rowsPerCol;   // llena hacia ABAJO y luego a la siguiente columna
                        int rx = region.X + col * (colW + gapX), ry = top + row * (cardH + gapY);
                        resultRects.Add(new KeyValuePair<RectangleF, int>(new Rectangle(rx, ry, colW, cardH), i));
                    }
                }
                // CACHE: cabecera + tarjetas SIN seleccion. Se rehace solo al cambiar la consulta/region/color;
                // moverse por los resultados NO lo toca (solo copia el cache + la tarjeta seleccionada en vivo).
                int accentArgb = Accent.ToArgb();
                string qNorm = Normalize(Query ?? "");   // UNA vez por dibujado, no una por tarjeta
                if (resCache == null || resCacheW != region.Width || resCacheH != region.Height || resCacheAccent != accentArgb || resCacheQuery != Query || resCacheDatos != DatosVer)
                {
                    int rw = Math.Max(1, region.Width), rh = Math.Max(1, region.Height);
                    if (resCache == null || resCache.Width != rw || resCache.Height != rh)   // REUSA el bitmap si el tamano no cambio
                    {
                        if (resCache != null) resCache.Dispose();   // solo se reasigna al cambiar de tamano, no en cada tecla (menos basura/tirones)
                        resCache = new Bitmap(rw, rh, PixelFormat.Format32bppPArgb);
                    }
                    using (Graphics cg = Graphics.FromImage(resCache))
                    {
                        cg.Clear(Color.Transparent);
                        cg.SmoothingMode = SmoothingMode.AntiAlias;
                        TextRenderer.DrawText(cg, "Resultados", fHead, new Rectangle(0, 0, region.Width, 24), Color.White, TextFormatFlags.Left);
                        if (n == 0)
                            TextRenderer.DrawText(cg, (Query.Length == 0) ? "Escribe para buscar..." : "Sin resultados", fEmpty, new Rectangle(0, 30, region.Width, 28), Color.FromArgb(190, 200, 225), TextFormatFlags.Left);
                        else
                            for (int i = 0; i < n; i++)
                            {
                                Rectangle rr = Rectangle.Round(resultRects[i].Key); rr.Offset(-region.X, -region.Y);
                                DrawOneResultCard(cg, i, rr, false, qNorm);
                            }
                    }
                    resCacheW = region.Width; resCacheH = region.Height; resCacheAccent = accentArgb; resCacheQuery = Query; resCacheOrigin = region.Location; resCacheDatos = DatosVer;
                }
                g.DrawImageUnscaled(resCache, resCacheOrigin.X, resCacheOrigin.Y);
                // Tarjeta seleccionada EN VIVO encima: su relleno es opaco y tapa la version sin seleccion del cache.
                if (n > 0)
                {
                    int selIdx = FocusResults ? SelResult : 0;
                    if (selIdx >= 0 && selIdx < n) DrawOneResultCard(g, selIdx, Rectangle.Round(resultRects[selIdx].Key), true, qNorm);
                }
            }

            // Dibuja UNA tarjeta de resultado en rr (ya en las coords donde toca: absolutas en vivo, relativas en el cache).
            // 'qn' es la consulta ya limpia de tildes. Antes se limpiaba DENTRO, o sea CUARENTA veces por cada
            // tecla que pulsaba el cliente, para obtener siempre lo mismo. Ahora se limpia una vez y se pasa.
            private void DrawOneResultCard(Graphics g, int i, Rectangle rr, bool sel, string qn)
            {
                if (Results == null || i < 0 || i >= Results.Count) return;
                EnsureHornoTarjeta(rr.Width, rr.Height);
                g.DrawImageUnscaled(sel ? bmpTarjSel : bmpTarj, rr.X - MargenTarj, rr.Y - MargenTarj);
                SearchItem it = Results[i];
                string tag = (it.Kind == 0) ? "ARTISTA" : (it.Kind == 1) ? "ALBUM" : "CANCION";
                Color tagc = (it.Kind == 0) ? Color.FromArgb(150, 215, 255) : (it.Kind == 1) ? Color.FromArgb(255, 210, 120) : Color.FromArgb(170, 245, 170);

                // ---- RENGLON DE ARRIBA: que es, de que disco, y de que genero ----
                // La pastilla del genero va pegada a la derecha; lo que quede es para el tipo y el disco.
                int xIz = rr.X + 9, derLim = rr.Right - 9;
                string gen = (GetGenero != null) ? GetGenero(it) : "";
                if (gen != null && gen.Length > 0)
                {
                    Bitmap pg = HorneaGeneroRes(g, gen);
                    int gw = pg.Width - 2 * MargenTarj, gh = pg.Height - 2 * MargenTarj;
                    int gx = derLim - gw;
                    if (gx > xIz + 40)
                    {
                        g.DrawImageUnscaled(pg, gx - MargenTarj, rr.Y + 3 - MargenTarj);   // el fondo, ya hecho
                        TextRenderer.DrawText(g, gen, fResSub, new Rectangle(gx, rr.Y + 3, gw, gh), Lighten(ColorDeEtiqueta(gen), 0.45),
                                              TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding);
                        derLim = gx - 8;
                    }
                }
                // El rotulo se MIDE una vez (los tres posibles miden siempre lo mismo) pero se DIBUJA aqui:
                // el texto no se puede hornear aparte, porque el sistema lo mezcla con el color que tiene
                // debajo y una letra dibujada sobre transparente y luego pegada sale mas fina.
                int tw = AnchoRotulo(g, it.Kind, tag);
                TextRenderer.DrawText(g, tag, fResSub, new Rectangle(xIz, rr.Y + 4, Math.Max(10, derLim - xIz), 13), tagc,
                                      TextFormatFlags.Left | TextFormatFlags.NoPadding);
                string disco = (GetDisco != null) ? GetDisco(it) : "";
                if (disco != null && disco.Length > 0)
                {
                    int dx = xIz + tw + 8;
                    if (derLim - dx > 24)
                        TextRenderer.DrawText(g, "\u00b7  " + disco, fResSub, new Rectangle(dx, rr.Y + 4, derLim - dx, 13),
                                              Color.FromArgb(138, 150, 182),
                                              TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPadding);
                }

                // ---- RENGLON PRINCIPAL: el nombre, con LO TECLEADO encendido ----
                Rectangle tr = new Rectangle(rr.X + 9, rr.Y + 16, rr.Width - 16, rr.Height - 18);
                int mIni, mLar;
                if (qn != null && qn.Length > 0 && BuscaTramo(it.Display, qn, out mIni, out mLar))
                {
                    // Se mide con NoPadding y se dibuja con NoPadding: si no, medir y pintar no coinciden y el
                    // resaltado sale corrido.
                    const TextFormatFlags FL = TextFormatFlags.Left | TextFormatFlags.NoPadding | TextFormatFlags.NoClipping;
                    string ante = it.Display.Substring(0, mIni), coincide = it.Display.Substring(mIni, mLar);
                    int wa = TextRenderer.MeasureText(g, ante, fRes, new Size(9999, 99), TextFormatFlags.NoPadding).Width;
                    int wc = TextRenderer.MeasureText(g, coincide, fRes, new Size(9999, 99), TextFormatFlags.NoPadding).Width;
                    if (wa + wc <= tr.Width)   // si el tramo no se ve entero, mejor no resaltar nada
                    {
                        if (marcaB == null) marcaB = new SolidBrush(Color.Black);
                        marcaB.Color = Color.FromArgb(70, 255, 205, 90);
                        // El resaltado se ajusta al ALTO DE LA LETRA, no al de la caja: la caja es mas alta que
                        // el texto y la marca quedaba colgando por debajo.
                        if (altoLetra < 0) altoLetra = TextRenderer.MeasureText(g, "Xg", fRes, new Size(9999, 99), TextFormatFlags.NoPadding).Height;
                        int hTxt = altoLetra;
                        using (GraphicsPath gp = RoundedPath(new Rectangle(tr.X + wa - 2, tr.Y - 1, wc + 4, hTxt + 2), 4))
                            g.FillPath(marcaB, gp);
                        TextRenderer.DrawText(g, ante, fRes, new Rectangle(tr.X, tr.Y, tr.Width, tr.Height), Color.White, FL);
                        TextRenderer.DrawText(g, coincide, fRes, new Rectangle(tr.X + wa, tr.Y, tr.Width - wa, tr.Height), Color.FromArgb(255, 214, 120), FL);
                        TextRenderer.DrawText(g, it.Display.Substring(mIni + mLar), fRes,
                                              new Rectangle(tr.X + wa + wc, tr.Y, Math.Max(4, tr.Width - wa - wc), tr.Height),
                                              Color.White, TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPadding);
                        return;
                    }
                }
                TextRenderer.DrawText(g, it.Display, fRes, tr, Color.White, TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
            }

            // Cachea las caratulas (ya redimensionadas) de todos los discos del artista
            // Reconstruye SIEMPRE: pide las portadas vigentes a la cache (nunca guarda una
            // referencia que pudiera liberarse despues -> evita dibujar imagenes muertas).
            private List<Image> EnsureArtistCovers(SearchItem it)
            {
                artistCovers.Clear();
                if (it.Albums != null)
                    for (int i = 0; i < it.Albums.Count; i++)
                    {
                        Image im = Portada(it.Albums[i]);
                        if (im != null) artistCovers.Add(im);
                    }
                return artistCovers;
            }

            // Mezcla a->b con factor f (0..1) en un bitmap reutilizable
            private Image BlendInto(Image a, Image b, float f)
            {
                if (blendBmp == null) blendBmp = new Bitmap(320, 320, PixelFormat.Format32bppPArgb);
                using (Graphics g = Graphics.FromImage(blendBmp))
                {
                    g.Clear(Color.Black);
                    g.InterpolationMode = InterpolationMode.Bilinear;
                    Rectangle dst = new Rectangle(0, 0, blendBmp.Width, blendBmp.Height);
                    if (a != null) g.DrawImage(a, dst);
                    if (b != null && f > 0f)
                    {
                        ColorMatrix cm = new ColorMatrix();
                        cm.Matrix33 = f;
                        using (ImageAttributes ia = new ImageAttributes())
                        {
                            ia.SetColorMatrix(cm, ColorMatrixFlag.Default, ColorAdjustType.Bitmap);
                            g.DrawImage(b, dst, 0, 0, b.Width, b.Height, GraphicsUnit.Pixel, ia);
                        }
                    }
                }
                return blendBmp;
            }

            // Calcula la(s) portada(s) y la celda del cubo de vista previa (sin dibujarlo). ca/cb/f = par a
            // fundir (discos TOP/artista con varias portadas). Devuelve false si no hay nada que mostrar.
            // BARRER RESULTADOS NO ENCARGA CARATULAS. Antes, cada resultado por el que el cliente pasaba de
            // largo con la flecha encargaba SU caratula al disco: recorrer cuarenta resultados dejaba cuarenta
            // imagenes grandes por descifrar, todas ellas de resultados que ya no estaba mirando. En el
            // ordenador del bar, que tiene un solo nucleo, ese trabajo de fondo es justo lo que se siente como
            // tirones AL MOVERSE. Mientras se mueve solo se usa lo que ya esta en memoria; en cuanto se para
            // en un resultado (dos decimas), se encarga la suya.
            private int selMomento = Environment.TickCount;
            private int selAnterior = -1;
            private const int EsperaPortadaMs = 200;
            public Func<Album, Image> GetCoverYa;   // SOLO lo que ya esta en memoria; no encarga nada al disco
            private Image Portada(Album a)
            {
                if (a == null) return null;
                bool parado = (Environment.TickCount - selMomento) >= EsperaPortadaMs;
                if (parado || GetCoverYa == null) return (GetCover != null) ? GetCover(a) : null;
                return GetCoverYa(a);
            }

            private bool ComputePreview(Rectangle region, out Image ca, out Image cb, out float f, out Rectangle area)
            {
                ca = null; cb = null; f = 0f; area = Rectangle.Empty;
                int n = (Results != null) ? Results.Count : 0;
                if (SelResult != selAnterior) { selAnterior = SelResult; selMomento = Environment.TickCount; }
                if (n == 0 || SelResult < 0 || SelResult >= n) { cubeRect = Rectangle.Empty; return false; }
                SearchItem it = Results[SelResult];
                if (it.Kind == 0)
                {
                    List<Image> cov = EnsureArtistCovers(it);
                    if (cov.Count == 0) ca = Portada(it.AlbumRef);
                    else if (cov.Count == 1) ca = cov[0];
                    else
                    {
                        double cyc = 3.8, hold = 2.6;   // ~3.2s por caratula, funde ~1s
                        int m = cov.Count;
                        double total = cyc * m;
                        double pos = Phase - Math.Floor(Phase / total) * total;
                        int idx = (int)(pos / cyc) % m;
                        double within = pos - idx * cyc;
                        float ff = 0f;
                        if (within > hold) ff = (float)((within - hold) / (cyc - hold));
                        if (ff < 0f) ff = 0f; else if (ff > 1f) ff = 1f;
                        ca = cov[idx]; cb = cov[(idx + 1) % m]; f = ff;
                    }
                }
                else ca = Portada(it.AlbumRef);

                int side = (int)(Math.Min(region.Width, region.Height) * 0.62);
                if (side < 40) side = 40;
                int cx = region.X + region.Width / 2;
                int top = region.Y + (region.Height - side) / 2 - 24;
                if (top < region.Y + 6) top = region.Y + 6;
                area = new Rectangle(cx - side / 2, top, side, side);
                cubeRect = area;
                return true;
            }

            // CPU: dibuja el cubo de vista previa (girando) + su texto.
            private void DrawPreviewCube(Graphics g, Rectangle region)
            {
                Image ca, cb; float f; Rectangle area;
                if (!ComputePreview(region, out ca, out cb, out f, out area)) return;
                Image cover = (cb == null || f <= 0.002f) ? ca : BlendInto(ca, cb, f);
                g.InterpolationMode = InterpolationMode.Bilinear;
                Cube.Draw(g, area, cover, CubeAngle);
                DrawPreviewInfo(g, region, area);
            }

            // Texto de la vista previa (titulo, subtitulo y ayuda) debajo del cubo. Comun a CPU y GPU.
            private void DrawPreviewInfo(Graphics g, Rectangle region, Rectangle area)
            {
                int n = (Results != null) ? Results.Count : 0;
                if (SelResult < 0 || SelResult >= n) return;
                SearchItem it = Results[SelResult];
                string title, sub;
                if (it.Kind == 1) { title = (it.AlbumRef != null) ? it.AlbumRef.Name : it.Display; sub = (it.AlbumRef != null) ? it.AlbumRef.Artist : ""; }
                else if (it.Kind == 2 && it.TrackRef != null) { title = it.TrackRef.Title; sub = it.TrackRef.Artist + ((it.AlbumRef != null) ? "   -   " + it.AlbumRef.Name : ""); }
                else { title = it.Display; int dc = (it.Albums != null) ? it.Albums.Count : 0; sub = dc + (dc == 1 ? " disco" : " discos"); }

                int ty = area.Bottom + 12;
                EnsurePaintRes();
                TextRenderer.DrawText(g, title, fPrevT, new Rectangle(region.X, ty, region.Width, 28), Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.EndEllipsis);
                TextRenderer.DrawText(g, sub, fPrevS, new Rectangle(region.X, ty + 30, region.Width, 24), Color.FromArgb(215, 225, 245), TextFormatFlags.HorizontalCenter | TextFormatFlags.EndEllipsis);
                // Ayuda con ICONOS (mismo estilo que la barra de arriba), centrada.
                {
                    Font hf = fPrevH;
                    SmoothingMode oldsm = g.SmoothingMode; g.SmoothingMode = SmoothingMode.AntiAlias;
                    System.Drawing.Text.TextRenderingHint oldth = g.TextRenderingHint;
                    g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                    Color htx = Color.FromArgb(205, 214, 238);
                    Color yellow = Color.FromArgb(242, 206, 72), green = Color.FromArgb(72, 212, 112);
                    int hcy = region.Bottom - 14;
                    int dd = 15; float gap = 7, grp = 26;
                    string t1 = "volver al teclado", t2 = "elegir";
                    SizeF s1 = g.MeasureString(t1, hf), s2 = g.MeasureString(t2, hf);
                    float total = dd + gap + s1.Width + grp + dd + gap + s2.Width;
                    float hx = region.X + (region.Width - total) / 2f;
                    hx = CtrlDirLeft(g, hx, hcy, dd, yellow) + gap;   // boton IZQUIERDA
                    hx = CtrlTxt(g, hf, t1, hx, hcy, htx) + grp;
                    hx = CtrlDot(g, hx, hcy, dd, green) + gap;         // boton PONER (verde)
                    hx = CtrlTxt(g, hf, t2, hx, hcy, htx);
                    g.SmoothingMode = oldsm; g.TextRenderingHint = oldth;
                }
            }
        }

        private class SearchItem
        {
            public int Kind;     // 0=artista, 1=album, 2=cancion
            public string Display;
            public string Key;
            public int Mask;    // que letras contiene Key (ver MarcaLetras)
            public int Score;
            public Album AlbumRef;
            public Track TrackRef;
            public List<Album> Albums;   // todos los discos del artista (Kind==0)
        }

        private class Album
        {
            public string Folder;
            public string Name;
            public string Artist;
            public char Letter;
            public string CoverPath;
            public List<Track> Tracks = new List<Track>();
            public List<string> VideoFiles = new List<string>();
            public bool IsTop = false;             // disco virtual de "lo mas sonado" por genero
            public bool TopIsVideo = false;        // (TOP) este disco virtual contiene VIDEOS, no canciones
            public string KeyCache, KeyFrom;       // clave de la casilla ya armada (ver CellKey): se pide en cada cuadro
            public string KeyQ, KeyQDe;            // y su variante con el palomito (ver ClaveCasilla), tambien armada una vez
            public List<string> CycleCovers;       // (TOP) caratulas distintas para ciclar en el cubo seleccionado
            public List<string> TrackCovers;       // (TOP) caratula de origen por cada cancion (alineado con Tracks)
            public List<string> TrackInfo;         // (TOP) "Artista - Album" de origen por cada cancion
            public List<Album> TrackAlbums;        // (TOP) disco de origen por cada cancion (para "sonando")
        }

        // ==========  ETIQUETAS (ID3)  ==========
        private class Track
        {
            public string Path;
            public string Artist;
            public string Title;
            public string Album;
            public string Genre;

            // En la lista del disco se muestra EXACTAMENTE el nombre del archivo (sin extension), tal
            // cual esta en la carpeta: cero adivinanzas. Title/Artist se siguen usando por dentro para
            // "Sonando:", el color por genero y el buscador.
            public override string ToString()
            {
                try { return System.IO.Path.GetFileNameWithoutExtension(Path); }
                catch { return Title; }
            }

            private static readonly string[] Id3v1Genres = {
                "Blues","Classic Rock","Country","Dance","Disco","Funk","Grunge","Hip-Hop","Jazz","Metal",
                "New Age","Oldies","Other","Pop","R&B","Rap","Reggae","Rock","Techno","Industrial",
                "Alternative","Ska","Death Metal","Pranks","Soundtrack","Euro-Techno","Ambient","Trip-Hop","Vocal","Jazz+Funk",
                "Fusion","Trance","Classical","Instrumental","Acid","House","Game","Sound Clip","Gospel","Noise",
                "AlternRock","Bass","Soul","Punk","Space","Meditative","Instrumental Pop","Instrumental Rock","Ethnic","Gothic",
                "Darkwave","Techno-Industrial","Electronic","Pop-Folk","Eurodance","Dream","Southern Rock","Comedy","Cult","Gangsta",
                "Top 40","Christian Rap","Pop/Funk","Jungle","Native American","Cabaret","New Wave","Psychadelic","Rave","Showtunes",
                "Trailer","Lo-Fi","Tribal","Acid Punk","Acid Jazz","Polka","Retro","Musical","Rock & Roll","Hard Rock"
            };

            private static string NormalizeGenre(string raw)
            {
                if (string.IsNullOrEmpty(raw)) return "";
                raw = raw.Trim();
                if (raw.Length > 0 && raw[0] == '(')
                {
                    int close = raw.IndexOf(')');
                    if (close > 1)
                    {
                        string num = raw.Substring(1, close - 1);
                        int n;
                        if (int.TryParse(num, out n) && n >= 0 && n < Id3v1Genres.Length)
                        {
                            string rest = raw.Substring(close + 1).Trim();
                            if (rest.Length > 0) return rest;
                            return Id3v1Genres[n];
                        }
                    }
                }
                int num2;
                if (int.TryParse(raw, out num2) && num2 >= 0 && num2 < Id3v1Genres.Length) return Id3v1Genres[num2];
                return raw;
            }

            // RAPIDO: no abre el archivo. Titulo/artista salen del nombre y la carpeta.
            // (Con +100k canciones, abrir cada MP3 para leer ID3 era lo que tardaba.)
            public static Track FromFile(string path)
            {
                Track t = new Track();
                t.Path = Pool(path); t.Artist = ""; t.Title = ""; t.Album = ""; t.Genre = "";
                string name = System.IO.Path.GetFileNameWithoutExtension(path);
                string fa, ft;
                bool split = SplitArtist(name, out fa, out ft);
                if (split && AllDigits(fa))
                {
                    // "01 - X - Y": quitar el numero de pista y reanalizar -> artista X, titulo Y.
                    string fa2, ft2;
                    if (SplitArtist(ft, out fa2, out ft2) && !AllDigits(fa2)) { t.Artist = fa2; t.Title = ft2; }
                    else t.Title = name;   // "01 - Titulo": igual que siempre
                }
                else if (split) { t.Artist = fa; t.Title = ft; }
                else { t.Title = name; }
                if (string.IsNullOrEmpty(t.Artist))
                {
                    string d = System.IO.Path.GetDirectoryName(path);
                    string leaf = (d != null) ? LeafName(d) : "Desconocido";
                    string da, dn;
                    if (SplitArtist(leaf, out da, out dn)) t.Artist = da; else t.Artist = leaf;
                }
                return t;
            }

            // EL GENERO A SOLAS, LEYENDO LO MENOS POSIBLE.
            //
            // La etiqueta de texto de un MP3 puede llevar la CARATULA dentro y medir megas. Leerla entera para
            // sacar UNA palabra es tirar el disco a la basura, y el paseo de fondo hacia eso con TODAS las
            // canciones de la biblioteca: con veinte mil archivos son gigas de lectura inutil.
            //
            // La etiqueta va por MARCOS, y cada marco dice de antemano cuanto mide. Aqui se leen solo las diez
            // letras de cabecera de cada marco y se SALTAN los que no interesan -la caratula, sobre todo- sin
            // llegar a leerlos. De un archivo con caratula de 300 KB se leen unos cientos de bytes. Si la
            // etiqueta larga no trae genero, se prueba la corta del final (128 bytes); y si tampoco, se queda
            // sin genero, que es decoracion, en vez de leerse el archivo entero.
            public static string SoloGenero(string path)
            {
                Track t = new Track();
                t.Path = path; t.Artist = ""; t.Title = ""; t.Album = ""; t.Genre = "";
                try
                {
                    if (System.IO.Path.GetExtension(path).ToLowerInvariant() != ".mp3") return "";
                    using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 4096))
                    {
                        byte[] cab = new byte[10];
                        if (fs.Read(cab, 0, 10) == 10 && cab[0] == (byte)'I' && cab[1] == (byte)'D' && cab[2] == (byte)'3'
                            && cab[3] >= 3)   // las etiquetas muy viejas (2.2) tienen otra forma: se cae a la corta
                        {
                            int major = cab[3];
                            long size = ((cab[6] & 0x7f) << 21) + ((cab[7] & 0x7f) << 14) + ((cab[8] & 0x7f) << 7) + (cab[9] & 0x7f);
                            long fin = 10 + size;
                            byte[] fh = new byte[10];
                            while (fs.Position + 10 <= fin)
                            {
                                if (fs.Read(fh, 0, 10) != 10) break;
                                if (fh[0] == 0) break;   // relleno: se acabaron los marcos
                                int fsz;
                                if (major >= 4) fsz = ((fh[4] & 0x7f) << 21) + ((fh[5] & 0x7f) << 14) + ((fh[6] & 0x7f) << 7) + (fh[7] & 0x7f);
                                else fsz = (fh[4] << 24) + (fh[5] << 16) + (fh[6] << 8) + fh[7];
                                if (fsz <= 0 || fs.Position + fsz > fin) break;
                                bool esGenero = (fh[0] == (byte)'T' && fh[1] == (byte)'C' && fh[2] == (byte)'O' && fh[3] == (byte)'N');
                                if (esGenero && fsz <= 4096)
                                {
                                    // Se le pasa el marco entero (cabecera incluida) al mismo lector de siempre,
                                    // asi el genero se interpreta exactamente igual que cuando se lee todo.
                                    byte[] uno = new byte[10 + fsz];
                                    Array.Copy(fh, 0, uno, 0, 10);
                                    int leidos = 0, r;
                                    while (leidos < fsz && (r = fs.Read(uno, 10 + leidos, fsz - leidos)) > 0) leidos += r;
                                    ParseId3v2(uno, 10 + leidos, major, t);
                                    if (!string.IsNullOrEmpty(t.Genre)) break;
                                }
                                else fs.Position += fsz;   // la caratula y lo demas: ni se tocan
                            }
                        }
                    }
                }
                catch { }
                if (string.IsNullOrEmpty(t.Genre)) { try { ReadId3v1(path, t); } catch { } }
                return t.Genre ?? "";
            }

            // Lee el ID3 bajo demanda (una sola vez), sobre todo para el GENERO (color de fondo).
            private bool tagsLoaded = false;
            public void EnsureTags()
            {
                if (tagsLoaded) return;
                tagsLoaded = true;
                try { if (System.IO.Path.GetExtension(Path).ToLowerInvariant() == ".mp3") ReadId3(Path, this); }
                catch { }
            }

            private static void ReadId3(string path, Track t)
            {
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read))
                {
                    byte[] header = new byte[10];
                    if (fs.Read(header, 0, 10) == 10 && header[0] == (byte)'I' && header[1] == (byte)'D' && header[2] == (byte)'3')
                    {
                        int major = header[3];
                        int size = ((header[6] & 0x7f) << 21) | ((header[7] & 0x7f) << 14) | ((header[8] & 0x7f) << 7) | (header[9] & 0x7f);
                        if (size > 0 && size <= 33554432)   // tope 32MB: un encabezado CORRUPTO puede declarar hasta 256MB y ese new byte[] tumbaria la RAM de la rocola; se cae al ID3v1
                        {
                            byte[] tag = new byte[size];
                            int read = 0, r;
                            while (read < size && (r = fs.Read(tag, read, size - read)) > 0) read += r;
                            ParseId3v2(tag, read, major, t);
                        }
                    }
                }
                if (string.IsNullOrEmpty(t.Title) || string.IsNullOrEmpty(t.Artist) || string.IsNullOrEmpty(t.Album) || string.IsNullOrEmpty(t.Genre)) ReadId3v1(path, t);
            }

            private static void ParseId3v2(byte[] tag, int len, int major, Track t)
            {
                int pos = 0;
                while (pos + 10 <= len)
                {
                    string id = Encoding.ASCII.GetString(tag, pos, 4);
                    if (id[0] == '\0') break;
                    bool valid = true;
                    for (int i = 0; i < 4; i++) { char c = id[i]; if (!((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))) { valid = false; break; } }
                    if (!valid) break;
                    int frameSize;
                    if (major >= 4) frameSize = ((tag[pos + 4] & 0x7f) << 21) | ((tag[pos + 5] & 0x7f) << 14) | ((tag[pos + 6] & 0x7f) << 7) | (tag[pos + 7] & 0x7f);
                    else frameSize = (tag[pos + 4] << 24) | (tag[pos + 5] << 16) | (tag[pos + 6] << 8) | tag[pos + 7];
                    int startPos = pos + 10;
                    if (frameSize <= 0 || startPos + frameSize > len) break;
                    if (id == "TIT2" || id == "TPE1" || id == "TALB" || id == "TCON")
                    {
                        string val = DecodeText(tag, startPos, frameSize);
                        if (val != null) val = val.Trim();
                        bool has = !string.IsNullOrEmpty(val);
                        // El ID3 MANDA sobre titulo/artista: el nombre de archivo es solo una adivinanza
                        // (en discos de varios artistas suele venir al reves, o sin titulo siquiera).
                        if (id == "TIT2" && has) t.Title = val;
                        else if (id == "TPE1" && has) t.Artist = val;
                        else if (id == "TALB" && has && string.IsNullOrEmpty(t.Album)) t.Album = val;
                        else if (id == "TCON" && has && string.IsNullOrEmpty(t.Genre)) t.Genre = NormalizeGenre(val);
                    }
                    pos = startPos + frameSize;
                }
            }

            private static string DecodeText(byte[] b, int start, int size)
            {
                if (size < 1) return "";
                byte enc = b[start];
                int s = start + 1, n = size - 1;
                string result;
                switch (enc)
                {
                    case 1:
                        if (n >= 2 && b[s] == 0xFF && b[s + 1] == 0xFE) result = Encoding.Unicode.GetString(b, s + 2, n - 2);
                        else if (n >= 2 && b[s] == 0xFE && b[s + 1] == 0xFF) result = Encoding.BigEndianUnicode.GetString(b, s + 2, n - 2);
                        else result = Encoding.Unicode.GetString(b, s, n);
                        break;
                    case 2: result = Encoding.BigEndianUnicode.GetString(b, s, n); break;
                    case 3: result = Encoding.UTF8.GetString(b, s, n); break;
                    default: result = Encoding.GetEncoding(28591).GetString(b, s, n); break;
                }
                int z = result.IndexOf('\0');
                if (z >= 0) result = result.Substring(0, z);
                return result.Trim();
            }

            private static void ReadId3v1(string path, Track t)
            {
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read))
                {
                    if (fs.Length < 128) return;
                    fs.Seek(-128, SeekOrigin.End);
                    byte[] b = new byte[128];
                    if (fs.Read(b, 0, 128) != 128) return;
                    if (!(b[0] == (byte)'T' && b[1] == (byte)'A' && b[2] == (byte)'G')) return;
                    Encoding latin = Encoding.GetEncoding(28591);
                    char[] tc = new char[] { '\0', ' ' };
                    string title = latin.GetString(b, 3, 30).Trim(tc);
                    string artist = latin.GetString(b, 33, 30).Trim(tc);
                    string album = latin.GetString(b, 63, 30).Trim(tc);
                    if (string.IsNullOrEmpty(t.Title) && title.Length > 0) t.Title = title;
                    if (string.IsNullOrEmpty(t.Artist) && artist.Length > 0) t.Artist = artist;
                    if (string.IsNullOrEmpty(t.Album) && album.Length > 0) t.Album = album;
                    int gi = b[127];
                    if (string.IsNullOrEmpty(t.Genre) && gi >= 0 && gi < Id3v1Genres.Length) t.Genre = Id3v1Genres[gi];
                }
            }
        }
    }
}